        public BOCTACHUI()
        {
            InitializeComponent();

            // LICENSE-ONLINE-20260811-01
            // Khóa bảng công cụ trước khi khởi tạo các chức năng CAD.
            // Publishable key là khóa công khai; khóa secret/service_role
            // tuyệt đối không được đặt trong DLL.
            if (!DesignerProperties.GetIsInDesignMode(this) &&
                !OnlineLicenseManager.EnsureActivated())
            {
                IsEnabled = false;
                Opacity = 0.55;
                ToolTip =
                    "Chưa kích hoạt bản quyền. Đóng và mở lại bảng công cụ " +
                    "để nhập key kích hoạt.";
                return;
            }

            KhoiTaoTatCaTabOng();
            KhoiTaoTatCaTabVan();
            KhoiTaoTatCaTabThietBi();

            // STEP21: chỉ kiểm tra trạng thái. Không bắt buộc phải có model ONNX.
            UpdateOnnxStatusUi();

            // STEP21C: chỉ đọc local cloud-state, không gọi Internet lúc mở Palette.
            UpdateAiCloudStatusUi();

            // STEP21D: Dataset cũng chỉ đọc local summary khi mở Palette.
            UpdateAiDatasetStatusUi();

            // STEP21F: chỉ đọc trạng thái export local, không chạy training.
            UpdateAiTrainingStatusUi();

            // STEP22A: Graph chỉ build khi user quét vùng / chạy AI.
            UpdateAiGraphStatusUi();

            // STEP22B: thử restore GNN model local; lỗi GNN không chặn các AI cũ.
            TryRestoreMepGraphGnnModel();
            UpdateAiGnnStatusUi();

            // STEP22B2: chỉ đọc trạng thái Graph Cloud local, không gọi Internet.
            UpdateAiGraphCloudStatusUi();
        }

