        private void EnsureLayerExists(
            Transaction tr,
            Database db,
            string layerName,
            bool isOngGio)
        {
            LayerTable lt =
                (LayerTable)tr.GetObject(
                    db.LayerTableId,
                    OpenMode.ForRead);

            if (!lt.Has(layerName))
            {
                lt.UpgradeOpen();

                LayerTableRecord ltr = new LayerTableRecord();
                ltr.Name = layerName;

                short colorIndex = GetExpectedAciColor(layerName);

                ltr.Color =
                    Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                        ColorMethod.ByAci,
                        colorIndex);

                lt.Add(ltr);
                tr.AddNewlyCreatedDBObject(ltr, true);

                if (isOngGio)
                {
                    ltr.Transparency =
                        new Autodesk.AutoCAD.Colors.Transparency(102);
                }
                else
                {
                    ltr.Transparency =
                        new Autodesk.AutoCAD.Colors.Transparency(255);
                }
            }
            else
            {
                LayerTableRecord ltr =
                    (LayerTableRecord)tr.GetObject(
                        lt[layerName],
                        OpenMode.ForWrite);

                if (!_userCustomColors.ContainsKey(layerName))
                {
                    ltr.Color =
                        Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                            ColorMethod.ByAci,
                            GetBrightAciColor(layerName));
                }
            }
        }

        private double TinhGocLech(
            Curve curve,
            Point3d closestPt,
            double txtRotation)
        {
            try
            {
                Vector3d deriv =
                    curve.GetFirstDerivative(
                        curve.GetParameterAtPoint(closestPt));

                double curveAngle =
                    deriv.AngleOnPlane(new Plane());

                double diff = Math.Abs(curveAngle - txtRotation);

                diff = diff % Math.PI;

                if (diff > Math.PI / 2.0)
                    diff = Math.PI - diff;

                return diff;
            }
            catch
            {
                // Không xác định được hướng → coi như không song song.
                return Math.PI / 2.0;
            }
        }

        /// <summary>
        /// Chữ kích thước chỉ được gán cho ống khi gần như song song
        /// với hướng ống (góc lệch ≤ MaxParallelAngleRadians).
        /// </summary>
        private bool IsTextParallelToCurve(
            Curve curve,
            Point3d closestPt,
            double txtRotation)
        {
            return TinhGocLech(curve, closestPt, txtRotation)
                <= MaxParallelAngleRadians;
        }

        private bool IsTouching(
            Curve c1,
            Curve c2,
            out Point3d touchPt)
        {
            touchPt = Point3d.Origin;

            Point3d[] pts1 = { c1.StartPoint, c1.EndPoint };
            Point3d[] pts2 = { c2.StartPoint, c2.EndPoint };

            foreach (var p1 in pts1)
            {
                foreach (var p2 in pts2)
                {
                    if (p1.DistanceTo(p2) < 1.0)
                    {
                        touchPt = p1;
                        return true;
                    }
                }
            }

            return false;
        }

        private bool IsCollinear(
            Curve c1,
            Curve c2,
            Point3d touchPt)
        {
            try
            {
                Vector3d v1 =
                    c1.GetFirstDerivative(
                        c1.GetParameterAtPoint(touchPt))
                        .GetNormal();

                Vector3d v2 =
                    c2.GetFirstDerivative(
                        c2.GetParameterAtPoint(touchPt))
                        .GetNormal();

                double angle = v1.GetAngleTo(v2);

                return angle < 0.1 ||
                       Math.Abs(angle - Math.PI) < 0.1;
            }
            catch
            {
                return false;
            }
        }

        private bool IsFireFightingPipeContext(PipeUiContext ctx)
        {
            return ctx != null &&
                (ReferenceEquals(ctx, _ctxFF) ||
                 string.IsNullOrWhiteSpace(ctx.Suffix));
        }

        private Vector3d GetAutomaticNetworkDirectionAway(
            Curve curve,
            bool atStart)
        {
            if (curve == null)
                return Vector3d.XAxis;

            try
            {
                double parameter =
                    atStart ? curve.StartParam : curve.EndParam;

                Vector3d derivative =
                    curve.GetFirstDerivative(parameter);

                Vector3d direction = atStart
                    ? derivative
                    : new Vector3d(
                        -derivative.X,
                        -derivative.Y,
                        -derivative.Z);

                direction = new Vector3d(
                    direction.X,
                    direction.Y,
                    0.0);

                if (direction.Length > 1e-6)
                    return direction.GetNormal();
            }
            catch
            {
            }

            try
            {
                Vector3d chord = atStart
                    ? curve.EndPoint - curve.StartPoint
                    : curve.StartPoint - curve.EndPoint;

                chord = new Vector3d(
                    chord.X,
                    chord.Y,
                    0.0);

                if (chord.Length > 1e-6)
                    return chord.GetNormal();
            }
            catch
            {
            }

            return Vector3d.XAxis;
        }

        private void AddAutomaticNetworkEnd(
            List<AutomaticPipeNetworkNode> nodes,
            SegmentData segment,
            Point3d point,
            bool atStart)
        {
            if (nodes == null || segment?.Curve == null)
                return;

            Point3d flatPoint =
                new Point3d(point.X, point.Y, 0.0);

            AutomaticPipeNetworkNode node =
                nodes.FirstOrDefault(
                    candidate =>
                        candidate.Point.DistanceTo(flatPoint) <=
                        AutomaticNetworkNodeTolerance);

            if (node == null)
            {
                node = new AutomaticPipeNetworkNode
                {
                    Point = flatPoint
                };

                nodes.Add(node);
            }

            node.Ends.Add(
                new AutomaticPipeNetworkEnd
                {
                    Segment = segment,
                    Point = flatPoint,
                    DirectionAway =
                        GetAutomaticNetworkDirectionAway(
                            segment.Curve,
                            atStart)
                });
        }

        private List<AutomaticPipeNetworkNode>
            BuildAutomaticPipeNetworkNodes(
                List<SegmentData> segments)
        {
            List<AutomaticPipeNetworkNode> nodes =
                new List<AutomaticPipeNetworkNode>();

            if (segments == null)
                return nodes;

            foreach (
                SegmentData segment
                in segments.Where(item => item?.Curve != null))
            {
                AddAutomaticNetworkEnd(
                    nodes,
                    segment,
                    segment.Curve.StartPoint,
                    true);

                AddAutomaticNetworkEnd(
                    nodes,
                    segment,
                    segment.Curve.EndPoint,
                    false);
            }

            return nodes;
        }

        private int PropagateAiPipeSizesWithinSameParentOnly(
            List<SegmentData> segments)
        {
            if (segments == null ||
                segments.Count == 0)
            {
                return 0;
            }

            int inherited =
                0;

            foreach (IGrouping<Curve, SegmentData> parentGroup
                in segments
                    .Where(
                        s =>
                            s?.OriginalParent != null)
                    .GroupBy(
                        s =>
                            s.OriginalParent))
            {
                List<SegmentData> explicitSegments =
                    parentGroup
                        .Where(
                            s =>
                                s.HasExplicitSize &&
                                !string.IsNullOrWhiteSpace(
                                    s.Layer))
                        .ToList();

                List<string> sizes =
                    explicitSegments
                        .Select(
                            s =>
                                s.Layer)
                        .Distinct(
                            StringComparer.OrdinalIgnoreCase)
                        .ToList();

                if (sizes.Count != 1)
                    continue;

                SegmentData source =
                    explicitSegments
                        .OrderBy(
                            s =>
                                s.BestScore)
                        .FirstOrDefault();

                if (source == null)
                    continue;

                foreach (SegmentData target
                    in parentGroup.Where(
                        s =>
                            string.IsNullOrWhiteSpace(
                                s.Layer)))
                {
                    target.Layer =
                        source.Layer;

                    target.Width =
                        FixedDnPipeDisplayWidth;

                    target.LabelText =
                        source.LabelText;

                    target.AiInferenceSource =
                        "SAME_PARENT_TOPOLOGY";

                    target.AiInferenceConfidence =
                        0.96;

                    inherited++;
                }
            }

            return inherited;
        }

        private int PropagateFirePipeSizesByTopology(
            List<SegmentData> segments)
        {
            if (segments == null || segments.Count == 0)
                return 0;

            int inheritedCount = 0;

            // Ưu tiên 1: một LINE/POLYLINE gốc chỉ có đúng một DN
            // được ghi rõ thì mọi đoạn bị cắt từ chính tuyến đó kế thừa DN.
            // Nếu trên cùng tuyến có nhiều DN, không đoán ở bước này.
            foreach (
                IGrouping<Curve, SegmentData> parentGroup
                in segments.GroupBy(item => item.OriginalParent))
            {
                List<SegmentData> explicitSegments =
                    parentGroup
                        .Where(
                            item =>
                                item.HasExplicitSize &&
                                !string.IsNullOrWhiteSpace(item.Layer))
                        .ToList();

                List<string> explicitLayers =
                    explicitSegments
                        .Select(item => item.Layer)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToList();

                if (explicitLayers.Count != 1)
                    continue;

                SegmentData source = explicitSegments[0];

                foreach (
                    SegmentData target
                    in parentGroup.Where(
                        item => string.IsNullOrWhiteSpace(item.Layer)))
                {
                    target.Layer = source.Layer;
                    target.Width = FixedDnPipeDisplayWidth;
                    target.LabelText = source.LabelText;

                    if (string.IsNullOrWhiteSpace(
                            target.AiInferenceSource))
                    {
                        target.AiInferenceSource =
                            "SAME_PARENT_TOPOLOGY";

                        target.AiInferenceConfidence =
                            0.94;
                    }

                    inheritedCount++;
                }
            }

            List<AutomaticPipeNetworkNode> nodes =
                BuildAutomaticPipeNetworkNodes(segments);

            Dictionary<SegmentData, List<AutomaticPipeNetworkNode>>
                nodesBySegment =
                    new Dictionary<
                        SegmentData,
                        List<AutomaticPipeNetworkNode>>();

            foreach (AutomaticPipeNetworkNode node in nodes)
            {
                foreach (
                    SegmentData segment
                    in node.Ends
                        .Select(end => end.Segment)
                        .Distinct())
                {
                    if (!nodesBySegment.TryGetValue(
                        segment,
                        out List<AutomaticPipeNetworkNode> segmentNodes))
                    {
                        segmentNodes =
                            new List<AutomaticPipeNetworkNode>();

                        nodesBySegment[segment] = segmentNodes;
                    }

                    segmentNodes.Add(node);
                }
            }

            bool changed;
            int guard = 0;

            do
            {
                changed = false;

                Dictionary<SegmentData, SegmentData> pending =
                    new Dictionary<SegmentData, SegmentData>();

                foreach (
                    SegmentData orphan
                    in segments.Where(
                        item => string.IsNullOrWhiteSpace(item.Layer)))
                {
                    List<SegmentData> donors =
                        new List<SegmentData>();

                    if (!nodesBySegment.TryGetValue(
                        orphan,
                        out List<AutomaticPipeNetworkNode> orphanNodes))
                    {
                        continue;
                    }

                    foreach (
                        AutomaticPipeNetworkNode node
                        in orphanNodes)
                    {
                        int incidentPipeCount =
                            node.Ends
                                .Select(end => end.Segment)
                                .Distinct()
                                .Count();

                        foreach (
                            AutomaticPipeNetworkEnd orphanEnd
                            in node.Ends.Where(
                                end => ReferenceEquals(
                                    end.Segment,
                                    orphan)))
                        {
                            List<AutomaticPipeNetworkEnd> otherEnds =
                                node.Ends
                                    .Where(
                                        end => !ReferenceEquals(
                                            end.Segment,
                                            orphan))
                                    .ToList();

                            if (incidentPipeCount <= 2)
                            {
                                donors.AddRange(
                                    otherEnds
                                        .Where(
                                            end =>
                                                !string.IsNullOrWhiteSpace(
                                                    end.Segment.Layer))
                                        .Select(end => end.Segment));

                                continue;
                            }

                            // Nút T/giao nhiều nhánh: chỉ cho truyền DN qua
                            // cặp gần thẳng nhất. Nhánh vuông góc không được
                            // đưa DN25/DN32 sang ống chính DN150 và ngược lại.
                            double maximumAngle = -1.0;

                            foreach (
                                AutomaticPipeNetworkEnd otherEnd
                                in otherEnds)
                            {
                                double angleDeg =
                                    orphanEnd.DirectionAway.GetAngleTo(
                                        otherEnd.DirectionAway) *
                                    180.0 / Math.PI;

                                if (angleDeg > maximumAngle)
                                    maximumAngle = angleDeg;
                            }

                            if (maximumAngle <
                                AutomaticStraightThroughAngleDeg)
                            {
                                continue;
                            }

                            donors.AddRange(
                                otherEnds
                                    .Where(
                                        end =>
                                        {
                                            double angleDeg =
                                                orphanEnd.DirectionAway
                                                    .GetAngleTo(
                                                        end.DirectionAway) *
                                                180.0 / Math.PI;

                                            return
                                                angleDeg >=
                                                    AutomaticStraightThroughAngleDeg &&
                                                Math.Abs(
                                                    maximumAngle -
                                                    angleDeg) <= 5.0 &&
                                                !string.IsNullOrWhiteSpace(
                                                    end.Segment.Layer);
                                        })
                                    .Select(end => end.Segment));
                        }
                    }

                    List<SegmentData> uniqueDonors =
                        donors.Distinct().ToList();

                    List<string> donorLayers =
                        uniqueDonors
                            .Select(item => item.Layer)
                            .Where(
                                layer =>
                                    !string.IsNullOrWhiteSpace(layer))
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .ToList();

                    // Hai đầu báo hai DN khác nhau là vị trí chuyển cỡ.
                    // Không tự đoán để tránh tô sai cả vòng ống.
                    if (donorLayers.Count != 1)
                        continue;

                    SegmentData donor =
                        uniqueDonors
                            .Where(
                                item => string.Equals(
                                    item.Layer,
                                    donorLayers[0],
                                    StringComparison.OrdinalIgnoreCase))
                            .OrderByDescending(
                                item => item.HasExplicitSize)
                            .ThenBy(item => item.BestScore)
                            .FirstOrDefault();

                    if (donor != null)
                        pending[orphan] = donor;
                }

                foreach (
                    KeyValuePair<SegmentData, SegmentData> pair
                    in pending)
                {
                    pair.Key.Layer = pair.Value.Layer;
                    pair.Key.Width = FixedDnPipeDisplayWidth;
                    pair.Key.LabelText = pair.Value.LabelText;

                    if (string.IsNullOrWhiteSpace(
                            pair.Key.AiInferenceSource))
                    {
                        pair.Key.AiInferenceSource =
                            "NETWORK_TOPOLOGY";

                        pair.Key.AiInferenceConfidence =
                            0.84;
                    }

                    inheritedCount++;
                    changed = true;
                }

                guard++;
            }
            while (changed && guard <= segments.Count + 1);

            // Tab Chữa cháy luôn hiển thị cùng một độ dày, DN chỉ còn
            // quyết định tên layer/màu chứ không làm nét DN150 dày hơn DN25.
            foreach (
                SegmentData segment
                in segments.Where(
                    item => !string.IsNullOrWhiteSpace(item.Layer)))
            {
                segment.Width = FixedDnPipeDisplayWidth;
            }

            return inheritedCount;
        }

        private void CapNhatVaSapXepDanhSachSize(
            PipeUiContext ctx,
            List<string> rawSizes,
            string itemToSelect = null)
        {
            if (ctx?.Sizes == null)
                return;

            var sortedSizes = rawSizes
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Select(x => x.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(s =>
                {
                    var matches =
                        Regex.Matches(s, @"\d+(\.\d+)?");

                    return matches.Count > 0
                        ? double.Parse(
                            matches[0].Value,
                            CultureInfo.InvariantCulture)
                        : 0;
                })
                .ThenBy(s =>
                {
                    var matches =
                        Regex.Matches(s, @"\d+(\.\d+)?");

                    return matches.Count > 1
                        ? double.Parse(
                            matches[1].Value,
                            CultureInfo.InvariantCulture)
                        : 0;
                })
                .ThenBy(s => s)
                .ToList();

            ctx.Sizes.Clear();

            string prefix = GetLayerPrefix(ctx);

            foreach (var s in sortedSizes)
            {
                string layerName = $"{prefix}_{s}";
                short aci = GetExpectedAciColor(layerName);

                ctx.Sizes.Add(
                    new PipeSizeItem
                    {
                        SizeName = s,
                        AciColor = aci,
                        LayerColorBrush = GetBrushFromAci(aci)
                    });
            }

            if (ctx.LstSize == null)
                return;

            if (itemToSelect != null)
            {
                var target =
                    ctx.Sizes.FirstOrDefault(
                        x => x.SizeName.Equals(
                            itemToSelect,
                            StringComparison.OrdinalIgnoreCase));

                if (target != null)
                {
                    ctx.LstSize.SelectedItem = target;
                    ctx.LstSize.ScrollIntoView(target);
                }
            }
            else if (ctx.Sizes.Count > 0)
            {
                ctx.LstSize.SelectedIndex = 0;
            }
        }

        private bool LaOngGio(string material)
        {
            string m =
                (material ?? "").Trim().ToUpperInvariant();

            return m.Contains("ỐNG GIÓ") ||
                   m.Contains("ONG GIO") ||
                   m.StartsWith("OG ") ||
                   m.StartsWith("OG_") ||
                   m == "OG" ||
                   m.Contains("OG THẢI") ||
                   m.Contains("OG THAI") ||
                   m.Contains("OG HÚT") ||
                   m.Contains("OG HUT") ||
                   m.Contains("OG LẠNH") ||
                   m.Contains("OG LANH") ||
                   m.Contains("OG CẤP") ||
                   m.Contains("OG CAP") ||
                   m.Contains("OG HỒI") ||
                   m.Contains("OG HOI") ||
                   m.Contains("SEAF") ||
                   m.Contains("FAF") ||
                   m.Contains("EAF") ||
                   m.Contains("PAF") ||
                   m.Contains("BEP");
        }

        private bool LaOngGioHutKhoi(string material)
        {
            string m =
                (material ?? "").Trim().ToUpperInvariant();

            return m.Contains("HÚT KHÓI") ||
                   m.Contains("HUT KHOI") ||
                   m.Contains("HÚT KHÓI") ||
                   m.Contains("SMOKE");
        }

        private bool LaOngDong(string material)
        {
            string m =
                (material ?? "").Trim().ToUpperInvariant();

            return m == "ỐNG ĐỒNG" ||
                   m == "ĐỒNG" ||
                   m.Contains("ỐNG ĐỒNG") ||
                   m.EndsWith("_ CU") ||
                   m.Contains(" _ CU");
        }

        private void CapNhatSizeTheoVatLieu(PipeUiContext ctx)
        {
            if (ctx == null)
                return;

            string material = GetSelectedPipeMaterialName(ctx);
            List<string> newSizes = new List<string>();

            bool isOngGioSize = LaOngGio(material);

            if (ctx.Suffix == "ACMV")
            {
                var chkGio =
                    FindName("ChkNhomOngGioACMV") as System.Windows.Controls.CheckBox;
                if (chkGio != null)
                    isOngGioSize = chkGio.IsChecked == true;
            }

            if (isOngGioSize)
            {
                newSizes.AddRange(
                    new[]
                    {
                        "100x100",
                        "200x100",
                        "500x200",
                        "800x300",
                        "800x350"
                    });
            }
            else if (LaOngDong(material))
            {
                newSizes.AddRange(
                    new[]
                    {
                        "6.4 - 9.5", "6.4 - 12.7",
                        "6.4 - 15.9", "9.5 - 12.7",
                        "9.5 - 15.9", "9.5 - 19.1",
                        "9.5 - 22.2", "12.7 - 19.1",
                        "12.7 - 22.2", "12.7 - 25.4",
                        "12.7 - 28.6", "15.9 - 28.6",
                        "15.9 - 31.8", "15.9 - 34.9",
                        "15.9 - 38.1"
                    });
            }
            else
            {
                newSizes.AddRange(
                    new[]
                    {
                        "DN15", "DN20", "DN25",
                        "DN32", "DN40", "DN50",
                        "DN65", "DN80", "DN100",
                        "DN125", "DN150", "DN200",
                        "DN250", "DN300", "DN350",
                        "DN400"
                    });
            }

            CapNhatVaSapXepDanhSachSize(ctx, newSizes);
            CapNhatHienThiPanelOngGioACMV(ctx);
            CapNhatDanhSachCnEiOngGio(ctx);
        }

        private void CapNhatHienThiPanelOngGioACMV(PipeUiContext ctx)
        {
            if (ctx == null || ctx.Suffix != "ACMV")
                return;

            var panelThuong =
                FindName("PanelSizeOngThuongACMV") as System.Windows.UIElement;
            var panelGio =
                FindName("PanelSizeOngGioACMV") as System.Windows.UIElement;

            // Nếu thiếu panel ống gió trong XAML → vẫn cho vẽ bằng list size thường
            if (panelThuong == null && panelGio == null)
                return;

            string material = GetSelectedPipeMaterialName(ctx);
            bool isOngGio = LaOngGio(material);

            // Ưu tiên theo ô tích nhóm Ống gió (ACMV)
            if (ctx.Suffix == "ACMV")
            {
                var chkGio =
                    FindName("ChkNhomOngGioACMV") as System.Windows.Controls.CheckBox;
                if (chkGio != null)
                    isOngGio = chkGio.IsChecked == true;
            }

            if (panelThuong != null)
            {
                // Không có panel gió riêng → luôn hiện panel thường (chứa size WxH)
                if (panelGio == null)
                    panelThuong.Visibility = System.Windows.Visibility.Visible;
                else
                    panelThuong.Visibility = isOngGio
                        ? System.Windows.Visibility.Collapsed
                        : System.Windows.Visibility.Visible;
            }

            if (panelGio != null)
            {
                panelGio.Visibility = isOngGio
                    ? System.Windows.Visibility.Visible
                    : System.Windows.Visibility.Collapsed;
            }

            // Đồng bộ list size ống gió từ ctx.Sizes (có màu Layer)
            if (isOngGio)
            {
                try
                {
                    var lstGio = TimListBox("LstSizeOngGioACMV");
                    if (lstGio != null && ctx.Sizes != null)
                    {
                        string selectedName = null;
                        if (lstGio.SelectedItem is PipeSizeItem selItem)
                            selectedName = selItem.SizeName;
                        else
                            selectedName = LayNoiDungItem(lstGio.SelectedItem);

                        // Chỉ gán ItemsSource — không Clear Items (tránh crash)
                        lstGio.ItemsSource = ctx.Sizes;

                        if (ctx.Sizes.Count > 0)
                        {
                            PipeSizeItem target = null;
                            if (!string.IsNullOrWhiteSpace(selectedName))
                            {
                                foreach (var s in ctx.Sizes)
                                {
                                    if (string.Equals(s.SizeName, selectedName,
                                        StringComparison.OrdinalIgnoreCase))
                                    {
                                        target = s;
                                        break;
                                    }
                                }
                            }
                            object want = target ?? ctx.Sizes[0];
                            if (!ReferenceEquals(lstGio.SelectedItem, want))
                                lstGio.SelectedItem = want;
                        }
                    }

                    CapNhatDanhSachCnEiOngGio(ctx);
                }
                catch (System.Exception ex)
                {
                    System.Diagnostics.Debug.WriteLine(
                        "CapNhatHienThiPanelOngGioACMV: " + ex.Message);
                }
            }
        }

        private void CapNhatDanhSachCnEiOngGio(PipeUiContext ctx)
        {
            if (ctx == null || ctx.Suffix != "ACMV")
                return;

            var lstCnEi = TimListBox("LstCnEiOngGioACMV");
            var txtTitle =
                FindName("TxtTieuDeCnEi") as System.Windows.Controls.TextBlock;

            if (lstCnEi == null)
                return;

            string material = GetSelectedPipeMaterialName(ctx);
            bool isHutKhoi = LaOngGioHutKhoi(material);

            // Hút khói → EI ; các loại ống gió còn lại → CN
            string[] items = isHutKhoi
                ? new[] { "EI30", "EI45", "EI60", "EI90", "EI120", "EI160" }
                : new[]
                {
                    "CN10", "CN13", "CN15", "CN20",
                    "CN25", "CN30", "CN35"
                };

            if (txtTitle != null)
                txtTitle.Text = isHutKhoi ? "EI" : "CN";

            // OG Hút khói thường cần EI → mặc định tích
            // OG Thải / OG Cấp thường không bọc CN → mặc định bỏ tích
            var chk =
                FindName("ChkDungCnEi") as System.Windows.Controls.CheckBox;

            if (chk != null)
            {
                chk.IsChecked = isHutKhoi;
                CapNhatTrangThaiCnEi();
            }

            string selected = LayNoiDungItem(lstCnEi.SelectedItem);
            lstCnEi.Items.Clear();

            foreach (string item in items)
            {
                lstCnEi.Items.Add(
                    new WpfListBoxItem
                    {
                        Content = item
                    });
            }

            int idx = 0;

            for (int i = 0; i < lstCnEi.Items.Count; i++)
            {
                if (LayNoiDungItem(lstCnEi.Items[i]).Equals(
                    selected,
                    StringComparison.OrdinalIgnoreCase))
                {
                    idx = i;
                    break;
                }
            }

            if (lstCnEi.Items.Count > 0)
                lstCnEi.SelectedIndex = idx;
        }

        private string GetSelectedOngGioSize()
        {
            var lstGio = TimListBox("LstSizeOngGioACMV");
            if (lstGio?.SelectedItem is PipeSizeItem psi &&
                !string.IsNullOrWhiteSpace(psi.SizeName))
                return psi.SizeName;

            string size = LayNoiDungItem(lstGio?.SelectedItem);
