        private List<Point3d> PromptVerticalRiserPoints(
            Editor ed)
        {
            List<Point3d> points =
                new List<Point3d>();

            if (ed == null)
                return points;

            while (true)
            {
                PromptPointOptions options =
                    new PromptPointOptions(
                        points.Count == 0
                            ? "\n[TRỤC ĐỨNG] Chọn tâm trục hoặc Enter để hủy: "
                            : "\n[TRỤC ĐỨNG] Chọn tâm trục tiếp theo hoặc Enter để kết thúc: ")
                    {
                        AllowNone = true
                    };

                PromptPointResult result =
                    ed.GetPoint(options);

                if (result.Status == PromptStatus.None)
                    break;

                if (result.Status != PromptStatus.OK)
                {
                    points.Clear();
                    break;
                }

                points.Add(result.Value);
            }

            return points;
        }

        private void EnsureVerticalRiserRegApp(
            Transaction tr,
            Database db)
        {
            RegAppTable table =
                (RegAppTable)tr.GetObject(
                    db.RegAppTableId,
                    OpenMode.ForRead);

            if (table.Has(VerticalRiserRegAppName))
                return;

            table.UpgradeOpen();

            RegAppTableRecord record =
                new RegAppTableRecord
                {
                    Name = VerticalRiserRegAppName
                };

            table.Add(record);
            tr.AddNewlyCreatedDBObject(record, true);
        }

        private ObjectId EnsureVerticalRiserBlockDefinition(
            Transaction tr,
            Database db,
            bool isUp)
        {
            string blockName =
                isUp
                    ? VerticalRiserBlockUpName
                    : VerticalRiserBlockDownName;

            BlockTable blockTable =
                (BlockTable)tr.GetObject(
                    db.BlockTableId,
                    OpenMode.ForRead);

            if (blockTable.Has(blockName))
                return blockTable[blockName];

            blockTable.UpgradeOpen();

            BlockTableRecord definition =
                new BlockTableRecord
                {
                    Name = blockName,
                    Origin = Point3d.Origin
                };

            ObjectId definitionId =
                blockTable.Add(definition);

            tr.AddNewlyCreatedDBObject(
                definition,
                true);

            Circle circle =
                new Circle(
                    Point3d.Origin,
                    Vector3d.ZAxis,
                    VerticalRiserMarkerRadius);

            AppendVerticalRiserBlockEntity(
                tr,
                db,
                definition,
                circle);

            double sign = isUp ? 1.0 : -1.0;
            Point3d arrowTail =
                new Point3d(
                    0.0,
                    -sign * 55.0,
                    0.0);
            Point3d arrowTip =
                new Point3d(
                    0.0,
                    sign * 78.0,
                    0.0);
            Point3d arrowLeft =
                new Point3d(
                    -32.0,
                    sign * 38.0,
                    0.0);
            Point3d arrowRight =
                new Point3d(
                    32.0,
                    sign * 38.0,
                    0.0);

            AppendVerticalRiserBlockEntity(
                tr,
                db,
                definition,
                new Line(arrowTail, arrowTip));
            AppendVerticalRiserBlockEntity(
                tr,
                db,
                definition,
                new Line(arrowTip, arrowLeft));
            AppendVerticalRiserBlockEntity(
                tr,
                db,
                definition,
                new Line(arrowTip, arrowRight));

            AttributeDefinition sizeAttribute =
                new AttributeDefinition(
                    new Point3d(
                        VerticalRiserMarkerRadius + 45.0,
                        30.0,
                        0.0),
                    "DN",
                    "SIZE",
                    "Size ống",
                    db.Textstyle)
                {
                    Height = VerticalRiserTextHeight,
                    Preset = true,
                    Verifiable = false,
                    LockPositionInBlock = true
                };

            AppendVerticalRiserBlockEntity(
                tr,
                db,
                definition,
                sizeAttribute);

            AttributeDefinition heightAttribute =
                new AttributeDefinition(
                    new Point3d(
                        VerticalRiserMarkerRadius + 45.0,
                        -55.0,
                        0.0),
                    "H=0.000m",
                    "HEIGHT",
                    "Chiều cao trục đứng",
                    db.Textstyle)
                {
                    Height = VerticalRiserTextHeight,
                    Preset = true,
                    Verifiable = false,
                    LockPositionInBlock = true
                };

            AppendVerticalRiserBlockEntity(
                tr,
                db,
                definition,
                heightAttribute);

            return definitionId;
        }

        private void AppendVerticalRiserBlockEntity(
            Transaction tr,
            Database db,
            BlockTableRecord definition,
            Entity entity)
        {
            if (tr == null ||
                db == null ||
                definition == null ||
                entity == null)
            {
                return;
            }

            entity.SetDatabaseDefaults(db);
            entity.Layer = "0";
            entity.Color =
                Autodesk.AutoCAD.Colors.Color
                    .FromColorIndex(
                        ColorMethod.ByBlock,
                        0);

            definition.AppendEntity(entity);
            tr.AddNewlyCreatedDBObject(entity, true);
        }

        private void AppendVerticalRiserAttributes(
            Transaction tr,
            BlockReference blockReference,
            ObjectId definitionId,
            string displaySize,
            double heightMeters)
        {
            if (tr == null ||
                blockReference == null ||
                definitionId.IsNull)
            {
                return;
            }

            BlockTableRecord definition =
                tr.GetObject(
                    definitionId,
                    OpenMode.ForRead,
                    false) as BlockTableRecord;

            if (definition == null)
                return;

            foreach (ObjectId id in definition)
            {
                AttributeDefinition source =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as AttributeDefinition;

                if (source == null ||
                    source.Constant)
                {
                    continue;
                }

                AttributeReference target =
                    new AttributeReference();

                target.SetAttributeFromBlock(
                    source,
                    blockReference.BlockTransform);

                if (string.Equals(
                        source.Tag,
                        "SIZE",
                        StringComparison.OrdinalIgnoreCase))
                {
                    target.TextString =
                        displaySize ?? "";
                }
                else if (string.Equals(
                             source.Tag,
                             "HEIGHT",
                             StringComparison.OrdinalIgnoreCase))
                {
                    target.TextString =
                        "H=" +
                        heightMeters.ToString(
                            "0.###",
                            CultureInfo.InvariantCulture) +
                        "m";
                }

                blockReference.AttributeCollection
                    .AppendAttribute(target);

                tr.AddNewlyCreatedDBObject(
                    target,
                    true);
            }
        }

        private void SetVerticalRiserXData(
            BlockReference blockReference,
            VerticalRiserData data)
        {
            if (blockReference == null ||
                data == null)
            {
                return;
            }

            using (ResultBuffer buffer =
                new ResultBuffer(
                    new TypedValue(
                        (int)DxfCode.ExtendedDataRegAppName,
                        VerticalRiserRegAppName),
                    new TypedValue(
                        (int)DxfCode.ExtendedDataAsciiString,
                        "V1"),
                    new TypedValue(
                        (int)DxfCode.ExtendedDataAsciiString,
                        data.Id ?? ""),
                    new TypedValue(
                        (int)DxfCode.ExtendedDataAsciiString,
                        data.PipeLayer ?? ""),
                    new TypedValue(
                        (int)DxfCode.ExtendedDataAsciiString,
                        data.SystemCode ?? ""),
                    new TypedValue(
                        (int)DxfCode.ExtendedDataAsciiString,
                        data.Material ?? ""),
                    new TypedValue(
                        (int)DxfCode.ExtendedDataAsciiString,
                        data.Size ?? ""),
                    new TypedValue(
                        (int)DxfCode.ExtendedDataAsciiString,
                        data.Direction ?? "UP"),
                    new TypedValue(
                        (int)DxfCode.ExtendedDataReal,
                        data.HeightMeters)))
            {
                blockReference.XData = buffer;
            }
        }

        private bool TryReadVerticalRiserData(
            Entity entity,
            out VerticalRiserData data)
        {
            data = null;

            if (entity == null ||
                entity.IsErased)
            {
                return false;
            }

            ResultBuffer buffer = null;

            try
            {
                buffer =
                    entity.GetXDataForApplication(
                        VerticalRiserRegAppName);

                if (buffer == null)
                    return false;

                TypedValue[] values =
                    buffer.AsArray();

                if (values == null ||
                    values.Length < 9)
                {
                    return false;
                }

                double height =
                    Convert.ToDouble(
                        values[8].Value,
                        CultureInfo.InvariantCulture);

                if (height <= 0.0 ||
                    double.IsNaN(height) ||
                    double.IsInfinity(height))
                {
                    return false;
                }

                data =
                    new VerticalRiserData
                    {
                        Id =
                            Convert.ToString(
                                values[2].Value,
                                CultureInfo.InvariantCulture) ?? "",
                        PipeLayer =
                            Convert.ToString(
                                values[3].Value,
                                CultureInfo.InvariantCulture) ??
                            entity.Layer ?? "",
                        SystemCode =
                            Convert.ToString(
                                values[4].Value,
                                CultureInfo.InvariantCulture) ?? "",
                        Material =
                            Convert.ToString(
                                values[5].Value,
                                CultureInfo.InvariantCulture) ?? "",
                        Size =
                            Convert.ToString(
                                values[6].Value,
                                CultureInfo.InvariantCulture) ?? "",
                        Direction =
                            Convert.ToString(
                                values[7].Value,
                                CultureInfo.InvariantCulture) ?? "UP",
                        HeightMeters = height
                    };

                return !string.IsNullOrWhiteSpace(
                    data.PipeLayer);
            }
            catch
            {
                data = null;
                return false;
            }
            finally
            {
                if (buffer != null)
                    buffer.Dispose();
            }
        }

        private int GetNextVerticalRiserSequence(
            Transaction tr,
            BlockTableRecord space)
        {
            int maxSequence = 0;

            if (tr == null ||
                space == null)
            {
                return 1;
            }

            foreach (ObjectId id in space)
            {
                BlockReference blockReference =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as BlockReference;

                if (blockReference == null ||
                    !TryReadVerticalRiserData(
                        blockReference,
                        out VerticalRiserData data))
                {
                    continue;
                }

                Match match =
                    Regex.Match(
                        data.Id ?? "",
                        @"(?<N>\d+)$");

                if (match.Success &&
                    int.TryParse(
                        match.Groups["N"].Value,
                        out int number))
                {
                    maxSequence =
                        Math.Max(
                            maxSequence,
                            number);
                }
            }

            return maxSequence + 1;
        }

        // ============================================================
        // KIỂM TRA 3D / 3D PIPE REVIEW
        // - Nhanh: dựng line 3D nhẹ máy, kiểm tra topo nhanh.
        // - Dep: dựng mô hình "BIM mini" đẹp hơn:
        //        + Ống nước / PCCC / CTN => Solid tròn
        //        + Ống gió => Solid hộp chữ nhật
        //        + Trục đứng => Solid đứng đúng chiều cao
        // ============================================================
        private enum Review3DDisplayMode
        {
            Nhanh,
            Dep
        }

        private enum Review3DProfileKind
        {
            PipeRound,
            DuctRect
        }

        private class Review3DPipeData
        {
            public ObjectId SourceId { get; set; }
            public string SourceLayer { get; set; }
            public List<Point3d> Points { get; set; } =
                new List<Point3d>();

            // Các đỉnh thật cần làm mượt (vd: góc PLINE).
            // Không dùng các điểm sample ARC để tránh mô hình bị "hạt".
            public List<Point3d> JointPoints { get; set; } =
                new List<Point3d>();

            // True nếu Points là các vertex thật của Polyline.
            // Khi đó chế độ ĐẸP có thể trim đoạn thẳng và chèn co sweep thật.
            public bool UseVertexJoints { get; set; } = false;

            public Review3DProfileKind ProfileKind { get; set; } =
                Review3DProfileKind.PipeRound;

            // PipeRound: Width = đường kính ngoài.
            // DuctRect: Width = bề rộng, Height = bề cao.
            public double Width { get; set; } =
                FixedDnPipeDisplayWidth;
            public double Height { get; set; } =
                FixedDnPipeDisplayWidth;

            public string DisplayLabel { get; set; } = "";

            public Point3d StartPoint
            {
                get
                {
                    return Points != null && Points.Count > 0
                        ? Points[0]
                        : Point3d.Origin;
                }
            }

            public Point3d EndPoint
            {
                get
                {
                    return Points != null && Points.Count > 0
                        ? Points[Points.Count - 1]
                        : Point3d.Origin;
                }
            }

            public bool IsClosed
            {
                get
                {
                    return Points != null &&
                           Points.Count > 2 &&
                           PlanDistance(
                               Points[0],
                               Points[Points.Count - 1]) <=
                           Review3DJoinTolerance * 0.25;
                }
            }
        }

        private class Review3DRiserData
        {
            public ObjectId SourceId { get; set; }
            public Point3d BasePoint { get; set; }
            public string PipeLayer { get; set; }
            public string Size { get; set; }
            public string Direction { get; set; }
            public double HeightMeters { get; set; }

            public Review3DProfileKind ProfileKind { get; set; } =
                Review3DProfileKind.PipeRound;

            public double Width { get; set; } =
                FixedDnPipeDisplayWidth;
            public double Height { get; set; } =
                FixedDnPipeDisplayWidth;
            public string DisplayLabel { get; set; } = "";
        }

        private class Review3DAirTerminalData
        {
            public ObjectId SourceId { get; set; }
            public Point3d Position { get; set; }
            public double Rotation { get; set; }
            public double Width { get; set; }
            public double Height { get; set; }
            public string DisplayLabel { get; set; } = "";
            public string Kind { get; set; } = "GRILLE";
        }

        private class Review3DErrorData
        {
            public Point3d Point { get; set; }
            public string Text { get; set; }
        }

        private class Review3DFittingConnection
        {
            public Point3d Node { get; set; }
            public Vector3d Direction { get; set; }
            public double Diameter { get; set; }
            public Review3DPipeData Pipe { get; set; }
            public Review3DRiserData Riser { get; set; }
            public bool IsRiser { get; set; }
        }

        private void BtnKiemTra3D_Click(
            object sender,
            RoutedEventArgs e)
        {
            PipeUiContext ctx =
                GetContext(sender);

            if (ctx == null)
                return;

            Document doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            Editor ed = doc.Editor;
            Database db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            // Nếu đã có preview 3D:
            // - đang xem 3D => có thể click lỗi để quay đúng vị trí 2D;
            // - đang focus 2D => có thể quay lại mô hình 3D;
            // - vẫn giữ LamMoi / Xoa trên cùng một nút để UI không bị rối.
            if (HasReview3DPreview(db))
            {
                if (_review3DIsIn2DFocus)
                {
                    PromptKeywordOptions focusOptions =
                        new PromptKeywordOptions(
                            "\n[KIỂM TRA 3D] Đang xem vị trí lỗi trên mặt bằng. " +
                            "[Quay3D/LamMoi/Xoa] <Quay3D>: ");

                    focusOptions.AllowNone = true;
                    focusOptions.Keywords.Add("Quay3D");
                    focusOptions.Keywords.Add("LamMoi");
                    focusOptions.Keywords.Add("Xoa");

                    PromptResult focusResult =
                        ed.GetKeywords(
                            focusOptions);

                    if (focusResult.Status ==
                        PromptStatus.Cancel)
                    {
                        return;
                    }

                    string focusChoice =
                        focusResult.Status ==
                            PromptStatus.OK
                            ? focusResult.StringResult
                            : "Quay3D";

                    if (string.Equals(
                            focusChoice,
                            "Quay3D",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        using (doc.LockDocument())
                        using (Transaction tr =
                            db.TransactionManager.StartTransaction())
                        {
                            DeleteReview2DFocusMarker(
                                tr,
                                db);

                            SetReview3DPreviewVisibility(
                                tr,
                                db,
                                true);

                            tr.Commit();
                        }

                        SetReview3DIsometricView(
                            ed);

                        SetReview3DConceptualVisualStyle();

                        TryIsolateReview3DPreview(
                            doc,
                            ed,
                            db);

                        TryZoomExtents(
                            doc);

                        _review3DIsIn2DFocus =
                            false;

                        StartReview3DEscapeWatcher();

                        ed.Regen();
                        return;
                    }

                    // Với LamMoi / Xoa phải trả object về trạng thái bình thường trước.
                    StopReview3DEscapeWatcher();

                    TryUnisolateReview3DObjects(
                        doc,
                        ed);

                    using (doc.LockDocument())
                    using (Transaction tr =
                        db.TransactionManager.StartTransaction())
                    {
                        DeleteReview2DFocusMarker(
                            tr,
                            db);

                        SetReview3DPreviewVisibility(
                            tr,
                            db,
                            true);

                        DeleteReview3DPreview(
                            tr,
                            db);

                        tr.Commit();
                    }

                    _review3DIsIn2DFocus =
                        false;

                    SetReview3DTopView(ed);
                    ed.Regen();

                    if (string.Equals(
                            focusChoice,
                            "Xoa",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        ed.WriteMessage(
                            "\n[KIỂM TRA 3D] Đã xóa mô hình kiểm tra 3D.");
                        return;
                    }

                    // LamMoi => tiếp tục xuống dưới để dựng preview mới.
                }
                else
                {
                    PromptKeywordOptions oldPreviewOptions =
                        new PromptKeywordOptions(
                            "\n[KIỂM TRA 3D] Đã có mô hình 3D. " +
                            "[TimLoi/LamMoi/Xoa] <TimLoi>: ");

                    oldPreviewOptions.AllowNone = true;
                    oldPreviewOptions.Keywords.Add("TimLoi");
                    oldPreviewOptions.Keywords.Add("LamMoi");
                    oldPreviewOptions.Keywords.Add("Xoa");

                    PromptResult oldPreviewResult =
                        ed.GetKeywords(oldPreviewOptions);

                    if (oldPreviewResult.Status ==
                        PromptStatus.Cancel)
                    {
                        return;
                    }

                    string oldChoice =
                        oldPreviewResult.Status ==
                            PromptStatus.OK
                            ? oldPreviewResult.StringResult
                            : "TimLoi";

                    if (string.Equals(
                            oldChoice,
                            "TimLoi",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        bool focused =
                            TryFocusReview3DErrorIn2D(
                                doc,
                                ed,
                                db);

                        if (focused)
                        {
                            _review3DIsIn2DFocus =
                                true;

                            StopReview3DEscapeWatcher();
                        }

                        return;
                    }

                    if (string.Equals(
                            oldChoice,
                            "Xoa",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        StopReview3DEscapeWatcher();

                        TryUnisolateReview3DObjects(
                            doc,
                            ed);

                        using (doc.LockDocument())
                        using (Transaction tr =
                            db.TransactionManager.StartTransaction())
                        {
                            DeleteReview2DFocusMarker(
                                tr,
                                db);

                            DeleteReview3DPreview(
                                tr,
                                db);

                            tr.Commit();
                        }

                        _review3DIsIn2DFocus =
                            false;

                        SetReview3DTopView(ed);
                        ed.Regen();

                        ed.WriteMessage(
                            "\n[KIỂM TRA 3D] Đã xóa mô hình kiểm tra 3D.");
                        return;
                    }

                    // LamMoi: bỏ cô lập, xóa preview cũ và về TOP.
                    StopReview3DEscapeWatcher();

                    TryUnisolateReview3DObjects(
                        doc,
                        ed);

                    using (doc.LockDocument())
                    using (Transaction tr =
                        db.TransactionManager.StartTransaction())
                    {
                        DeleteReview2DFocusMarker(
                            tr,
                            db);

                        DeleteReview3DPreview(
                            tr,
                            db);

                        tr.Commit();
                    }

                    _review3DIsIn2DFocus =
                        false;

                    SetReview3DTopView(ed);
                    ed.Regen();
                }
            }

            // Chọn chế độ dựng.
            PromptKeywordOptions modeOptions =
                new PromptKeywordOptions(
                    "\n[KIỂM TRA 3D] Chế độ " +
                    "[Nhanh/Dep] <Dep>: ");

            modeOptions.AllowNone = true;
            modeOptions.Keywords.Add("Nhanh");
            modeOptions.Keywords.Add("Dep");

            PromptResult modeResult =
                ed.GetKeywords(
                    modeOptions);

            if (modeResult.Status ==
                PromptStatus.Cancel)
            {
                return;
            }

            Review3DDisplayMode mode =
                (modeResult.Status == PromptStatus.OK &&
                 string.Equals(
                     modeResult.StringResult,
                     "Nhanh",
                     StringComparison.OrdinalIgnoreCase))
                    ? Review3DDisplayMode.Nhanh
                    : Review3DDisplayMode.Dep;

            // Cao độ Z của toàn bộ ống ngang trong vùng đang kiểm tra.
            PromptDoubleOptions elevationOptions =
                new PromptDoubleOptions(
                    "\n[KIỂM TRA 3D] Nhập CAO ĐỘ ỐNG NGANG (m) " +
                    "<" +
                    _lastReview3DElevationMeters
                        .ToString(
                            "0.###",
                            CultureInfo.InvariantCulture) +
                    ">: ");

            elevationOptions.AllowNone = true;
            elevationOptions.AllowNegative = true;
            elevationOptions.AllowZero = true;

            PromptDoubleResult elevationResult =
                ed.GetDouble(
                    elevationOptions);

            if (elevationResult.Status ==
                PromptStatus.Cancel)
            {
                return;
            }

            double elevationMeters =
                _lastReview3DElevationMeters;

            if (elevationResult.Status ==
                PromptStatus.OK)
            {
                elevationMeters =
                    elevationResult.Value;
            }

            if (double.IsNaN(elevationMeters) ||
                double.IsInfinity(elevationMeters))
            {
                MessageBox.Show(
                    "Cao độ ống ngang không hợp lệ.",
                    "KIỂM TRA 3D");
                return;
            }

            _lastReview3DElevationMeters =
                elevationMeters;

            PromptKeywordOptions rangeOptions =
                new PromptKeywordOptions(
                    "\n[KIỂM TRA 3D] Phạm vi kiểm tra " +
                    "[Vung/ToanBo] <Vung>: ");

            rangeOptions.AllowNone = true;
            rangeOptions.Keywords.Add("Vung");
            rangeOptions.Keywords.Add("ToanBo");

            PromptResult rangeResult =
                ed.GetKeywords(
                    rangeOptions);

            if (rangeResult.Status ==
                PromptStatus.Cancel)
            {
                return;
            }

            bool useAll =
                rangeResult.Status ==
                    PromptStatus.OK &&
                string.Equals(
                    rangeResult.StringResult,
                    "ToanBo",
                    StringComparison.OrdinalIgnoreCase);

            ObjectId[] sourceIds;

            if (useAll)
            {
                List<ObjectId> ids =
                    new List<ObjectId>();

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    BlockTableRecord space =
                        (BlockTableRecord)tr.GetObject(
                            db.CurrentSpaceId,
                            OpenMode.ForRead);

                    foreach (ObjectId id in space)
                    {
                        ids.Add(id);
                    }

                    tr.Commit();
                }

                sourceIds =
                    ids.ToArray();
            }
            else
            {
                PromptSelectionOptions selectionOptions =
                    new PromptSelectionOptions();

                selectionOptions.MessageForAdding =
                    "\n[KIỂM TRA 3D] Quét vùng ống / ống gió / trục đứng cần kiểm tra: ";

                PromptSelectionResult selectionResult =
                    ed.GetSelection(
                        selectionOptions);

                if (selectionResult.Status !=
                        PromptStatus.OK ||
                    selectionResult.Value == null ||
                    selectionResult.Value.Count == 0)
                {
                    return;
                }

                sourceIds =
                    selectionResult.Value
                        .GetObjectIds();
            }

            double elevation =
                elevationMeters * 1000.0;

            List<Review3DPipeData> pipes =
                new List<Review3DPipeData>();

            List<Review3DRiserData> risers =
                new List<Review3DRiserData>();

            List<Review3DAirTerminalData> airTerminals =
                new List<Review3DAirTerminalData>();

            List<Point3d> equipmentAnchors =
                new List<Point3d>();

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (ObjectId id in sourceIds)
                {
                    if (id.IsNull ||
                        !id.IsValid)
                    {
                        continue;
                    }

                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased)
                    {
                        continue;
                    }

                    string layer =
                        (ent.Layer ?? "")
                            .Trim();

                    if (IsReview3DTempLayer(layer))
                        continue;

                    // TRỤC ĐỨNG.
                    if (ent is BlockReference &&
                        TryReadVerticalRiserData(
                            ent,
                            out VerticalRiserData riserData))
                    {
                        string riserPipeLayer =
                            (riserData.PipeLayer ??
                             layer ??
                             "").Trim();

                        if (!LayerBelongsToReview3DContext(
                                ctx,
                                riserPipeLayer))
                        {
                            continue;
                        }

                        BlockReference br =
                            (BlockReference)ent;

                        Review3DProfileKind riserKind;
                        double riserW;
                        double riserH;
                        string riserLabel;

                        DetermineReview3DProfile(
                            string.IsNullOrWhiteSpace(
                                riserData.Size)
                                ? riserPipeLayer
                                : riserData.Size,
                            riserPipeLayer,
                            out riserKind,
                            out riserW,
                            out riserH,
                            out riserLabel);

                        risers.Add(
                            new Review3DRiserData
                            {
                                SourceId = id,
                                BasePoint =
                                    new Point3d(
                                        br.Position.X,
                                        br.Position.Y,
                                        0.0),
                                PipeLayer =
                                    riserPipeLayer,
                                Size =
                                    riserData.Size ?? "",
                                Direction =
                                    riserData.Direction ?? "UP",
                                HeightMeters =
                                    riserData.HeightMeters,
                                ProfileKind =
                                    riserKind,
                                Width = riserW,
                                Height = riserH,
                                DisplayLabel =
                                    riserLabel
                            });

                        continue;
                    }

                    // ỐNG NGANG / ỐNG GIÓ / ĐƯỜNG TÂM SHOP.
                    if (ent is Curve curve &&
                        IsReview3DPipeCurve(
                            ctx,
                            layer))
                    {
                        Review3DPipeData pipe =
                            BuildReview3DPipeData(
                                curve,
                                layer);

                        if (pipe != null &&
                            pipe.Points != null &&
                            pipe.Points.Count >= 2)
                        {
                            pipe.SourceId = id;
                            pipe.SourceLayer = layer;
                            pipes.Add(pipe);
                        }

                        continue;
                    }

                    // MIỆNG GIÓ 3D:
                    // Đọc các block ký hiệu miệng gió / diffuser / grille
                    // nằm cùng context để dựng gắn vào ống gió 3D.
                    if (ent is BlockReference blockRef &&
                        LayerBelongsToReview3DContext(
                            ctx,
                            layer) &&
                        !LaLayerThietBiHoacVan(layer))
                    {
                        if (TryBuildReview3DAirTerminal(
                                tr,
                                blockRef,
                                layer,
                                out Review3DAirTerminalData terminal))
                        {
                            terminal.SourceId = id;
                            airTerminals.Add(
                                terminal);
                        }
                    }

                    // Điểm thiết bị / van / text đầu cuối để tránh báo hở giả.
                    if (LayerBelongsToReview3DContext(
                            ctx,
                            layer) &&
                        LaLayerThietBiHoacVan(layer) &&
                        (ent is DBText ||
                         ent is MText ||
                         ent is BlockReference))
                    {
                        Point3d p =
                            LayDiemDaiDien(ent);

                        equipmentAnchors.Add(
                            new Point3d(
                                p.X,
                                p.Y,
                                0.0));
                    }
                }

                tr.Commit();
            }

            if (pipes.Count == 0 &&
                risers.Count == 0)
            {
                MessageBox.Show(
                    "Không tìm thấy ống / ống gió / trục đứng hợp lệ trong phạm vi chọn.\n\n" +
                    "Tool đọc:\n" +
                    "• Ống thường trên layer của tool.\n" +
                    "• Đường tâm ống SHOP.\n" +
                    "• Ống gió có size dạng 800x400 trong layer.\n" +
                    "• Trục đứng được tạo bằng nút VẼ TRỤC ĐỨNG.",
                    "KIỂM TRA 3D");
                return;
            }

            List<Review3DErrorData> errors =
                BuildReview3DErrors(
                    pipes,
                    risers,
                    equipmentAnchors,
                    elevation);

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                DeleteReview3DPreview(
                    tr,
                    db);

                EnsureReview3DLayers(
                    tr,
                    db);

                BlockTableRecord space =
                    (BlockTableRecord)tr.GetObject(
                        db.CurrentSpaceId,
                        OpenMode.ForWrite);

                foreach (Review3DPipeData pipe
                    in pipes)
                {
                    if (mode ==
                        Review3DDisplayMode.Dep)
                    {
                        AppendReview3DPrettyPipe(
                            tr,
                            db,
                            space,
                            pipe,
                            elevation);

                        AppendReview3DPipeSizeLabel(
                            tr,
                            db,
                            space,
                            pipe,
                            elevation);
                    }
                    else
                    {
                        AppendReview3DPipe(
                            tr,
                            db,
                            space,
                            pipe,
                            elevation);
                    }
                }

                foreach (Review3DRiserData riser
                    in risers)
                {
                    if (mode ==
                        Review3DDisplayMode.Dep)
                    {
                        AppendReview3DPrettyRiser(
                            tr,
                            db,
                            space,
                            riser,
                            elevation);

                        AppendReview3DRiserSizeLabel(
                            tr,
                            db,
                            space,
                            riser,
                            elevation);
                    }
                    else
                    {
                        AppendReview3DRiser(
                            tr,
                            db,
                            space,
                            riser,
                            elevation);
                    }
                }

                // Bản ĐẸP: thêm fitting tròn tại góc PLINE / giao tuyến ống tròn.
                // Mục đích là che mép giao giữa các cylinder, nhìn liền khối hơn.
                if (mode ==
                    Review3DDisplayMode.Dep)
                {
                    AppendReview3DAirTerminals(
                        tr,
                        db,
                        space,
                        pipes,
                        airTerminals,
                        elevation);

                    AppendReview3DPrettyJoints(
                        tr,
                        db,
                        space,
                        pipes,
                        risers,
                        elevation);
                }

                foreach (Review3DErrorData error
                    in errors)
                {
                    if (mode ==
                        Review3DDisplayMode.Dep)
                    {
                        AppendReview3DPrettyErrorMarker(
                            tr,
                            db,
                            space,
                            error);
                    }
                    else
                    {
                        AppendReview3DErrorMarker(
                            tr,
                            db,
                            space,
                            error);
                    }
                }

                if (mode ==
                    Review3DDisplayMode.Dep)
                {
                    MergeReview3DSolidsLikeRevit(
                        tr,
                        db);
                }

                tr.Commit();
            }

            _review3DIsIn2DFocus =
                false;

            CaptureReview3DOriginalViewIfNeeded(
                ed);

            SetReview3DIsometricView(ed);

            if (mode ==
                Review3DDisplayMode.Dep)
            {
                SetReview3DConceptualVisualStyle();
                TryIsolateReview3DPreview(
                    doc,
                    ed,
                    db);
                TryZoomExtents(
                    doc);
            }

            ed.Regen();

            StartReview3DEscapeWatcher();

            string modeText =
                mode == Review3DDisplayMode.Dep
                    ? "ĐẸP / KHỐI ĐẶC + MIỆNG GIÓ 3D"
                    : "NHANH";

            ed.WriteMessage(
                "\n[KIỂM TRA 3D] Chế độ " +
                modeText +
                " | " +
                pipes.Count +
                " tuyến/curve | " +
                risers.Count +
                " trục đứng | " +
                errors.Count +
                " vị trí nghi hở.");

            if (errors.Count > 0)
            {
                MessageBox.Show(
                    "Đã tạo mô hình KIỂM TRA 3D (" +
                    modeText +
                    ").\n\n" +
                    "Phát hiện " +
                    errors.Count +
                    " vị trí cần kiểm tra.\n" +
                    "Các vị trí này nằm trên layer " +
                    Review3DErrorLayer +
                    " và được đánh dấu HỞ / TRỤC CHƯA NỐI.\n" +
                    "Chế độ ĐẸP đã dựng CO / NỐI / GIẢM / TÊ 3D, cố gắng UNION khối, và tự gắn miệng gió 3D nếu phát hiện block gần ống gió.\n\n" +
                    "Lưu ý: đây là cảnh báo hình học để rà soát, " +
                    "không tự kết luận 100% là thiếu ống.",
                    "KIỂM TRA 3D");
            }
            else
            {
                MessageBox.Show(
                    "Đã tạo mô hình KIỂM TRA 3D (" +
                    modeText +
                    ").\n\n" +
                    "Chưa phát hiện đầu ống hở hoặc trục đứng " +
                    "không chạm tuyến trong phạm vi đã chọn.",
                    "KIỂM TRA 3D");
            }
        }

        private Review3DPipeData BuildReview3DPipeData(
            Curve curve,
            string layer)
        {
            Review3DPipeData pipe =
                BuildReview3DCenterline(
                    curve);

            if (pipe == null)
                return null;

            Review3DProfileKind kind;
            double width;
            double height;
            string label;

            DetermineReview3DProfile(
                layer,
                layer,
                out kind,
                out width,
                out height,
                out label);

            pipe.ProfileKind =
                kind;
            pipe.Width =
                width;
            pipe.Height =
                height;
            pipe.DisplayLabel =
                label;

            return pipe;
        }

        private Review3DPipeData BuildReview3DCenterline(
            Curve curve)
        {
            if (curve == null)
                return null;

            List<Point3d> points =
                new List<Point3d>();

            List<Point3d> joints =
                new List<Point3d>();

            bool useVertexJoints =
                false;

            try
            {
                if (curve is Line line)
                {
                    points.Add(
                        new Point3d(
                            line.StartPoint.X,
                            line.StartPoint.Y,
                            0.0));

                    points.Add(
                        new Point3d(
                            line.EndPoint.X,
                            line.EndPoint.Y,
                            0.0));
                }
                else if (curve is Polyline pline)
                {
                    useVertexJoints =
                        true;

                    int count =
                        pline.NumberOfVertices;

                    if (count < 2)
                        return null;

                    for (int i = 0;
                        i < count;
                        i++)
                    {
                        Point3d p =
                            pline.GetPoint3dAt(i);

                        Point3d flat =
                            new Point3d(
                                p.X,
                                p.Y,
                                0.0);

                        if (points.Count == 0 ||
                            PlanDistance(
                                points[points.Count - 1],
                                flat) > 1e-6)
                        {
                            points.Add(flat);
                        }

                        // Chỉ đỉnh giữa là joint thật.
                        if (i > 0 &&
                            i < count - 1)
                        {
                            joints.Add(flat);
                        }
                    }

                    if (pline.Closed &&
                        points.Count > 2)
                    {
                        if (PlanDistance(
                                points[0],
                                points[points.Count - 1]) >
                            1e-6)
                        {
                            points.Add(
                                points[0]);
                        }

                        // Với polyline kín, đỉnh đầu cũng là một joint.
                        joints.Add(
                            points[0]);
                    }
                }
                else
                {
                    // ARC / SPLINE / curve khác:
                    // sample vừa phải để mô hình theo được đường cong.
                    // KHÔNG đưa các sample này vào JointPoints.
                    double length =
                        LayChieuDaiCurveThongKe(
                            curve);

                    if (length <= 1e-6)
                        return null;

                    int segmentCount =
                        (int)Math.Ceiling(
                            length /
                            Review3DSampleStep);

                    segmentCount =
                        Math.Max(
                            4,
                            Math.Min(
                                segmentCount,
                                48));

                    for (int i = 0;
                        i <= segmentCount;
                        i++)
                    {
                        double dist =
                            length *
                            i /
                            segmentCount;

                        Point3d p;

                        if (i == 0)
                        {
                            p =
                                curve.StartPoint;
                        }
                        else if (i ==
                                 segmentCount)
                        {
                            p =
                                curve.EndPoint;
                        }
                        else
                        {
                            p =
                                curve.GetPointAtDist(
                                    dist);
                        }

                        Point3d flat =
                            new Point3d(
                                p.X,
                                p.Y,
                                0.0);

                        if (points.Count == 0 ||
                            PlanDistance(
                                points[points.Count - 1],
                                flat) > 1e-6)
                        {
                            points.Add(
                                flat);
                        }
                    }
                }
            }
            catch
            {
                try
                {
                    Point3d a =
                        curve.StartPoint;
                    Point3d b =
                        curve.EndPoint;

                    points.Clear();
                    joints.Clear();

                    points.Add(
                        new Point3d(
                            a.X,
                            a.Y,
                            0.0));

                    points.Add(
                        new Point3d(
                            b.X,
                            b.Y,
                            0.0));
                }
                catch
                {
                    return null;
                }
            }

            if (points.Count < 2)
                return null;

            return
                new Review3DPipeData
                {
                    Points = points,
                    JointPoints = joints,
                    UseVertexJoints =
                        useVertexJoints
                };
        }

        private bool HasReview3DPreview(
            Database db)
        {
            if (db == null)
                return false;

            try
            {
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    BlockTableRecord space =
                        (BlockTableRecord)tr.GetObject(
                            db.CurrentSpaceId,
                            OpenMode.ForRead);

                    foreach (ObjectId id in space)
                    {
                        Entity ent =
                            tr.GetObject(
                                id,
                                OpenMode.ForRead,
                                false) as Entity;

                        if (ent != null &&
                            !ent.IsErased &&
                            IsReview3DTempLayer(
                                ent.Layer))
                        {
                            return true;
                        }
                    }

                    tr.Commit();
                }
            }
            catch
            {
            }

            return false;
        }

        private static bool IsReview3DTempLayer(
            string layerName)
        {
            if (string.IsNullOrWhiteSpace(
                    layerName))
            {
                return false;
            }

            return
                layerName.Equals(
                    Review3DPipeLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DRiserLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DErrorLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DPipeSolidLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DDuctSolidLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DRiserSolidLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DFittingSolidLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DLabelLayer,
                    StringComparison.OrdinalIgnoreCase);
        }

        private bool LayerBelongsToReview3DContext(
            PipeUiContext ctx,
            string layerName)
        {
            if (ctx == null ||
                string.IsNullOrWhiteSpace(
                    layerName))
            {
                return false;
            }

            string u =
                layerName
                    .Trim()
                    .ToUpperInvariant();

            string systemCode =
                CleanLayerText(
                    GetSystemCode(ctx))
                    .ToUpperInvariant();

            if (systemCode == "FF")
            {
                return
                    u.StartsWith("FF_") ||
                    u.StartsWith("CHUA_CHAY_") ||
                    u.StartsWith("CHỮA_CHÁY_");
            }

            if (systemCode == "ACMV")
            {
                return
                    u.StartsWith("ACMV_");
            }

            if (systemCode == "CTN")
            {
                return
                    u.StartsWith("CTN_");
            }

            return
                u.StartsWith(
                    systemCode + "_");
        }

        private bool IsReview3DPipeCurve(
            PipeUiContext ctx,
            string layerName)
        {
            if (!LayerBelongsToReview3DContext(
                    ctx,
                    layerName))
            {
                return false;
            }

            // SHOP chỉ lấy TIM, không lấy 2 nét biên.
            if (LaLayerTamOngShop(
                    layerName))
            {
                return true;
            }

            if (LaLayerBienOngShop(
                    layerName) ||
                LaLayerPhuKienHoacTamShop(
                    layerName))
            {
                return false;
            }

            if (LaLayerOng(
                    layerName))
            {
                return true;
            }

            // Bổ sung nhận diện ống gió dựa trên size WxH trong layer.
            if (TryExtractDuctSizeFromText(
                    layerName,
                    out double _,
                    out double _))
            {
                return true;
            }

            return false;
        }

        private static bool TryExtractDuctSizeFromText(
            string source,
            out double width,
            out double height)
        {
            width = 0.0;
            height = 0.0;

            if (string.IsNullOrWhiteSpace(source))
                return false;

            Match m =
                Regex.Match(
                    source,
                    @"(\d+(?:\.\d+)?)\s*[xX×]\s*(\d+(?:\.\d+)?)");

            if (!m.Success)
                return false;

            if (!double.TryParse(
                    m.Groups[1].Value,
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out width))
            {
                return false;
            }

            if (!double.TryParse(
                    m.Groups[2].Value,
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out height))
            {
                return false;
            }

            width =
                Math.Max(
                    width,
                    Review3DMinimumVisualSize);
            height =
                Math.Max(
                    height,
                    Review3DMinimumVisualSize);

            return true;
        }

        private void DetermineReview3DProfile(
            string sourceText,
            string layerText,
            out Review3DProfileKind kind,
            out double width,
            out double height,
            out string label)
        {
            kind =
                Review3DProfileKind.PipeRound;
            width =
                FixedDnPipeDisplayWidth;
            height =
                FixedDnPipeDisplayWidth;
            label = "";

            string source =
                (sourceText ?? "").Trim();

            string layer =
                (layerText ?? "").Trim();

            if (TryExtractDuctSizeFromText(
                    source,
                    out double ductW,
                    out double ductH) ||
                TryExtractDuctSizeFromText(
                    layer,
                    out ductW,
                    out ductH))
            {
                kind =
                    Review3DProfileKind.DuctRect;
                width =
                    ductW;
                height =
                    ductH;
                label =
                    ductW.ToString(
                        "0.###",
                        CultureInfo.InvariantCulture) +
                    "x" +
                    ductH.ToString(
                        "0.###",
                        CultureInfo.InvariantCulture);
                return;
            }

            Match dnMatch =
                Regex.Match(
                    source + " " + layer,
                    @"DN\s*(\d+(?:\.\d+)?)",
                    RegexOptions.IgnoreCase);

            if (dnMatch.Success)
            {
                if (double.TryParse(
                        dnMatch.Groups[1].Value,
                        NumberStyles.Float,
                        CultureInfo.InvariantCulture,
                        out double dn))
                {
                    width =
                        LookupReview3DOutsideDiameter(
                            dn,
                            layer);
                    height = width;
                    label =
                        "DN" +
                        dn.ToString(
                            "0.###",
                            CultureInfo.InvariantCulture);
                    return;
                }
            }

            // Fallback: nếu không parse được, vẫn xem như ống tròn nhỏ.
            width =
                Math.Max(
                    FixedDnPipeDisplayWidth,
                    Review3DMinimumVisualSize);
            height =
                width;
            label = "PIPE";
        }

        private static double LookupReview3DOutsideDiameter(
            double nominal,
            string layerText)
        {
            if (nominal <= 0.0)
                return Review3DMinimumVisualSize;

            string layer =
                BoDauTiengViet(
                    layerText ?? "");

            bool preferFireSteel =
                layer.Contains("FF") ||
                layer.Contains("TRANG KEM") ||
                layer.Contains("THEP DEN") ||
                layer.Contains("NHUNG NONG");

            if (preferFireSteel)
            {
                foreach (double[] row
                    in FireSteelDnOutsideDiameterTable)
                {
                    if (row != null &&
                        row.Length >= 2 &&
                        Math.Abs(
                            row[0] - nominal) <= 0.6)
                    {
                        return
                            Math.Max(
                                row[1],
                                Review3DMinimumVisualSize);
                    }
                }
            }

            foreach (double[] row
                in OutsideDiameterToNominalTable)
            {
                if (row == null ||
                    row.Length < 2)
                {
                    continue;
                }

                if (Math.Abs(
                        row[0] - nominal) <= 0.6)
                {
                    return
                        Math.Max(
                            row[1],
                            Review3DMinimumVisualSize);
                }
            }

            return
                Math.Max(
                    nominal,
                    Review3DMinimumVisualSize);
        }

        private List<Review3DErrorData> BuildReview3DErrors(
            List<Review3DPipeData> pipes,
            List<Review3DRiserData> risers,
            List<Point3d> equipmentAnchors,
            double elevation)
        {
            List<Review3DErrorData> errors =
                new List<Review3DErrorData>();

            if (pipes == null)
                pipes =
                    new List<Review3DPipeData>();

            if (risers == null)
                risers =
                    new List<Review3DRiserData>();

            if (equipmentAnchors == null)
                equipmentAnchors =
                    new List<Point3d>();

            for (int i = 0;
                i < pipes.Count;
                i++)
            {
                Review3DPipeData pipe =
                    pipes[i];

                if (pipe == null ||
                    pipe.Points == null ||
                    pipe.Points.Count < 2 ||
                    pipe.IsClosed)
                {
                    continue;
                }

                Point3d[] ends =
                {
                    pipe.StartPoint,
                    pipe.EndPoint
                };

                foreach (Point3d endpoint
                    in ends)
                {
                    bool connected =
                        false;

                    for (int j = 0;
                        j < pipes.Count;
                        j++)
                    {
                        if (j == i)
                            continue;

                        if (DistancePointToReview3DPipe(
                                endpoint,
                                pipes[j]) <=
                            Review3DJoinTolerance)
                        {
                            connected = true;
                            break;
                        }
                    }

                    if (!connected)
                    {
                        foreach (Review3DRiserData riser
                            in risers)
                        {
                            if (PlanDistance(
                                    endpoint,
                                    riser.BasePoint) <=
                                Review3DJoinTolerance)
                            {
                                connected = true;
                                break;
                            }
                        }
                    }

                    if (!connected)
                    {
                        foreach (Point3d anchor
                            in equipmentAnchors)
                        {
                            if (PlanDistance(
                                    endpoint,
                                    anchor) <=
                                Review3DEquipmentTolerance)
                            {
                                connected = true;
                                break;
                            }
                        }
                    }

                    if (!connected)
                    {
                        AddReview3DErrorUnique(
                            errors,
                            new Review3DErrorData
                            {
                                Point =
                                    new Point3d(
                                        endpoint.X,
                                        endpoint.Y,
                                        elevation),
                                Text = "HỞ"
                            });
                    }
                }
            }

            foreach (Review3DRiserData riser
                in risers)
            {
                bool connectedToPipe =
                    false;

                foreach (Review3DPipeData pipe
                    in pipes)
                {
                    if (DistancePointToReview3DPipe(
                            riser.BasePoint,
                            pipe) <=
                        Review3DJoinTolerance)
                    {
                        connectedToPipe = true;
                        break;
                    }
                }

                if (!connectedToPipe)
                {
                    AddReview3DErrorUnique(
                        errors,
                        new Review3DErrorData
                        {
                            Point =
                                new Point3d(
                                    riser.BasePoint.X,
                                    riser.BasePoint.Y,
                                    elevation),
                            Text =
                                "TRỤC CHƯA NỐI"
                        });
                }
            }

            return errors;
        }

        private static void AddReview3DErrorUnique(
            List<Review3DErrorData> errors,
            Review3DErrorData candidate)
        {
            if (errors == null ||
                candidate == null)
            {
                return;
            }

            foreach (Review3DErrorData error
                in errors)
            {
                if (error == null)
                    continue;

                if (error.Point.DistanceTo(
                        candidate.Point) <=
                    Review3DJoinTolerance * 0.35)
                {
                    if ((candidate.Text ?? "")
                            .Contains("TRỤC"))
                    {
                        error.Text =
                            candidate.Text;
                    }

                    return;
                }
            }

            errors.Add(
                candidate);
        }

        private static double DistancePointToReview3DPipe(
            Point3d point,
            Review3DPipeData pipe)
        {
            if (pipe == null ||
                pipe.Points == null ||
                pipe.Points.Count < 2)
            {
                return double.MaxValue;
            }

            double best =
                double.MaxValue;

            for (int i = 0;
                i < pipe.Points.Count - 1;
                i++)
            {
                double d =
                    DistancePointToSegment2D(
                        point,
                        pipe.Points[i],
                        pipe.Points[i + 1]);

                if (d < best)
                    best = d;

                if (best <=
                    Review3DJoinTolerance)
                {
                    break;
                }
            }

            return best;
        }

        private static double DistancePointToSegment2D(
            Point3d p,
            Point3d a,
            Point3d b)
        {
            double dx =
                b.X - a.X;
            double dy =
                b.Y - a.Y;

            double len2 =
                dx * dx +
                dy * dy;

            if (len2 <= 1e-12)
            {
                return
                    Math.Sqrt(
                        (p.X - a.X) *
                        (p.X - a.X) +
                        (p.Y - a.Y) *
                        (p.Y - a.Y));
            }

            double t =
                ((p.X - a.X) * dx +
                 (p.Y - a.Y) * dy) /
                len2;

            t =
                Math.Max(
                    0.0,
                    Math.Min(
                        1.0,
                        t));

            double x =
                a.X +
                t * dx;
            double y =
                a.Y +
                t * dy;

            double ex =
                p.X - x;
            double ey =
                p.Y - y;

            return
                Math.Sqrt(
                    ex * ex +
                    ey * ey);
        }

