        private static void SetReview3DLayerColor(
            Transaction tr,
            Database db,
            string layerName,
            short aci)
        {
            LayerTable table =
                (LayerTable)tr.GetObject(
                    db.LayerTableId,
                    OpenMode.ForRead);

            if (!table.Has(layerName))
                return;

            LayerTableRecord layer =
                (LayerTableRecord)tr.GetObject(
                    table[layerName],
                    OpenMode.ForWrite);

            layer.Color =
                Autodesk.AutoCAD.Colors.Color
                    .FromColorIndex(
                        ColorMethod.ByAci,
                        aci);

            layer.IsPlottable = false;
        }

        private static void DeleteReview3DPreview(
            Transaction tr,
            Database db)
        {
            BlockTableRecord space =
                (BlockTableRecord)tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForRead);

            List<ObjectId> eraseIds =
                new List<ObjectId>();

            foreach (ObjectId id in space)
            {
                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent != null &&
                    !ent.IsErased &&
                    IsReview3DTempLayer(
                        ent.Layer))
                {
                    eraseIds.Add(id);
                }
            }

            foreach (ObjectId id in eraseIds)
            {
                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForWrite,
                        false) as Entity;

                if (ent != null &&
                    !ent.IsErased)
                {
                    ent.Erase();
                }
            }
        }

        private static void AppendReview3DPipe(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DPipeData pipe,
            double elevation)
        {
            if (pipe == null ||
                pipe.Points == null ||
                pipe.Points.Count < 2)
            {
                return;
            }

            for (int i = 0;
                i < pipe.Points.Count - 1;
                i++)
            {
                Point3d a =
                    pipe.Points[i];
                Point3d b =
                    pipe.Points[i + 1];

                if (PlanDistance(
                        a,
                        b) <= 1e-6)
                {
                    continue;
                }

                Line line =
                    new Line(
                        new Point3d(
                            a.X,
                            a.Y,
                            elevation),
                        new Point3d(
                            b.X,
                            b.Y,
                            elevation));

                line.SetDatabaseDefaults(db);
                line.Layer =
                    Review3DPipeLayer;
                line.ColorIndex = 256;

                space.AppendEntity(line);
                tr.AddNewlyCreatedDBObject(
                    line,
                    true);
            }
        }

        private static void AppendReview3DRiser(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DRiserData riser,
            double elevation)
        {
            if (riser == null ||
                riser.HeightMeters <= 0.0)
            {
                return;
            }

            bool isDown =
                string.Equals(
                    (riser.Direction ?? "")
                        .Trim(),
                    "DOWN",
                    StringComparison.OrdinalIgnoreCase);

            double targetZ =
                elevation +
                (isDown ? -1.0 : 1.0) *
                riser.HeightMeters *
                1000.0;

            Line line =
                new Line(
                    new Point3d(
                        riser.BasePoint.X,
                        riser.BasePoint.Y,
                        elevation),
                    new Point3d(
                        riser.BasePoint.X,
                        riser.BasePoint.Y,
                        targetZ));

            line.SetDatabaseDefaults(db);
            line.Layer =
                Review3DRiserLayer;
            line.ColorIndex = 256;

            space.AppendEntity(line);
            tr.AddNewlyCreatedDBObject(
                line,
                true);

            double half =
                Review3DErrorMarkerSize *
                0.35;

            Point3d top =
                new Point3d(
                    riser.BasePoint.X,
                    riser.BasePoint.Y,
                    targetZ);

            Line markX =
                new Line(
                    new Point3d(
                        top.X - half,
                        top.Y,
                        top.Z),
                    new Point3d(
                        top.X + half,
                        top.Y,
                        top.Z));

            markX.SetDatabaseDefaults(db);
            markX.Layer =
                Review3DRiserLayer;
            markX.ColorIndex = 256;

            space.AppendEntity(markX);
            tr.AddNewlyCreatedDBObject(
                markX,
                true);

            Line markY =
                new Line(
                    new Point3d(
                        top.X,
                        top.Y - half,
                        top.Z),
                    new Point3d(
                        top.X,
                        top.Y + half,
                        top.Z));

            markY.SetDatabaseDefaults(db);
            markY.Layer =
                Review3DRiserLayer;
            markY.ColorIndex = 256;

            space.AppendEntity(markY);
            tr.AddNewlyCreatedDBObject(
                markY,
                true);
        }

        private void AppendReview3DPrettyPipe(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DPipeData pipe,
            double elevation)
        {
            if (pipe == null ||
                pipe.Points == null ||
                pipe.Points.Count < 2)
            {
                return;
            }

            for (int i = 0;
                i < pipe.Points.Count - 1;
                i++)
            {
                Point3d a =
                    pipe.Points[i];
                Point3d b =
                    pipe.Points[i + 1];

                Vector3d planVector =
                    b - a;

                double planLength =
                    PlanDistance(
                        a,
                        b);

                if (planLength <= 1e-6)
                {
                    continue;
                }

                Point3d start =
                    new Point3d(
                        a.X,
                        a.Y,
                        elevation);

                Point3d end =
                    new Point3d(
                        b.X,
                        b.Y,
                        elevation);

                // Ống tròn là Polyline vertex thật:
                // trim hai đầu quanh góc để dành chỗ cho CO 3D sweep.
                if (pipe.ProfileKind ==
                        Review3DProfileKind.PipeRound &&
                    pipe.UseVertexJoints)
                {
                    Vector3d dir =
                        new Vector3d(
                            b.X - a.X,
                            b.Y - a.Y,
                            0.0)
                            .GetNormal();

                    double trimStart =
                        i > 0
                            ? CalculateReview3DElbowTrim(
                                pipe,
                                i)
                            : 0.0;

                    double trimEnd =
                        i < pipe.Points.Count - 2
                            ? CalculateReview3DElbowTrim(
                                pipe,
                                i + 1)
                            : 0.0;

                    double maxTrim =
                        planLength * 0.42;

                    trimStart =
                        Math.Min(
                            trimStart,
                            maxTrim);

                    trimEnd =
                        Math.Min(
                            trimEnd,
                            maxTrim);

                    if (trimStart +
                        trimEnd >
                        planLength * 0.82)
                    {
                        double scale =
                            planLength * 0.82 /
                            Math.Max(
                                trimStart + trimEnd,
                                1e-9);

                        trimStart *= scale;
                        trimEnd *= scale;
                    }

                    start =
                        start +
                        dir * trimStart;

                    end =
                        end -
                        dir * trimEnd;
                }

                if (start.DistanceTo(
                        end) <= 1e-6)
                {
                    continue;
                }

                if (pipe.ProfileKind ==
                    Review3DProfileKind.DuctRect)
                {
                    AppendReview3DRectSolidSegment(
                        tr,
                        db,
                        space,
                        start,
                        end,
                        Math.Max(
                            pipe.Width,
                            Review3DMinimumVisualSize),
                        Math.Max(
                            pipe.Height,
                            Review3DMinimumVisualSize),
                        Review3DDuctSolidLayer);
                }
                else
                {
                    AppendReview3DRoundSolidSegment(
                        tr,
                        db,
                        space,
                        start,
                        end,
                        Math.Max(
                            pipe.Width,
                            Review3DMinimumVisualSize),
                        Review3DPipeSolidLayer);
                }
            }
        }

        private double CalculateReview3DElbowTrim(
            Review3DPipeData pipe,
            int jointIndex)
        {
            if (pipe == null ||
                pipe.Points == null ||
                !pipe.UseVertexJoints ||
                jointIndex <= 0 ||
                jointIndex >=
                    pipe.Points.Count - 1)
            {
                return 0.0;
            }

            Point3d prev =
                pipe.Points[jointIndex - 1];

            Point3d joint =
                pipe.Points[jointIndex];

            Point3d next =
                pipe.Points[jointIndex + 1];

            Vector3d d1 =
                new Vector3d(
                    prev.X - joint.X,
                    prev.Y - joint.Y,
                    0.0);

            Vector3d d2 =
                new Vector3d(
                    next.X - joint.X,
                    next.Y - joint.Y,
                    0.0);

            if (d1.Length <= 1e-6 ||
                d2.Length <= 1e-6)
            {
                return 0.0;
            }

            d1 =
                d1.GetNormal();

            d2 =
                d2.GetNormal();

            double dot =
                Math.Max(
                    -1.0,
                    Math.Min(
                        1.0,
                        d1.DotProduct(
                            d2)));

            double theta =
                Math.Acos(
                    dot);

            double thetaDeg =
                theta * 180.0 /
                Math.PI;

            if (thetaDeg <
                    Review3DElbowMinAngleDeg ||
                thetaDeg >
                    Review3DElbowMaxAngleDeg)
            {
                return 0.0;
            }

            double diameter =
                Math.Max(
                    pipe.Width,
                    Review3DMinimumVisualSize);

            double centerRadius =
                Math.Max(
                    diameter *
                    Review3DElbowRadiusRatio,
                    Review3DElbowMinCenterRadius);

            double tanHalf =
                Math.Tan(
                    theta * 0.5);

            if (Math.Abs(
                    tanHalf) <= 1e-6)
            {
                return 0.0;
            }

            // Khoảng cách từ vertex tới tiếp điểm của cung fillet.
            return
                centerRadius /
                tanHalf;
        }

        private void AppendReview3DPrettyRiser(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DRiserData riser,
            double elevation)
        {
            if (riser == null ||
                riser.HeightMeters <= 0.0)
            {
                return;
            }

            bool isDown =
                string.Equals(
                    (riser.Direction ?? "")
                        .Trim(),
                    "DOWN",
                    StringComparison.OrdinalIgnoreCase);

            Point3d start =
                new Point3d(
                    riser.BasePoint.X,
                    riser.BasePoint.Y,
                    elevation);

            Point3d end =
                new Point3d(
                    riser.BasePoint.X,
                    riser.BasePoint.Y,
                    elevation +
                    (isDown ? -1.0 : 1.0) *
                    riser.HeightMeters *
                    1000.0);

            if (riser.ProfileKind ==
                Review3DProfileKind.DuctRect)
            {
                AppendReview3DRectSolidSegment(
                    tr,
                    db,
                    space,
                    start,
                    end,
                    Math.Max(
                        riser.Width,
                        Review3DMinimumVisualSize),
                    Math.Max(
                        riser.Height,
                        Review3DMinimumVisualSize),
                    Review3DRiserSolidLayer);
            }
            else
            {
                AppendReview3DRoundSolidSegment(
                    tr,
                    db,
                    space,
                    start,
                    end,
                    Math.Max(
                        riser.Width,
                        Review3DMinimumVisualSize),
                    Review3DRiserSolidLayer);
            }
        }

        private void AppendReview3DRoundSolidSegment(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Point3d start,
            Point3d end,
            double diameter,
            string layerName)
        {
            Solid3d solid =
                CreateReview3DRoundSolid(
                    start,
                    end,
                    diameter);

            if (solid != null)
            {
                solid.SetDatabaseDefaults(db);
                solid.Layer = layerName;
                solid.ColorIndex = 256;
                space.AppendEntity(solid);
                tr.AddNewlyCreatedDBObject(
                    solid,
                    true);
                return;
            }

            // Fallback nếu sweep thất bại.
            Line line =
                new Line(
                    start,
                    end);

            line.SetDatabaseDefaults(db);
            line.Layer =
                Review3DPipeLayer;
            line.ColorIndex = 256;
            space.AppendEntity(line);
            tr.AddNewlyCreatedDBObject(
                line,
                true);
        }

        private void AppendReview3DRectSolidSegment(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Point3d start,
            Point3d end,
            double width,
            double height,
            string layerName)
        {
            Solid3d solid =
                CreateReview3DRectSolid(
                    start,
                    end,
                    width,
                    height);

            if (solid != null)
            {
                solid.SetDatabaseDefaults(db);
                solid.Layer = layerName;
                solid.ColorIndex = 256;
                space.AppendEntity(solid);
                tr.AddNewlyCreatedDBObject(
                    solid,
                    true);
                return;
            }

            Line line =
                new Line(
                    start,
                    end);

            line.SetDatabaseDefaults(db);
            line.Layer =
                Review3DPipeLayer;
            line.ColorIndex = 256;
            space.AppendEntity(line);
            tr.AddNewlyCreatedDBObject(
                line,
                true);
        }

        private Solid3d CreateReview3DRoundSolid(
            Point3d start,
            Point3d end,
            double diameter)
        {
            Vector3d direction =
                end - start;

            if (direction.Length <= 1e-6)
                return null;

            double radius =
                Math.Max(
                    diameter,
                    Review3DMinimumVisualSize) * 0.5;

            Line path =
                new Line(
                    start,
                    end);

            Circle profile =
                new Circle(
                    Point3d.Origin,
                    Vector3d.ZAxis,
                    radius);

            DBObjectCollection curveColl =
                new DBObjectCollection();

            DBObjectCollection regionColl =
                null;

            Solid3d solid =
                null;

            try
            {
                Matrix3d profileTransform =
                    BuildReview3DProfileTransform(
                        start,
                        direction);

                profile.TransformBy(
                    profileTransform);

                curveColl.Add(profile);

                regionColl =
                    Autodesk.AutoCAD.DatabaseServices.Region.CreateFromCurves(
                        curveColl);

                if (regionColl == null ||
                    regionColl.Count == 0)
                {
                    return null;
                }

                Autodesk.AutoCAD.DatabaseServices.Region region =
                    regionColl[0] as Autodesk.AutoCAD.DatabaseServices.Region;

                if (region == null)
                    return null;

                SweepOptionsBuilder builder =
                    new SweepOptionsBuilder();

                builder.Align =
                    SweepOptionsAlignOption.AlignSweepEntityToPath;
                builder.AlignStart = true;
                builder.BasePoint = start;
                builder.CheckIntersections = false;

                solid =
                    new Solid3d();

                solid.RecordHistory = false;
                solid.CreateSweptSolid(
                    region,
                    path,
                    builder.ToSweepOptions());

                region.Dispose();

                for (int i = 1;
                    i < regionColl.Count;
                    i++)
                {
                    if (regionColl[i] is IDisposable d)
                        d.Dispose();
                }

                path.Dispose();
                profile.Dispose();

                return solid;
            }
            catch
            {
                if (solid != null)
                    solid.Dispose();

                try
                {
                    path.Dispose();
                }
                catch
                {
                }

                try
                {
                    profile.Dispose();
                }
                catch
                {
                }

                if (regionColl != null)
                {
                    foreach (object obj
                        in regionColl)
                    {
                        if (obj is IDisposable d)
                        {
                            try
                            {
                                d.Dispose();
                            }
                            catch
                            {
                            }
                        }
                    }
                }

                return null;
            }
        }

        private Solid3d CreateReview3DRectSolid(
            Point3d start,
            Point3d end,
            double width,
            double height)
        {
            Vector3d direction =
                end - start;

            if (direction.Length <= 1e-6)
                return null;

            double halfW =
                Math.Max(
                    width,
                    Review3DMinimumVisualSize) * 0.5;
            double halfH =
                Math.Max(
                    height,
                    Review3DMinimumVisualSize) * 0.5;

            Line path =
                new Line(
                    start,
                    end);

            Polyline profile =
                new Polyline();

            DBObjectCollection curveColl =
                new DBObjectCollection();

            DBObjectCollection regionColl =
                null;

            Solid3d solid =
                null;

            try
            {
                profile.AddVertexAt(
                    0,
                    new Point2d(-halfW, -halfH),
                    0.0,
                    0.0,
                    0.0);

                profile.AddVertexAt(
                    1,
                    new Point2d(halfW, -halfH),
                    0.0,
                    0.0,
                    0.0);

                profile.AddVertexAt(
                    2,
                    new Point2d(halfW, halfH),
                    0.0,
                    0.0,
                    0.0);

                profile.AddVertexAt(
                    3,
                    new Point2d(-halfW, halfH),
                    0.0,
                    0.0,
                    0.0);

                profile.Closed = true;

                Matrix3d profileTransform =
                    BuildReview3DProfileTransform(
                        start,
                        direction);

                profile.TransformBy(
                    profileTransform);

                curveColl.Add(profile);

                regionColl =
                    Autodesk.AutoCAD.DatabaseServices.Region.CreateFromCurves(
                        curveColl);

                if (regionColl == null ||
                    regionColl.Count == 0)
                {
                    return null;
                }

                Autodesk.AutoCAD.DatabaseServices.Region region =
                    regionColl[0] as Autodesk.AutoCAD.DatabaseServices.Region;

                if (region == null)
                    return null;

                SweepOptionsBuilder builder =
                    new SweepOptionsBuilder();

                builder.Align =
                    SweepOptionsAlignOption.AlignSweepEntityToPath;
                builder.AlignStart = true;
                builder.BasePoint = start;
                builder.CheckIntersections = false;

                solid =
                    new Solid3d();

                solid.RecordHistory = false;
                solid.CreateSweptSolid(
                    region,
                    path,
                    builder.ToSweepOptions());

                region.Dispose();

                for (int i = 1;
                    i < regionColl.Count;
                    i++)
                {
                    if (regionColl[i] is IDisposable d)
                        d.Dispose();
                }

                path.Dispose();
                profile.Dispose();

                return solid;
            }
            catch
            {
                if (solid != null)
                    solid.Dispose();

                try
                {
                    path.Dispose();
                }
                catch
                {
                }

                try
                {
                    profile.Dispose();
                }
                catch
                {
                }

                if (regionColl != null)
                {
                    foreach (object obj
                        in regionColl)
                    {
                        if (obj is IDisposable d)
                        {
                            try
                            {
                                d.Dispose();
                            }
                            catch
                            {
                            }
                        }
                    }
                }

                return null;
            }
        }

        private static Matrix3d BuildReview3DProfileTransform(
            Point3d origin,
            Vector3d direction)
        {
            Vector3d zAxis =
                direction.GetNormal();

            Vector3d xAxis;

            if (Math.Abs(
                    zAxis.DotProduct(
                        Vector3d.ZAxis)) > 0.98)
            {
                xAxis =
                    Vector3d.XAxis;
            }
            else
            {
                xAxis =
                    Vector3d.ZAxis
                        .CrossProduct(
                            zAxis)
                        .GetNormal();
            }

            Vector3d yAxis =
                zAxis
                    .CrossProduct(
                        xAxis)
                    .GetNormal();

            return
                Matrix3d.AlignCoordinateSystem(
                    Point3d.Origin,
                    Vector3d.XAxis,
                    Vector3d.YAxis,
                    Vector3d.ZAxis,
                    origin,
                    xAxis,
                    yAxis,
                    zAxis);
        }

        private bool TryBuildReview3DAirTerminal(
            Transaction tr,
            BlockReference blockRef,
            string layer,
            out Review3DAirTerminalData terminal)
        {
            terminal = null;

            if (tr == null ||
                blockRef == null ||
                blockRef.IsErased)
            {
                return false;
            }

            string blockName =
                GetShopStatBlockName(
                    tr,
                    blockRef);

            string source =
                ((blockName ?? "") +
                 " " +
                 (layer ?? ""))
                    .ToUpperInvariant();

            bool keywordMatched =
                source.Contains("MIENG") ||
                source.Contains("GRILLE") ||
                source.Contains("DIFF") ||
                source.Contains("LOUVER") ||
                source.Contains("SAG") ||
                source.Contains("RAG") ||
                source.Contains("EAG") ||
                source.Contains("SA ") ||
                source.Contains(" RA ") ||
                source.Contains(" EA ");

            double width =
                0.0;
            double height =
                0.0;

            if (!TryExtractDuctSizeFromText(
                    source,
                    out width,
                    out height))
            {
                try
                {
                    Extents3d ext =
                        blockRef.GeometricExtents;

                    double ex =
                        Math.Abs(
                            ext.MaxPoint.X -
                            ext.MinPoint.X);

                    double ey =
                        Math.Abs(
                            ext.MaxPoint.Y -
                            ext.MinPoint.Y);

                    double maxXY =
                        Math.Max(
                            ex,
                            ey);

                    double minXY =
                        Math.Min(
                            ex,
                            ey);

                    // Nếu block quá nhỏ hoặc quá lớn,
                    // coi như không phải miệng gió.
                    if (maxXY < 40.0 ||
                        maxXY > 2000.0)
                    {
                        if (!keywordMatched)
                            return false;
                    }

                    if (maxXY >= 40.0)
                    {
                        if (minXY <= 1e-6)
                            minXY = maxXY;

                        if (maxXY / Math.Max(minXY, 1.0) > 1.8)
                        {
                            width =
                                Math.Max(
                                    250.0,
                                    Math.Min(
                                        maxXY,
                                        1200.0));

                            height =
                                Math.Max(
                                    100.0,
                                    Math.Min(
                                        minXY,
                                        350.0));
                        }
                        else
                        {
                            width =
                                Math.Max(
                                    250.0,
                                    Math.Min(
                                        maxXY,
                                        900.0));

                            height =
                                Math.Max(
                                    250.0,
                                    Math.Min(
                                        minXY,
                                        900.0));
                        }
                    }
                }
                catch
                {
                }
            }

            if (width <= 1e-6 ||
                height <= 1e-6)
            {
                if (!keywordMatched)
                    return false;

                width = 600.0;
                height = 150.0;
            }

            string kind =
                width / Math.Max(height, 1.0) > 1.8
                    ? "LINEAR"
                    : "GRILLE";

            terminal =
                new Review3DAirTerminalData
                {
                    Position =
                        new Point3d(
                            blockRef.Position.X,
                            blockRef.Position.Y,
                            0.0),
                    Rotation =
                        blockRef.Rotation,
                    Width = width,
                    Height = height,
                    DisplayLabel =
                        width.ToString(
                            "0.###",
                            CultureInfo.InvariantCulture) +
                        "x" +
                        height.ToString(
                            "0.###",
                            CultureInfo.InvariantCulture),
                    Kind = kind
                };

            return true;
        }

        private void AppendReview3DAirTerminals(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            List<Review3DPipeData> pipes,
            List<Review3DAirTerminalData> airTerminals,
            double elevation)
        {
            if (pipes == null ||
                airTerminals == null ||
                airTerminals.Count == 0)
            {
                return;
            }

            List<Review3DPipeData> ducts =
                pipes
                    .Where(
                        p =>
                            p != null &&
                            p.ProfileKind ==
                                Review3DProfileKind.DuctRect &&
                            p.Points != null &&
                            p.Points.Count >= 2)
                    .ToList();

            if (ducts.Count == 0)
                return;

            foreach (Review3DAirTerminalData terminal
                in airTerminals)
            {
                if (terminal == null)
                    continue;

                if (!TryFindNearestReview3DDuctSegment(
                        ducts,
                        terminal.Position,
                        out Review3DPipeData duct,
                        out Point3d attachPoint2D,
                        out Vector3d segmentDirection,
                        out double planDistance))
                {
                    continue;
                }

                double maxAttachDistance =
                    Math.Max(
                        duct.Width * 0.9,
                        900.0);

                if (planDistance >
                    maxAttachDistance)
                {
                    continue;
                }

                AppendReview3DAirTerminalAtDuct(
                    tr,
                    db,
                    space,
                    duct,
                    terminal,
                    attachPoint2D,
                    segmentDirection,
                    elevation);
            }
        }

        private bool TryFindNearestReview3DDuctSegment(
            List<Review3DPipeData> ducts,
            Point3d probe,
            out Review3DPipeData bestDuct,
            out Point3d bestPoint,
            out Vector3d bestDirection,
            out double bestDistance)
        {
            bestDuct = null;
            bestPoint = Point3d.Origin;
            bestDirection = Vector3d.XAxis;
            bestDistance = double.MaxValue;

            if (ducts == null)
                return false;

            foreach (Review3DPipeData duct
                in ducts)
            {
                if (duct == null ||
                    duct.Points == null ||
                    duct.Points.Count < 2)
                {
                    continue;
                }

                for (int i = 0;
                    i < duct.Points.Count - 1;
                    i++)
                {
                    Point3d a = duct.Points[i];
                    Point3d b = duct.Points[i + 1];

                    Vector3d ab =
                        new Vector3d(
                            b.X - a.X,
                            b.Y - a.Y,
                            0.0);

                    double len =
                        ab.Length;

                    if (len <= 1e-6)
                        continue;

                    Vector3d dir =
                        ab.GetNormal();

                    Vector3d ap =
                        new Vector3d(
                            probe.X - a.X,
                            probe.Y - a.Y,
                            0.0);

                    double t =
                        ap.DotProduct(dir);

                    t =
                        Math.Max(
                            0.0,
                            Math.Min(
                                len,
                                t));

                    Point3d proj =
                        new Point3d(
                            a.X + dir.X * t,
                            a.Y + dir.Y * t,
                            0.0);

                    double dist =
                        PlanDistance(
                            probe,
                            proj);

                    if (dist < bestDistance)
                    {
                        bestDistance = dist;
                        bestDuct = duct;
                        bestPoint = proj;
                        bestDirection = dir;
                    }
                }
            }

            return bestDuct != null;
        }

        private void AppendReview3DAirTerminalAtDuct(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DPipeData duct,
            Review3DAirTerminalData terminal,
            Point3d attachPoint2D,
            Vector3d segmentDirection,
            double elevation)
        {
            if (duct == null ||
                terminal == null)
            {
                return;
            }

            Point3d attachBottomCenter =
                new Point3d(
                    attachPoint2D.X,
                    attachPoint2D.Y,
                    elevation -
                    Math.Max(
                        duct.Height,
                        Review3DMinimumVisualSize) * 0.5);

            double faceWidth =
                Math.Max(
                    150.0,
                    Math.Min(
                        terminal.Width,
                        duct.Width * 0.95));

            double faceHeight =
                Math.Max(
                    100.0,
                    Math.Min(
                        terminal.Height,
                        duct.Width * 0.75));

            double neckWidth =
                Math.Max(
                    120.0,
                    Math.Min(
                        faceWidth * 0.70,
                        duct.Width * 0.70));

            double neckHeight =
                Math.Max(
                    80.0,
                    Math.Min(
                        faceHeight * 0.70,
                        duct.Width * 0.45));

            double drop =
                Math.Max(
                    duct.Height * 0.90,
                    180.0);

            Point3d neckEnd =
                new Point3d(
                    attachBottomCenter.X,
                    attachBottomCenter.Y,
                    attachBottomCenter.Z -
                    drop);

            AppendReview3DRectSolidSegment(
                tr,
                db,
                space,
                attachBottomCenter,
                neckEnd,
                neckWidth,
                neckHeight,
                Review3DFittingSolidLayer);

            double boxThickness =
                Math.Max(
                    24.0,
                    faceHeight * 0.08);

            Point3d grilleBottom =
                new Point3d(
                    neckEnd.X,
                    neckEnd.Y,
                    neckEnd.Z -
                    boxThickness);

            Solid3d grille =
                CreateReview3DRectSolid(
                    neckEnd,
                    grilleBottom,
                    faceWidth,
                    faceHeight);

            if (grille != null)
            {
                try
                {
                    double rot =
                        Math.Abs(
                            terminal.Rotation) > 1e-6
                            ? terminal.Rotation
                            : Math.Atan2(
                                segmentDirection.Y,
                                segmentDirection.X);

                    Point3d center =
                        new Point3d(
                            neckEnd.X,
                            neckEnd.Y,
                            neckEnd.Z -
                            boxThickness * 0.5);

                    grille.TransformBy(
                        Matrix3d.Rotation(
                            rot,
                            Vector3d.ZAxis,
                            center));

                    grille.SetDatabaseDefaults(db);
                    grille.Layer =
                        Review3DFittingSolidLayer;
                    grille.ColorIndex =
                        256;

                    space.AppendEntity(
                        grille);

                    tr.AddNewlyCreatedDBObject(
                        grille,
                        true);
                }
                catch
                {
                    grille.Dispose();
                }
            }

            AppendReview3DLabelText(
                tr,
                db,
                space,
                new Point3d(
                    neckEnd.X +
                    Math.Max(
                        faceWidth * 0.65,
                        140.0),
                    neckEnd.Y,
                    neckEnd.Z -
                    boxThickness * 0.5),
                terminal.DisplayLabel,
                0.0);
        }

        private void AppendReview3DPrettyJoints(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            List<Review3DPipeData> pipes,
            List<Review3DRiserData> risers,
            double elevation)
        {
            if (pipes == null)
                return;

            List<Point3d> placed =
                new List<Point3d>();

            // --------------------------------------------------------
            // A) CO THẬT cho các vertex của Polyline ống tròn.
            // Straight segments đã được trim trong AppendReview3DPrettyPipe.
            // --------------------------------------------------------
            foreach (Review3DPipeData pipe
                in pipes)
            {
                if (pipe == null ||
                    pipe.ProfileKind !=
                        Review3DProfileKind.PipeRound ||
                    !pipe.UseVertexJoints ||
                    pipe.Points == null ||
                    pipe.Points.Count < 3)
                {
                    continue;
                }

                for (int jointIndex = 1;
                    jointIndex <
                        pipe.Points.Count - 1;
                    jointIndex++)
                {
                    if (AppendReview3DRealElbow(
                            tr,
                            db,
                            space,
                            pipe,
                            jointIndex,
                            elevation))
                    {
                        placed.Add(
                            new Point3d(
                                pipe.Points[jointIndex].X,
                                pipe.Points[jointIndex].Y,
                                elevation));
                    }
                }
            }

            // --------------------------------------------------------
            // B) Gom endpoint thành NODE để nhận diện:
            // - 2 tuyến thẳng khác DN => GIẢM
            // - 2 tuyến cùng DN thẳng => NỐI / MĂNG SÔNG
            // - 3+ nhánh => TÊ / TÊ GIẢM dạng fitting body
            // - nút khó => fallback sphere nhỏ.
            // --------------------------------------------------------
            List<List<Review3DFittingConnection>> nodes =
                BuildReview3DFittingNodes(
                    pipes,
                    risers,
                    elevation);

            foreach (List<Review3DFittingConnection> node
                in nodes)
            {
                if (node == null ||
                    node.Count < 2)
                {
                    continue;
                }

                Point3d center =
                    node[0].Node;

                bool alreadyPlaced =
                    placed.Any(
                        p =>
                            p.DistanceTo(
                                center) <=
                            Review3DJoinTolerance * 0.35);

                if (alreadyPlaced)
                    continue;

                List<Review3DFittingConnection> roundConnections =
                    node
                        .Where(
                            c =>
                                c != null &&
                                c.Diameter > 0.0)
                        .ToList();

                if (roundConnections.Count < 2)
                    continue;

                bool handled =
                    false;

                if (roundConnections.Count == 2)
                {
                    Review3DFittingConnection a =
                        roundConnections[0];

                    Review3DFittingConnection b =
                        roundConnections[1];

                    double angleDeg =
                        GetReview3DAngleDeg(
                            a.Direction,
                            b.Direction);

                    bool nearlyStraight =
                        angleDeg >=
                        Review3DStraightAngleDeg;

                    bool differentDiameter =
                        Review3DDiametersDifferent(
                            a.Diameter,
                            b.Diameter);

                    if (nearlyStraight &&
                        differentDiameter)
                    {
                        handled =
                            AppendReview3DReducerFitting(
                                tr,
                                db,
                                space,
                                center,
                                a,
                                b);
                    }
                    else if (nearlyStraight)
                    {
                        // Không chèn măng sông lồi ở 2 ống cùng size,
                        // để khối nhìn liền mạch hơn.
                        handled = true;
                    }
                    else
                    {
                        // Hai entity rời gặp góc: nếu cùng nằm ngang thì tạo co sweep.
                        handled =
                            AppendReview3DNodeElbow(
                                tr,
                                db,
                                space,
                                center,
                                a,
                                b);
                    }
                }
                else
                {
                    handled =
                        AppendReview3DTeeFitting(
                            tr,
                            db,
                            space,
                            center,
                            roundConnections);
                }

                if (!handled)
                {
                    double maxDiameter =
                        roundConnections
                            .Max(
                                c =>
                                    Math.Max(
                                        c.Diameter,
                                        Review3DMinimumVisualSize));

                    AppendReview3DJointSphereUnique(
                        tr,
                        db,
                        space,
                        placed,
                        center,
                        maxDiameter * 0.50);
                }
                else
                {
                    placed.Add(
                        center);
                }
            }
        }

        private List<List<Review3DFittingConnection>> BuildReview3DFittingNodes(
            List<Review3DPipeData> pipes,
            List<Review3DRiserData> risers,
            double elevation)
        {
            List<Review3DFittingConnection> all =
                new List<Review3DFittingConnection>();

            if (pipes != null)
            {
                foreach (Review3DPipeData pipe
                    in pipes)
                {
                    if (pipe == null ||
                        pipe.ProfileKind !=
                            Review3DProfileKind.PipeRound ||
                        pipe.Points == null ||
                        pipe.Points.Count < 2)
                    {
                        continue;
                    }

                    double diameter =
                        Math.Max(
                            pipe.Width,
                            Review3DMinimumVisualSize);

                    Point3d s =
                        pipe.StartPoint;

                    Point3d sNext =
                        pipe.Points[1];

                    Vector3d sDir =
                        new Vector3d(
                            sNext.X - s.X,
                            sNext.Y - s.Y,
                            0.0);

                    if (sDir.Length > 1e-6)
                    {
                        all.Add(
                            new Review3DFittingConnection
                            {
                                Node =
                                    new Point3d(
                                        s.X,
                                        s.Y,
                                        elevation),
                                Direction =
                                    sDir.GetNormal(),
                                Diameter =
                                    diameter,
                                Pipe =
                                    pipe
                            });
                    }

                    Point3d e =
                        pipe.EndPoint;

                    Point3d ePrev =
                        pipe.Points[
                            pipe.Points.Count - 2];

                    Vector3d eDir =
                        new Vector3d(
                            ePrev.X - e.X,
                            ePrev.Y - e.Y,
                            0.0);

                    if (eDir.Length > 1e-6)
                    {
                        all.Add(
                            new Review3DFittingConnection
                            {
                                Node =
                                    new Point3d(
                                        e.X,
                                        e.Y,
                                        elevation),
                                Direction =
                                    eDir.GetNormal(),
                                Diameter =
                                    diameter,
                                Pipe =
                                    pipe
                            });
                    }
                }
            }

            if (risers != null)
            {
                foreach (Review3DRiserData riser
                    in risers)
                {
                    if (riser == null ||
                        riser.ProfileKind !=
                            Review3DProfileKind.PipeRound ||
                        riser.HeightMeters <= 0.0)
                    {
                        continue;
                    }

                    bool isDown =
                        string.Equals(
                            (riser.Direction ?? "")
                                .Trim(),
                            "DOWN",
                            StringComparison.OrdinalIgnoreCase);

                    all.Add(
                        new Review3DFittingConnection
                        {
                            Node =
                                new Point3d(
                                    riser.BasePoint.X,
                                    riser.BasePoint.Y,
                                    elevation),
                            Direction =
                                isDown
                                    ? -Vector3d.ZAxis
                                    : Vector3d.ZAxis,
                            Diameter =
                                Math.Max(
                                    riser.Width,
                                    Review3DMinimumVisualSize),
                            Riser =
                                riser,
                            IsRiser =
                                true
                        });
                }
            }

            List<List<Review3DFittingConnection>> nodes =
                new List<List<Review3DFittingConnection>>();

            foreach (Review3DFittingConnection connection
                in all)
            {
                List<Review3DFittingConnection> target =
                    null;

                foreach (List<Review3DFittingConnection> existing
                    in nodes)
                {
                    if (existing == null ||
                        existing.Count == 0)
                    {
                        continue;
                    }

                    if (existing[0].Node.DistanceTo(
                            connection.Node) <=
                        Review3DJoinTolerance)
                    {
                        target =
                            existing;
                        break;
                    }
                }

                if (target == null)
                {
                    target =
                        new List<Review3DFittingConnection>();

                    nodes.Add(
                        target);
                }

                target.Add(
                    connection);
            }

            return
                nodes
                    .Where(
                        n =>
                            n != null &&
                            n.Count >= 2)
                    .ToList();
        }

        private static bool Review3DDiametersDifferent(
            double a,
            double b)
        {
            double max =
                Math.Max(
                    Math.Abs(a),
                    Math.Abs(b));

            if (max <= 1e-6)
                return false;

            return
                Math.Abs(
                    a - b) /
                max >=
                Review3DDiameterDifferentRatio;
        }

        private static double GetReview3DAngleDeg(
            Vector3d a,
            Vector3d b)
        {
            if (a.Length <= 1e-6 ||
                b.Length <= 1e-6)
            {
                return 0.0;
            }

            Vector3d an =
                a.GetNormal();

            Vector3d bn =
                b.GetNormal();

            double dot =
                Math.Max(
                    -1.0,
                    Math.Min(
                        1.0,
                        an.DotProduct(
                            bn)));

            return
                Math.Acos(
                    dot) *
                180.0 /
                Math.PI;
        }

        private bool AppendReview3DRealElbow(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DPipeData pipe,
            int jointIndex,
            double elevation)
        {
            if (pipe == null ||
                pipe.Points == null ||
                jointIndex <= 0 ||
                jointIndex >=
                    pipe.Points.Count - 1)
            {
                return false;
            }

            Point3d prev =
                pipe.Points[jointIndex - 1];

            Point3d joint =
                pipe.Points[jointIndex];

            Point3d next =
                pipe.Points[jointIndex + 1];

            Vector3d d1 =
                new Vector3d(
                    prev.X - joint.X,
                    prev.Y - joint.Y,
                    0.0);

            Vector3d d2 =
                new Vector3d(
                    next.X - joint.X,
                    next.Y - joint.Y,
                    0.0);

            if (d1.Length <= 1e-6 ||
                d2.Length <= 1e-6)
            {
                return false;
            }

            d1 =
                d1.GetNormal();

            d2 =
                d2.GetNormal();

            double thetaDeg =
                GetReview3DAngleDeg(
                    d1,
                    d2);

            if (thetaDeg <
                    Review3DElbowMinAngleDeg ||
                thetaDeg >
                    Review3DElbowMaxAngleDeg)
            {
                return false;
            }

            double theta =
                thetaDeg *
                Math.PI /
                180.0;

            double diameter =
                Math.Max(
                    pipe.Width,
                    Review3DMinimumVisualSize);

            double centerRadius =
                Math.Max(
                    diameter *
                    Review3DElbowRadiusRatio,
                    Review3DElbowMinCenterRadius);

            double tanHalf =
                Math.Tan(
                    theta * 0.5);

            if (Math.Abs(
                    tanHalf) <= 1e-6)
            {
                return false;
            }

            double tangent =
                centerRadius /
                tanHalf;

            tangent =
                Math.Min(
                    tangent,
                    PlanDistance(
                        prev,
                        joint) * 0.42);

            tangent =
                Math.Min(
                    tangent,
                    PlanDistance(
                        joint,
                        next) * 0.42);

            if (tangent <= 1e-6)
                return false;

            Point3d j3 =
                new Point3d(
                    joint.X,
                    joint.Y,
                    elevation);

            Point3d p1 =
                j3 +
                d1 * tangent;

            Point3d p2 =
                j3 +
                d2 * tangent;

            Vector3d bisector =
                d1 + d2;

            if (bisector.Length <= 1e-6)
                return false;

            bisector =
                bisector.GetNormal();

            double sinHalf =
                Math.Sin(
                    theta * 0.5);

            if (Math.Abs(
                    sinHalf) <= 1e-6)
            {
                return false;
            }

            // Khi tangent bị giới hạn bởi đoạn ngắn, radius thực cũng giảm theo.
            double actualRadius =
                tangent *
                tanHalf;

            double centerDistance =
                actualRadius /
                sinHalf;

            Point3d center =
                j3 +
                bisector *
                centerDistance;

            return
                AppendReview3DArcElbowSolid(
                    tr,
                    db,
                    space,
                    center,
                    p1,
                    p2,
                    diameter);
        }

        private bool AppendReview3DNodeElbow(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Point3d node,
            Review3DFittingConnection a,
            Review3DFittingConnection b)
        {
            if (a == null ||
                b == null)
            {
                return false;
            }

            // Co sweep hiện tại chỉ xử lý hai nhánh cùng mặt phẳng ngang.
            if (Math.Abs(
                    a.Direction.Z) > 0.1 ||
                Math.Abs(
                    b.Direction.Z) > 0.1)
            {
                return false;
            }

            Vector3d d1 =
                a.Direction.GetNormal();

            Vector3d d2 =
                b.Direction.GetNormal();

            double thetaDeg =
                GetReview3DAngleDeg(
                    d1,
                    d2);

            if (thetaDeg <
                    Review3DElbowMinAngleDeg ||
                thetaDeg >
                    Review3DElbowMaxAngleDeg)
            {
                return false;
            }

            double diameter =
                Math.Max(
                    a.Diameter,
                    b.Diameter);

            double theta =
                thetaDeg *
                Math.PI /
                180.0;

            double centerRadius =
                Math.Max(
                    diameter *
                    Review3DElbowRadiusRatio,
                    Review3DElbowMinCenterRadius);

            double tangent =
                centerRadius /
                Math.Max(
                    Math.Tan(
                        theta * 0.5),
                    1e-6);

            tangent =
                Math.Min(
                    tangent,
                    diameter * 2.5);

            Point3d p1 =
                node +
                d1 * tangent;

            Point3d p2 =
                node +
                d2 * tangent;

            Vector3d bisector =
                d1 + d2;

            if (bisector.Length <= 1e-6)
                return false;

            bisector =
                bisector.GetNormal();

            double actualRadius =
                tangent *
                Math.Tan(
                    theta * 0.5);

            double centerDistance =
                actualRadius /
                Math.Max(
                    Math.Sin(
                        theta * 0.5),
                    1e-6);

            Point3d center =
                node +
                bisector *
                centerDistance;

            return
                AppendReview3DArcElbowSolid(
                    tr,
                    db,
                    space,
                    center,
                    p1,
                    p2,
                    diameter);
        }

        private bool AppendReview3DArcElbowSolid(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Point3d center,
            Point3d p1,
            Point3d p2,
            double diameter)
        {
            Vector3d r1 =
                p1 - center;

            Vector3d r2 =
                p2 - center;

            if (r1.Length <= 1e-6 ||
                r2.Length <= 1e-6)
            {
                return false;
            }

            double radius =
                (r1.Length +
                 r2.Length) * 0.5;

            double startAngle =
                Math.Atan2(
                    r1.Y,
                    r1.X);

            double endAngle =
                Math.Atan2(
                    r2.Y,
                    r2.X);

            double signed =
                Math.Atan2(
                    r1.X * r2.Y -
                    r1.Y * r2.X,
                    r1.X * r2.X +
                    r1.Y * r2.Y);

            // Arc luôn chạy CCW theo +Z.
            // Nếu góc ký hiệu âm thì đảo hai đầu để lấy cung ngắn.
            if (signed < 0.0)
            {
                Point3d tmpP =
                    p1;
                p1 =
                    p2;
                p2 =
                    tmpP;

                Vector3d tmpR =
                    r1;
                r1 =
                    r2;
                r2 =
                    tmpR;

                startAngle =
                    Math.Atan2(
                        r1.Y,
                        r1.X);

                endAngle =
                    Math.Atan2(
                        r2.Y,
                        r2.X);
            }

            while (endAngle <=
                startAngle)
            {
                endAngle +=
                    Math.PI * 2.0;
            }

            if (endAngle -
                startAngle >
                Math.PI)
            {
                // Sau khi đảo mà vẫn > 180° thì không dùng sweep co.
                return false;
            }

            Arc path =
                new Arc(
                    center,
                    Vector3d.ZAxis,
                    radius,
                    startAngle,
                    endAngle);

            Circle profile =
                new Circle(
                    Point3d.Origin,
                    Vector3d.ZAxis,
                    Math.Max(
                        diameter,
                        Review3DMinimumVisualSize) *
                    0.5);

            DBObjectCollection curves =
                new DBObjectCollection();

            DBObjectCollection regions =
                null;

            Solid3d solid =
                null;

            try
            {
                Vector3d radial =
                    path.StartPoint -
                    center;

                Vector3d tangent =
                    Vector3d.ZAxis
                        .CrossProduct(
                            radial)
                        .GetNormal();

                profile.TransformBy(
                    BuildReview3DProfileTransform(
                        path.StartPoint,
                        tangent));

                curves.Add(
                    profile);

                regions =
                    Autodesk.AutoCAD.DatabaseServices.Region
                        .CreateFromCurves(
                            curves);

                if (regions == null ||
                    regions.Count == 0)
                {
                    return false;
                }

                Autodesk.AutoCAD.DatabaseServices.Region region =
                    regions[0] as Autodesk.AutoCAD.DatabaseServices.Region;

                if (region == null)
                    return false;

                SweepOptionsBuilder builder =
                    new SweepOptionsBuilder();

                builder.Align =
                    SweepOptionsAlignOption
                        .AlignSweepEntityToPath;
                builder.AlignStart = true;
                builder.BasePoint =
                    path.StartPoint;
                builder.CheckIntersections =
                    false;

                solid =
                    new Solid3d();

                solid.RecordHistory =
                    false;

                solid.CreateSweptSolid(
                    region,
                    path,
                    builder.ToSweepOptions());

                solid.SetDatabaseDefaults(db);
                solid.Layer =
                    Review3DFittingSolidLayer;
                solid.ColorIndex = 256;

                space.AppendEntity(
                    solid);

                tr.AddNewlyCreatedDBObject(
                    solid,
                    true);

                region.Dispose();

                for (int i = 1;
                    i < regions.Count;
                    i++)
                {
                    if (regions[i] is IDisposable d)
                        d.Dispose();
                }

                path.Dispose();
                profile.Dispose();

                return true;
            }
            catch
            {
                if (solid != null)
                    solid.Dispose();

                try
                {
                    path.Dispose();
                }
                catch
                {
                }

                try
                {
                    profile.Dispose();
                }
                catch
                {
                }

                if (regions != null)
                {
                    foreach (object obj
                        in regions)
                    {
                        if (obj is IDisposable d)
                        {
                            try
                            {
                                d.Dispose();
                            }
                            catch
                            {
                            }
                        }
                    }
                }

                return false;
            }
        }

        private bool AppendReview3DReducerFitting(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Point3d node,
            Review3DFittingConnection a,
            Review3DFittingConnection b)
        {
            if (a == null ||
                b == null)
            {
                return false;
            }

            Review3DFittingConnection large =
                a.Diameter >= b.Diameter
                    ? a
                    : b;

            Review3DFittingConnection small =
                ReferenceEquals(
                    large,
                    a)
                    ? b
                    : a;

            double largeD =
                Math.Max(
                    large.Diameter,
                    Review3DMinimumVisualSize);

            double smallD =
                Math.Max(
                    small.Diameter,
                    Review3DMinimumVisualSize);

            // Reducer kéo dài và thuôn hơn.
            double length =
                Math.Max(
                    Review3DReducerMinLength * 1.4,
                    largeD * 3.2);

            Point3d start =
                node +
                large.Direction.GetNormal() *
                (length * 0.5);

            Point3d end =
                node +
                small.Direction.GetNormal() *
                (length * 0.5);

            Vector3d axis =
                end - start;

            if (axis.Length <= 1e-6)
                return false;

            Solid3d reducer =
                new Solid3d();

            try
            {
                reducer.CreateFrustum(
                    axis.Length,
                    largeD * 0.5,
                    largeD * 0.5,
                    smallD * 0.5);

                Matrix3d transform =
                    BuildReview3DProfileTransform(
                        start,
                        axis);

                reducer.TransformBy(
                    transform);

                reducer.SetDatabaseDefaults(db);
                reducer.Layer =
                    Review3DFittingSolidLayer;
                reducer.ColorIndex = 256;

                space.AppendEntity(
                    reducer);

                tr.AddNewlyCreatedDBObject(
                    reducer,
                    true);

                return true;
            }
            catch
            {
                reducer.Dispose();
                return false;
            }
        }

        private bool AppendReview3DCouplingFitting(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Point3d node,
            Review3DFittingConnection a,
            Review3DFittingConnection b)
        {
            if (a == null ||
                b == null)
            {
                return false;
            }

            double diameter =
                Math.Max(
                    Math.Max(
                        a.Diameter,
                        b.Diameter),
                    Review3DMinimumVisualSize);

            double outerDiameter =
                diameter *
                Review3DFittingDiameterScale;

            double length =
                Math.Max(
                    diameter *
                    Review3DFittingSleeveLengthRatio,
                    70.0);

            Point3d start =
                node +
                a.Direction.GetNormal() *
                (length * 0.5);

            Point3d end =
                node +
                b.Direction.GetNormal() *
                (length * 0.5);

            if (start.DistanceTo(
                    end) <= 1e-6)
            {
                return false;
            }

            AppendReview3DRoundSolidSegment(
                tr,
                db,
                space,
                start,
                end,
                outerDiameter,
                Review3DFittingSolidLayer);

            return true;
        }

        private bool AppendReview3DTeeFitting(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Point3d node,
            List<Review3DFittingConnection> connections)
        {
            if (connections == null ||
                connections.Count < 3)
            {
                return false;
            }

            double maxDiameter =
                connections
                    .Max(
                        c =>
                            Math.Max(
                                c.Diameter,
                                Review3DMinimumVisualSize));

            double bodyDiameter =
                maxDiameter *
                1.02;

            double legLength =
                Math.Max(
                    maxDiameter *
                    0.75,
                    70.0);

            int created =
                0;

            foreach (Review3DFittingConnection c
                in connections)
            {
                if (c == null ||
                    c.Direction.Length <= 1e-6)
                {
                    continue;
                }

                Point3d end =
                    node +
                    c.Direction.GetNormal() *
                    legLength;

                AppendReview3DRoundSolidSegment(
                    tr,
                    db,
                    space,
                    node,
                    end,
                    Math.Max(
                        c.Diameter *
                        1.03,
                        bodyDiameter * 0.78),
                    Review3DFittingSolidLayer);

                created++;
            }

            // Một hub tròn nhỏ tại tâm để các sleeve giao nhau kín.
            Solid3d hub =
                new Solid3d();

            try
            {
                hub.CreateSphere(
                    bodyDiameter * 0.34);

                hub.TransformBy(
                    Matrix3d.Displacement(
                        node -
                        Point3d.Origin));

                hub.SetDatabaseDefaults(db);
                hub.Layer =
                    Review3DFittingSolidLayer;
                hub.ColorIndex = 256;

                space.AppendEntity(
                    hub);

                tr.AddNewlyCreatedDBObject(
                    hub,
                    true);

                created++;
            }
            catch
            {
                hub.Dispose();
            }

            return
                created >= 3;
        }

        private static void AppendReview3DJointSphereUnique(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            List<Point3d> placed,
            Point3d center,
            double radius)
        {
            if (radius <= 1e-6)
                return;

            if (placed != null)
            {
                foreach (Point3d existing
                    in placed)
                {
                    if (existing.DistanceTo(
                            center) <=
                        Review3DJoinTolerance * 0.35)
                    {
                        return;
                    }
                }
            }

            Solid3d sphere =
                new Solid3d();

            try
            {
                sphere.CreateSphere(
                    radius);

                sphere.TransformBy(
                    Matrix3d.Displacement(
                        center -
                        Point3d.Origin));

                sphere.SetDatabaseDefaults(db);
                sphere.Layer =
                    Review3DFittingSolidLayer;
                sphere.ColorIndex = 256;

                space.AppendEntity(
                    sphere);

                tr.AddNewlyCreatedDBObject(
                    sphere,
                    true);

                placed?.Add(
                    center);
            }
            catch
            {
                sphere.Dispose();
            }
        }

        private void AppendReview3DPipeSizeLabel(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DPipeData pipe,
            double elevation)
        {
            if (pipe == null ||
                pipe.ProfileKind !=
                    Review3DProfileKind.PipeRound ||
                pipe.Points == null ||
                pipe.Points.Count < 2)
            {
                return;
            }

            string label =
                NormalizeReview3DSizeLabel(
                    pipe.DisplayLabel);

            if (string.IsNullOrWhiteSpace(
                    label))
            {
                return;
            }

            int segIndex =
                0;

            double bestLen =
                -1.0;

            for (int i = 0;
                i < pipe.Points.Count - 1;
                i++)
            {
                double len =
                    PlanDistance(
                        pipe.Points[i],
                        pipe.Points[i + 1]);

                if (len > bestLen)
                {
                    bestLen = len;
                    segIndex = i;
                }
            }

            Point3d a =
                pipe.Points[segIndex];
            Point3d b =
                pipe.Points[segIndex + 1];

            Point3d mid =
                new Point3d(
                    (a.X + b.X) * 0.5,
                    (a.Y + b.Y) * 0.5,
                    elevation +
                    Math.Max(
                        pipe.Width * 0.5 +
                        Review3DLabelOffset,
                        Review3DLabelOffset));

            double angle =
                Math.Atan2(
                    b.Y - a.Y,
                    b.X - a.X);

            AppendReview3DLabelText(
                tr,
                db,
                space,
                mid,
                label,
                angle);
        }

        private void AppendReview3DRiserSizeLabel(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DRiserData riser,
            double elevation)
        {
            if (riser == null ||
                riser.ProfileKind !=
                    Review3DProfileKind.PipeRound)
            {
                return;
            }

            string label =
                NormalizeReview3DSizeLabel(
                    riser.DisplayLabel);

            if (string.IsNullOrWhiteSpace(
                    label))
            {
                return;
            }

            bool isDown =
                string.Equals(
                    (riser.Direction ?? "")
                        .Trim(),
                    "DOWN",
                    StringComparison.OrdinalIgnoreCase);

            double topZ =
                elevation +
                (isDown ? -1.0 : 1.0) *
                Math.Max(
                    riser.HeightMeters,
                    0.0) * 1000.0;

            Point3d p =
                new Point3d(
                    riser.BasePoint.X +
                    Math.Max(
                        riser.Width * 0.8,
                        120.0),
                    riser.BasePoint.Y,
                    (elevation + topZ) * 0.5);

            AppendReview3DLabelText(
                tr,
                db,
                space,
                p,
                label,
                0.0);
        }

        private static string NormalizeReview3DSizeLabel(
            string raw)
        {
            if (string.IsNullOrWhiteSpace(
                    raw))
            {
                return "";
            }

            string s =
                raw.Trim()
                    .ToUpperInvariant();

            if (s.StartsWith(
                    "DN"))
            {
                Match m =
                    Regex.Match(
                        s,
                        @"DN\s*(\d+(?:\.\d+)?)",
                        RegexOptions.IgnoreCase);

                if (m.Success)
                {
                    return
                        "DN" +
                        m.Groups[1].Value;
                }

                return s;
            }

            return "";
        }

        private static void AppendReview3DLabelText(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Point3d position,
            string textValue,
            double rotation)
        {
            if (string.IsNullOrWhiteSpace(
                    textValue))
            {
                return;
            }

            DBText text =
                new DBText();

            text.SetDatabaseDefaults(db);
            text.TextStyleId =
                db.Textstyle;
            text.TextString =
                textValue;
            text.Height =
                Review3DLabelTextHeight;
            text.WidthFactor =
                0.9;
            text.Layer =
                Review3DLabelLayer;
            text.ColorIndex =
                256;
            text.Position =
                position;
            text.Rotation =
                rotation;

            space.AppendEntity(
                text);

            tr.AddNewlyCreatedDBObject(
                text,
                true);
        }

        private static void AppendReview3DErrorMarker(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DErrorData error)
        {
            if (error == null)
                return;

            Point3d p =
                error.Point;

            double s =
                Review3DErrorMarkerSize;

            AppendReview3DMarkerLine(
                tr,
                db,
                space,
                new Point3d(
                    p.X - s,
                    p.Y,
                    p.Z),
                new Point3d(
                    p.X + s,
                    p.Y,
                    p.Z));

            AppendReview3DMarkerLine(
                tr,
                db,
                space,
                new Point3d(
                    p.X,
                    p.Y - s,
                    p.Z),
                new Point3d(
                    p.X,
                    p.Y + s,
                    p.Z));

            AppendReview3DMarkerLine(
                tr,
                db,
                space,
                new Point3d(
                    p.X,
                    p.Y,
                    p.Z - s),
                new Point3d(
                    p.X,
                    p.Y,
                    p.Z + s));

            DBText text =
                new DBText();

            text.SetDatabaseDefaults(db);
            text.TextStyleId =
                db.Textstyle;
            text.TextString =
                string.IsNullOrWhiteSpace(
                    error.Text)
                    ? "HỞ"
                    : error.Text;
            text.Height =
                Review3DErrorTextHeight;
            text.WidthFactor = 1.0;
            text.Layer =
                Review3DErrorLayer;
            text.ColorIndex = 256;
            text.Position =
                new Point3d(
                    p.X + s * 1.15,
                    p.Y + s * 1.15,
                    p.Z);

            space.AppendEntity(text);
            tr.AddNewlyCreatedDBObject(
                text,
                true);
        }

        private static void AppendReview3DPrettyErrorMarker(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Review3DErrorData error)
        {
            if (error == null)
                return;

            Point3d p =
                error.Point;

            double radius =
                Review3DErrorMarkerSize * 0.42;

            // Quả cầu đỏ 3D: nhìn thấy rõ từ mọi góc.
            Solid3d markerSphere =
                new Solid3d();

            try
            {
                markerSphere.CreateSphere(
                    radius);

                markerSphere.TransformBy(
                    Matrix3d.Displacement(
                        p -
                        Point3d.Origin));

                markerSphere.SetDatabaseDefaults(db);
                markerSphere.Layer =
                    Review3DErrorLayer;
                markerSphere.ColorIndex = 256;

                space.AppendEntity(
                    markerSphere);

                tr.AddNewlyCreatedDBObject(
                    markerSphere,
                    true);
            }
            catch
            {
                markerSphere.Dispose();
            }

            // Vòng tròn mảnh để vẫn nhận ra điểm lỗi khi visual style đổi.
            Circle ring =
                new Circle(
                    p,
                    Vector3d.ZAxis,
                    radius * 1.35);

            ring.SetDatabaseDefaults(db);
            ring.Layer =
                Review3DErrorLayer;
            ring.ColorIndex = 256;

            space.AppendEntity(ring);
            tr.AddNewlyCreatedDBObject(
                ring,
                true);

            DBText label =
                new DBText();

            label.SetDatabaseDefaults(db);
            label.TextStyleId =
                db.Textstyle;
            label.TextString =
                string.IsNullOrWhiteSpace(
                    error.Text)
                    ? "HỞ"
                    : error.Text;
            label.Height =
                Review3DErrorTextHeight * 0.78;
            label.WidthFactor = 1.0;
            label.Layer =
                Review3DErrorLayer;
            label.ColorIndex = 256;
            label.Position =
                new Point3d(
                    p.X + radius * 1.65,
                    p.Y + radius * 1.05,
                    p.Z + radius * 0.55);

            space.AppendEntity(label);
            tr.AddNewlyCreatedDBObject(
                label,
                true);
        }

        private static void AppendReview3DMarkerLine(
            Transaction tr,
            Database db,
            BlockTableRecord space,
            Point3d a,
            Point3d b)
        {
            Line line =
                new Line(
                    a,
                    b);

            line.SetDatabaseDefaults(db);
            line.Layer =
                Review3DErrorLayer;
            line.ColorIndex = 256;

            space.AppendEntity(line);
            tr.AddNewlyCreatedDBObject(
                line,
                true);
        }

        private void MergeReview3DSolidsLikeRevit(
            Transaction tr,
            Database db)
        {
            if (tr == null ||
                db == null)
            {
                return;
            }

            List<ObjectId> solids =
                CollectReview3DMergeCandidateIds(
                    tr,
                    db);

            if (solids.Count <= 1)
                return;

            bool mergedSomething =
                true;

            while (mergedSomething)
            {
                mergedSomething =
                    false;

                for (int i = 0;
                    i < solids.Count;
                    i++)
                {
                    if (!TryGetReview3DSolidExtents(
                            tr,
                            solids[i],
                            out Extents3d extA))
                    {
                        continue;
                    }

                    for (int j = i + 1;
                        j < solids.Count;
                        j++)
                    {
                        if (!TryGetReview3DSolidExtents(
                                tr,
                                solids[j],
                                out Extents3d extB))
                        {
                            continue;
                        }

                        if (!AreReview3DExtentsNear(
                                extA,
                                extB,
                                Review3DUnionSearchTolerance))
                        {
                            continue;
                        }

                        bool merged =
                            TryUniteReview3DSolidPair(
                                tr,
                                solids[i],
                                solids[j]);

                        if (!merged)
                            continue;

                        solids.RemoveAt(
                            j);

                        mergedSomething =
                            true;
                        break;
                    }

                    if (mergedSomething)
                        break;
                }
            }
        }

        private List<ObjectId> CollectReview3DMergeCandidateIds(
            Transaction tr,
            Database db)
        {
            List<ObjectId> ids =
                new List<ObjectId>();

            BlockTableRecord space =
                (BlockTableRecord)tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForRead);

            foreach (ObjectId id in space)
            {
                if (id.IsNull ||
                    !id.IsValid)
                {
                    continue;
                }

                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent == null ||
                    ent.IsErased ||
                    !(ent is Solid3d))
                {
                    continue;
                }

                if (!IsReview3DMergeCandidateLayer(
                        ent.Layer))
                {
                    continue;
                }

                ids.Add(
                    id);
            }

            return ids;
        }

        private static bool IsReview3DMergeCandidateLayer(
            string layerName)
        {
            if (string.IsNullOrWhiteSpace(
                    layerName))
            {
                return false;
            }

            return
                layerName.Equals(
                    Review3DPipeSolidLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DRiserSolidLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DFittingSolidLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layerName.Equals(
                    Review3DDuctSolidLayer,
                    StringComparison.OrdinalIgnoreCase);
        }

        private static bool TryGetReview3DSolidExtents(
            Transaction tr,
            ObjectId id,
            out Extents3d extents)
        {
            extents =
                default(Extents3d);

            if (id.IsNull ||
                !id.IsValid)
            {
                return false;
            }

            try
            {
                Solid3d solid =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Solid3d;

                if (solid == null ||
                    solid.IsErased)
                {
                    return false;
                }

                extents =
                    solid.GeometricExtents;

                return true;
            }
            catch
            {
                return false;
            }
        }

        private static bool AreReview3DExtentsNear(
            Extents3d a,
            Extents3d b,
            double tol)
        {
            return
                a.MinPoint.X <= b.MaxPoint.X + tol &&
                a.MaxPoint.X >= b.MinPoint.X - tol &&
                a.MinPoint.Y <= b.MaxPoint.Y + tol &&
                a.MaxPoint.Y >= b.MinPoint.Y - tol &&
                a.MinPoint.Z <= b.MaxPoint.Z + tol &&
                a.MaxPoint.Z >= b.MinPoint.Z - tol;
        }

        private bool TryUniteReview3DSolidPair(
            Transaction tr,
            ObjectId keeperId,
            ObjectId otherId)
        {
            if (keeperId.IsNull ||
                otherId.IsNull ||
                keeperId == otherId)
            {
                return false;
            }

            Solid3d keeper =
                tr.GetObject(
                    keeperId,
                    OpenMode.ForWrite,
                    false) as Solid3d;

            Solid3d other =
                tr.GetObject(
                    otherId,
                    OpenMode.ForWrite,
                    false) as Solid3d;

            if (keeper == null ||
                other == null ||
                keeper.IsErased ||
                other.IsErased)
            {
                return false;
            }

            try
            {
                if (!AreReview3DExtentsNear(
                        keeper.GeometricExtents,
                        other.GeometricExtents,
                        Review3DUnionBoundingTolerance))
                {
                    return false;
                }
            }
            catch
            {
            }

            Solid3d toolClone =
                null;

            try
            {
                toolClone =
                    other.Clone() as Solid3d;

                if (toolClone == null)
                    return false;

                keeper.BooleanOperation(
                    BooleanOperationType.BoolUnite,
                    toolClone);

                if (!other.IsErased)
                {
                    other.Erase();
                }

                if (string.Equals(
                        keeper.Layer,
                        Review3DFittingSolidLayer,
                        StringComparison.OrdinalIgnoreCase))
                {
                    keeper.Layer =
                        Review3DPipeSolidLayer;
                }

                return true;
            }
            catch
            {
                return false;
            }
            finally
            {
                if (toolClone != null)
                {
                    try
                    {
                        toolClone.Dispose();
                    }
                    catch
                    {
                    }
                }
            }
        }

        private void CaptureReview3DOriginalViewIfNeeded(
            Editor ed)
        {
            if (_review3DOriginalViewCaptured ||
                ed == null)
            {
                return;
            }

            try
            {
                using (ViewTableRecord view =
                    ed.GetCurrentView())
                {
                    _review3DOriginalTarget =
                        view.Target;
                    _review3DOriginalCenterPoint =
                        view.CenterPoint;
                    _review3DOriginalViewDirection =
                        view.ViewDirection;
                    _review3DOriginalViewTwist =
                        view.ViewTwist;
                    _review3DOriginalViewWidth =
                        view.Width;
                    _review3DOriginalViewHeight =
                        view.Height;
                }

                try
                {
                    object value =
                        Autodesk.AutoCAD.ApplicationServices.Application
                            .GetSystemVariable(
                                "VSCURRENT");

                    _review3DOriginalVisualStyle =
                        Convert.ToString(
                            value) ?? "";
                }
                catch
                {
                    _review3DOriginalVisualStyle =
                        "";
                }

                try
                {
                    _review3DOriginalFacetRes =
                        Convert.ToDouble(
                            Autodesk.AutoCAD.ApplicationServices.Application
                                .GetSystemVariable(
                                    "FACETRES"),
                            CultureInfo.InvariantCulture);
                }
                catch
                {
                }

                try
                {
                    _review3DOriginalIsoLines =
                        Convert.ToInt32(
                            Autodesk.AutoCAD.ApplicationServices.Application
                                .GetSystemVariable(
                                    "ISOLINES"),
                            CultureInfo.InvariantCulture);
                }
                catch
                {
                }

                try
                {
                    _review3DOriginalDispSilh =
                        Convert.ToInt32(
                            Autodesk.AutoCAD.ApplicationServices.Application
                                .GetSystemVariable(
                                    "DISPSILH"),
                            CultureInfo.InvariantCulture);
                }
                catch
                {
                }

                _review3DOriginalViewCaptured =
                    true;
            }
            catch
            {
                _review3DOriginalViewCaptured =
                    false;
            }
        }

        private void RestoreReview3DOriginalView(
            Editor ed)
        {
            if (!_review3DOriginalViewCaptured ||
                ed == null)
            {
                SetReview3DTopView(
                    ed);
                return;
            }

            try
            {
                if (!string.IsNullOrWhiteSpace(
                        _review3DOriginalVisualStyle))
                {
                    Autodesk.AutoCAD.ApplicationServices.Application
                        .SetSystemVariable(
                            "VSCURRENT",
                            _review3DOriginalVisualStyle);
                }
            }
            catch
            {
                try
                {
                    Autodesk.AutoCAD.ApplicationServices.Application
                        .SetSystemVariable(
                            "VSCURRENT",
                            "2D Wireframe");
                }
                catch
                {
                }
            }

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Application
                    .SetSystemVariable(
                        "FACETRES",
                        _review3DOriginalFacetRes);
            }
            catch
            {
            }

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Application
                    .SetSystemVariable(
                        "ISOLINES",
                        _review3DOriginalIsoLines);
            }
            catch
            {
            }

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Application
                    .SetSystemVariable(
                        "DISPSILH",
                        _review3DOriginalDispSilh);
            }
            catch
            {
            }

            try
            {
                using (ViewTableRecord view =
                    ed.GetCurrentView())
                {
                    view.Target =
                        _review3DOriginalTarget;
                    view.CenterPoint =
                        _review3DOriginalCenterPoint;
                    view.ViewDirection =
                        _review3DOriginalViewDirection;
                    view.ViewTwist =
                        _review3DOriginalViewTwist;
                    view.Width =
                        _review3DOriginalViewWidth;
                    view.Height =
                        _review3DOriginalViewHeight;

                    ed.SetCurrentView(
                        view);
                }
            }
            catch
            {
                SetReview3DTopView(
                    ed);
            }
        }

        private void ClearReview3DOriginalViewCapture()
        {
            _review3DOriginalViewCaptured =
                false;
            _review3DOriginalVisualStyle =
                "";
        }

        private static bool IsReview3DEscapePressed()
        {
            try
            {
                return
                    (GetAsyncKeyState(
                        Review3DVirtualKeyEscape) &
                     0x8000) != 0;
            }
            catch
            {
                return false;
            }
        }

        private void StartReview3DEscapeWatcher()
        {
            if (_review3DEscapeWatcherAttached)
                return;

            _review3DEscapeWasDown =
                IsReview3DEscapePressed();

            Autodesk.AutoCAD.ApplicationServices.Core.Application
                .Idle +=
                Review3DEscapeIdle;

            _review3DEscapeWatcherAttached =
                true;
        }

        private void StopReview3DEscapeWatcher()
        {
            if (!_review3DEscapeWatcherAttached)
                return;

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .Idle -=
                    Review3DEscapeIdle;
            }
            catch
            {
            }

            _review3DEscapeWatcherAttached =
                false;
            _review3DEscapeWasDown =
                false;
        }

        private void Review3DEscapeIdle(
            object sender,
            EventArgs e)
        {
            if (!_review3DEscapeWatcherAttached ||
                _review3DExitByEscapeInProgress ||
                _review3DIsIn2DFocus)
            {
                return;
            }

            bool down =
                IsReview3DEscapePressed();

            if (down &&
                !_review3DEscapeWasDown)
            {
                ExitReview3DByEscape();
            }

            _review3DEscapeWasDown =
                down;
        }

        private void ExitReview3DByEscape()
        {
            if (_review3DExitByEscapeInProgress)
                return;

            Document doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
            {
                StopReview3DEscapeWatcher();
                return;
            }

            Editor ed =
                doc.Editor;

            Database db =
                doc.Database;

            _review3DExitByEscapeInProgress =
                true;

            StopReview3DEscapeWatcher();

            try
            {
                // Trả lại toàn bộ object 2D đã bị ISOLATEOBJECTS ẩn.
                TryUnisolateReview3DObjects(
                    doc,
                    ed);

                try
                {
                    ed.SetImpliedSelection(
                        new ObjectId[0]);
                }
                catch
                {
                }

                using (doc.LockDocument())
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    DeleteReview2DFocusMarker(
                        tr,
                        db);

                    // ESC = thoát hẳn chế độ 3D, xóa preview tạm.
                    DeleteReview3DPreview(
                        tr,
                        db);

                    tr.Commit();
                }

                _review3DIsIn2DFocus =
                    false;

                // Trả đúng góc nhìn/zoom/visual style trước khi vào 3D.
                RestoreReview3DOriginalView(
                    ed);

                ed.Regen();

                ed.WriteMessage(
                    "\n[KIỂM TRA 3D] ESC: Đã thoát chế độ 3D và trở về bản vẽ 2D ban đầu.");

                ClearReview3DOriginalViewCapture();
            }
            catch
            {
                try
                {
                    RestoreReview3DOriginalView(
                        ed);
                    ed.Regen();
                }
                catch
                {
                }

                ClearReview3DOriginalViewCapture();
            }
            finally
            {
                _review3DExitByEscapeInProgress =
                    false;
            }
        }

        private bool TryFocusReview3DErrorIn2D(
            Document doc,
            Editor ed,
            Database db)
        {
            if (doc == null ||
                ed == null ||
                db == null)
            {
                return false;
            }

            PromptEntityOptions options =
                new PromptEntityOptions(
                    "\n[KIỂM TRA 3D] Click trực tiếp vào DẤU LỖI ĐỎ cần kiểm tra: ");

            options.AllowNone =
                false;

            PromptEntityResult result =
                ed.GetEntity(
                    options);

            if (result.Status !=
                PromptStatus.OK)
            {
                return false;
            }

            Point3d errorPoint =
                Point3d.Origin;

            string errorText =
                "VỊ TRÍ CẦN KIỂM TRA";

            bool valid =
                false;

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                Entity ent =
                    tr.GetObject(
                        result.ObjectId,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent == null ||
                    ent.IsErased ||
                    !string.Equals(
                        ent.Layer,
                        Review3DErrorLayer,
                        StringComparison.OrdinalIgnoreCase))
                {
                    MessageBox.Show(
                        "Đối tượng vừa chọn không phải marker lỗi 3D.\n\n" +
                        "Hãy click vào quả cầu / vòng / chữ màu đỏ của vị trí lỗi.",
                        "KIỂM TRA 3D");
                    return false;
                }

                if (ent is DBText dbText)
                {
                    errorPoint =
                        dbText.Position;

                    if (!string.IsNullOrWhiteSpace(
                            dbText.TextString))
                    {
                        errorText =
                            dbText.TextString;
                    }

                    valid =
                        true;
                }
                else if (ent is MText mt)
                {
                    errorPoint =
                        mt.Location;

                    if (!string.IsNullOrWhiteSpace(
                            mt.Contents))
                    {
                        errorText =
                            mt.Contents;
                    }

                    valid =
                        true;
                }
                else if (ent is Circle circle)
                {
                    errorPoint =
                        circle.Center;
                    valid =
                        true;
                }
                else if (ent is Line line)
                {
                    errorPoint =
                        new Point3d(
                            (line.StartPoint.X +
                             line.EndPoint.X) * 0.5,
                            (line.StartPoint.Y +
                             line.EndPoint.Y) * 0.5,
                            (line.StartPoint.Z +
                             line.EndPoint.Z) * 0.5);

                    valid =
                        true;
                }
                else
                {
                    try
                    {
                        Extents3d ex =
                            ent.GeometricExtents;

                        errorPoint =
                            new Point3d(
                                (ex.MinPoint.X +
                                 ex.MaxPoint.X) * 0.5,
                                (ex.MinPoint.Y +
                                 ex.MaxPoint.Y) * 0.5,
                                (ex.MinPoint.Z +
                                 ex.MaxPoint.Z) * 0.5);

                        valid =
                            true;
                    }
                    catch
                    {
                        valid =
                            false;
                    }
                }

                tr.Commit();
            }

            if (!valid)
            {
                MessageBox.Show(
                    "Không xác định được vị trí marker lỗi vừa chọn.",
                    "KIỂM TRA 3D");
                return false;
            }

            TryUnisolateReview3DObjects(
                doc,
                ed);

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                DeleteReview2DFocusMarker(
                    tr,
                    db);

                SetReview3DPreviewVisibility(
                    tr,
                    db,
                    false);

                EnsureLayerExists(
                    tr,
                    db,
                    Review2DFocusLayer,
                    false);

                SetReview3DLayerColor(
                    tr,
                    db,
                    Review2DFocusLayer,
                    1);

                AppendReview2DFocusMarker(
                    tr,
                    db,
                    errorPoint,
                    errorText);

                tr.Commit();
            }

            Point3d planPoint =
                new Point3d(
                    errorPoint.X,
                    errorPoint.Y,
                    0.0);

            ZoomToReview2DPoint(
                ed,
                planPoint);

            ed.Regen();

            ed.WriteMessage(
                "\n[KIỂM TRA 3D] Đã quay về mặt bằng đúng vị trí lỗi. " +
                "Bấm KIỂM TRA 3D > Quay3D để quay lại mô hình.");

            return true;
        }

        private static void SetReview3DPreviewVisibility(
            Transaction tr,
            Database db,
            bool visible)
        {
            if (tr == null ||
                db == null)
            {
                return;
            }

            BlockTableRecord space =
                (BlockTableRecord)tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForRead);

            foreach (ObjectId id in space)
            {
                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent == null ||
                    ent.IsErased ||
                    !IsReview3DTempLayer(
                        ent.Layer))
                {
                    continue;
                }

                ent.UpgradeOpen();
                ent.Visible =
                    visible;
            }
        }

        private static void DeleteReview2DFocusMarker(
            Transaction tr,
            Database db)
        {
            if (tr == null ||
                db == null)
            {
                return;
            }

            BlockTableRecord space =
                (BlockTableRecord)tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForRead);

            List<ObjectId> ids =
                new List<ObjectId>();

            foreach (ObjectId id in space)
            {
                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent != null &&
                    !ent.IsErased &&
                    string.Equals(
                        ent.Layer,
                        Review2DFocusLayer,
                        StringComparison.OrdinalIgnoreCase))
                {
                    ids.Add(
                        id);
                }
            }

            foreach (ObjectId id in ids)
            {
                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForWrite,
                        false) as Entity;

                if (ent != null &&
                    !ent.IsErased)
                {
                    ent.Erase();
                }
            }
        }

        private static void AppendReview2DFocusMarker(
            Transaction tr,
            Database db,
            Point3d sourcePoint,
            string errorText)
        {
            BlockTableRecord space =
                (BlockTableRecord)tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForWrite);

            Point3d p =
                new Point3d(
                    sourcePoint.X,
                    sourcePoint.Y,
                    0.0);

            double radius =
                Math.Max(
                    Review3DErrorMarkerSize * 2.0,
                    350.0);

            Circle circle =
                new Circle(
                    p,
                    Vector3d.ZAxis,
                    radius);

            circle.SetDatabaseDefaults(db);
            circle.Layer =
                Review2DFocusLayer;
            circle.ColorIndex =
                256;

            space.AppendEntity(
                circle);

            tr.AddNewlyCreatedDBObject(
                circle,
                true);

            Line cross1 =
                new Line(
                    new Point3d(
                        p.X - radius * 0.72,
                        p.Y - radius * 0.72,
                        0.0),
                    new Point3d(
                        p.X + radius * 0.72,
                        p.Y + radius * 0.72,
                        0.0));

            cross1.SetDatabaseDefaults(db);
            cross1.Layer =
                Review2DFocusLayer;
            cross1.ColorIndex =
                256;

            space.AppendEntity(
                cross1);

            tr.AddNewlyCreatedDBObject(
                cross1,
                true);

            Line cross2 =
                new Line(
                    new Point3d(
                        p.X - radius * 0.72,
                        p.Y + radius * 0.72,
                        0.0),
                    new Point3d(
                        p.X + radius * 0.72,
                        p.Y - radius * 0.72,
                        0.0));

            cross2.SetDatabaseDefaults(db);
            cross2.Layer =
                Review2DFocusLayer;
            cross2.ColorIndex =
                256;

            space.AppendEntity(
                cross2);

            tr.AddNewlyCreatedDBObject(
                cross2,
                true);

            DBText label =
                new DBText();

            label.SetDatabaseDefaults(db);
            label.TextStyleId =
                db.Textstyle;
            label.TextString =
                "KIỂM TRA: " +
                (string.IsNullOrWhiteSpace(
                    errorText)
                    ? "VỊ TRÍ NÀY"
                    : errorText);
            label.Height =
                Math.Max(
                    Review3DErrorTextHeight,
                    160.0);
            label.WidthFactor =
                1.0;
            label.Layer =
                Review2DFocusLayer;
            label.ColorIndex =
                256;
            label.Position =
                new Point3d(
                    p.X + radius * 1.15,
                    p.Y + radius * 0.65,
                    0.0);

            space.AppendEntity(
                label);

            tr.AddNewlyCreatedDBObject(
                label,
                true);
        }

        private static void ZoomToReview2DPoint(
            Editor ed,
            Point3d point)
        {
            if (ed == null)
                return;

            try
            {
                using (ViewTableRecord view =
                    ed.GetCurrentView())
                {
                    double oldHeight =
                        Math.Max(
                            view.Height,
                            1.0);

                    double oldWidth =
                        Math.Max(
                            view.Width,
                            oldHeight);

                    double aspect =
                        oldWidth /
                        oldHeight;

                    double targetHeight =
                        3000.0;

                    view.ViewDirection =
                        Vector3d.ZAxis;
                    view.ViewTwist =
                        0.0;
                    view.Target =
                        point;
                    view.CenterPoint =
                        Point2d.Origin;
                    view.Height =
                        targetHeight;
                    view.Width =
                        targetHeight *
                        aspect;

                    ed.SetCurrentView(
                        view);
                }
            }
            catch
            {
                SetReview3DTopView(
                    ed);
            }
        }

        private List<ObjectId> CollectReview3DPreviewIds(
            Database db)
        {
            List<ObjectId> ids =
                new List<ObjectId>();

            if (db == null)
                return ids;

            try
            {
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    BlockTableRecord space =
                        (BlockTableRecord)tr.GetObject(
                            db.CurrentSpaceId,
                            OpenMode.ForRead);

                    foreach (ObjectId id in space)
                    {
                        Entity ent =
                            tr.GetObject(
                                id,
                                OpenMode.ForRead,
                                false) as Entity;

                        if (ent != null &&
                            !ent.IsErased &&
                            IsReview3DTempLayer(
                                ent.Layer))
                        {
                            ids.Add(id);
                        }
                    }

                    tr.Commit();
                }
            }
            catch
            {
            }

            return ids;
        }

        private void TryIsolateReview3DPreview(
            Document doc,
            Editor ed,
            Database db)
        {
            if (doc == null ||
                ed == null ||
                db == null)
            {
                return;
            }

            try
            {
                List<ObjectId> previewIds =
                    CollectReview3DPreviewIds(
                        db);

                if (previewIds == null ||
                    previewIds.Count == 0)
                {
                    return;
                }

                ed.SetImpliedSelection(
                    previewIds.ToArray());

                doc.SendStringToExecute(
                    "._ISOLATEOBJECTS \n",
                    true,
                    false,
                    false);
            }
            catch
            {
            }
        }

        private static void TryUnisolateReview3DObjects(
            Document doc,
            Editor ed)
        {
            if (doc == null)
                return;

            try
            {
                if (ed != null)
                {
                    ed.SetImpliedSelection(
                        new ObjectId[0]);
                }

                doc.SendStringToExecute(
                    "._UNISOLATEOBJECTS \n",
                    true,
                    false,
                    false);
            }
            catch
            {
            }
        }

        private static void TryZoomExtents(
            Document doc)
        {
            if (doc == null)
                return;

            try
            {
                doc.SendStringToExecute(
                    "._ZOOM _E \n",
                    true,
                    false,
                    false);
            }
            catch
            {
            }
        }

        private static void SetReview3DIsometricView(
            Editor ed)
        {
            if (ed == null)
                return;

            try
            {
                using (ViewTableRecord view =
                    ed.GetCurrentView())
                {
                    view.ViewDirection =
                        new Vector3d(
                            1.0,
                            -1.0,
                            1.0);

                    view.ViewTwist = 0.0;

                    ed.SetCurrentView(
                        view);
                }
            }
            catch
            {
            }
        }

        private static void SetReview3DTopView(
            Editor ed)
        {
            if (ed == null)
                return;

            try
            {
                using (ViewTableRecord view =
                    ed.GetCurrentView())
                {
                    view.ViewDirection =
                        Vector3d.ZAxis;
                    view.ViewTwist = 0.0;
                    ed.SetCurrentView(
                        view);
                }
            }
            catch
            {
            }
        }

        private static void SetReview3DConceptualVisualStyle()
        {
            // Mục tiêu thật sự ở đây là ép AutoCAD hiển thị SOLID dạng SHADED,
            // không phải wireframe. Nếu chỉ đổi góc nhìn mà visual style vẫn
            // là 2D Wireframe thì Solid3d sẽ chỉ hiện thành các nét như ảnh user gửi.
            try
            {
                Autodesk.AutoCAD.ApplicationServices.Application
                    .SetSystemVariable(
                        "FACETRES",
                        10.0);
            }
            catch
            {
            }

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Application
                    .SetSystemVariable(
                        "ISOLINES",
                        0);
            }
            catch
            {
            }

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Application
                    .SetSystemVariable(
                        "DISPSILH",
                        0);
            }
            catch
            {
            }

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Application
                    .SetSystemVariable(
                        "VSCURRENT",
                        "Shaded");
            }
            catch
            {
                try
                {
                    Autodesk.AutoCAD.ApplicationServices.Application
                        .SetSystemVariable(
                            "SHADEMODE",
                            "Gouraud");
                }
                catch
                {
                }
            }

            try
            {
                var doc =
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .DocumentManager
                        .MdiActiveDocument;

                if (doc != null)
                {
                    // Gọi command trực tiếp để chắc chắn viewport chuyển sang SHADED,
                    // kể cả trường hợp SetSystemVariable không làm viewport cập nhật ngay.
                    doc.SendStringToExecute(
                        "._VSCURRENT _Shaded \n",
                        true,
                        false,
                        false);

                    doc.SendStringToExecute(
                        "._REGEN \n",
                        true,
                        false,
                        false);
                }
            }
            catch
            {
            }
        }


        private void BtnVeOng_Click(
            object sender,
            RoutedEventArgs e)
        {
            PipeUiContext ctx = GetContext(sender);

            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var db = doc.Database;

            string size = GetSelectedPipeSizeName(ctx);

            if (string.IsNullOrEmpty(size))
            {
                MessageBox.Show(
                    "Vui lòng chọn Size ống trước khi vẽ!",
                    "Cảnh báo");

                return;
            }

            double plineWidth = LayWidthTuSize(size);
            string layerName =
                $"{GetLayerPrefix(ctx)}_{CleanLayerText(size)}";
            bool isOngGio = CheckIsOngGio(ctx);

            using (doc.LockDocument())
            {
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .SetSystemVariable(
                        "PLINEWID",
                        plineWidth);

                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .SetSystemVariable(
                        "CECOLOR",
                        "BYLAYER");

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    EnsureLayerExists(
                        tr,
                        db,
                        layerName,
                        isOngGio);

                    LayerTable lt =
                        (LayerTable)tr.GetObject(
                            db.LayerTableId,
                            OpenMode.ForRead);

                    db.Clayer = lt[layerName];
                    tr.Commit();
                }
            }

            _currentLayerNameForText = layerName;
            _currentPlineWidth = plineWidth;
            _lastPlineId = ObjectId.Null;
            _pendingPlineIds.Clear();

            StartPlineTextWatcher(doc);

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            doc.SendStringToExecute(
                "._PLINE ",
                true,
                false,
                false);
        }

        private void BtnVeOng2_Click(
            object sender,
            RoutedEventArgs e)
        {
            PipeUiContext ctx = GetContext(sender);

            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var db = doc.Database;
            var ed = doc.Editor;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            // Chọn text trên bản vẽ để lấy kích thước
            PromptEntityOptions peo =
                new PromptEntityOptions(
                    "\n[VẼ ỐNG 2] Chọn text chứa kích thước ống " +
                    "(vd: PPR DN20, EAL 200x200 EI60): ")
                {
                    AllowNone = false
                };

            peo.SetRejectMessage("\nChỉ chọn TEXT hoặc MTEXT.");
            peo.AddAllowedClass(typeof(DBText), false);
            peo.AddAllowedClass(typeof(MText), false);

            PromptEntityResult per = ed.GetEntity(peo);

            if (per.Status != PromptStatus.OK)
            {
                ed.WriteMessage("\n[VẼ ỐNG 2] Đã hủy.");
                return;
            }

            string rawText = "";

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                Entity ent =
                    tr.GetObject(per.ObjectId, OpenMode.ForRead)
                        as Entity;

                if (ent is DBText dbText)
                    rawText = dbText.TextString ?? "";
                else if (ent is MText mText)
                    rawText = mText.Contents ?? mText.Text ?? "";

                tr.Commit();
            }

            // MText có thể chứa formatting codes
            rawText = Regex.Replace(
                rawText,
                @"\\[A-Za-z][^;]*;",
                " ");
            rawText = Regex.Replace(rawText, @"[{}]", " ");
            rawText = Regex.Replace(rawText, @"\s+", " ").Trim();

            if (string.IsNullOrWhiteSpace(rawText))
            {
                MessageBox.Show(
                    "Không đọc được nội dung text đã chọn!",
                    "Cảnh báo");
                return;
            }

            string size = ExtractSizeFromDrawingText(rawText);

            if (string.IsNullOrWhiteSpace(size))
            {
                MessageBox.Show(
                    $"Không nhận diện được kích thước ống từ text:\n\"{rawText}\"\n\n" +
                    "Ví dụ hợp lệ: PPR DN20, DN50, 200x200, EAL 500x200 EI60",
                    "Cảnh báo");
                return;
            }

            // Ghép CN/EI từ bảng UI nếu đang tích (không lấy từ text bản vẽ)
            size = AppendCnFromUiIfSelected(ctx, size);

            double plineWidth = LayWidthTuSize(size);
            string layerName =
                $"{GetLayerPrefix(ctx)}_{CleanLayerText(size)}";
            bool isOngGio = CheckIsOngGio(ctx) ||
                            size.IndexOf('x') >= 0 ||
                            size.IndexOf('X') >= 0;

            ed.WriteMessage(
                $"\n[VẼ ỐNG 2] Text: \"{rawText}\" → Size: {size}");
            ed.WriteMessage(
                $"\n[VẼ ỐNG 2] Layer: {layerName}");

            using (doc.LockDocument())
            {
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .SetSystemVariable("PLINEWID", plineWidth);

                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .SetSystemVariable("CECOLOR", "BYLAYER");

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    EnsureLayerExists(
                        tr,
                        db,
                        layerName,
                        isOngGio);

                    LayerTable lt =
                        (LayerTable)tr.GetObject(
                            db.LayerTableId,
                            OpenMode.ForRead);

                    db.Clayer = lt[layerName];
                    tr.Commit();
                }
            }

            _currentLayerNameForText = layerName;
            _currentPlineWidth = plineWidth;
            _lastPlineId = ObjectId.Null;
            _pendingPlineIds.Clear();

            StartPlineTextWatcher(doc);

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            doc.SendStringToExecute(
                "._PLINE ",
                true,
                false,
                false);
        }

        /// <summary>
        /// Lấy size từ text bản vẽ: DN20, 200x200, kèm EI/CN nếu có.
        /// </summary>
        private string ExtractSizeFromDrawingText(string sourceText)
        {
            if (string.IsNullOrWhiteSpace(sourceText))
                return "";

            string normalized =
                NormalizePipeLabel(sourceText)
                    .Replace(',', '.')
                    .ToUpperInvariant();

            // DN / D / Ø
            string sizePart = ExtractSizeOnlyText(sourceText);

            // Nếu ExtractSizeOnlyText rỗng, thử DN không khoảng
            if (string.IsNullOrWhiteSpace(sizePart))
            {
                Match dn =
                    Regex.Match(
                        normalized,
                        @"(?<![A-Z0-9])DN\s*(\d{1,4}(?:\.\d+)?)",
                        RegexOptions.IgnoreCase);

                if (dn.Success)
                    sizePart = "DN" + dn.Groups[1].Value;
            }

            // Ống gió: WxH
            if (string.IsNullOrWhiteSpace(sizePart))
            {
                Match rect =
                    Regex.Match(
                        normalized,
                        @"(?<!\d)(\d{2,4})\s*[xX×]\s*(\d{2,4})(?!\d)");

                if (rect.Success)
                    sizePart =
                        rect.Groups[1].Value + "x" +
                        rect.Groups[2].Value;
            }

            if (string.IsNullOrWhiteSpace(sizePart))
                return "";

            // Chỉ lấy kích thước (DN / WxH) — không lấy EI / CN
            sizePart = Regex.Replace(
                sizePart,
                @"\s+",
                "");

            return sizePart;
        }

        /// <summary>
        /// Nếu trên bảng đang tích CN (ống) hoặc CN/EI (ống gió)
        /// thì ghép vào size lấy từ bản vẽ.
        /// </summary>
        private string AppendCnFromUiIfSelected(
            PipeUiContext ctx,
            string size)
        {
            if (ctx == null || string.IsNullOrWhiteSpace(size))
                return size;

            // Đã có CN/EI trong size rồi thì thôi
            string upper = size.ToUpperInvariant();
            if (upper.Contains("_CN") ||
                upper.Contains("_EI") ||
                Regex.IsMatch(upper, @"(^|[^A-Z])CN\d") ||
                Regex.IsMatch(upper, @"(^|[^A-Z])EI\d"))
            {
                return size;
            }

            if (ctx.Suffix != "ACMV")
                return size;

            var chkOngGio =
                FindName("ChkNhomOngGioACMV") as System.Windows.Controls.CheckBox;
            bool isOngGioGroup = chkOngGio?.IsChecked == true;

            string cnPart = "";

            if (isOngGioGroup)
            {
                // Ống gió: dùng ChkDungCnEi + LstCnEiOngGioACMV
                cnPart = GetSelectedCnEi();
            }
            else
            {
                // Ống thường: dùng ChkDungCnOngACMV + LstCnOngACMV
                cnPart = GetSelectedCnOngAcmv();
            }

            if (string.IsNullOrWhiteSpace(cnPart))
                return size;

            return $"{size}_{cnPart.Trim()}";
        }

        private Polyline ConvertCurveToWidePolyline(
            Curve curve,
            string layerName,
            double width)
        {
            if (curve == null)
                return null;

            Polyline pline = new Polyline();
            pline.SetDatabaseDefaults();
            pline.Layer = layerName;
            pline.Color =
                Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                    ColorMethod.ByLayer,
                    256);
            pline.Linetype = "ByLayer";
            pline.LineWeight = Autodesk.AutoCAD.DatabaseServices.LineWeight.ByLayer;

            if (curve is Line line)
            {
                pline.AddVertexAt(
                    0,
                    new Point2d(line.StartPoint.X, line.StartPoint.Y),
                    0, width, width);
                pline.AddVertexAt(
                    1,
                    new Point2d(line.EndPoint.X, line.EndPoint.Y),
                    0, width, width);
            }
            else if (curve is Polyline sourcePline &&
                     sourcePline.NumberOfVertices >= 2)
            {
                for (int i = 0; i < sourcePline.NumberOfVertices; i++)
                {
                    Point2d pt = sourcePline.GetPoint2dAt(i);
                    double bulge = sourcePline.GetBulgeAt(i);
                    pline.AddVertexAt(i, pt, bulge, width, width);
                }

                pline.Closed = sourcePline.Closed;
            }
            else
            {
                // Fallback: lấy 2 điểm đầu-cuối
                try
                {
                    Point3d sp = curve.StartPoint;
                    Point3d ep = curve.EndPoint;

                    if (sp.DistanceTo(ep) < 0.001)
                        return null;

                    pline.AddVertexAt(
                        0,
                        new Point2d(sp.X, sp.Y),
                        0, width, width);
                    pline.AddVertexAt(
                        1,
                        new Point2d(ep.X, ep.Y),
                        0, width, width);
                }
                catch
                {
                    return null;
                }
            }

            pline.ConstantWidth = width;
            return pline;
        }

        private void BtnDoiLayer_Click(
            object sender,
            RoutedEventArgs e)
        {
            PipeUiContext ctx = GetContext(sender);

            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var db = doc.Database;
            var ed = doc.Editor;

            string size = GetSelectedPipeSizeName(ctx);

            if (string.IsNullOrEmpty(size))
            {
                MessageBox.Show(
                    "Vui lòng chọn Size ống trước khi thực hiện đổi Layer!",
                    "Cảnh báo");

                return;
            }

            double plineWidth = LayWidthTuSize(size);
            string layerName =
                $"{GetLayerPrefix(ctx)}_{CleanLayerText(size)}";
            string shortSizeLabel = GetShortSizeLabel(size);
            bool isOngGio = CheckIsOngGio(ctx);

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            PromptSelectionOptions pso =
                new PromptSelectionOptions();

            pso.MessageForAdding =
                $"\nQuét chọn các đối tượng để chuyển sang Layer [{layerName}]: ";

            PromptSelectionResult psr = ed.GetSelection(pso);

            if (psr.Status != PromptStatus.OK ||
                psr.Value.Count == 0)
            {
                return;
            }

            using (doc.LockDocument())
            {
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    EnsureLayerExists(
                        tr,
                        db,
                        layerName,
                        isOngGio);

                    BlockTableRecord btr =
                        (BlockTableRecord)tr.GetObject(
                            db.CurrentSpaceId,
                            OpenMode.ForWrite);

                    HashSet<ObjectId> selectedIds =
                        new HashSet<ObjectId>(
                            psr.Value
                                .Cast<SelectedObject>()
                                .Where(item =>
                                    item != null &&
                                    item.ObjectId != ObjectId.Null)
                                .Select(item => item.ObjectId));

                    Dictionary<ObjectId, string> selectedCurveLayers =
                        new Dictionary<ObjectId, string>();

                    HashSet<ObjectId> textIdsToUpdate =
                        new HashSet<ObjectId>();

                    // Danh sách polyline kết quả (sau convert) để tạo chữ
                    List<Polyline> resultPolylines =
                        new List<Polyline>();

                    int convertedLineCount = 0;
                    int updatedPlineCount = 0;

                    // --- Bước 1: phân loại + tìm chữ đi kèm ---
                    foreach (ObjectId id in selectedIds)
                    {
                        Entity selectedEntity =
                            tr.GetObject(
                                id,
                                OpenMode.ForRead,
                                false) as Entity;

                        if (selectedEntity is Curve)
                        {
                            selectedCurveLayers[id] =
                                selectedEntity.Layer;
                        }

                        if (selectedEntity is DBText ||
                            selectedEntity is MText)
                        {
                            textIdsToUpdate.Add(id);
                        }
                    }

                    foreach (ObjectId textId in
                        FindAssociatedPipeLabels(
                            tr,
                            selectedCurveLayers))
                    {
                        textIdsToUpdate.Add(textId);
                    }

                    // --- Bước 2: xử lý từng đối tượng đã chọn ---
                    foreach (ObjectId id in selectedIds)
                    {
                        Entity ent =
                            tr.GetObject(
                                id,
                                OpenMode.ForWrite,
                                false) as Entity;

                        if (ent == null)
                            continue;

                        // Text đã chọn → chỉ đổi layer + nội dung
                        if (ent is DBText || ent is MText)
                        {
                            ApplyLayerAndLabel(
                                ent,
                                layerName,
                                plineWidth,
                                shortSizeLabel);
                            continue;
                        }

                        // Polyline có sẵn → set layer + độ dày
                        if (ent is Polyline existingPline)
                        {
                            ApplyLayerAndLabel(
                                existingPline,
                                layerName,
                                plineWidth,
                                shortSizeLabel);

                            resultPolylines.Add(existingPline);
                            updatedPlineCount++;
                            continue;
                        }

                        // Line / Curve khác → chuyển thành Polyline có độ dày
                        if (ent is Curve curve)
                        {
                            Polyline newPline =
                                ConvertCurveToWidePolyline(
                                    curve,
                                    layerName,
                                    plineWidth);

                            if (newPline == null)
                            {
                                // Không convert được → chỉ đổi layer
                                ApplyLayerAndLabel(
                                    ent,
                                    layerName,
                                    plineWidth,
                                    shortSizeLabel);
                                continue;
                            }

                            btr.AppendEntity(newPline);
                            tr.AddNewlyCreatedDBObject(newPline, true);
                            resultPolylines.Add(newPline);

                            // Xóa Line/Curve cũ
                            ent.Erase();
                            convertedLineCount++;
                        }
                        else
                        {
                            ApplyLayerAndLabel(
                                ent,
                                layerName,
                                plineWidth,
                                shortSizeLabel);
                        }
                    }

                    // --- Bước 3: cập nhật chữ đi kèm (nếu có) ---
                    foreach (ObjectId textId in textIdsToUpdate)
                    {
                        if (selectedIds.Contains(textId))
                            continue;

                        Entity textEntity =
                            tr.GetObject(
                                textId,
                                OpenMode.ForWrite,
                                false) as Entity;

                        if (textEntity != null)
                        {
                            ApplyLayerAndLabel(
                                textEntity,
                                layerName,
                                plineWidth,
                                shortSizeLabel);
                        }
                    }

                    // --- Bước 4: luôn tạo chữ DN nếu chưa có chữ đi kèm ---
                    int createdLabelCount = 0;

                    bool hasExistingLabels =
                        textIdsToUpdate.Count > 0;

                    if (!hasExistingLabels)
                    {
                        foreach (Polyline pline in resultPolylines)
                        {
                            if (pline == null ||
                                pline.IsErased ||
                                !pline.ObjectId.IsValid)
                            {
                                continue;
                            }

                            DBText newLabel =
                                CreateAutomaticSizeLabel(
                                    db,
                                    pline,
                                    layerName,
                                    shortSizeLabel,
                                    plineWidth);

                            if (newLabel == null)
                                continue;

                            btr.AppendEntity(newLabel);
                            tr.AddNewlyCreatedDBObject(
                                newLabel,
                                true);

                            newLabel.AdjustAlignment(db);
                            createdLabelCount++;
                        }
                    }

                    tr.Commit();

                    ed.WriteMessage(
                        $"\n[{LayerChangeBuild}] Đã chuyển " +
                        $"{selectedIds.Count} đối tượng " +
                        $"(pline: {updatedPlineCount}, " +
                        $"line→pline: {convertedLineCount}), " +
                        $"cập nhật {textIdsToUpdate.Count} chữ, " +
                        $"tạo mới {createdLabelCount} chữ " +
                        $"→ Layer: {layerName}, Width: {plineWidth}");
                }

                ed.Regen();
            }
        }

        private HashSet<ObjectId> FindAssociatedPipeLabels(
            Transaction tr,
            Dictionary<ObjectId, string> selectedCurveLayers)
        {
            HashSet<ObjectId> result =
                new HashSet<ObjectId>();

            if (tr == null ||
                selectedCurveLayers == null ||
                selectedCurveLayers.Count == 0)
            {
                return result;
            }

            Dictionary<ObjectId, HashSet<ObjectId>>
                selectedCurvesByOwner =
                    new Dictionary<ObjectId, HashSet<ObjectId>>();

            foreach (KeyValuePair<ObjectId, string> pair
                in selectedCurveLayers)
            {
                Curve curve =
                    tr.GetObject(
                        pair.Key,
                        OpenMode.ForRead,
                        false) as Curve;

                if (curve == null)
                    continue;

                if (!selectedCurvesByOwner.TryGetValue(
                    curve.OwnerId,
                    out HashSet<ObjectId> ownerIds))
                {
                    ownerIds = new HashSet<ObjectId>();
                    selectedCurvesByOwner[curve.OwnerId] = ownerIds;
                }

                ownerIds.Add(pair.Key);
            }

            foreach (KeyValuePair<ObjectId, HashSet<ObjectId>>
                ownerPair in selectedCurvesByOwner)
            {
                BlockTableRecord owner =
                    tr.GetObject(
                        ownerPair.Key,
                        OpenMode.ForRead,
                        false) as BlockTableRecord;

                if (owner == null)
                    continue;

                HashSet<string> oldLayers =
                    new HashSet<string>(
                        ownerPair.Value
                            .Where(selectedCurveLayers.ContainsKey)
                            .Select(id => selectedCurveLayers[id]),
                        StringComparer.OrdinalIgnoreCase);

                Dictionary<string, List<Curve>> curvesByLayer =
                    new Dictionary<string, List<Curve>>(
                        StringComparer.OrdinalIgnoreCase);

                List<Curve> allCurves =
                    new List<Curve>();

                List<Entity> labelCandidates =
                    new List<Entity>();

                foreach (ObjectId id in owner)
                {
                    Entity entity =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (entity == null)
                        continue;

                    Curve curve = entity as Curve;

                    if (curve != null)
                    {
                        allCurves.Add(curve);

                        if (oldLayers.Contains(curve.Layer))
                        {
                            if (!curvesByLayer.TryGetValue(
                                curve.Layer,
                                out List<Curve> layerCurves))
                            {
                                layerCurves = new List<Curve>();
                                curvesByLayer[curve.Layer] = layerCurves;
                            }

                            layerCurves.Add(curve);
                        }

                        continue;
                    }

                    if (entity is DBText || entity is MText)
                        labelCandidates.Add(entity);
                }

                foreach (Entity label in labelCandidates)
                {
                    string oldLabelText = GetLabelText(label);

                    string matchingOldLayer =
                        oldLayers.FirstOrDefault(
                            oldLayer =>
                                AreSamePipeLabel(
                                    oldLabelText,
                                    oldLayer) ||
                                AreSamePipeLabel(
                                    label.Layer,
                                    oldLayer));

                    List<Curve> candidateCurves;

                    if (!string.IsNullOrWhiteSpace(
                            matchingOldLayer) &&
                        curvesByLayer.TryGetValue(
                            matchingOldLayer,
                            out List<Curve> matchingLayerCurves))
                    {
                        candidateCurves = matchingLayerCurves;
                    }
                    else if (
                        LooksLikePipeLabel(oldLabelText) ||
                        LooksLikePipeLabel(label.Layer))
                    {
                        candidateCurves = allCurves;
                    }
                    else
                    {
                        continue;
                    }

                    Point3d labelPoint = GetLabelPoint(label);
                    double labelRotation = GetLabelRotation(label);
                    Curve nearestCurve = null;
                    double nearestDistance = double.MaxValue;
                    double nearestScore = double.MaxValue;

                    foreach (Curve curve in candidateCurves)
                    {
                        try
                        {
                            Point3d closestPoint;

                            try
                            {
                                closestPoint =
                                    curve.GetClosestPointTo(
                                        labelPoint,
                                        Vector3d.ZAxis,
                                        false);
                            }
                            catch
                            {
                                closestPoint =
                                    curve.GetClosestPointTo(
                                        labelPoint,
                                        false);
                            }

                            double deltaX =
                                closestPoint.X - labelPoint.X;

                            double deltaY =
                                closestPoint.Y - labelPoint.Y;

                            double distance =
                                Math.Sqrt(
                                    (deltaX * deltaX) +
                                    (deltaY * deltaY));

                            // Chữ gắn với ống phải gần như song song.
                            if (!IsTextParallelToCurve(
                                curve,
                                closestPoint,
                                labelRotation))
                            {
                                continue;
                            }

                            double angleScore =
                                TinhGocLech(
                                    curve,
                                    closestPoint,
                                    labelRotation) * 2000.0;

                            double score = distance + angleScore;

                            if (score < nearestScore)
                            {
                                nearestScore = score;
                                nearestDistance = distance;
                                nearestCurve = curve;
                            }
                        }
                        catch
                        {
                            // Bỏ qua đường cong không xác định được điểm gần nhất.
                        }
                    }

                    if (nearestCurve == null ||
                        !ownerPair.Value.Contains(
                            nearestCurve.ObjectId))
                    {
                        continue;
                    }

                    if (nearestDistance <=
                        GetMaximumLabelDistance(
                            nearestCurve,
                            label))
                    {
                        result.Add(label.ObjectId);
                    }
                }
            }

            return result;
        }

        private bool LooksLikePipeLabel(string value)
        {
            string normalized = NormalizePipeLabel(value);

            return Regex.IsMatch(
                normalized,
                @"^(FF|ACMV|CTN)_",
                RegexOptions.IgnoreCase);
        }

        private double GetLabelRotation(Entity entity)
        {
            if (entity is DBText dbText)
                return dbText.Rotation;

            if (entity is MText mText)
                return mText.Rotation;

            return 0;
        }

        private bool AreSamePipeLabel(
            string first,
            string second)
        {
            return string.Equals(
                NormalizePipeLabel(first),
                NormalizePipeLabel(second),
                StringComparison.OrdinalIgnoreCase);
        }

        private string NormalizePipeLabel(string value)
        {
            string normalized =
                (value ?? "")
                    .Replace("\r", "")
                    .Replace("\n", "")
                    .Trim();

            return Regex.Replace(
                normalized,
                @"\s+",
                " ");
        }

        private string GetLabelText(Entity entity)
        {
            if (entity is DBText dbText)
                return (dbText.TextString ?? "").Trim();

            if (entity is MText mText)
            {
                return (mText.Text ?? "")
                    .Replace("\r", "")
                    .Replace("\n", "")
                    .Trim();
            }

            return "";
        }

        private Point3d GetLabelPoint(Entity entity)
        {
            if (entity is DBText dbText)
            {
                if (dbText.Justify != AttachmentPoint.BaseLeft &&
                    (dbText.AlignmentPoint.X != 0 ||
                     dbText.AlignmentPoint.Y != 0 ||
                     dbText.AlignmentPoint.Z != 0))
                {
                    return dbText.AlignmentPoint;
                }

                return dbText.Position;
            }

            if (entity is MText mText)
                return mText.Location;

            return Point3d.Origin;
        }

        private double GetMaximumLabelDistance(
            Curve curve,
            Entity label)
        {
            double curveWidth = 0;

            if (curve is Polyline polyline)
            {
                curveWidth = polyline.ConstantWidth;

                for (int index = 0;
                    index < polyline.NumberOfVertices;
                    index++)
                {
                    curveWidth = Math.Max(
                        curveWidth,
                        polyline.GetStartWidthAt(index));

                    curveWidth = Math.Max(
                        curveWidth,
                        polyline.GetEndWidthAt(index));
                }
            }

            double textHeight = 0;

            if (label is DBText dbText)
                textHeight = dbText.Height;
            else if (label is MText mText)
                textHeight = mText.TextHeight;

            return Math.Max(
                1500.0,
                (curveWidth / 2.0) +
                (textHeight * 6.0) +
                200.0);
        }

        private void SetPolylineWidth(Polyline polyline, double width)
        {
            if (polyline == null)
                return;

            polyline.ConstantWidth = width;

            for (int i = 0; i < polyline.NumberOfVertices; i++)
            {
                polyline.SetStartWidthAt(i, width);
                polyline.SetEndWidthAt(i, width);
            }
        }

        private string GetShortSizeLabel(string sizeOrLayer)
        {
            if (string.IsNullOrWhiteSpace(sizeOrLayer))
                return "";

            string source = sizeOrLayer.Trim();
            string sizePart = ExtractSizeOnlyText(source);

            // Fallback: phần sau _ cuối nếu chưa lấy được size
            if (string.IsNullOrWhiteSpace(sizePart) &&
                source.Contains("_"))
            {
                sizePart = source.Split('_').Last().Trim();
            }

            if (string.IsNullOrWhiteSpace(sizePart))
                sizePart = source;

            // Lấy CN / EI nếu có trong chuỗi (vd: DN20_CN25, ..._EI60)
            string upper = source.ToUpperInvariant();
            string cnEi = "";

            Match ei =
                Regex.Match(
                    upper,
                    @"(?<![A-Z0-9])EI\s*(\d{2,3})(?![A-Z0-9])");

            Match cn =
                Regex.Match(
                    upper,
                    @"(?<![A-Z0-9])CN\s*(\d{1,3})(?![A-Z0-9])");

            if (ei.Success)
                cnEi = "EI" + ei.Groups[1].Value;
            else if (cn.Success)
                cnEi = "CN" + cn.Groups[1].Value;

            if (!string.IsNullOrWhiteSpace(cnEi))
            {
                // Tránh lặp nếu sizePart đã chứa CN/EI
                string sizeUpper = sizePart.ToUpperInvariant();
                if (!sizeUpper.Contains(cnEi))
                    return $"{sizePart} {cnEi}";
            }

            return sizePart;
        }

        private void ApplyLayerAndLabel(
            Entity entity,
            string layerName,
            double plineWidth,
            string shortSizeLabel = null)
        {
            if (entity == null)
                return;

            entity.Layer = layerName;

            entity.Color =
                Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                    ColorMethod.ByLayer,
                    256);

            entity.Linetype = "ByLayer";
            entity.LineWeight = Autodesk.AutoCAD.DatabaseServices.LineWeight.ByLayer;

            double labelHeight =
                Math.Max(
                    plineWidth * LabelTextHeightToWidthRatio,
                    MinimumLabelTextHeight);

            if (entity is Polyline polyline)
            {
                SetPolylineWidth(polyline, plineWidth);
            }

            string displayText =
                !string.IsNullOrWhiteSpace(shortSizeLabel)
                    ? shortSizeLabel
                    : GetShortSizeLabel(layerName);

            if (entity is DBText dbText)
            {
                dbText.TextString = displayText;
                dbText.Height = labelHeight;

                if (dbText.Database != null)
                    dbText.AdjustAlignment(dbText.Database);
            }
            else if (entity is MText mText)
            {
                mText.Contents = displayText;
                mText.TextHeight = labelHeight;
            }
        }

        private bool TryGetClosestPointInPlan(
            Curve curve,
            Point3d sourcePoint,
            out Point3d closestPoint,
            out double planDistance)
        {
            closestPoint = Point3d.Origin;
            planDistance = double.MaxValue;

            if (curve == null)
                return false;

            try
            {
                try
                {
                    closestPoint =
                        curve.GetClosestPointTo(
                            sourcePoint,
                            Vector3d.ZAxis,
                            false);
                }
                catch
                {
                    Point3d flatPoint =
                        new Point3d(
                            sourcePoint.X,
                            sourcePoint.Y,
                            curve.StartPoint.Z);

                    closestPoint =
                        curve.GetClosestPointTo(
                            flatPoint,
                            false);
                }

                double deltaX =
                    closestPoint.X - sourcePoint.X;

                double deltaY =
                    closestPoint.Y - sourcePoint.Y;

                planDistance =
                    Math.Sqrt(
                        (deltaX * deltaX) +
                        (deltaY * deltaY));

                return true;
            }
            catch
            {
                return false;
            }
        }

        private void AddUniquePoint(
            List<Point3d> points,
            Point3d point,
            double tolerance = 1.0)
        {
            if (points == null)
                return;

            bool alreadyExists =
                points.Any(
                    existing =>
                    {
                        double deltaX =
                            existing.X - point.X;

                        double deltaY =
                            existing.Y - point.Y;

                        return Math.Sqrt(
                            (deltaX * deltaX) +
                            (deltaY * deltaY)) <= tolerance;
                    });

            if (!alreadyExists)
                points.Add(point);
        }

        private List<Point3d> GetCircularCentersFromBlock(
            Transaction tr,
            BlockReference blockReference)
        {
            List<Point3d> centers =
                new List<Point3d>();

            if (tr == null || blockReference == null)
                return centers;

            try
            {
                BlockTableRecord definition =
                    tr.GetObject(
                        blockReference.BlockTableRecord,
                        OpenMode.ForRead,
                        false) as BlockTableRecord;

                if (definition == null)
                    return centers;

                foreach (ObjectId entityId in definition)
                {
                    Circle circle =
                        tr.GetObject(
                            entityId,
                            OpenMode.ForRead,
                            false) as Circle;

                    if (circle == null)
                        continue;

                    Point3d worldCenter =
                        circle.Center.TransformBy(
                            blockReference.BlockTransform);

                    AddUniquePoint(
                        centers,
                        worldCenter,
                        5.0);
                }
            }
            catch
            {
                // Block không đọc được hình tròn thì bỏ qua nhận diện tâm.
            }

            return centers;
        }

        private Dictionary<Curve, List<SprinklerProjectionData>>
            MapSprinklerCentersToCurves(
                List<Curve> originalCurves,
                List<Point3d> sprinklerCenters)
        {
            Dictionary<Curve, List<SprinklerProjectionData>> result =
                new Dictionary<Curve, List<SprinklerProjectionData>>();

            foreach (Curve curve in originalCurves)
            {
                result[curve] =
                    new List<SprinklerProjectionData>();
            }

            foreach (Point3d center in sprinklerCenters)
            {
                Curve bestCurve = null;
                Point3d bestPoint = Point3d.Origin;
                double bestDistance = double.MaxValue;

                foreach (Curve curve in originalCurves)
                {
                    if (!TryGetClosestPointInPlan(
                        curve,
                        center,
                        out Point3d pointOnCurve,
                        out double planDistance))
                    {
                        continue;
                    }

                    if (planDistance < bestDistance)
                    {
                        bestDistance = planDistance;
                        bestCurve = curve;
                        bestPoint = pointOnCurve;
                    }
                }

                if (bestCurve == null ||
                    bestDistance > SprinklerCenterSearchDistance)
                {
                    continue;
                }

                bool duplicate =
                    result[bestCurve].Any(
                        item =>
                        {
                            double deltaX =
                                item.Center.X - center.X;

                            double deltaY =
                                item.Center.Y - center.Y;

                            return Math.Sqrt(
                                (deltaX * deltaX) +
                                (deltaY * deltaY)) <= 5.0;
                        });

                if (!duplicate)
                {
                    result[bestCurve].Add(
                        new SprinklerProjectionData
                        {
                            Center = center,
                            PointOnCurve = bestPoint,
                            PlanDistance = bestDistance
                        });
                }
            }

            return result;
        }

        private int CreateSprinklerCenterConnections(
            Transaction tr,
            Database db,
            BlockTableRecord targetSpace,
            List<SegmentData> allSegments,
            Dictionary<Curve, List<SprinklerProjectionData>>
                sprinklerProjections,
            bool isOngGio)
        {
            int createdCount = 0;

            if (tr == null ||
                db == null ||
                targetSpace == null ||
                allSegments == null ||
                sprinklerProjections == null)
            {
                return createdCount;
            }

            foreach (
                KeyValuePair<Curve, List<SprinklerProjectionData>>
                    pair in sprinklerProjections)
            {
                List<SegmentData> parentSegments =
                    allSegments
                        .Where(
                            segment =>
                                segment.OriginalParent == pair.Key &&
                                !string.IsNullOrWhiteSpace(
                                    segment.Layer))
                        .ToList();

                if (parentSegments.Count == 0)
                    continue;

                foreach (
                    SprinklerProjectionData projection
                    in pair.Value)
                {
                    if (projection.PlanDistance <= 1.0)
                        continue;

                    SegmentData nearestSegment = null;
                    double nearestDistance = double.MaxValue;

                    foreach (SegmentData segment in parentSegments)
                    {
                        if (!TryGetClosestPointInPlan(
                            segment.Curve,
                            projection.PointOnCurve,
                            out Point3d ignoredPoint,
                            out double planDistance))
                        {
                            continue;
                        }

                        if (planDistance < nearestDistance)
                        {
                            nearestDistance = planDistance;
                            nearestSegment = segment;
                        }
                    }

                    if (nearestSegment == null)
                        continue;

                    EnsureLayerExists(
                        tr,
                        db,
                        nearestSegment.Layer,
                        isOngGio);

                    Polyline connector = new Polyline();
                    connector.SetDatabaseDefaults(db);
                    connector.Layer = nearestSegment.Layer;

                    connector.Color =
                        Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                            ColorMethod.ByLayer,
                            256);

                    connector.Linetype = "ByLayer";
                    connector.LineWeight = Autodesk.AutoCAD.DatabaseServices.LineWeight.ByLayer;
                    connector.ConstantWidth = nearestSegment.Width;

                    connector.AddVertexAt(
                        0,
                        new Point2d(
                            projection.PointOnCurve.X,
                            projection.PointOnCurve.Y),
                        0,
                        nearestSegment.Width,
                        nearestSegment.Width);

                    connector.AddVertexAt(
                        1,
                        new Point2d(
                            projection.Center.X,
                            projection.Center.Y),
                        0,
                        nearestSegment.Width,
                        nearestSegment.Width);

                    targetSpace.AppendEntity(connector);
                    tr.AddNewlyCreatedDBObject(connector, true);
                    createdCount++;
                }
            }

            return createdCount;
        }

        private Dictionary<Curve, List<TextProjectionData>>
            MapTextsToOriginalCurves(
                List<Curve> originalCurves,
                List<TextData> texts)
        {
            Dictionary<Curve, List<TextProjectionData>> result =
                new Dictionary<Curve, List<TextProjectionData>>();

            foreach (Curve curve in originalCurves)
            {
                result[curve] =
                    new List<TextProjectionData>();
            }

            foreach (TextData text in texts)
            {
                Curve bestCurve = null;
                Point3d bestPoint = Point3d.Origin;
                double bestScore = double.MaxValue;

                foreach (Curve curve in originalCurves)
                {
                    if (!TryGetClosestPointInPlan(
                        curve,
                        text.Position,
                        out Point3d closestPoint,
                        out double planDistance))
                    {
                        continue;
                    }

                    if (planDistance > 3500.0)
                        continue;

                    // Bắt buộc chữ phải song song với ống.
                    // Chữ của nhánh vuông góc không được gán cho ống chính.
                    if (!IsTextParallelToCurve(
                        curve,
                        closestPoint,
                        text.Rotation))
                    {
                        continue;
                    }

                    double angleScore =
                        TinhGocLech(
                            curve,
                            closestPoint,
                            text.Rotation) * 5000.0;

                    double score =
                        planDistance + angleScore;

                    if (score < bestScore)
                    {
                        bestScore = score;
                        bestCurve = curve;
                        bestPoint = closestPoint;
                    }
                }

                if (bestCurve == null)
                    continue;

                try
                {
                    double distanceAlongCurve =
                        bestCurve.GetDistAtPoint(bestPoint);

                    result[bestCurve].Add(
                        new TextProjectionData
                        {
                            Text = text,
                            DistanceAlongCurve =
                                distanceAlongCurve,
                            MatchScore = bestScore
                        });
                }
                catch
                {
                    // Bỏ qua text không chiếu được lên chiều dài tuyến.
                }
            }

            foreach (Curve curve in originalCurves)
            {
                List<TextProjectionData> ordered =
                    result[curve]
                        .OrderBy(
                            item => item.DistanceAlongCurve)
                        .ThenBy(
                            item => item.MatchScore)
                        .ToList();

                List<TextProjectionData> filtered =
                    new List<TextProjectionData>();

                foreach (
                    TextProjectionData projection in ordered)
                {
                    TextProjectionData duplicate =
                        filtered.LastOrDefault(
                            item =>
                                Math.Abs(
                                    item.DistanceAlongCurve -
                                    projection.DistanceAlongCurve) <
                                10.0 &&
                                string.Equals(
                                    item.Text.LayerName,
                                    projection.Text.LayerName,
                                    StringComparison.OrdinalIgnoreCase));

                    if (duplicate == null)
                    {
                        filtered.Add(projection);
                    }
                    else if (
                        projection.MatchScore <
                        duplicate.MatchScore)
                    {
                        int duplicateIndex =
                            filtered.IndexOf(duplicate);

                        filtered[duplicateIndex] = projection;
                    }
                }

                result[curve] =
                    filtered
                        .OrderBy(
                            item => item.DistanceAlongCurve)
                        .ToList();
            }

            return result;
        }

        private List<double> GetTextSizeTransitionDistances(
            Curve curve,
            Dictionary<Curve, List<TextProjectionData>>
                projectionsByCurve,
            IEnumerable<double> preferredSplitDistances)
        {
            List<double> transitions =
                new List<double>();

            if (curve == null ||
                projectionsByCurve == null ||
                !projectionsByCurve.TryGetValue(
                    curve,
                    out List<TextProjectionData> projections) ||
                projections.Count < 2)
            {
                return transitions;
            }

            List<TextProjectionData> ordered =
                projections
                    .OrderBy(
                        item => item.DistanceAlongCurve)
                    .ToList();

            List<double> preferredDistances =
                (preferredSplitDistances ??
                 Enumerable.Empty<double>())
                    .OrderBy(distance => distance)
                    .ToList();

            double totalLength;

            try
            {
                totalLength =
                    curve.GetDistanceAtParameter(
                        curve.EndParam);
            }
            catch
            {
                return transitions;
            }

            for (int index = 0;
                index < ordered.Count - 1;
                index++)
            {
                TextProjectionData current = ordered[index];
                TextProjectionData next = ordered[index + 1];

                if (string.Equals(
                    current.Text.LayerName,
                    next.Text.LayerName,
                    StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (next.DistanceAlongCurve -
                    current.DistanceAlongCurve < 20.0)
                {
                    continue;
                }

                double middleDistance =
                    (current.DistanceAlongCurve +
                     next.DistanceAlongCurve) / 2.0;

                List<double> geometryCandidates =
                    preferredDistances
                        .Where(
                            distance =>
                                distance >
                                current.DistanceAlongCurve + 1.0 &&
                                distance <
                                next.DistanceAlongCurve - 1.0)
                        .ToList();

                double transitionDistance =
                    geometryCandidates.Count > 0
                        ? geometryCandidates
                            .OrderBy(
                                distance =>
                                    Math.Abs(
                                        distance -
                                        middleDistance))
                            .First()
                        : middleDistance;

                if (transitionDistance > 1.0 &&
                    transitionDistance < totalLength - 1.0)
                {
                    transitions.Add(transitionDistance);
                }
            }

            return transitions;
        }

        private string ExtractSizeOnlyText(string sourceText)
        {
            string normalized =
                NormalizePipeLabel(sourceText);

            Match nominalSize =
                Regex.Match(
                    normalized,
                    @"(?<![A-Z0-9])(?:DN|D|Ø|Φ)\s*\d{1,4}(?:[\.,]\d+)?(?:\s*MM)?(?![A-Z0-9])",
                    RegexOptions.IgnoreCase);

            if (nominalSize.Success)
            {
                string result =
                    Regex.Replace(
                        nominalSize.Value,
                        @"\s+",
                        "")
                    .ToUpperInvariant();

                return Regex.Replace(
                    result,
                    @"MM$",
                    "",
                    RegexOptions.IgnoreCase);
            }

            Match pairedSize =
                Regex.Match(
                    normalized,
                    @"(?<!\d)\d{1,4}(?:[\.,]\d{1,2})?\s*(?:[/\\xX×-])\s*\d{1,4}(?:[\.,]\d{1,2})?(?!\d)");

            if (pairedSize.Success)
            {
                return Regex.Replace(
                    pairedSize.Value,
                    @"\s+",
                    " ").Trim();
            }

            // Tuyệt đối không lấy một con số đứng riêng.
            // Nhờ vậy các cao độ như FFL +7000, BOP +3500,
            // EL -1200 và số kích thước kiến trúc 3000
            // sẽ không bị hiểu là kích thước ống.
            return "";
        }

        private bool TryParseAutomaticPipeSize(
            PipeUiContext ctx,
            string sourceText,
            out string sizeText,
            out double pipeWidth)
        {
            sizeText = "";
            pipeWidth = 0;

            string normalized =
                NormalizePipeLabel(sourceText)
                    .Replace(',', '.')
                    .ToUpperInvariant();

            if (string.IsNullOrWhiteSpace(normalized))
                return false;

            // 1. Ký hiệu danh nghĩa: DN20, DN 25, DN50 mm...
            Match dnMatch =
                Regex.Match(
                    normalized,
                    @"(?<![A-Z0-9])DN\s*(?<SIZE>\d{1,4}(?:\.\d+)?)(?:\s*MM)?(?![A-Z0-9])",
                    RegexOptions.IgnoreCase);

            if (dnMatch.Success &&
                TryParsePositiveSize(
                    dnMatch.Groups["SIZE"].Value,
                    2000.0,
                    out double dnSize))
            {
                sizeText =
                    "DN" + FormatSizeNumber(dnSize);

                pipeWidth = dnSize;
                return true;
            }

            // 2. Đường kính ngoài: D60, D63, Ø60, Φ60...
            // Các cỡ thông dụng được đổi về DN.
            // Ví dụ D60 hoặc D63 được hiểu là DN50.
            Match outsideMatch =
                Regex.Match(
                    normalized,
                    @"(?<![A-Z0-9])(?<PREFIX>D|Ø|Φ)\s*(?<SIZE>\d{1,4}(?:\.\d+)?)(?:\s*MM)?(?![A-Z0-9])",
                    RegexOptions.IgnoreCase);

            if (outsideMatch.Success &&
                TryParsePositiveSize(
                    outsideMatch.Groups["SIZE"].Value,
                    2000.0,
                    out double outsideSize))
            {
                if (TryConvertOutsideDiameterToNominal(
                    outsideSize,
                    out double nominalSize))
                {
                    sizeText =
                        "DN" +
                        FormatSizeNumber(nominalSize);

                    pipeWidth = nominalSize;
                }
                else
                {
                    string prefix =
                        outsideMatch.Groups["PREFIX"]
                            .Value
                            .ToUpperInvariant();

                    sizeText =
                        prefix +
                        FormatSizeNumber(outsideSize);

                    pipeWidth = outsideSize;
                }

                return true;
            }

            string material =
                GetSelectedPipeMaterialName(ctx);

            // 3. Chỉ ống đồng mới được nhận cặp đường kính
            // không có ký hiệu DN hoặc D.
            if (LaOngDong(material))
            {
                Match copperMatch =
                    Regex.Match(
                        normalized,
                        @"(?<![\d\.])(?<FIRST>\d{1,2}(?:\.\d{1,2})?)\s*(?:[/\\xX×-])\s*(?<SECOND>\d{1,2}(?:\.\d{1,2})?)(?![\d\.])");

                if (copperMatch.Success &&
                    TryParsePositiveSize(
                        copperMatch.Groups["FIRST"].Value,
                        100.0,
                        out double firstCopperSize) &&
                    TryParsePositiveSize(
                        copperMatch.Groups["SECOND"].Value,
                        100.0,
                        out double secondCopperSize))
                {
                    sizeText =
                        FormatSizeNumber(firstCopperSize) +
                        " - " +
                        FormatSizeNumber(secondCopperSize);

                    pipeWidth =
                        Math.Max(
                            firstCopperSize,
                            secondCopperSize);

                    return true;
                }
            }

            // 4. Chỉ ống gió mới nhận dạng rộng x cao.
            if (LaOngGio(material))
            {
                Match ductMatch =
                    Regex.Match(
                        normalized,
                        @"(?<!\d)(?<WIDTH>\d{2,4})\s*[xX×]\s*(?<HEIGHT>\d{2,4})(?!\d)");

                if (ductMatch.Success &&
                    TryParsePositiveSize(
                        ductMatch.Groups["WIDTH"].Value,
                        9999.0,
                        out double ductWidth) &&
                    TryParsePositiveSize(
                        ductMatch.Groups["HEIGHT"].Value,
                        9999.0,
                        out double ductHeight))
                {
                    sizeText =
                        FormatSizeNumber(ductWidth) +
                        "x" +
                        FormatSizeNumber(ductHeight);

                    pipeWidth =
                        Math.Max(
                            ductWidth,
                            ductHeight);

                    return true;
                }
            }

            // Không còn nhánh lấy "số đầu tiên" như code cũ.
            // Do đó FFL +7000, BOP: FFL +7000,
            // TOP +3500, EL -1200, số trục và kích thước
            // kiến trúc đều bị bỏ qua.
            return false;
        }

        private bool TryParsePositiveSize(
            string value,
            double maximum,
            out double result)
        {
            result = 0;

            if (!double.TryParse(
                (value ?? "").Replace(',', '.'),
                NumberStyles.AllowDecimalPoint,
                CultureInfo.InvariantCulture,
                out double parsed))
            {
                return false;
            }

            if (parsed <= 0 || parsed > maximum)
                return false;

            result = parsed;
            return true;
        }

        private string FormatSizeNumber(double value)
        {
            return value.ToString(
                "0.##",
                CultureInfo.InvariantCulture);
        }

        private static bool TryGetFireSteelOutsideDiameter(
            double nominalDn,
            out double outsideDiameter)
        {
            outsideDiameter = 0.0;

            if (nominalDn <= 0.0)
                return false;

            foreach (double[] row
                in FireSteelDnOutsideDiameterTable)
            {
                if (row == null ||
                    row.Length < 2)
                {
                    continue;
                }

                if (Math.Abs(
                        row[0] -
                        nominalDn) <= 0.01)
                {
                    outsideDiameter =
                        row[1];

                    return true;
                }
            }

            return false;
        }

        private static double GetFireSteelOutsideDiameterForSize(
            string sizeText,
            double fallbackWidth)
        {
            string normalized =
                NormalizeShopDnToken(
                    sizeText ?? "");

            Match m =
                Regex.Match(
                    normalized,
                    @"DN\s*(?<DN>\d{1,4}(?:[.,]\d+)?)",
                    RegexOptions.IgnoreCase);

            if (!m.Success)
                return fallbackWidth;

            if (!double.TryParse(
                    m.Groups["DN"].Value
                        .Replace(',', '.'),
                    NumberStyles.AllowDecimalPoint,
                    CultureInfo.InvariantCulture,
                    out double dn))
            {
                return fallbackWidth;
            }

            if (TryGetFireSteelOutsideDiameter(
                    dn,
                    out double od))
            {
                return od;
            }

            return fallbackWidth;
        }

        private static double GetFireSteelOutsideDiameterForPair(
            string fromSize,
            string toSize,
            double fallback)
        {
            double a =
                GetFireSteelOutsideDiameterForSize(
                    fromSize,
                    0.0);

            double b =
                GetFireSteelOutsideDiameterForSize(
                    toSize,
                    0.0);

            double result =
                Math.Max(
                    a,
                    b);

            return result > 0.0
                ? result
                : fallback;
        }


        private bool TryConvertOutsideDiameterToNominal(
            double outsideDiameter,
            out double nominalDiameter)
        {
            nominalDiameter = 0;

            // Bảng quy đổi các đường kính ngoài thường gặp.
            // Sai số 0.2 mm cho phép nhận cả D60 và D60.3.
            foreach (double[] row
                in OutsideDiameterToNominalTable)
            {
                for (int index = 1;
                    index < row.Length;
                    index++)
                {
                    if (Math.Abs(
                        outsideDiameter -
                        row[index]) <= 0.2)
                    {
                        nominalDiameter = row[0];
                        return true;
                    }
                }
            }

            return false;
        }

        private DBText CreateAutomaticSizeLabel(
            Database db,
            Polyline pipe,
            string layerName,
            string labelText,
            double pipeWidth)
        {
            if (db == null ||
                pipe == null ||
                pipe.NumberOfVertices < 2 ||
                string.IsNullOrWhiteSpace(layerName) ||
                string.IsNullOrWhiteSpace(labelText))
            {
                return null;
            }

            try
            {
                double totalLength =
                    pipe.GetDistanceAtParameter(
                        pipe.EndParam);

                // Vẽ tự động: đoạn có kích thước dù ngắn
                // vẫn phải hiện chữ.
                if (totalLength <= 0.001)
                    return null;

                Point3d middlePoint =
                    pipe.GetPointAtDist(
                        totalLength / 2.0);

                double middleParameter =
                    pipe.GetParameterAtPoint(
                        middlePoint);

                Vector3d direction =
                    pipe.GetFirstDerivative(
                        middleParameter);

                if (direction.Length < 0.000001)
                    return null;

                direction = direction.GetNormal();

                double textRotation =
                    direction.AngleOnPlane(new Plane());

                if (textRotation > Math.PI / 2.0 &&
                    textRotation <=
                    3.0 * Math.PI / 2.0)
                {
                    textRotation -= Math.PI;
                    direction = direction.Negate();
                }

                Vector3d normal =
                    direction.RotateBy(
                        Math.PI / 2.0,
                        Vector3d.ZAxis);

                double textHeight =
                    Math.Max(
                        pipeWidth *
                        LabelTextHeightToWidthRatio,
                        MinimumLabelTextHeight) *
                    AutomaticLabelScale;

                double offset =
                    (pipeWidth / 2.0) +
                    (textHeight * 0.2);

                Point3d textPoint =
                    middlePoint +
                    (normal * offset);

                DBText sizeLabel = new DBText();
                sizeLabel.SetDatabaseDefaults(db);
                sizeLabel.TextString = labelText;
                sizeLabel.Height = textHeight;
                sizeLabel.Layer = layerName;

                sizeLabel.Color =
                    Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                        ColorMethod.ByLayer,
                        256);

                sizeLabel.Linetype = "ByLayer";
                sizeLabel.LineWeight = Autodesk.AutoCAD.DatabaseServices.LineWeight.ByLayer;
                sizeLabel.Justify =
                    AttachmentPoint.BottomCenter;

                sizeLabel.AlignmentPoint = textPoint;
                sizeLabel.Rotation = textRotation;

                return sizeLabel;
            }
            catch
            {
                return null;
            }
        }


        // ============================================================
        // FIX40I - VẼ ỐNG MẪU HỖ TRỢ CẢ MẪU SHOP
        // ============================================================

        private static bool IsTemplateShopCenterline(
            Curve curve)
        {
            if (curve == null)
                return false;

            string layer =
                (curve.Layer ?? "")
                    .Trim();

            return layer.StartsWith(
                "FF_SHOP_TAM_",
                StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsTemplateShopPipeEdge(
            Curve curve)
        {
            if (curve == null)
                return false;

            string layer =
                (curve.Layer ?? "")
                    .Trim()
                    .ToUpperInvariant();

            return Regex.IsMatch(
                layer,
                @"^FF_SHOP_DN\d+(?:[.,]\d+)?$",
                RegexOptions.IgnoreCase);
        }

        private static bool IsTemplateShopFitting(
            Entity entity)
        {
            if (!(entity is BlockReference))
                return false;

            string layer =
                (entity.Layer ?? "")
                    .Trim()
                    .ToUpperInvariant();

            return
                layer.StartsWith("FF_SHOP_CO90_") ||
                layer.StartsWith("FF_SHOP_COLOI45_") ||
                layer.StartsWith("FF_SHOP_TE_") ||
                layer.StartsWith("FF_SHOP_GIAM_") ||
                layer.StartsWith("FF_SHOP_PK_");
        }

        private static bool IsTemplateShopOutputLayer(
            string layerName)
        {
            string layer =
                (layerName ?? "")
                    .Trim()
                    .ToUpperInvariant();

            if (string.IsNullOrWhiteSpace(layer))
                return false;

            return
                layer.StartsWith("FF_SHOP_DN") ||
                layer.StartsWith("FF_SHOP_TAM_") ||
                layer.StartsWith("FF_SHOP_CO90_") ||
                layer.StartsWith("FF_SHOP_COLOI45_") ||
                layer.StartsWith("FF_SHOP_TE_") ||
                layer.StartsWith("FF_SHOP_GIAM_") ||
                layer.StartsWith("FF_SHOP_PK_");
        }

        private static bool IsTemplateShopOutputEntity(
            Entity entity)
        {
            if (entity == null)
                return false;

            if (entity is Curve curve &&
                (IsTemplateShopPipeEdge(curve) ||
                 IsTemplateShopCenterline(curve)))
            {
                return true;
            }

            if (IsTemplateShopFitting(entity))
                return true;

            if ((entity is DBText ||
                 entity is MText) &&
                IsTemplateShopOutputLayer(
                    entity.Layer))
            {
                return true;
            }

            return false;
        }

        private Curve BuildVirtualTemplateCenterlineFromShopEdges(
            List<Curve> shopPipeEdges)
        {
            List<Line> lines =
                (shopPipeEdges ??
                 new List<Curve>())
                    .OfType<Line>()
                    .Where(
                        line =>
                            line != null &&
                            line.Length > 1.0)
                    .ToList();

            if (lines.Count < 2)
                return null;

            Line bestCenterline = null;
            double bestLength = 0.0;
            double bestSeparationError =
                double.MaxValue;

            for (int i = 0;
                i < lines.Count;
                i++)
            {
                Line a = lines[i];

                Vector3d da =
                    a.EndPoint -
                    a.StartPoint;

                da =
                    new Vector3d(
                        da.X,
                        da.Y,
                        0.0);

                if (da.Length < 1e-9)
                    continue;

                double lenA =
                    da.Length;

                da =
                    da.GetNormal();

                for (int j = i + 1;
                    j < lines.Count;
                    j++)
                {
                    Line b = lines[j];

                    if (!string.Equals(
                            a.Layer,
                            b.Layer,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    Vector3d dbDir =
                        b.EndPoint -
                        b.StartPoint;

                    dbDir =
                        new Vector3d(
                            dbDir.X,
                            dbDir.Y,
                            0.0);

                    if (dbDir.Length < 1e-9)
                        continue;

                    double lenB =
                        dbDir.Length;

                    dbDir =
                        dbDir.GetNormal();

                    double parallel =
                        Math.Abs(
                            da.DotProduct(
                                dbDir));

                    if (parallel < 0.995)
                        continue;

                    Point3d bStart =
                        b.StartPoint;

                    Point3d bEnd =
                        b.EndPoint;

                    if (da.DotProduct(dbDir) < 0.0)
                    {
                        Point3d temp =
                            bStart;

                        bStart =
                            bEnd;

                        bEnd =
                            temp;
                    }

                    double lengthTolerance =
                        Math.Max(
                            20.0,
                            Math.Max(
                                lenA,
                                lenB) *
                            0.08);

                    if (Math.Abs(
                            lenA -
                            lenB) >
                        lengthTolerance)
                    {
                        continue;
                    }

                    Vector3d normal =
                        new Vector3d(
                            -da.Y,
                            da.X,
                            0.0);

                    double separation =
                        Math.Abs(
                            (bStart - a.StartPoint)
                                .DotProduct(normal));

                    string sizeToken =
                        NormalizeShopDnToken(
                            a.Layer);

                    double expectedOd =
                        GetFireSteelOutsideDiameterForSize(
                            sizeToken,
                            0.0);

                    double separationError =
                        expectedOd > 0.0
                            ? Math.Abs(
                                separation -
                                expectedOd)
                            : 0.0;

                    double separationTolerance =
                        expectedOd > 0.0
                            ? Math.Max(
                                5.0,
                                expectedOd * 0.20)
                            : Math.Max(
                                10.0,
                                separation * 0.25);

                    if (expectedOd > 0.0 &&
                        separationError >
                        separationTolerance)
                    {
                        continue;
                    }

                    Point3d centerStart =
                        MidPoint(
                            a.StartPoint,
                            bStart);

                    Point3d centerEnd =
                        MidPoint(
                            a.EndPoint,
                            bEnd);

                    double centerLength =
                        centerStart.DistanceTo(
                            centerEnd);

                    if (centerLength <= 1.0)
                        continue;

                    bool better =
                        centerLength >
                            bestLength + 1.0 ||
                        (Math.Abs(
                            centerLength -
                            bestLength) <= 1.0 &&
                         separationError <
                            bestSeparationError);

                    if (!better)
                        continue;

                    bestCenterline?.Dispose();

                    bestCenterline =
                        new Line(
                            centerStart,
                            centerEnd);

                    bestLength =
                        centerLength;

                    bestSeparationError =
                        separationError;
                }
            }

            return bestCenterline;
        }

        private Curve SelectShopTemplateReferenceCurve(
            List<Curve> selectedShopCenterlines,
            List<Curve> sampleShopEdges,
            List<Curve> sampleContextCurves)
        {
            List<Curve> centerlines =
                (selectedShopCenterlines ??
                 new List<Curve>())
                    .Where(
                        curve =>
                            curve != null &&
                            GetTemplateCurveLength(
                                curve) > 1.0)
                    .ToList();

            if (centerlines.Count == 0)
                return null;

            List<Curve> context =
                (sampleContextCurves ??
                 new List<Curve>())
                    .Where(
                        curve =>
                            curve != null)
                    .ToList();

            // FIX40J:
            // Nhánh sprinkler thường có MỘT đầu nối vuông góc vào tuyến chính.
            // Tuyến chính ngang thường bị các nhánh cắt ở GIỮA, không phải endpoint,
            // nên FindTemplateBranchRootIndex của nó thường = -1.
            //
            // Vì vậy ưu tiên centerline có root endpoint rõ ràng,
            // thay vì lấy "đường dài nhất" như FIX40I.
            List<Curve> rootedCandidates =
                centerlines
                    .Where(
                        curve =>
                            FindTemplateBranchRootIndex(
                                curve,
                                context) >= 0)
                    .ToList();

            List<Curve> candidates =
                rootedCandidates.Count > 0
                    ? rootedCandidates
                    : centerlines;

            // Trong các ứng viên branch-root, chọn đoạn có nhiều coverage
            // với 2 nét SHOP và dài hơn.
            return candidates
                .OrderByDescending(
                    curve =>
                        GetTemplateCoverageScore(
                            curve,
                            sampleShopEdges ??
                            new List<Curve>()))
                .ThenByDescending(
                    GetTemplateCurveLength)
                .FirstOrDefault();
        }


        private Point3d GetTemplateEntityRepresentativePoint(
            Entity entity)
        {
            if (entity == null)
                return Point3d.Origin;

            try
            {
                if (entity is Curve curve)
                {
                    return GetTemplateCurvePoint(
                        curve,
                        0.5);
                }

                if (entity is BlockReference block)
                    return block.Position;

                if (entity is DBText dbText)
                    return dbText.Position;

                if (entity is MText mText)
                    return mText.Location;

                Extents3d ext =
                    entity.GeometricExtents;

                return new Point3d(
                    (ext.MinPoint.X + ext.MaxPoint.X) / 2.0,
                    (ext.MinPoint.Y + ext.MaxPoint.Y) / 2.0,
                    (ext.MinPoint.Z + ext.MaxPoint.Z) / 2.0);
            }
            catch
            {
                return Point3d.Origin;
            }
        }

        private double GetTemplateSignedStation(
            Point3d point,
            Point3d origin,
            Vector3d direction)
        {
            Vector3d d =
                new Vector3d(
                    direction.X,
                    direction.Y,
                    0.0);

            if (d.Length < 1e-9)
                return 0.0;

            d = d.GetNormal();

            Vector3d v =
                point -
                origin;

            return v.DotProduct(d);
        }

        private double GetTemplateDistanceToInfiniteAxis(
            Point3d point,
            Point3d origin,
            Vector3d direction)
        {
            Point3d closest =
                GetClosestPointOnManualInfiniteLine(
                    point,
                    origin,
                    direction);

            return GetTemplatePlanDistance(
                point,
                closest);
        }

        private List<Entity> FilterShopTemplateEntitiesToReferenceBranch(
            Curve referenceCurve,
            List<Entity> sampleEntities,
            List<Curve> sampleShopPipeEdges)
        {
            List<Entity> result =
                new List<Entity>();

            if (referenceCurve == null ||
                sampleEntities == null ||
                sampleEntities.Count == 0)
            {
                return result;
            }

            if (!TryGetTemplatePlanDirection(
                    referenceCurve,
                    out Vector3d refDirection))
            {
                return result;
            }

            Point3d refOrigin =
                referenceCurve.StartPoint;

            double maxOutsideDiameter = 0.0;

            foreach (Curve edge in
                sampleShopPipeEdges ??
                new List<Curve>())
            {
                if (edge == null)
                    continue;

                maxOutsideDiameter =
                    Math.Max(
                        maxOutsideDiameter,
                        GetFireSteelOutsideDiameterForSize(
                            edge.Layer,
                            0.0));
            }

            if (maxOutsideDiameter <= 0.0)
                maxOutsideDiameter = 100.0;

            // Hành lang chỉ đủ rộng để chứa 2 nét + fitting của CHÍNH nhánh.
            // Khoảng cách giữa các nhánh trong bản vẽ thường vài mét,
            // nên corridor này không ăn sang nhánh kế bên.
            double corridor =
                Math.Max(
                    180.0,
                    maxOutsideDiameter * 1.60);

            double fittingCorridor =
                Math.Max(
                    280.0,
                    maxOutsideDiameter * 2.50);

            double stationPadding =
                Math.Max(
                    350.0,
                    maxOutsideDiameter * 3.50);

            // --------------------------------------------------------
            // BƯỚC A: tìm span dọc của đúng nhánh bằng các nét/tim SHOP
            // song song với reference.
            // --------------------------------------------------------
            double minStation =
                double.MaxValue;

            double maxStation =
                double.MinValue;

            List<Curve> branchLongitudinalCurves =
                new List<Curve>();

            foreach (Entity entity in sampleEntities)
            {
                if (!(entity is Curve curve))
                    continue;

                if (!IsTemplateShopPipeEdge(curve) &&
                    !IsTemplateShopCenterline(curve))
                {
                    continue;
                }

                if (!TryGetTemplatePlanDirection(
                        curve,
                        out Vector3d curveDirection))
                {
                    continue;
                }

                double directionDot =
                    Math.Abs(
                        refDirection.DotProduct(
                            curveDirection));

                if (directionDot < 0.94)
                    continue;

                Point3d middle =
                    GetTemplateCurvePoint(
                        curve,
                        0.5);

                double axisDistance =
                    GetTemplateDistanceToInfiniteAxis(
                        middle,
                        refOrigin,
                        refDirection);

                if (axisDistance >
                    corridor)
                {
                    continue;
                }

                branchLongitudinalCurves.Add(
                    curve);

                double s0 =
                    GetTemplateSignedStation(
                        curve.StartPoint,
                        refOrigin,
                        refDirection);

                double s1 =
                    GetTemplateSignedStation(
                        curve.EndPoint,
                        refOrigin,
                        refDirection);

                minStation =
                    Math.Min(
                        minStation,
                        Math.Min(s0, s1));

                maxStation =
                    Math.Max(
                        maxStation,
                        Math.Max(s0, s1));
            }

            if (minStation ==
                    double.MaxValue ||
                maxStation ==
                    double.MinValue)
            {
                minStation =
                    Math.Min(
                        GetTemplateSignedStation(
                            referenceCurve.StartPoint,
                            refOrigin,
                            refDirection),
                        GetTemplateSignedStation(
                            referenceCurve.EndPoint,
                            refOrigin,
                            refDirection));

                maxStation =
                    Math.Max(
                        GetTemplateSignedStation(
                            referenceCurve.StartPoint,
                            refOrigin,
                            refDirection),
                        GetTemplateSignedStation(
                            referenceCurve.EndPoint,
                            refOrigin,
                            refDirection));
            }

            double allowedMin =
                minStation -
                stationPadding;

            double allowedMax =
                maxStation +
                stationPadding;

            // --------------------------------------------------------
            // BƯỚC B: chỉ giữ output thuộc hành lang của branch.
            // Đặc biệt: KHÔNG copy tuyến chính ngang dài đi qua root.
            // --------------------------------------------------------
            foreach (Entity entity in sampleEntities)
            {
                if (!IsTemplateShopOutputEntity(
                        entity))
                {
                    continue;
                }

                if (entity is Curve curve)
                {
                    Point3d middle =
                        GetTemplateCurvePoint(
                            curve,
                            0.5);

                    double station =
                        GetTemplateSignedStation(
                            middle,
                            refOrigin,
                            refDirection);

                    double axisDistance =
                        GetTemplateDistanceToInfiniteAxis(
                            middle,
                            refOrigin,
                            refDirection);

                    bool isLongitudinal =
                        false;

                    if (TryGetTemplatePlanDirection(
                            curve,
                            out Vector3d curveDirection))
                    {
                        isLongitudinal =
                            Math.Abs(
                                refDirection.DotProduct(
                                    curveDirection)) >=
                            0.94;
                    }

                    if (isLongitudinal)
                    {
                        if (axisDistance <=
                                corridor &&
                            station >= allowedMin &&
                            station <= allowedMax)
                        {
                            result.Add(entity);
                        }

                        continue;
                    }

                    // Đoạn vuông góc/nghiêng chỉ được copy nếu nó RẤT GẦN
                    // một đầu của span branch (ví dụ đoạn ngắn sát Co).
                    double toStart =
                        GetTemplatePlanDistance(
                            middle,
                            referenceCurve.StartPoint);

                    double toEnd =
                        GetTemplatePlanDistance(
                            middle,
                            referenceCurve.EndPoint);

                    double shortCrossLimit =
                        Math.Max(
                            450.0,
                            maxOutsideDiameter * 4.0);

                    if (GetTemplateCurveLength(curve) <=
                            shortCrossLimit &&
                        Math.Min(
                            toStart,
                            toEnd) <=
                            fittingCorridor)
                    {
                        result.Add(entity);
                    }

                    continue;
                }

                Point3d point =
                    GetTemplateEntityRepresentativePoint(
                        entity);

                double pointStation =
                    GetTemplateSignedStation(
                        point,
                        refOrigin,
                        refDirection);

                double pointDistance =
                    GetTemplateDistanceToInfiniteAxis(
                        point,
                        refOrigin,
                        refDirection);

                if (pointDistance <=
                        fittingCorridor &&
                    pointStation >=
                        allowedMin &&
                    pointStation <=
                        allowedMax)
                {
                    result.Add(entity);
                }
            }

            return result
                .Distinct()
                .ToList();
        }


        private bool IsTemplateReferenceCurve(Entity entity)
        {
            return entity is Line ||
                   entity is Polyline ||
                   entity is Polyline2d ||
                   entity is Polyline3d ||
                   entity is Arc;
        }

        private double GetTemplateCurveWidth(Curve curve)
        {
            if (!(curve is Polyline polyline))
                return 0.0;

            double width = polyline.ConstantWidth;

            for (int index = 0;
                index < polyline.NumberOfVertices;
                index++)
            {
                width = Math.Max(
                    width,
                    polyline.GetStartWidthAt(index));

                width = Math.Max(
                    width,
                    polyline.GetEndWidthAt(index));
            }

            return width;
        }

        private bool IsTemplatePipeCurve(Curve curve)
        {
            if (curve == null ||
                !IsTemplateReferenceCurve(curve))
            {
                return false;
            }

            // Kiểu cũ: Polyline có width.
            if (GetTemplateCurveWidth(curve) > 0.001)
                return true;

            // FIX40I: SHOP mới là 2 LINE trên FF_SHOP_DNxx.
            // FF_SHOP_TAM_* là tim tham chiếu, không phải nét biên.
            return IsTemplateShopPipeEdge(
                curve);
        }

        private double GetTemplateCurveLength(Curve curve)
        {
            if (curve == null)
                return 0.0;

            try
            {
                return curve.GetDistanceAtParameter(
                    curve.EndParam);
            }
            catch
            {
                try
                {
                    return curve.StartPoint.DistanceTo(
                        curve.EndPoint);
                }
                catch
                {
                    return 0.0;
                }
            }
        }

        private Point3d GetTemplateCurvePoint(
            Curve curve,
            double fraction)
        {
            fraction =
                Math.Max(
                    0.0,
                    Math.Min(1.0, fraction));

            double length =
                GetTemplateCurveLength(curve);

            if (length <= 0.001)
                return curve.StartPoint;

            try
            {
                return curve.GetPointAtDist(
                    length * fraction);
            }
            catch
            {
                return fraction < 0.5
                    ? curve.StartPoint
                    : curve.EndPoint;
            }
        }

        private double GetTemplatePlanDistance(
            Point3d first,
            Point3d second)
        {
            double deltaX = first.X - second.X;
            double deltaY = first.Y - second.Y;

            return Math.Sqrt(
                (deltaX * deltaX) +
                (deltaY * deltaY));
        }

        private double GetTemplateCoverageScore(
            Curve referenceCurve,
            IEnumerable<Curve> templatePipeCurves)
        {
            double score = 0.0;

            foreach (Curve pipeCurve in
                templatePipeCurves ??
                Enumerable.Empty<Curve>())
            {
                double maximumDistance = 0.0;
                bool valid = true;

                foreach (double fraction in
                    new double[] { 0.15, 0.5, 0.85 })
                {
                    Point3d testPoint =
                        GetTemplateCurvePoint(
                            pipeCurve,
                            fraction);

                    if (!TryGetClosestPointInPlan(
                        referenceCurve,
                        testPoint,
                        out Point3d ignoredPoint,
                        out double planDistance))
                    {
                        valid = false;
                        break;
                    }

                    maximumDistance =
                        Math.Max(
                            maximumDistance,
                            planDistance);
                }

                double allowedDistance =
                    Math.Max(
                        250.0,
                        (GetTemplateCurveWidth(
                            pipeCurve) / 2.0) +
                        150.0);

                if (valid &&
                    maximumDistance <= allowedDistance)
                {
                    score +=
                        GetTemplateCurveLength(
                            pipeCurve);
                }
            }

            return score;
        }

        private Curve SelectTemplateReferenceCurve(
            List<Curve> sourceCurves,
            List<Curve> templatePipeCurves)
        {
            List<Curve> candidates =
                sourceCurves != null &&
                sourceCurves.Count > 0
                    ? sourceCurves
                    : templatePipeCurves;

            if (candidates == null ||
                candidates.Count == 0)
            {
                return null;
            }

            return candidates
                .OrderByDescending(
                    curve =>
                        GetTemplateCoverageScore(
                            curve,
                            templatePipeCurves))
                .ThenByDescending(
                    GetTemplateCurveLength)
                .FirstOrDefault();
        }

        private double GetTemplateAxisProjection(
            Point3d point,
            Point3d axisOrigin,
            Vector3d axisDirection)
        {
            Vector3d delta =
                new Vector3d(
                    point.X - axisOrigin.X,
                    point.Y - axisOrigin.Y,
                    0.0);

            return delta.DotProduct(axisDirection);
        }

        private double GetTemplateAxisOffset(
            Point3d point,
            Point3d axisOrigin,
            Vector3d axisNormal)
        {
            Vector3d delta =
                new Vector3d(
                    point.X - axisOrigin.X,
                    point.Y - axisOrigin.Y,
                    0.0);

            return Math.Abs(
                delta.DotProduct(axisNormal));
        }

        private Curve BuildVirtualTemplateCenterline(
            List<Curve> templatePipeCurves)
        {
            List<Curve> validCurves =
                (templatePipeCurves ??
                 new List<Curve>())
                    .Where(
                        curve =>
                            curve != null &&
                            GetTemplateCurveLength(curve) >
                            1.0)
                    .ToList();

            if (validCurves.Count == 0)
                return null;

            double bestSpan = 0.0;
            double bestCoveredLength = 0.0;
            Point3d bestOrigin = Point3d.Origin;
            Vector3d bestDirection = Vector3d.XAxis;
            double bestStart = 0.0;
            double bestEnd = 0.0;

            foreach (Curve seedCurve in validCurves)
            {
                if (!TryGetTemplatePlanDirection(
                    seedCurve,
                    out Vector3d axisDirection))
                {
                    continue;
                }

                Point3d axisOrigin =
                    seedCurve.StartPoint;

                Vector3d axisNormal =
                    new Vector3d(
                        -axisDirection.Y,
                        axisDirection.X,
                        0.0);

                List<double[]> intervals =
                    new List<double[]>();

                foreach (Curve candidateCurve in validCurves)
                {
                    if (!TryGetTemplatePlanDirection(
                        candidateCurve,
                        out Vector3d candidateDirection))
                    {
                        continue;
                    }

                    double parallelScore =
                        Math.Abs(
                            axisDirection.DotProduct(
                                candidateDirection));

                    if (parallelScore < 0.985)
                        continue;

                    double maximumAxisOffset =
                        Math.Max(
                            200.0,
                            (Math.Max(
                                GetTemplateCurveWidth(
                                    seedCurve),
                                GetTemplateCurveWidth(
                                    candidateCurve)) /
                             2.0) +
                            100.0);

                    Point3d candidateStart =
                        candidateCurve.StartPoint;

                    Point3d candidateMiddle =
                        GetTemplateCurvePoint(
                            candidateCurve,
                            0.5);

                    Point3d candidateEnd =
                        candidateCurve.EndPoint;

                    if (GetTemplateAxisOffset(
                            candidateStart,
                            axisOrigin,
                            axisNormal) >
                            maximumAxisOffset ||
                        GetTemplateAxisOffset(
                            candidateMiddle,
                            axisOrigin,
                            axisNormal) >
                            maximumAxisOffset ||
                        GetTemplateAxisOffset(
                            candidateEnd,
                            axisOrigin,
                            axisNormal) >
                            maximumAxisOffset)
                    {
                        continue;
                    }

                    double firstProjection =
                        GetTemplateAxisProjection(
                            candidateStart,
                            axisOrigin,
                            axisDirection);

                    double secondProjection =
                        GetTemplateAxisProjection(
                            candidateEnd,
                            axisOrigin,
                            axisDirection);

                    intervals.Add(
                        new double[]
                        {
                            Math.Min(
                                firstProjection,
                                secondProjection),
                            Math.Max(
                                firstProjection,
                                secondProjection)
                        });
                }

                if (intervals.Count == 0)
                    continue;

                List<double[]> orderedIntervals =
                    intervals
                        .OrderBy(item => item[0])
                        .ThenBy(item => item[1])
                        .ToList();

                double clusterStart =
                    orderedIntervals[0][0];

                double clusterEnd =
                    orderedIntervals[0][1];

                double clusterCoveredLength =
                    orderedIntervals[0][1] -
                    orderedIntervals[0][0];

                Action evaluateCluster = () =>
                {
                    double span =
                        clusterEnd - clusterStart;

                    if (span > bestSpan + 1.0 ||
                        (Math.Abs(span - bestSpan) <=
                            1.0 &&
                         clusterCoveredLength >
                            bestCoveredLength))
                    {
                        bestSpan = span;
                        bestCoveredLength =
                            clusterCoveredLength;
                        bestOrigin = axisOrigin;
                        bestDirection = axisDirection;
                        bestStart = clusterStart;
                        bestEnd = clusterEnd;
                    }
                };

                for (int intervalIndex = 1;
                    intervalIndex <
                    orderedIntervals.Count;
                    intervalIndex++)
                {
                    double[] interval =
                        orderedIntervals[intervalIndex];

                    if (interval[0] <=
                        clusterEnd +
                        TemplateConnectionTolerance)
                    {
                        double uncoveredStart =
                            Math.Max(
                                clusterEnd,
                                interval[0]);

                        if (interval[1] > uncoveredStart)
                        {
                            clusterCoveredLength +=
                                interval[1] -
                                uncoveredStart;
                        }

                        clusterEnd =
                            Math.Max(
                                clusterEnd,
                                interval[1]);
                    }
                    else
                    {
                        evaluateCluster();

                        clusterStart = interval[0];
                        clusterEnd = interval[1];

                        clusterCoveredLength =
                            interval[1] -
                            interval[0];
                    }
                }

                evaluateCluster();
            }

            if (bestSpan <= 1.0)
                return null;

            Point3d virtualStart =
                new Point3d(
                    bestOrigin.X +
                    (bestDirection.X * bestStart),
                    bestOrigin.Y +
                    (bestDirection.Y * bestStart),
                    bestOrigin.Z);

            Point3d virtualEnd =
                new Point3d(
                    bestOrigin.X +
                    (bestDirection.X * bestEnd),
                    bestOrigin.Y +
                    (bestDirection.Y * bestEnd),
                    bestOrigin.Z);

            return new Line(
                virtualStart,
                virtualEnd);
        }

        private Curve SelectUsableTemplateReferenceCurve(
            Curve sourceReferenceCurve,
            Curve virtualReferenceCurve,
            List<Curve> templatePipeCurves)
        {
            if (sourceReferenceCurve == null)
                return virtualReferenceCurve;

            if (virtualReferenceCurve == null)
                return sourceReferenceCurve;

            double sourceCoverage =
                GetTemplateCoverageScore(
                    sourceReferenceCurve,
                    templatePipeCurves);

            double virtualCoverage =
                GetTemplateCoverageScore(
                    virtualReferenceCurve,
                    templatePipeCurves);

            double sourceLength =
                GetTemplateCurveLength(
                    sourceReferenceCurve);

            double virtualLength =
                GetTemplateCurveLength(
                    virtualReferenceCurve);

            double allowedLengthDifference =
                Math.Max(
                    TemplateAbsoluteLengthTolerance,
                    virtualLength *
                    TemplateLengthToleranceRatio);

            bool sourceCurveStillRepresentsWholeBranch =
                sourceCoverage >=
                    virtualCoverage * 0.90 &&
                Math.Abs(
                    sourceLength -
                    virtualLength) <=
                    allowedLengthDifference;

            return sourceCurveStillRepresentsWholeBranch
                ? sourceReferenceCurve
                : virtualReferenceCurve;
        }

        private List<Point3d> CollectTemplateShopMarkerCenters(
            Transaction tr,
            IEnumerable<Entity> entities)
        {
            List<Point3d> centers =
                new List<Point3d>();

            foreach (Entity entity in
                entities ??
                Enumerable.Empty<Entity>())
            {
                if (entity == null ||
                    IsTemplateShopFitting(entity))
                {
                    continue;
                }

                if (entity is Circle circle)
                {
                    AddUniquePoint(
                        centers,
                        circle.Center,
                        5.0);

                    continue;
                }

                if (entity is BlockReference blockReference)
                {
                    // FIX40K:
                    // Với mẫu SHOP KHÔNG dùng Position của mọi block làm marker.
                    // Chỉ nhận block thật sự có hình tròn bên trong
                    // (đầu phun/marker). Tránh VT, note, symbol... làm sai span.
                    List<Point3d> blockCenters =
                        GetCircularCentersFromBlock(
                            tr,
                            blockReference);

                    foreach (Point3d center
                        in blockCenters)
                    {
                        AddUniquePoint(
                            centers,
                            center,
                            5.0);
                    }
                }
            }

            return centers;
        }

        private Curve BuildTemplateMarkerBoundReferenceCurve(
            Curve baseCurve,
            List<Point3d> markers)
        {
            if (baseCurve == null ||
                markers == null ||
                markers.Count < 2)
            {
                return null;
            }

            if (!TryGetTemplatePlanDirection(
                    baseCurve,
                    out Vector3d direction))
            {
                return null;
            }

            Point3d origin =
                baseCurve.StartPoint;

            List<double> stations =
                new List<double>();

            foreach (Point3d marker
                in markers)
            {
                if (!TryGetClosestPointInPlan(
                        baseCurve,
                        marker,
                        out Point3d closest,
                        out double distance))
                {
                    continue;
                }

                if (distance >
                    TemplateMarkerSearchDistance)
                {
                    continue;
                }

                stations.Add(
                    GetTemplateSignedStation(
                        closest,
                        origin,
                        direction));
            }

            if (stations.Count < 2)
                return null;

            double minStation =
                stations.Min();

            double maxStation =
                stations.Max();

            if (maxStation -
                minStation <
                50.0)
            {
                return null;
            }

            Point3d start =
                origin +
                direction *
                minStation;

            Point3d end =
                origin +
                direction *
                maxStation;

            return new Line(
                start,
                end);
        }

        private Entity CloneTemplateEntityInsideReferenceSpan(
            Entity sourceEntity,
            Curve referenceCurve,
            bool strictShopSpan)
        {
            if (sourceEntity == null)
                return null;

            if (!strictShopSpan ||
                referenceCurve == null)
            {
                return sourceEntity.Clone()
                    as Entity;
            }

            if (!TryGetTemplatePlanDirection(
                    referenceCurve,
                    out Vector3d refDirection))
            {
                return sourceEntity.Clone()
                    as Entity;
            }

            Point3d origin =
                referenceCurve.StartPoint;

            double span =
                GetTemplateSignedStation(
                    referenceCurve.EndPoint,
                    origin,
                    refDirection);

            if (span < 0.0)
            {
                refDirection =
                    refDirection.Negate();

                span =
                    -span;
            }

            if (span <= 1.0)
                return null;

            // --------------------------------------------------------
            // LINE SHOP:
            // Nếu entity dài xuyên ra ngoài vùng user đã quét,
            // chỉ clone phần nằm trong marker-span.
            // --------------------------------------------------------
            if (sourceEntity is Line sourceLine)
            {
                Vector3d lineVector =
                    sourceLine.EndPoint -
                    sourceLine.StartPoint;

                lineVector =
                    new Vector3d(
                        lineVector.X,
                        lineVector.Y,
                        0.0);

                if (lineVector.Length < 1e-9)
                    return null;

                Vector3d lineDirection =
                    lineVector.GetNormal();

                double parallel =
                    Math.Abs(
                        refDirection.DotProduct(
                            lineDirection));

                if (parallel >= 0.94)
                {
                    double s0 =
                        GetTemplateSignedStation(
                            sourceLine.StartPoint,
                            origin,
                            refDirection);

                    double s1 =
                        GetTemplateSignedStation(
                            sourceLine.EndPoint,
                            origin,
                            refDirection);

                    double ds =
                        s1 - s0;

                    if (Math.Abs(ds) < 1e-9)
                        return null;

                    double tAtMin =
                        (0.0 - s0) /
                        ds;

                    double tAtMax =
                        (span - s0) /
                        ds;

                    double tLow =
                        Math.Max(
                            0.0,
                            Math.Min(
                                tAtMin,
                                tAtMax));

                    double tHigh =
                        Math.Min(
                            1.0,
                            Math.Max(
                                tAtMin,
                                tAtMax));

                    if (tHigh -
                        tLow <=
                        1e-6)
                    {
                        return null;
                    }

                    Point3d p0 =
                        sourceLine.StartPoint +
                        (sourceLine.EndPoint -
                         sourceLine.StartPoint) *
                        tLow;

                    Point3d p1 =
                        sourceLine.StartPoint +
                        (sourceLine.EndPoint -
                         sourceLine.StartPoint) *
                        tHigh;

                    Line clipped =
                        sourceLine.Clone()
                            as Line;

                    if (clipped == null)
                        return null;

                    clipped.StartPoint =
                        p0;

                    clipped.EndPoint =
                        p1;

                    return clipped;
                }
            }

            // --------------------------------------------------------
            // BLOCK/TEXT/FITTING và curve không song song:
            // chỉ giữ nếu tâm đại diện nằm trong đúng marker-span.
            // --------------------------------------------------------
            Point3d representative =
                GetTemplateEntityRepresentativePoint(
                    sourceEntity);

            double station =
                GetTemplateSignedStation(
                    representative,
                    origin,
                    refDirection);

            double alongTolerance =
                50.0;

            if (station <
                    -alongTolerance ||
                station >
                    span +
                    alongTolerance)
            {
                return null;
            }

            return sourceEntity.Clone()
                as Entity;
        }


        private List<Point3d> CollectTemplateMarkerCenters(
            Transaction tr,
            IEnumerable<Entity> entities)
        {
            List<Point3d> centers =
                new List<Point3d>();

            foreach (Entity entity in
                entities ??
                Enumerable.Empty<Entity>())
            {
                // FIX40I:
                // Co/Tê/Giảm của mẫu SHOP là OUTPUT cần copy,
                // KHÔNG phải marker nhận diện (đầu phun).
                // Nếu tính fitting là marker thì target line gốc sẽ thiếu
                // marker tương ứng và bị loại sai ở TryMatchTemplateBranch.
                if (IsTemplateShopFitting(
                        entity))
                {
                    continue;
                }

                if (entity is Circle circle)
                {
                    AddUniquePoint(
                        centers,
                        circle.Center,
                        5.0);
                }
                else if (entity is BlockReference blockReference)
                {
                    List<Point3d> blockCenters =
                        GetCircularCentersFromBlock(
                            tr,
                            blockReference);

                    if (blockCenters.Count == 0)
                    {
                        AddUniquePoint(
                            centers,
                            blockReference.Position,
                            5.0);
                    }
                    else
                    {
                        foreach (Point3d center
                            in blockCenters)
                        {
                            AddUniquePoint(
                                centers,
                                center,
                                5.0);
                        }
                    }
                }
            }

            return centers;
        }

        private List<Point3d> GetTemplateMarkersNearCurve(
            Curve curve,
            IEnumerable<Point3d> markerCenters)
        {
            List<Point3d> result =
                new List<Point3d>();

            foreach (Point3d center in
                markerCenters ??
                Enumerable.Empty<Point3d>())
            {
                if (TryGetClosestPointInPlan(
                    curve,
                    center,
                    out Point3d ignoredPoint,
                    out double planDistance) &&
                    planDistance <=
                    TemplateMarkerSearchDistance)
                {
                    AddUniquePoint(
                        result,
                        center,
                        5.0);
                }
            }

            return result;
        }

        private bool TryGetTemplatePlanDirection(
            Curve curve,
            out Vector3d direction)
        {
            direction = Vector3d.XAxis;

            if (curve == null)
                return false;

            try
            {
                Point3d startPoint =
                    curve.StartPoint;

                Point3d endPoint =
                    curve.EndPoint;

                Vector3d chord =
                    new Vector3d(
                        endPoint.X - startPoint.X,
                        endPoint.Y - startPoint.Y,
                        0.0);

                if (chord.Length <= 0.001)
                    return false;

                direction = chord.GetNormal();
                return true;
            }
            catch
            {
                return false;
            }
        }

        private int FindTemplateBranchRootIndex(
            Curve branchCurve,
            IEnumerable<Curve> contextCurves)
        {
            if (!TryGetTemplatePlanDirection(
                branchCurve,
                out Vector3d branchDirection))
            {
                return -1;
            }

            Point3d[] endpoints =
            {
                branchCurve.StartPoint,
                branchCurve.EndPoint
            };

            bool[] hasNonCollinearConnection =
            {
                false,
                false
            };

            for (int endpointIndex = 0;
                endpointIndex < endpoints.Length;
                endpointIndex++)
            {
                foreach (Curve otherCurve in
                    contextCurves ??
                    Enumerable.Empty<Curve>())
                {
                    if (otherCurve == null ||
                        ReferenceEquals(
                            branchCurve,
                            otherCurve))
                    {
                        continue;
                    }

                    if (branchCurve.ObjectId != ObjectId.Null &&
                        otherCurve.ObjectId != ObjectId.Null &&
                        branchCurve.ObjectId ==
                        otherCurve.ObjectId)
                    {
                        continue;
                    }

                    if (!TryGetClosestPointInPlan(
                        otherCurve,
                        endpoints[endpointIndex],
                        out Point3d ignoredPoint,
                        out double planDistance) ||
                        planDistance >
                        TemplateConnectionTolerance)
                    {
                        continue;
                    }

                    if (!TryGetTemplatePlanDirection(
                        otherCurve,
                        out Vector3d otherDirection))
                    {
                        continue;
                    }

                    double directionDot =
                        Math.Abs(
                            branchDirection.DotProduct(
                                otherDirection));

                    if (directionDot < 0.94)
                    {
                        hasNonCollinearConnection[
                            endpointIndex] = true;

                        break;
                    }
                }
            }

            if (hasNonCollinearConnection[0] &&
                !hasNonCollinearConnection[1])
            {
                return 0;
            }

            if (!hasNonCollinearConnection[0] &&
                hasNonCollinearConnection[1])
            {
                return 1;
            }

            return -1;
        }

        private bool TryBuildTemplateAlignment(
            Curve sourceCurve,
            Curve targetCurve,
            bool reverseTarget,
            out Matrix3d transform)
        {
            transform = Matrix3d.Identity;

            try
            {
                Point3d sourceStart =
                    sourceCurve.StartPoint;

                Point3d sourceEnd =
                    sourceCurve.EndPoint;

                Point3d targetStart =
                    reverseTarget
                        ? targetCurve.EndPoint
                        : targetCurve.StartPoint;

                Point3d targetEnd =
                    reverseTarget
                        ? targetCurve.StartPoint
                        : targetCurve.EndPoint;

                Vector3d sourceXAxis =
                    new Vector3d(
                        sourceEnd.X - sourceStart.X,
                        sourceEnd.Y - sourceStart.Y,
                        0.0);

                Vector3d targetXAxis =
                    new Vector3d(
                        targetEnd.X - targetStart.X,
                        targetEnd.Y - targetStart.Y,
                        0.0);

                if (sourceXAxis.Length <= 0.001 ||
                    targetXAxis.Length <= 0.001)
                {
                    return false;
                }

                sourceXAxis = sourceXAxis.GetNormal();
                targetXAxis = targetXAxis.GetNormal();

                Vector3d sourceYAxis =
                    Vector3d.ZAxis
                        .CrossProduct(sourceXAxis)
                        .GetNormal();

                Vector3d targetYAxis =
                    Vector3d.ZAxis
                        .CrossProduct(targetXAxis)
                        .GetNormal();

                transform =
                    Matrix3d.AlignCoordinateSystem(
                        sourceStart,
                        sourceXAxis,
                        sourceYAxis,
                        Vector3d.ZAxis,
                        targetStart,
                        targetXAxis,
                        targetYAxis,
                        Vector3d.ZAxis);

                return true;
            }
            catch
            {
                return false;
            }
        }

        private bool TryMatchTemplateBranch(
            Curve sourceCurve,
            Curve targetCurve,
            int sourceRootIndex,
            int targetRootIndex,
            List<Point3d> sourceMarkers,
            List<Point3d> targetMarkers,
            out Matrix3d bestTransform,
            out double bestScore)
        {
            bestTransform = Matrix3d.Identity;
            bestScore = double.MaxValue;

            double sourceLength =
                GetTemplateCurveLength(
                    sourceCurve);

            double targetLength =
                GetTemplateCurveLength(
                    targetCurve);

            if (sourceLength <= 0.001 ||
                targetLength <= 0.001)
            {
                return false;
            }

            double lengthTolerance =
                Math.Max(
                    TemplateAbsoluteLengthTolerance,
                    sourceLength *
                    TemplateLengthToleranceRatio);

            if (Math.Abs(
                sourceLength -
                targetLength) > lengthTolerance)
            {
                return false;
            }

            List<bool> reverseOptions =
                new List<bool>();

            if (sourceRootIndex >= 0 &&
                targetRootIndex >= 0)
            {
                reverseOptions.Add(
                    sourceRootIndex !=
                    targetRootIndex);
            }
            else
            {
                reverseOptions.Add(false);
                reverseOptions.Add(true);
            }

            foreach (bool reverseTarget in
                reverseOptions.Distinct())
            {
                if (!TryBuildTemplateAlignment(
                    sourceCurve,
                    targetCurve,
                    reverseTarget,
                    out Matrix3d candidateTransform))
                {
                    continue;
                }

                double shapeErrorTotal = 0.0;
                int shapePointCount = 0;

                for (int index = 0;
                    index <= 8;
                    index++)
                {
                    double fraction =
                        index / 8.0;

                    Point3d sourcePoint =
                        GetTemplateCurvePoint(
                            sourceCurve,
                            fraction);

                    Point3d targetPoint =
                        GetTemplateCurvePoint(
                            targetCurve,
                            reverseTarget
                                ? 1.0 - fraction
                                : fraction);

                    Point3d transformedPoint =
                        sourcePoint.TransformBy(
                            candidateTransform);

                    shapeErrorTotal +=
                        GetTemplatePlanDistance(
                            transformedPoint,
                            targetPoint);

                    shapePointCount++;
                }

                double shapeError =
                    shapePointCount > 0
                        ? shapeErrorTotal /
                          shapePointCount
                        : double.MaxValue;

                double shapeTolerance =
                    Math.Max(
                        80.0,
                        sourceLength *
                        TemplateShapeToleranceRatio);

                if (shapeError > shapeTolerance)
                    continue;

                int matchedMarkerCount = 0;
                double markerErrorTotal = 0.0;

                HashSet<int> usedTargetMarkerIndexes =
                    new HashSet<int>();

                foreach (Point3d sourceMarker in
                    sourceMarkers ??
                    new List<Point3d>())
                {
                    Point3d expectedMarker =
                        sourceMarker.TransformBy(
                            candidateTransform);

                    int bestMarkerIndex = -1;

                    double nearestMarkerDistance =
                        double.MaxValue;

                    for (int markerIndex = 0;
                        markerIndex <
                        (targetMarkers?.Count ?? 0);
                        markerIndex++)
                    {
                        if (usedTargetMarkerIndexes.Contains(
                            markerIndex))
                        {
                            continue;
                        }

                        double markerDistance =
                            GetTemplatePlanDistance(
                                expectedMarker,
                                targetMarkers[markerIndex]);

                        if (markerDistance <
                            nearestMarkerDistance)
                        {
                            nearestMarkerDistance =
                                markerDistance;

                            bestMarkerIndex =
                                markerIndex;
                        }
                    }

                    if (bestMarkerIndex >= 0 &&
                        nearestMarkerDistance <=
                        TemplateMarkerMatchTolerance)
                    {
                        usedTargetMarkerIndexes.Add(
                            bestMarkerIndex);

                        matchedMarkerCount++;
                        markerErrorTotal +=
                            nearestMarkerDistance;
                    }
                }

                int requiredMarkerCount =
                    sourceMarkers != null &&
                    sourceMarkers.Count > 0
                        ? Math.Max(
                            1,
                            (int)Math.Ceiling(
                                sourceMarkers.Count *
                                0.75))
                        : 0;

                if (matchedMarkerCount <
                    requiredMarkerCount)
                {
                    continue;
                }

                double markerError =
                    matchedMarkerCount > 0
                        ? markerErrorTotal /
                          matchedMarkerCount
                        : 0.0;

                double score =
                    shapeError +
                    (markerError * 0.35);

                if (sourceRootIndex < 0 &&
                    targetRootIndex < 0 &&
                    (sourceMarkers == null ||
                     sourceMarkers.Count == 0) &&
                    TryGetTemplatePlanDirection(
                        sourceCurve,
                        out Vector3d sourceDirection) &&
                    TryGetTemplatePlanDirection(
                        targetCurve,
                        out Vector3d targetDirection))
                {
                    if (reverseTarget)
                    {
                        targetDirection =
                            targetDirection.Negate();
                    }

                    score +=
                        sourceDirection.GetAngleTo(
                            targetDirection) * 10.0;
                }

                if (score < bestScore)
                {
                    bestScore = score;
                    bestTransform =
                        candidateTransform;
                }
            }

            return bestScore < double.MaxValue;
        }

        private bool HasTemplateOutputAtPlacement(
            Curve probeCurve,
            Matrix3d transform,
            IEnumerable<Curve> existingPipeCurves)
        {
            if (probeCurve == null)
                return false;

            Point3d expectedCenter =
                GetTemplateCurvePoint(
                    probeCurve,
                    0.5)
                .TransformBy(transform);

            double probeLength =
                GetTemplateCurveLength(
                    probeCurve);

            double lengthTolerance =
                Math.Max(
                    TemplateAbsoluteLengthTolerance,
                    probeLength *
                    TemplateLengthToleranceRatio);

            foreach (Curve existingCurve in
                existingPipeCurves ??
                Enumerable.Empty<Curve>())
            {
                if (!string.Equals(
                    existingCurve.Layer,
                    probeCurve.Layer,
                    StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (Math.Abs(
                    GetTemplateCurveLength(
                        existingCurve) -
                    probeLength) >
                    lengthTolerance)
                {
                    continue;
                }

                Point3d existingCenter =
                    GetTemplateCurvePoint(
                        existingCurve,
                        0.5);

                if (GetTemplatePlanDistance(
                    expectedCenter,
                    existingCenter) <=
                    TemplateDuplicateTolerance)
                {
                    return true;
                }
            }

            return false;
        }

        private double GetReadableTemplateTextRotation(
            double rotation)
        {
            double fullTurn = Math.PI * 2.0;

            double readableRotation =
                rotation % fullTurn;

            if (readableRotation < 0.0)
                readableRotation += fullTurn;

            if (readableRotation > Math.PI / 2.0 &&
                readableRotation <=
                3.0 * Math.PI / 2.0)
            {
                readableRotation -= Math.PI;
            }

            return readableRotation;
        }

        private void KeepTemplateCopiedTextReadable(
            Entity entity)
        {
            if (entity is DBText dbText)
            {
                dbText.Rotation =
                    GetReadableTemplateTextRotation(
                        dbText.Rotation);
            }
            else if (entity is MText mText)
            {
                mText.Rotation =
                    GetReadableTemplateTextRotation(
                        mText.Rotation);
            }
        }

        private int ReplaceTemplateRawTargetLineWithShop(
            Transaction tr,
            BlockTableRecord targetSpace,
            Curve targetCurve,
            Curve sourceReferenceCurve,
            Matrix3d transform)
        {
            if (tr == null ||
                targetSpace == null ||
                targetCurve == null ||
                sourceReferenceCurve == null)
            {
                return 0;
            }

            // FIX40L:
            // Chế độ SHOP phải THAY line/tim gốc bằng bộ SHOP.
            // Không để line gốc nằm giữa 2 nét SHOP như FIX40K.
            //
            // Hiện bản vẽ đầu vào của user dùng LINE cho tim nhánh,
            // nên xử lý LINE thật chắc trước. Curve khác không xóa bừa.
            if (!(targetCurve is Line sourceLine))
                return 0;

            try
            {
                Point3d appliedStart =
                    sourceReferenceCurve
                        .StartPoint
                        .TransformBy(transform);

                Point3d appliedEnd =
                    sourceReferenceCurve
                        .EndPoint
                        .TransformBy(transform);

                Point3d lineStart =
                    sourceLine.StartPoint;

                Point3d lineEnd =
                    sourceLine.EndPoint;

                Vector3d lineVector =
                    lineEnd -
                    lineStart;

                if (lineVector.Length < 1e-6)
                    return 0;

                double lengthSquared =
                    lineVector.DotProduct(
                        lineVector);

                if (lengthSquared < 1e-9)
                    return 0;

                double GetParameter(Point3d point)
                {
                    return
                        (point - lineStart)
                            .DotProduct(lineVector) /
                        lengthSquared;
                }

                double t0 =
                    GetParameter(
                        appliedStart);

                double t1 =
                    GetParameter(
                        appliedEnd);

                double low =
                    Math.Max(
                        0.0,
                        Math.Min(
                            t0,
                            t1));

                double high =
                    Math.Min(
                        1.0,
                        Math.Max(
                            t0,
                            t1));

                if (high <= low)
                    return 0;

                double sourceLength =
                    lineVector.Length;

                double removedLength =
                    (high - low) *
                    sourceLength;

                if (removedLength < 5.0)
                    return 0;

                Point3d cutLow =
                    lineStart +
                    lineVector *
                    low;

                Point3d cutHigh =
                    lineStart +
                    lineVector *
                    high;

                int residualCount = 0;

                // Giữ phần line TRƯỚC vùng SHOP nếu có.
                if (low * sourceLength >
                    5.0)
                {
                    Line before =
                        sourceLine.Clone()
                            as Line;

                    if (before != null)
                    {
                        before.StartPoint =
                            lineStart;

                        before.EndPoint =
                            cutLow;

                        targetSpace.AppendEntity(
                            before);

                        tr.AddNewlyCreatedDBObject(
                            before,
                            true);

                        residualCount++;
                    }
                }

                // Giữ phần line SAU vùng SHOP nếu có.
                if ((1.0 - high) *
                    sourceLength >
                    5.0)
                {
                    Line after =
                        sourceLine.Clone()
                            as Line;

                    if (after != null)
                    {
                        after.StartPoint =
                            cutHigh;

                        after.EndPoint =
                            lineEnd;

                        targetSpace.AppendEntity(
                            after);

                        tr.AddNewlyCreatedDBObject(
                            after,
                            true);

                        residualCount++;
                    }
                }

                if (!sourceLine.IsWriteEnabled)
                    sourceLine.UpgradeOpen();

                sourceLine.Erase();

                try
                {
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .DocumentManager
                        .MdiActiveDocument?
                        .Editor
                        .WriteMessage(
                            $"\n[{TemplateAutoDrawBuild}] " +
                            $"Đã thay LINE gốc bằng SHOP: " +
                            $"xóa đoạn {removedLength:0.##} mm, " +
                            $"giữ {residualCount} đoạn ngoài.");
                }
                catch
                {
                }

                return 1;
            }
            catch
            {
                return 0;
            }
        }


        private List<TextData> CollectTemplateShopTextsNearCurve(
            PipeUiContext ctx,
            Transaction tr,
            IEnumerable<Entity> entities,
            Curve branchCurve,
            double maxPlanDistance)
        {
            List<TextData> result =
                new List<TextData>();

            if (branchCurve == null)
                return result;

            if (!TryGetTemplatePlanDirection(
                    branchCurve,
                    out Vector3d direction))
            {
                return result;
            }

            Point3d origin =
                branchCurve.StartPoint;

            double span =
                GetTemplateSignedStation(
                    branchCurve.EndPoint,
                    origin,
                    direction);

            if (span < 0.0)
            {
                direction =
                    direction.Negate();

                span =
                    -span;
            }

            double stationPadding =
                500.0;

            Action<string, Point3d, double> tryAdd =
                (rawText, position, rotation) =>
                {
                    Point3d closest;

                    double planDistance;

                    if (!TryGetClosestPointInPlan(
                            branchCurve,
                            position,
                            out closest,
                            out planDistance))
                    {
                        return;
                    }

                    if (planDistance >
                        maxPlanDistance)
                    {
                        return;
                    }

                    double station =
                        GetTemplateSignedStation(
                            closest,
                            origin,
                            direction);

                    if (station <
                            -stationPadding ||
                        station >
                            span +
                            stationPadding)
                    {
                        return;
                    }

                    int before =
                        result.Count;

                    TryAddShopPipeSizeText(
                        ctx,
                        rawText,
                        position,
                        rotation,
                        result);

                    // Nếu text không song song với branch thì MapTextsToOriginalCurves
                    // sẽ loại tiếp. Ở đây chỉ giới hạn theo hành lang.
                };

            foreach (Entity entity in
                entities ??
                Enumerable.Empty<Entity>())
            {
                if (entity == null)
                    continue;

                if (entity is DBText dbText)
                {
                    Point3d pt =
                        (dbText.Justify !=
                            AttachmentPoint.BaseLeft &&
                         (dbText.AlignmentPoint.X != 0.0 ||
                          dbText.AlignmentPoint.Y != 0.0))
                            ? dbText.AlignmentPoint
                            : dbText.Position;

                    tryAdd(
                        dbText.TextString,
                        pt,
                        dbText.Rotation);

                    continue;
                }

                if (entity is MText mText)
                {
                    tryAdd(
                        mText.Text,
                        mText.Location,
                        mText.Rotation);

                    continue;
                }

                if (entity is BlockReference blockReference)
                {
                    foreach (ObjectId attId
                        in blockReference.AttributeCollection)
                    {
                        AttributeReference att =
                            tr.GetObject(
                                attId,
                                OpenMode.ForRead,
                                false)
                                as AttributeReference;

                        if (att == null)
                            continue;

                        tryAdd(
                            att.TextString,
                            att.Position,
                            att.Rotation);
                    }
                }
            }

            return result;
        }

        private List<Point3d> CollectTemplateShopSprinklersNearCurve(
            Transaction tr,
            IEnumerable<Entity> entities,
            Curve branchCurve,
            double maxPlanDistance)
        {
            List<Point3d> result =
                new List<Point3d>();

            if (branchCurve == null)
                return result;

            if (!TryGetTemplatePlanDirection(
                    branchCurve,
                    out Vector3d direction))
            {
                return result;
            }

            Point3d origin =
                branchCurve.StartPoint;

            double span =
                GetTemplateSignedStation(
                    branchCurve.EndPoint,
                    origin,
                    direction);

            if (span < 0.0)
            {
                direction =
                    direction.Negate();

                span =
                    -span;
            }

            double stationPadding =
                650.0;

            Action<Point3d> tryAdd =
                center =>
                {
                    if (!TryGetClosestPointInPlan(
                            branchCurve,
                            center,
                            out Point3d closest,
                            out double planDistance))
                    {
                        return;
                    }

                    if (planDistance >
                        maxPlanDistance)
                    {
                        return;
                    }

                    double station =
                        GetTemplateSignedStation(
                            closest,
                            origin,
                            direction);

                    if (station <
                            -stationPadding ||
                        station >
                            span +
                            stationPadding)
                    {
                        return;
                    }

                    AddUniquePoint(
                        result,
                        center,
                        5.0);
                };

            foreach (Entity entity in
                entities ??
                Enumerable.Empty<Entity>())
            {
                if (entity == null ||
                    IsTemplateShopFitting(entity))
                {
                    continue;
                }

                if (entity is Circle circle)
                {
                    tryAdd(circle.Center);
                    continue;
                }

                if (entity is BlockReference blockReference)
                {
                    foreach (Point3d center in
                        GetCircularCentersFromBlock(
                            tr,
                            blockReference))
                    {
                        tryAdd(center);
                    }

                    if (IsLikelyShopSprinklerBlock(
                            tr,
                            blockReference))
                    {
                        tryAdd(
                            blockReference.Position);
                    }
                }
            }

            return result;
        }

        private int DrawTemplateShopUsingRealShopEngine(
            Transaction tr,
            Database db,
            BlockTableRecord targetSpace,
            List<Entity> targetEntities,
            Curve rawTargetCurve,
            Curve sourceReferenceCurve,
            Matrix3d transform,
            out int fittingCount,
            out int erasedRawCount)
        {
            fittingCount = 0;
            erasedRawCount = 0;

            if (tr == null ||
                db == null ||
                targetSpace == null ||
                targetEntities == null ||
                rawTargetCurve == null ||
                sourceReferenceCurve == null)
            {
                return 0;
            }

            // ========================================================
            // FIX40M:
            // KHÔNG clone 2 nét SHOP của mẫu nữa.
            //
            // Mẫu chỉ dùng để tìm đúng nhánh target.
            // Sau đó dựng một TIM target đúng theo span mẫu đã match,
            // rồi chạy CHÍNH ENGINE VẼ SHOP đang dùng ở nút VẼ SHOP ỐNG.
            // ========================================================
            Point3d targetStart =
                sourceReferenceCurve
                    .StartPoint
                    .TransformBy(transform);

            Point3d targetEnd =
                sourceReferenceCurve
                    .EndPoint
                    .TransformBy(transform);

            if (targetStart.DistanceTo(
                    targetEnd) <
                5.0)
            {
                return 0;
            }

            using (Line branchCurve =
                new Line(
                    targetStart,
                    targetEnd))
            {
                // Giữ layer line gốc để còn fallback nhận DN từ layer.
                try
                {
                    branchCurve.Layer =
                        rawTargetCurve.Layer;
                }
                catch
                {
                }

                PipeUiContext ctx =
                    _ctxFF;

                List<TextData> texts =
                    CollectTemplateShopTextsNearCurve(
                        ctx,
                        tr,
                        targetEntities,
                        branchCurve,
                        1200.0);

                Dictionary<Curve, List<TextProjectionData>>
                    textMap =
                        MapTextsToOriginalCurves(
                            new List<Curve>
                            {
                                branchCurve
                            },
                            texts);

                List<ShopPipeCandidate> shopPipes =
                    new List<ShopPipeCandidate>();

                if (textMap.TryGetValue(
                        branchCurve,
                        out List<TextProjectionData> projections) &&
                    projections != null &&
                    projections.Count > 0)
                {
                    List<ShopPipeCandidate> splitCandidates =
                        CreateShopSplitCandidatesFromTexts(
                            branchCurve,
                            projections);

                    if (splitCandidates.Count > 0)
                    {
                        shopPipes.AddRange(
                            splitCandidates);
                    }
                    else
                    {
                        TextProjectionData best =
                            projections
                                .OrderBy(x => x.MatchScore)
                                .ThenBy(
                                    x => x.DistanceAlongCurve)
                                .First();

                        ShopPipeCandidate candidate =
                            CreateShopPipeCandidate(
                                branchCurve,
                                best.Text.TextString,
                                best.Text.Width);

                        if (candidate != null)
                            shopPipes.Add(candidate);
                    }
                }

                // Fallback theo layer target nếu khu vực không quét trúng chữ DN.
                if (shopPipes.Count == 0 &&
                    TryParseAutomaticPipeSize(
                        ctx,
                        rawTargetCurve.Layer,
                        out string layerSize,
                        out double layerWidth))
                {
                    ShopPipeCandidate candidate =
                        CreateShopPipeCandidate(
                            branchCurve,
                            layerSize,
                            layerWidth);

                    if (candidate != null)
                        shopPipes.Add(candidate);
                }

                if (shopPipes.Count == 0)
                {
                    try
                    {
                        Autodesk.AutoCAD.ApplicationServices.Core.Application
                            .DocumentManager
                            .MdiActiveDocument?
                            .Editor
                            .WriteMessage(
                                $"\n[{TemplateAutoDrawBuild}] " +
                                "Bỏ nhánh: không nhận được DN trên target.");
                    }
                    catch
                    {
                    }

                    return 0;
                }

                List<Point3d> sprinklerCenters =
                    CollectTemplateShopSprinklersNearCurve(
                        tr,
                        targetEntities,
                        branchCurve,
                        1200.0);

                string shopMaterial =
                    InferShopMaterialFromPipes(
                        shopPipes,
                        GetSelectedPipeMaterialName(
                            ctx));

                string shopLibraryPath =
                    FindShopFittingLibraryPath(
                        shopMaterial,
                        db);

                List<ShopFittingGapInfo> fittingGaps =
                    new List<ShopFittingGapInfo>();

                int reducerCount;
                int elbow90Count;
                int elbow45Count;
                int teeCount;
                int sprinklerElbowCount;

                fittingCount =
                    DrawSmartShopFittings(
                        tr,
                        db,
                        targetSpace,
                        shopPipes,
                        sprinklerCenters,
                        shopLibraryPath,
                        fittingGaps,
                        out reducerCount,
                        out elbow90Count,
                        out elbow45Count,
                        out teeCount,
                        out sprinklerElbowCount);

                int edgeCount = 0;

                foreach (ShopPipeCandidate pipe
                    in shopPipes)
                {
                    EnsureShopLayerExists(
                        tr,
                        db,
                        pipe.LayerName);

                    edgeCount +=
                        DrawShopParallelPipeWithGaps(
                            tr,
                            db,
                            targetSpace,
                            pipe,
                            fittingGaps);
                }

                if (edgeCount <= 0)
                    return 0;

                // Chỉ sau khi engine SHOP đã vẽ thành công mới bỏ line gốc.
                erasedRawCount =
                    ReplaceTemplateRawTargetLineWithShop(
                        tr,
                        targetSpace,
                        rawTargetCurve,
                        sourceReferenceCurve,
                        transform);

                try
                {
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .DocumentManager
                        .MdiActiveDocument?
                        .Editor
                        .WriteMessage(
                            $"\n[{TemplateAutoDrawBuild}] REAL-SHOP: " +
                            $"edge={edgeCount}, fitting={fittingCount}, " +
                            $"DN-segment={shopPipes.Count}, " +
                            $"raw-replaced={erasedRawCount}.");
                }
                catch
                {
                }

                return edgeCount;
            }
        }


        private void BtnAutoDrawByTemplate_Click(
            object sender,
            RoutedEventArgs e)
        {
            Document doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            Editor ed = doc.Editor;
            Database db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            TypedValue[] filterValues =
                new TypedValue[]
                {
                    new TypedValue(
                        (int)DxfCode.Operator,
                        "<OR"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "LINE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "LWPOLYLINE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "POLYLINE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "ARC"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "TEXT"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "MTEXT"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "INSERT"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "CIRCLE"),
                    new TypedValue(
                        (int)DxfCode.Operator,
                        "OR>")
                };

            SelectionFilter selectionFilter =
                new SelectionFilter(filterValues);

            PromptSelectionOptions sampleOptions =
                new PromptSelectionOptions();

            sampleOptions.MessageForAdding =
                "\nBƯỚC 1 - Quét chọn NHÁNH MẪU " +
                "(mẫu thường HOẶC mẫu SHOP 2 nét + phụ kiện): ";

            PromptSelectionResult sampleResult =
                ed.GetSelection(
                    sampleOptions,
                    selectionFilter);

            if (sampleResult.Status != PromptStatus.OK ||
                sampleResult.Value.Count == 0)
            {
                return;
            }

            PromptSelectionOptions targetOptions =
                new PromptSelectionOptions();

            targetOptions.MessageForAdding =
                "\nBƯỚC 2 - Quét KHU VỰC line/tim gốc " +
                "cần tìm các nhánh tương tự để áp mẫu: ";

            PromptSelectionResult targetResult =
                ed.GetSelection(
                    targetOptions,
                    selectionFilter);

            if (targetResult.Status != PromptStatus.OK ||
                targetResult.Value.Count == 0)
            {
                return;
            }

            Curve virtualReferenceCurve = null;
            Curve markerBoundReferenceCurve = null;

            try
            {
                using (doc.LockDocument())
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    List<Entity> sampleEntities =
                        sampleResult.Value
                            .GetObjectIds()
                            .Select(
                                id => tr.GetObject(
                                    id,
                                    OpenMode.ForRead,
                                    false) as Entity)
                            .Where(
                                entity => entity != null)
                            .ToList();

                    List<Entity> targetEntities =
                        targetResult.Value
                            .GetObjectIds()
                            .Select(
                                id => tr.GetObject(
                                    id,
                                    OpenMode.ForRead,
                                    false) as Entity)
                            .Where(
                                entity => entity != null)
                            .ToList();

                    List<Curve> samplePipeCurves =
                        sampleEntities
                            .OfType<Curve>()
                            .Where(IsTemplatePipeCurve)
                            .ToList();

                    List<Curve> sampleShopCenterlines =
                        sampleEntities
                            .OfType<Curve>()
                            .Where(
                                IsTemplateShopCenterline)
                            .ToList();

                    bool isShopTemplate =
                        samplePipeCurves.Any(
                            IsTemplateShopPipeEdge) ||
                        sampleEntities.Any(
                            IsTemplateShopFitting) ||
                        sampleShopCenterlines.Count > 0;

                    if (samplePipeCurves.Count == 0)
                    {
                        MessageBox.Show(
                            "Không tìm thấy ống mẫu đã vẽ.\n\n" +
                            "Mẫu thường: chọn Polyline ống có bề rộng.\n" +
                            "Mẫu SHOP: chọn đủ 2 nét FF_SHOP_DN... " +
                            "và phụ kiện/tim SHOP nếu có.",
                            "Vẽ ống tự động theo mẫu");

                        return;
                    }

                    HashSet<string> templatePipeLayers =
                        new HashSet<string>(
                            samplePipeCurves.Select(
                                curve => curve.Layer),
                            StringComparer.OrdinalIgnoreCase);

                    List<Entity> templateEntitiesToCopy;

                    if (isShopTemplate)
                    {
                        templateEntitiesToCopy =
                            sampleEntities
                                .Where(
                                    entity =>
                                        IsTemplateShopOutputEntity(
                                            entity))
                                .ToList();
                    }
                    else
                    {
                        templateEntitiesToCopy =
                            sampleEntities
                                .Where(
                                    entity =>
                                        (entity is Curve curve &&
                                         samplePipeCurves.Contains(
                                             curve)) ||
                                        ((entity is DBText ||
                                          entity is MText) &&
                                         templatePipeLayers.Contains(
                                             entity.Layer)))
                                .ToList();
                    }

                    List<Curve> sampleContextCurves =
                        sampleEntities
                            .Where(IsTemplateReferenceCurve)
                            .Cast<Curve>()
                            .ToList();

                    List<Curve> sampleSourceCurves =
                        sampleContextCurves
                            .Where(
                                curve =>
                                    !samplePipeCurves.Contains(
                                        curve) &&
                                    !IsTemplateShopCenterline(
                                        curve))
                            .ToList();

                    Curve sourceReferenceCurve =
                        null;

                    if (isShopTemplate)
                    {
                        sourceReferenceCurve =
                            SelectShopTemplateReferenceCurve(
                                sampleShopCenterlines,
                                samplePipeCurves,
                                sampleContextCurves);
                    }
                    else if (sampleSourceCurves.Count > 0)
                    {
                        sourceReferenceCurve =
                            SelectTemplateReferenceCurve(
                                sampleSourceCurves,
                                samplePipeCurves);
                    }

                    if (isShopTemplate)
                    {
                        if (sourceReferenceCurve == null)
                        {
                            virtualReferenceCurve =
                                BuildVirtualTemplateCenterlineFromShopEdges(
                                    samplePipeCurves);
                        }
                    }
                    else
                    {
                        virtualReferenceCurve =
                            BuildVirtualTemplateCenterline(
                                samplePipeCurves);
                    }

                    Curve referenceCurve;

                    if (isShopTemplate)
                    {
                        referenceCurve =
                            sourceReferenceCurve ??
                            virtualReferenceCurve;
                    }
                    else
                    {
                        referenceCurve =
                            SelectUsableTemplateReferenceCurve(
                                sourceReferenceCurve,
                                virtualReferenceCurve,
                                samplePipeCurves);
                    }

                    if (isShopTemplate &&
                        referenceCurve != null)
                    {
                        templateEntitiesToCopy =
                            FilterShopTemplateEntitiesToReferenceBranch(
                                referenceCurve,
                                sampleEntities,
                                samplePipeCurves);
                    }

                    if (referenceCurve == null ||
                        templateEntitiesToCopy.Count == 0)
                    {
                        MessageBox.Show(
                            "Không dựng được TIM của nhánh mẫu.\n\n" +
                            "Nếu là mẫu SHOP, hãy quét đủ 2 nét song song " +
                            "của cùng DN và FF_SHOP_TAM_* nếu đang có.\n" +
                            "Nếu là mẫu thường, hãy quét đủ ống mẫu.",
                            "Vẽ ống tự động theo mẫu");

                        return;
                    }

                    List<Point3d> allSampleMarkers =
                        isShopTemplate
                            ? CollectTemplateShopMarkerCenters(
                                tr,
                                sampleEntities)
                            : CollectTemplateMarkerCenters(
                                tr,
                                sampleEntities);

                    List<Point3d> sampleMarkers =
                        GetTemplateMarkersNearCurve(
                            referenceCurve,
                            allSampleMarkers);

                    bool strictShopSelectionSpan =
                        false;

                    if (isShopTemplate &&
                        sampleMarkers.Count >= 2)
                    {
                        markerBoundReferenceCurve =
                            BuildTemplateMarkerBoundReferenceCurve(
                                referenceCurve,
                                sampleMarkers);

                        if (markerBoundReferenceCurve != null)
                        {
                            referenceCurve =
                                markerBoundReferenceCurve;

                            strictShopSelectionSpan =
                                true;

                            sampleMarkers =
                                GetTemplateMarkersNearCurve(
                                    referenceCurve,
                                    allSampleMarkers);

                            // Sau khi khóa span bằng đúng marker nằm trong vùng quét,
                            // lọc lại bộ SHOP theo reference mới.
                            templateEntitiesToCopy =
                                FilterShopTemplateEntitiesToReferenceBranch(
                                    referenceCurve,
                                    sampleEntities,
                                    samplePipeCurves);
                        }
                    }

                    int sourceRootIndex =
                        strictShopSelectionSpan
                            ? -1
                            : FindTemplateBranchRootIndex(
                                referenceCurve,
                                sampleContextCurves);

                    List<Curve> targetSourceCurves =
                        targetEntities
                            .Where(IsTemplateReferenceCurve)
                            .Cast<Curve>()
                            .Where(
                                curve =>
                                    !IsTemplatePipeCurve(curve) &&
                                    !IsTemplateShopCenterline(
                                        curve))
                            .ToList();

                    List<Curve> existingTargetPipeCurves =
                        targetEntities
                            .OfType<Curve>()
                            .Where(IsTemplatePipeCurve)
                            .ToList();

                    List<Point3d> allTargetMarkers =
                        isShopTemplate
                            ? CollectTemplateShopMarkerCenters(
                                tr,
                                targetEntities)
                            : CollectTemplateMarkerCenters(
                                tr,
                                targetEntities);

                    if (targetSourceCurves.Count == 0)
                    {
                        MessageBox.Show(
                            "Không tìm thấy đường tim nhánh " +
                            "trong khu vực đã quét.",
                            "Vẽ ống tự động theo mẫu");

                        return;
                    }

                    Curve probeCurve;

                    if (isShopTemplate)
                    {
                        Vector3d referenceDirection =
                            Vector3d.XAxis;

                        TryGetTemplatePlanDirection(
                            referenceCurve,
                            out referenceDirection);

                        probeCurve =
                            samplePipeCurves
                                .Where(
                                    curve =>
                                    {
                                        if (!TryGetTemplatePlanDirection(
                                                curve,
                                                out Vector3d d))
                                        {
                                            return false;
                                        }

                                        return Math.Abs(
                                            referenceDirection.DotProduct(d)) >=
                                            0.94;
                                    })
                                .OrderByDescending(
                                    GetTemplateCurveLength)
                                .FirstOrDefault() ??
                            samplePipeCurves
                                .OrderByDescending(
                                    GetTemplateCurveLength)
                                .First();
                    }
                    else
                    {
                        probeCurve =
                            samplePipeCurves
                                .OrderByDescending(
                                    GetTemplateCurveLength)
                                .First();
                    }

                    List<TemplateBranchMatchData> matches =
                        new List<TemplateBranchMatchData>();

                    List<Point3d> acceptedTargetCenters =
                        new List<Point3d>();

                    foreach (Curve targetCurve
                        in targetSourceCurves)
                    {
                        if (referenceCurve.ObjectId !=
                                ObjectId.Null &&
                            targetCurve.ObjectId !=
                                ObjectId.Null &&
                            referenceCurve.ObjectId ==
                                targetCurve.ObjectId)
                        {
                            continue;
                        }

                        List<Point3d> targetMarkers =
                            GetTemplateMarkersNearCurve(
                                targetCurve,
                                allTargetMarkers);

                        int targetRootIndex =
                            FindTemplateBranchRootIndex(
                                targetCurve,
                                targetSourceCurves);

                        Curve targetMatchCurve =
                            targetCurve;

                        Curve temporaryTargetReference =
                            null;

                        if (strictShopSelectionSpan)
                        {
                            // FIX40K:
                            // LINE target có thể dài xuyên ra ngoài khung quét.
                            // Chỉ dùng đoạn từ marker đầu -> marker cuối
                            // thật sự nằm trong SelectionSet của user.
                            if (targetMarkers.Count < 2)
                                continue;

                            temporaryTargetReference =
                                BuildTemplateMarkerBoundReferenceCurve(
                                    targetCurve,
                                    targetMarkers);

                            if (temporaryTargetReference == null)
                                continue;

                            targetMatchCurve =
                                temporaryTargetReference;

                            targetMarkers =
                                GetTemplateMarkersNearCurve(
                                    targetMatchCurve,
                                    allTargetMarkers);

                            targetRootIndex =
                                -1;
                        }
                        else if (isShopTemplate &&
                                 sourceRootIndex >= 0 &&
                                 targetRootIndex < 0)
                        {
                            continue;
                        }

                        bool matched =
                            TryMatchTemplateBranch(
                                referenceCurve,
                                targetMatchCurve,
                                sourceRootIndex,
                                targetRootIndex,
                                sampleMarkers,
                                targetMarkers,
                                out Matrix3d transform,
                                out double score);

                        temporaryTargetReference?.Dispose();

                        if (!matched)
                        {
                            continue;
                        }

                        Point3d targetCenter =
                            GetTemplateCurvePoint(
                                referenceCurve,
                                0.5)
                            .TransformBy(transform);

                        if (acceptedTargetCenters.Any(
                            center =>
                                GetTemplatePlanDistance(
                                    center,
                                    targetCenter) <=
                                TemplateDuplicateTolerance))
                        {
                            continue;
                        }

                        if (HasTemplateOutputAtPlacement(
                            probeCurve,
                            transform,
                            existingTargetPipeCurves))
                        {
                            continue;
                        }

                        acceptedTargetCenters.Add(
                            targetCenter);

                        matches.Add(
                            new TemplateBranchMatchData
                            {
                                TargetCurve = targetCurve,
                                Transform = transform,
                                Score = score,
                                TargetCenter = targetCenter
                            });
                    }

                    if (matches.Count == 0)
                    {
                        MessageBox.Show(
                            "Không tìm thấy nhánh nào đủ giống " +
                            "với nhánh mẫu.\n" +
                            "Hãy quét đủ các đoạn ống khác DN " +
                            "và các đầu phun của nhánh mẫu.",
                            "Vẽ ống tự động theo mẫu");

                        return;
                    }

                    BlockTableRecord targetSpace =
                        tr.GetObject(
                            db.CurrentSpaceId,
                            OpenMode.ForWrite)
                            as BlockTableRecord;

                    int copiedEntityCount = 0;
                    int copiedBranchCount = 0;

                    foreach (
                        TemplateBranchMatchData match
                        in matches.OrderBy(
                            item => item.Score))
                    {
                        if (isShopTemplate)
                        {
                            // ==================================================
                            // FIX40M:
                            // Không copy geometry mẫu.
                            // Chạy engine VẼ SHOP thật trên chính tim target.
                            // ==================================================
                            int targetFittingCount;
                            int targetRawReplaced;

                            int createdEdges =
                                DrawTemplateShopUsingRealShopEngine(
                                    tr,
                                    db,
                                    targetSpace,
                                    targetEntities,
                                    match.TargetCurve,
                                    referenceCurve,
                                    match.Transform,
                                    out targetFittingCount,
                                    out targetRawReplaced);

                            if (createdEdges > 0)
                            {
                                copiedBranchCount++;

                                copiedEntityCount +=
                                    createdEdges +
                                    targetFittingCount;
                            }

                            continue;
                        }

                        // ======================================================
                        // MẪU THƯỜNG: giữ nguyên cơ chế clone cũ.
                        // ======================================================
                        int copiedOnCurrentBranch = 0;

                        foreach (
                            Entity templateEntity
                            in templateEntitiesToCopy)
                        {
                            Entity copiedEntity =
                                CloneTemplateEntityInsideReferenceSpan(
                                    templateEntity,
                                    referenceCurve,
                                    false);

                            if (copiedEntity == null)
                                continue;

                            copiedEntity.TransformBy(
                                match.Transform);

                            KeepTemplateCopiedTextReadable(
                                copiedEntity);

                            targetSpace.AppendEntity(
                                copiedEntity);

                            tr.AddNewlyCreatedDBObject(
                                copiedEntity,
                                true);

                            if (copiedEntity
                                is DBText copiedText)
                            {
                                copiedText.AdjustAlignment(db);
                            }

                            copiedEntityCount++;
                            copiedOnCurrentBranch++;
                        }

                        if (copiedOnCurrentBranch > 0)
                            copiedBranchCount++;
                    }

                    tr.Commit();
                    ed.Regen();

                    string templateModeText =
                        isShopTemplate
                            ? "[MẪU SHOP]"
                            : "[MẪU THƯỜNG]";

                    string templateCopiedText =
                        isShopTemplate
                            ? " SHOP dựng lại bằng chính engine VẼ SHOP ỐNG."
                            : " ống/chữ.";

                    ed.WriteMessage(
                        $"\n[{TemplateAutoDrawBuild}] Hoàn tất " +
                        $"{templateModeText}: " +
                        $"đã nhận diện {copiedBranchCount} " +
                        $"nhánh tương tự và sao chép " +
                        $"{copiedEntityCount} đối tượng" +
                        templateCopiedText +
                        (isShopTemplate
                            ? $" | Bộ mẫu sau lọc={templateEntitiesToCopy.Count}" +
                              (strictShopSelectionSpan
                                  ? " | KHÓA THEO MARKER VÙNG QUÉT=YES"
                                  : " | KHÓA THEO MARKER VÙNG QUÉT=NO") +
                              " | THAY LINE GỐC=YES" +
                              " | REAL SHOP ENGINE=YES"
                            : ""));
                }
            }
            catch (System.Exception ex)
            {
                MessageBox.Show(
                    "Không thể vẽ tự động theo mẫu:\n" +
                    ex.Message,
                    "Lỗi");
            }
            finally
            {
                markerBoundReferenceCurve?.Dispose();
                virtualReferenceCurve?.Dispose();
            }
        }

        private void BtnVeOgTuDong_Click(
            object sender,
            RoutedEventArgs e)
        {
            PipeUiContext ctx = _ctxACMV ?? GetContext(sender);
            if (ctx == null)
                ctx = _ctxACMV;

            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var ed = doc.Editor;
            var db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            PromptSelectionOptions pso =
                new PromptSelectionOptions();
            pso.MessageForAdding =
                "\n[VẼ OG TỰ ĐỘNG] Quét chọn vùng có đường ống gió + chữ size (WxH) + tên OG: ";

            TypedValue[] tvs =
                new TypedValue[]
                {
                    new TypedValue((int)DxfCode.Operator, "<OR"),
                    new TypedValue((int)DxfCode.Start, "LINE"),
                    new TypedValue((int)DxfCode.Start, "ARC"),
                    new TypedValue((int)DxfCode.Start, "LWPOLYLINE"),
                    new TypedValue((int)DxfCode.Start, "POLYLINE"),
                    new TypedValue((int)DxfCode.Start, "TEXT"),
                    new TypedValue((int)DxfCode.Start, "MTEXT"),
                    new TypedValue((int)DxfCode.Start, "INSERT"),
                    new TypedValue((int)DxfCode.Operator, "OR>")
                };

            PromptSelectionResult psr =
                ed.GetSelection(pso, new SelectionFilter(tvs));

            if (psr.Status != PromptStatus.OK ||
                psr.Value.Count == 0)
                return;

            var sizeTexts =
                new List<OngGioSizeTextInfo>();
            var protectionTexts =
                new List<OngGioProtectionTextInfo>();
            var ogTypeTexts =
                new List<OngGioTypeTextInfo>();
            var segments =
                new List<OngGioSegmentInfo>();
            var arcs =
                new List<OngGioArcInfo>();
            var candidates =
                new List<OngGioCenterlineCandidate>();

            string layerPrefix = GetOngGioAutoLayerPrefix(ctx);

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (SelectedObject so in psr.Value)
                {
                    if (so == null) continue;
                    Entity ent =
                        tr.GetObject(so.ObjectId, OpenMode.ForRead)
                            as Entity;
                    if (ent == null) continue;

                    if (ent is DBText dbText)
                    {
                        string str = (dbText.TextString ?? "")
                            .Replace("\r", " ").Replace("\n", " ").Trim();
                        Point3d pt = dbText.Position;
                        if (dbText.Justify != AttachmentPoint.BaseLeft &&
                            !(dbText.AlignmentPoint.X == 0 &&
                              dbText.AlignmentPoint.Y == 0))
                            pt = dbText.AlignmentPoint;

                        if (TryParseOngGioSize(
                                str,
                                out string sz,
                                out double sideA,
                                out double sideB,
                                out double w,
                                out string ei))
                        {
                            sizeTexts.Add(
                                new OngGioSizeTextInfo
                                {
                                    Pos = pt,
                                    Size = sz,
                                    SideA = sideA,
                                    SideB = sideB,
                                    Width = w,
                                    Ei = ei
                                });
                        }

                        if (TryParseOngGioProtection(str, out string protect))
                        {
                            protectionTexts.Add(
                                new OngGioProtectionTextInfo
                                {
                                    Pos = pt,
                                    Text = protect
                                });
                        }

                        if (TryParseOngGioType(str, out string ogType))
                        {
                            ogTypeTexts.Add(
                                new OngGioTypeTextInfo
                                {
                                    Pos = pt,
                                    Type = ogType
                                });
                        }
                    }
                    else if (ent is MText mText)
                    {
                        string str =
                            LayPlainTextTuMText(mText.Contents);
                        Point3d pt = mText.Location;

                        if (TryParseOngGioSize(
                                str,
                                out string sz,
                                out double sideA,
                                out double sideB,
                                out double w,
                                out string ei))
                        {
                            sizeTexts.Add(
                                new OngGioSizeTextInfo
                                {
                                    Pos = pt,
                                    Size = sz,
                                    SideA = sideA,
                                    SideB = sideB,
                                    Width = w,
                                    Ei = ei
                                });
                        }

                        if (TryParseOngGioProtection(str, out string protect))
                        {
                            protectionTexts.Add(
                                new OngGioProtectionTextInfo
                                {
                                    Pos = pt,
                                    Text = protect
                                });
                        }

                        if (TryParseOngGioType(str, out string ogType))
                        {
                            ogTypeTexts.Add(
                                new OngGioTypeTextInfo
                                {
                                    Pos = pt,
                                    Type = ogType
                                });
                        }
                    }
                    else if (ent is Entity src)
                    {
                        bool hasClosedCandidate =
                            TryCreateOngGioCandidateFromRectangle(
                                src,
                                out OngGioCenterlineCandidate closedCandidate);

                        if (hasClosedCandidate)
                        {
                            candidates.Add(closedCandidate);
                        }

                        if (!hasClosedCandidate)
                            AddOngGioSegmentsFromEntity(src, segments);

                        AddOngGioArcFromEntity(src, arcs);
                    }
                }

                tr.Commit();
            }

            if (sizeTexts.Count == 0)
            {
                MessageBox.Show(
                    "Không tìm thấy chữ kích thước ống gió (dạng 500x200, 800x300...).",
                    "Cảnh báo");
                return;
            }

            candidates.AddRange(
                CreateOngGioCandidatesFromParallelSegments(segments));
            candidates.AddRange(
                CreateReducerCandidatesFromEndSegments(segments));
            List<OngGioCenterlineCandidate> arcCandidates =
                CreateOngGioCandidatesFromConcentricArcs(arcs);
            arcCandidates.AddRange(
                CreateTerminalOngGioCandidatesFromSingleArcs(
                    arcs,
                    arcCandidates,
                    candidates,
                    segments));
            candidates.AddRange(arcCandidates);
            candidates =
                RemoveShortStraightCandidatesNearArcs(
                    candidates,
                    arcCandidates);

            candidates =
                RemoveOrTrimCandidatesAtReducers(candidates);

            candidates =
                RemoveDuplicateOngGioCandidates(candidates)
                    .Where(x => x != null && x.Length > 100.0)
                    .ToList();

            ExtendBranchCandidatesToNearbyMainDucts(candidates);

            candidates =
                candidates
                    .Where(x =>
                        x != null &&
                        !IsOngGioCandidateBlockedByInternalMark(
                            x,
                            segments))
                    .ToList();

            if (candidates.Count == 0)
            {
                MessageBox.Show(
                    "Không nhận diện được khung ống gió hình chữ nhật trong vùng chọn.\n" +
                    "Hãy quét gồm 4 cạnh LINE/POLYLINE hoặc closed polyline của ống gió, kèm chữ size dạng 500x200.",
                    "Cảnh báo");
                return;
            }

            int converted = 0;
            string defaultOg =
                ogTypeTexts.Count > 0
                    ? ogTypeTexts[0].Type
                    : "OG THẢI";

            ResolveOngGioCandidateMetadata(
                candidates,
                sizeTexts,
                protectionTexts,
                ogTypeTexts,
                defaultOg);

            PropagateConnectedStraightMetadataToArcs(candidates);

            candidates =
                MergeConnectedSameLayerCandidates(
                    candidates);

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                BlockTableRecord btr =
                    (BlockTableRecord)tr.GetObject(
                        db.CurrentSpaceId, OpenMode.ForWrite);

                foreach (OngGioCenterlineCandidate candidate in candidates)
                {
                    if (candidate == null ||
                        candidate.Length <= 100.0)
                        continue;

                    if (IsOngGioCandidateBlockedByInternalMark(
                            candidate,
                            segments))
                        continue;

                    OngGioSizeTextInfo sizeInfo =
                        candidate.ResolvedSizeInfo ??
                        FindNearestOngGioSizeText(
                            candidate,
                            sizeTexts);

                    if (sizeInfo == null)
                        continue;

                    string size = sizeInfo.Size;
                    double width = sizeInfo.Width;
                    string eiPart =
                        candidate.ResolvedProtection;

                    if (string.IsNullOrWhiteSpace(eiPart))
                        eiPart = sizeInfo.Ei;

                    if (string.IsNullOrWhiteSpace(eiPart))
                    {
                        OngGioProtectionTextInfo protectInfo =
                            FindNearestOngGioProtectionText(
                                candidate,
                                protectionTexts);
                        if (protectInfo != null)
                            eiPart = protectInfo.Text;
                    }

                    if (width <= 0)
                        width = LayWidthTuSize(size);
                    if (width <= 0)
                        width = candidate.DuctWidth;
                    if (width <= 0)
                        width = 100.0;

                    string ogType =
                        string.IsNullOrWhiteSpace(
                            candidate.ResolvedOgType)
                            ? defaultOg
                            : candidate.ResolvedOgType;

                    if (string.IsNullOrWhiteSpace(
                            candidate.ResolvedOgType))
                    {
                        OngGioTypeTextInfo typeInfo =
                            FindNearestOngGioTypeText(
                                candidate,
                                ogTypeTexts);
                        if (typeInfo != null &&
                            !string.IsNullOrWhiteSpace(typeInfo.Type))
                        {
                            ogType = typeInfo.Type;
                        }
                    }

                    string sizeForLayer = size;
                    if (!string.IsNullOrWhiteSpace(eiPart))
                        sizeForLayer = size + "_" + eiPart;

                    string layerName =
                        $"{layerPrefix}_{CleanLayerText(ogType)}_{CleanLayerText(sizeForLayer)}";

                    EnsureLayerExists(tr, db, layerName, true);

                    if (candidate.IsReducer)
                    {
                        converted += DrawReducerCandidate(
                            tr,
                            db,
                            btr,
                            candidate,
                            sizeTexts,
                            protectionTexts,
                            candidates,
                            ogType,
                            layerPrefix);
                    }
                    else
                    {
                        Polyline newPl =
                            CreatePolylineFromOngGioCandidate(candidate);
                        if (newPl == null)
                            continue;

                        newPl.SetDatabaseDefaults(db);
                        newPl.Layer = layerName;
                        newPl.ColorIndex = 256;
                        newPl.ConstantWidth = width;

                        btr.AppendEntity(newPl);
                        tr.AddNewlyCreatedDBObject(newPl, true);

                        if (TryGetOngGioLabelPlacement(
                                candidate,
                                out Point3d labelPoint,
                                out Vector3d labelDirection,
                                out double labelSegmentLength) &&
                            labelSegmentLength >=
                                Math.Max(width * 2.0, 1500.0))
                        {
                            AddOngGioLabel(
                                tr,
                                db,
                                btr,
                                layerName,
                                BuildOngGioDisplayText(size, eiPart),
                                width,
                                labelPoint,
                                labelDirection);
                        }

                        converted++;
                    }
                }

                tr.Commit();
            }

            ed.Regen();
            ed.WriteMessage(
                $"\n[VẼ OG TỰ ĐỘNG] Đã tạo {converted} đường tâm ống gió " +
                $"từ khung chữ nhật. Độ dày = cạnh lớn nhất của size, layer gốc: {layerPrefix}.");
        }

