        private string GetOngGioAutoLayerPrefix(PipeUiContext ctx)
        {
            string systemCode = CleanLayerText(GetSystemCode(ctx));
            if (string.IsNullOrWhiteSpace(systemCode))
                systemCode = "ACMV";

            string viTri = GetViTriText("ACMV");
            if (!string.IsNullOrWhiteSpace(viTri))
                return $"{systemCode}_{viTri}";

            return systemCode;
        }

        private static string LayPlainTextTuMText(string contents)
        {
            string str = contents ?? "";
            str = str.Replace("\\P", " ");
            str = Regex.Replace(str, @"\\[A-Za-z][^;]*;", "");
            str = Regex.Replace(str, @"[{}]", "");
            str = str.Replace("\r", " ").Replace("\n", " ");

            if (str.Contains(";"))
            {
                string[] parts = str.Split(';');
                str = parts.Length > 0 ? parts[parts.Length - 1] : str;
            }

            return Regex.Replace(str, @"\s+", " ").Trim();
        }

        private bool TryParseOngGioSize(
            string source,
            out string sizeText,
            out double sideA,
            out double sideB,
            out double width,
            out string eiText)
        {
            sizeText = "";
            sideA = 0;
            sideB = 0;
            width = 0;
            eiText = "";
            if (string.IsNullOrWhiteSpace(source))
                return false;

            string n = source.ToUpperInvariant()
                .Replace(',', '.')
                .Replace('×', 'X')
                .Replace('Х', 'X');

            Match m = Regex.Match(
                n,
                @"(?<![A-Z0-9])(?<A>\d{2,4}(?:\.\d+)?)\s*[xX×*/\/\-]\s*(?<B>\d{2,4}(?:\.\d+)?)(?![A-Z0-9])");

            if (!m.Success)
                return false;

            if (!double.TryParse(
                    m.Groups["A"].Value,
                    NumberStyles.Any,
                    CultureInfo.InvariantCulture,
                    out double a) ||
                !double.TryParse(
                    m.Groups["B"].Value,
                    NumberStyles.Any,
                    CultureInfo.InvariantCulture,
                    out double b))
                return false;

            if (a < 50 || b < 50 || a > 5000 || b > 5000)
                return false;

            sizeText =
                FormatSizeNumber(a) + "x" + FormatSizeNumber(b);
            sideA = a;
            sideB = b;
            // Bề rộng nét = cạnh LỚN (900x300 → 900)
            width = Math.Max(a, b);

            Match ei = Regex.Match(
                n,
                @"\b(?<K>EI|CN)\s*(?<E>\d{0,3})\b");
            if (ei.Success)
                eiText =
                    ei.Groups["K"].Value +
                    ei.Groups["E"].Value;

            return true;
        }

        private bool TryParseOngGioProtection(
            string source,
            out string protectionText)
        {
            protectionText = "";

            if (string.IsNullOrWhiteSpace(source))
                return false;

            string n = source.ToUpperInvariant()
                .Replace("\r", " ")
                .Replace("\n", " ");

            Match m = Regex.Match(
                n,
                @"\b(?<K>EI|CN)\s*(?<E>\d{0,3})\b");

            if (!m.Success)
                return false;

            protectionText =
                m.Groups["K"].Value +
                m.Groups["E"].Value;

            return !string.IsNullOrWhiteSpace(protectionText);
        }

        private bool TryCreateOngGioCandidateFromRectangle(
            Entity src,
            out OngGioCenterlineCandidate candidate)
        {
            candidate = null;

            try
            {
                if (src is Polyline pl)
                {
                    if (PolylineHasArcSegments(pl))
                        return false;

                    List<Point3d> pts =
                        GetPolylineVerticesForOngGio(pl);

                    return TryCreateOngGioCandidateFromPointLoop(
                        pts,
                        "RECT-PL",
                        out candidate);
                }
            }
            catch { }

            return false;
        }

        private static bool PolylineHasArcSegments(
            Polyline pl)
        {
            if (pl == null || pl.NumberOfVertices < 2)
                return false;

            int segmentCount =
                pl.Closed
                    ? pl.NumberOfVertices
                    : pl.NumberOfVertices - 1;

            for (int i = 0; i < segmentCount; i++)
            {
                if (Math.Abs(pl.GetBulgeAt(i)) > 1e-9)
                    return true;
            }

            return false;
        }

        private static List<Point3d> GetPolylineVerticesForOngGio(
            Polyline pl)
        {
            var pts = new List<Point3d>();
            if (pl == null)
                return pts;

            for (int i = 0; i < pl.NumberOfVertices; i++)
            {
                Point3d p = pl.GetPoint3dAt(i);
                if (pts.Count == 0 ||
                    pts[pts.Count - 1].DistanceTo(p) > 1e-6)
                {
                    pts.Add(p);
                }
            }

            if (pts.Count > 1 &&
                pts[0].DistanceTo(pts[pts.Count - 1]) < 50.0)
            {
                pts.RemoveAt(pts.Count - 1);
            }

            if (!pl.Closed &&
                pts.Count >= 2 &&
                pts[0].DistanceTo(pts[pts.Count - 1]) >= 50.0)
            {
                pts.Clear();
            }

            return pts;
        }

        private bool TryCreateOngGioCandidateFromPointLoop(
            List<Point3d> pts,
            string source,
            out OngGioCenterlineCandidate candidate)
        {
            candidate = null;

            if (pts == null || pts.Count != 4)
                return false;

            double[] len = new double[4];
            Vector3d[] dir = new Vector3d[4];

            for (int i = 0; i < 4; i++)
            {
                Point3d a = pts[i];
                Point3d b = pts[(i + 1) % 4];
                Vector3d v = b - a;
                len[i] = v.Length;

                if (len[i] < 50.0)
                    return false;

                dir[i] = v.GetNormal();
            }

            double avg02 = (len[0] + len[2]) / 2.0;
            double avg13 = (len[1] + len[3]) / 2.0;

            bool pair02Parallel = AreParallel(dir[0], dir[2], 15.0);
            bool pair13Parallel = AreParallel(dir[1], dir[3], 15.0);

            if (!pair02Parallel && !pair13Parallel)
                return false;

            Point3d start;
            Point3d end;
            double ductWidth;
            double startWidth;
            double endWidth;

            bool use02AsEnds =
                pair02Parallel &&
                (!pair13Parallel || avg02 <= avg13);

            if (use02AsEnds)
            {
                start = MidPoint(pts[0], pts[1]);
                end = MidPoint(pts[2], pts[3]);
                ductWidth = avg02;
                startWidth = len[0];
                endWidth = len[2];
            }
            else
            {
                start = MidPoint(pts[1], pts[2]);
                end = MidPoint(pts[3], pts[0]);
                ductWidth = avg13;
                startWidth = len[1];
                endWidth = len[3];
            }

            bool ok = TryCreateOngGioCenterlineCandidate(
                start,
                end,
                ductWidth,
                source,
                out candidate);

            if (!ok || candidate == null)
                return false;

            candidate.StartDuctWidth = startWidth;
            candidate.EndDuctWidth = endWidth;
            candidate.IsReducer =
                Math.Abs(startWidth - endWidth) >
                Math.Max(80.0, Math.Max(startWidth, endWidth) * 0.12);

            return true;
        }

        private void AddOngGioSegmentsFromEntity(
            Entity src,
            List<OngGioSegmentInfo> segments)
        {
            if (src == null || segments == null)
                return;

            try
            {
                if (src is Arc)
                    return;

                string key = src.ObjectId.IsNull
                    ? Guid.NewGuid().ToString()
                    : src.ObjectId.ToString();

                if (src is Line line)
                {
                    AddOngGioSegment(
                        line.StartPoint,
                        line.EndPoint,
                        key,
                        segments);
                    return;
                }

                if (src is Polyline pl)
                {
                    for (int i = 0; i < pl.NumberOfVertices - 1; i++)
                    {
                        if (Math.Abs(pl.GetBulgeAt(i)) > 1e-9)
                            continue;

                        AddOngGioSegment(
                            pl.GetPoint3dAt(i),
                            pl.GetPoint3dAt(i + 1),
                            key,
                            segments);
                    }

                    if (pl.Closed && pl.NumberOfVertices > 2)
                    {
                        int last = pl.NumberOfVertices - 1;

                        if (Math.Abs(pl.GetBulgeAt(last)) <= 1e-9)
                        {
                            AddOngGioSegment(
                                pl.GetPoint3dAt(last),
                                pl.GetPoint3dAt(0),
                                key,
                                segments);
                        }
                    }

                    return;
                }

                if (src is Curve cv)
                {
                    AddOngGioSegment(
                        cv.StartPoint,
                        cv.EndPoint,
                        key,
                        segments);
                }
            }
            catch { }
        }

        private void AddOngGioArcFromEntity(
            Entity src,
            List<OngGioArcInfo> arcs)
        {
            if (src == null || arcs == null)
                return;

            try
            {
                if (src is Arc arc)
                {
                    AddOngGioArcInfo(
                        arc.Center,
                        arc.Radius,
                        arc.StartAngle,
                        arc.EndAngle,
                        NormalizeSignedAngle(
                            arc.EndAngle - arc.StartAngle),
                        arc.StartPoint,
                        arc.EndPoint,
                        arcs);
                    return;
                }

                if (src is Polyline pl)
                {
                    int segmentCount =
                        pl.Closed
                            ? pl.NumberOfVertices
                            : pl.NumberOfVertices - 1;

                    for (int i = 0; i < segmentCount; i++)
                    {
                        double bulge = pl.GetBulgeAt(i);
                        if (Math.Abs(bulge) <= 1e-9)
                            continue;

                        int next =
                            (i + 1) % pl.NumberOfVertices;

                        TryAddOngGioArcFromBulge(
                            pl.GetPoint3dAt(i),
                            pl.GetPoint3dAt(next),
                            bulge,
                            arcs);
                    }
                }
            }
            catch { }
        }

        private static void TryAddOngGioArcFromBulge(
            Point3d start,
            Point3d end,
            double bulge,
            List<OngGioArcInfo> arcs)
        {
            if (arcs == null || Math.Abs(bulge) <= 1e-9)
                return;

            Vector3d chord = end - start;
            double chordLength =
                Math.Sqrt(
                    chord.X * chord.X +
                    chord.Y * chord.Y);

            if (chordLength < 1e-6)
                return;

            double included = 4.0 * Math.Atan(bulge);
            if (Math.Abs(included) < Math.PI / 6.0 ||
                Math.Abs(included) > Math.PI * 0.75)
                return;

            double radius =
                chordLength * (1.0 + bulge * bulge) /
                (4.0 * Math.Abs(bulge));
            if (radius < 50.0)
                return;

            Point3d chordMiddle = MidPoint(start, end);
            double centerOffset =
                chordLength * (1.0 - bulge * bulge) /
                (4.0 * bulge);
            double normalX = -chord.Y / chordLength;
            double normalY = chord.X / chordLength;
            Point3d center =
                new Point3d(
                    chordMiddle.X + normalX * centerOffset,
                    chordMiddle.Y + normalY * centerOffset,
                    chordMiddle.Z);

            double startAngle =
                Math.Atan2(
                    start.Y - center.Y,
                    start.X - center.X);
            double endAngle = startAngle + included;

            AddOngGioArcInfo(
                center,
                radius,
                startAngle,
                endAngle,
                included,
                start,
                end,
                arcs);
        }

        private static void AddOngGioArcInfo(
            Point3d center,
            double radius,
            double startAngle,
            double endAngle,
            double included,
            Point3d start,
            Point3d end,
            List<OngGioArcInfo> arcs)
        {
            if (arcs == null)
                return;

            if (Math.Abs(included) < Math.PI / 6.0 ||
                Math.Abs(included) > Math.PI * 0.75 ||
                radius < 50.0)
                return;

            arcs.Add(
                new OngGioArcInfo
                {
                    Center = center,
                    Radius = radius,
                    StartAngle = startAngle,
                    EndAngle = endAngle,
                    IncludedAngle = included,
                    Start = start,
                    End = end
                });
        }

        private static void AddOngGioSegment(
            Point3d start,
            Point3d end,
            string sourceKey,
            List<OngGioSegmentInfo> segments)
        {
            Vector3d v = end - start;
            double len = v.Length;

            if (len < 100.0)
                return;

            Vector3d dir = v.GetNormal();

            segments.Add(
                new OngGioSegmentInfo
                {
                    Start = start,
                    End = end,
                    Mid = MidPoint(start, end),
                    Direction = dir,
                    Length = len,
                    SourceKey = sourceKey
                });
        }

        private List<OngGioCenterlineCandidate> CreateOngGioCandidatesFromParallelSegments(
            List<OngGioSegmentInfo> segments)
        {
            var result = new List<OngGioCenterlineCandidate>();

            if (segments == null || segments.Count < 2)
                return result;

            for (int i = 0; i < segments.Count; i++)
            {
                for (int j = i + 1; j < segments.Count; j++)
                {
                    OngGioSegmentInfo a = segments[i];
                    OngGioSegmentInfo b = segments[j];

                    if (a == null || b == null)
                        continue;

                    if (!AreParallel(a.Direction, b.Direction, 10.0))
                        continue;

                    if (!AreSimilarLength(a.Length, b.Length, 0.35))
                        continue;

                    double gap =
                        DistancePointToInfiniteLine(
                            b.Mid,
                            a.Start,
                            a.Direction);

                    if (gap < 50.0 || gap > 5000.0)
                        continue;

                    if (gap > Math.Min(a.Length, b.Length) * 0.75)
                        continue;

                    Vector3d u = a.Direction;

                    double a0 = DotPoint(a.Start, u);
                    double a1 = DotPoint(a.End, u);
                    double b0 = DotPoint(b.Start, u);
                    double b1 = DotPoint(b.End, u);

                    if (a0 > a1)
                        Swap(ref a0, ref a1);
                    if (b0 > b1)
                        Swap(ref b0, ref b1);

                    double startT = Math.Max(a0, b0);
                    double endT = Math.Min(a1, b1);
                    double overlap = endT - startT;

                    if (overlap < Math.Max(200.0, Math.Min(a.Length, b.Length) * 0.35))
                        continue;

                    Point3d aStart = PointOnSegmentProjection(a, startT, u);
                    Point3d aEnd = PointOnSegmentProjection(a, endT, u);
                    Point3d bStart = PointOnSegmentProjection(b, startT, u);
                    Point3d bEnd = PointOnSegmentProjection(b, endT, u);

                    if (aStart.DistanceTo(bStart) < 50.0 ||
                        aEnd.DistanceTo(bEnd) < 50.0)
                        continue;

                    Point3d centerStart = MidPoint(aStart, bStart);
                    Point3d centerEnd = MidPoint(aEnd, bEnd);

                    if (TryCreateOngGioCenterlineCandidate(
                            centerStart,
                            centerEnd,
                            gap,
                            "RECT-LINES",
                            out OngGioCenterlineCandidate candidate))
                    {
                        result.Add(candidate);
                    }
                }
            }

            return result;
        }

        private List<OngGioCenterlineCandidate> CreateReducerCandidatesFromEndSegments(
            List<OngGioSegmentInfo> segments)
        {
            var result = new List<OngGioCenterlineCandidate>();

            if (segments == null || segments.Count < 2)
                return result;

            for (int i = 0; i < segments.Count; i++)
            {
                for (int j = i + 1; j < segments.Count; j++)
                {
                    OngGioSegmentInfo a = segments[i];
                    OngGioSegmentInfo b = segments[j];

                    if (a == null || b == null)
                        continue;

                    if (!AreParallel(a.Direction, b.Direction, 12.0))
                        continue;

                    double maxLen = Math.Max(a.Length, b.Length);
                    double minLen = Math.Min(a.Length, b.Length);

                    if (maxLen < 80.0 || maxLen > 5000.0)
                        continue;

                    if (minLen / maxLen < 0.25)
                        continue;

                    if (Math.Abs(a.Length - b.Length) <=
                        Math.Max(80.0, maxLen * 0.12))
                        continue;

                    Vector3d centerVector = b.Mid - a.Mid;
                    double centerDistance = centerVector.Length;

                    if (centerDistance < 100.0 ||
                        centerDistance > maxLen * 4.0)
                        continue;

                    Vector3d centerDirection =
                        centerVector.GetNormal();

                    double dot =
                        Math.Abs(
                            centerDirection.DotProduct(
                                a.Direction.GetNormal()));

                    if (dot > Math.Sin(Math.PI / 9.0))
                        continue;

                    if (!HasReducerSideConnections(
                            a,
                            b,
                            segments))
                        continue;

                    if (!TryCreateOngGioCenterlineCandidate(
                            a.Mid,
                            b.Mid,
                            (a.Length + b.Length) / 2.0,
                            "REDUCER-END-LINES",
                            out OngGioCenterlineCandidate candidate))
                        continue;

                    candidate.IsReducer = true;
                    candidate.StartDuctWidth = a.Length;
                    candidate.EndDuctWidth = b.Length;

                    result.Add(candidate);
                }
            }

            return result;
        }

        private static bool HasReducerSideConnections(
            OngGioSegmentInfo firstEnd,
            OngGioSegmentInfo secondEnd,
            List<OngGioSegmentInfo> segments)
        {
            if (firstEnd == null ||
                secondEnd == null ||
                segments == null)
                return false;

            double direct =
                firstEnd.Start.DistanceTo(secondEnd.Start) +
                firstEnd.End.DistanceTo(secondEnd.End);
            double crossed =
                firstEnd.Start.DistanceTo(secondEnd.End) +
                firstEnd.End.DistanceTo(secondEnd.Start);

            Point3d firstTarget;
            Point3d secondTarget;

            if (direct <= crossed)
            {
                firstTarget = secondEnd.Start;
                secondTarget = secondEnd.End;
            }
            else
            {
                firstTarget = secondEnd.End;
                secondTarget = secondEnd.Start;
            }

            double endpointTolerance =
                Math.Min(
                    100.0,
                    Math.Max(
                        25.0,
                        Math.Min(firstEnd.Length, secondEnd.Length) * 0.05));

            return
                HasOngGioSideConnectingPoints(
                    firstEnd.Start,
                    firstTarget,
                    firstEnd,
                    secondEnd,
                    segments,
                    endpointTolerance) &&
                HasOngGioSideConnectingPoints(
                    firstEnd.End,
                    secondTarget,
                    firstEnd,
                    secondEnd,
                    segments,
                    endpointTolerance);
        }

        private static bool HasOngGioSideConnectingPoints(
            Point3d firstPoint,
            Point3d secondPoint,
            OngGioSegmentInfo firstEnd,
            OngGioSegmentInfo secondEnd,
            List<OngGioSegmentInfo> segments,
            double endpointTolerance)
        {
            Vector3d expected = secondPoint - firstPoint;
            if (expected.Length < 80.0)
                return false;

            Vector3d expectedDirection = expected.GetNormal();

            foreach (OngGioSegmentInfo side in segments)
            {
                if (side == null ||
                    ReferenceEquals(side, firstEnd) ||
                    ReferenceEquals(side, secondEnd))
                    continue;

                bool sameDirection =
                    side.Start.DistanceTo(firstPoint) <= endpointTolerance &&
                    side.End.DistanceTo(secondPoint) <= endpointTolerance;
                bool reverseDirection =
                    side.End.DistanceTo(firstPoint) <= endpointTolerance &&
                    side.Start.DistanceTo(secondPoint) <= endpointTolerance;

                if (!sameDirection && !reverseDirection)
                    continue;

                double alignment =
                    Math.Abs(
                        side.Direction.GetNormal()
                            .DotProduct(expectedDirection));

                if (alignment >= Math.Cos(Math.PI / 4.0))
                    return true;
            }

            return false;
        }

        private List<OngGioCenterlineCandidate> CreateOngGioCandidatesFromConcentricArcs(
            List<OngGioArcInfo> arcs)
        {
            var result = new List<OngGioCenterlineCandidate>();

            if (arcs == null || arcs.Count == 0)
                return result;

            var used = new HashSet<int>();

            for (int i = 0; i < arcs.Count; i++)
            {
                if (used.Contains(i))
                    continue;

                OngGioArcInfo a = arcs[i];
                int bestIndex = -1;
                double bestScore = double.MaxValue;
                OngGioCenterlineCandidate bestCandidate = null;

                for (int j = i + 1; j < arcs.Count; j++)
                {
                    if (used.Contains(j))
                        continue;

                    OngGioArcInfo b = arcs[j];

                    if (!TryCreateArcCandidateFromPair(
                            a,
                            b,
                            out OngGioCenterlineCandidate pairCandidate,
                            out double score))
                        continue;

                    if (score < bestScore)
                    {
                        bestScore = score;
                        bestIndex = j;
                        bestCandidate = pairCandidate;
                    }
                }

                if (bestIndex >= 0 && bestCandidate != null)
                {
                    used.Add(i);
                    used.Add(bestIndex);
                    result.Add(bestCandidate);
                }
                else
                {
                    used.Add(i);
                }
            }

            return result.Where(x => x != null).ToList();
        }

        private bool TryCreateArcCandidateFromPair(
            OngGioArcInfo first,
            OngGioArcInfo second,
            out OngGioCenterlineCandidate candidate,
            out double score)
        {
            candidate = null;
            score = double.MaxValue;

            if (first == null || second == null)
                return false;

            double centerGap =
                first.Center.DistanceTo(second.Center);
            if (centerGap > 80.0)
                return false;

            double firstSweep = Math.Abs(first.IncludedAngle);
            double secondSweep = Math.Abs(second.IncludedAngle);
            double sweepGap = Math.Abs(firstSweep - secondSweep);
            if (sweepGap > Math.PI / 10.0)
                return false;

            double radiusGap =
                Math.Abs(first.Radius - second.Radius);
            if (radiusGap < 50.0 || radiusGap > 5000.0)
                return false;

            double directPairing =
                first.Start.DistanceTo(second.Start) +
                first.End.DistanceTo(second.End);
            double crossedPairing =
                first.Start.DistanceTo(second.End) +
                first.End.DistanceTo(second.Start);
            bool useCrossedPairing = crossedPairing < directPairing;

            Point3d start =
                useCrossedPairing
                    ? MidPoint(first.Start, second.End)
                    : MidPoint(first.Start, second.Start);
            Point3d end =
                useCrossedPairing
                    ? MidPoint(first.End, second.Start)
                    : MidPoint(first.End, second.End);

            double startGap =
                useCrossedPairing
                    ? first.Start.DistanceTo(second.End)
                    : first.Start.DistanceTo(second.Start);
            double endGap =
                useCrossedPairing
                    ? first.End.DistanceTo(second.Start)
                    : first.End.DistanceTo(second.End);

            double endpointTolerance =
                Math.Max(
                    100.0,
                    radiusGap * 0.35 + centerGap);

            if (Math.Abs(startGap - radiusGap) > endpointTolerance ||
                Math.Abs(endGap - radiusGap) > endpointTolerance ||
                Math.Abs(startGap - endGap) > endpointTolerance)
                return false;

            Point3d firstArcMiddle =
                PointAtAngle(
                    first.Center,
                    first.Radius,
                    first.StartAngle + first.IncludedAngle / 2.0);
            Point3d secondArcMiddle =
                PointAtAngle(
                    second.Center,
                    second.Radius,
                    second.StartAngle + second.IncludedAngle / 2.0);
            Point3d middle =
                MidPoint(firstArcMiddle, secondArcMiddle);

            if (start.DistanceTo(middle) < 50.0 ||
                middle.DistanceTo(end) < 50.0)
                return false;

            Point3d center =
                MidPoint(first.Center, second.Center);
            double radius =
                (center.DistanceTo(start) +
                 center.DistanceTo(end)) / 2.0;
            double startAngle =
                Math.Atan2(
                    start.Y - center.Y,
                    start.X - center.X);
            double endAngle =
                Math.Atan2(
                    end.Y - center.Y,
                    end.X - center.X);
            double includedAngle =
                NormalizeSignedAngle(endAngle - startAngle);
            double ductWidth =
                (startGap + endGap) / 2.0;
            Vector3d direction = middle - start;

            if (direction.Length < 1e-9)
                return false;

            candidate = new OngGioCenterlineCandidate
            {
                Start = start,
                End = end,
                Mid = middle,
                Direction = direction.GetNormal(),
                Length =
                    start.DistanceTo(middle) +
                    middle.DistanceTo(end),
                DuctWidth = ductWidth,
                Source = "ELBOW-ARC-PAIR",
                IsArc = true,
                ArcCenter = center,
                ArcRadius = radius,
                ArcStartAngle = startAngle,
                ArcEndAngle = endAngle,
                ArcIncludedAngle = includedAngle,
                Vertices = new List<Point3d>
                {
                    start,
                    middle,
                    end
                }
            };

            double pairingScore =
                Math.Min(directPairing, crossedPairing);
            score =
                centerGap * 5.0 +
                sweepGap * Math.Max(first.Radius, second.Radius) +
                Math.Abs(startGap - endGap) * 2.0 +
                pairingScore * 0.05;

            return true;
        }

        private List<OngGioCenterlineCandidate> CreateTerminalOngGioCandidatesFromSingleArcs(
            List<OngGioArcInfo> arcs,
            List<OngGioCenterlineCandidate> pairedArcCandidates,
            List<OngGioCenterlineCandidate> nearbyCandidates,
            List<OngGioSegmentInfo> sourceSegments)
        {
            var result = new List<OngGioCenterlineCandidate>();

            if (arcs == null ||
                arcs.Count == 0 ||
                nearbyCandidates == null ||
                nearbyCandidates.Count == 0)
                return result;

            foreach (OngGioArcInfo arc in arcs)
            {
                if (arc == null)
                    continue;

                double sweep = Math.Abs(arc.IncludedAngle);
                if (sweep < Math.PI * 55.0 / 180.0 ||
                    sweep > Math.PI * 125.0 / 180.0)
                    continue;

                if (IsOngGioArcRepresentedByPair(
                        arc,
                        pairedArcCandidates))
                    continue;

                OngGioCenterlineCandidate bestCandidate = null;
                double bestScore = double.MaxValue;

                foreach (OngGioCenterlineCandidate neighbor in nearbyCandidates)
                {
                    if (neighbor == null ||
                        neighbor.IsArc ||
                        neighbor.Length < 100.0)
                        continue;

                    foreach (bool useNeighborStart in new[] { true, false })
                    {
                        Point3d neighborPoint =
                            useNeighborStart
                                ? neighbor.Start
                                : neighbor.End;
                        double ductWidth =
                            GetOngGioCandidateEndpointWidth(
                                neighbor,
                                useNeighborStart);

                        if (ductWidth < 80.0 || ductWidth > 5000.0)
                            continue;

                        foreach (double radiusOffset in
                                 new[]
                                 {
                                     -ductWidth / 2.0,
                                     ductWidth / 2.0
                                 })
                        {
                            double centerRadius =
                                arc.Radius + radiusOffset;
                            if (centerRadius < 50.0)
                                continue;

                            Point3d centerStart =
                                PointAtAngle(
                                    arc.Center,
                                    centerRadius,
                                    arc.StartAngle);
                            Point3d centerEnd =
                                PointAtAngle(
                                    arc.Center,
                                    centerRadius,
                                    arc.EndAngle);

                            TryCreateStrictTerminalArcCandidate(
                                arc,
                                neighbor,
                                neighborPoint,
                                ductWidth,
                                centerRadius,
                                centerStart,
                                centerEnd,
                                nearbyCandidates,
                                sourceSegments,
                                ref bestCandidate,
                                ref bestScore);
                        }
                    }
                }

                if (bestCandidate == null)
                    continue;

                bool duplicate =
                    result.Any(x =>
                        x != null &&
                        x.ArcCenter.DistanceTo(
                            bestCandidate.ArcCenter) <= 30.0 &&
                        Math.Abs(
                            x.ArcRadius -
                            bestCandidate.ArcRadius) <= 30.0 &&
                        ((x.Start.DistanceTo(
                              bestCandidate.Start) <= 50.0 &&
                          x.End.DistanceTo(
                              bestCandidate.End) <= 50.0) ||
                         (x.Start.DistanceTo(
                              bestCandidate.End) <= 50.0 &&
                          x.End.DistanceTo(
                              bestCandidate.Start) <= 50.0)));

                if (!duplicate)
                    result.Add(bestCandidate);
            }

            return result;
        }

        private static bool IsOngGioArcRepresentedByPair(
            OngGioArcInfo arc,
            List<OngGioCenterlineCandidate> pairedArcCandidates)
        {
            if (arc == null || pairedArcCandidates == null)
                return false;

            foreach (OngGioCenterlineCandidate pair in pairedArcCandidates)
            {
                if (pair == null || !pair.IsArc || pair.DuctWidth <= 0.0)
                    continue;

                double centerTolerance =
                    Math.Max(30.0, pair.DuctWidth * 0.05);
                if (arc.Center.DistanceTo(pair.ArcCenter) > centerTolerance)
                    continue;

                double sweepGap =
                    Math.Abs(
                        Math.Abs(arc.IncludedAngle) -
                        Math.Abs(pair.ArcIncludedAngle));
                if (sweepGap > Math.PI / 18.0)
                    continue;

                double boundaryOffset =
                    Math.Abs(arc.Radius - pair.ArcRadius);
                double offsetTolerance =
                    Math.Max(30.0, pair.DuctWidth * 0.10);

                if (Math.Abs(
                        boundaryOffset -
                        pair.DuctWidth / 2.0) <= offsetTolerance)
                    return true;
            }

            return false;
        }

        private static void TryCreateStrictTerminalArcCandidate(
            OngGioArcInfo arc,
            OngGioCenterlineCandidate neighbor,
            Point3d neighborPoint,
            double ductWidth,
            double centerRadius,
            Point3d centerStart,
            Point3d centerEnd,
            List<OngGioCenterlineCandidate> nearbyCandidates,
            List<OngGioSegmentInfo> sourceSegments,
            ref OngGioCenterlineCandidate bestCandidate,
            ref double bestScore)
        {
            if (arc == null || neighbor == null)
                return;

            double jointTolerance =
                Math.Max(
                    50.0,
                    Math.Min(250.0, ductWidth * 0.25));

            foreach (bool useArcStart in new[] { true, false })
            {
                Point3d jointPoint =
                    useArcStart ? centerStart : centerEnd;
                Point3d farPoint =
                    useArcStart ? centerEnd : centerStart;
                Point3d jointBoundaryPoint =
                    useArcStart ? arc.Start : arc.End;
                Point3d farBoundaryPoint =
                    useArcStart ? arc.End : arc.Start;
                double jointAngle =
                    useArcStart
                        ? arc.StartAngle
                        : arc.EndAngle;
                double farAngle =
                    useArcStart
                        ? arc.EndAngle
                        : arc.StartAngle;
                Vector3d jointTangent =
                    GetOngGioArcTangent(jointAngle);
                Vector3d farTangent =
                    GetOngGioArcTangent(farAngle);
                double jointDistance =
                    neighborPoint.DistanceTo(jointPoint);

                if (jointDistance > jointTolerance ||
                    !AreParallel(
                        neighbor.Direction,
                        jointTangent,
                        10.0))
                    continue;

                bool hasJointOutline =
                    HasOngGioArcBoundaryTangentContinuation(
                        jointBoundaryPoint,
                        jointTangent,
                        ductWidth,
                        sourceSegments,
                        out double jointOutlineScore);
                double exactJointTolerance =
                    Math.Max(
                        35.0,
                        Math.Min(100.0, ductWidth * 0.10));

                if (!hasJointOutline &&
                    jointDistance > exactJointTolerance)
                    continue;

                if (!HasStrictTerminalArcFarEnd(
                        farPoint,
                        farBoundaryPoint,
                        farTangent,
                        ductWidth,
                        neighbor,
                        nearbyCandidates,
                        sourceSegments,
                        jointTolerance,
                        out double farEndScore))
                    continue;

                double alignment =
                    Math.Abs(
                        neighbor.Direction.GetNormal()
                            .DotProduct(jointTangent));
                double score =
                    jointDistance +
                    farEndScore +
                    (hasJointOutline
                        ? jointOutlineScore * 0.25
                        : 0.0) +
                    (1.0 - alignment) * ductWidth;

                if (score >= bestScore)
                    continue;

                Point3d middle =
                    PointAtAngle(
                        arc.Center,
                        centerRadius,
                        arc.StartAngle +
                        arc.IncludedAngle / 2.0);
                Vector3d direction = middle - centerStart;
                if (direction.Length < 1e-9)
                    continue;

                bestCandidate =
                    new OngGioCenterlineCandidate
                    {
                        Start = centerStart,
                        End = centerEnd,
                        Mid = middle,
                        Direction = direction.GetNormal(),
                        Length =
                            centerStart.DistanceTo(middle) +
                            middle.DistanceTo(centerEnd),
                        DuctWidth = ductWidth,
                        Source = "ELBOW-TERMINAL-STRICT",
                        IsArc = true,
                        ArcCenter = arc.Center,
                        ArcRadius = centerRadius,
                        ArcStartAngle = arc.StartAngle,
                        ArcEndAngle = arc.EndAngle,
                        ArcIncludedAngle = arc.IncludedAngle,
                        Vertices = new List<Point3d>
                        {
                            centerStart,
                            middle,
                            centerEnd
                        }
                    };
                bestScore = score;
            }
        }

        private static bool HasStrictTerminalArcFarEnd(
            Point3d farPoint,
            Point3d farBoundaryPoint,
            Vector3d farTangent,
            double ductWidth,
            OngGioCenterlineCandidate joinedNeighbor,
            List<OngGioCenterlineCandidate> nearbyCandidates,
            List<OngGioSegmentInfo> sourceSegments,
            double tolerance,
            out double score)
        {
            score = double.MaxValue;

            foreach (OngGioCenterlineCandidate candidate in
                     nearbyCandidates ??
                     new List<OngGioCenterlineCandidate>())
            {
                if (candidate == null ||
                    candidate.IsArc ||
                    ReferenceEquals(candidate, joinedNeighbor))
                    continue;

                foreach (bool useStart in new[] { true, false })
                {
                    Point3d endpoint =
                        useStart ? candidate.Start : candidate.End;
                    double endpointWidth =
                        GetOngGioCandidateEndpointWidth(
                            candidate,
                            useStart);

                    if (Math.Abs(endpointWidth - ductWidth) >
                        Math.Max(80.0, ductWidth * 0.20))
                        continue;

                    double distance = endpoint.DistanceTo(farPoint);
                    if (distance > tolerance ||
                        !AreParallel(
                            candidate.Direction,
                            farTangent,
                            18.0))
                        continue;

                    score = distance;
                    return true;
                }
            }

            Vector3d capDirection =
                farTangent.RotateBy(
                    Math.PI / 2.0,
                    Vector3d.ZAxis).GetNormal();
            Point3d expectedFirst =
                farPoint + capDirection * (ductWidth / 2.0);
            Point3d expectedSecond =
                farPoint - capDirection * (ductWidth / 2.0);

            foreach (OngGioSegmentInfo segment in
                     sourceSegments ??
                     new List<OngGioSegmentInfo>())
            {
                if (segment == null ||
                    segment.Length < ductWidth * 0.82 ||
                    segment.Length > ductWidth * 1.18 ||
                    !AreParallel(
                        segment.Direction,
                        capDirection,
                        10.0))
                    continue;

                double direct =
                    segment.Start.DistanceTo(expectedFirst) +
                    segment.End.DistanceTo(expectedSecond);
                double crossed =
                    segment.Start.DistanceTo(expectedSecond) +
                    segment.End.DistanceTo(expectedFirst);
                double endpointError = Math.Min(direct, crossed) / 2.0;

                if (endpointError > tolerance)
                    continue;

                score = endpointError;
                return true;
            }

            if (HasOngGioArcBoundaryTangentContinuation(
                    farBoundaryPoint,
                    farTangent,
                    ductWidth,
                    sourceSegments,
                    out double continuationScore))
            {
                score = continuationScore;
                return true;
            }

            return false;
        }

        private static bool HasOngGioArcBoundaryTangentContinuation(
            Point3d boundaryPoint,
            Vector3d tangent,
            double ductWidth,
            List<OngGioSegmentInfo> sourceSegments,
            out double score)
        {
            score = double.MaxValue;

            if (sourceSegments == null || sourceSegments.Count == 0)
                return false;

            double endpointTolerance =
                Math.Max(
                    35.0,
                    Math.Min(150.0, ductWidth * 0.15));
            double minimumLength =
                Math.Max(80.0, ductWidth * 0.15);

            foreach (OngGioSegmentInfo segment in sourceSegments)
            {
                if (segment == null ||
                    segment.Length < minimumLength ||
                    !AreParallel(
                        segment.Direction,
                        tangent,
                        12.0))
                    continue;

                double endpointDistance =
                    Math.Min(
                        boundaryPoint.DistanceTo(segment.Start),
                        boundaryPoint.DistanceTo(segment.End));

                if (endpointDistance > endpointTolerance)
                    continue;

                if (endpointDistance < score)
                    score = endpointDistance;
            }

            return score < double.MaxValue;
        }

        private static double GetOngGioCandidateEndpointWidth(
            OngGioCenterlineCandidate candidate,
            bool useStart)
        {
            if (candidate == null)
                return 0.0;

            if (candidate.IsReducer)
            {
                double endpointWidth =
                    useStart
                        ? candidate.StartDuctWidth
                        : candidate.EndDuctWidth;
                if (endpointWidth > 0.0)
                    return endpointWidth;
            }

            return candidate.DuctWidth;
        }

        private static Vector3d GetOngGioArcTangent(
            double angle)
        {
            return new Vector3d(
                -Math.Sin(angle),
                Math.Cos(angle),
                0.0).GetNormal();
        }

        private static Point3d PointOnSegmentProjection(
            OngGioSegmentInfo seg,
            double targetT,
            Vector3d direction)
        {
            double startT = DotPoint(seg.Start, direction);
            return seg.Start + direction * (targetT - startT);
        }

        private static bool TryCreateOngGioCenterlineCandidate(
            Point3d start,
            Point3d end,
            double ductWidth,
            string source,
            out OngGioCenterlineCandidate candidate)
        {
            candidate = null;

            Vector3d v = end - start;
            double len = v.Length;

            if (len < 100.0)
                return false;

            candidate =
                new OngGioCenterlineCandidate
                {
                    Start = start,
                    End = end,
                    Mid = MidPoint(start, end),
                    Direction = v.GetNormal(),
                    Length = len,
                    DuctWidth = ductWidth,
                    Source = source
                };

            return true;
        }

        private static List<OngGioCenterlineCandidate> RemoveDuplicateOngGioCandidates(
            List<OngGioCenterlineCandidate> candidates)
        {
            var result = new List<OngGioCenterlineCandidate>();

            foreach (OngGioCenterlineCandidate candidate in
                     (candidates ?? new List<OngGioCenterlineCandidate>())
                     .Where(x => x != null)
                     .OrderByDescending(x => x.Length))
            {
                bool duplicate = false;

                foreach (OngGioCenterlineCandidate existing in result)
                {
                    if (IsDuplicateOngGioCandidate(existing, candidate))
                    {
                        duplicate = true;
                        break;
                    }
                }

                if (!duplicate)
                    result.Add(candidate);
            }

            return result;
        }

        private static bool IsDuplicateOngGioCandidate(
            OngGioCenterlineCandidate a,
            OngGioCenterlineCandidate b)
        {
            if (a == null || b == null)
                return false;

            if (!AreParallel(a.Direction, b.Direction, 8.0))
                return false;

            double tol = Math.Max(
                120.0,
                Math.Min(
                    Math.Max(a.DuctWidth, 0.0),
                    Math.Max(b.DuctWidth, 0.0)) * 0.35);

            bool sameEnds =
                a.Start.DistanceTo(b.Start) <= tol &&
                a.End.DistanceTo(b.End) <= tol;

            bool reverseEnds =
                a.Start.DistanceTo(b.End) <= tol &&
                a.End.DistanceTo(b.Start) <= tol;

            bool sameMiddle =
                a.Mid.DistanceTo(b.Mid) <= tol &&
                Math.Abs(a.Length - b.Length) <=
                Math.Max(200.0, Math.Min(a.Length, b.Length) * 0.2);

            return sameEnds || reverseEnds || sameMiddle;
        }

        private List<OngGioCenterlineCandidate> RemoveShortStraightCandidatesNearArcs(
            List<OngGioCenterlineCandidate> candidates,
            List<OngGioCenterlineCandidate> arcCandidates)
        {
            if (candidates == null ||
                arcCandidates == null ||
                arcCandidates.Count == 0)
                return candidates ?? new List<OngGioCenterlineCandidate>();

            var result = new List<OngGioCenterlineCandidate>();

            foreach (OngGioCenterlineCandidate candidate in candidates)
            {
                if (candidate == null)
                    continue;

                if (candidate.IsArc || candidate.IsReducer)
                {
                    result.Add(candidate);
                    continue;
                }

                bool nearArc = false;

                foreach (OngGioCenterlineCandidate arc in arcCandidates)
                {
                    if (arc == null || !arc.IsArc)
                        continue;

                    if (IsCandidateInsideArcFitting(
                            candidate,
                            arc))
                    {
                        nearArc = true;
                        break;
                    }
                }

                if (!nearArc)
                    result.Add(candidate);
            }

            return result;
        }

        private static bool IsCandidateInsideArcFitting(
            OngGioCenterlineCandidate candidate,
            OngGioCenterlineCandidate arc)
        {
            if (candidate == null ||
                arc == null ||
                !arc.IsArc)
                return false;

            double maxLength =
                Math.Max(
                    arc.Length * 1.6,
                    arc.DuctWidth * 2.5);
            if (candidate.Length > maxLength)
                return false;

            double tolerance =
                Math.Max(
                    150.0,
                    Math.Max(candidate.DuctWidth, arc.DuctWidth) * 0.65);

            double startDistance =
                DistancePointToOngGioCandidatePath(
                    candidate.Start,
                    arc);
            double endDistance =
                DistancePointToOngGioCandidatePath(
                    candidate.End,
                    arc);

            if (startDistance <= tolerance &&
                endDistance <= tolerance)
                return true;

            if (!candidate.IsReducer)
                return false;

            double middleDistance =
                DistancePointToOngGioCandidatePath(
                    candidate.Mid,
                    arc);

            return
                middleDistance <= tolerance &&
                Math.Min(startDistance, endDistance) <= tolerance &&
                Math.Max(startDistance, endDistance) <= tolerance * 1.5;
        }

        private static double DistancePointToOngGioCandidatePath(
            Point3d point,
            OngGioCenterlineCandidate path)
        {
            if (path == null)
                return double.MaxValue;

            if (path.Vertices != null &&
                path.Vertices.Count >= 2)
            {
                double best = double.MaxValue;

                for (int i = 0; i < path.Vertices.Count - 1; i++)
                {
                    double distance =
                        DistancePointToSegment(
                            point,
                            path.Vertices[i],
                            path.Vertices[i + 1],
                            out double ignored);

                    if (distance < best)
                        best = distance;
                }

                return best;
            }

            return DistancePointToSegment(
                point,
                path.Start,
                path.End,
                out double unused);
        }

        private List<OngGioCenterlineCandidate> RemoveOrTrimCandidatesAtReducers(
            List<OngGioCenterlineCandidate> candidates)
        {
            if (candidates == null || candidates.Count == 0)
                return candidates ?? new List<OngGioCenterlineCandidate>();

            List<OngGioCenterlineCandidate> reducers =
                candidates
                    .Where(x => x != null && x.IsReducer)
                    .ToList();

            if (reducers.Count == 0)
                return candidates;

            var result = new List<OngGioCenterlineCandidate>();

            foreach (OngGioCenterlineCandidate candidate in candidates)
            {
                if (candidate == null)
                    continue;

                if (candidate.IsReducer || candidate.IsArc)
                {
                    result.Add(candidate);
                    continue;
                }

                bool remove = false;

                foreach (OngGioCenterlineCandidate reducer in reducers)
                {
                    if (ReferenceEquals(candidate, reducer))
                        continue;

                    if (IsCandidateInsideReducerEnvelope(
                            candidate,
                            reducer))
                    {
                        remove = true;
                        break;
                    }

                    TrimStraightCandidateAtReducerBoundary(
                        candidate,
                        reducer);

                    if (candidate.Length < 100.0)
                    {
                        remove = true;
                        break;
                    }
                }

                if (!remove)
                    result.Add(candidate);
            }

            return result;
        }

        private static bool IsCandidateInsideReducerEnvelope(
            OngGioCenterlineCandidate candidate,
            OngGioCenterlineCandidate reducer)
        {
            if (candidate == null ||
                reducer == null ||
                !reducer.IsReducer)
                return false;

            Vector3d axis = reducer.End - reducer.Start;
            double reducerLength = axis.Length;
            if (reducerLength < 1e-9)
                return false;

            Vector3d direction = axis.GetNormal();
            double startT =
                (candidate.Start - reducer.Start)
                    .DotProduct(direction);
            double endT =
                (candidate.End - reducer.Start)
                    .DotProduct(direction);
            double axialTolerance =
                Math.Max(80.0, reducerLength * 0.08);

            if (startT < -axialTolerance ||
                startT > reducerLength + axialTolerance ||
                endT < -axialTolerance ||
                endT > reducerLength + axialTolerance)
                return false;

            double maxEndWidth =
                Math.Max(
                    reducer.StartDuctWidth,
                    reducer.EndDuctWidth);
            if (maxEndWidth <= 0.0)
                maxEndWidth = reducer.DuctWidth;

            double lateralTolerance =
                Math.Max(120.0, maxEndWidth * 0.60);
            double startLateral =
                DistancePointToInfiniteLine(
                    candidate.Start,
                    reducer.Start,
                    direction);
            double endLateral =
                DistancePointToInfiniteLine(
                    candidate.End,
                    reducer.Start,
                    direction);
            double maxCandidateLength =
                Math.Max(
                    reducerLength * 1.5,
                    maxEndWidth * 1.25);

            return
                startLateral <= lateralTolerance &&
                endLateral <= lateralTolerance &&
                candidate.Length <= maxCandidateLength;
        }

        private static void TrimStraightCandidateAtReducerBoundary(
            OngGioCenterlineCandidate candidate,
            OngGioCenterlineCandidate reducer)
        {
            if (candidate == null ||
                reducer == null ||
                !reducer.IsReducer ||
                candidate.IsArc ||
                candidate.IsReducer ||
                (candidate.Vertices != null &&
                 candidate.Vertices.Count > 2))
                return;

            Vector3d axis = reducer.End - reducer.Start;
            double reducerLength = axis.Length;
            if (reducerLength < 1e-9)
                return;

            Vector3d direction = axis.GetNormal();
            if (!AreParallel(candidate.Direction, direction, 12.0))
                return;

            double lateralTolerance =
                Math.Max(
                    100.0,
                    Math.Min(
                        Math.Max(candidate.DuctWidth, 0.0),
                        Math.Max(reducer.DuctWidth, 0.0)) * 0.35);

            if (DistancePointToInfiniteLine(
                    candidate.Start,
                    reducer.Start,
                    direction) > lateralTolerance ||
                DistancePointToInfiniteLine(
                    candidate.End,
                    reducer.Start,
                    direction) > lateralTolerance)
                return;

            double startT =
                (candidate.Start - reducer.Start)
                    .DotProduct(direction);
            double endT =
                (candidate.End - reducer.Start)
                    .DotProduct(direction);
            double axialTolerance =
                Math.Max(50.0, reducerLength * 0.05);

            bool startInside =
                startT >= -axialTolerance &&
                startT <= reducerLength + axialTolerance;
            bool endInside =
                endT >= -axialTolerance &&
                endT <= reducerLength + axialTolerance;

            if (startInside == endInside)
                return;

            double outsideT = startInside ? endT : startT;
            Point3d boundary =
                outsideT < 0.0
                    ? reducer.Start
                    : reducer.End;

            if (startInside)
                candidate.Start = boundary;
            else
                candidate.End = boundary;

            RefreshOngGioCandidateGeometry(candidate);
        }

        private List<OngGioCenterlineCandidate> MergeMiterStraightCandidates(
            List<OngGioCenterlineCandidate> candidates)
        {
            if (candidates == null || candidates.Count < 2)
                return candidates ?? new List<OngGioCenterlineCandidate>();

            var used = new HashSet<int>();
            var result = new List<OngGioCenterlineCandidate>();

            for (int i = 0; i < candidates.Count; i++)
            {
                if (used.Contains(i))
                    continue;

                OngGioCenterlineCandidate a = candidates[i];
                if (a == null ||
                    a.IsArc ||
                    a.IsReducer ||
                    a.DuctWidth <= 0.0)
                {
                    if (a != null)
                        result.Add(a);
                    continue;
                }

                int bestIndex = -1;
                Point3d jointA = Point3d.Origin;
                Point3d jointB = Point3d.Origin;
                Point3d farA = Point3d.Origin;
                Point3d farB = Point3d.Origin;
                double bestScore = double.MaxValue;

                for (int j = i + 1; j < candidates.Count; j++)
                {
                    if (used.Contains(j))
                        continue;

                    OngGioCenterlineCandidate b = candidates[j];
                    if (b == null ||
                        b.IsArc ||
                        b.IsReducer ||
                        b.DuctWidth <= 0.0)
                        continue;

                    if (Math.Abs(a.DuctWidth - b.DuctWidth) >
                        Math.Max(100.0, Math.Max(a.DuctWidth, b.DuctWidth) * 0.2))
                        continue;

                    if (AreParallel(a.Direction, b.Direction, 18.0))
                        continue;

                    Point3d ja;
                    Point3d jb;
                    Point3d fa;
                    Point3d fb;
                    double d =
                        ClosestEndpointPair(
                            a,
                            b,
                            out ja,
                            out jb,
                            out fa,
                            out fb);

                    double tol =
                        Math.Max(250.0, Math.Max(a.DuctWidth, b.DuctWidth) * 0.75);

                    if (d > tol)
                        continue;

                    double score = d + Math.Abs(a.Length - b.Length) * 0.05;
                    if (score < bestScore)
                    {
                        bestScore = score;
                        bestIndex = j;
                        jointA = ja;
                        jointB = jb;
                        farA = fa;
                        farB = fb;
                    }
                }

                if (bestIndex < 0)
                {
                    result.Add(a);
                    continue;
                }

                OngGioCenterlineCandidate other = candidates[bestIndex];
                Point3d joint = MidPoint(jointA, jointB);
                var vertices = new List<Point3d> { farA, joint, farB };

                OngGioCenterlineCandidate merged =
                    new OngGioCenterlineCandidate
                    {
                        Start = farA,
                        End = farB,
                        Mid = joint,
                        Direction = (joint - farA).GetNormal(),
                        Length = farA.DistanceTo(joint) + joint.DistanceTo(farB),
                        DuctWidth = (a.DuctWidth + other.DuctWidth) / 2.0,
                        Source = "MITER",
                        Vertices = vertices
                    };

                result.Add(merged);
                used.Add(i);
                used.Add(bestIndex);
            }

            return result;
        }

        private static double ClosestEndpointPair(
            OngGioCenterlineCandidate a,
            OngGioCenterlineCandidate b,
            out Point3d jointA,
            out Point3d jointB,
            out Point3d farA,
            out Point3d farB)
        {
            jointA = a.Start;
            jointB = b.Start;
            farA = a.End;
            farB = b.End;

            double best = a.Start.DistanceTo(b.Start);

            double d = a.Start.DistanceTo(b.End);
            if (d < best)
            {
                best = d;
                jointA = a.Start;
                jointB = b.End;
                farA = a.End;
                farB = b.Start;
            }

            d = a.End.DistanceTo(b.Start);
            if (d < best)
            {
                best = d;
                jointA = a.End;
                jointB = b.Start;
                farA = a.Start;
                farB = b.End;
            }

            d = a.End.DistanceTo(b.End);
            if (d < best)
            {
                best = d;
                jointA = a.End;
                jointB = b.End;
                farA = a.Start;
                farB = b.Start;
            }

            return best;
        }

        private void ExtendBranchCandidatesToNearbyMainDucts(
            List<OngGioCenterlineCandidate> candidates)
        {
            if (candidates == null || candidates.Count < 2)
                return;

            foreach (OngGioCenterlineCandidate branch in candidates)
            {
                if (branch == null ||
                    branch.IsArc ||
                    branch.IsReducer ||
                    branch.DuctWidth <= 0.0)
                    continue;

                foreach (bool useStart in new[] { true, false })
                {
                    Point3d endPoint =
                        useStart ? branch.Start : branch.End;

                    OngGioCenterlineCandidate bestMain = null;
                    Point3d bestPoint = Point3d.Origin;
                    double bestScore = double.MaxValue;

                    foreach (OngGioCenterlineCandidate main in candidates)
                    {
                        if (main == null ||
                            ReferenceEquals(main, branch) ||
                            main.IsArc ||
                            main.IsReducer ||
                            main.DuctWidth <= branch.DuctWidth * 1.15)
                            continue;

                        if (AreParallel(
                                branch.Direction,
                                main.Direction,
                                18.0))
                            continue;

                        double t;
                        double d =
                            DistancePointToSegment(
                                endPoint,
                                main.Start,
                                main.End,
                                out t);

                        if (t < -0.1 || t > 1.1)
                            continue;

                        double tol =
                            Math.Max(
                                300.0,
                                (branch.DuctWidth + main.DuctWidth) * 0.6);

                        if (d > tol)
                            continue;

                        if (d < bestScore)
                        {
                            bestScore = d;
                            bestMain = main;
                            Point3d projected =
                                ProjectPointToSegment(
                                    endPoint,
                                    main.Start,
                                    main.End);
                            Vector3d edgeDirection =
                                endPoint - projected;
                            if (edgeDirection.Length < 1e-9)
                            {
                                edgeDirection =
                                    branch.Direction.RotateBy(
                                        Math.PI / 2.0,
                                        Vector3d.ZAxis);
                            }

                            edgeDirection = edgeDirection.GetNormal();
                            bestPoint =
                                projected +
                                edgeDirection *
                                (main.DuctWidth / 2.0);
                        }
                    }

                    if (bestMain == null)
                        continue;

                    if (useStart)
                        branch.Start = bestPoint;
                    else
                        branch.End = bestPoint;

                    RefreshOngGioCandidateGeometry(branch);
                }
            }
        }

        private bool IsOngGioCandidateBlockedByInternalMark(
            OngGioCenterlineCandidate candidate,
            List<OngGioSegmentInfo> segments)
        {
            if (candidate == null ||
                candidate.IsArc ||
                candidate.IsReducer ||
                segments == null ||
                segments.Count == 0 ||
                candidate.DuctWidth <= 0.0)
                return false;

            int perpendicularInsideCount = 0;
            double halfWidth =
                Math.Max(candidate.DuctWidth / 2.0, 50.0);

            foreach (OngGioSegmentInfo seg in segments)
            {
                if (seg == null || seg.Length < 80.0)
                    continue;

                double t;
                double centerDist =
                    DistancePointToSegment(
                        seg.Mid,
                        candidate.Start,
                        candidate.End,
                        out t);

                if (t < 0.08 || t > 0.92)
                    continue;

                if (centerDist > halfWidth + 80.0)
                    continue;

                double axisDot =
                    Math.Abs(
                        seg.Direction.GetNormal()
                            .DotProduct(candidate.Direction.GetNormal()));

                bool isParallelToDuct = axisDot > Math.Cos(Math.PI / 12.0);
                bool isPerpendicularToDuct = axisDot < Math.Sin(Math.PI / 12.0);

                if (isParallelToDuct)
                    continue;

                if (isPerpendicularToDuct)
                {
                    perpendicularInsideCount++;
                    continue;
                }

                if (seg.Length >= Math.Min(candidate.Length * 0.25, halfWidth * 0.8))
                    return true;
            }

            return perpendicularInsideCount >= 2;
        }

        private OngGioSizeTextInfo FindNearestOngGioSizeText(
            OngGioCenterlineCandidate candidate,
            List<OngGioSizeTextInfo> texts)
        {
            if (candidate == null || texts == null || texts.Count == 0)
                return null;

            OngGioSizeTextInfo best = null;
            double bestScore = double.MaxValue;
            double bestGeometryDifference = double.MaxValue;

            if (candidate.DuctWidth > 0.0)
            {
                foreach (OngGioSizeTextInfo text in texts)
                {
                    if (text == null)
                        continue;

                    double difference =
                        GetOngGioGeometryDifference(
                            text,
                            candidate.DuctWidth);
                    if (difference < bestGeometryDifference)
                        bestGeometryDifference = difference;
                }
            }

            double geometryTolerance =
                Math.Max(
                    20.0,
                    candidate.DuctWidth * 0.02);

            foreach (OngGioSizeTextInfo text in texts)
            {
                if (text == null)
                    continue;

                double geometryDifference =
                    GetOngGioGeometryDifference(
                        text,
                        candidate.DuctWidth);

                if (bestGeometryDifference < double.MaxValue &&
                    geometryDifference >
                        bestGeometryDifference + geometryTolerance)
                    continue;

                double outsidePenalty;
                double dLine =
                    GetOngGioTextDistanceToCandidate(
                        text.Pos,
                        candidate,
                        out outsidePenalty);

                double dMid =
                    text.Pos.DistanceTo(candidate.Mid);
                double widthPenalty =
                    geometryDifference * 8.0;

                double score =
                    dLine +
                    outsidePenalty * 0.5 +
                    dMid * 0.02 +
                    widthPenalty;

                if (score < bestScore)
                {
                    bestScore = score;
                    best = text;
                }
            }

            return best;
        }

        private static double GetOngGioGeometryDifference(
            OngGioSizeTextInfo text,
            double measuredWidth)
        {
            if (text == null || measuredWidth <= 0.0)
                return 0.0;

            double difference = double.MaxValue;

            if (text.SideA > 0.0)
            {
                difference =
                    Math.Min(
                        difference,
                        Math.Abs(text.SideA - measuredWidth));
            }

            if (text.SideB > 0.0)
            {
                difference =
                    Math.Min(
                        difference,
                        Math.Abs(text.SideB - measuredWidth));
            }

            if (difference == double.MaxValue &&
                text.Width > 0.0)
            {
                difference =
                    Math.Abs(text.Width - measuredWidth);
            }

            return difference == double.MaxValue
                ? 0.0
                : difference;
        }

        private static double GetOngGioTextDistanceToCandidate(
            Point3d textPoint,
            OngGioCenterlineCandidate candidate,
            out double outsidePenalty)
        {
            outsidePenalty = 0.0;

            if (candidate == null)
                return double.MaxValue;

            if (candidate.Vertices != null &&
                candidate.Vertices.Count >= 2)
            {
                return DistancePointToOngGioCandidatePath(
                    textPoint,
                    candidate);
            }

            double distance =
                DistancePointToSegment(
                    textPoint,
                    candidate.Start,
                    candidate.End,
                    out double t);

            if (t < 0.0)
                outsidePenalty = -t * candidate.Length;
            else if (t > 1.0)
                outsidePenalty = (t - 1.0) * candidate.Length;

            return distance;
        }

        private OngGioProtectionTextInfo FindNearestOngGioProtectionText(
            OngGioCenterlineCandidate candidate,
            List<OngGioProtectionTextInfo> texts)
        {
            if (candidate == null || texts == null || texts.Count == 0)
                return null;

            OngGioProtectionTextInfo best = null;
            double bestScore = double.MaxValue;

            foreach (OngGioProtectionTextInfo text in texts)
            {
                if (text == null)
                    continue;

                double outsidePenalty;
                double dLine =
                    GetOngGioTextDistanceToCandidate(
                        text.Pos,
                        candidate,
                        out outsidePenalty);

                double score =
                    dLine +
                    outsidePenalty * 0.5 +
                    text.Pos.DistanceTo(candidate.Mid) * 0.05;

                if (score < bestScore)
                {
                    bestScore = score;
                    best = text;
                }
            }

            return best;
        }

        private OngGioTypeTextInfo FindNearestOngGioTypeText(
            OngGioCenterlineCandidate candidate,
            List<OngGioTypeTextInfo> texts)
        {
            if (candidate == null || texts == null || texts.Count == 0)
                return null;

            OngGioTypeTextInfo best = null;
            double bestScore = double.MaxValue;

            foreach (OngGioTypeTextInfo text in texts)
            {
                if (text == null)
                    continue;

                double outsidePenalty;
                double dLine =
                    GetOngGioTextDistanceToCandidate(
                        text.Pos,
                        candidate,
                        out outsidePenalty);

                double score =
                    dLine +
                    outsidePenalty * 0.5 +
                    text.Pos.DistanceTo(candidate.Mid) * 0.05;

                if (score < bestScore)
                {
                    bestScore = score;
                    best = text;
                }
            }

            return best;
        }

        private void ResolveOngGioCandidateMetadata(
            List<OngGioCenterlineCandidate> candidates,
            List<OngGioSizeTextInfo> sizeTexts,
            List<OngGioProtectionTextInfo> protectionTexts,
            List<OngGioTypeTextInfo> typeTexts,
            string defaultOgType)
        {
            if (candidates == null)
                return;

            foreach (OngGioCenterlineCandidate candidate in candidates)
            {
                if (candidate == null || candidate.IsReducer)
                    continue;

                OngGioSizeTextInfo sizeInfo =
                    FindNearestOngGioSizeText(
                        candidate,
                        sizeTexts);
                if (sizeInfo == null)
                    continue;

                candidate.ResolvedSizeInfo = sizeInfo;
                candidate.ResolvedProtection = sizeInfo.Ei;

                if (string.IsNullOrWhiteSpace(
                        candidate.ResolvedProtection))
                {
                    OngGioProtectionTextInfo protection =
                        FindNearestOngGioProtectionText(
                            candidate,
                            protectionTexts);
                    if (protection != null)
                    {
                        candidate.ResolvedProtection =
                            protection.Text;
                    }
                }

                candidate.ResolvedOgType = defaultOgType;
                OngGioTypeTextInfo typeInfo =
                    FindNearestOngGioTypeText(
                        candidate,
                        typeTexts);
                if (typeInfo != null &&
                    !string.IsNullOrWhiteSpace(typeInfo.Type))
                {
                    candidate.ResolvedOgType = typeInfo.Type;
                }
            }
        }

        private static void PropagateConnectedStraightMetadataToArcs(
            List<OngGioCenterlineCandidate> candidates)
        {
            if (candidates == null || candidates.Count < 2)
                return;

            foreach (OngGioCenterlineCandidate arc in candidates)
            {
                if (arc == null || !arc.IsArc || arc.IsReducer)
                    continue;

                double endpointTolerance =
                    Math.Max(
                        100.0,
                        arc.DuctWidth *
                        (string.Equals(
                            arc.Source,
                            "ELBOW-TERMINAL-STRICT",
                            StringComparison.OrdinalIgnoreCase)
                            ? 0.55
                            : 0.25));
                double widthTolerance =
                    Math.Max(30.0, arc.DuctWidth * 0.05);

                List<OngGioCenterlineCandidate> connected =
                    candidates
                        .Where(x =>
                            x != null &&
                            !ReferenceEquals(x, arc) &&
                            !x.IsArc &&
                            !x.IsReducer &&
                            x.ResolvedSizeInfo != null &&
                            GetClosestOngGioEndpointDistance(
                                arc,
                                x) <= endpointTolerance &&
                            Math.Abs(
                                arc.DuctWidth - x.DuctWidth) <=
                                widthTolerance)
                        .ToList();

                if (connected.Count == 0)
                    continue;

                var groups =
                    connected
                        .GroupBy(x =>
                            ((x.ResolvedSizeInfo.Size ?? "") + "|" +
                             (x.ResolvedProtection ?? "") + "|" +
                             (x.ResolvedOgType ?? ""))
                            .ToUpperInvariant())
                        .OrderByDescending(x => x.Count())
                        .ToList();

                if (groups.Count > 1 &&
                    groups[0].Count() == groups[1].Count())
                    continue;

                OngGioCenterlineCandidate source =
                    groups[0]
                        .OrderBy(x =>
                            GetClosestOngGioEndpointDistance(
                                arc,
                                x))
                        .FirstOrDefault();

                if (source == null)
                    continue;

                arc.ResolvedSizeInfo = source.ResolvedSizeInfo;
                arc.ResolvedProtection = source.ResolvedProtection;
                arc.ResolvedOgType = source.ResolvedOgType;
            }
        }

        private static double GetClosestOngGioEndpointDistance(
            OngGioCenterlineCandidate first,
            OngGioCenterlineCandidate second)
        {
            if (first == null || second == null)
                return double.MaxValue;

            return Math.Min(
                Math.Min(
                    first.Start.DistanceTo(second.Start),
                    first.Start.DistanceTo(second.End)),
                Math.Min(
                    first.End.DistanceTo(second.Start),
                    first.End.DistanceTo(second.End)));
        }

        private List<OngGioCenterlineCandidate> MergeConnectedSameLayerCandidates(
            List<OngGioCenterlineCandidate> candidates)
        {
            var remaining =
                (candidates ??
                 new List<OngGioCenterlineCandidate>())
                .Where(x => x != null)
                .ToList();
            var topologyCandidates =
                new List<OngGioCenterlineCandidate>(remaining);
            var result = new List<OngGioCenterlineCandidate>();

            while (remaining.Count > 0)
            {
                OngGioCenterlineCandidate current = remaining[0];
                remaining.RemoveAt(0);

                if (current.IsReducer ||
                    current.ResolvedSizeInfo == null)
                {
                    result.Add(current);
                    continue;
                }

                while (true)
                {
                    int bestIndex = -1;
                    double bestConnectionScore = double.MaxValue;

                    for (int i = 0; i < remaining.Count; i++)
                    {
                        OngGioCenterlineCandidate next = remaining[i];
                        if (!HaveSameResolvedOngGioLayer(
                                current,
                                next))
                            continue;

                        if (!TryGetOngGioEndpointConnectionScore(
                                current,
                                next,
                                topologyCandidates,
                                out double connectionScore))
                            continue;

                        if (connectionScore < bestConnectionScore)
                        {
                            bestConnectionScore = connectionScore;
                            bestIndex = i;
                        }
                    }

                    if (bestIndex < 0)
                        break;

                    OngGioCenterlineCandidate nextCandidate =
                        remaining[bestIndex];
                    if (!TryMergeOngGioCandidatesAtEndpoints(
                            current,
                            nextCandidate,
                            out OngGioCenterlineCandidate merged))
                        break;

                    current = merged;
                    remaining.RemoveAt(bestIndex);
                }

                result.Add(current);
            }

            return result;
        }

        private static bool HaveSameResolvedOngGioLayer(
            OngGioCenterlineCandidate first,
            OngGioCenterlineCandidate second)
        {
            if (first == null || second == null ||
                first.IsReducer || second.IsReducer ||
                first.ResolvedSizeInfo == null ||
                second.ResolvedSizeInfo == null)
                return false;

            if (!string.Equals(
                    first.ResolvedSizeInfo.Size,
                    second.ResolvedSizeInfo.Size,
                    StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(
                    first.ResolvedProtection ?? "",
                    second.ResolvedProtection ?? "",
                    StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(
                    first.ResolvedOgType ?? "",
                    second.ResolvedOgType ?? "",
                    StringComparison.OrdinalIgnoreCase))
                return false;

            return true;
        }

        private static bool TryGetOngGioEndpointConnectionScore(
            OngGioCenterlineCandidate first,
            OngGioCenterlineCandidate second,
            List<OngGioCenterlineCandidate> allCandidates,
            out double score)
        {
            score = double.MaxValue;

            if (first == null || second == null)
                return false;

            bool firstUsesStart;
            bool secondUsesStart;
            Point3d firstPoint;
            Point3d secondPoint;
            double distance =
                GetClosestOngGioEndpointPair(
                    first,
                    second,
                    out firstUsesStart,
                    out secondUsesStart,
                    out firstPoint,
                    out secondPoint);
            double tolerance =
                GetOngGioCandidateMergeTolerance(
                    first,
                    second);

            if (distance > tolerance)
                return false;

            Vector3d firstDirection =
                GetOngGioEndpointPathDirection(
                    first,
                    firstUsesStart);
            Vector3d secondDirection =
                GetOngGioEndpointPathDirection(
                    second,
                    secondUsesStart);

            if (firstDirection.Length < 1e-9 ||
                secondDirection.Length < 1e-9)
                return false;

            bool hasArc = first.IsArc || second.IsArc;
            double angleTolerance = hasArc ? 40.0 : 15.0;
            bool directionsContinue =
                AreParallel(
                    firstDirection,
                    secondDirection,
                    angleTolerance);
            double actualWidth =
                Math.Max(
                    Math.Max(first.DuctWidth, second.DuctWidth),
                    100.0);
            double exactJointTolerance =
                Math.Max(
                    40.0,
                    Math.Min(100.0, actualWidth * 0.08));

            if (!hasArc && directionsContinue)
            {
                double lateralTolerance =
                    Math.Max(
                        40.0,
                        Math.Min(120.0, actualWidth * 0.10));
                double lateralOffset =
                    DistancePointToInfiniteLine(
                        secondPoint,
                        firstPoint,
                        firstDirection.GetNormal());

                if (lateralOffset > lateralTolerance)
                    return false;
            }

            if (!directionsContinue)
            {
                if (distance > exactJointTolerance)
                    return false;

                Point3d joint = MidPoint(firstPoint, secondPoint);
                int jointDegree =
                    CountOngGioCandidatesAtJoint(
                        allCandidates,
                        joint,
                        exactJointTolerance * 1.5);

                if (jointDegree > 2)
                    return false;
            }

            double alignment =
                Math.Abs(
                    firstDirection.GetNormal()
                        .DotProduct(
                            secondDirection.GetNormal()));
            score =
                distance +
                (1.0 - alignment) * actualWidth * 0.25;

            return true;
        }

        private static double GetClosestOngGioEndpointPair(
            OngGioCenterlineCandidate first,
            OngGioCenterlineCandidate second,
            out bool firstUsesStart,
            out bool secondUsesStart,
            out Point3d firstPoint,
            out Point3d secondPoint)
        {
            firstUsesStart = true;
            secondUsesStart = true;
            firstPoint = first.Start;
            secondPoint = second.Start;
            double best = first.Start.DistanceTo(second.Start);

            double distance = first.Start.DistanceTo(second.End);
            if (distance < best)
            {
                best = distance;
                firstUsesStart = true;
                secondUsesStart = false;
                firstPoint = first.Start;
                secondPoint = second.End;
            }

            distance = first.End.DistanceTo(second.Start);
            if (distance < best)
            {
                best = distance;
                firstUsesStart = false;
                secondUsesStart = true;
                firstPoint = first.End;
                secondPoint = second.Start;
            }

            distance = first.End.DistanceTo(second.End);
            if (distance < best)
            {
                best = distance;
                firstUsesStart = false;
                secondUsesStart = false;
                firstPoint = first.End;
                secondPoint = second.End;
            }

            return best;
        }

        private static double GetOngGioCandidateMergeTolerance(
            OngGioCenterlineCandidate first,
            OngGioCenterlineCandidate second)
        {
            double actualWidth =
                Math.Max(
                    Math.Max(
                        first?.DuctWidth ?? 0.0,
                        second?.DuctWidth ?? 0.0),
                    100.0);

            if ((first?.IsArc ?? false) ||
                (second?.IsArc ?? false))
            {
                return Math.Max(150.0, actualWidth * 0.55);
            }

            return Math.Max(100.0, actualWidth * 0.45);
        }

        private static Vector3d GetOngGioEndpointPathDirection(
            OngGioCenterlineCandidate candidate,
            bool useStart)
        {
            List<Point3d> vertices =
                GetOngGioCandidateVertices(candidate);

            if (vertices.Count < 2)
                return Vector3d.XAxis;

            Vector3d direction =
                useStart
                    ? vertices[1] - vertices[0]
                    : vertices[vertices.Count - 2] -
                      vertices[vertices.Count - 1];

            return direction.Length < 1e-9
                ? Vector3d.XAxis
                : direction.GetNormal();
        }

        private static int CountOngGioCandidatesAtJoint(
            List<OngGioCenterlineCandidate> candidates,
            Point3d joint,
            double tolerance)
        {
            if (candidates == null)
                return 0;

            return candidates.Count(x =>
                x != null &&
                !x.IsReducer &&
                (x.Start.DistanceTo(joint) <= tolerance ||
                 x.End.DistanceTo(joint) <= tolerance));
        }

        private static bool TryMergeOngGioCandidatesAtEndpoints(
            OngGioCenterlineCandidate first,
            OngGioCenterlineCandidate second,
            out OngGioCenterlineCandidate merged)
        {
            merged = null;

            List<Point3d> firstVertices =
                GetOngGioCandidateVertices(first);
            List<Point3d> secondVertices =
                GetOngGioCandidateVertices(second);

            if (firstVertices.Count < 2 ||
                secondVertices.Count < 2)
                return false;

            double tolerance =
                GetOngGioCandidateMergeTolerance(
                    first,
                    second);
            double bestDistance = double.MaxValue;
            List<Point3d> bestFirst = null;
            List<Point3d> bestSecond = null;

            for (int reverseFirst = 0; reverseFirst < 2; reverseFirst++)
            {
                for (int reverseSecond = 0; reverseSecond < 2; reverseSecond++)
                {
                    List<Point3d> orientedFirst =
                        new List<Point3d>(firstVertices);
                    List<Point3d> orientedSecond =
                        new List<Point3d>(secondVertices);

                    if (reverseFirst == 1)
                        orientedFirst.Reverse();
                    if (reverseSecond == 1)
                        orientedSecond.Reverse();

                    double distance =
                        orientedFirst[orientedFirst.Count - 1]
                            .DistanceTo(orientedSecond[0]);

                    if (distance < bestDistance)
                    {
                        bestDistance = distance;
                        bestFirst = orientedFirst;
                        bestSecond = orientedSecond;
                    }
                }
            }

            if (bestFirst == null ||
                bestSecond == null ||
                bestDistance > tolerance)
                return false;

            Point3d joint =
                MidPoint(
                    bestFirst[bestFirst.Count - 1],
                    bestSecond[0]);
            bestFirst[bestFirst.Count - 1] = joint;
            bestSecond[0] = joint;

            var vertices = new List<Point3d>();
            vertices.AddRange(bestFirst);

            for (int i = 1; i < bestSecond.Count; i++)
            {
                Point3d point = bestSecond[i];
                if (vertices.Count == 0 ||
                    vertices[vertices.Count - 1]
                        .DistanceTo(point) > 1e-6)
                {
                    vertices.Add(point);
                }
            }

            vertices =
                SimplifyOngGioPathVertices(vertices);

            double length =
                GetOngGioPathLength(vertices);
            if (vertices.Count < 2 || length < 100.0)
                return false;

            Vector3d direction =
                vertices[1] - vertices[0];
            if (direction.Length < 1e-9)
                return false;

            double weightedWidth =
                first.DuctWidth * Math.Max(first.Length, 1.0) +
                second.DuctWidth * Math.Max(second.Length, 1.0);
            double totalWeight =
                Math.Max(first.Length, 1.0) +
                Math.Max(second.Length, 1.0);
            bool isArcRun =
                first.IsArc ||
                second.IsArc ||
                vertices.Count > 2;

            merged = new OngGioCenterlineCandidate
            {
                Start = vertices[0],
                End = vertices[vertices.Count - 1],
                Mid = GetPointAtHalfOngGioPath(vertices),
                Direction = direction.GetNormal(),
                Length = length,
                DuctWidth = weightedWidth / totalWeight,
                Source = isArcRun
                    ? "ELBOW-RUN"
                    : "STRAIGHT-RUN",
                IsArc = isArcRun,
                Vertices = vertices,
                ResolvedSizeInfo = first.ResolvedSizeInfo,
                ResolvedProtection = first.ResolvedProtection,
                ResolvedOgType = first.ResolvedOgType
            };

            return true;
        }

        private static List<Point3d> SimplifyOngGioPathVertices(
            List<Point3d> vertices)
        {
            var clean = new List<Point3d>();

            foreach (Point3d point in
                     vertices ?? new List<Point3d>())
            {
                if (clean.Count == 0 ||
                    clean[clean.Count - 1]
                        .DistanceTo(point) > 1e-6)
                {
                    clean.Add(point);
                }
            }

            if (clean.Count < 3)
                return clean;

            var result = new List<Point3d> { clean[0] };

            for (int i = 1; i < clean.Count - 1; i++)
            {
                Point3d previous = result[result.Count - 1];
                Point3d current = clean[i];
                Point3d next = clean[i + 1];
                Vector3d firstDirection = current - previous;
                Vector3d secondDirection = next - current;

                bool isForwardCollinear =
                    firstDirection.Length > 1e-9 &&
                    secondDirection.Length > 1e-9 &&
                    AreParallel(
                        firstDirection,
                        secondDirection,
                        3.0) &&
                    firstDirection.GetNormal()
                        .DotProduct(
                            secondDirection.GetNormal()) > 0.0;

                if (!isForwardCollinear)
                    result.Add(current);
            }

            result.Add(clean[clean.Count - 1]);
            return result;
        }

        private static List<Point3d> GetOngGioCandidateVertices(
            OngGioCenterlineCandidate candidate)
        {
            if (candidate?.Vertices != null &&
                candidate.Vertices.Count >= 2)
            {
                return new List<Point3d>(candidate.Vertices);
            }

            if (candidate == null)
                return new List<Point3d>();

            return new List<Point3d>
            {
                candidate.Start,
                candidate.End
            };
        }

        private static double GetOngGioPathLength(
            List<Point3d> vertices)
        {
            if (vertices == null || vertices.Count < 2)
                return 0.0;

            double length = 0.0;

            for (int i = 0; i < vertices.Count - 1; i++)
            {
                length +=
                    vertices[i].DistanceTo(vertices[i + 1]);
            }

            return length;
        }

        private static Point3d GetPointAtHalfOngGioPath(
            List<Point3d> vertices)
        {
            if (vertices == null || vertices.Count == 0)
                return Point3d.Origin;
            if (vertices.Count == 1)
                return vertices[0];

            double totalLength =
                GetOngGioPathLength(vertices);
            double target = totalLength / 2.0;
            double accumulated = 0.0;

            for (int i = 0; i < vertices.Count - 1; i++)
            {
                Point3d start = vertices[i];
                Point3d end = vertices[i + 1];
                double segmentLength = start.DistanceTo(end);

                if (accumulated + segmentLength >= target &&
                    segmentLength > 1e-9)
                {
                    double ratio =
                        (target - accumulated) /
                        segmentLength;
                    return start + (end - start) * ratio;
                }

                accumulated += segmentLength;
            }

            return vertices[vertices.Count - 1];
        }

        private static bool TryGetOngGioLabelPlacement(
            OngGioCenterlineCandidate candidate,
            out Point3d point,
            out Vector3d direction,
            out double segmentLength)
        {
            point = Point3d.Origin;
            direction = Vector3d.XAxis;
            segmentLength = 0.0;

            if (candidate == null ||
                (candidate.IsArc &&
                 !string.Equals(
                     candidate.Source,
                     "ELBOW-RUN",
                     StringComparison.OrdinalIgnoreCase)))
                return false;

            List<Point3d> vertices =
                GetOngGioCandidateVertices(candidate);

            for (int i = 0; i < vertices.Count - 1; i++)
            {
                Vector3d vector =
                    vertices[i + 1] - vertices[i];
                double length = vector.Length;

                if (length <= segmentLength || length < 1e-9)
                    continue;

                segmentLength = length;
                point = MidPoint(vertices[i], vertices[i + 1]);
                direction = vector.GetNormal();
            }

            return segmentLength > 0.0;
        }

        private int DrawReducerCandidate(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            OngGioCenterlineCandidate candidate,
            List<OngGioSizeTextInfo> sizeTexts,
            List<OngGioProtectionTextInfo> protectionTexts,
            List<OngGioCenterlineCandidate> allCandidates,
            string ogType,
            string layerPrefix)
        {
            if (candidate == null ||
                sizeTexts == null ||
                sizeTexts.Count == 0)
                return 0;

            Point3d split = candidate.Mid;

            OngGioSizeTextInfo startSize =
                FindBestReducerSizeForWidth(
                    candidate.Start,
                    candidate.StartDuctWidth,
                    sizeTexts);

            OngGioSizeTextInfo endSize =
                FindBestReducerSizeForWidth(
                    candidate.End,
                    candidate.EndDuctWidth,
                    sizeTexts);

            if (startSize == null)
                startSize = FindNearestOngGioSizeText(candidate, sizeTexts);
            if (endSize == null)
                endSize = startSize;

            int count = 0;
            double halfLength = candidate.Length / 2.0;
            Vector3d startDirection =
                FindReducerExtensionDirection(
                    candidate.Start,
                    candidate.Mid,
                    candidate,
                    allCandidates);
            Vector3d endDirection =
                FindReducerExtensionDirection(
                    candidate.End,
                    candidate.Mid,
                    candidate,
                    allCandidates);

            Point3d startEnd =
                candidate.Start + startDirection * halfLength;
            Point3d endEnd =
                candidate.End + endDirection * halfLength;

            count += DrawStraightOngGioPart(
                tr,
                db,
                btr,
                candidate.Start,
                startEnd,
                startDirection,
                startSize,
                FindNearestProtectionTextToPoint(
                    candidate.Start,
                    protectionTexts),
                ogType,
                layerPrefix,
                false);

            count += DrawStraightOngGioPart(
                tr,
                db,
                btr,
                candidate.End,
                endEnd,
                endDirection,
                endSize,
                FindNearestProtectionTextToPoint(
                    candidate.End,
                    protectionTexts),
                ogType,
                layerPrefix,
                false);

            return count;
        }

        private int DrawStraightOngGioPart(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d start,
            Point3d end,
            Vector3d direction,
            OngGioSizeTextInfo sizeInfo,
            OngGioProtectionTextInfo protectionInfo,
            string ogType,
            string layerPrefix,
            bool showLabel)
        {
            if (sizeInfo == null)
                return 0;

            Vector3d v = end - start;
            if (v.Length < 100.0)
                return 0;

            string size = sizeInfo.Size;
            string eiPart = sizeInfo.Ei;

            if (string.IsNullOrWhiteSpace(eiPart) &&
                protectionInfo != null)
            {
                eiPart = protectionInfo.Text;
            }

            double width = sizeInfo.Width;
            if (width <= 0.0)
                width = LayWidthTuSize(size);
            if (width <= 0.0)
                width = 100.0;

            string layerName =
                BuildOngGioLayerName(
                    layerPrefix,
                    ogType,
                    size,
                    eiPart);

            EnsureLayerExists(tr, db, layerName, true);

            Polyline pl = new Polyline();
            pl.SetDatabaseDefaults(db);
            pl.AddVertexAt(
                0,
                new Point2d(start.X, start.Y),
                0, 0, 0);
            pl.AddVertexAt(
                1,
                new Point2d(end.X, end.Y),
                0, 0, 0);
            pl.Layer = layerName;
            pl.ColorIndex = 256;
            pl.ConstantWidth = width;

            btr.AppendEntity(pl);
            tr.AddNewlyCreatedDBObject(pl, true);

            if (showLabel)
            {
                AddOngGioLabel(
                    tr,
                    db,
                    btr,
                    layerName,
                    BuildOngGioDisplayText(size, eiPart),
                    width,
                    MidPoint(start, end),
                    v.GetNormal());
            }

            return 1;
        }

        private OngGioSizeTextInfo FindBestReducerSizeForWidth(
            Point3d point,
            double targetWidth,
            List<OngGioSizeTextInfo> texts)
        {
            if (texts == null || texts.Count == 0)
                return null;

            OngGioSizeTextInfo best = null;
            double bestDist = double.MaxValue;
            double bestGeometryDifference = double.MaxValue;

            foreach (OngGioSizeTextInfo text in texts)
            {
                if (text == null)
                    continue;

                double difference =
                    GetOngGioGeometryDifference(
                        text,
                        targetWidth);
                if (difference < bestGeometryDifference)
                    bestGeometryDifference = difference;
            }

            double geometryTolerance =
                Math.Max(20.0, targetWidth * 0.02);

            foreach (OngGioSizeTextInfo text in texts)
            {
                if (text == null)
                    continue;

                double geometryDifference =
                    GetOngGioGeometryDifference(
                        text,
                        targetWidth);

                if (bestGeometryDifference < double.MaxValue &&
                    geometryDifference >
                        bestGeometryDifference + geometryTolerance)
                    continue;

                double widthPenalty =
                    geometryDifference * 8.0;

                double d =
                    point.DistanceTo(text.Pos) * 0.12 +
                    widthPenalty;

                if (d < bestDist)
                {
                    bestDist = d;
                    best = text;
                }
            }

            return best;
        }

        private OngGioProtectionTextInfo FindNearestProtectionTextToPoint(
            Point3d point,
            List<OngGioProtectionTextInfo> texts)
        {
            if (texts == null || texts.Count == 0)
                return null;

            OngGioProtectionTextInfo best = null;
            double bestDist = double.MaxValue;

            foreach (OngGioProtectionTextInfo text in texts)
            {
                if (text == null)
                    continue;

                double d = point.DistanceTo(text.Pos);
                if (d < bestDist)
                {
                    bestDist = d;
                    best = text;
                }
            }

            return best;
        }

        private Vector3d FindReducerExtensionDirection(
            Point3d reducerEnd,
            Point3d reducerMiddle,
            OngGioCenterlineCandidate reducer,
            List<OngGioCenterlineCandidate> allCandidates)
        {
            Vector3d fallback = reducerMiddle - reducerEnd;
            if (fallback.Length < 1e-9)
                fallback = reducer.Direction;
            fallback = fallback.GetNormal();

            if (allCandidates == null)
                return fallback;

            OngGioCenterlineCandidate best = null;
            double bestScore = double.MaxValue;

            foreach (OngGioCenterlineCandidate candidate in allCandidates)
            {
                if (candidate == null ||
                    ReferenceEquals(candidate, reducer) ||
                    candidate.IsArc ||
                    candidate.IsReducer)
                    continue;

                double t;
                double d =
                    DistancePointToSegment(
                        reducerEnd,
                        candidate.Start,
                        candidate.End,
                        out t);

                if (d > Math.Max(500.0, candidate.DuctWidth * 0.75))
                    continue;

                double score =
                    d +
                    (1.0 -
                     Math.Abs(
                         candidate.Direction.GetNormal()
                             .DotProduct(fallback))) * 100.0;

                if (score < bestScore)
                {
                    bestScore = score;
                    best = candidate;
                }
            }

            if (best == null)
                return fallback;

            Vector3d dir = best.Direction.GetNormal();
            if (dir.DotProduct(fallback) < 0.0)
                dir = dir.Negate();

            return dir;
        }

        private Polyline CreatePolylineFromOngGioCandidate(
            OngGioCenterlineCandidate candidate)
        {
            if (candidate == null)
                return null;

            Polyline pl = new Polyline();

            if (candidate.Vertices != null &&
                candidate.Vertices.Count >= 2)
            {
                for (int i = 0; i < candidate.Vertices.Count; i++)
                {
                    Point3d p = candidate.Vertices[i];
                    pl.AddVertexAt(
                        i,
                        new Point2d(p.X, p.Y),
                        0, 0, 0);
                }
            }
            else if (candidate.IsArc)
            {
                double bulge =
                    Math.Tan(candidate.ArcIncludedAngle / 4.0);

                pl.AddVertexAt(
                    0,
                    new Point2d(
                        candidate.Start.X,
                        candidate.Start.Y),
                    bulge,
                    0, 0);
                pl.AddVertexAt(
                    1,
                    new Point2d(
                        candidate.End.X,
                        candidate.End.Y),
                    0,
                    0, 0);
            }
            else
            {
                pl.AddVertexAt(
                    0,
                    new Point2d(
                        candidate.Start.X,
                        candidate.Start.Y),
                    0, 0, 0);
                pl.AddVertexAt(
                    1,
                    new Point2d(
                        candidate.End.X,
                        candidate.End.Y),
                    0, 0, 0);
            }

            return pl;
        }

        private void AddOngGioLabel(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            string layerName,
            string labelText,
            double width,
            Point3d textPt,
            Vector3d direction)
        {
            try
            {
                DBText label = new DBText();
                label.SetDatabaseDefaults(db);
                label.TextStyleId = db.Textstyle;
                label.TextString = labelText;
                label.Height = Math.Max(
                    MinimumLabelTextHeight,
                    width * 0.15);
                label.WidthFactor = 1.0;
                label.Layer = layerName;
                label.ColorIndex = 256;
                label.Rotation =
                    GetReadableRotation(direction);
                label.Justify = AttachmentPoint.MiddleCenter;
                label.AlignmentPoint = textPt;
                label.Position = textPt;

                btr.AppendEntity(label);
                tr.AddNewlyCreatedDBObject(label, true);

                try { label.AdjustAlignment(db); } catch { }
            }
            catch { }
        }

        private string BuildOngGioLayerName(
            string layerPrefix,
            string ogType,
            string size,
            string protection)
        {
            string sizeForLayer = size;
            if (!string.IsNullOrWhiteSpace(protection))
                sizeForLayer = size + "_" + protection;

            return
                $"{layerPrefix}_{CleanLayerText(ogType)}_{CleanLayerText(sizeForLayer)}";
        }

        private static string BuildOngGioDisplayText(
            string size,
            string protection)
        {
            if (string.IsNullOrWhiteSpace(protection))
                return size;

            return (size + " " + protection).Trim();
        }

        private static Point3d PointAtAngle(
            Point3d center,
            double radius,
            double angle)
        {
            return new Point3d(
                center.X + Math.Cos(angle) * radius,
                center.Y + Math.Sin(angle) * radius,
                center.Z);
        }

        private static double NormalizePositiveAngle(double angle)
        {
            while (angle < 0.0)
                angle += Math.PI * 2.0;
            while (angle >= Math.PI * 2.0)
                angle -= Math.PI * 2.0;
            return angle;
        }

        private static double NormalizeSignedAngle(double angle)
        {
            while (angle <= -Math.PI)
                angle += Math.PI * 2.0;
            while (angle > Math.PI)
                angle -= Math.PI * 2.0;
            return angle;
        }

        private static bool AreParallel(
            Vector3d a,
            Vector3d b,
            double angleToleranceDegrees)
        {
            if (a.Length < 1e-9 || b.Length < 1e-9)
                return false;

            Vector3d na = a.GetNormal();
            Vector3d nb = b.GetNormal();
            double dot = Math.Abs(na.DotProduct(nb));
            double cos =
                Math.Cos(
                    angleToleranceDegrees *
                    Math.PI / 180.0);

            return dot >= cos;
        }

        private static bool AreSimilarLength(
            double a,
            double b,
            double toleranceRatio)
        {
            double max = Math.Max(Math.Abs(a), Math.Abs(b));
            if (max < 1e-9)
                return false;

            return Math.Abs(a - b) / max <= toleranceRatio;
        }

        private static double DistancePointToInfiniteLine(
            Point3d p,
            Point3d linePoint,
            Vector3d unitDirection)
        {
            Vector3d v = p - linePoint;
            Vector3d perpendicular =
                v - unitDirection * v.DotProduct(unitDirection);

            return perpendicular.Length;
        }

        private static double DistancePointToSegment(
            Point3d p,
            Point3d a,
            Point3d b,
            out double t)
        {
            Vector3d ab = b - a;
            double len2 = ab.DotProduct(ab);

            if (len2 < 1e-9)
            {
                t = 0.0;
                return p.DistanceTo(a);
            }

            t = ((p - a).DotProduct(ab)) / len2;
            double tc = Math.Max(0.0, Math.Min(1.0, t));
            Point3d closest = a + ab * tc;

            return p.DistanceTo(closest);
        }

        private static Point3d ProjectPointToSegment(
            Point3d p,
            Point3d a,
            Point3d b)
        {
            double t;
            DistancePointToSegment(p, a, b, out t);
            t = Math.Max(0.0, Math.Min(1.0, t));
            Vector3d ab = b - a;
            return a + ab * t;
        }

        private static void RefreshOngGioCandidateGeometry(
            OngGioCenterlineCandidate candidate)
        {
            if (candidate == null)
                return;

            Vector3d v = candidate.End - candidate.Start;
            double len = v.Length;

            if (len < 1e-9)
                return;

            candidate.Length = len;
            candidate.Direction = v.GetNormal();
            candidate.Mid =
                MidPoint(candidate.Start, candidate.End);
        }

        private static Point3d MidPoint(
            Point3d a,
            Point3d b)
        {
            return new Point3d(
                (a.X + b.X) / 2.0,
                (a.Y + b.Y) / 2.0,
                (a.Z + b.Z) / 2.0);
        }

        private static double DotPoint(
            Point3d p,
            Vector3d direction)
        {
            return p.X * direction.X +
                   p.Y * direction.Y +
                   p.Z * direction.Z;
        }

        private static void Swap(
            ref double a,
            ref double b)
        {
            double t = a;
            a = b;
            b = t;
        }

        private static double GetReadableRotation(
            Vector3d direction)
        {
            double angle =
                Math.Atan2(direction.Y, direction.X);

            while (angle < 0.0)
                angle += Math.PI * 2.0;
            while (angle >= Math.PI * 2.0)
                angle -= Math.PI * 2.0;

            if (angle > Math.PI / 2.0 &&
                angle <= Math.PI * 3.0 / 2.0)
            {
                angle -= Math.PI;
            }

            return angle;
        }

        private bool TryParseOngGioType(
            string source,
            out string ogType)
        {
            ogType = "";
            if (string.IsNullOrWhiteSpace(source))
                return false;

            string u = BoDauTiengViet(source.Trim());

            // Khớp các loại OG
            string[][] map =
            {
                new[] { "OG HUT KHOI", "OG HÚT KHÓI" },
                new[] { "HUT KHOI", "OG HÚT KHÓI" },
                new[] { "OG THAI", "OG THẢI" },
                new[] { "OG LANH", "OG LẠNH" },
                new[] { "OG CAP", "OG CẤP" },
                new[] { "OG HOI", "OG HỒI" },
                new[] { "ONG GIO THAI", "OG THẢI" },
                new[] { "ONG GIO", "OG THẢI" },
            };

            foreach (var pair in map)
            {
                if (u.Contains(pair[0]))
                {
                    ogType = pair[1];
                    return true;
                }
            }

            // OG đứng riêng + từ sau
            Match m = Regex.Match(
                u,
                @"\bOG\s*(THAI|HUT|LANH|CAP|HOI|KHOI)?");
            if (m.Success)
            {
                string k = m.Groups[1].Value;
                if (k.Contains("HUT") || k.Contains("KHOI"))
                    ogType = "OG HÚT KHÓI";
                else if (k == "LANH")
                    ogType = "OG LẠNH";
                else if (k == "CAP")
                    ogType = "OG CẤP";
                else if (k == "HOI")
                    ogType = "OG HỒI";
                else
                    ogType = "OG THẢI";
                return true;
            }

            return false;
        }

        private void BtnAutoConvertPipe_Click(
            object sender,
            RoutedEventArgs e)
        {
            PipeUiContext ctx = GetContext(sender);

            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var ed = doc.Editor;
            var db = doc.Database;

            string layerPrefix =
                GetLayerPrefix(ctx);

            bool isOngGio =
                CheckIsOngGio(ctx);

            bool isFireFighting =
                IsFireFightingPipeContext(ctx);

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            PromptSelectionOptions pso =
                new PromptSelectionOptions();

            pso.MessageForAdding =
                "\nQuét chọn toàn bộ khu vực tuyến ống, " +
                "nhánh rẽ, đầu phun và Text kích thước: ";

            TypedValue[] tvs =
                new TypedValue[]
                {
                    new TypedValue(
                        (int)DxfCode.Operator,
                        "<OR"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "LINE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "LWPOLYLINE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "POLYLINE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "TEXT"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "MTEXT"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "INSERT"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "CIRCLE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "ARC"),
                    new TypedValue(
                        (int)DxfCode.Operator,
                        "OR>")
                };

            SelectionFilter filter =
                new SelectionFilter(tvs);

            PromptSelectionResult psr =
                ed.GetSelection(pso, filter);

            if (psr.Status != PromptStatus.OK ||
                psr.Value.Count == 0)
            {
                return;
            }

            using (doc.LockDocument())
            {
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    BlockTableRecord btr =
                        (BlockTableRecord)tr.GetObject(
                            db.CurrentSpaceId,
                            OpenMode.ForWrite);

                    List<Curve> origCurves =
                        new List<Curve>();

                    List<Entity> intersectEntities =
                        new List<Entity>();

                    List<TextData> allTexts =
                        new List<TextData>();

                    List<Point3d> sprinklerCenters =
                        new List<Point3d>();

                    foreach (SelectedObject so in psr.Value)
                    {
                        Entity ent =
                            tr.GetObject(
                                so.ObjectId,
                                OpenMode.ForRead)
                                as Entity;

                        if (ent is Line ||
                            ent is Polyline ||
                            ent is Polyline2d ||
                            ent is Polyline3d)
                        {
                            origCurves.Add(ent as Curve);
                            intersectEntities.Add(ent);
                        }
                        else if (
                            ent is BlockReference blockReference)
                        {
                            intersectEntities.Add(ent);

                            foreach (
                                Point3d center in
                                GetCircularCentersFromBlock(
                                    tr,
                                    blockReference))
                            {
                                AddUniquePoint(
                                    sprinklerCenters,
                                    center,
                                    5.0);
                            }
                        }
                        else if (ent is Circle circle)
                        {
                            intersectEntities.Add(ent);

                            AddUniquePoint(
                                sprinklerCenters,
                                circle.Center,
                                5.0);
                        }
                        else if (ent is Arc)
                        {
                            intersectEntities.Add(ent);
                        }
                        else if (ent is DBText txt)
                        {
                            Point3d pt =
                                (txt.Justify !=
                                    AttachmentPoint.BaseLeft &&
                                 (txt.AlignmentPoint.X != 0 ||
                                  txt.AlignmentPoint.Y != 0))
                                    ? txt.AlignmentPoint
                                    : txt.Position;

                            string str =
                                txt.TextString
                                    .Replace("\r", "")
                                    .Replace("\n", "")
                                    .Trim();

                            if (TryParseAutomaticPipeSize(
                                ctx,
                                str,
                                out string detectedSize,
                                out double detectedWidth))
                            {
                                allTexts.Add(
                                    new TextData
                                    {
                                        Position = pt,
                                        Rotation = txt.Rotation,
                                        TextString =
                                            detectedSize,
                                        LayerName =
                                            $"{layerPrefix}_" +
                                            $"{CleanLayerText(detectedSize)}",
                                        Width =
                                            isFireFighting
                                                ? FixedDnPipeDisplayWidth
                                                : detectedWidth
                                    });
                            }
                        }
                        else if (ent is MText mtxt)
                        {
                            string str =
                                mtxt.Text
                                    .Replace("\r", "")
                                    .Replace("\n", "")
                                    .Trim();

                            if (TryParseAutomaticPipeSize(
                                ctx,
                                str,
                                out string detectedSize,
                                out double detectedWidth))
                            {
                                allTexts.Add(
                                    new TextData
                                    {
                                        Position =
                                            mtxt.Location,
                                        Rotation =
                                            mtxt.Rotation,
                                        TextString =
                                            detectedSize,
                                        LayerName =
                                            $"{layerPrefix}_" +
                                            $"{CleanLayerText(detectedSize)}",
                                        Width =
                                            isFireFighting
                                                ? FixedDnPipeDisplayWidth
                                                : detectedWidth
                                    });
                            }
                        }
                    }

                    if (origCurves.Count == 0 ||
                        allTexts.Count == 0)
                    {
                        MessageBox.Show(
                            "Phải quét trúng ít nhất 1 đường ống " +
                            "và 1 Text kích thước!",
                            "Cảnh báo");

                        return;
                    }

                    Dictionary<Curve, List<TextProjectionData>>
                        textProjectionsByCurve =
                            MapTextsToOriginalCurves(
                                origCurves,
                                allTexts);

                    Dictionary<Curve, List<SprinklerProjectionData>>
                        sprinklerProjectionsByCurve =
                            MapSprinklerCentersToCurves(
                                origCurves,
                                sprinklerCenters);

                    int detectedSprinklerCount =
                        sprinklerProjectionsByCurve
                            .Sum(pair => pair.Value.Count);

                    int sizeTransitionCount = 0;

                    List<SegmentData> allSegments =
                        new List<SegmentData>();

                    Plane xyPlane =
                        new Plane(
                            Point3d.Origin,
                            Vector3d.ZAxis);

                    foreach (Curve mainCurve in origCurves)
                    {
                        Point3dCollection splitPoints =
                            new Point3dCollection();

                        foreach (
                            Entity otherEnt
                            in intersectEntities)
                        {
                            if (mainCurve == otherEnt)
                                continue;

                            try
                            {
                                Point3dCollection pts =
                                    new Point3dCollection();

                                mainCurve.IntersectWith(
                                    otherEnt,
                                    Intersect.OnBothOperands,
                                    xyPlane,
                                    pts,
                                    IntPtr.Zero,
                                    IntPtr.Zero);

                                foreach (Point3d p in pts)
                                {
                                    splitPoints.Add(
                                        mainCurve
                                            .GetClosestPointTo(
                                                p,
                                                false));
                                }
                            }
                            catch
                            {
                            }

                            try
                            {
                                List<Point3d> testPoints =
                                    new List<Point3d>();

                                if (otherEnt
                                    is BlockReference blk)
                                {
                                    testPoints.Add(
                                        blk.Position);
                                }
                                else if (otherEnt
                                    is Circle cir)
                                {
                                    testPoints.Add(
                                        cir.Center);
                                }
                                else if (otherEnt
                                    is Curve oc)
                                {
                                    testPoints.Add(
                                        oc.StartPoint);

                                    testPoints.Add(
                                        oc.EndPoint);
                                }

                                foreach (
                                    Point3d pt in testPoints)
                                {
                                    Point3d flatPt =
                                        new Point3d(
                                            pt.X,
                                            pt.Y,
                                            mainCurve
                                                .StartPoint.Z);

                                    Point3d closest =
                                        mainCurve
                                            .GetClosestPointTo(
                                                flatPt,
                                                false);

                                    if (closest.DistanceTo(
                                        flatPt) < 150.0)
                                    {
                                        splitPoints.Add(
                                            closest);
                                    }
                                }
                            }
                            catch
                            {
                            }
                        }

                        if (mainCurve is Polyline pl)
                        {
                            for (int i = 0;
                                i < pl.NumberOfVertices;
                                i++)
                            {
                                splitPoints.Add(
                                    pl.GetPoint3dAt(i));
                            }
                        }

                        if (sprinklerProjectionsByCurve
                            .TryGetValue(
                                mainCurve,
                                out List<SprinklerProjectionData>
                                    curveSprinklers))
                        {
                            foreach (
                                SprinklerProjectionData sprinkler
                                in curveSprinklers)
                            {
                                splitPoints.Add(
                                    sprinkler.PointOnCurve);
                            }
                        }

                        List<double> validDistances =
                            new List<double>();

                        double totalLength =
                            mainCurve
                                .GetDistanceAtParameter(
                                    mainCurve.EndParam);

                        foreach (Point3d pt in splitPoints)
                        {
                            try
                            {
                                double dist =
                                    mainCurve.GetDistAtPoint(
                                        mainCurve
                                            .GetClosestPointTo(
                                                pt,
                                                false));

                                if (dist > 1.0 &&
                                    dist < totalLength - 1.0)
                                {
                                    if (!validDistances.Any(
                                        d => Math.Abs(
                                            d - dist) < 1.0))
                                    {
                                        validDistances.Add(
                                            dist);
                                    }
                                }
                            }
                            catch
                            {
                            }
                        }

                        List<double> textTransitionDistances =
                            GetTextSizeTransitionDistances(
                                mainCurve,
                                textProjectionsByCurve,
                                validDistances);

                        sizeTransitionCount +=
                            textTransitionDistances.Count;

                        foreach (
                            double transitionDistance
                            in textTransitionDistances)
                        {
                            if (transitionDistance > 1.0 &&
                                transitionDistance <
                                    totalLength - 1.0 &&
                                !validDistances.Any(
                                    d => Math.Abs(
                                        d -
                                        transitionDistance) <
                                        1.0))
                            {
                                validDistances.Add(
                                    transitionDistance);
                            }
                        }

                        validDistances.Sort();

                        Point3dCollection finalSplitPts =
                            new Point3dCollection();

                        foreach (double d in validDistances)
                        {
                            finalSplitPts.Add(
                                mainCurve.GetPointAtDist(d));
                        }

                        if (finalSplitPts.Count > 0)
                        {
                            try
                            {
                                DBObjectCollection splits =
                                    mainCurve.GetSplitCurves(
                                        finalSplitPts);

                                foreach (DBObject obj in splits)
                                {
                                    if (obj is Curve c)
                                    {
                                        allSegments.Add(
                                            new SegmentData
                                            {
                                                Curve = c,
                                                OriginalParent =
                                                    mainCurve
                                            });
                                    }
                                }
                            }
                            catch
                            {
                                allSegments.Add(
                                    new SegmentData
                                    {
                                        Curve =
                                            mainCurve.Clone()
                                                as Curve,
                                        OriginalParent =
                                            mainCurve
                                    });
                            }
                        }
                        else
                        {
                            allSegments.Add(
                                new SegmentData
                                {
                                    Curve =
                                        mainCurve.Clone()
                                            as Curve,
                                    OriginalParent =
                                        mainCurve
                                });
                        }
                    }

                    foreach (
                        KeyValuePair<Curve, List<TextProjectionData>>
                            curveTextPair
                        in textProjectionsByCurve)
                    {
                        foreach (
                            TextProjectionData projection
                            in curveTextPair.Value)
                        {
                            TextData txt = projection.Text;
                            SegmentData bestSeg = null;
                            double minScore = double.MaxValue;

                            foreach (
                                SegmentData seg
                                in allSegments.Where(
                                    item =>
                                        item.OriginalParent ==
                                        curveTextPair.Key))
                            {
                                if (!TryGetClosestPointInPlan(
                                    seg.Curve,
                                    txt.Position,
                                    out Point3d closestPtOnPipe,
                                    out double distToCurve))
                                {
                                    continue;
                                }

                                if (distToCurve > 3500.0)
                                    continue;

                                // Chỉ nhận chữ song song với đoạn ống.
                                if (!IsTextParallelToCurve(
                                    seg.Curve,
                                    closestPtOnPipe,
                                    txt.Rotation))
                                {
                                    continue;
                                }

                                double angleScore =
                                    TinhGocLech(
                                        seg.Curve,
                                        closestPtOnPipe,
                                        txt.Rotation) *
                                    5000.0;

                                double score =
                                    distToCurve +
                                    angleScore;

                                if (score < minScore)
                                {
                                    minScore = score;
                                    bestSeg = seg;
                                }
                            }

                            if (bestSeg != null &&
                                minScore <
                                bestSeg.BestScore)
                            {
                                bestSeg.Layer =
                                    txt.LayerName;

                                bestSeg.Width =
                                    txt.Width;

                                bestSeg.LabelText =
                                    ExtractSizeOnlyText(
                                        txt.TextString);

                                bestSeg.BestScore =
                                    minScore;

                                bestSeg.HasExplicitSize = true;
                            }
                        }
                    }

                    int topologyInheritedCount = 0;

                    if (isFireFighting)
                    {
                        topologyInheritedCount =
                            PropagateFirePipeSizesByTopology(
                                allSegments);
                    }
                    else
                    {
                        // Giữ cách truyền cũ cho ACMV/CTN: chỉ nối tiếp
                        // thẳng hàng, không thay đổi hành vi các tab khác.
                        bool changed;

                        do
                        {
                            changed = false;

                            foreach (
                                var orphan in allSegments.Where(
                                    s => s.Layer == null))
                            {
                                foreach (
                                    var parent in allSegments.Where(
                                        s => s.Layer != null))
                                {
                                    if (IsTouching(
                                            orphan.Curve,
                                            parent.Curve,
                                            out Point3d touchPt) &&
                                        IsCollinear(
                                            orphan.Curve,
                                            parent.Curve,
                                            touchPt))
                                    {
                                        orphan.Layer =
                                            parent.Layer;

                                        orphan.Width =
                                            parent.Width;

                                        orphan.LabelText =
                                            parent.LabelText;

                                        changed = true;
                                        break;
                                    }
                                }
                            }
                        }
                        while (changed);
                    }

                    int sprinklerConnectionCount =
                        CreateSprinklerCenterConnections(
                            tr,
                            db,
                            btr,
                            allSegments,
                            sprinklerProjectionsByCurve,
                            isOngGio);

                    int convertedCount = 0;
                    int generatedSizeTextCount = 0;

                    var groupedByOriginal =
                        allSegments
                            .GroupBy(
                                s => s.OriginalParent)
                            .ToList();

                    foreach (var group in groupedByOriginal)
                    {
                        List<SegmentData> segs =
                            group.ToList();

                        List<Entity> finalEntitiesToAdd =
                            new List<Entity>();

                        bool modified = false;

                        for (int i = 0;
                            i < segs.Count;)
                        {
                            var current = segs[i];

                            if (current.Layer == null)
                            {
                                finalEntitiesToAdd.Add(
                                    current.Curve.Clone()
                                        as Entity);

                                i++;
                            }
                            else
                            {
                                int j = i;

                                List<Curve> mergeList =
                                    new List<Curve>();

                                while (j < segs.Count &&
                                    segs[j].Layer ==
                                    current.Layer)
                                {
                                    mergeList.Add(
                                        segs[j].Curve);

                                    j++;
                                }

                                EnsureLayerExists(
                                    tr,
                                    db,
                                    current.Layer,
                                    isOngGio);

                                Polyline mergedPline =
                                    new Polyline();

                                mergedPline
                                    .SetDatabaseDefaults();

                                mergedPline.Layer =
                                    current.Layer;

                                mergedPline.Color =
                                    Autodesk.AutoCAD.Colors.Color
                                        .FromColorIndex(
                                            ColorMethod.ByLayer,
                                            256);

                                mergedPline.ConstantWidth =
                                    current.Width;

                                List<Point3d> allPts =
                                    new List<Point3d>();

                                foreach (
                                    var c in mergeList)
                                {
                                    if (c is Line l)
                                    {
                                        allPts.Add(
                                            l.StartPoint);

                                        allPts.Add(
                                            l.EndPoint);
                                    }
                                    else if (
                                        c is Polyline p &&
                                        p.NumberOfVertices > 0)
                                    {
                                        allPts.Add(
                                            p.GetPoint3dAt(0));

                                        allPts.Add(
                                            p.GetPoint3dAt(
                                                p.NumberOfVertices -
                                                1));
                                    }
                                }

                                List<Point3d> uniquePts =
                                    new List<Point3d>();

                                foreach (var p in allPts)
                                {
                                    if (!uniquePts.Any(
                                        up =>
                                            up.DistanceTo(p) <
                                            1.0))
                                    {
                                        uniquePts.Add(p);
                                    }
                                }

                                if (uniquePts.Count >= 2)
                                {
                                    Point3d pA =
                                        uniquePts[0];

                                    Point3d pB =
                                        uniquePts[1];

                                    double maxD =
                                        pA.DistanceTo(pB);

                                    for (int a = 0;
                                        a < uniquePts.Count;
                                        a++)
                                    {
                                        for (int b = a + 1;
                                            b < uniquePts.Count;
                                            b++)
                                        {
                                            double d =
                                                uniquePts[a]
                                                    .DistanceTo(
                                                        uniquePts[b]);

                                            if (d > maxD)
                                            {
                                                maxD = d;
                                                pA = uniquePts[a];
                                                pB = uniquePts[b];
                                            }
                                        }
                                    }

                                    double sumLen =
                                        mergeList.Sum(
                                            c =>
                                                c.GetDistanceAtParameter(
                                                    c.EndParam));

                                    if (Math.Abs(
                                        sumLen - maxD) < 5.0)
                                    {
                                        mergedPline.AddVertexAt(
                                            0,
                                            new Point2d(
                                                pA.X,
                                                pA.Y),
                                            0,
                                            current.Width,
                                            current.Width);

                                        mergedPline.AddVertexAt(
                                            1,
                                            new Point2d(
                                                pB.X,
                                                pB.Y),
                                            0,
                                            current.Width,
                                            current.Width);
                                    }
                                    else
                                    {
                                        int vIdx = 0;

                                        foreach (
                                            var c in mergeList)
                                        {
                                            if (c is Line l)
                                            {
                                                if (vIdx == 0)
                                                {
                                                    mergedPline
                                                        .AddVertexAt(
                                                            vIdx++,
                                                            new Point2d(
                                                                l.StartPoint.X,
                                                                l.StartPoint.Y),
                                                            0,
                                                            current.Width,
                                                            current.Width);
                                                }

                                                mergedPline
                                                    .AddVertexAt(
                                                        vIdx++,
                                                        new Point2d(
                                                            l.EndPoint.X,
                                                            l.EndPoint.Y),
                                                        0,
                                                        current.Width,
                                                        current.Width);
                                            }
                                            else if (
                                                c is Polyline p)
                                            {
                                                for (
                                                    int k = 0;
                                                    k <
                                                    p.NumberOfVertices;
                                                    k++)
                                                {
                                                    Point3d pt =
                                                        p.GetPoint3dAt(
                                                            k);

                                                    mergedPline
                                                        .AddVertexAt(
                                                            vIdx++,
                                                            new Point2d(
                                                                pt.X,
                                                                pt.Y),
                                                            0,
                                                            current.Width,
                                                            current.Width);
                                                }
                                            }
                                        }
                                    }
                                }

                                finalEntitiesToAdd.Add(
                                    mergedPline);

                                string generatedLabelText =
                                    !string.IsNullOrWhiteSpace(
                                        current.LabelText)
                                        ? current.LabelText
                                        : ExtractSizeOnlyText(
                                            current.Layer);

                                DBText generatedSizeLabel =
                                    CreateAutomaticSizeLabel(
                                        db,
                                        mergedPline,
                                        current.Layer,
                                        generatedLabelText,
                                        current.Width);

                                if (generatedSizeLabel != null)
                                {
                                    finalEntitiesToAdd.Add(
                                        generatedSizeLabel);

                                    generatedSizeTextCount++;
                                }

                                modified = true;
                                convertedCount++;
                                i = j;
                            }
                        }

                        if (modified)
                        {
                            group.Key.UpgradeOpen();
                            group.Key.Erase();

                            foreach (
                                Entity newEnt
                                in finalEntitiesToAdd)
                            {
                                if (newEnt == null)
                                    continue;

                                btr.AppendEntity(newEnt);

                                tr.AddNewlyCreatedDBObject(
                                    newEnt,
                                    true);

                                if (newEnt
                                    is DBText generatedText)
                                {
                                    generatedText
                                        .AdjustAlignment(db);
                                }
                            }
                        }
                    }

                    tr.Commit();

                    ed.WriteMessage(
                        $"\n[{AutoConvertBuild}] Hoàn tất: " +
                        $"Đã tạo {convertedCount} đoạn ống, " +
                        $"tách {sizeTransitionCount} vị trí " +
                        $"chuyển kích thước, tạo mới " +
                        $"{generatedSizeTextCount} chữ kích thước, " +
                        $"kế thừa topology {topologyInheritedCount} đoạn, " +
                        $"nhận {detectedSprinklerCount} tâm đầu phun " +
                        $"và nối thêm {sprinklerConnectionCount} " +
                        $"đoạn tới tâm.");
                }
            }
        }



        // ============================================================
        // FIX40A - PHỤ KIỆN THỦ CÔNG TỪ THƯ VIỆN STEEL
        // UI: TÊN PK (1/4) + SIZE (3/4) + ĐẶT TB
        // ============================================================

        private void TxtPhuKienThuVienThem_KeyDown(
            object sender,
            WpfKeyEventArgs e)
        {
            if (e.Key != WpfKey.Enter)
                return;

            string value =
                (TxtPhuKienThuVienThem?.Text ?? "")
                    .Trim();

            if (string.IsNullOrWhiteSpace(value))
                return;

            AddAndSelectManualLibraryItem(
                LstPhuKienThuVien,
                value);

            TxtPhuKienThuVienThem.Clear();
            e.Handled = true;
        }

        private void TxtSizePhuKienThuVienThem_KeyDown(
            object sender,
            WpfKeyEventArgs e)
        {
            if (e.Key != WpfKey.Enter)
                return;

            string value =
                NormalizeManualLibrarySize(
                    TxtSizePhuKienThuVienThem?.Text ?? "");

            if (string.IsNullOrWhiteSpace(value))
            {
                MessageBox.Show(
                    "Size không hợp lệ.\n\n" +
                    "Ví dụ:\n" +
                    "DN50\n" +
                    "DN150x80 (Tê giảm)",
                    "PHỤ KIỆN");
                return;
            }

            AddAndSelectManualLibraryItem(
                LstSizePhuKienThuVien,
                value);

            TxtSizePhuKienThuVienThem.Clear();
            e.Handled = true;
        }

        private static void AddAndSelectManualLibraryItem(
            WpfListBox listBox,
            string value)
        {
            if (listBox == null ||
                string.IsNullOrWhiteSpace(value))
            {
                return;
            }

            foreach (object obj in listBox.Items)
            {
                string old =
                    GetManualLibraryItemText(obj);

                if (string.Equals(
                        old,
                        value,
                        StringComparison.OrdinalIgnoreCase))
                {
                    listBox.SelectedItem = obj;
                    listBox.ScrollIntoView(obj);
                    return;
                }
            }

            WpfListBoxItem item =
                new WpfListBoxItem
                {
                    Content = value
                };

            listBox.Items.Add(item);
            listBox.SelectedItem = item;
            listBox.ScrollIntoView(item);
        }

        private static string GetManualLibraryItemText(
            object item)
        {
            if (item == null)
                return "";

            if (item is WpfListBoxItem lbi)
            {
                return (lbi.Content ?? "")
                    .ToString()
                    .Trim();
            }

            return item.ToString()?.Trim() ?? "";
        }

        private static string GetSelectedManualLibraryItem(
            WpfListBox listBox)
        {
            if (listBox == null ||
                listBox.SelectedItem == null)
            {
                return "";
            }

            return GetManualLibraryItemText(
                listBox.SelectedItem);
        }

        private static string NormalizeManualLibrarySize(
            string raw)
        {
            string u =
                (raw ?? "")
                    .Trim()
                    .ToUpperInvariant()
                    .Replace(" ", "")
                    .Replace("×", "X")
                    .Replace("*", "X");

            if (string.IsNullOrWhiteSpace(u))
                return "";

            Match pair =
                Regex.Match(
                    u,
                    @"^(?:DN)?(\d{1,4}(?:[.,]\d+)?)X(?:DN)?(\d{1,4}(?:[.,]\d+)?)$",
                    RegexOptions.IgnoreCase);

            if (pair.Success)
            {
                string a =
                    pair.Groups[1].Value
                        .Replace(',', '.');

                string b =
                    pair.Groups[2].Value
                        .Replace(',', '.');

                return "DN" + a + "x" + b;
            }

            Match one =
                Regex.Match(
                    u,
                    @"^(?:DN)?(\d{1,4}(?:[.,]\d+)?)$",
                    RegexOptions.IgnoreCase);

            if (!one.Success)
                return "";

            return "DN" +
                one.Groups[1].Value
                    .Replace(',', '.');
        }

        private static bool TrySplitManualTeeReducerSize(
            string sizeText,
            out string mainSize,
            out string branchSize)
        {
            mainSize = "";
            branchSize = "";

            string normalized =
                NormalizeManualLibrarySize(
                    sizeText);

            Match m =
                Regex.Match(
                    normalized,
                    @"^DN(\d{1,4}(?:\.\d+)?)x(\d{1,4}(?:\.\d+)?)$",
                    RegexOptions.IgnoreCase);

            if (!m.Success)
                return false;

            mainSize =
                "DN" + m.Groups[1].Value;

            branchSize =
                "DN" + m.Groups[2].Value;

            return true;
        }

        private void BtnDatPhuKienThuVien_Click(
            object sender,
            RoutedEventArgs e)
        {
            string pk =
                GetSelectedManualLibraryItem(
                    LstPhuKienThuVien);

            string size =
                GetSelectedManualLibraryItem(
                    LstSizePhuKienThuVien);

            if (string.IsNullOrWhiteSpace(pk))
            {
                MessageBox.Show(
                    "Hãy chọn TÊN PK trước.",
                    "PHỤ KIỆN");
                return;
            }

            if (string.IsNullOrWhiteSpace(size))
            {
                MessageBox.Show(
                    "Hãy chọn SIZE trước.",
                    "PHỤ KIỆN");
                return;
            }

            string pkKey =
                NormalizeShopKey(pk);

            string fromSize =
                NormalizeManualLibrarySize(size);

            string toSize =
                fromSize;

            string fittingType = "";
            bool useShopFittingEngine = false;

            if (pkKey == "CO90" ||
                pkKey.Contains("CO90"))
            {
                fittingType = "ELBOW90";
                useShopFittingEngine = true;
            }
            else if (pkKey.Contains("LOI45") ||
                     pkKey.Contains("CO45") ||
                     pkKey.Contains("ELB45"))
            {
                fittingType = "ELBOW45";
                useShopFittingEngine = true;
            }
            else if (pkKey.Contains("TEDEU") ||
                     pkKey == "TEE" ||
                     pkKey == "TE")
            {
                fittingType = "TEE";
                useShopFittingEngine = true;
                toSize = fromSize;
            }
            else if (pkKey.Contains("TEGIAM") ||
                     pkKey.Contains("TETHU"))
            {
                // FIX40C: tên thật trong thư viện là TEED cho TÊ GIẢM.
                // Ví dụ: SCREW-TEED-DN20x15
                fittingType = "TEED";
                useShopFittingEngine = true;

                if (!TrySplitManualTeeReducerSize(
                        size,
                        out fromSize,
                        out toSize))
                {
                    MessageBox.Show(
                        "TÊ GIẢM cần 2 kích thước.\n\n" +
                        "Hãy nhập vào ô SIZE bên dưới theo dạng:\n" +
                        "DN150x80\n" +
                        "sau đó nhấn Enter và chọn size vừa thêm.",
                        "PHỤ KIỆN");
                    return;
                }
            }

            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var ed = doc.Editor;
            var db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            // Chữa cháy dùng thư viện STEEL.
            string libraryPath =
                FindShopFittingLibraryPath(
                    "STEEL",
                    db);

            if (string.IsNullOrWhiteSpace(libraryPath) ||
                !File.Exists(libraryPath))
            {
                MessageBox.Show(
                    "Không tìm thấy file thư viện STEEL trong thư mục DLL.\n\n" +
                    "Tên file hỗ trợ: Thu vien STEEL.dwg / STEEL.dwg",
                    "PHỤ KIỆN");
                return;
            }

            string genericBlockName = "";
            string shopBlockName = "";

            if (useShopFittingEngine)
            {
                // FIX40B:
                // Chỉ dùng bộ tìm block của VẼ SHOP.
                // KHÔNG gọi TryInsertShopLibraryFitting khi đặt thủ công,
                // vì hàm đó yêu cầu topology/hướng ống thật.
                shopBlockName =
                    FindShopFittingBlockName(
                        libraryPath,
                        fittingType,
                        fromSize,
                        toSize);

                if (string.IsNullOrWhiteSpace(shopBlockName))
                {
                    MessageBox.Show(
                        "Không tìm thấy block trong thư viện:\n\n" +
                        pk + " - " + size + "\n\n" +
                        "Đã tìm theo đúng bộ tên SCREW/WELD của VẼ SHOP.",
                        "PHỤ KIỆN");
                    return;
                }
            }
            else
            {
                genericBlockName =
                    FindManualAccessoryBlockName(
                        libraryPath,
                        pk,
                        fromSize);

                if (string.IsNullOrWhiteSpace(genericBlockName))
                {
                    MessageBox.Show(
                        "Không tìm thấy block phù hợp trong thư viện:\n\n" +
                        pk + " - " + fromSize + "\n\n" +
                        "Code đã dò theo tên phụ kiện + DN trong " +
                        Path.GetFileName(libraryPath) + ".",
                        "PHỤ KIỆN");
                    return;
                }
            }

            string layerName =
                BuildManualAccessoryLayerName(
                    pk,
                    fromSize,
                    toSize);

            int inserted = 0;

            ed.WriteMessage(
                "\n[ĐẶT TB] " +
                pk + " | " +
                (string.Equals(
                    fromSize,
                    toSize,
                    StringComparison.OrdinalIgnoreCase)
                    ? fromSize
                    : fromSize + "x" +
                      NormalizeShopDnToken(toSize).Replace("DN", "")) +
                " | Thư viện: " +
                Path.GetFileName(libraryPath) +
                "\nClick GẦN vị trí cần đặt. Tool ghép ĐƯỜNG TÂM CỔNG PHỤ KIỆN với ĐƯỜNG TÂM ỐNG để tự đặt đúng tâm + đúng hướng. Enter/ESC để kết thúc.");

            while (true)
            {
                PromptPointOptions ppo =
                    new PromptPointOptions(
                        "\nChọn điểm đặt " +
                        pk +
                        " [" +
                        size +
                        "] <Enter/ESC kết thúc>: ")
                    {
                        AllowNone = true
                    };

                PromptPointResult ppr =
                    ed.GetPoint(ppo);

                if (ppr.Status == PromptStatus.Cancel ||
                    ppr.Status == PromptStatus.None)
                {
                    break;
                }

                if (ppr.Status != PromptStatus.OK)
                    continue;

                bool ok = false;

                using (doc.LockDocument())
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    BlockTableRecord btr =
                        (BlockTableRecord)tr.GetObject(
                            db.CurrentSpaceId,
                            OpenMode.ForWrite);

                    EnsureShopLayerExists(
                        tr,
                        db,
                        layerName);

                    if (useShopFittingEngine)
                    {
                        // FIX40B:
                        // Manual = chèn đúng block tại điểm click,
                        // không yêu cầu topology / port-direction matching.
                        ok =
                            TryInsertManualShopFittingBlock(
                                tr,
                                db,
                                btr,
                                libraryPath,
                                shopBlockName,
                                fittingType,
                                fromSize,
                                toSize,
                                ppr.Value,
                                layerName);
                    }
                    else
                    {
                        ok =
                            TryInsertManualAccessoryBlock(
                                tr,
                                db,
                                btr,
                                libraryPath,
                                genericBlockName,
                                ppr.Value,
                                layerName);
                    }

                    if (ok)
                        tr.Commit();
                    else
                        tr.Abort();
                }

                if (!ok)
                {
                    MessageBox.Show(
                        "Không chèn được block:\n" +
                        pk + " - " + size +
                        "\n\nBlock đã tìm thấy nhưng AutoCAD không import/chèn được.",
                        "PHỤ KIỆN");
                    break;
                }

                inserted++;

                try
                {
                    ed.Regen();
                }
                catch
                {
                }
            }

            ed.WriteMessage(
                $"\n[ĐẶT TB] Đã chèn {inserted} phụ kiện " +
                $"{pk} {size}.");
        }

        private string BuildManualAccessoryLayerName(
            string pk,
            string fromSize,
            string toSize)
        {
            string pkKey =
                NormalizeShopKey(
                    pk ?? "");

            string a =
                CleanLayerText(
                    fromSize ?? "");

            string b =
                CleanLayerText(
                    toSize ?? "");

            // Dùng layer chuẩn SHOP cho 4 fitting chính để
            // chức năng THỐNG KÊ PHỤ KIỆN hiện tại vẫn nhận được.
            if (pkKey.Contains("CO90"))
                return "FF_SHOP_CO90_" + a;

            if (pkKey.Contains("LOI45") ||
                pkKey.Contains("CO45") ||
                pkKey.Contains("ELB45"))
            {
                return "FF_SHOP_COLOI45_" + a;
            }

            if (pkKey.Contains("TEDEU") ||
                pkKey.Contains("TEGIAM") ||
                pkKey.Contains("TETHU") ||
                pkKey == "TEE" ||
                pkKey == "TE")
            {
                return "FF_SHOP_TE_" +
                    a +
                    "-" +
                    b;
            }

            return "FF_SHOP_PK_" +
                CleanLayerText(
                    pkKey) +
                "_" +
                a;
        }

        private bool TryInsertManualShopFittingBlock(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            string libraryPath,
            string sourceBlockName,
            string fittingType,
            string fromSize,
            string toSize,
            Point3d insertPoint,
            string layerName)
        {
            if (tr == null ||
                db == null ||
                btr == null ||
                string.IsNullOrWhiteSpace(libraryPath) ||
                string.IsNullOrWhiteSpace(sourceBlockName))
            {
                return false;
            }

            ObjectId blockId =
                EnsureExternalBlockImported(
                    tr,
                    db,
                    libraryPath,
                    sourceBlockName);

            if (blockId.IsNull)
                return false;

            NormalizeShopImportedBlock(
                tr,
                blockId);

            ShopFittingPlacementInfo placement =
                null;

            try
            {
                placement =
                    AnalyzeShopFittingPlacement(
                        blockId,
                        fittingType,
                        fromSize,
                        toSize);
            }
            catch
            {
                placement = null;
            }

            double dn1 =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        fromSize));

            double dn2 =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        toSize));

            double refDn =
                Math.Max(
                    dn1,
                    dn2);

            if (refDn <= 0.0)
                refDn = 25.0;

            double refOutsideDiameter =
                GetFireSteelOutsideDiameterForPair(
                    fromSize,
                    toSize,
                    refDn);

            // ========================================================
            // FIX40H - CO HÀN DN65+
            //
            // SCREW và WELD không dùng chung hình học cổng nối.
            // Với WELD-ELB90 / WELD-ELB45 từ DN65 trở lên:
            // bỏ placement generic nếu có và đọc lại đúng TÂM HAI MẶT NỐI
            // bên ngoài của block WELD. Ø ngoài thực được dùng để chọn
            // đúng mặt nối, không dùng DN danh nghĩa.
            // ========================================================
            string sourceBlockKey =
                NormalizeShopKey(
                    sourceBlockName ?? "");

            bool isWeldElbow =
                sourceBlockKey.StartsWith(
                    "WELD",
                    StringComparison.OrdinalIgnoreCase) &&
                (IsElbow90Key(
                     NormalizeShopKey(
                         fittingType ?? "")) ||
                 IsElbow45Key(
                     NormalizeShopKey(
                         fittingType ?? "")));

            if (isWeldElbow &&
                refDn >= 65.0)
            {
                ShopFittingPlacementInfo weldPlacement =
                    AnalyzeManualWeldElbowTruePorts(
                        blockId,
                        fittingType,
                        fromSize,
                        toSize,
                        refOutsideDiameter);

                if (weldPlacement != null)
                {
                    placement =
                        weldPlacement;
                }
            }

            Point3d targetPoint =
                insertPoint;

            double rotation = 0.0;

            bool autoSnapped = false;
            bool autoRotated = false;

            string snapInfo = "SNAP=NO";
            string autoRotateInfo = "ROTATE=NO";

            // ========================================================
            // FIX40G - GIẢI ĐỒNG THỜI TÂM + GÓC
            //
            // Không còn:
            // 1) snap theo một logic,
            // 2) rồi xoay theo một logic khác.
            //
            // Mà dùng CHÍNH HAI ĐƯỜNG TÂM CỔNG NỐI của block:
            // Anchor -> Port.Center
            //
            // để match với CHÍNH HAI TIM ỐNG.
            // ========================================================
            if (placement != null &&
                TryResolveManualFittingTransformByPortCenterlines(
                    tr,
                    db,
                    insertPoint,
                    fittingType,
                    fromSize,
                    toSize,
                    refOutsideDiameter,
                    placement,
                    out Point3d solvedPoint,
                    out double solvedRotation,
                    out string solvedInfo))
            {
                targetPoint =
                    solvedPoint;

                rotation =
                    solvedRotation;

                autoSnapped = true;
                autoRotated = true;

                snapInfo =
                    "PORT-CENTERLINE-SNAP";

                autoRotateInfo =
                    solvedInfo;
            }
            else
            {
                // Nếu chưa giải được cả 2 đầu phụ kiện:
                // chỉ được SNAP tâm, KHÔNG tự xoay bằng logic mơ hồ.
                autoSnapped =
                    TrySnapManualFittingPointToPipeCenter(
                        tr,
                        db,
                        insertPoint,
                        fittingType,
                        fromSize,
                        toSize,
                        refOutsideDiameter,
                        out Point3d snappedPoint,
                        out snapInfo);

                if (autoSnapped)
                    targetPoint = snappedPoint;

                rotation = 0.0;
                autoRotated = false;

                autoRotateInfo =
                    placement == null
                        ? "không đọc được port block"
                        : "không match đủ đường tâm cổng phụ kiện với tim ống";
            }

            // ========================================================
            // Đưa ANCHOR của fitting đúng vào giao TIM ỐNG.
            // Sau đó rotation đã làm các centerline cổng trùng centerline ống.
            // ========================================================
            Point3d basePoint =
                targetPoint;

            if (placement != null)
            {
                try
                {
                    Vector3d anchorVector =
                        placement.Anchor
                            .GetAsVector()
                            .RotateBy(
                                rotation,
                                Vector3d.ZAxis);

                    basePoint =
                        targetPoint -
                        anchorVector;
                }
                catch
                {
                    basePoint =
                        targetPoint;
                }
            }
            else
            {
                try
                {
                    if (TryGetShopBlockLocalCenter(
                            tr,
                            blockId,
                            out Point3d localCenter,
                            out double _))
                    {
                        Vector3d localVector =
                            localCenter
                                .GetAsVector()
                                .RotateBy(
                                    rotation,
                                    Vector3d.ZAxis);

                        basePoint =
                            targetPoint -
                            localVector;
                    }
                }
                catch
                {
                    basePoint =
                        targetPoint;
                }
            }

            BlockReference br =
                new BlockReference(
                    basePoint,
                    blockId);

            br.SetDatabaseDefaults(db);
            br.Layer = layerName;
            br.Rotation = rotation;

            br.ScaleFactors =
                new Scale3d(
                    1.0,
                    1.0,
                    1.0);

            br.Color =
                Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                    ColorMethod.ByAci,
                    GetShopVisibleAciColor(layerName));

            br.LineWeight =
                Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight000;

            br.Transparency =
                new Autodesk.AutoCAD.Colors.Transparency(
                    (byte)255);

            br.Visible = true;

            btr.AppendEntity(br);
            tr.AddNewlyCreatedDBObject(
                br,
                true);

            try
            {
                double degree =
                    rotation *
                    180.0 /
                    Math.PI;

                double snapDistance =
                    PlanDistance(
                        insertPoint,
                        targetPoint);

                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument?
                    .Editor
                    .WriteMessage(
                        $"\n[ĐẶT TB FIX40H] " +
                        $"{fittingType} {fromSize}->{toSize} | " +
                        $"block={sourceBlockName} | " +
                        $"Øngoài={refOutsideDiameter:0.##} | " +
                        $"AUTO-SNAP={(autoSnapped ? "YES" : "NO")} " +
                        $"({snapDistance:0.##}) | " +
                        $"AUTO-ROTATE={(autoRotated ? "YES" : "NO")} | " +
                        $"rotation={degree:0.##}° | " +
                        $"{snapInfo} | {autoRotateInfo}");
            }
            catch
            {
            }

            return true;
        }


        private class ManualPipeAxisCandidate
        {
            public Point3d A { get; set; }
            public Point3d B { get; set; }
            public Vector3d Direction { get; set; }
            public string Layer { get; set; }
            public bool IsShopCenterline { get; set; }
            public double DistanceToPick { get; set; }
        }

        private bool TrySnapManualFittingPointToPipeCenter(
            Transaction tr,
            Database db,
            Point3d pick,
            string fittingType,
            string fromSize,
            string toSize,
            double expectedOutsideDiameter,
            out Point3d snappedPoint,
            out string info)
        {
            snappedPoint = pick;
            info = "SNAP=NO";

            if (tr == null ||
                db == null)
            {
                return false;
            }

            string key =
                NormalizeShopKey(
                    fittingType ?? "");

            List<ManualPipeAxisCandidate> axes =
                FindManualPipeAxesNearPoint(
                    tr,
                    db,
                    pick,
                    fromSize,
                    toSize,
                    expectedOutsideDiameter);

            if (axes == null ||
                axes.Count == 0)
            {
                info = "không thấy tim/ống gần điểm click";
                return false;
            }

            double maxSnap =
                Math.Max(
                    180.0,
                    Math.Min(
                        700.0,
                        expectedOutsideDiameter * 3.5 + 120.0));

            // ========================================================
            // CO90 / LƠI45:
            // lấy giao điểm hai TIM ỐNG phù hợp gần click nhất.
            // Với hướng trục line, Co45 = hai trục tạo ~45°.
            // ========================================================
            if (IsElbow90Key(key) ||
                IsElbow45Key(key))
            {
                double targetAxisAngle =
                    IsElbow90Key(key)
                        ? 90.0
                        : 45.0;

                if (TryFindBestManualAxisIntersection(
                        axes,
                        pick,
                        targetAxisAngle,
                        IsElbow90Key(key) ? 22.0 : 25.0,
                        maxSnap,
                        out Point3d joint,
                        out double actualAngle,
                        out string layerInfo))
                {
                    snappedPoint = joint;
                    info =
                        $"SNAP-GIAO-TIM | angle={actualAngle:0.##}° | {layerInfo}";
                    return true;
                }
            }

            // ========================================================
            // TÊ:
            // chỉ cần tìm giao của trục main + branch ~90°.
            // Main có thể là một LINE xuyên qua joint hoặc hai đoạn cùng trục.
            // ========================================================
            if (IsTeeKey(key))
            {
                if (TryFindBestManualAxisIntersection(
                        axes,
                        pick,
                        90.0,
                        25.0,
                        maxSnap,
                        out Point3d joint,
                        out double actualAngle,
                        out string layerInfo))
                {
                    snappedPoint = joint;
                    info =
                        $"SNAP-TÂM-TÊ | angle={actualAngle:0.##}° | {layerInfo}";
                    return true;
                }
            }

            // ========================================================
            // FALLBACK:
            // nếu chưa xác định được giao điểm, snap vào TIM ỐNG gần nhất.
            // Ưu tiên FF_SHOP_TAM_*.
            // ========================================================
            ManualPipeAxisCandidate nearest =
                axes
                    .OrderByDescending(x =>
                        x.IsShopCenterline)
                    .ThenBy(x =>
                        x.DistanceToPick)
                    .FirstOrDefault();

            if (nearest != null)
            {
                Point3d closest =
                    GetClosestPointOnManualSegment(
                        pick,
                        nearest.A,
                        nearest.B,
                        out double _);

                if (PlanDistance(
                        pick,
                        closest) <=
                    maxSnap)
                {
                    snappedPoint =
                        closest;

                    info =
                        $"SNAP-TIM-GẦN-NHẤT | layer={nearest.Layer}";
                    return true;
                }
            }

            return false;
        }

        private List<ManualPipeAxisCandidate> FindManualPipeAxesNearPoint(
            Transaction tr,
            Database db,
            Point3d pick,
            string fromSize,
            string toSize,
            double expectedOutsideDiameter)
        {
            List<ManualPipeAxisCandidate> best =
                new List<ManualPipeAxisCandidate>();

            if (tr == null ||
                db == null)
            {
                return best;
            }

            BlockTableRecord btr =
                tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForRead,
                    false) as BlockTableRecord;

            if (btr == null)
                return best;

            double tightTol =
                Math.Max(
                    35.0,
                    Math.Min(
                        180.0,
                        expectedOutsideDiameter * 0.75 + 25.0));

            double wideTol =
                Math.Max(
                    80.0,
                    Math.Min(
                        450.0,
                        expectedOutsideDiameter * 2.2 + 80.0));

            // Pass:
            // 0 centerline đúng DN
            // 1 line/pipe đúng DN
            // 2 centerline bất kỳ
            // 3 line/pipe bất kỳ
            for (int pass = 0;
                pass < 4;
                pass++)
            {
                bool centerOnly =
                    pass == 0 ||
                    pass == 2;

                bool sizeOnly =
                    pass == 0 ||
                    pass == 1;

                double tol =
                    centerOnly
                        ? tightTol
                        : wideTol;

                List<ManualPipeAxisCandidate> current =
                    new List<ManualPipeAxisCandidate>();

                foreach (ObjectId id in btr)
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased)
                    {
                        continue;
                    }

                    string layer =
                        (ent.Layer ?? "")
                            .Trim();

                    if (!IsManualPipeCandidateLayer(
                            layer,
                            centerOnly))
                    {
                        continue;
                    }

                    if (sizeOnly &&
                        !ManualPipeLayerMatchesAnySize(
                            layer,
                            fromSize,
                            toSize))
                    {
                        continue;
                    }

                    bool isCenter =
                        layer.StartsWith(
                            "FF_SHOP_TAM_",
                            StringComparison.OrdinalIgnoreCase);

                    if (ent is Line ln)
                    {
                        AddManualAxisCandidate(
                            current,
                            ln.StartPoint,
                            ln.EndPoint,
                            layer,
                            isCenter,
                            pick,
                            tol);
                    }
                    else if (ent is Polyline pl)
                    {
                        AddManualAxisCandidatesFromPolyline(
                            current,
                            pl,
                            layer,
                            isCenter,
                            pick,
                            tol);
                    }
                }

                DeduplicateManualAxisCandidates(
                    current,
                    Math.Max(
                        6.0,
                        expectedOutsideDiameter * 0.06));

                if (centerOnly)
                {
                    // Nếu có tim SHOP thật thì dùng luôn.
                    if (current.Count >= 2)
                        return current;

                    if (current.Count > best.Count)
                        best = current;
                }
                else
                {
                    // FIX40F:
                    // KHÔNG được lấy trực tiếp 2 nét biên làm tim.
                    // Ghép từng cặp line song song có khoảng cách ~= Ø ngoài,
                    // rồi tạo TIM ẢO đúng chính giữa hai nét.
                    List<ManualPipeAxisCandidate> realCenters =
                        current
                            .Where(x =>
                                x != null &&
                                x.IsShopCenterline)
                            .ToList();

                    List<ManualPipeAxisCandidate> rawEdges =
                        current
                            .Where(x =>
                                x != null &&
                                !x.IsShopCenterline)
                            .ToList();

                    List<ManualPipeAxisCandidate> virtualCenters =
                        BuildManualVirtualCenterAxesFromDoubleLines(
                            rawEdges,
                            expectedOutsideDiameter,
                            pick,
                            tol);

                    List<ManualPipeAxisCandidate> combinedCenters =
                        new List<ManualPipeAxisCandidate>();

                    combinedCenters.AddRange(
                        realCenters);

                    combinedCenters.AddRange(
                        virtualCenters);

                    DeduplicateManualAxisCandidates(
                        combinedCenters,
                        Math.Max(
                            4.0,
                            expectedOutsideDiameter * 0.04));

                    // Chỉ trả về TIM THẬT / TIM ẢO.
                    // Không bao giờ trả trực tiếp các nét biên SHOP.
                    if (combinedCenters.Count >= 2)
                        return combinedCenters;

                    if (combinedCenters.Count > best.Count)
                        best = combinedCenters;
                }
            }

            return best;
        }

        private List<ManualPipeAxisCandidate>
            BuildManualVirtualCenterAxesFromDoubleLines(
                List<ManualPipeAxisCandidate> edgeAxes,
                double expectedOutsideDiameter,
                Point3d pick,
                double searchTolerance)
        {
            List<ManualPipeAxisCandidate> result =
                new List<ManualPipeAxisCandidate>();

            if (edgeAxes == null ||
                edgeAxes.Count < 2 ||
                expectedOutsideDiameter <= 0.0)
            {
                return result;
            }

            // Cho phép đọc cả SHOP cũ từng vẽ sai theo DN:
            // ví dụ DN80 cũ cách 80 nhưng đúng phải 88.90.
            // Tolerance 20% giúp nhận lại tâm, còn SHOP mới vẫn ưu tiên rất tốt.
            double separationTolerance =
                Math.Max(
                    5.0,
                    expectedOutsideDiameter * 0.20);

            double maxCenterDistance =
                Math.Max(
                    searchTolerance * 1.35,
                    expectedOutsideDiameter * 1.8);

            for (int i = 0;
                i < edgeAxes.Count;
                i++)
            {
                ManualPipeAxisCandidate a =
                    edgeAxes[i];

                if (a == null ||
                    a.Direction.Length < 1e-9)
                {
                    continue;
                }

                for (int j = i + 1;
                    j < edgeAxes.Count;
                    j++)
                {
                    ManualPipeAxisCandidate b =
                        edgeAxes[j];

                    if (b == null ||
                        b.Direction.Length < 1e-9)
                    {
                        continue;
                    }

                    double angle =
                        GetShopAngleDegrees(
                            a.Direction,
                            b.Direction);

                    double axisAngle =
                        Math.Min(
                            angle,
                            Math.Abs(
                                180.0 -
                                angle));

                    if (axisAngle > 5.0)
                        continue;

                    Vector3d dir =
                        new Vector3d(
                            a.Direction.X,
                            a.Direction.Y,
                            0.0);

                    if (dir.Length < 1e-9)
                        continue;

                    dir =
                        dir.GetNormal();

                    // Khoảng cách vuông góc giữa 2 đường song song.
                    Point3d bOnA =
                        GetClosestPointOnManualInfiniteLine(
                            b.A,
                            a.A,
                            dir);

                    double separation =
                        PlanDistance(
                            b.A,
                            bOnA);

                    if (Math.Abs(
                            separation -
                            expectedOutsideDiameter) >
                        separationTolerance)
                    {
                        continue;
                    }

                    // Điểm nằm chính giữa 2 nét biên.
                    Point3d centerBase =
                        MidPoint(
                            b.A,
                            bOnA);

                    Point3d centerClosest =
                        GetClosestPointOnManualInfiniteLine(
                            pick,
                            centerBase,
                            dir);

                    double distanceToPick =
                        PlanDistance(
                            pick,
                            centerClosest);

                    if (distanceToPick >
                        maxCenterDistance)
                    {
                        continue;
                    }

                    // FIX40G:
                    // Tạo TIM ẢO nhưng GIỮ PHẠM VI THẬT của hai nét biên.
                    // Nhờ vậy khi tới góc Co/Tê, code biết ống nằm về phía nào
                    // của giao điểm thay vì coi tim ảo kéo dài vô hạn hai phía.
                    double a1 =
                        a.A.GetAsVector()
                            .DotProduct(dir);

                    double a2 =
                        a.B.GetAsVector()
                            .DotProduct(dir);

                    double b1 =
                        b.A.GetAsVector()
                            .DotProduct(dir);

                    double b2 =
                        b.B.GetAsVector()
                            .DotProduct(dir);

                    double minA =
                        Math.Min(a1, a2);

                    double maxA =
                        Math.Max(a1, a2);

                    double minB =
                        Math.Min(b1, b2);

                    double maxB =
                        Math.Max(b1, b2);

                    double minT =
                        Math.Max(
                            minA,
                            minB);

                    double maxT =
                        Math.Min(
                            maxA,
                            maxB);

                    // Nếu hai nét không overlap hoàn toàn do đã chừa fitting,
                    // dùng vùng bao của cả hai nhưng vẫn giữ extents hữu hạn.
                    if (maxT - minT < 1.0)
                    {
                        minT =
                            Math.Min(
                                minA,
                                minB);

                        maxT =
                            Math.Max(
                                maxA,
                                maxB);
                    }

                    double baseT =
                        centerBase
                            .GetAsVector()
                            .DotProduct(dir);

                    Point3d va =
                        centerBase +
                        dir *
                        (minT - baseT);

                    Point3d vb =
                        centerBase +
                        dir *
                        (maxT - baseT);

                    string layerLabel =
                        "VIRTUAL_CENTER[" +
                        (string.IsNullOrWhiteSpace(a.Layer)
                            ? "PIPE"
                            : a.Layer) +
                        "]";

                    result.Add(
                        new ManualPipeAxisCandidate
                        {
                            A = va,
                            B = vb,
                            Direction = dir,
                            Layer = layerLabel,
                            IsShopCenterline = true,
                            DistanceToPick = distanceToPick
                        });
                }
            }

            DeduplicateManualAxisCandidates(
                result,
                Math.Max(
                    3.0,
                    expectedOutsideDiameter * 0.035));

            return result;
        }


        private void AddManualAxisCandidate(
            List<ManualPipeAxisCandidate> list,
            Point3d a,
            Point3d b,
            string layer,
            bool isCenterline,
            Point3d pick,
            double tolerance)
        {
            if (list == null)
                return;

            Vector3d v =
                b - a;

            v =
                new Vector3d(
                    v.X,
                    v.Y,
                    0.0);

            if (v.Length < 1e-6)
                return;

            Point3d closest =
                GetClosestPointOnManualSegment(
                    pick,
                    a,
                    b,
                    out double _);

            double distance =
                PlanDistance(
                    pick,
                    closest);

            if (distance > tolerance)
                return;

            list.Add(
                new ManualPipeAxisCandidate
                {
                    A = a,
                    B = b,
                    Direction = v.GetNormal(),
                    Layer = layer ?? "",
                    IsShopCenterline = isCenterline,
                    DistanceToPick = distance
                });
        }

        private void AddManualAxisCandidatesFromPolyline(
            List<ManualPipeAxisCandidate> list,
            Polyline pl,
            string layer,
            bool isCenterline,
            Point3d pick,
            double tolerance)
        {
            if (list == null ||
                pl == null ||
                pl.NumberOfVertices < 2)
            {
                return;
            }

            int segmentCount =
                pl.Closed
                    ? pl.NumberOfVertices
                    : pl.NumberOfVertices - 1;

            for (int i = 0;
                i < segmentCount;
                i++)
            {
                try
                {
                    int next =
                        (i + 1) %
                        pl.NumberOfVertices;

                    // Chỉ dùng segment thẳng.
                    if (Math.Abs(
                            pl.GetBulgeAt(i)) >
                        1e-9)
                    {
                        continue;
                    }

                    Point3d a =
                        pl.GetPoint3dAt(i);

                    Point3d b =
                        pl.GetPoint3dAt(next);

                    AddManualAxisCandidate(
                        list,
                        a,
                        b,
                        layer,
                        isCenterline,
                        pick,
                        tolerance);
                }
                catch
                {
                }
            }
        }

        private static void DeduplicateManualAxisCandidates(
            List<ManualPipeAxisCandidate> axes,
            double locationTolerance)
        {
            if (axes == null ||
                axes.Count <= 1)
            {
                return;
            }

            List<ManualPipeAxisCandidate> unique =
                new List<ManualPipeAxisCandidate>();

            foreach (ManualPipeAxisCandidate axis
                in axes
                    .OrderByDescending(x =>
                        x.IsShopCenterline)
                    .ThenBy(x =>
                        x.DistanceToPick))
            {
                if (axis == null ||
                    axis.Direction.Length < 1e-9)
                {
                    continue;
                }

                Point3d mid =
                    MidPoint(
                        axis.A,
                        axis.B);

                bool duplicate =
                    unique.Any(old =>
                    {
                        double angle =
                            GetShopAngleDegrees(
                                old.Direction,
                                axis.Direction);

                        // Trục không phân biệt chiều:
                        angle =
                            Math.Min(
                                angle,
                                Math.Abs(
                                    180.0 -
                                    angle));

                        if (angle > 5.0)
                            return false;

                        Point3d oldClosest =
                            GetClosestPointOnManualInfiniteLine(
                                mid,
                                old.A,
                                old.Direction);

                        return PlanDistance(
                                   mid,
                                   oldClosest) <=
                               locationTolerance;
                    });

                if (!duplicate)
                    unique.Add(axis);
            }

            axes.Clear();
            axes.AddRange(unique);
        }

        private static Point3d GetClosestPointOnManualInfiniteLine(
            Point3d point,
            Point3d linePoint,
            Vector3d direction)
        {
            Vector3d d =
                new Vector3d(
                    direction.X,
                    direction.Y,
                    0.0);

            if (d.Length < 1e-9)
                return linePoint;

            d =
                d.GetNormal();

            Vector3d v =
                point -
                linePoint;

            double t =
                v.DotProduct(d);

            return linePoint +
                d * t;
        }

        private bool TryFindBestManualAxisIntersection(
            List<ManualPipeAxisCandidate> axes,
            Point3d pick,
            double targetAxisAngle,
            double angleTolerance,
            double maxSnapDistance,
            out Point3d joint,
            out double actualAngle,
            out string info)
        {
            joint = pick;
            actualAngle = 0.0;
            info = "";

            if (axes == null ||
                axes.Count < 2)
            {
                return false;
            }

            double bestScore =
                double.MaxValue;

            ManualPipeAxisCandidate bestA =
                null;

            ManualPipeAxisCandidate bestB =
                null;

            for (int i = 0;
                i < axes.Count;
                i++)
            {
                ManualPipeAxisCandidate a =
                    axes[i];

                if (a == null ||
                    a.Direction.Length < 1e-9)
                {
                    continue;
                }

                for (int j = i + 1;
                    j < axes.Count;
                    j++)
                {
                    ManualPipeAxisCandidate b =
                        axes[j];

                    if (b == null ||
                        b.Direction.Length < 1e-9)
                    {
                        continue;
                    }

                    double angle =
                        GetShopAngleDegrees(
                            a.Direction,
                            b.Direction);

                    // Góc giữa hai TRỤC, không phân biệt chiều.
                    angle =
                        Math.Min(
                            angle,
                            Math.Abs(
                                180.0 -
                                angle));

                    double angleError =
                        Math.Abs(
                            angle -
                            targetAxisAngle);

                    if (angleError >
                        angleTolerance)
                    {
                        continue;
                    }

                    if (!TryIntersectShopAxes(
                            a.A,
                            a.Direction,
                            b.A,
                            b.Direction,
                            out Point3d p))
                    {
                        continue;
                    }

                    double snapDistance =
                        PlanDistance(
                            pick,
                            p);

                    if (snapDistance >
                        maxSnapDistance)
                    {
                        continue;
                    }

                    // Ưu tiên centerline thật.
                    double centerBonus =
                        (a.IsShopCenterline ? 60.0 : 0.0) +
                        (b.IsShopCenterline ? 60.0 : 0.0);

                    double score =
                        angleError * 12.0 +
                        snapDistance +
                        a.DistanceToPick * 0.25 +
                        b.DistanceToPick * 0.25 -
                        centerBonus;

                    if (score < bestScore)
                    {
                        bestScore = score;
                        joint = p;
                        actualAngle = angle;
                        bestA = a;
                        bestB = b;
                    }
                }
            }

            if (bestA == null ||
                bestB == null)
            {
                return false;
            }

            info =
                $"{bestA.Layer} + {bestB.Layer}";

            return true;
        }


        private ShopFittingPlacementInfo AnalyzeManualWeldElbowTruePorts(
            ObjectId blockId,
            string fittingType,
            string fromSize,
            string toSize,
            double outsideDiameter)
        {
            if (blockId.IsNull ||
                outsideDiameter <= 0.0)
            {
                return null;
            }

            string key =
                NormalizeShopKey(
                    fittingType ?? "");

            ShopFittingPlacementInfo placement =
                null;

            // --------------------------------------------------------
            // WELD CO 90:
            // Hai cổng thật là hai MẶT NỐI NGOÀI cùng nằm ở biên block.
            // BuildShopFittingBoundaryPortsForLargeWeld đọc tâm của chính
            // các mặt này, vì vậy Anchor = giao hai centerline cổng thật.
            // --------------------------------------------------------
            if (IsElbow90Key(key))
            {
                List<ShopFittingPortInfo> truePorts =
                    BuildShopFittingBoundaryPortsForLargeWeld(
                        blockId,
                        outsideDiameter);

                placement =
                    AnalyzeShopElbowPorts(
                        truePorts,
                        90.0,
                        outsideDiameter);

                if (placement != null)
                {
                    WriteManualWeldPortDiagnostic(
                        "ELB90",
                        fromSize,
                        outsideDiameter,
                        placement);

                    return placement;
                }
            }

            // --------------------------------------------------------
            // WELD LƠI / CO 45:
            // Một mặt nối có thể nghiêng 45°, vì vậy dùng bộ đọc mặt nghiêng.
            // Bộ này lấy midpoint của đoạn mặt nối và normal hướng ra ngoài.
            // --------------------------------------------------------
            if (IsElbow45Key(key))
            {
                List<ShopFittingPortInfo> truePorts =
                    BuildShopElbow45ObliquePorts(
                        blockId,
                        outsideDiameter);

                placement =
                    AnalyzeShopElbowPorts(
                        truePorts,
                        135.0,
                        outsideDiameter);

                if (placement != null)
                {
                    WriteManualWeldPortDiagnostic(
                        "ELB45",
                        fromSize,
                        outsideDiameter,
                        placement);

                    return placement;
                }

                // Fallback cuối: nếu block ELB45 WELD có 2 mặt nằm trên
                // biên X/Y như một số size, thử boundary ports.
                truePorts =
                    BuildShopFittingBoundaryPortsForLargeWeld(
                        blockId,
                        outsideDiameter);

                placement =
                    AnalyzeShopElbowPorts(
                        truePorts,
                        135.0,
                        outsideDiameter);

                if (placement != null)
                {
                    WriteManualWeldPortDiagnostic(
                        "ELB45-BOUNDARY",
                        fromSize,
                        outsideDiameter,
                        placement);

                    return placement;
                }
            }

            return null;
        }

        private void WriteManualWeldPortDiagnostic(
            string kind,
            string size,
            double outsideDiameter,
            ShopFittingPlacementInfo placement)
        {
            if (placement == null)
                return;

            try
            {
                string ports =
                    string.Join(
                        " ; ",
                        placement.Ports
                            .Select((p, i) =>
                                $"P{i + 1}=({p.Center.X:0.##}," +
                                $"{p.Center.Y:0.##})"));

                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument?
                    .Editor
                    .WriteMessage(
                        $"\n[ĐẶT TB FIX40H] WELD TRUE PORTS " +
                        $"{kind} {size} | Ø={outsideDiameter:0.##} | " +
                        $"Anchor=({placement.Anchor.X:0.##}," +
                        $"{placement.Anchor.Y:0.##}) | {ports}");
            }
            catch
            {
            }
        }


        private bool TryResolveManualFittingTransformByPortCenterlines(
            Transaction tr,
            Database db,
            Point3d pick,
            string fittingType,
            string fromSize,
            string toSize,
            double expectedOutsideDiameter,
            ShopFittingPlacementInfo placement,
            out Point3d targetPoint,
            out double rotation,
            out string info)
        {
            targetPoint = pick;
            rotation = 0.0;
            info = "";

            if (tr == null ||
                db == null ||
                placement == null ||
                placement.Ports == null ||
                placement.Ports.Count < 2)
            {
                return false;
            }

            string key =
                NormalizeShopKey(
                    fittingType ?? "");

            List<ManualPipeAxisCandidate> axes =
                FindManualPipeAxesNearPoint(
                    tr,
                    db,
                    pick,
                    fromSize,
                    toSize,
                    expectedOutsideDiameter);

            if (axes == null ||
                axes.Count < 2)
            {
                info = "không đủ tim ống";
                return false;
            }

            double maxSnap =
                Math.Max(
                    180.0,
                    Math.Min(
                        750.0,
                        expectedOutsideDiameter * 3.8 + 140.0));

            // ========================================================
            // CO 90 / LƠI 45:
            // - tìm đúng 2 trục ống
            // - lấy ray ống thực đi ra khỏi joint
            // - match với Anchor->Port.Center của block
            // ========================================================
            if (IsElbow90Key(key) ||
                IsElbow45Key(key))
            {
                double targetAxisAngle =
                    IsElbow90Key(key)
                        ? 90.0
                        : 45.0;

                double axisTol =
                    IsElbow90Key(key)
                        ? 22.0
                        : 25.0;

                double bestScore =
                    double.MaxValue;

                Point3d bestJoint =
                    pick;

                double bestRotation =
                    0.0;

                string bestInfo =
                    "";

                for (int i = 0;
                    i < axes.Count;
                    i++)
                {
                    ManualPipeAxisCandidate ax1 =
                        axes[i];

                    if (ax1 == null ||
                        ax1.Direction.Length < 1e-9)
                    {
                        continue;
                    }

                    for (int j = i + 1;
                        j < axes.Count;
                        j++)
                    {
                        ManualPipeAxisCandidate ax2 =
                            axes[j];

                        if (ax2 == null ||
                            ax2.Direction.Length < 1e-9)
                        {
                            continue;
                        }

                        double axisAngle =
                            GetManualUndirectedAxisAngle(
                                ax1.Direction,
                                ax2.Direction);

                        double axisError =
                            Math.Abs(
                                axisAngle -
                                targetAxisAngle);

                        if (axisError >
                            axisTol)
                        {
                            continue;
                        }

                        if (!TryIntersectShopAxes(
                                ax1.A,
                                ax1.Direction,
                                ax2.A,
                                ax2.Direction,
                                out Point3d joint))
                        {
                            continue;
                        }

                        double snapDistance =
                            PlanDistance(
                                pick,
                                joint);

                        if (snapDistance >
                            maxSnap)
                        {
                            continue;
                        }

                        List<Vector3d> arms1 =
                            GetManualAxisArmDirectionsAtJoint(
                                ax1,
                                joint,
                                expectedOutsideDiameter);

                        List<Vector3d> arms2 =
                            GetManualAxisArmDirectionsAtJoint(
                                ax2,
                                joint,
                                expectedOutsideDiameter);

                        if (arms1.Count == 0 ||
                            arms2.Count == 0)
                        {
                            continue;
                        }

                        foreach (Vector3d arm1
                            in arms1)
                        {
                            foreach (Vector3d arm2
                                in arms2)
                            {
                                double armAngle =
                                    GetShopAngleDegrees(
                                        arm1,
                                        arm2);

                                double expectedArmAngle =
                                    IsElbow45Key(key)
                                        ? 135.0
                                        : 90.0;

                                double armError =
                                    Math.Abs(
                                        armAngle -
                                        expectedArmAngle);

                                // Co45 có thể biểu diễn bằng 45/135 tùy chiều
                                // segment, nhưng đường tâm cổng block sẽ quyết định
                                // cặp nào đúng. Vẫn ưu tiên 135° như topology SHOP.
                                if (IsElbow45Key(key) &&
                                    armError > 30.0)
                                {
                                    double alternate =
                                        Math.Abs(
                                            armAngle -
                                            45.0);

                                    armError =
                                        Math.Min(
                                            armError,
                                            alternate + 8.0);
                                }

                                if (armError > 35.0)
                                    continue;

                                if (!TryMatchShopPortCenterlinesToDirections(
                                        placement,
                                        new List<Vector3d>
                                        {
                                            arm1,
                                            arm2
                                        },
                                        null,
                                        out double candidateRotation,
                                        out double portScore))
                                {
                                    continue;
                                }

                                double throughPenalty =
                                    (arms1.Count > 1 ? 12.0 : 0.0) +
                                    (arms2.Count > 1 ? 12.0 : 0.0);

                                double score =
                                    portScore * 12.0 +
                                    axisError * 5.0 +
                                    armError * 2.0 +
                                    snapDistance * 0.12 +
                                    throughPenalty;

                                if (score < bestScore)
                                {
                                    bestScore = score;
                                    bestJoint = joint;
                                    bestRotation =
                                        candidateRotation;

                                    bestInfo =
                                        $"PORT-CL: " +
                                        $"{ax1.Layer} + {ax2.Layer} | " +
                                        $"pipe={FormatManualDirection(arm1)}/" +
                                        $"{FormatManualDirection(arm2)} | " +
                                        $"fit-score={portScore:0.##}";
                                }
                            }
                        }
                    }
                }

                if (bestScore <
                    double.MaxValue)
                {
                    targetPoint =
                        bestJoint;

                    rotation =
                        bestRotation;

                    info =
                        bestInfo;

                    return true;
                }

                info =
                    "không match được 2 centerline cổng Co với 2 tim ống";

                return false;
            }

            // ========================================================
            // TÊ ĐỀU / TÊ GIẢM:
            // tại mỗi giao hai trục ~90°, gom toàn bộ ray ống thật tại joint,
            // sau đó match main/main/branch với 3 centerline cổng block.
            // ========================================================
            if (IsTeeKey(key))
            {
                if (placement.Ports.Count < 3)
                {
                    info = "block Tê không đủ 3 port";
                    return false;
                }

                double bestScore =
                    double.MaxValue;

                Point3d bestJoint =
                    pick;

                double bestRotation =
                    0.0;

                string bestInfo =
                    "";

                for (int i = 0;
                    i < axes.Count;
                    i++)
                {
                    for (int j = i + 1;
                        j < axes.Count;
                        j++)
                    {
                        ManualPipeAxisCandidate ax1 =
                            axes[i];

                        ManualPipeAxisCandidate ax2 =
                            axes[j];

                        if (ax1 == null ||
                            ax2 == null)
                        {
                            continue;
                        }

                        double axisAngle =
                            GetManualUndirectedAxisAngle(
                                ax1.Direction,
                                ax2.Direction);

                        double axisError =
                            Math.Abs(
                                axisAngle -
                                90.0);

                        if (axisError > 25.0)
                            continue;

                        if (!TryIntersectShopAxes(
                                ax1.A,
                                ax1.Direction,
                                ax2.A,
                                ax2.Direction,
                                out Point3d joint))
                        {
                            continue;
                        }

                        double snapDistance =
                            PlanDistance(
                                pick,
                                joint);

                        if (snapDistance >
                            maxSnap)
                        {
                            continue;
                        }

                        List<Vector3d> allArms =
                            CollectManualPipeArmsAtJoint(
                                axes,
                                joint,
                                expectedOutsideDiameter);

                        if (!TryPickManualTeeArms(
                                allArms,
                                out Vector3d main1,
                                out Vector3d main2,
                                out Vector3d branch,
                                out double teeTopologyScore))
                        {
                            continue;
                        }

                        List<List<int>> permutations =
                            new List<List<int>>
                            {
                                new List<int> { 0, 1, 2 },
                                new List<int> { 1, 0, 2 }
                            };

                        if (!TryMatchShopPortCenterlinesToDirections(
                                placement,
                                new List<Vector3d>
                                {
                                    main1,
                                    main2,
                                    branch
                                },
                                permutations,
                                out double candidateRotation,
                                out double portScore))
                        {
                            continue;
                        }

                        double score =
                            portScore * 12.0 +
                            teeTopologyScore * 3.0 +
                            axisError * 5.0 +
                            snapDistance * 0.12;

                        if (score < bestScore)
                        {
                            bestScore = score;
                            bestJoint = joint;
                            bestRotation =
                                candidateRotation;

                            bestInfo =
                                $"PORT-CL TEE: main=" +
                                $"{FormatManualDirection(main1)}/" +
                                $"{FormatManualDirection(main2)} | " +
                                $"branch={FormatManualDirection(branch)} | " +
                                $"fit-score={portScore:0.##}";
                        }
                    }
                }

                if (bestScore <
                    double.MaxValue)
                {
                    targetPoint =
                        bestJoint;

                    rotation =
                        bestRotation;

                    info =
                        bestInfo;

                    return true;
                }

                info =
                    "không match được 3 centerline cổng Tê với tim ống";

                return false;
            }

            return false;
        }

        private static double GetManualUndirectedAxisAngle(
            Vector3d a,
            Vector3d b)
        {
            double angle =
                GetShopAngleDegrees(
                    a,
                    b);

            return Math.Min(
                angle,
                Math.Abs(
                    180.0 -
                    angle));
        }

        private List<Vector3d> GetManualAxisArmDirectionsAtJoint(
            ManualPipeAxisCandidate axis,
            Point3d joint,
            double expectedOutsideDiameter)
        {
            List<Vector3d> result =
                new List<Vector3d>();

            if (axis == null)
                return result;

            Vector3d ab =
                axis.B -
                axis.A;

            ab =
                new Vector3d(
                    ab.X,
                    ab.Y,
                    0.0);

            if (ab.Length < 1e-9)
                return result;

            double length =
                ab.Length;

            Vector3d dir =
                ab.GetNormal();

            double along =
                (joint - axis.A)
                    .DotProduct(dir);

            double extensionTol =
                Math.Max(
                    80.0,
                    expectedOutsideDiameter * 3.0);

            // Joint quá xa ngoài phạm vi segment => không phải ray của nút này.
            if (along < -extensionTol ||
                along > length + extensionTol)
            {
                return result;
            }

            double endTol =
                Math.Max(
                    35.0,
                    expectedOutsideDiameter * 1.15);

            // Joint ở trước/đầu A -> ống đi từ joint về phía B.
            if (along <= endTol)
            {
                AddManualArmDirection(
                    result,
                    dir);
            }
            // Joint ở gần/sau đầu B -> ống đi về phía A.
            else if (along >=
                     length - endTol)
            {
                AddManualArmDirection(
                    result,
                    -dir);
            }
            else
            {
                // Joint nằm giữa segment: đây là tuyến xuyên qua nút.
                AddManualArmDirection(
                    result,
                    dir);

                AddManualArmDirection(
                    result,
                    -dir);
            }

            DeduplicateManualArmDirections(
                result,
                5.0);

            return result;
        }

        private List<Vector3d> CollectManualPipeArmsAtJoint(
            List<ManualPipeAxisCandidate> axes,
            Point3d joint,
            double expectedOutsideDiameter)
        {
            List<Vector3d> result =
                new List<Vector3d>();

            if (axes == null)
                return result;

            double lineTol =
                Math.Max(
                    8.0,
                    expectedOutsideDiameter * 0.10);

            foreach (ManualPipeAxisCandidate axis
                in axes)
            {
                if (axis == null ||
                    axis.Direction.Length < 1e-9)
                {
                    continue;
                }

                Point3d onAxis =
                    GetClosestPointOnManualInfiniteLine(
                        joint,
                        axis.A,
                        axis.Direction);

                if (PlanDistance(
                        joint,
                        onAxis) >
                    lineTol)
                {
                    continue;
                }

                List<Vector3d> arms =
                    GetManualAxisArmDirectionsAtJoint(
                        axis,
                        joint,
                        expectedOutsideDiameter);

                foreach (Vector3d arm in arms)
                    AddManualArmDirection(result, arm);
            }

            DeduplicateManualArmDirections(
                result,
                8.0);

            return result;
        }

        private bool TryMatchShopPortCenterlinesToDirections(
            ShopFittingPlacementInfo placement,
            List<Vector3d> desiredDirections,
            List<List<int>> explicitPermutations,
            out double bestRotation,
            out double bestScore)
        {
            bestRotation = 0.0;
            bestScore = double.MaxValue;

            if (placement == null ||
                placement.Ports == null ||
                desiredDirections == null ||
                placement.Ports.Count < desiredDirections.Count ||
                desiredDirections.Count == 0)
            {
                return false;
            }

            int count =
                desiredDirections.Count;

            List<Vector3d> localCenterlines =
                new List<Vector3d>();

            for (int i = 0;
                i < count;
                i++)
            {
                ShopFittingPortInfo port =
                    placement.Ports[i];

                Vector3d local =
                    port.Center -
                    placement.Anchor;

                local =
                    new Vector3d(
                        local.X,
                        local.Y,
                        0.0);

                // Nếu tâm cổng gần trùng anchor do block đặc biệt,
                // mới fallback về outward direction.
                if (local.Length < 1e-6)
                {
                    local =
                        new Vector3d(
                            port.OutwardDirection.X,
                            port.OutwardDirection.Y,
                            0.0);
                }

                if (local.Length < 1e-9)
                    return false;

                localCenterlines.Add(
                    local.GetNormal());
            }

            List<List<int>> permutations =
                explicitPermutations ??
                BuildShopIndexPermutations(count);

            foreach (List<int> perm
                in permutations)
            {
                if (perm == null ||
                    perm.Count != count)
                {
                    continue;
                }

                Vector3d local0 =
                    localCenterlines[
                        perm[0]];

                Vector3d desired0 =
                    desiredDirections[0];

                desired0 =
                    new Vector3d(
                        desired0.X,
                        desired0.Y,
                        0.0);

                if (desired0.Length < 1e-9)
                    continue;

                desired0 =
                    desired0.GetNormal();

                double candidateRotation =
                    Math.Atan2(
                        desired0.Y,
                        desired0.X) -
                    Math.Atan2(
                        local0.Y,
                        local0.X);

                double score = 0.0;

                for (int i = 0;
                    i < count;
                    i++)
                {
                    Vector3d local =
                        localCenterlines[
                            perm[i]]
                            .RotateBy(
                                candidateRotation,
                                Vector3d.ZAxis);

                    Vector3d desired =
                        desiredDirections[i];

                    desired =
                        new Vector3d(
                            desired.X,
                            desired.Y,
                            0.0);

                    if (desired.Length < 1e-9)
                    {
                        score =
                            double.MaxValue;
                        break;
                    }

                    desired =
                        desired.GetNormal();

                    score +=
                        GetShopAngleDegrees(
                            local,
                            desired);
                }

                if (score < bestScore)
                {
                    bestScore =
                        score;

                    bestRotation =
                        candidateRotation;
                }
            }

            // Vì đây là centerline-to-centerline matching nên yêu cầu chặt hơn.
            double maxScore =
                count * 14.0;

            return bestScore <=
                maxScore;
        }


        private bool TryResolveManualFittingRotationFromNearbyPipes(
            Transaction tr,
            Database db,
            Point3d insertPoint,
            string fittingType,
            string fromSize,
            string toSize,
            ShopFittingPlacementInfo placement,
            out double rotation,
            out string info)
        {
            rotation = 0.0;
            info = "";

            if (tr == null ||
                db == null ||
                placement == null ||
                placement.Ports.Count == 0)
            {
                return false;
            }

            string key =
                NormalizeShopKey(
                    fittingType ?? "");

            double dn1 =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        fromSize));

            double dn2 =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        toSize));

            double refDn =
                Math.Max(
                    dn1,
                    dn2);

            if (refDn <= 0.0)
                refDn = 25.0;

            List<Vector3d> arms =
                FindManualPipeArmsNearPoint(
                    tr,
                    db,
                    insertPoint,
                    fromSize,
                    toSize,
                    refDn);

            if (arms == null ||
                arms.Count == 0)
            {
                info = "không thấy ống gần điểm click";
                return false;
            }

            // --------------------------------------------------------
            // CO 90
            // --------------------------------------------------------
            if (IsElbow90Key(key))
            {
                if (!TryPickManualElbowArms(
                        arms,
                        90.0,
                        out Vector3d a,
                        out Vector3d b,
                        out double angle))
                {
                    info =
                        $"không tìm được 2 hướng ~90°; arms={arms.Count}";
                    return false;
                }

                if (!TryMatchShopPortsToDirections(
                        placement.Ports
                            .Take(2)
                            .ToList(),
                        new List<Vector3d>
                        {
                            a,
                            b
                        },
                        false,
                        out rotation,
                        out double _))
                {
                    info = "block port không match Co90";
                    return false;
                }

                info =
                    $"2 ống={FormatManualDirection(a)} + " +
                    $"{FormatManualDirection(b)} | góc={angle:0.##}°";

                return true;
            }

            // --------------------------------------------------------
            // LƠI / CO 45
            // Outward arms ở joint tạo góc khoảng 135°.
            // --------------------------------------------------------
            if (IsElbow45Key(key))
            {
                if (!TryPickManualElbowArms(
                        arms,
                        135.0,
                        out Vector3d a,
                        out Vector3d b,
                        out double angle))
                {
                    info =
                        $"không tìm được 2 hướng ~135°; arms={arms.Count}";
                    return false;
                }

                if (!TryMatchShopPortsToDirections(
                        placement.Ports
                            .Take(2)
                            .ToList(),
                        new List<Vector3d>
                        {
                            a,
                            b
                        },
                        false,
                        out rotation,
                        out double _))
                {
                    info = "block port không match Lơi45";
                    return false;
                }

                info =
                    $"2 ống={FormatManualDirection(a)} + " +
                    $"{FormatManualDirection(b)} | góc={angle:0.##}°";

                return true;
            }

            // --------------------------------------------------------
            // TÊ ĐỀU / TÊ GIẢM
            // --------------------------------------------------------
            if (IsTeeKey(key))
            {
                if (placement.Ports.Count < 3)
                {
                    info = "block Tê không đủ 3 port";
                    return false;
                }

                if (!TryPickManualTeeArms(
                        arms,
                        out Vector3d main1,
                        out Vector3d main2,
                        out Vector3d branch,
                        out double teeScore))
                {
                    info =
                        $"không nhận đủ topology Tê; arms={arms.Count}";
                    return false;
                }

                // AnalyzeShopTeePorts đã cố định:
                // port 0/1 = main, port 2 = branch.
                List<List<int>> permutations =
                    new List<List<int>>
                    {
                        new List<int> { 0, 1, 2 },
                        new List<int> { 1, 0, 2 }
                    };

                if (!TryMatchShopPortsToDirections(
                        placement.Ports
                            .Take(3)
                            .ToList(),
                        new List<Vector3d>
                        {
                            main1,
                            main2,
                            branch
                        },
                        false,
                        out rotation,
                        out double _,
                        permutations))
                {
                    info = "block port không match topology Tê";
                    return false;
                }

                info =
                    $"main={FormatManualDirection(main1)}/" +
                    $"{FormatManualDirection(main2)} | " +
                    $"branch={FormatManualDirection(branch)} | " +
                    $"score={teeScore:0.##}";

                return true;
            }

            return false;
        }

        private List<Vector3d> FindManualPipeArmsNearPoint(
            Transaction tr,
            Database db,
            Point3d pick,
            string fromSize,
            string toSize,
            double refDn)
        {
            List<Vector3d> result =
                new List<Vector3d>();

            if (tr == null ||
                db == null)
            {
                return result;
            }

            BlockTableRecord btr =
                tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForRead,
                    false) as BlockTableRecord;

            if (btr == null)
                return result;

            double tightTol =
                Math.Max(
                    20.0,
                    Math.Min(
                        120.0,
                        refDn * 0.55 + 12.0));

            double fallbackTol =
                Math.Max(
                    45.0,
                    Math.Min(
                        220.0,
                        refDn * 1.10 + 30.0));

            // 4 pass:
            // 0 = centerline đúng DN
            // 1 = pipe đúng DN
            // 2 = centerline bất kỳ
            // 3 = pipe bất kỳ
            for (int pass = 0;
                pass < 4;
                pass++)
            {
                List<Vector3d> passArms =
                    new List<Vector3d>();

                bool centerOnly =
                    pass == 0 ||
                    pass == 2;

                bool sizeMatchOnly =
                    pass == 0 ||
                    pass == 1;

                double tol =
                    centerOnly
                        ? tightTol
                        : fallbackTol;

                foreach (ObjectId id in btr)
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased)
                    {
                        continue;
                    }

                    string layer =
                        (ent.Layer ?? "")
                            .Trim();

                    if (!IsManualPipeCandidateLayer(
                            layer,
                            centerOnly))
                    {
                        continue;
                    }

                    if (sizeMatchOnly &&
                        !ManualPipeLayerMatchesAnySize(
                            layer,
                            fromSize,
                            toSize))
                    {
                        continue;
                    }

                    if (ent is Line ln)
                    {
                        AddManualArmsFromLine(
                            passArms,
                            ln.StartPoint,
                            ln.EndPoint,
                            pick,
                            tol);
                    }
                    else if (ent is Polyline pl)
                    {
                        AddManualArmsFromPolyline(
                            passArms,
                            pl,
                            pick,
                            tol);
                    }
                    else if (ent is Arc arc)
                    {
                        AddManualArmsFromArc(
                            passArms,
                            arc,
                            pick,
                            tol);
                    }
                }

                DeduplicateManualArmDirections(
                    passArms,
                    10.0);

                if (passArms.Count >= 2)
                {
                    return passArms;
                }

                // Nếu pass tìm được 1 hướng, giữ làm fallback,
                // nhưng vẫn thử pass rộng hơn để tìm đủ hướng.
                if (passArms.Count > result.Count)
                {
                    result =
                        passArms;
                }
            }

            return result;
        }

        private bool IsManualPipeCandidateLayer(
            string layerName,
            bool centerOnly)
        {
            if (string.IsNullOrWhiteSpace(layerName))
                return false;

            string u =
                layerName
                    .Trim()
                    .ToUpperInvariant();

            if (centerOnly)
            {
                return u.StartsWith(
                    "FF_SHOP_TAM_",
                    StringComparison.OrdinalIgnoreCase);
            }

            if (u.StartsWith("FF_SHOP_CO90_") ||
                u.StartsWith("FF_SHOP_COLOI45_") ||
                u.StartsWith("FF_SHOP_TE_") ||
                u.StartsWith("FF_SHOP_GIAM_") ||
                u.StartsWith("FF_SHOP_PK_"))
            {
                return false;
            }

            if (u.StartsWith(
                    "FF_SHOP_TAM_",
                    StringComparison.OrdinalIgnoreCase) ||
                Regex.IsMatch(
                    u,
                    @"^FF_SHOP_DN\d+(?:[.,]\d+)?$",
                    RegexOptions.IgnoreCase))
            {
                return true;
            }

            try
            {
                return LaLayerOng(
                    layerName);
            }
            catch
            {
                return false;
            }
        }

        private static bool ManualPipeLayerMatchesAnySize(
            string layerName,
            string fromSize,
            string toSize)
        {
            if (string.IsNullOrWhiteSpace(layerName))
                return false;

            string u =
                layerName
                    .Trim()
                    .ToUpperInvariant();

            string a =
                NormalizeShopDnToken(
                    fromSize ?? "")
                    .ToUpperInvariant();

            string b =
                NormalizeShopDnToken(
                    toSize ?? "")
                    .ToUpperInvariant();

            bool hitA =
                !string.IsNullOrWhiteSpace(a) &&
                ShopKeyContainsSize(
                    u,
                    a);

            bool hitB =
                !string.IsNullOrWhiteSpace(b) &&
                ShopKeyContainsSize(
                    u,
                    b);

            return hitA || hitB;
        }

        private void AddManualArmsFromLine(
            List<Vector3d> arms,
            Point3d a,
            Point3d b,
            Point3d pick,
            double tolerance)
        {
            if (arms == null)
                return;

            Vector3d ab =
                b - a;

            if (ab.Length < 1e-9)
                return;

            Vector3d dir =
                new Vector3d(
                    ab.X,
                    ab.Y,
                    0.0);

            if (dir.Length < 1e-9)
                return;

            dir =
                dir.GetNormal();

            Point3d closest =
                GetClosestPointOnManualSegment(
                    pick,
                    a,
                    b,
                    out double t);

            if (PlanDistance(
                    pick,
                    closest) >
                tolerance)
            {
                return;
            }

            double endpointTol =
                Math.Max(
                    0.02,
                    Math.Min(
                        0.20,
                        tolerance /
                        Math.Max(
                            ab.Length,
                            1.0)));

            if (t <= endpointTol)
            {
                AddManualArmDirection(
                    arms,
                    dir);
            }
            else if (t >= 1.0 - endpointTol)
            {
                AddManualArmDirection(
                    arms,
                    -dir);
            }
            else
            {
                AddManualArmDirection(
                    arms,
                    dir);

                AddManualArmDirection(
                    arms,
                    -dir);
            }
        }

        private void AddManualArmsFromPolyline(
            List<Vector3d> arms,
            Polyline pl,
            Point3d pick,
            double tolerance)
        {
            if (arms == null ||
                pl == null ||
                pl.NumberOfVertices < 2)
            {
                return;
            }

            for (int i = 0;
                i < pl.NumberOfVertices - 1;
                i++)
            {
                try
                {
                    Point2d p2a =
                        pl.GetPoint2dAt(i);

                    Point2d p2b =
                        pl.GetPoint2dAt(i + 1);

                    Point3d a =
                        new Point3d(
                            p2a.X,
                            p2a.Y,
                            0.0);

                    Point3d b =
                        new Point3d(
                            p2b.X,
                            p2b.Y,
                            0.0);

                    AddManualArmsFromLine(
                        arms,
                        a,
                        b,
                        pick,
                        tolerance);
                }
                catch
                {
                }
            }

            if (pl.Closed &&
                pl.NumberOfVertices > 2)
            {
                try
                {
                    Point2d p2a =
                        pl.GetPoint2dAt(
                            pl.NumberOfVertices - 1);

                    Point2d p2b =
                        pl.GetPoint2dAt(0);

                    AddManualArmsFromLine(
                        arms,
                        new Point3d(
                            p2a.X,
                            p2a.Y,
                            0.0),
                        new Point3d(
                            p2b.X,
                            p2b.Y,
                            0.0),
                        pick,
                        tolerance);
                }
                catch
                {
                }
            }
        }

        private void AddManualArmsFromArc(
            List<Vector3d> arms,
            Arc arc,
            Point3d pick,
            double tolerance)
        {
            if (arms == null ||
                arc == null)
            {
                return;
            }

            try
            {
                Point3d closest =
                    arc.GetClosestPointTo(
                        pick,
                        false);

                if (PlanDistance(
                        pick,
                        closest) >
                    tolerance)
                {
                    return;
                }

                Vector3d radial =
                    closest -
                    arc.Center;

                radial =
                    new Vector3d(
                        radial.X,
                        radial.Y,
                        0.0);

                if (radial.Length < 1e-9)
                    return;

                Vector3d tangent =
                    new Vector3d(
                        -radial.Y,
                        radial.X,
                        0.0)
                        .GetNormal();

                // Arc gần điểm đặt được xem như tuyến đi qua điểm:
                // có hai hướng tiếp tuyến ngược nhau.
                AddManualArmDirection(
                    arms,
                    tangent);

                AddManualArmDirection(
                    arms,
                    -tangent);
            }
            catch
            {
            }
        }

        private static Point3d GetClosestPointOnManualSegment(
            Point3d p,
            Point3d a,
            Point3d b,
            out double t)
        {
            Vector3d ab =
                b - a;

            double len2 =
                ab.DotProduct(ab);

            if (len2 < 1e-12)
            {
                t = 0.0;
                return a;
            }

            Vector3d ap =
                p - a;

            t =
                ap.DotProduct(ab) /
                len2;

            t =
                Math.Max(
                    0.0,
                    Math.Min(
                        1.0,
                        t));

            return a +
                ab * t;
        }

        private static void AddManualArmDirection(
            List<Vector3d> arms,
            Vector3d direction)
        {
            if (arms == null)
                return;

            Vector3d d =
                new Vector3d(
                    direction.X,
                    direction.Y,
                    0.0);

            if (d.Length < 1e-9)
                return;

            arms.Add(
                d.GetNormal());
        }

        private static void DeduplicateManualArmDirections(
            List<Vector3d> arms,
            double toleranceDeg)
        {
            if (arms == null ||
                arms.Count <= 1)
            {
                return;
            }

            List<Vector3d> unique =
                new List<Vector3d>();

            foreach (Vector3d arm in arms)
            {
                if (arm.Length < 1e-9)
                    continue;

                Vector3d d =
                    arm.GetNormal();

                bool duplicate =
                    unique.Any(u =>
                        GetShopAngleDegrees(
                            u,
                            d) <=
                        toleranceDeg);

                if (!duplicate)
                    unique.Add(d);
            }

            arms.Clear();
            arms.AddRange(unique);
        }

        private static bool TryPickManualElbowArms(
            List<Vector3d> arms,
            double targetIncludedAngle,
            out Vector3d a,
            out Vector3d b,
            out double actualAngle)
        {
            a = Vector3d.XAxis;
            b = Vector3d.YAxis;
            actualAngle = 0.0;

            if (arms == null ||
                arms.Count < 2)
            {
                return false;
            }

            double bestError =
                double.MaxValue;

            for (int i = 0;
                i < arms.Count;
                i++)
            {
                for (int j = i + 1;
                    j < arms.Count;
                    j++)
                {
                    double angle =
                        GetShopAngleDegrees(
                            arms[i],
                            arms[j]);

                    double error =
                        Math.Abs(
                            angle -
                            targetIncludedAngle);

                    if (error < bestError)
                    {
                        bestError = error;
                        actualAngle = angle;
                        a = arms[i];
                        b = arms[j];
                    }
                }
            }

            double tolerance =
                targetIncludedAngle > 120.0
                    ? 24.0
                    : 20.0;

            return bestError <= tolerance;
        }

        private static bool TryPickManualTeeArms(
            List<Vector3d> arms,
            out Vector3d main1,
            out Vector3d main2,
            out Vector3d branch,
            out double bestScore)
        {
            main1 = Vector3d.XAxis;
            main2 = -Vector3d.XAxis;
            branch = Vector3d.YAxis;
            bestScore = double.MaxValue;

            if (arms == null ||
                arms.Count < 3)
            {
                return false;
            }

            bool found = false;

            for (int i = 0;
                i < arms.Count;
                i++)
            {
                for (int j = i + 1;
                    j < arms.Count;
                    j++)
                {
                    double mainAngle =
                        GetShopAngleDegrees(
                            arms[i],
                            arms[j]);

                    double mainError =
                        Math.Abs(
                            180.0 -
                            mainAngle);

                    if (mainError > 25.0)
                        continue;

                    for (int k = 0;
                        k < arms.Count;
                        k++)
                    {
                        if (k == i ||
                            k == j)
                        {
                            continue;
                        }

                        double e1 =
                            Math.Abs(
                                90.0 -
                                GetShopAngleDegrees(
                                    arms[i],
                                    arms[k]));

                        double e2 =
                            Math.Abs(
                                90.0 -
                                GetShopAngleDegrees(
                                    arms[j],
                                    arms[k]));

                        if (e1 > 28.0 ||
                            e2 > 28.0)
                        {
                            continue;
                        }

                        double score =
                            mainError * 2.0 +
                            e1 +
                            e2;

                        if (score < bestScore)
                        {
                            bestScore = score;
                            main1 = arms[i];
                            main2 = arms[j];
                            branch = arms[k];
                            found = true;
                        }
                    }
                }
            }

            return found;
        }

        private static string FormatManualDirection(
            Vector3d direction)
        {
            if (direction.Length < 1e-9)
                return "?";

            double deg =
                Math.Atan2(
                    direction.Y,
                    direction.X) *
                180.0 /
                Math.PI;

            while (deg < 0.0)
                deg += 360.0;

            while (deg >= 360.0)
                deg -= 360.0;

            return deg.ToString(
                "0.#",
                CultureInfo.InvariantCulture) +
                "°";
        }


        private bool TryInsertManualAccessoryBlock(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            string libraryPath,
            string sourceBlockName,
            Point3d insertPoint,
            string layerName)
        {
            if (tr == null ||
                db == null ||
                btr == null ||
                string.IsNullOrWhiteSpace(libraryPath) ||
                string.IsNullOrWhiteSpace(sourceBlockName))
            {
                return false;
            }

            ObjectId blockId =
                EnsureExternalBlockImported(
                    tr,
                    db,
                    libraryPath,
                    sourceBlockName);

            if (blockId.IsNull)
                return false;

            NormalizeShopImportedBlock(
                tr,
                blockId);

            // Với van / Y lọc / KNM: đặt tâm hình học đúng vào điểm click.
            Point3d basePoint =
                insertPoint;

            try
            {
                if (TryGetShopBlockLocalCenter(
                        tr,
                        blockId,
                        out Point3d localCenter,
                        out double _))
                {
                    basePoint =
                        insertPoint -
                        localCenter.GetAsVector();
                }
            }
            catch
            {
            }

            BlockReference br =
                new BlockReference(
                    basePoint,
                    blockId);

            br.SetDatabaseDefaults(db);
            br.Layer = layerName;
            br.Rotation = 0.0;
            br.ScaleFactors =
                new Scale3d(
                    1.0,
                    1.0,
                    1.0);

            br.Color =
                Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                    ColorMethod.ByAci,
                    GetShopVisibleAciColor(layerName));

            br.LineWeight =
                Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight000;

            br.Transparency =
                new Autodesk.AutoCAD.Colors.Transparency(
                    (byte)255);

            br.Visible = true;

            btr.AppendEntity(br);
            tr.AddNewlyCreatedDBObject(
                br,
                true);

            return true;
        }

        private string FindManualAccessoryBlockName(
            string libraryPath,
            string accessoryName,
            string sizeText)
        {
            if (string.IsNullOrWhiteSpace(libraryPath) ||
                !File.Exists(libraryPath) ||
                string.IsNullOrWhiteSpace(accessoryName))
            {
                return "";
            }

            try
            {
                using (Database libDb =
                    new Database(false, true))
                {
                    libDb.ReadDwgFile(
                        libraryPath,
                        FileOpenMode.OpenForReadAndAllShare,
                        true,
                        "");

                    using (Transaction tr =
                        libDb.TransactionManager.StartTransaction())
                    {
                        BlockTable bt =
                            (BlockTable)tr.GetObject(
                                libDb.BlockTableId,
                                OpenMode.ForRead);

                        string bestName = "";
                        int bestScore = int.MinValue;

                        foreach (ObjectId id in bt)
                        {
                            BlockTableRecord rec =
                                tr.GetObject(
                                    id,
                                    OpenMode.ForRead,
                                    false) as BlockTableRecord;

                            if (rec == null ||
                                rec.IsLayout ||
                                rec.IsAnonymous ||
                                rec.IsFromExternalReference)
                            {
                                continue;
                            }

                            string name =
                                rec.Name ?? "";

                            if (string.IsNullOrWhiteSpace(name))
                                continue;

                            int score =
                                ScoreManualAccessoryBlockName(
                                    name,
                                    accessoryName,
                                    sizeText);

                            if (score > bestScore)
                            {
                                bestScore = score;
                                bestName = name;
                            }
                        }

                        tr.Commit();

                        // Phải đạt điểm loại phụ kiện + size đủ chắc.
                        return bestScore >= 180
                            ? bestName
                            : "";
                    }
                }
            }
            catch
            {
                return "";
            }
        }

        private static int ScoreManualAccessoryBlockName(
            string blockName,
            string accessoryName,
            string sizeText)
        {
            string nameKey =
                NormalizeShopKey(
                    blockName ?? "");

            string accessoryKey =
                NormalizeShopKey(
                    accessoryName ?? "");

            if (string.IsNullOrWhiteSpace(nameKey) ||
                string.IsNullOrWhiteSpace(accessoryKey))
            {
                return int.MinValue;
            }

            int score = 0;
            bool typeHit = false;

            if (accessoryKey.Contains("VCONG"))
            {
                typeHit =
                    nameKey.Contains("VANCONG") ||
                    nameKey.Contains("GATEVALVE") ||
                    nameKey.Contains("GATE");

                if (typeHit) score += 220;
            }
            else if (accessoryKey.Contains("VBUOM"))
            {
                typeHit =
                    nameKey.Contains("VANBUOM") ||
                    nameKey.Contains("BUTTERFLYVALVE") ||
                    nameKey.Contains("BUTTERFLY");

                if (typeHit) score += 220;
            }
            else if (accessoryKey.Contains("YLOC"))
            {
                typeHit =
                    nameKey.Contains("YLOC") ||
                    nameKey.Contains("YFILTER") ||
                    nameKey.Contains("YSTRAINER") ||
                    nameKey.Contains("STRAINER");

                if (typeHit) score += 220;
            }
            else if (accessoryKey == "KNM" ||
                     accessoryKey.Contains("KHOPNOIMEM"))
            {
                typeHit =
                    nameKey.Contains("KNM") ||
                    nameKey.Contains("KHOPNOIMEM") ||
                    nameKey.Contains("FLEXIBLEJOINT") ||
                    nameKey.Contains("FLEXIBLE") ||
                    nameKey.Contains("RUBBERJOINT");

                if (typeHit) score += 220;
            }
            else
            {
                // Phụ kiện người dùng tự thêm:
                // thử khớp trực tiếp tên đã bỏ dấu/ký tự.
                typeHit =
                    nameKey.Contains(accessoryKey);

                if (typeHit) score += 200;
            }

            if (!typeHit)
                return int.MinValue;

            bool sizeHit =
                ShopKeyContainsSize(
                    blockName,
                    sizeText);

            bool blockHasDn =
                Regex.IsMatch(
                    nameKey,
                    @"DN\d{1,4}");

            if (sizeHit)
            {
                score += 120;
            }
            else if (blockHasDn)
            {
                // Block có ghi DN nhưng sai size -> loại.
                return int.MinValue;
            }
            else
            {
                // Dynamic/generic block không ghi DN:
                // vẫn cho dùng nhưng ưu tiên thấp hơn.
                score += 10;
            }

            // Ưu tiên block có tên ngắn/rõ hơn khi bằng điểm.
            score -=
                Math.Min(
                    nameKey.Length,
                    80) / 10;

            return score;
        }



        // ============================================================
        // FIX40O - CTN SHOP PPR
        // ============================================================

        private static bool TryMapCtnPprNominalDnToOutsideD(
            double nominalDn,
            out double outsideD)
        {
            outsideD = 0.0;

            // Mapping thực dụng cho PPR:
            // DN15 -> D20, DN20 -> D25, DN25 -> D32,
            // DN32 -> D40, DN40 -> D50, DN50 -> D63,
            // DN65 -> D75, DN80 -> D90, DN100 -> D110.
            //
            // Với size ngoài bảng (ví dụ DN125), fallback dùng chính số
            // để vẫn tìm được block D125 nếu thư viện có.
            double[][] map =
                new double[][]
                {
                    new double[] { 15, 20 },
                    new double[] { 20, 25 },
                    new double[] { 25, 32 },
                    new double[] { 32, 40 },
                    new double[] { 40, 50 },
                    new double[] { 50, 63 },
                    new double[] { 65, 75 },
                    new double[] { 80, 90 },
                    new double[] { 100, 110 }
                };

            foreach (double[] row in map)
            {
                if (Math.Abs(
                        row[0] -
                        nominalDn) <= 0.01)
                {
                    outsideD =
                        row[1];

                    return true;
                }
            }

            if (nominalDn > 0.0)
            {
                outsideD =
                    nominalDn;

                return true;
            }

            return false;
        }

        private bool TryParseCtnPprShopSize(
            string sourceText,
            out string sizeText,
            out double outsideDiameter)
        {
            sizeText = "";
            outsideDiameter = 0.0;

            string normalized =
                NormalizePipeLabel(
                    sourceText ?? "")
                    .Replace(',', '.')
                    .ToUpperInvariant();

            if (string.IsNullOrWhiteSpace(
                    normalized))
            {
                return false;
            }

            // 1) PPR ghi đúng theo Ø ngoài: D20 / D25 / Ø32 / Φ40...
            Match dMatch =
                Regex.Match(
                    normalized,
                    @"(?<![A-Z0-9])(?:D|Ø|Φ)\s*(?<SIZE>\d{1,4}(?:\.\d+)?)(?:\s*MM)?(?![A-Z0-9])",
                    RegexOptions.IgnoreCase);

            if (dMatch.Success &&
                double.TryParse(
                    dMatch.Groups["SIZE"].Value,
                    NumberStyles.AllowDecimalPoint,
                    CultureInfo.InvariantCulture,
                    out double dSize) &&
                dSize > 0.0)
            {
                outsideDiameter =
                    dSize;

                sizeText =
                    "D" +
                    FormatShopDnNumber(
                        dSize);

                return true;
            }

            // 2) Nếu bản vẽ đang ghi DN thì đổi sang Ø ngoài PPR.
            Match dnMatch =
                Regex.Match(
                    normalized,
                    @"(?<![A-Z0-9])DN\s*(?<SIZE>\d{1,4}(?:\.\d+)?)(?:\s*MM)?(?![A-Z0-9])",
                    RegexOptions.IgnoreCase);

            if (dnMatch.Success &&
                double.TryParse(
                    dnMatch.Groups["SIZE"].Value,
                    NumberStyles.AllowDecimalPoint,
                    CultureInfo.InvariantCulture,
                    out double nominalDn) &&
                TryMapCtnPprNominalDnToOutsideD(
                    nominalDn,
                    out double mappedD))
            {
                outsideDiameter =
                    mappedD;

                sizeText =
                    "D" +
                    FormatShopDnNumber(
                        mappedD);

                return true;
            }

            // 3) Layer CTN có thể chứa "_D20_" hoặc "_DN20_".
            Match embeddedD =
                Regex.Match(
                    normalized,
                    @"(?:^|[_\-\s])D\s*(?<SIZE>\d{1,4}(?:\.\d+)?)(?:$|[_\-\s])",
                    RegexOptions.IgnoreCase);

            if (embeddedD.Success &&
                double.TryParse(
                    embeddedD.Groups["SIZE"].Value,
                    NumberStyles.AllowDecimalPoint,
                    CultureInfo.InvariantCulture,
                    out double embeddedDSize) &&
                embeddedDSize > 0.0)
            {
                outsideDiameter =
                    embeddedDSize;

                sizeText =
                    "D" +
                    FormatShopDnNumber(
                        embeddedDSize);

                return true;
            }

            Match embeddedDn =
                Regex.Match(
                    normalized,
                    @"(?:^|[_\-\s])DN\s*(?<SIZE>\d{1,4}(?:\.\d+)?)(?:$|[_\-\s])",
                    RegexOptions.IgnoreCase);

            if (embeddedDn.Success &&
                double.TryParse(
                    embeddedDn.Groups["SIZE"].Value,
                    NumberStyles.AllowDecimalPoint,
                    CultureInfo.InvariantCulture,
                    out double embeddedNominal) &&
                TryMapCtnPprNominalDnToOutsideD(
                    embeddedNominal,
                    out double embeddedMappedD))
            {
                outsideDiameter =
                    embeddedMappedD;

                sizeText =
                    "D" +
                    FormatShopDnNumber(
                        embeddedMappedD);

                return true;
            }

            return false;
        }

        private void TryAddCtnPprShopSizeText(
            string rawText,
            Point3d position,
            double rotation,
            List<TextData> texts)
        {
            if (texts == null)
                return;

            if (!TryParseCtnPprShopSize(
                    rawText,
                    out string detectedSize,
                    out double outsideD))
            {
                return;
            }

            texts.Add(
                new TextData
                {
                    Position = position,
                    Rotation = rotation,
                    TextString = detectedSize,
                    LayerName =
                        "CTN_SHOP_PPR_" +
                        CleanLayerText(
                            detectedSize),
                    Width = outsideD
                });
        }

        private ShopPipeCandidate CreateCtnPprShopPipeCandidate(
            Curve curve,
            string sizeText,
            double outsideDiameter)
        {
            if (curve == null ||
                string.IsNullOrWhiteSpace(
                    sizeText) ||
                outsideDiameter <= 0.0)
            {
                return null;
            }

            try
            {
                Point3d start =
                    curve.StartPoint;

                Point3d end =
                    curve.EndPoint;

                Vector3d startDir =
                    GetShopCurveDirection(
                        curve,
                        true);

                Vector3d endDir =
                    GetShopCurveDirection(
                        curve,
                        false);

                if (startDir.Length < 1e-9 ||
                    endDir.Length < 1e-9)
                {
                    return null;
                }

                Vector3d startNormal =
                    GetPlanNormal(
                        startDir);

                Vector3d endNormal =
                    GetPlanNormal(
                        endDir);

                double half =
                    outsideDiameter /
                    2.0;

                string cleanSize =
                    CleanLayerText(
                        sizeText);

                return new ShopPipeCandidate
                {
                    Curve = curve,
                    SizeText = sizeText,
                    Width = outsideDiameter,
                    LayerName =
                        "CTN_SHOP_PPR_" +
                        cleanSize,
                    Start = start,
                    End = end,
                    StartLeft =
                        start +
                        startNormal * half,
                    StartRight =
                        start -
                        startNormal * half,
                    EndLeft =
                        end +
                        endNormal * half,
                    EndRight =
                        end -
                        endNormal * half
                };
            }
            catch
            {
                return null;
            }
        }

        private List<ShopPipeCandidate>
            CreateCtnPprShopSplitCandidatesFromTexts(
                Curve curve,
                List<TextProjectionData> projections)
        {
            List<ShopPipeCandidate> result =
                new List<ShopPipeCandidate>();

            if (curve == null ||
                projections == null ||
                projections.Count < 2 ||
                !(curve is Line ||
                  curve is Polyline ||
                  curve is Polyline2d ||
                  curve is Polyline3d))
            {
                return result;
            }

            if (!IsShopStraightCurve(
                    curve))
            {
                return result;
            }

            List<TextProjectionData> ordered =
                projections
                    .Where(
                        x =>
                            x != null &&
                            x.Text != null &&
                            x.Text.Width > 0.0)
                    .OrderBy(
                        x =>
                            x.DistanceAlongCurve)
                    .ToList();

            if (ordered.Count < 2)
                return result;

            try
            {
                double totalLength =
                    curve.GetDistanceAtParameter(
                        curve.EndParam);

                if (totalLength < 10.0)
                    return result;

                List<double> boundaries =
                    new List<double>
                    {
                        0.0
                    };

                for (int i = 0;
                    i < ordered.Count - 1;
                    i++)
                {
                    double middle =
                        (ordered[i]
                            .DistanceAlongCurve +
                         ordered[i + 1]
                            .DistanceAlongCurve) /
                        2.0;

                    if (middle > 1.0 &&
                        middle <
                            totalLength -
                            1.0)
                    {
                        boundaries.Add(
                            middle);
                    }
                }

                boundaries.Add(
                    totalLength);

                if (boundaries.Count !=
                    ordered.Count + 1)
                {
                    return result;
                }

                for (int i = 0;
                    i < ordered.Count;
                    i++)
                {
                    double d1 =
                        boundaries[i];

                    double d2 =
                        boundaries[i + 1];

                    if (d2 - d1 <
                        5.0)
                    {
                        continue;
                    }

                    Point3d p1 =
                        curve.GetPointAtDist(
                            d1);

                    Point3d p2 =
                        curve.GetPointAtDist(
                            d2);

                    if (p1.DistanceTo(p2) <
                        5.0)
                    {
                        continue;
                    }

                    Line segment =
                        new Line(
                            p1,
                            p2);

                    ShopPipeCandidate candidate =
                        CreateCtnPprShopPipeCandidate(
                            segment,
                            ordered[i]
                                .Text
                                .TextString,
                            ordered[i]
                                .Text
                                .Width);

                    if (candidate != null)
                        result.Add(candidate);
                }
            }
            catch
            {
                result.Clear();
            }

            return result;
        }

        /// <summary>
        /// Chỉ cho tuyến chưa có chữ kế thừa size khi:
        /// - cùng layer nguồn PPR (không dùng layer 0), và
        /// - một đầu tuyến thật sự chạm tuyến đã nhận size.
        /// Nhờ vậy các nhánh ngắn đi tới thiết bị vẫn được vẽ SHOP,
        /// nhưng line kiến trúc bị quét kèm không bị đổi thành ống.
        /// </summary>
        private bool CanInheritCtnPprShopSize(
            Curve unknownCurve,
            Curve knownCurve)
        {
            if (unknownCurve == null ||
                knownCurve == null ||
                ReferenceEquals(
                    unknownCurve,
                    knownCurve))
            {
                return false;
            }

            string unknownLayer =
                NormalizeShopKey(
                    unknownCurve.Layer ?? "");

            string knownLayer =
                NormalizeShopKey(
                    knownCurve.Layer ?? "");

            if (string.IsNullOrWhiteSpace(unknownLayer) ||
                string.IsNullOrWhiteSpace(knownLayer) ||
                unknownLayer == "0" ||
                knownLayer == "0" ||
                !string.Equals(
                    unknownLayer,
                    knownLayer,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            try
            {
                Point3d[] unknownEnds =
                    new[]
                    {
                        unknownCurve.StartPoint,
                        unknownCurve.EndPoint
                    };

                foreach (Point3d end
                    in unknownEnds)
                {
                    Point3d nearest =
                        knownCurve.GetClosestPointTo(
                            end,
                            false);

                    if (PlanDistance(
                            end,
                            nearest) <=
                        Math.Max(
                            10.0,
                            ShopJointTolerance))
                    {
                        return true;
                    }
                }
            }
            catch
            {
            }

            return false;
        }

        private int AddInheritedCtnPprShopCandidates(
            List<Curve> curves,
            Dictionary<Curve, ShopPipeCandidate> knownByCurve,
            Dictionary<Curve, ObjectId> sourceIdByCurve,
            List<ShopPipeCandidate> shopPipes,
            Dictionary<ShopPipeCandidate, ObjectId> sourceIdByCandidate,
            List<CtnPprDeviceInstance> devices)
        {
            if (curves == null ||
                knownByCurve == null ||
                sourceIdByCurve == null ||
                shopPipes == null ||
                sourceIdByCandidate == null ||
                devices == null)
            {
                return 0;
            }

            int totalAdded = 0;
            int maxPass = Math.Max(1, curves.Count);

            for (int pass = 0;
                pass < maxPass;
                pass++)
            {
                int addedThisPass = 0;

                foreach (Curve curve
                    in curves)
                {
                    if (curve == null ||
                        knownByCurve.ContainsKey(curve))
                    {
                        continue;
                    }

                    // Một đầu đang chạm block thiết bị và đầu còn lại nối mạng ống:
                    // không lấy DN của tuyến chính để đoán cho nhánh thiết bị.
                    if (TryFindCtnPprTerminalDeviceBranch(
                            curve,
                            curves,
                            devices,
                            out CtnPprDeviceInstance ignoredDevice))
                    {
                        continue;
                    }

                    List<ShopPipeCandidate> connected =
                        knownByCurve
                            .Where(x =>
                                CanInheritCtnPprShopSize(
                                    curve,
                                    x.Key))
                            .Select(x => x.Value)
                            .Where(x => x != null)
                            .ToList();

                    if (connected.Count == 0)
                        continue;

                    List<ShopPipeCandidate> uniqueSizes =
                        connected
                            .GroupBy(x =>
                                CleanLayerText(
                                    x.SizeText ?? ""),
                                StringComparer.OrdinalIgnoreCase)
                            .Select(g => g.First())
                            .ToList();

                    // Hai tuyến lân cận cho hai size khác nhau:
                    // không đoán bừa size cho nhánh chưa có chữ.
                    if (uniqueSizes.Count != 1)
                        continue;

                    ShopPipeCandidate source =
                        uniqueSizes[0];

                    ShopPipeCandidate inherited =
                        CreateCtnPprShopPipeCandidate(
                            curve,
                            source.SizeText,
                            source.Width);

                    if (inherited == null)
                        continue;

                    shopPipes.Add(inherited);
                    knownByCurve[curve] = inherited;

                    if (sourceIdByCurve.TryGetValue(
                            curve,
                            out ObjectId sourceId) &&
                        !sourceId.IsNull)
                    {
                        sourceIdByCandidate[inherited] =
                            sourceId;
                    }

                    addedThisPass++;
                    totalAdded++;
                }

                if (addedThisPass == 0)
                    break;
            }

            return totalAdded;
        }

        private void TryAddCtnShopOccupiedBlockExtents(
            Transaction tr,
            BlockReference blockReference,
            List<Extents3d> occupiedExtents)
        {
            if (tr == null ||
                blockReference == null ||
                occupiedExtents == null ||
                blockReference.IsErased)
            {
                return;
            }

            try
            {
                BlockTableRecord definition =
                    tr.GetObject(
                        blockReference.BlockTableRecord,
                        OpenMode.ForRead,
                        false) as BlockTableRecord;

                if (definition == null ||
                    definition.IsLayout ||
                    definition.IsFromExternalReference)
                {
                    return;
                }

                Extents3d ext =
                    blockReference.GeometricExtents;

                double dx =
                    Math.Abs(
                        ext.MaxPoint.X -
                        ext.MinPoint.X);

                double dy =
                    Math.Abs(
                        ext.MaxPoint.Y -
                        ext.MinPoint.Y);

                double maxSpan =
                    Math.Max(dx, dy);

                // Bỏ block rỗng và block kiến trúc quá lớn.
                if (maxSpan < 2.0 ||
                    maxSpan > 3000.0)
                {
                    return;
                }

                occupiedExtents.Add(ext);
            }
            catch
            {
            }
        }

        private Extents3d TransformCtnDeviceExtents(
            Extents3d source,
            Matrix3d transform)
        {
            Point3d[] corners =
                new[]
                {
                    new Point3d(source.MinPoint.X, source.MinPoint.Y, source.MinPoint.Z),
                    new Point3d(source.MinPoint.X, source.MinPoint.Y, source.MaxPoint.Z),
                    new Point3d(source.MinPoint.X, source.MaxPoint.Y, source.MinPoint.Z),
                    new Point3d(source.MinPoint.X, source.MaxPoint.Y, source.MaxPoint.Z),
                    new Point3d(source.MaxPoint.X, source.MinPoint.Y, source.MinPoint.Z),
                    new Point3d(source.MaxPoint.X, source.MinPoint.Y, source.MaxPoint.Z),
                    new Point3d(source.MaxPoint.X, source.MaxPoint.Y, source.MinPoint.Z),
                    new Point3d(source.MaxPoint.X, source.MaxPoint.Y, source.MaxPoint.Z)
                };

            Point3d first =
                corners[0].TransformBy(transform);

            Extents3d result =
                new Extents3d(first, first);

            for (int i = 1;
                i < corners.Length;
                i++)
            {
                result.AddPoint(
                    corners[i].TransformBy(transform));
            }

            return result;
        }

        private string GetCtnPprDeviceSignature(
            Transaction tr,
            BlockReference blockReference,
            Extents3d worldExtents)
        {
            if (tr == null || blockReference == null)
                return "";

            string name = "";

            try
            {
                ObjectId definitionId =
                    blockReference.BlockTableRecord;

                if (blockReference.IsDynamicBlock &&
                    !blockReference.DynamicBlockTableRecord.IsNull &&
                    blockReference.DynamicBlockTableRecord.IsValid)
                {
                    definitionId =
                        blockReference.DynamicBlockTableRecord;
                }

                BlockTableRecord definition =
                    tr.GetObject(
                        definitionId,
                        OpenMode.ForRead,
                        false) as BlockTableRecord;

                name = definition?.Name ?? "";
            }
            catch
            {
            }

            string nameKey =
                NormalizeShopKey(name);

            double dx =
                Math.Abs(
                    worldExtents.MaxPoint.X -
                    worldExtents.MinPoint.X);

            double dy =
                Math.Abs(
                    worldExtents.MaxPoint.Y -
                    worldExtents.MinPoint.Y);

            // Sắp xếp hai cạnh để cùng block xoay 90° vẫn cùng dấu nhận dạng.
            double small = Math.Min(dx, dy);
            double large = Math.Max(dx, dy);

            string geometryKey =
                Math.Round(small / 10.0).ToString(
                    CultureInfo.InvariantCulture) +
                "X" +
                Math.Round(large / 10.0).ToString(
                    CultureInfo.InvariantCulture);

            if (string.IsNullOrWhiteSpace(nameKey))
                nameKey = "ANON";

            return nameKey + "|" + geometryKey;
        }

        private void AddCtnPprDeviceInstance(
            Transaction tr,
            BlockReference blockReference,
            Extents3d worldExtents,
            List<CtnPprDeviceInstance> devices)
        {
            if (tr == null ||
                blockReference == null ||
                devices == null)
            {
                return;
            }

            double dx =
                Math.Abs(
                    worldExtents.MaxPoint.X -
                    worldExtents.MinPoint.X);

            double dy =
                Math.Abs(
                    worldExtents.MaxPoint.Y -
                    worldExtents.MinPoint.Y);

            double maxSpan = Math.Max(dx, dy);

            // Giữ cả block đầu nối nhỏ và thiết bị vệ sinh lớn,
            // bỏ block rỗng hoặc khung kiến trúc quá lớn.
            if (maxSpan < 15.0 ||
                maxSpan > 3000.0)
            {
                return;
            }

            string signature =
                GetCtnPprDeviceSignature(
                    tr,
                    blockReference,
                    worldExtents);

            if (string.IsNullOrWhiteSpace(signature))
                return;

            Point3d center =
                new Point3d(
                    (worldExtents.MinPoint.X + worldExtents.MaxPoint.X) * 0.5,
                    (worldExtents.MinPoint.Y + worldExtents.MaxPoint.Y) * 0.5,
                    (worldExtents.MinPoint.Z + worldExtents.MaxPoint.Z) * 0.5);

            bool duplicate =
                devices.Any(x =>
                    x != null &&
                    string.Equals(
                        x.Signature,
                        signature,
                        StringComparison.OrdinalIgnoreCase) &&
                    PlanDistance(
                        x.Center,
                        center) <= 2.0);

            if (duplicate)
                return;

            devices.Add(
                new CtnPprDeviceInstance
                {
                    Signature = signature,
                    Extents = worldExtents,
                    Center = center,
                    MaxSpan = maxSpan
                });
        }

        private void CollectCtnPprNestedDeviceInstances(
            Transaction tr,
            BlockTableRecord parentDefinition,
            Matrix3d parentToWorld,
            List<CtnPprDeviceInstance> devices,
            HashSet<ObjectId> definitionPath,
            int depth)
        {
            if (tr == null ||
                parentDefinition == null ||
                devices == null ||
                definitionPath == null ||
                depth > 12 ||
                definitionPath.Contains(
                    parentDefinition.ObjectId))
            {
                return;
            }

            definitionPath.Add(
                parentDefinition.ObjectId);

            try
            {
                foreach (ObjectId childId
                    in parentDefinition)
                {
                    BlockReference nested =
                        tr.GetObject(
                            childId,
                            OpenMode.ForRead,
                            false) as BlockReference;

                    if (nested == null || nested.IsErased)
                        continue;

                    try
                    {
                        Extents3d worldExtents =
                            TransformCtnDeviceExtents(
                                nested.GeometricExtents,
                                parentToWorld);

                        AddCtnPprDeviceInstance(
                            tr,
                            nested,
                            worldExtents,
                            devices);
                    }
                    catch
                    {
                    }

                    BlockTableRecord nestedDefinition =
                        null;

                    try
                    {
                        nestedDefinition =
                            tr.GetObject(
                                nested.BlockTableRecord,
                                OpenMode.ForRead,
                                false) as BlockTableRecord;
                    }
                    catch
                    {
                    }

                    if (nestedDefinition == null)
                        continue;

                    Matrix3d nestedToWorld =
                        parentToWorld *
                        nested.BlockTransform;

                    CollectCtnPprNestedDeviceInstances(
                        tr,
                        nestedDefinition,
                        nestedToWorld,
                        devices,
                        definitionPath,
                        depth + 1);
                }
            }
            catch
            {
            }
            finally
            {
                definitionPath.Remove(
                    parentDefinition.ObjectId);
            }
        }

        private void CollectCtnPprDeviceInstances(
            Transaction tr,
            BlockReference rootBlock,
            List<CtnPprDeviceInstance> devices)
        {
            if (tr == null ||
                rootBlock == null ||
                devices == null ||
                rootBlock.IsErased)
            {
                return;
            }

            BlockTableRecord rootDefinition = null;

            try
            {
                rootDefinition =
                    tr.GetObject(
                        rootBlock.BlockTableRecord,
                        OpenMode.ForRead,
                        false) as BlockTableRecord;
            }
            catch
            {
            }

            if (rootDefinition == null)
                return;

            // Block thiết bị đặt trực tiếp trong bản vẽ.
            if (!rootDefinition.IsFromExternalReference)
            {
                try
                {
                    AddCtnPprDeviceInstance(
                        tr,
                        rootBlock,
                        rootBlock.GeometricExtents,
                        devices);
                }
                catch
                {
                }
            }

            // Nếu root là XREF thì duyệt các block thiết bị nằm bên trong.
            CollectCtnPprNestedDeviceInstances(
                tr,
                rootDefinition,
                rootBlock.BlockTransform,
                devices,
                new HashSet<ObjectId>(),
                0);
        }

        private double DistanceFromPointToCtnDeviceExtents(
            Point3d point,
            Extents3d extents)
        {
            double dx = 0.0;
            double dy = 0.0;

            if (point.X < extents.MinPoint.X)
                dx = extents.MinPoint.X - point.X;
            else if (point.X > extents.MaxPoint.X)
                dx = point.X - extents.MaxPoint.X;

            if (point.Y < extents.MinPoint.Y)
                dy = extents.MinPoint.Y - point.Y;
            else if (point.Y > extents.MaxPoint.Y)
                dy = point.Y - extents.MaxPoint.Y;

            return Math.Sqrt(dx * dx + dy * dy);
        }

        private CtnPprDeviceInstance FindCtnPprDeviceAtCurveEnd(
            Curve curve,
            List<CtnPprDeviceInstance> devices)
        {
            if (curve == null ||
                devices == null ||
                devices.Count == 0)
            {
                return null;
            }

            Point3d start;
            Point3d end;

            try
            {
                start = curve.StartPoint;
                end = curve.EndPoint;
            }
            catch
            {
                return null;
            }

            CtnPprDeviceInstance best = null;
            double bestDistance = double.MaxValue;

            foreach (CtnPprDeviceInstance device
                in devices)
            {
                if (device == null)
                    continue;

                double distance =
                    Math.Min(
                        DistanceFromPointToCtnDeviceExtents(
                            start,
                            device.Extents),
                        DistanceFromPointToCtnDeviceExtents(
                            end,
                            device.Extents));

                double maxAllowed =
                    Math.Max(
                        80.0,
                        Math.Min(
                            350.0,
                            device.MaxSpan * 0.35));

                if (distance > maxAllowed)
                    continue;

                // Nếu nhiều block lồng cùng chứa đầu ống, ưu tiên block nhỏ
                // nằm sát đầu nối hơn thay vì lấy cả khung XREF lớn.
                double score =
                    distance +
                    device.MaxSpan * 0.0001;

                if (score < bestDistance)
                {
                    bestDistance = score;
                    best = device;
                }
            }

            return best;
        }

        private bool IsCtnPprCurveEndConnectedToOtherCurve(
            Point3d endPoint,
            Curve sourceCurve,
            List<Curve> curves)
        {
            if (sourceCurve == null || curves == null)
                return false;

            double tolerance =
                Math.Max(
                    10.0,
                    ShopJointTolerance);

            foreach (Curve other
                in curves)
            {
                if (other == null ||
                    ReferenceEquals(
                        other,
                        sourceCurve))
                {
                    continue;
                }

                try
                {
                    Point3d nearest =
                        other.GetClosestPointTo(
                            endPoint,
                            false);

                    if (PlanDistance(
                            endPoint,
                            nearest) <= tolerance)
                    {
                        return true;
                    }
                }
                catch
                {
                }
            }

            return false;
        }

        private bool TryFindCtnPprTerminalDeviceBranch(
            Curve curve,
            List<Curve> curves,
            List<CtnPprDeviceInstance> devices,
            out CtnPprDeviceInstance device)
        {
            device =
                FindCtnPprDeviceAtCurveEnd(
                    curve,
                    devices);

            if (curve == null || device == null)
                return false;

            Point3d start;
            Point3d end;

            try
            {
                start = curve.StartPoint;
                end = curve.EndPoint;
            }
            catch
            {
                device = null;
                return false;
            }

            double startDistance =
                DistanceFromPointToCtnDeviceExtents(
                    start,
                    device.Extents);

            double endDistance =
                DistanceFromPointToCtnDeviceExtents(
                    end,
                    device.Extents);

            Point3d deviceEnd =
                startDistance <= endDistance
                    ? start
                    : end;

            Point3d networkEnd =
                startDistance <= endDistance
                    ? end
                    : start;

            bool networkEndConnected =
                IsCtnPprCurveEndConnectedToOtherCurve(
                    networkEnd,
                    curve,
                    curves);

            bool deviceEndConnected =
                IsCtnPprCurveEndConnectedToOtherCurve(
                    deviceEnd,
                    curve,
                    curves);

            // Nhánh cấp tới thiết bị phải có đúng tính chất đầu cuối:
            // một đầu nối vào mạng ống, đầu sát thiết bị không nối tiếp tuyến khác.
            if (!networkEndConnected || deviceEndConnected)
            {
                device = null;
                return false;
            }

            return true;
        }

        private Dictionary<string, ShopPipeCandidate>
            LearnCtnPprDeviceSizes(
                Dictionary<Curve, ShopPipeCandidate> directlyKnownByCurve,
                List<Curve> curves,
                List<CtnPprDeviceInstance> devices)
        {
            Dictionary<string, List<ShopPipeCandidate>> samples =
                new Dictionary<string, List<ShopPipeCandidate>>(
                    StringComparer.OrdinalIgnoreCase);

            if (directlyKnownByCurve != null &&
                devices != null)
            {
                foreach (KeyValuePair<Curve, ShopPipeCandidate> pair
                    in directlyKnownByCurve)
                {
                    if (pair.Key == null || pair.Value == null)
                        continue;

                    if (!TryFindCtnPprTerminalDeviceBranch(
                            pair.Key,
                            curves,
                            devices,
                            out CtnPprDeviceInstance device) ||
                        string.IsNullOrWhiteSpace(
                            device.Signature))
                    {
                        continue;
                    }

                    if (!samples.ContainsKey(device.Signature))
                    {
                        samples[device.Signature] =
                            new List<ShopPipeCandidate>();
                    }

                    samples[device.Signature].Add(
                        pair.Value);
                }
            }

            Dictionary<string, ShopPipeCandidate> learned =
                new Dictionary<string, ShopPipeCandidate>(
                    StringComparer.OrdinalIgnoreCase);

            foreach (KeyValuePair<string, List<ShopPipeCandidate>> item
                in samples)
            {
                List<ShopPipeCandidate> uniqueSizes =
                    item.Value
                        .Where(x => x != null)
                        .GroupBy(x =>
                            CleanLayerText(
                                x.SizeText ?? ""),
                            StringComparer.OrdinalIgnoreCase)
                        .Select(g => g.First())
                        .ToList();

                // Cùng loại thiết bị xuất hiện hai size mẫu khác nhau:
                // không học để tránh gán sai hàng loạt.
                if (uniqueSizes.Count == 1)
                {
                    learned[item.Key] =
                        uniqueSizes[0];
                }
            }

            return learned;
        }

        private int AddDeviceMatchedCtnPprShopCandidates(
            List<Curve> curves,
            Dictionary<Curve, ShopPipeCandidate> knownByCurve,
            Dictionary<Curve, ShopPipeCandidate> directlyKnownByCurve,
            Dictionary<Curve, ObjectId> sourceIdByCurve,
            List<ShopPipeCandidate> shopPipes,
            Dictionary<ShopPipeCandidate, ObjectId> sourceIdByCandidate,
            List<CtnPprDeviceInstance> devices,
            Dictionary<string, ShopPipeCandidate> learnedDeviceSizes)
        {
            if (curves == null ||
                knownByCurve == null ||
                directlyKnownByCurve == null ||
                sourceIdByCurve == null ||
                shopPipes == null ||
                sourceIdByCandidate == null ||
                devices == null ||
                learnedDeviceSizes == null)
            {
                return 0;
            }

            int added = 0;

            foreach (Curve curve
                in curves)
            {
                if (curve == null ||
                    directlyKnownByCurve.ContainsKey(curve))
                {
                    continue;
                }

                if (!TryFindCtnPprTerminalDeviceBranch(
                        curve,
                        curves,
                        devices,
                        out CtnPprDeviceInstance device) ||
                    !learnedDeviceSizes.TryGetValue(
                        device.Signature,
                        out ShopPipeCandidate learned) ||
                    learned == null)
                {
                    continue;
                }

                ShopPipeCandidate candidate =
                    CreateCtnPprShopPipeCandidate(
                        curve,
                        learned.SizeText,
                        learned.Width);

                if (candidate == null)
                    continue;

                // Candidate lấy từ tên layer chỉ là dự phòng. Khi đã nhận ra
                // đúng mẫu thiết bị thì phải bỏ DN layer (thường là DN25 tuyến chính).
                if (knownByCurve.TryGetValue(
                        curve,
                        out ShopPipeCandidate provisional) &&
                    provisional != null)
                {
                    shopPipes.Remove(
                        provisional);

                    sourceIdByCandidate.Remove(
                        provisional);
                }

                shopPipes.Add(candidate);
                knownByCurve[curve] = candidate;

                if (sourceIdByCurve.TryGetValue(
                        curve,
                        out ObjectId sourceId) &&
                    !sourceId.IsNull)
                {
                    sourceIdByCandidate[candidate] =
                        sourceId;
                }

                added++;
            }

            return added;
        }

        private int RemoveUnsafeCtnPprDeviceFallbackCandidates(
            List<Curve> curves,
            Dictionary<Curve, ShopPipeCandidate> directlyKnownByCurve,
            Dictionary<Curve, ShopPipeCandidate> layerFallbackByCurve,
            Dictionary<Curve, ShopPipeCandidate> knownByCurve,
            List<ShopPipeCandidate> shopPipes,
            Dictionary<ShopPipeCandidate, ObjectId> sourceIdByCandidate,
            List<CtnPprDeviceInstance> devices,
            Dictionary<string, ShopPipeCandidate> learnedDeviceSizes)
        {
            if (curves == null ||
                directlyKnownByCurve == null ||
                layerFallbackByCurve == null ||
                knownByCurve == null ||
                shopPipes == null ||
                sourceIdByCandidate == null ||
                devices == null ||
                learnedDeviceSizes == null)
            {
                return 0;
            }

            int removed = 0;

            foreach (KeyValuePair<Curve, ShopPipeCandidate> pair
                in layerFallbackByCurve.ToList())
            {
                Curve curve = pair.Key;
                ShopPipeCandidate fallback = pair.Value;

                if (curve == null ||
                    fallback == null ||
                    directlyKnownByCurve.ContainsKey(curve) ||
                    !knownByCurve.TryGetValue(
                        curve,
                        out ShopPipeCandidate current) ||
                    !ReferenceEquals(
                        current,
                        fallback))
                {
                    continue;
                }

                if (!TryFindCtnPprTerminalDeviceBranch(
                        curve,
                        curves,
                        devices,
                        out CtnPprDeviceInstance device))
                {
                    continue;
                }

                // Có mẫu đã học thì AddDeviceMatched... phải thay candidate trước đó.
                // Không có mẫu đáng tin: bỏ DN lấy từ layer và giữ nguyên line nguồn.
                if (learnedDeviceSizes.ContainsKey(
                        device.Signature))
                {
                    continue;
                }

                shopPipes.Remove(
                    fallback);

                sourceIdByCandidate.Remove(
                    fallback);

                knownByCurve.Remove(
                    curve);

                removed++;
            }

            return removed;
        }

        private void BtnVeShopOngPprCTN_Click(
            object sender,
            RoutedEventArgs e)
        {
            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var ed =
                doc.Editor;

            var db =
                doc.Database;

            Autodesk.AutoCAD.Internal.Utils
                .SetFocusToDwgView();

            PromptSelectionOptions pso =
                new PromptSelectionOptions();

            pso.MessageForAdding =
                "\n[SHOP CTN PPR] Quét tuyến PPR + chữ D/DN + XREF/block thiết bị: ";

            TypedValue[] tvs =
                new TypedValue[]
                {
                    new TypedValue(
                        (int)DxfCode.Operator,
                        "<OR"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "LINE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "LWPOLYLINE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "POLYLINE"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "ARC"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "TEXT"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "MTEXT"),
                    new TypedValue(
                        (int)DxfCode.Start,
                        "INSERT"),
                    new TypedValue(
                        (int)DxfCode.Operator,
                        "OR>")
                };

            PromptSelectionResult psr =
                ed.GetSelection(
                    pso,
                    new SelectionFilter(
                        tvs));

            if (psr.Status !=
                    PromptStatus.OK ||
                psr.Value == null ||
                psr.Value.Count == 0)
            {
                return;
            }

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager
                    .StartTransaction())
            {
                BlockTableRecord btr =
                    (BlockTableRecord)
                    tr.GetObject(
                        db.CurrentSpaceId,
                        OpenMode.ForWrite);

                List<Curve> curves =
                    new List<Curve>();

                Dictionary<Curve, ObjectId>
                    sourceIdByCurve =
                        new Dictionary<Curve, ObjectId>();

                List<TextData> texts =
                    new List<TextData>();

                List<Extents3d> occupiedBlockExtents =
                    new List<Extents3d>();

                List<CtnPprDeviceInstance> deviceInstances =
                    new List<CtnPprDeviceInstance>();

                foreach (SelectedObject so
                    in psr.Value)
                {
                    if (so == null ||
                        so.ObjectId.IsNull)
                    {
                        continue;
                    }

                    Entity ent =
                        tr.GetObject(
                            so.ObjectId,
                            OpenMode.ForRead)
                            as Entity;

                    if (ent == null)
                        continue;

                    if ((ent is Line ||
                         ent is Polyline ||
                         ent is Polyline2d ||
                         ent is Polyline3d ||
                         ent is Arc) &&
                        ent is Curve curveEnt)
                    {
                        curves.Add(
                            curveEnt);

                        sourceIdByCurve[curveEnt] =
                            so.ObjectId;
                    }
                    else if (ent is DBText dbText)
                    {
                        Point3d pt =
                            (dbText.Justify !=
                                AttachmentPoint.BaseLeft &&
                             (dbText.AlignmentPoint.X != 0.0 ||
                              dbText.AlignmentPoint.Y != 0.0))
                                ? dbText.AlignmentPoint
                                : dbText.Position;

                        TryAddCtnPprShopSizeText(
                            dbText.TextString,
                            pt,
                            dbText.Rotation,
                            texts);
                    }
                    else if (ent is MText mText)
                    {
                        TryAddCtnPprShopSizeText(
                            mText.Text,
                            mText.Location,
                            mText.Rotation,
                            texts);
                    }
                    else if (ent is BlockReference blockRef)
                    {
                        // Ghi nhận vùng đã có thiết bị/phụ kiện.
                        // Engine SHOP không được chèn thêm block chồng lên đó.
                        TryAddCtnShopOccupiedBlockExtents(
                            tr,
                            blockRef,
                            occupiedBlockExtents);

                        // Với XREF: duyệt các block thiết bị lồng bên trong.
                        // Cùng tên block + cùng kích thước hình học = cùng mẫu thiết bị.
                        CollectCtnPprDeviceInstances(
                            tr,
                            blockRef,
                            deviceInstances);

                        foreach (ObjectId attId
                            in blockRef
                                .AttributeCollection)
                        {
                            AttributeReference att =
                                tr.GetObject(
                                    attId,
                                    OpenMode.ForRead,
                                    false)
                                    as AttributeReference;

                            if (att == null)
                                continue;

                            TryAddCtnPprShopSizeText(
                                att.TextString,
                                att.Position,
                                att.Rotation,
                                texts);
                        }
                    }
                }

                if (curves.Count == 0)
                {
                    MessageBox.Show(
                        "Phải quét trúng ít nhất 1 line/polyline tuyến PPR.",
                        "VẼ SHOP CTN - PPR");

                    return;
                }

                Dictionary<Curve, List<TextProjectionData>>
                    textMap =
                        MapTextsToOriginalCurves(
                            curves,
                            texts);

                List<ShopPipeCandidate> shopPipes =
                    new List<ShopPipeCandidate>();

                // Map ngược để CHỈ xóa line nguồn khi chính candidate đó
                // đã vẽ ra SHOP thành công.
                Dictionary<ShopPipeCandidate, ObjectId>
                    sourceIdByCandidate =
                        new Dictionary<ShopPipeCandidate, ObjectId>();

                // Đại diện size theo từng curve nguồn để các nhánh ngắn
                // cùng layer có thể kế thừa size tới thiết bị.
                Dictionary<Curve, ShopPipeCandidate>
                    knownByCurve =
                        new Dictionary<Curve, ShopPipeCandidate>();

                // Chỉ chữ DN/D đặt trực tiếp gần nhánh mới được dùng làm mẫu học.
                // Size đọc từ layer là dự phòng, không được ghi đè mẫu thiết bị.
                Dictionary<Curve, ShopPipeCandidate>
                    directlyKnownByCurve =
                        new Dictionary<Curve, ShopPipeCandidate>();

                Dictionary<Curve, ShopPipeCandidate>
                    layerFallbackByCurve =
                        new Dictionary<Curve, ShopPipeCandidate>();

                foreach (Curve curve
                    in curves)
                {
                    List<TextProjectionData>
                        projections =
                            null;

                    if (textMap.TryGetValue(
                            curve,
                            out projections) &&
                        projections != null &&
                        projections.Count > 0)
                    {
                        List<ShopPipeCandidate>
                            splitCandidates =
                                CreateCtnPprShopSplitCandidatesFromTexts(
                                    curve,
                                    projections);

                        if (splitCandidates.Count >
                            0)
                        {
                            shopPipes.AddRange(
                                splitCandidates);

                            if (sourceIdByCurve.TryGetValue(
                                    curve,
                                    out ObjectId splitSourceId) &&
                                !splitSourceId.IsNull)
                            {
                                foreach (ShopPipeCandidate split
                                    in splitCandidates)
                                {
                                    sourceIdByCandidate[split] =
                                        splitSourceId;
                                }
                            }

                            List<ShopPipeCandidate> splitUniqueSizes =
                                splitCandidates
                                    .GroupBy(x =>
                                        CleanLayerText(
                                            x.SizeText ?? ""),
                                        StringComparer.OrdinalIgnoreCase)
                                    .Select(g => g.First())
                                    .ToList();

                            if (splitUniqueSizes.Count == 1)
                            {
                                knownByCurve[curve] =
                                    splitUniqueSizes[0];

                                directlyKnownByCurve[curve] =
                                    splitUniqueSizes[0];
                            }

                            continue;
                        }

                        TextProjectionData best =
                            projections
                                .OrderBy(
                                    x =>
                                        x.MatchScore)
                                .ThenBy(
                                    x =>
                                        x.DistanceAlongCurve)
                                .First();

                        ShopPipeCandidate
                            candidate =
                                CreateCtnPprShopPipeCandidate(
                                    curve,
                                    best.Text
                                        .TextString,
                                    best.Text
                                        .Width);

                        if (candidate != null)
                        {
                            shopPipes.Add(
                                candidate);

                            knownByCurve[curve] =
                                candidate;

                            directlyKnownByCurve[curve] =
                                candidate;

                            if (sourceIdByCurve.TryGetValue(
                                    curve,
                                    out ObjectId textSourceId) &&
                                !textSourceId.IsNull)
                            {
                                sourceIdByCandidate[candidate] =
                                    textSourceId;
                            }
                        }

                        continue;
                    }

                    // Fallback đọc D/DN ngay từ tên layer CTN.
                    if (TryParseCtnPprShopSize(
                            curve.Layer,
                            out string layerSize,
                            out double layerOutsideD))
                    {
                        ShopPipeCandidate
                            candidate =
                                CreateCtnPprShopPipeCandidate(
                                    curve,
                                    layerSize,
                                    layerOutsideD);

                        if (candidate != null)
                        {
                            shopPipes.Add(
                                candidate);

                            knownByCurve[curve] =
                                candidate;

                            layerFallbackByCurve[curve] =
                                candidate;

                            if (sourceIdByCurve.TryGetValue(
                                    curve,
                                    out ObjectId layerSourceId) &&
                                !layerSourceId.IsNull)
                            {
                                sourceIdByCandidate[candidate] =
                                    layerSourceId;
                            }
                        }
                    }
                }

                Dictionary<string, ShopPipeCandidate>
                    learnedDeviceSizes =
                        LearnCtnPprDeviceSizes(
                            directlyKnownByCurve,
                            curves,
                            deviceInstances);

                int deviceMatchedPipeCount =
                    AddDeviceMatchedCtnPprShopCandidates(
                        curves,
                        knownByCurve,
                        directlyKnownByCurve,
                        sourceIdByCurve,
                        shopPipes,
                        sourceIdByCandidate,
                        deviceInstances,
                        learnedDeviceSizes);

                int preservedDeviceBranchCount =
                    RemoveUnsafeCtnPprDeviceFallbackCandidates(
                        curves,
                        directlyKnownByCurve,
                        layerFallbackByCurve,
                        knownByCurve,
                        shopPipes,
                        sourceIdByCandidate,
                        deviceInstances,
                        learnedDeviceSizes);

                // Chỉ chặn chèn phụ kiện trong đúng những mẫu thiết bị đã học.
                // Không lấy toàn bộ khung XREF làm vùng cấm.
                foreach (CtnPprDeviceInstance device
                    in deviceInstances)
                {
                    if (device != null &&
                        learnedDeviceSizes.ContainsKey(
                            device.Signature))
                    {
                        occupiedBlockExtents.Add(
                            device.Extents);
                    }
                }

                int inheritedPipeCount =
                    AddInheritedCtnPprShopCandidates(
                        curves,
                        knownByCurve,
                        sourceIdByCurve,
                        shopPipes,
                        sourceIdByCandidate,
                        deviceInstances);

                if (shopPipes.Count == 0)
                {
                    MessageBox.Show(
                        "Không nhận được size PPR.\n\n" +
                        "Hãy quét thêm chữ dạng D20 / D25 / D32... " +
                        "hoặc DN15 / DN20... gần tuyến ống.\n" +
                        "Muốn học size theo thiết bị, hãy quét luôn XREF/block " +
                        "và ít nhất một nhánh cùng mẫu đã có chữ DN.",
                        "VẼ SHOP CTN - PPR");

                    return;
                }

                string shopLibraryPath =
                    FindShopFittingLibraryPath(
                        "PPR",
                        db);

                if (string.IsNullOrWhiteSpace(
                        shopLibraryPath))
                {
                    MessageBox.Show(
                        "Không tìm thấy file Thu vien PPR.dwg trong thư mục DLL.",
                        "VẼ SHOP CTN - PPR");

                    return;
                }

                ed.WriteMessage(
                    "\n[CTN SHOP PPR] Thư viện: " +
                    Path.GetFileName(
                        shopLibraryPath));

                List<ShopFittingGapInfo>
                    fittingGaps =
                        new List<ShopFittingGapInfo>();

                int reducerCount;
                int elbow90Count;
                int elbow45Count;
                int teeCount;
                int sprinklerElbowCount;

                // CTN không dùng logic co đầu phun:
                // truyền danh sách đầu phun rỗng.
                int fittingCount =
                    DrawSmartShopFittings(
                        tr,
                        db,
                        btr,
                        shopPipes,
                        new List<Point3d>(),
                        shopLibraryPath,
                        fittingGaps,
                        out reducerCount,
                        out elbow90Count,
                        out elbow45Count,
                        out teeCount,
                        out sprinklerElbowCount,
                        occupiedBlockExtents);

                int edgeCount =
                    0;

                HashSet<ObjectId> drawnSourceIds =
                    new HashSet<ObjectId>();

                foreach (ShopPipeCandidate pipe
                    in shopPipes)
                {
                    EnsureShopLayerExists(
                        tr,
                        db,
                        pipe.LayerName);

                    int drawnForPipe =
                        DrawShopParallelPipeWithGaps(
                            tr,
                            db,
                            btr,
                            pipe,
                            fittingGaps);

                    edgeCount +=
                        drawnForPipe;

                    if (drawnForPipe > 0 &&
                        sourceIdByCandidate.TryGetValue(
                            pipe,
                            out ObjectId drawnSourceId) &&
                        !drawnSourceId.IsNull)
                    {
                        drawnSourceIds.Add(
                            drawnSourceId);
                    }
                }

                // FIX43: tuyệt đối không xóa toàn bộ line đã quét.
                // Chỉ xóa đúng line nguồn đã tạo được nét SHOP.
                int erasedSourceCount =
                    EraseShopSourceCurves(
                        tr,
                        drawnSourceIds);

                tr.Commit();

                try
                {
                    ed.Regen();
                }
                catch
                {
                }

                ed.WriteMessage(
                    $"\n[{ShopSmartBuild}] CTN PPR: " +
                    $"đã vẽ {edgeCount} nét SHOP cho {shopPipes.Count} đoạn; " +
                    $"nhận {deviceInstances.Count} block con; " +
                    $"học {learnedDeviceSizes.Count} mẫu thiết bị; " +
                    $"gán size theo thiết bị cho {deviceMatchedPipeCount} nhánh; " +
                    $"giữ {preservedDeviceBranchCount} nhánh thiết bị chưa đủ mẫu; " +
                    $"kế thừa size cho {inheritedPipeCount} nhánh ngắn; " +
                    $"phụ kiện={fittingCount} " +
                    $"(giảm {reducerCount}, co90 {elbow90Count}, " +
                    $"lơi45 {elbow45Count}, tê {teeCount}); " +
                    $"xóa {erasedSourceCount} nét gốc. " +
                    $"Giữ nguyên {Math.Max(0, sourceIdByCurve.Count - erasedSourceCount)} line chưa vẽ SHOP. " +
                    $"Khoảng cách 2 nét = đúng Ø ngoài PPR.");

                if (fittingCount == 0)
                {
                    ed.WriteMessage(
                        "\n[CTN SHOP PPR] Không có phụ kiện được chèn. " +
                        "Nếu tuyến có Co/Tê/Giảm mà vẫn =0, kiểm tra Command Line " +
                        "để xem tên block PPR được tìm thấy hay chưa.");
                }
            }
        }


        private void BtnVeShopThuCongCTN_Click(
            object sender,
            RoutedEventArgs e)
        {
            PipeUiContext ctx = _ctxCTN ?? GetContext(sender);

            string selectedSize =
                GetSelectedPipeSizeName(ctx);

            string material =
                GetSelectedPipeMaterialName(ctx);

            if (string.IsNullOrWhiteSpace(selectedSize))
            {
                MessageBox.Show(
                    "Hãy chọn SIZE ống CTN trước khi bấm VẼ SHOP.",
                    "VẼ SHOP CTN");
                return;
            }

            if (!TryGetCtnManualShopSize(
                    material,
                    selectedSize,
                    out string shopSize,
                    out double outsideDiameter))
            {
                MessageBox.Show(
                    "Không nhận được kích thước SHOP từ SIZE đang chọn: " +
                    selectedSize,
                    "VẼ SHOP CTN");
                return;
            }

            Document doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            Editor ed = doc.Editor;
            Database db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            List<Tuple<Point3d, Point3d>> spans =
                PromptManualShopSpans(
                    ed,
                    "VẼ SHOP CTN");

            if (spans == null || spans.Count == 0)
                return;

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                BlockTable bt =
                    (BlockTable)tr.GetObject(
                        db.BlockTableId,
                        OpenMode.ForRead);

                BlockTableRecord btr =
                    (BlockTableRecord)tr.GetObject(
                        bt[BlockTableRecord.ModelSpace],
                        OpenMode.ForWrite);

                List<Line> temporaryLines =
                    new List<Line>();

                List<ShopPipeCandidate> newPipes =
                    new List<ShopPipeCandidate>();

                try
                {
                    foreach (Tuple<Point3d, Point3d> span in spans)
                    {
                        Line center =
                            new Line(
                                span.Item1,
                                span.Item2);

                        temporaryLines.Add(center);

                        ShopPipeCandidate pipe =
                            CreateCtnManualShopPipeCandidate(
                                center,
                                material,
                                shopSize,
                                outsideDiameter);

                        if (pipe != null)
                            newPipes.Add(pipe);
                    }

                    if (newPipes.Count == 0)
                    {
                        MessageBox.Show(
                            "Không tạo được đoạn SHOP CTN hợp lệ.",
                            "VẼ SHOP CTN");
                        return;
                    }

                    List<ShopPipeCandidate> oldPipes =
                        CollectConnectedCtnManualShopPipes(
                            tr,
                            btr,
                            material,
                            newPipes);

                    List<ShopPipeCandidate> topologyPipes =
                        new List<ShopPipeCandidate>();

                    topologyPipes.AddRange(oldPipes);
                    topologyPipes.AddRange(newPipes);

                    string libraryPath =
                        FindShopFittingLibraryPath(
                            material,
                            db);

                    if (string.IsNullOrWhiteSpace(libraryPath))
                    {
                        ed.WriteMessage(
                            "\n[VẼ SHOP CTN] Không tìm thấy thư viện phụ kiện cho [" +
                            material +
                            "]. Tool vẫn vẽ ống nhưng chưa thể chèn phụ kiện.");
                    }

                    List<ShopFittingGapInfo> fittingGaps =
                        new List<ShopFittingGapInfo>();

                    int reducerCount;
                    int elbow90Count;
                    int elbow45Count;
                    int teeCount;
                    int sprinklerElbowCount;

                    int fittingCount =
                        DrawSmartShopFittings(
                            tr,
                            db,
                            btr,
                            topologyPipes,
                            new List<Point3d>(),
                            libraryPath,
                            fittingGaps,
                            out reducerCount,
                            out elbow90Count,
                            out elbow45Count,
                            out teeCount,
                            out sprinklerElbowCount);

                    // Chỉ mở khe tại phụ kiện trên tuyến cũ, không xóa tuyến cũ.
                    TrimExistingManualShopEdges(
                        tr,
                        db,
                        btr,
                        oldPipes,
                        fittingGaps);

                    int drawnCount = 0;

                    foreach (ShopPipeCandidate pipe in newPipes)
                    {
                        EnsureShopLayerExists(
                            tr,
                            db,
                            pipe.LayerName);

                        drawnCount +=
                            DrawShopParallelPipeWithGaps(
                                tr,
                                db,
                                btr,
                                pipe,
                                fittingGaps);

                        AppendManualShopSourceLine(
                            tr,
                            db,
                            btr,
                            pipe.Start,
                            pipe.End,
                            material,
                            pipe.SizeText);
                    }

                    tr.Commit();

                    try { ed.Regen(); }
                    catch { }

                    ed.WriteMessage(
                        "\n[VẼ SHOP CTN] Hoàn tất " +
                        newPipes.Count +
                        " đoạn, " +
                        drawnCount +
                        " nét; phụ kiện=" + fittingCount +
                        " (giảm " + reducerCount +
                        ", co90 " + elbow90Count +
                        ", co45 " + elbow45Count +
                        ", tê/tê giảm " + teeCount +
                        "). Size SHOP=" + shopSize +
                        ", Ø ngoài=" + outsideDiameter.ToString("0.##") +
                        " mm.");
                }
                finally
                {
                    foreach (Line line in temporaryLines)
                    {
                        try { line.Dispose(); }
                        catch { }
                    }
                }
            }
        }

        private List<Tuple<Point3d, Point3d>> PromptManualShopSpans(
            Editor ed,
            string title)
        {
            if (ed == null)
                return null;

            List<Tuple<Point3d, Point3d>> spans =
                new List<Tuple<Point3d, Point3d>>();

            PromptPointResult firstResult =
                ed.GetPoint(
                    "\n[" + title + "] Chọn điểm đầu tim ống: ");

            if (firstResult.Status != PromptStatus.OK)
                return null;

            Point3d current = firstResult.Value;

            while (true)
            {
                PromptPointOptions options =
                    new PromptPointOptions(
                        "\n[" + title + "] Chọn điểm tiếp theo hoặc Enter để kết thúc: ")
                    {
                        UseBasePoint = true,
                        BasePoint = current,
                        AllowNone = true
                    };

                PromptPointResult result =
                    ed.GetPoint(options);

                if (result.Status == PromptStatus.None)
                    break;

                if (result.Status != PromptStatus.OK)
                    return null;

                Point3d next = result.Value;

                if (PlanDistance(current, next) < 5.0)
                {
                    ed.WriteMessage(
                        "\n[" + title + "] Đoạn quá ngắn, hãy chọn điểm khác.");
                    continue;
                }

                spans.Add(
                    Tuple.Create(current, next));

                current = next;
            }

            return spans;
        }

        private bool TryGetCtnManualShopSize(
            string material,
            string sourceText,
            out string sizeText,
            out double outsideDiameter)
        {
            sizeText = "";
            outsideDiameter = 0.0;

            string materialKey =
                NormalizeShopKey(material ?? "");

            if (materialKey.Contains("PPR"))
            {
                return TryParseCtnPprShopSize(
                    sourceText,
                    out sizeText,
                    out outsideDiameter);
            }

            // uPVC và HDPE có thể đã ghi trực tiếp đường kính ngoài D/Ø.
            Match outsideMatch =
                Regex.Match(
                    NormalizePipeLabel(sourceText ?? "")
                        .Replace(',', '.')
                        .ToUpperInvariant(),
                    @"(?<![A-Z0-9])(?:D|Ø|Φ)\s*(?<SIZE>\d{1,4}(?:\.\d+)?)(?:\s*MM)?(?![A-Z0-9])",
                    RegexOptions.IgnoreCase);

            if ((materialKey.Contains("UPVC") ||
                 materialKey.Contains("PVC") ||
                 materialKey.Contains("HDPE")) &&
                outsideMatch.Success &&
                double.TryParse(
                    outsideMatch.Groups["SIZE"].Value,
                    NumberStyles.AllowDecimalPoint,
                    CultureInfo.InvariantCulture,
                    out double explicitOutside) &&
                explicitOutside > 0.0)
            {
                outsideDiameter = explicitOutside;
                sizeText =
                    "D" +
                    FormatShopDnNumber(explicitOutside);
                return true;
            }

            if (!TryParseAutomaticPipeSize(
                    _ctxCTN,
                    sourceText,
                    out string nominalSizeText,
                    out double nominalDn))
            {
                return false;
            }

            if (materialKey.Contains("UPVC") ||
                materialKey.Contains("PVC"))
            {
                outsideDiameter =
                    MapCtnUpvcNominalToOutside(
                        nominalDn);

                sizeText =
                    "D" +
                    FormatShopDnNumber(
                        outsideDiameter);

                return outsideDiameter > 0.0;
            }

            if (materialKey.Contains("HDPE"))
            {
                outsideDiameter = nominalDn;
                sizeText =
                    "D" +
                    FormatShopDnNumber(
                        outsideDiameter);

                return outsideDiameter > 0.0;
            }

            // Tráng kẽm / nhúng nóng / inox: dùng đúng Ø ngoài ống kim loại.
            outsideDiameter =
                GetFireSteelOutsideDiameterForSize(
                    nominalSizeText,
                    nominalDn);

            sizeText = nominalSizeText;

            return outsideDiameter > 0.0;
        }

        private static double MapCtnUpvcNominalToOutside(
            double nominalDn)
        {
            double[][] map =
                new double[][]
                {
                    new double[] { 15, 21 },
                    new double[] { 20, 27 },
                    new double[] { 25, 34 },
                    new double[] { 32, 42 },
                    new double[] { 40, 49 },
                    new double[] { 50, 60 },
                    new double[] { 65, 75 },
                    new double[] { 80, 90 },
                    new double[] { 100, 110 },
                    new double[] { 125, 140 },
                    new double[] { 150, 168 },
                    new double[] { 200, 220 },
                    new double[] { 250, 250 },
                    new double[] { 300, 315 }
                };

            foreach (double[] row in map)
            {
                if (Math.Abs(row[0] - nominalDn) <= 0.01)
                    return row[1];
            }

            return nominalDn;
        }

        private ShopPipeCandidate CreateCtnManualShopPipeCandidate(
            Curve curve,
            string material,
            string sizeText,
            double outsideDiameter)
        {
            if (curve == null ||
                string.IsNullOrWhiteSpace(sizeText) ||
                outsideDiameter <= 0.0)
            {
                return null;
            }

            try
            {
                Point3d start = curve.StartPoint;
                Point3d end = curve.EndPoint;

                Vector3d startDir =
                    GetShopCurveDirection(curve, true);

                Vector3d endDir =
                    GetShopCurveDirection(curve, false);

                if (startDir.Length < 1e-9 ||
                    endDir.Length < 1e-9)
                {
                    return null;
                }

                Vector3d startNormal =
                    GetPlanNormal(startDir);

                Vector3d endNormal =
                    GetPlanNormal(endDir);

                double half = outsideDiameter / 2.0;

                string materialToken =
                    CleanLayerText(material ?? "ONG")
                        .Replace(" ", "_");

                string layerName =
                    "CTN_SHOP_" +
                    materialToken +
                    "_" +
                    CleanLayerText(sizeText);

                return new ShopPipeCandidate
                {
                    Curve = curve,
                    SizeText = sizeText,
                    Width = outsideDiameter,
                    LayerName = layerName,
                    Start = start,
                    End = end,
                    StartLeft = start + startNormal * half,
                    StartRight = start - startNormal * half,
                    EndLeft = end + endNormal * half,
                    EndRight = end - endNormal * half
                };
            }
            catch
            {
                return null;
            }
        }

        private List<ShopPipeCandidate> CollectConnectedCtnManualShopPipes(
            Transaction tr,
            BlockTableRecord btr,
            string material,
            List<ShopPipeCandidate> newPipes)
        {
            List<ShopPipeCandidate> sourceCandidates =
                new List<ShopPipeCandidate>();

            List<ShopPipeCandidate> centerlineCandidates =
                new List<ShopPipeCandidate>();

            if (tr == null || btr == null ||
                newPipes == null || newPipes.Count == 0)
            {
                return sourceCandidates;
            }

            string materialKey =
                NormalizeShopKey(material ?? "");

            foreach (ObjectId id in btr.Cast<ObjectId>().ToList())
            {
                Line line =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Line;

                if (line == null || line.IsErased)
                    continue;

                string layer = line.Layer ?? "";

                bool isManualSource =
                    layer.StartsWith(
                        "TDL_MSHOP_SRC_",
                        StringComparison.OrdinalIgnoreCase);

                bool isCtnCenterline =
                    layer.StartsWith(
                        "CTN_SHOP_TAM_",
                        StringComparison.OrdinalIgnoreCase);

                if (!isManualSource && !isCtnCenterline)
                    continue;

                string layerKey =
                    NormalizeShopKey(layer);

                if (!string.IsNullOrWhiteSpace(materialKey) &&
                    !layerKey.Contains(materialKey))
                {
                    continue;
                }

                if (!TryGetCtnManualShopSize(
                        material,
                        layer,
                        out string sizeText,
                        out double outsideD))
                {
                    continue;
                }

                ShopPipeCandidate candidate =
                    CreateCtnManualShopPipeCandidate(
                        line,
                        material,
                        sizeText,
                        outsideD);

                if (candidate == null ||
                    !newPipes.Any(
                        pipe => ManualShopPipesTouch(
                            pipe,
                            candidate)))
                {
                    continue;
                }

                if (isManualSource)
                    sourceCandidates.Add(candidate);
                else
                    centerlineCandidates.Add(candidate);
            }

            foreach (ShopPipeCandidate center in centerlineCandidates)
            {
                if (sourceCandidates.Any(
                        source => ManualShopPipesOverlap(
                            source,
                            center)))
                {
                    continue;
                }

                sourceCandidates.Add(center);
            }

            return sourceCandidates;
        }

        // VẼ SHOP THỦ CÔNG:
        // Người dùng chỉ điểm theo TIM ống. Tool tự vẽ hai biên + tim nét đứt,
        // đồng thời đưa các tuyến SHOP cũ lân cận vào cùng đồ thị nút để chèn
        // Co, Nối giảm, Tê hoặc Tê giảm đúng ngay khi vẽ.
        private void BtnVeShopThuCong_Click(
            object sender,
            RoutedEventArgs e)
        {
            PipeUiContext ctx = GetContext(sender) ?? _ctxFF;

            string selectedSize =
                GetSelectedPipeSizeName(ctx);

            if (string.IsNullOrWhiteSpace(selectedSize))
            {
                MessageBox.Show(
                    "Hãy chọn SIZE ống trước khi bấm VẼ SHOP.",
                    "VẼ SHOP");
                return;
            }

            double selectedWidth;
            string normalizedSize;

            if (!TryParseAutomaticPipeSize(
                    ctx,
                    selectedSize,
                    out normalizedSize,
                    out selectedWidth))
            {
                normalizedSize = selectedSize.Trim();
                selectedWidth = LayWidthTuSize(selectedSize);
            }

            if (string.IsNullOrWhiteSpace(normalizedSize) ||
                selectedWidth <= 0.0)
            {
                MessageBox.Show(
                    "SIZE đang chọn không hợp lệ: " + selectedSize,
                    "VẼ SHOP");
                return;
            }

            Document doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            Editor ed = doc.Editor;
            Database db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            List<Tuple<Point3d, Point3d>> spans =
                new List<Tuple<Point3d, Point3d>>();

            PromptPointResult firstResult =
                ed.GetPoint(
                    "\n[VẼ SHOP] Chọn điểm đầu tim ống: ");

            if (firstResult.Status != PromptStatus.OK)
                return;

            Point3d current = firstResult.Value;

            while (true)
            {
                PromptPointOptions nextOptions =
                    new PromptPointOptions(
                        "\n[VẼ SHOP] Chọn điểm tiếp theo hoặc nhấn Enter để kết thúc: ");

                nextOptions.UseBasePoint = true;
                nextOptions.BasePoint = current;
                nextOptions.AllowNone = true;

                PromptPointResult nextResult =
                    ed.GetPoint(nextOptions);

                if (nextResult.Status == PromptStatus.None)
                    break;

                // ESC hủy toàn bộ lần vẽ hiện tại, không để lại đoạn dở dang.
                if (nextResult.Status != PromptStatus.OK)
                    return;

                Point3d next = nextResult.Value;

                if (PlanDistance(current, next) < 5.0)
                {
                    ed.WriteMessage(
                        "\n[VẼ SHOP] Đoạn quá ngắn, hãy chọn điểm khác.");
                    continue;
                }

                spans.Add(
                    Tuple.Create(current, next));

                current = next;
            }

            if (spans.Count == 0)
                return;

            string material =
                GetSelectedPipeMaterialName(ctx);

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                BlockTable bt =
                    (BlockTable)tr.GetObject(
                        db.BlockTableId,
                        OpenMode.ForRead);

                BlockTableRecord btr =
                    (BlockTableRecord)tr.GetObject(
                        bt[BlockTableRecord.ModelSpace],
                        OpenMode.ForWrite);

                List<Line> temporaryLines =
                    new List<Line>();

                List<ShopPipeCandidate> newPipes =
                    new List<ShopPipeCandidate>();

                try
                {
                    foreach (Tuple<Point3d, Point3d> span in spans)
                    {
                        Line center =
                            new Line(span.Item1, span.Item2);

                        temporaryLines.Add(center);

                        ShopPipeCandidate pipe =
                            CreateShopPipeCandidate(
                                center,
                                normalizedSize,
                                selectedWidth);

                        if (pipe != null)
                            newPipes.Add(pipe);
                    }

                    if (newPipes.Count == 0)
                    {
                        MessageBox.Show(
                            "Không tạo được đoạn SHOP hợp lệ.",
                            "VẼ SHOP");
                        return;
                    }

                    List<ShopPipeCandidate> oldPipes =
                        CollectConnectedManualShopPipes(
                            tr,
                            btr,
                            ctx,
                            material,
                            newPipes);

                    List<ShopPipeCandidate> topologyPipes =
                        new List<ShopPipeCandidate>();

                    topologyPipes.AddRange(oldPipes);
                    topologyPipes.AddRange(newPipes);

                    string shopLibraryPath =
                        FindShopFittingLibraryPath(
                            material,
                            db);

                    if (string.IsNullOrWhiteSpace(shopLibraryPath))
                    {
                        ed.WriteMessage(
                            "\n[VẼ SHOP] Không tìm thấy thư viện phụ kiện cho vật liệu [" +
                            material +
                            "]. Tool vẫn vẽ ống nhưng chưa thể chèn phụ kiện.");
                    }

                    List<ShopFittingGapInfo> fittingGaps =
                        new List<ShopFittingGapInfo>();

                    int reducerCount;
                    int elbow90Count;
                    int elbow45Count;
                    int teeCount;
                    int sprinklerElbowCount;

                    int fittingCount =
                        DrawSmartShopFittings(
                            tr,
                            db,
                            btr,
                            topologyPipes,
                            new List<Point3d>(),
                            shopLibraryPath,
                            fittingGaps,
                            out reducerCount,
                            out elbow90Count,
                            out elbow45Count,
                            out teeCount,
                            out sprinklerElbowCount);

                    // Tuyến cũ chỉ cắt đúng khe phụ kiện. Không xóa và không vẽ lại.
                    TrimExistingManualShopEdges(
                        tr,
                        db,
                        btr,
                        oldPipes,
                        fittingGaps);

                    int drawnCount = 0;

                    foreach (ShopPipeCandidate pipe in newPipes)
                    {
                        EnsureShopLayerExists(
                            tr,
                            db,
                            pipe.LayerName);

                        drawnCount +=
                            DrawShopParallelPipeWithGaps(
                                tr,
                                db,
                                btr,
                                pipe,
                                fittingGaps);

                        AppendManualShopSourceLine(
                            tr,
                            db,
                            btr,
                            pipe.Start,
                            pipe.End,
                            material,
                            pipe.SizeText);
                    }

                    tr.Commit();

                    try { ed.Regen(); }
                    catch { }

                    ed.WriteMessage(
                        "\n[VẼ SHOP] Hoàn tất " +
                        newPipes.Count +
                        " đoạn, " +
                        drawnCount +
                        " nét; phụ kiện=" +
                        fittingCount +
                        " (giảm " + reducerCount +
                        ", co90 " + elbow90Count +
                        ", co45 " + elbow45Count +
                        ", tê/tê giảm " + teeCount +
                        ").");
                }
                finally
                {
                    foreach (Line line in temporaryLines)
                    {
                        try { line.Dispose(); }
                        catch { }
                    }
                }
            }
        }

        private List<ShopPipeCandidate> CollectConnectedManualShopPipes(
            Transaction tr,
            BlockTableRecord btr,
            PipeUiContext ctx,
            string material,
            List<ShopPipeCandidate> newPipes)
        {
            List<ShopPipeCandidate> sourceCandidates =
                new List<ShopPipeCandidate>();

            List<ShopPipeCandidate> centerlineCandidates =
                new List<ShopPipeCandidate>();

            if (tr == null || btr == null ||
                newPipes == null || newPipes.Count == 0)
            {
                return sourceCandidates;
            }

            string materialKey =
                NormalizeShopKey(material ?? "");

            List<ObjectId> ids =
                btr.Cast<ObjectId>().ToList();

            foreach (ObjectId id in ids)
            {
                Line line =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Line;

                if (line == null || line.IsErased)
                    continue;

                string layer = line.Layer ?? "";

                bool isManualSource =
                    layer.StartsWith(
                        "TDL_MSHOP_SRC_",
                        StringComparison.OrdinalIgnoreCase);

                bool isShopCenterline =
                    layer.StartsWith(
                        "FF_SHOP_TAM_",
                        StringComparison.OrdinalIgnoreCase);

                if (!isManualSource && !isShopCenterline)
                    continue;

                if (isManualSource &&
                    !string.IsNullOrWhiteSpace(materialKey) &&
                    !NormalizeShopKey(layer).Contains(materialKey))
                {
                    continue;
                }

                if (!TryParseAutomaticPipeSize(
                        ctx,
                        layer,
                        out string sizeText,
                        out double width))
                {
                    continue;
                }

                ShopPipeCandidate candidate =
                    CreateShopPipeCandidate(
                        line,
                        sizeText,
                        width);

                if (candidate == null ||
                    !newPipes.Any(
                        p => ManualShopPipesTouch(p, candidate)))
                {
                    continue;
                }

                if (isManualSource)
                    sourceCandidates.Add(candidate);
                else
                    centerlineCandidates.Add(candidate);
            }

            // Với tuyến do chính chức năng này tạo, đường nguồn ẩn là chuẩn nhất.
            // Bỏ tâm nét đứt trùng tuyến nguồn để không tạo thừa arm tại nút.
            foreach (ShopPipeCandidate center in centerlineCandidates)
            {
                if (sourceCandidates.Any(
                        source => ManualShopPipesOverlap(
                            source,
                            center)))
                {
                    continue;
                }

                sourceCandidates.Add(center);
            }

            return sourceCandidates;
        }

        private bool ManualShopPipesTouch(
            ShopPipeCandidate a,
            ShopPipeCandidate b)
        {
            if (a == null || b == null)
                return false;

            double tolerance =
                Math.Max(
                    ShopJointTolerance,
                    Math.Max(a.Width, b.Width) * 1.5);

            if (PlanDistance(a.Start, b.Start) <= tolerance ||
                PlanDistance(a.Start, b.End) <= tolerance ||
                PlanDistance(a.End, b.Start) <= tolerance ||
                PlanDistance(a.End, b.End) <= tolerance)
            {
                return true;
            }

            List<ShopPipeLeg> legs =
                BuildShopPipeLegs(
                    new[] { a, b });

            List<ShopPipeLeg> aLegs =
                legs.Where(l => ReferenceEquals(l.Pipe, a)).ToList();

            List<ShopPipeLeg> bLegs =
                legs.Where(l => ReferenceEquals(l.Pipe, b)).ToList();

            foreach (ShopPipeLeg la in aLegs)
            {
                foreach (ShopPipeLeg lb in bLegs)
                {
                    if (TryGetShopSegmentIntersection(
                            la,
                            lb,
                            out Point3d _))
                    {
                        return true;
                    }

                    if (ManualShopPointTouchesLeg(
                            la.Start,
                            lb,
                            tolerance) ||
                        ManualShopPointTouchesLeg(
                            la.End,
                            lb,
                            tolerance) ||
                        ManualShopPointTouchesLeg(
                            lb.Start,
                            la,
                            tolerance) ||
                        ManualShopPointTouchesLeg(
                            lb.End,
                            la,
                            tolerance))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool ManualShopPointTouchesLeg(
            Point3d point,
            ShopPipeLeg leg,
            double tolerance)
        {
            if (leg == null || !leg.IsStraight)
                return false;

            if (!TryProjectShopPointToSegment(
                    point,
                    leg.Start,
                    leg.End,
                    out Point3d _,
                    out double t,
                    out double distance))
            {
                return false;
            }

            double length =
                Math.Max(
                    PlanDistance(leg.Start, leg.End),
                    1.0);

            double extension = tolerance / length;

            return distance <= tolerance &&
                t >= -extension &&
                t <= 1.0 + extension;
        }

        private bool ManualShopPipesOverlap(
            ShopPipeCandidate a,
            ShopPipeCandidate b)
        {
            if (a == null || b == null)
                return false;

            if (!string.Equals(
                    CleanLayerText(a.SizeText ?? ""),
                    CleanLayerText(b.SizeText ?? ""),
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3d da = a.End - a.Start;
            Vector3d db = b.End - b.Start;

            if (da.Length < 1e-6 || db.Length < 1e-6)
                return false;

            double angle =
                GetShopAngleDegrees(
                    da,
                    db);

            double axisError =
                Math.Min(
                    angle,
                    Math.Abs(180.0 - angle));

            if (axisError > ShopStraightAngleToleranceDeg)
                return false;

            Point3d middle =
                new Point3d(
                    (b.Start.X + b.End.X) / 2.0,
                    (b.Start.Y + b.End.Y) / 2.0,
                    (b.Start.Z + b.End.Z) / 2.0);

            return ManualShopPointTouchesLeg(
                middle,
                BuildShopPipeLegs(new[] { a }).FirstOrDefault(),
                Math.Max(ShopJointTolerance, a.Width));
        }

        private void AppendManualShopSourceLine(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d start,
            Point3d end,
            string material,
            string sizeText)
        {
            if (start.DistanceTo(end) < 1.0)
                return;

            string layerName =
                "TDL_MSHOP_SRC_" +
                CleanLayerText(material ?? "ONG") +
                "_" +
                CleanLayerText(sizeText ?? "DN");

            EnsureLayerExists(
                tr,
                db,
                layerName,
                false);

            try
            {
                LayerTable lt =
                    (LayerTable)tr.GetObject(
                        db.LayerTableId,
                        OpenMode.ForRead);

                if (lt.Has(layerName))
                {
                    LayerTableRecord layer =
                        (LayerTableRecord)tr.GetObject(
                            lt[layerName],
                            OpenMode.ForWrite);

                    layer.IsPlottable = false;
                    layer.IsLocked = false;
                }
            }
            catch { }

            Line source = new Line(start, end);
            source.SetDatabaseDefaults(db);
            source.Layer = layerName;
            source.Visible = false;
            source.Color =
                Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                    ColorMethod.ByAci,
                    8);

            btr.AppendEntity(source);
            tr.AddNewlyCreatedDBObject(source, true);
        }

        private void TrimExistingManualShopEdges(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            List<ShopPipeCandidate> oldPipes,
            List<ShopFittingGapInfo> fittingGaps)
        {
            if (tr == null || db == null || btr == null ||
                oldPipes == null || oldPipes.Count == 0 ||
                fittingGaps == null || fittingGaps.Count == 0)
            {
                return;
            }

            foreach (ShopPipeCandidate pipe in oldPipes)
            {
                if (pipe == null ||
                    string.IsNullOrWhiteSpace(pipe.LayerName))
                {
                    continue;
                }

                Vector3d pipeDirection =
                    pipe.End - pipe.Start;

                if (pipeDirection.Length < 1e-6)
                    continue;

                foreach (ShopFittingGapInfo gap in fittingGaps)
                {
                    if (!ShopFittingGapAppliesToPipe(
                            gap,
                            pipe,
                            pipeDirection))
                    {
                        continue;
                    }

                    List<ObjectId> ids =
                        btr.Cast<ObjectId>().ToList();

                    foreach (ObjectId id in ids)
                    {
                        Line edge =
                            tr.GetObject(
                                id,
                                OpenMode.ForRead,
                                false) as Line;

                        if (edge == null || edge.IsErased ||
                            !string.Equals(
                                edge.Layer,
                                pipe.LayerName,
                                StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }

                        TrimManualShopEdgeAtGap(
                            tr,
                            db,
                            btr,
                            edge,
                            pipe,
                            gap);
                    }
                }
            }
        }

        private void TrimManualShopEdgeAtGap(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Line edge,
            ShopPipeCandidate pipe,
            ShopFittingGapInfo gap)
        {
            if (edge == null || pipe == null || gap == null ||
                gap.HalfLength <= 1.0)
            {
                return;
            }

            Vector3d edgeDirection =
                edge.EndPoint - edge.StartPoint;

            double edgeLength = edgeDirection.Length;

            if (edgeLength < 1e-6)
                return;

            edgeDirection = edgeDirection.GetNormal();

            Vector3d pipeDirection =
                pipe.End - pipe.Start;

            double axisAngle =
                GetShopAngleDegrees(
                    edgeDirection,
                    pipeDirection);

            double axisError =
                Math.Min(
                    axisAngle,
                    Math.Abs(180.0 - axisAngle));

            if (axisError > ShopStraightAngleToleranceDeg)
                return;

            Vector3d toJoint =
                gap.Joint - edge.StartPoint;

            double along =
                toJoint.DotProduct(edgeDirection);

            double reach =
                Math.Max(
                    ShopJointTolerance,
                    pipe.Width * 2.0);

            if (along < -reach ||
                along > edgeLength + reach)
            {
                return;
            }

            double clampedAlong =
                Math.Max(
                    0.0,
                    Math.Min(edgeLength, along));

            Point3d projected =
                edge.StartPoint +
                edgeDirection * clampedAlong;

            if (PlanDistance(projected, gap.Joint) > reach)
                return;

            double cutStart =
                Math.Max(
                    0.0,
                    along - gap.HalfLength);

            double cutEnd =
                Math.Min(
                    edgeLength,
                    along + gap.HalfLength);

            if (cutEnd - cutStart < 1.0)
                return;

            edge.UpgradeOpen();

            Point3d originalStart = edge.StartPoint;
            Point3d originalEnd = edge.EndPoint;

            if (cutStart <= 1.0 &&
                cutEnd >= edgeLength - 1.0)
            {
                edge.Erase();
                return;
            }

            if (cutStart <= 1.0)
            {
                edge.StartPoint =
                    originalStart +
                    edgeDirection * cutEnd;
                return;
            }

            if (cutEnd >= edgeLength - 1.0)
            {
                edge.EndPoint =
                    originalStart +
                    edgeDirection * cutStart;
                return;
            }

            Point3d firstEnd =
                originalStart +
                edgeDirection * cutStart;

            Point3d secondStart =
                originalStart +
                edgeDirection * cutEnd;

            edge.EndPoint = firstEnd;

            Line second =
                new Line(secondStart, originalEnd);

            second.SetDatabaseDefaults(db);
            second.Layer = edge.Layer;
            second.Color = edge.Color;
            second.LineWeight = edge.LineWeight;
            second.Transparency = edge.Transparency;
            second.Visible = edge.Visible;

            try
            {
                second.LinetypeId = edge.LinetypeId;
                second.LinetypeScale = edge.LinetypeScale;
            }
            catch { }

            btr.AppendEntity(second);
            tr.AddNewlyCreatedDBObject(second, true);
        }

        private void BtnVeShopOngChuaChay_Click(
            object sender,
            RoutedEventArgs e)
        {
            PipeUiContext ctx = GetContext(sender) ?? _ctxFF;

            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var ed = doc.Editor;
            var db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            PromptSelectionOptions pso =
                new PromptSelectionOptions();

            pso.MessageForAdding =
                "\n[VẼ SHOP ỐNG] Quét chọn line/polyline tuyến ống và chữ DN: ";

            TypedValue[] tvs =
                new TypedValue[]
                {
                    new TypedValue((int)DxfCode.Operator, "<OR"),
                    new TypedValue((int)DxfCode.Start, "LINE"),
                    new TypedValue((int)DxfCode.Start, "LWPOLYLINE"),
                    new TypedValue((int)DxfCode.Start, "POLYLINE"),
                    new TypedValue((int)DxfCode.Start, "ARC"),
                    new TypedValue((int)DxfCode.Start, "TEXT"),
                    new TypedValue((int)DxfCode.Start, "MTEXT"),
                    new TypedValue((int)DxfCode.Start, "INSERT"),
                    new TypedValue((int)DxfCode.Operator, "OR>")
                };

            PromptSelectionResult psr =
                ed.GetSelection(
                    pso,
                    new SelectionFilter(tvs));

            if (psr.Status != PromptStatus.OK ||
                psr.Value == null ||
                psr.Value.Count == 0)
                return;

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                BlockTableRecord btr =
                    (BlockTableRecord)tr.GetObject(
                        db.CurrentSpaceId,
                        OpenMode.ForWrite);

                List<Curve> curves =
                    new List<Curve>();
                List<ObjectId> sourceCurveIds =
                    new List<ObjectId>();
                List<TextData> texts =
                    new List<TextData>();
                List<Point3d> sprinklerCenters =
                    new List<Point3d>();

                foreach (SelectedObject so in psr.Value)
                {
                    if (so == null || so.ObjectId.IsNull)
                        continue;

                    Entity ent =
                        tr.GetObject(
                            so.ObjectId,
                            OpenMode.ForRead) as Entity;

                    if (ent == null)
                        continue;

                    if ((ent is Line ||
                         ent is Polyline ||
                         ent is Polyline2d ||
                         ent is Polyline3d ||
                         ent is Arc) &&
                        ent is Curve curveEnt)
                    {
                        curves.Add(curveEnt);
                        sourceCurveIds.Add(so.ObjectId);
                    }
                    else if (ent is DBText dbText)
                    {
                        Point3d pt =
                            (dbText.Justify !=
                                AttachmentPoint.BaseLeft &&
                             (dbText.AlignmentPoint.X != 0 ||
                              dbText.AlignmentPoint.Y != 0))
                                ? dbText.AlignmentPoint
                                : dbText.Position;

                        TryAddShopPipeSizeText(
                            ctx,
                            dbText.TextString,
                            pt,
                            dbText.Rotation,
                            texts);
                    }
                    else if (ent is MText mText)
                    {
                        TryAddShopPipeSizeText(
                            ctx,
                            mText.Text,
                            mText.Location,
                            mText.Rotation,
                            texts);
                    }
                    else if (ent is BlockReference blockRef)
                    {
                        // Lấy tâm hình tròn trong block để nhận biết đầu phun.
                        // Chỉ dùng các tâm này cho đầu tuyến hở, nên không ảnh hưởng
                        // các nút co/tê/giảm bình thường.
                        foreach (Point3d center in
                            GetCircularCentersFromBlock(tr, blockRef))
                        {
                            AddUniquePoint(
                                sprinklerCenters,
                                center,
                                5.0);
                        }

                        if (IsLikelyShopSprinklerBlock(tr, blockRef))
                        {
                            AddUniquePoint(
                                sprinklerCenters,
                                blockRef.Position,
                                5.0);
                        }

                        foreach (ObjectId attId
                            in blockRef.AttributeCollection)
                        {
                            AttributeReference att =
                                tr.GetObject(
                                    attId,
                                    OpenMode.ForRead)
                                    as AttributeReference;

                            if (att == null)
                                continue;

                            TryAddShopPipeSizeText(
                                ctx,
                                att.TextString,
                                att.Position,
                                att.Rotation,
                                texts);
                        }
                    }
                }

                if (curves.Count == 0)
                {
                    MessageBox.Show(
                        "Phải quét trúng ít nhất 1 line/polyline tuyến ống.",
                        "VẼ SHOP ỐNG");
                    return;
                }

                Dictionary<Curve, List<TextProjectionData>>
                    textMap =
                        MapTextsToOriginalCurves(
                            curves,
                            texts);

                List<ShopPipeCandidate> shopPipes =
                    new List<ShopPipeCandidate>();

                foreach (Curve curve in curves)
                {
                    string sizeText = "";
                    double width = 0.0;
                    List<TextProjectionData> projections = null;

                    if (textMap.TryGetValue(
                            curve,
                            out projections) &&
                        projections.Count > 0)
                    {
                        List<ShopPipeCandidate> splitCandidates =
                            CreateShopSplitCandidatesFromTexts(
                                curve,
                                projections);

                        if (splitCandidates.Count > 0)
                        {
                            shopPipes.AddRange(splitCandidates);
                            continue;
                        }

                        TextProjectionData best =
                            projections
                                .OrderBy(x => x.MatchScore)
                                .ThenBy(x => x.DistanceAlongCurve)
                                .First();

                        sizeText = best.Text.TextString;
                        width = best.Text.Width;
                    }

                    if (string.IsNullOrWhiteSpace(sizeText) &&
                        TryParseAutomaticPipeSize(
                            ctx,
                            curve.Layer,
                            out string layerSize,
                            out double layerWidth))
                    {
                        sizeText = layerSize;
                        width = layerWidth;
                    }

                    if (string.IsNullOrWhiteSpace(sizeText) ||
                        width <= 0.0)
                        continue;

                    ShopPipeCandidate candidate =
                        CreateShopPipeCandidate(
                            curve,
                            sizeText,
                            width);

                    if (candidate != null)
                        shopPipes.Add(candidate);
                }

                if (shopPipes.Count == 0)
                {
                    MessageBox.Show(
                        "Không nhận được DN nào. Hãy quét thêm chữ DN gần tuyến ống hoặc layer có DN.",
                        "VẼ SHOP ỐNG");
                    return;
                }

                string shopMaterial =
                    InferShopMaterialFromPipes(
                        shopPipes,
                        GetSelectedPipeMaterialName(ctx));

                string shopLibraryPath =
                    FindShopFittingLibraryPath(
                        shopMaterial,
                        db);

                if (string.IsNullOrWhiteSpace(
                        shopLibraryPath))
                {
                    ed.WriteMessage(
                        "\n[SHOP-LIB] Không tìm thấy file thư viện cho vật liệu [" +
                        shopMaterial +
                        "]. SHOP sẽ không tự chèn block thư viện.");
                }
                else
                {
                    ed.WriteMessage(
                        "\n[SHOP-LIB] Đang dùng đúng file: " +
                        Path.GetFileName(
                            shopLibraryPath));
                }

                // 1) Chèn phụ kiện TRƯỚC → đo nửa chiều dài block tại mỗi nút
                // 2) Vẽ ống 2 nét song song + tâm nét đứt, đầu ống CHẠM mặt phụ kiện
                List<ShopFittingGapInfo> fittingGaps =
                    new List<ShopFittingGapInfo>();

                int reducerCount;
                int elbow90Count;
                int elbow45Count;
                int teeCount;
                int sprinklerElbowCount;

                int fittingCount =
                    DrawSmartShopFittings(
                        tr,
                        db,
                        btr,
                        shopPipes,
                        sprinklerCenters,
                        shopLibraryPath,
                        fittingGaps,
                        out reducerCount,
                        out elbow90Count,
                        out elbow45Count,
                        out teeCount,
                        out sprinklerElbowCount);

                int edgeCount = 0;

                foreach (ShopPipeCandidate pipe in shopPipes)
                {
                    EnsureShopLayerExists(
                        tr,
                        db,
                        pipe.LayerName);

                    edgeCount += DrawShopParallelPipeWithGaps(
                        tr,
                        db,
                        btr,
                        pipe,
                        fittingGaps);
                }

                int erasedSourceCount =
                    EraseShopSourceCurves(
                        tr,
                        sourceCurveIds);

                tr.Commit();

                try
                {
                    ed.Regen();
                }
                catch { }

                ed.WriteMessage(
                    $"\n[{ShopSmartBuild}] Đã vẽ {edgeCount} nét (2 song song + tâm nét đứt) cho {shopPipes.Count} tuyến; " +
                    $"phụ kiện thư viện: {fittingCount} (giảm {reducerCount}, co90 {elbow90Count}, " +
                    $"co lơi 45 {elbow45Count}, tê {teeCount}, co90 đầu phun {sprinklerElbowCount}); " +
                    $"xóa {erasedSourceCount} nét gốc. " +
                    $"Khoảng cách 2 nét SHOP = Ø ngoài theo bảng thép.");

                if (fittingCount == 0 &&
                    !string.IsNullOrWhiteSpace(shopLibraryPath))
                {
                    ed.WriteMessage(
                        "\n[SHOP] Không chèn được block phụ kiện từ thư viện. " +
                        "Kiểm tra tên block trong file (CO90/TE/REDUCER + DN) " +
                        "hoặc gửi danh sách tên block để map lại.");
                }
                else if (string.IsNullOrWhiteSpace(shopLibraryPath))
                {
                    ed.WriteMessage(
                        "\n[SHOP] Chưa tìm thấy file thư viện trong thư mục DLL. " +
                        "Cần: Thu vien STEEL.dwg / Thu vien uPVC.dwg / Thu vien PPR.dwg");
                }
            }
        }

        private bool IsShopNodeInsideOccupiedBlock(
            Point3d nodePoint,
            List<Extents3d> occupiedBlockExtents)
        {
            if (occupiedBlockExtents == null ||
                occupiedBlockExtents.Count == 0)
            {
                return false;
            }

            const double tolerance = 5.0;

            foreach (Extents3d ext
                in occupiedBlockExtents)
            {
                if (nodePoint.X >= ext.MinPoint.X - tolerance &&
                    nodePoint.X <= ext.MaxPoint.X + tolerance &&
                    nodePoint.Y >= ext.MinPoint.Y - tolerance &&
                    nodePoint.Y <= ext.MaxPoint.Y + tolerance)
                {
                    return true;
                }
            }

            return false;
        }

        private int DrawSmartShopFittings(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            List<ShopPipeCandidate> shopPipes,
            List<Point3d> sprinklerCenters,
            string libraryPath,
            List<ShopFittingGapInfo> fittingGaps,
            out int reducerCount,
            out int elbow90Count,
            out int elbow45Count,
            out int teeCount,
            out int sprinklerElbowCount,
            List<Extents3d> occupiedBlockExtents = null)
        {
            reducerCount = 0;
            elbow90Count = 0;
            elbow45Count = 0;
            teeCount = 0;
            sprinklerElbowCount = 0;

            if (shopPipes == null || shopPipes.Count == 0)
                return 0;

            List<ShopPipeLeg> legs =
                BuildShopPipeLegs(shopPipes);

            List<ShopJointNode> nodes =
                BuildShopJointNodes(legs);

            int total = 0;

            foreach (ShopJointNode node in nodes)
            {
                if (node == null || node.Arms.Count == 0)
                    continue;

                // FIX45: vùng thiết bị chỉ được chặn đầu hở. Nút có 2/3 arm
                // là giao mạng ống thật; không được vì bbox XREF lớn mà bỏ Co/Tê/Giảm.
                if (node.Arms.Count <= 1 &&
                    IsShopNodeInsideOccupiedBlock(
                        node.Point,
                        occupiedBlockExtents))
                {
                    continue;
                }

                // Đầu hở gần đầu phun: chèn CO 90 ĐI XUỐNG (không dùng hướng ngang).
                if (node.Arms.Count == 1)
                {
                    if (IsShopSprinklerEnd(
                            node.Point,
                            sprinklerCenters))
                    {
                        if (DrawSmartShopSprinklerDropElbow(
                                tr,
                                db,
                                btr,
                                node.Point,
                                node.Arms[0],
                                libraryPath,
                                fittingGaps) > 0)
                        {
                            sprinklerElbowCount++;
                            elbow90Count++;
                            total++;
                        }
                    }

                    continue;
                }

                if (node.Arms.Count == 2)
                {
                    ShopJointArm a = node.Arms[0];
                    ShopJointArm b = node.Arms[1];

                    double includedAngle =
                        GetShopAngleDegrees(
                            a.Direction,
                            b.Direction);

                    double turnAngle =
                        Math.Abs(180.0 - includedAngle);

                    bool differentSize =
                        Math.Abs(a.Width - b.Width) >= 0.5;

                    if (differentSize &&
                        turnAngle <= ShopStraightAngleToleranceDeg)
                    {
                        if (DrawSmartShopReducer(
                                tr,
                                db,
                                btr,
                                node.Point,
                                a,
                                b,
                                libraryPath,
                                fittingGaps) > 0)
                        {
                            reducerCount++;
                            total++;
                        }

                        continue;
                    }

                    if (differentSize)
                    {
                        // Không tự ép một côn giảm vào nút đang đổi hướng.
                        // Trường hợp này cần block co giảm chuyên dụng trong thư viện.
                        continue;
                    }

                    if (Math.Abs(turnAngle - 90.0) <=
                        ShopElbowAngleToleranceDeg)
                    {
                        if (DrawSmartShopElbow(
                                tr,
                                db,
                                btr,
                                node.Point,
                                a,
                                b,
                                libraryPath,
                                90,
                                fittingGaps) > 0)
                        {
                            elbow90Count++;
                            total++;
                        }

                        continue;
                    }

                    if (Math.Abs(turnAngle - 45.0) <=
                        ShopElbowAngleToleranceDeg)
                    {
                        try
                        {
                            Autodesk.AutoCAD.ApplicationServices.Core.Application
                                .DocumentManager
                                .MdiActiveDocument?
                                .Editor
                                .WriteMessage(
                                    $"\n[SHOP FIX39] NODE CO45: " +
                                    $"{a.SizeText} | included={includedAngle:0.##}° | " +
                                    $"turn={turnAngle:0.##}°");
                        }
                        catch
                        {
                        }

                        if (DrawSmartShopElbow(
                                tr,
                                db,
                                btr,
                                node.Point,
                                a,
                                b,
                                libraryPath,
                                45,
                                fittingGaps) > 0)
                        {
                            elbow45Count++;
                            total++;
                        }
                    }

                    continue;
                }

                if (node.Arms.Count == 3)
                {
                    if (DrawSmartShopTee(
                            tr,
                            db,
                            btr,
                            node.Point,
                            node.Arms,
                            libraryPath,
                            fittingGaps) > 0)
                    {
                        teeCount++;
                        total++;
                    }

                    continue;
                }

                // 4 nhánh trở lên thường là giao cắt hoặc nút đặc biệt.
                // Không tự chèn để tránh nhận sai cao độ/giao cắt không nối.
            }

            return total;
        }

        private List<ShopPipeLeg> BuildShopPipeLegs(
            IEnumerable<ShopPipeCandidate> shopPipes)
        {
            List<ShopPipeLeg> result =
                new List<ShopPipeLeg>();

            if (shopPipes == null)
                return result;

            foreach (ShopPipeCandidate pipe in shopPipes)
            {
                if (pipe?.Curve == null)
                    continue;

                Curve curve = pipe.Curve;

                if (curve is Line)
                {
                    AddStraightShopLeg(
                        result,
                        pipe,
                        pipe.Start,
                        pipe.End);
                    continue;
                }

                if (curve is Polyline pl &&
                    pl.NumberOfVertices >= 2)
                {
                    for (int i = 0;
                        i < pl.NumberOfVertices - 1;
                        i++)
                    {
                        if (pl.GetSegmentType(i) !=
                            SegmentType.Line)
                        {
                            continue;
                        }

                        Point3d p1 = pl.GetPoint3dAt(i);
                        Point3d p2 = pl.GetPoint3dAt(i + 1);

                        AddStraightShopLeg(
                            result,
                            pipe,
                            p1,
                            p2);
                    }

                    if (pl.Closed &&
                        pl.NumberOfVertices > 2)
                    {
                        Point3d p1 =
                            pl.GetPoint3dAt(
                                pl.NumberOfVertices - 1);
                        Point3d p2 = pl.GetPoint3dAt(0);

                        AddStraightShopLeg(
                            result,
                            pipe,
                            p1,
                            p2);
                    }

                    continue;
                }

                // Arc/Curve khác: vẫn dùng 2 đầu và tiếp tuyến để nhận nút ở đầu,
                // nhưng không dùng phần giữa để suy đoán giao cắt.
                try
                {
                    Vector3d startDir =
                        GetShopCurveDirection(curve, true);
                    Vector3d endDir =
                        GetShopCurveDirection(curve, false);

                    result.Add(
                        new ShopPipeLeg
                        {
                            Pipe = pipe,
                            Start = curve.StartPoint,
                            End = curve.EndPoint,
                            StartDirectionAway = startDir,
                            EndDirectionAway = -endDir,
                            IsStraight = false
                        });
                }
                catch { }
            }

            return result;
        }

        private static void AddStraightShopLeg(
            List<ShopPipeLeg> result,
            ShopPipeCandidate pipe,
            Point3d start,
            Point3d end)
        {
            if (result == null ||
                pipe == null ||
                start.DistanceTo(end) < 1.0)
            {
                return;
            }

            Vector3d dir =
                new Vector3d(
                    end.X - start.X,
                    end.Y - start.Y,
                    0.0);

            if (dir.Length < 1e-9)
                return;

            dir = dir.GetNormal();

            result.Add(
                new ShopPipeLeg
                {
                    Pipe = pipe,
                    Start = start,
                    End = end,
                    StartDirectionAway = dir,
                    EndDirectionAway = -dir,
                    IsStraight = true
                });
        }

        private List<ShopJointNode> BuildShopJointNodes(
            List<ShopPipeLeg> legs)
        {
            List<ShopJointNode> result =
                new List<ShopJointNode>();

            if (legs == null || legs.Count == 0)
                return result;

            List<Point3d> nodePoints =
                new List<Point3d>();

            foreach (ShopPipeLeg leg in legs)
            {
                AddUniquePoint(
                    nodePoints,
                    leg.Start,
                    ShopDuplicateNodeTolerance);
                AddUniquePoint(
                    nodePoints,
                    leg.End,
                    ShopDuplicateNodeTolerance);
            }

            for (int i = 0; i < legs.Count; i++)
            {
                for (int j = i + 1; j < legs.Count; j++)
                {
                    ShopPipeLeg a = legs[i];
                    ShopPipeLeg b = legs[j];

                    if (a == null || b == null)
                        continue;

                    if (a.IsStraight && b.IsStraight &&
                        TryGetShopSegmentIntersection(
                            a,
                            b,
                            out Point3d crossing))
                    {
                        AddUniquePoint(
                            nodePoints,
                            crossing,
                            ShopDuplicateNodeTolerance);
                    }

                    TryRegisterShopEndpointOnLeg(
                        nodePoints,
                        a.Start,
                        b);
                    TryRegisterShopEndpointOnLeg(
                        nodePoints,
                        a.End,
                        b);
                    TryRegisterShopEndpointOnLeg(
                        nodePoints,
                        b.Start,
                        a);
                    TryRegisterShopEndpointOnLeg(
                        nodePoints,
                        b.End,
                        a);
                }
            }

            DeduplicateCtnShopNodePoints(
                nodePoints);

            foreach (Point3d pt in nodePoints)
            {
                ShopJointNode node =
                    new ShopJointNode
                    {
                        Point = pt
                    };

                foreach (ShopPipeLeg leg in legs)
                {
                    AddShopArmsAtNode(
                        node,
                        leg);
                }

                RemoveDuplicateShopArms(node.Arms);

                if (node.Arms.Count > 0)
                    result.Add(node);
            }

            // FIX37:
            // Nhiều bản vẽ MEP cố tình chừa một khe nhỏ tại vị trí Co 45.
            // Khi đó hai đoạn ống không có chung endpoint nên logic node cũ
            // hiểu thành hai đầu hở và không chèn ELB45.
            MergeShopNear45EndpointNodes(
                result);

            return result;
        }

        private void MergeShopNear45EndpointNodes(
            List<ShopJointNode> nodes)
        {
            if (nodes == null ||
                nodes.Count < 2)
            {
                return;
            }

            HashSet<int> removeIndexes =
                new HashSet<int>();

            List<ShopJointNode> addNodes =
                new List<ShopJointNode>();

            for (int i = 0;
                i < nodes.Count;
                i++)
            {
                if (removeIndexes.Contains(i))
                    continue;

                ShopJointNode aNode =
                    nodes[i];

                if (aNode == null ||
                    aNode.Arms == null ||
                    aNode.Arms.Count != 1)
                {
                    continue;
                }

                ShopJointArm a =
                    aNode.Arms[0];

                if (a == null ||
                    a.Direction.Length < 1e-9)
                {
                    continue;
                }

                for (int j = i + 1;
                    j < nodes.Count;
                    j++)
                {
                    if (removeIndexes.Contains(j))
                        continue;

                    ShopJointNode bNode =
                        nodes[j];

                    if (bNode == null ||
                        bNode.Arms == null ||
                        bNode.Arms.Count != 1)
                    {
                        continue;
                    }

                    ShopJointArm b =
                        bNode.Arms[0];

                    if (b == null ||
                        b.Direction.Length < 1e-9)
                    {
                        continue;
                    }

                    // Co 45 chỉ nối hai đoạn CÙNG DN.
                    string sa =
                        CleanLayerText(
                            a.SizeText ?? "");

                    string sb =
                        CleanLayerText(
                            b.SizeText ?? "");

                    if (string.IsNullOrWhiteSpace(sa) ||
                        string.IsNullOrWhiteSpace(sb) ||
                        !string.Equals(
                            sa,
                            sb,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    if (Math.Abs(
                            a.Width -
                            b.Width) >= 0.5)
                    {
                        continue;
                    }

                    double included =
                        GetShopAngleDegrees(
                            a.Direction,
                            b.Direction);

                    double turn =
                        Math.Abs(
                            180.0 -
                            included);

                    // Dung sai riêng cho "near-miss" 45°.
                    // Rộng hơn một chút so với node bình thường vì
                    // đường CAD thực tế có thể không đúng 45.000°.
                    if (Math.Abs(
                            turn -
                            45.0) > 24.0)
                    {
                        continue;
                    }

                    double dn =
                        Math.Max(
                            ParseShopDnNumber(
                                NormalizeShopDnToken(
                                    a.SizeText)),
                            ParseShopDnNumber(
                                NormalizeShopDnToken(
                                    b.SizeText)));

                    if (dn <= 0.0)
                        dn = Math.Max(a.Width, b.Width);

                    double maxJoin =
                        Math.Max(
                            ShopJointTolerance * 3.0,
                            Math.Max(
                                250.0,
                                dn * 2.5));

                    if (PlanDistance(
                            aNode.Point,
                            bNode.Point) >
                        maxJoin)
                    {
                        continue;
                    }

                    // Hướng từ endpoint đi về "góc thiếu" chính là -arm.Direction.
                    Vector3d towardA =
                        -a.Direction.GetNormal();

                    Vector3d towardB =
                        -b.Direction.GetNormal();

                    Point3d joint;

                    if (!TryIntersectShopAxes(
                            aNode.Point,
                            towardA,
                            bNode.Point,
                            towardB,
                            out joint))
                    {
                        continue;
                    }

                    double da =
                        PlanDistance(
                            aNode.Point,
                            joint);

                    double db =
                        PlanDistance(
                            bNode.Point,
                            joint);

                    if (da > maxJoin ||
                        db > maxJoin)
                    {
                        continue;
                    }

                    Vector3d va =
                        joint -
                        aNode.Point;

                    Vector3d vb =
                        joint -
                        bNode.Point;

                    if (va.Length < 1e-9 ||
                        vb.Length < 1e-9)
                    {
                        continue;
                    }

                    // Giao điểm phải nằm về phía phần ống đang bị thiếu,
                    // không được nằm sâu vào trong đoạn đã vẽ.
                    if (va.GetNormal()
                            .DotProduct(towardA) < 0.70 ||
                        vb.GetNormal()
                            .DotProduct(towardB) < 0.70)
                    {
                        continue;
                    }

                    // Tránh tạo node trùng node 2/3 nhánh đã có.
                    bool alreadyExists =
                        nodes.Any(n =>
                            n != null &&
                            n.Arms != null &&
                            n.Arms.Count >= 2 &&
                            PlanDistance(
                                n.Point,
                                joint) <=
                            ShopDuplicateNodeTolerance);

                    if (alreadyExists)
                        continue;

                    ShopJointNode merged =
                        new ShopJointNode
                        {
                            Point = joint
                        };

                    // Arm.Direction vẫn là hướng từ joint đi vào các đoạn ống.
                    AddShopArm(
                        merged.Arms,
                        a.Leg,
                        a.Direction);

                    AddShopArm(
                        merged.Arms,
                        b.Leg,
                        b.Direction);

                    RemoveDuplicateShopArms(
                        merged.Arms);

                    if (merged.Arms.Count != 2)
                        continue;

                    addNodes.Add(
                        merged);

                    removeIndexes.Add(i);
                    removeIndexes.Add(j);

                    try
                    {
                        Autodesk.AutoCAD.ApplicationServices.Core.Application
                            .DocumentManager
                            .MdiActiveDocument?
                            .Editor
                            .WriteMessage(
                                $"\n[SHOP FIX39] GHÉP NODE CO45: " +
                                $"{a.SizeText} | turn={turn:0.##}° | " +
                                $"gapA={da:0.##} | gapB={db:0.##}");
                    }
                    catch
                    {
                    }

                    break;
                }
            }

            if (removeIndexes.Count > 0)
            {
                List<ShopJointNode> kept =
                    nodes
                        .Where((n, idx) =>
                            !removeIndexes.Contains(idx))
                        .ToList();

                nodes.Clear();
                nodes.AddRange(kept);
            }

            if (addNodes.Count > 0)
                nodes.AddRange(addNodes);
        }


        private void TryRegisterShopEndpointOnLeg(
            List<Point3d> nodePoints,
            Point3d endpoint,
            ShopPipeLeg targetLeg)
        {
            if (nodePoints == null ||
                targetLeg == null ||
                !targetLeg.IsStraight)
            {
                return;
            }

            if (!TryProjectShopPointToSegment(
                    endpoint,
                    targetLeg.Start,
                    targetLeg.End,
                    out Point3d projected,
                    out double t,
                    out double distance))
            {
                return;
            }

            if (distance > ShopJointTolerance ||
                t <= 0.02 ||
                t >= 0.98)
            {
                return;
            }

            // FIX45: Tâm T phải nằm chính xác trên tim tuyến chính.
            // Code cũ lấy midpoint rồi AddUniquePoint giữ lại endpoint cũ,
            // làm hai nút giống nhau có lúc 2 arm, có lúc 3 arm.
            Point3d joint = projected;

            int endpointIndex = -1;
            double bestDistance = double.MaxValue;

            for (int i = 0;
                i < nodePoints.Count;
                i++)
            {
                double d =
                    PlanDistance(
                        nodePoints[i],
                        endpoint);

                if (d <= ShopDuplicateNodeTolerance &&
                    d < bestDistance)
                {
                    bestDistance = d;
                    endpointIndex = i;
                }
            }

            if (endpointIndex >= 0)
            {
                nodePoints[endpointIndex] = joint;

                for (int i = nodePoints.Count - 1;
                    i >= 0;
                    i--)
                {
                    if (i == endpointIndex)
                        continue;

                    if (PlanDistance(
                            nodePoints[i],
                            joint) <=
                        ShopDuplicateNodeTolerance)
                    {
                        nodePoints.RemoveAt(i);

                        if (i < endpointIndex)
                            endpointIndex--;
                    }
                }
            }
            else
            {
                nodePoints.Add(joint);
            }
        }

        private void DeduplicateCtnShopNodePoints(
            List<Point3d> nodePoints)
        {
            if (nodePoints == null ||
                nodePoints.Count < 2)
            {
                return;
            }

            for (int i = 0;
                i < nodePoints.Count;
                i++)
            {
                for (int j = nodePoints.Count - 1;
                    j > i;
                    j--)
                {
                    if (PlanDistance(
                            nodePoints[i],
                            nodePoints[j]) <=
                        ShopDuplicateNodeTolerance)
                    {
                        nodePoints.RemoveAt(j);
                    }
                }
            }
        }

        private void AddShopArmsAtNode(
            ShopJointNode node,
            ShopPipeLeg leg)
        {
            if (node == null || leg == null)
                return;

            double ds =
                PlanDistance(node.Point, leg.Start);
            double de =
                PlanDistance(node.Point, leg.End);

            bool atStart = ds <= ShopJointTolerance;
            bool atEnd = de <= ShopJointTolerance;

            if (atStart)
            {
                AddShopArm(
                    node.Arms,
                    leg,
                    leg.StartDirectionAway);
            }

            if (atEnd)
            {
                AddShopArm(
                    node.Arms,
                    leg,
                    leg.EndDirectionAway);
            }

            if (atStart || atEnd || !leg.IsStraight)
                return;

            if (TryProjectShopPointToSegment(
                    node.Point,
                    leg.Start,
                    leg.End,
                    out Point3d ignored,
                    out double t,
                    out double distance) &&
                distance <= ShopJointTolerance &&
                t > 0.02 &&
                t < 0.98)
            {
                Vector3d dir =
                    new Vector3d(
                        leg.End.X - leg.Start.X,
                        leg.End.Y - leg.Start.Y,
                        0.0);

                if (dir.Length > 1e-9)
                {
                    dir = dir.GetNormal();
                    AddShopArm(node.Arms, leg, dir);
                    AddShopArm(node.Arms, leg, -dir);
                }
            }
        }

        private static void AddShopArm(
            List<ShopJointArm> arms,
            ShopPipeLeg leg,
            Vector3d direction)
        {
            if (arms == null ||
                leg?.Pipe == null ||
                direction.Length < 1e-9)
            {
                return;
            }

            Vector3d dir =
                new Vector3d(
                    direction.X,
                    direction.Y,
                    0.0);

            if (dir.Length < 1e-9)
                return;

            arms.Add(
                new ShopJointArm
                {
                    Leg = leg,
                    Direction = dir.GetNormal()
                });
        }

        private static void RemoveDuplicateShopArms(
            List<ShopJointArm> arms)
        {
            if (arms == null || arms.Count < 2)
                return;

            for (int i = arms.Count - 1; i >= 0; i--)
            {
                ShopJointArm a = arms[i];

                for (int j = 0; j < i; j++)
                {
                    ShopJointArm b = arms[j];

                    if (!string.Equals(
                            a.SizeText,
                            b.SizeText,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    double angle =
                        GetShopAngleDegrees(
                            a.Direction,
                            b.Direction);

                    if (angle <= 3.0)
                    {
                        arms.RemoveAt(i);
                        break;
                    }
                }
            }
        }

        private static bool TryGetShopSegmentIntersection(
            ShopPipeLeg a,
            ShopPipeLeg b,
            out Point3d point)
        {
            point = Point3d.Origin;

            if (a == null || b == null ||
                !a.IsStraight || !b.IsStraight)
                return false;

            double px = a.Start.X;
            double py = a.Start.Y;
            double rx = a.End.X - a.Start.X;
            double ry = a.End.Y - a.Start.Y;
            double qx = b.Start.X;
            double qy = b.Start.Y;
            double sx = b.End.X - b.Start.X;
            double sy = b.End.Y - b.Start.Y;

            double denom = Cross2D(rx, ry, sx, sy);

            if (Math.Abs(denom) < 1e-9)
                return false;

            double qpx = qx - px;
            double qpy = qy - py;

            double t =
                Cross2D(qpx, qpy, sx, sy) / denom;
            double u =
                Cross2D(qpx, qpy, rx, ry) / denom;

            double lenA =
                Math.Sqrt((rx * rx) + (ry * ry));
            double lenB =
                Math.Sqrt((sx * sx) + (sy * sy));

            double extA =
                lenA > 1e-9
                    ? ShopJointTolerance / lenA
                    : 0.0;
            double extB =
                lenB > 1e-9
                    ? ShopJointTolerance / lenB
                    : 0.0;

            if (t < -extA || t > 1.0 + extA ||
                u < -extB || u > 1.0 + extB)
            {
                return false;
            }

            point =
                new Point3d(
                    px + (t * rx),
                    py + (t * ry),
                    (a.Start.Z + b.Start.Z) / 2.0);

            return true;
        }

        private static bool TryProjectShopPointToSegment(
            Point3d point,
            Point3d start,
            Point3d end,
            out Point3d projected,
            out double t,
            out double distance)
        {
            projected = Point3d.Origin;
            t = 0.0;
            distance = double.MaxValue;

            double vx = end.X - start.X;
            double vy = end.Y - start.Y;
            double len2 = (vx * vx) + (vy * vy);

            if (len2 < 1e-9)
                return false;

            t =
                ((point.X - start.X) * vx +
                 (point.Y - start.Y) * vy) / len2;

            double clamped = t;
            if (clamped < 0.0) clamped = 0.0;
            if (clamped > 1.0) clamped = 1.0;

            projected =
                new Point3d(
                    start.X + (clamped * vx),
                    start.Y + (clamped * vy),
                    (start.Z + end.Z) / 2.0);

            distance =
                PlanDistance(point, projected);

            return true;
        }

        private static double Cross2D(
            double ax,
            double ay,
            double bx,
            double by)
        {
            return (ax * by) - (ay * bx);
        }

        private static double PlanDistance(
            Point3d a,
            Point3d b)
        {
            double dx = a.X - b.X;
            double dy = a.Y - b.Y;
            return Math.Sqrt((dx * dx) + (dy * dy));
        }

        private static double GetShopAngleDegrees(
            Vector3d a,
            Vector3d b)
        {
            Vector3d aa =
                new Vector3d(a.X, a.Y, 0.0);
            Vector3d bb =
                new Vector3d(b.X, b.Y, 0.0);

            if (aa.Length < 1e-9 || bb.Length < 1e-9)
                return 0.0;

            aa = aa.GetNormal();
            bb = bb.GetNormal();

            double dot = aa.DotProduct(bb);
            if (dot < -1.0) dot = -1.0;
            if (dot > 1.0) dot = 1.0;

            return Math.Acos(dot) * 180.0 / Math.PI;
        }

        private static double ShopCross(
            Vector3d a,
            Vector3d b)
        {
            return (a.X * b.Y) - (a.Y * b.X);
        }

        /// <summary>
        /// Co 90 cuối nhánh đầu phun: một đầu theo ống, một đầu HƯỚNG XUỐNG.
        /// Không dùng orientation ngang.
        /// </summary>
        private int DrawSmartShopSprinklerDropElbow(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d nodePoint,
            ShopJointArm arm,
            string libraryPath,
            List<ShopFittingGapInfo> fittingGaps)
        {
            if (arm == null)
                return 0;

            string layerName =
                "FF_SHOP_CO90_DAUPHUN_" +
                CleanLayerText(arm.SizeText);

            EnsureShopLayerExists(
                tr,
                db,
                layerName);

            // Direction arm = từ node đầu phun đi ngược vào tuyến ống.
            Vector3d intoPipe =
                new Vector3d(
                    arm.Direction.X,
                    arm.Direction.Y,
                    0.0);

            if (intoPipe.Length < 1e-9)
                return 0;

            intoPipe =
                intoPipe.GetNormal();

            // FIX24:
            // Co tại đầu phun là CO ĐI XUỐNG theo Z, KHÔNG phải co 90
            // quay một chân xuống -Y trên mặt bằng.
            // Chỉ xoay đầu nối ngang của block theo hướng tuyến ống.
            double rotation =
                Math.Atan2(
                    intoPipe.Y,
                    intoPipe.X);

            // Tuyệt đối không mirror Y ở co đầu phun.
            // Hướng xuống sẽ do Visibility/Lookup của Dynamic Block quyết định.
            bool mirrorY = false;

            if (!TryInsertShopLibraryFitting(
                    tr,
                    db,
                    btr,
                    libraryPath,
                    "ELBOW90",
                    arm.SizeText,
                    arm.SizeText,
                    nodePoint,
                    rotation,
                    layerName,
                    mirrorY,
                    fittingGaps))
            {
                return 0;
            }

            return 1;
        }

        /// <summary>
        /// FIX24: đổi trạng thái Dynamic Block trên ĐÚNG reference vừa chèn.
        /// Không tìm "block gần nhất" vì gần đầu phun còn có block sprinkler,
        /// dễ chọn nhầm đối tượng.
        /// </summary>
        private bool TrySetShopFittingVisibilityOnReference(
            BlockReference br,
            bool preferDown,
            bool preferHorizontal)
        {
            if (br == null ||
                br.IsErased ||
                !br.IsDynamicBlock)
            {
                return false;
            }

            try
            {
                DynamicBlockReferencePropertyCollection props =
                    br.DynamicBlockReferencePropertyCollection;

                if (props == null)
                    return false;

                bool changed = false;

                foreach (DynamicBlockReferenceProperty prop in props)
                {
                    if (prop == null ||
                        prop.ReadOnly)
                    {
                        continue;
                    }

                    string pname =
                        NormalizeShopKey(
                            prop.PropertyName ?? "");

                    // Chỉ xét property kiểu Visibility / Lookup / State / Hướng.
                    bool possibleState =
                        pname.Contains("VISIBILITY") ||
                        pname.Contains("VISIBLE") ||
                        pname.Contains("STATE") ||
                        pname.Contains("TRANGTHAI") ||
                        pname.Contains("HUONG") ||
                        pname.Contains("ORIENT") ||
                        pname.Contains("TYPE") ||
                        pname.Contains("KIEU") ||
                        pname.Contains("VIEW") ||
                        pname.Contains("LOOKUP") ||
                        pname.Contains("CHIEU") ||
                        pname.Contains("DIRECTION");

                    if (pname.Contains("FLIP") ||
                        pname.Contains("MIRROR"))
                    {
                        continue;
                    }

                    object[] values = null;

                    try
                    {
                        values =
                            prop.GetAllowedValues();
                    }
                    catch
                    {
                        continue;
                    }

                    if (values == null ||
                        values.Length == 0)
                    {
                        continue;
                    }

                    // Nếu property có các giá trị chuỗi rõ nghĩa thì vẫn xét
                    // ngay cả khi tên property chung chung.
                    bool anyNamedState =
                        values.Any(v =>
                        {
                            string k =
                                NormalizeShopKey(
                                    (v ?? "").ToString());

                            return
                                k.Contains("XUONG") ||
                                k.Contains("DOWN") ||
                                k.Contains("DROP") ||
                                k.Contains("VERT") ||
                                k.Contains("NGANG") ||
                                k.Contains("HORIZ") ||
                                k.Contains("PLAN") ||
                                k.Contains("UP") ||
                                k.Contains("LEN");
                        });

                    if (!possibleState &&
                        !anyNamedState)
                    {
                        continue;
                    }

                    object bestValue = null;
                    int bestScore =
                        int.MinValue;

                    foreach (object value
                        in values)
                    {
                        string raw =
                            (value ?? "")
                                .ToString();

                        string k =
                            NormalizeShopKey(
                                raw);

                        int score = 0;

                        bool isDown =
                            k.Contains("HUONGXUONG") ||
                            k.Contains("XUONG") ||
                            k.Contains("DOWN") ||
                            k.Contains("DROP") ||
                            k.Contains("DIXUONG") ||
                            k.Contains("BOTTOM") ||
                            k.Contains("VERTDOWN");

                        bool isUp =
                            k.Contains("HUONGLEN") ||
                            k.Contains("LEN") ||
                            k.Contains("TOP") ||
                            k == "UP" ||
                            k.Contains("VERTUP");

                        bool isHorizontal =
                            k.Contains("NGANG") ||
                            k.Contains("HORIZ") ||
                            k.Contains("PLAN") ||
                            k.Contains("FLAT") ||
                            k.Contains("SIDE");

                        if (preferDown)
                        {
                            if (isDown)
                                score += 1000;

                            if (isHorizontal)
                                score -= 500;

                            if (isUp)
                                score -= 300;
                        }
                        else if (preferHorizontal)
                        {
                            if (isHorizontal)
                                score += 1000;

                            if (isDown ||
                                isUp)
                            {
                                score -= 500;
                            }
                        }

                        if (score >
                            bestScore)
                        {
                            bestScore = score;
                            bestValue = value;
                        }
                    }

                    if (bestValue != null &&
                        bestScore > 0)
                    {
                        try
                        {
                            prop.Value =
                                bestValue;

                            changed = true;

                            var doc =
                                Autodesk.AutoCAD.ApplicationServices.Core.Application
                                    .DocumentManager
                                    .MdiActiveDocument;

                            doc?.Editor.WriteMessage(
                                $"\n[SHOP FIX24] Dynamic state: " +
                                $"{prop.PropertyName} = {bestValue}");
                        }
                        catch
                        {
                        }
                    }
                }

                if (changed)
                {
                    try
                    {
                        br.RecordGraphicsModified(
                            true);
                    }
                    catch
                    {
                    }
                }

                return changed;
            }
            catch
            {
                return false;
            }
        }

        /// <summary>
        /// Block động co cuối đầu phun: visibility HƯỚNG XUỐNG.
        /// </summary>
        private void TrySetShopElbowDropVisibility(
            Transaction tr,
            BlockTableRecord btr,
            Point3d nearPoint)
        {
            TrySetShopFittingVisibility(
                tr,
                btr,
                nearPoint,
                preferDown: true,
                preferHorizontal: false);
        }

        /// <summary>
        /// Chọn visibility block động: xuống HOẶC ngang (không để hiện cả hai).
        /// </summary>
        private void TrySetShopFittingVisibility(
            Transaction tr,
            BlockTableRecord btr,
            Point3d nearPoint,
            bool preferDown,
            bool preferHorizontal)
        {
            if (tr == null || btr == null)
                return;

            try
            {
                BlockReference best = null;
                double bestDist = double.MaxValue;

                foreach (ObjectId id in btr)
                {
                    BlockReference br =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as BlockReference;

                    if (br == null || br.IsErased)
                        continue;

                    double d = br.Position.DistanceTo(nearPoint);
                    if (d < bestDist && d <= 400.0)
                    {
                        bestDist = d;
                        best = br;
                    }
                }

                if (best == null)
                    return;

                best =
                    tr.GetObject(
                        best.ObjectId,
                        OpenMode.ForWrite,
                        false) as BlockReference;

                if (best == null || !best.IsDynamicBlock)
                    return;

                DynamicBlockReferencePropertyCollection props =
                    best.DynamicBlockReferencePropertyCollection;

                if (props == null)
                    return;

                foreach (DynamicBlockReferenceProperty prop in props)
                {
                    if (prop == null || prop.ReadOnly)
                        continue;

                    string pname =
                        (prop.PropertyName ?? "").ToUpperInvariant();

                    bool isVis =
                        pname.Contains("VISIBILITY") ||
                        pname.Contains("VISIBLE") ||
                        pname.Contains("STATE") ||
                        pname.Contains("TRANGTHAI") ||
                        pname.Contains("HUONG") ||
                        pname.Contains("ORIENT") ||
                        pname.Contains("TYPE") ||
                        pname.Contains("KIEU") ||
                        pname.Contains("VIEW") ||
                        pname.Contains("LOOKUP") ||
                        pname.Contains("CHIEU") ||
                        pname.Contains("DIRECTION");

                    // Flip parameter: không dùng cho visibility, bỏ qua
                    if (pname.Contains("FLIP") ||
                        pname.Contains("MIRROR"))
                        continue;

                    if (!isVis)
                        continue;

                    object[] values = null;
                    try { values = prop.GetAllowedValues(); }
                    catch { continue; }

                    if (values == null || values.Length == 0)
                        continue;

                    string scoreBest = null;
                    int scoreBestVal = int.MinValue;

                    foreach (object v in values)
                    {
                        string s = (v ?? "").ToString();
                        string k = NormalizeShopKey(s);
                        int score = 0;

                        bool isDown =
                            k.Contains("XUONG") ||
                            k.Contains("DOWN") ||
                            k.Contains("DROP") ||
                            k.Contains("DIXUONG") ||
                            k.Contains("BOTTOM");

                        bool isUp =
                            k.Contains("LEN") ||
                            k.Contains("TOP") ||
                            (k.Contains("UP") &&
                             !k.Contains("SUP") &&
                             !k.Contains("COUP"));

                        bool isHoriz =
                            k.Contains("NGANG") ||
                            k.Contains("HORIZ") ||
                            k.Contains("FLAT") ||
                            k.Contains("PLAN") ||
                            k.Contains("SIDE") ||
                            k.Contains("LEFT") ||
                            k.Contains("RIGHT") ||
                            k == "1" ||
                            k == "A" ||
                            k.Contains("ELB90") ||
                            k.Contains("CO90");

                        if (preferDown)
                        {
                            if (isDown) score += 100;
                            if (isHoriz) score -= 60;
                            if (isUp) score += 5;
                        }
                        else if (preferHorizontal)
                        {
                            if (isHoriz) score += 100;
                            if (isDown) score -= 100;
                            if (isUp) score -= 50;
                            if (!isDown && !isUp) score += 40;
                        }

                        if (score > scoreBestVal)
                        {
                            scoreBestVal = score;
                            scoreBest = s;
                        }
                    }

                    if (scoreBest != null && scoreBestVal > 0)
                    {
                        try
                        {
                            prop.Value = scoreBest;
                        }
                        catch { }
                    }
                }

                try
                {
                    best.RecordGraphicsModified(true);
                }
                catch { }
            }
            catch { }
        }

        private bool IsShopSprinklerEnd(
            Point3d point,
            List<Point3d> sprinklerCenters)
        {
            if (sprinklerCenters == null ||
                sprinklerCenters.Count == 0)
            {
                return false;
            }

            return sprinklerCenters.Any(
                center =>
                    PlanDistance(point, center) <=
                    ShopSprinklerEndSearchDistance);
        }

        private bool IsLikelyShopSprinklerBlock(
            Transaction tr,
            BlockReference br)
        {
            if (tr == null || br == null)
                return false;

            try
            {
                BlockTableRecord def =
                    tr.GetObject(
                        br.BlockTableRecord,
                        OpenMode.ForRead,
                        false) as BlockTableRecord;

                string key =
                    NormalizeShopKey(def?.Name ?? "");

                return key.Contains("SPRINK") ||
                       key.Contains("SPK") ||
                       key.Contains("DAUPHUN") ||
                       key.Contains("PHUN") ||
                       key.Contains("SPRHEAD");
            }
            catch
            {
                return false;
            }
        }

        private static string GetShopSystemLayerPrefix(
            ShopJointArm arm)
        {
            string layer =
                arm?.Pipe?.LayerName ??
                "";

            if (layer.StartsWith(
                    "CTN_SHOP_",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "CTN_SHOP_";
            }

            return "FF_SHOP_";
        }

        private static string GetShopMaterialLayerToken(
            ShopJointArm arm)
        {
            string layer =
                (arm?.Pipe?.LayerName ?? "")
                    .ToUpperInvariant();

            if (layer.Contains(
                    "_PPR_"))
            {
                return "PPR_";
            }

            if (layer.Contains(
                    "_UPVC_"))
            {
                return "UPVC_";
            }

            return "";
        }


        private int DrawSmartShopReducer(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d nodePoint,
            ShopJointArm a,
            ShopJointArm b,
            string libraryPath,
            List<ShopFittingGapInfo> fittingGaps = null)
        {
            if (a == null || b == null)
                return 0;

            ShopJointArm large =
                a.Width >= b.Width ? a : b;
            ShopJointArm small =
                a.Width >= b.Width ? b : a;

            // Quy ước block reducer: +X đi từ đầu lớn sang đầu nhỏ.
            // Vì Direction của arm hướng từ nút đi ra ống, nên +X phải
            // hướng về phía ống nhỏ. Đây là chỗ sửa lỗi DN50 -> DN40
            // nhưng block cũ lại bị quay DN40 -> DN50.
            Vector3d largeToSmall =
                small.Direction;

            double rotation =
                Math.Atan2(
                    largeToSmall.Y,
                    largeToSmall.X);

            string layerName =
                GetShopSystemLayerPrefix(
                    large) +
                "GIAM_" +
                GetShopMaterialLayerToken(
                    large) +
                CleanLayerText(large.SizeText) +
                "-" +
                CleanLayerText(small.SizeText);

            EnsureShopLayerExists(tr, db, layerName);

            if (TryInsertShopLibraryFitting(
                    tr,
                    db,
                    btr,
                    libraryPath,
                    "REDUCER",
                    large.SizeText,
                    small.SizeText,
                    nodePoint,
                    rotation,
                    layerName,
                    false,
                    fittingGaps,
                    new List<Vector3d>
                    {
                        large.Direction,
                        small.Direction
                    }))
            {
                return 1;
            }

            // KHÔNG vẽ outline giả (hộp/hình lạ). Chỉ dùng block thư viện thật.
            return 0;
        }

        private int DrawSmartShopReducerOutline(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d nodePoint,
            ShopJointArm large,
            ShopJointArm small,
            string layerName)
        {
            if (large == null || small == null)
                return 0;

            Vector3d axis = small.Direction;
            if (axis.Length < 1e-9)
                return 0;
            axis = axis.GetNormal();

            Vector3d normal = GetPlanNormal(axis);
            double length =
                Math.Max(
                    150.0,
                    Math.Max(large.Width, small.Width) * 1.5);

            Point3d bigCenter =
                nodePoint - axis * (length / 2.0);
            Point3d smallCenter =
                nodePoint + axis * (length / 2.0);

            Point3d bigLeft =
                bigCenter + normal * (large.Width / 2.0);
            Point3d bigRight =
                bigCenter - normal * (large.Width / 2.0);
            Point3d smallLeft =
                smallCenter + normal * (small.Width / 2.0);
            Point3d smallRight =
                smallCenter - normal * (small.Width / 2.0);

            AppendShopLine(tr, db, btr, bigLeft, bigRight, layerName);
            AppendShopLine(tr, db, btr, smallLeft, smallRight, layerName);
            AppendShopLine(tr, db, btr, bigLeft, smallLeft, layerName);
            AppendShopLine(tr, db, btr, bigRight, smallRight, layerName);
            return 1;
        }

        private int DrawSmartShopElbow(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d nodePoint,
            ShopJointArm a,
            ShopJointArm b,
            string libraryPath,
            int angle,
            List<ShopFittingGapInfo> fittingGaps = null)
        {
            if (a == null || b == null)
                return 0;

            string fittingType =
                angle == 45 ? "ELBOW45" : "ELBOW90";

            string shopPrefix =
                GetShopSystemLayerPrefix(
                    a);

            string materialToken =
                GetShopMaterialLayerToken(
                    a);

            string layerName =
                angle == 45
                    ? shopPrefix +
                      "COLOI45_" +
                      materialToken +
                      CleanLayerText(a.SizeText)
                    : shopPrefix +
                      "CO90_" +
                      materialToken +
                      CleanLayerText(a.SizeText);

            EnsureShopLayerExists(tr, db, layerName);

            // Quy ước block co: nhánh chuẩn thứ nhất theo +X,
            // nhánh thứ hai nằm phía +Y. Nếu góc thực tế quay phải thì mirror Y.
            Vector3d first = a.Direction;
            Vector3d second = b.Direction;

            double rotation =
                Math.Atan2(first.Y, first.X);
            bool mirrorY =
                ShopCross(first, second) < 0.0;

            if (TryInsertShopLibraryFitting(
                    tr,
                    db,
                    btr,
                    libraryPath,
                    fittingType,
                    a.SizeText,
                    a.SizeText,
                    nodePoint,
                    rotation,
                    layerName,
                    mirrorY,
                    fittingGaps,
                    new List<Vector3d>
                    {
                        a.Direction,
                        b.Direction
                    }))
            {
                return 1;
            }

            // KHÔNG vẽ outline giả. Chỉ chèn block co thật từ thư viện.
            return 0;
        }

        private int DrawSmartShopElbowOutline(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d nodePoint,
            ShopJointArm a,
            ShopJointArm b,
            string layerName,
            int angle)
        {
            if (a == null || b == null)
                return 0;

            double halfA = Math.Max(a.Width, 10.0) / 2.0;
            double halfB = Math.Max(b.Width, 10.0) / 2.0;
            double legLen =
                Math.Max(
                    Math.Max(halfA, halfB) * 1.8,
                    80.0);

            Vector3d da = a.Direction;
            Vector3d dbDir = b.Direction;
            if (da.Length < 1e-9 || dbDir.Length < 1e-9)
                return 0;

            da = da.GetNormal();
            dbDir = dbDir.GetNormal();

            Vector3d na = GetPlanNormal(da);
            Vector3d nb = GetPlanNormal(dbDir);

            // Hai nhánh từ tâm nút đi ra theo hướng arm
            Point3d aEnd = nodePoint + da * legLen;
            Point3d bEnd = nodePoint + dbDir * legLen;

            // Vẽ 2 nét ngoài cho mỗi nhánh (hình co đơn giản)
            AppendShopLine(tr, db, btr, nodePoint + na * halfA, aEnd + na * halfA, layerName);
            AppendShopLine(tr, db, btr, nodePoint - na * halfA, aEnd - na * halfA, layerName);
            AppendShopLine(tr, db, btr, nodePoint + nb * halfB, bEnd + nb * halfB, layerName);
            AppendShopLine(tr, db, btr, nodePoint - nb * halfB, bEnd - nb * halfB, layerName);

            // Nối cung góc ngoài/trong gần đúng
            try
            {
                Vector3d mid = (da + dbDir);
                if (mid.Length > 1e-9)
                {
                    mid = mid.GetNormal();
                    Vector3d nMid = GetPlanNormal(mid);
                    double outer = Math.Max(halfA, halfB);
                    Point3d outerPt = nodePoint + mid * (legLen * 0.35) + nMid * outer;
                    // bỏ qua chi tiết phức tạp — 4 nét song song đã đủ nhận diện
                }
            }
            catch { }

            return 1;
        }

        private int DrawSmartShopTee(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d nodePoint,
            List<ShopJointArm> arms,
            string libraryPath,
            List<ShopFittingGapInfo> fittingGaps = null)
        {
            if (arms == null || arms.Count != 3)
                return 0;

            int mainA = 0;
            int mainB = 1;
            double bestOppositeAngle = -1.0;

            for (int i = 0; i < arms.Count; i++)
            {
                for (int j = i + 1; j < arms.Count; j++)
                {
                    double angle =
                        GetShopAngleDegrees(
                            arms[i].Direction,
                            arms[j].Direction);

                    if (angle > bestOppositeAngle)
                    {
                        bestOppositeAngle = angle;
                        mainA = i;
                        mainB = j;
                    }
                }
            }

            if (bestOppositeAngle < 150.0)
                return 0;

            int branchIndex =
                Enumerable.Range(0, 3)
                    .First(i => i != mainA && i != mainB);

            ShopJointArm main1 = arms[mainA];
            ShopJointArm main2 = arms[mainB];
            ShopJointArm branch = arms[branchIndex];

            // FIX34: phải là TÊ thật:
            // - hai đầu main gần thẳng hàng 180°
            // - branch gần 90° với CẢ HAI đầu main
            double branchAngle1 =
                GetShopAngleDegrees(
                    main1.Direction,
                    branch.Direction);

            double branchAngle2 =
                GetShopAngleDegrees(
                    main2.Direction,
                    branch.Direction);

            if (Math.Abs(branchAngle1 - 90.0) > 25.0 ||
                Math.Abs(branchAngle2 - 90.0) > 25.0)
            {
                return 0;
            }

            // Hai đầu đường chính của Tê phải cùng DN.
            if (Math.Abs(main1.Width - main2.Width) >= 0.5)
                return 0;

            ShopJointArm main =
                main1.Width >= main2.Width
                    ? main1
                    : main2;

            // Với bộ thư viện SCREW/WELD hiện tại:
            // Tê giảm chỉ cho main >= branch.
            // Nếu branch lớn hơn main => topology/size đang bị nhận sai, bỏ qua.
            if (branch.Width > main.Width + 0.5)
                return 0;

            string mainSize =
                main.SizeText;
            string branchSize =
                branch.SizeText;

            string layerName =
                GetShopSystemLayerPrefix(
                    main) +
                "TE_" +
                GetShopMaterialLayerToken(
                    main) +
                CleanLayerText(mainSize) +
                "-" +
                CleanLayerText(branchSize);

            EnsureShopLayerExists(tr, db, layerName);

            // Hướng ống thật trên bản vẽ
            Vector3d mainDir = main1.Direction;
            if (mainDir.Length < 1e-9)
                mainDir = main.Direction;
            mainDir = mainDir.GetNormal();

            Vector3d branchDir = branch.Direction;
            if (branchDir.Length > 1e-9)
                branchDir = branchDir.GetNormal();
            else
                branchDir = new Vector3d(-mainDir.Y, mainDir.X, 0.0);

            // FIX23: rotation truyền xuống là HƯỚNG ĐƯỜNG CHÍNH THỰC TẾ.
            // TryInsert sẽ tự đọc 3 port của block và map chúng vào
            // main / -main / branch. Không giả định block gốc nằm theo X hay Y.
            double rotation =
                Math.Atan2(
                    mainDir.Y,
                    mainDir.X);

            bool mirrorY =
                ShopCross(
                    mainDir,
                    branchDir) < 0.0;

            if (TryInsertShopLibraryFitting(
                    tr,
                    db,
                    btr,
                    libraryPath,
                    "TEE",
                    mainSize,
                    branchSize,
                    nodePoint,
                    rotation,
                    layerName,
                    mirrorY,
                    fittingGaps,
                    new List<Vector3d>
                    {
                        main1.Direction,
                        main2.Direction,
                        branch.Direction
                    }))
            {
                return 1;
            }

            return 0;
        }

        /// <summary>
        /// Tính xoay/mirror cho TÊ thư viện SCREW/WELD
        /// (trục chính block ≈ Y, nhánh ≈ X trong định nghĩa).
        /// </summary>
        private void ComputeShopTeeTransform(
            Vector3d mainDir,
            Vector3d branchDir,
            out double rotation,
            out bool mirrorY)
        {
            // Block SCREW/WELD-TEE: +Y = đường chính, +X = nhánh.
            // Thử 2 chiều through, chọn chiều làm nhánh (+X) khớp branchDir nhất.
            // Không mirror Y (dễ đảo trục chính).
            mainDir = mainDir.GetNormal();
            branchDir = branchDir.GetNormal();
            mirrorY = false;

            Vector3d through = mainDir;
            double bestScore = double.MinValue;
            double bestRot = 0.0;

            for (int i = 0; i < 2; i++)
            {
                // R*(0,1) = (-sinθ, cosθ) = through
                double theta = Math.Atan2(-through.X, through.Y);
                Vector3d xDir = new Vector3d(
                    Math.Cos(theta),
                    Math.Sin(theta),
                    0.0);
                double score = xDir.DotProduct(branchDir);
                if (score > bestScore)
                {
                    bestScore = score;
                    bestRot = theta;
                }
                through = -through;
            }

            rotation = bestRot;
        }

        private int EraseShopSourceCurves(
            Transaction tr,
            IEnumerable<ObjectId> sourceCurveIds)
        {
            if (tr == null || sourceCurveIds == null)
                return 0;

            int count = 0;

            foreach (ObjectId id in sourceCurveIds.Distinct())
            {
                if (id.IsNull || id.IsErased)
                    continue;

                try
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForWrite,
                            false) as Entity;

                    if (ent == null || ent.IsErased)
                        continue;

                    if (ent is Line ||
                        ent is Polyline ||
                        ent is Polyline2d ||
                        ent is Polyline3d ||
                        ent is Arc)
                    {
                        ent.Erase();
                        count++;
                    }
                }
                catch { }
            }

            return count;
        }

        private void TryAddShopPipeSizeText(
            PipeUiContext ctx,
            string rawText,
            Point3d position,
            double rotation,
            List<TextData> texts)
        {
            if (texts == null)
                return;

            string str =
                (rawText ?? "")
                    .Replace("\r", " ")
                    .Replace("\n", " ")
                    .Trim();

            if (!TryParseAutomaticPipeSize(
                    ctx,
                    str,
                    out string detectedSize,
                    out double detectedWidth))
                return;

            texts.Add(
                new TextData
                {
                    Position = position,
                    Rotation = rotation,
                    TextString = detectedSize,
                    LayerName =
                        "FF_SHOP_" +
                        CleanLayerText(detectedSize),
                    Width = detectedWidth
                });
        }

        private ShopPipeCandidate CreateShopPipeCandidate(
            Curve curve,
            string sizeText,
            double width)
        {
            if (curve == null ||
                string.IsNullOrWhiteSpace(sizeText) ||
                width <= 0.0)
                return null;

            // FIX40F:
            // Với VẼ SHOP CHỮA CHÁY, Width phải là Ø NGOÀI ống thép.
            // Nếu size là DN trong bảng user cung cấp thì thay width=DN
            // bằng đúng đường kính ngoài.
            double shopOutsideWidth =
                GetFireSteelOutsideDiameterForSize(
                    sizeText,
                    width);

            if (shopOutsideWidth <= 0.0)
                shopOutsideWidth = width;

            try
            {
                Point3d start = curve.StartPoint;
                Point3d end = curve.EndPoint;

                Vector3d startDir =
                    GetShopCurveDirection(
                        curve,
                        true);
                Vector3d endDir =
                    GetShopCurveDirection(
                        curve,
                        false);

                if (startDir.Length < 1e-9 ||
                    endDir.Length < 1e-9)
                    return null;

                Vector3d startNormal =
                    GetPlanNormal(startDir);
                Vector3d endNormal =
                    GetPlanNormal(endDir);

                double half = shopOutsideWidth / 2.0;

                string cleanSize =
                    CleanLayerText(sizeText);

                return new ShopPipeCandidate
                {
                    Curve = curve,
                    SizeText = sizeText,
                    Width = shopOutsideWidth,
                    LayerName = "FF_SHOP_" + cleanSize,
                    Start = start,
                    End = end,
                    StartLeft = start + startNormal * half,
                    StartRight = start - startNormal * half,
                    EndLeft = end + endNormal * half,
                    EndRight = end - endNormal * half
                };
            }
            catch
            {
                return null;
            }
        }

        /// <summary>
        /// True nếu curve chỉ là 1 đoạn thẳng (không gãy góc).
        /// </summary>
        private bool IsShopStraightCurve(Curve curve)
        {
            if (curve == null)
                return false;

            if (curve is Line)
                return true;

            if (curve is Polyline pl)
            {
                if (pl.NumberOfVertices < 2)
                    return false;

                Vector3d? firstDir = null;

                for (int i = 0; i < pl.NumberOfVertices - 1; i++)
                {
                    if (pl.GetSegmentType(i) != SegmentType.Line)
                        return false;

                    Point2d a = pl.GetPoint2dAt(i);
                    Point2d b = pl.GetPoint2dAt(i + 1);
                    Vector3d d =
                        new Vector3d(b.X - a.X, b.Y - a.Y, 0.0);

                    if (d.Length < 1e-9)
                        continue;

                    d = d.GetNormal();

                    if (firstDir == null)
                    {
                        firstDir = d;
                        continue;
                    }

                    double ang =
                        GetShopAngleDegrees(firstDir.Value, d);

                    // Lệch > 5° coi là có góc gãy
                    if (ang > 5.0 && ang < 175.0)
                        return false;
                }

                return firstDir != null;
            }

            return false;
        }

        private List<ShopPipeCandidate>
            CreateShopSplitCandidatesFromTexts(
                Curve curve,
                List<TextProjectionData> projections)
        {
            List<ShopPipeCandidate> result =
                new List<ShopPipeCandidate>();

            if (curve == null ||
                projections == null ||
                projections.Count < 2 ||
                !(curve is Line ||
                  curve is Polyline ||
                  curve is Polyline2d ||
                  curve is Polyline3d))
            {
                return result;
            }

            // QUAN TRỌNG: không được cắt polyline có góc thành Line (d1→d2)
            // vì Line là đường CHÉO (chord), phá góc vuông gốc.
            // Chỉ split khi đường nguồn là 1 đoạn thẳng.
            if (!IsShopStraightCurve(curve))
                return result;

            List<TextProjectionData> ordered =
                projections
                    .Where(x =>
                        x != null &&
                        x.Text != null &&
                        x.Text.Width > 0.0)
                    .OrderBy(x => x.DistanceAlongCurve)
                    .ToList();

            if (ordered.Count < 2)
                return result;

            try
            {
                double totalLength =
                    curve.GetDistanceAtParameter(
                        curve.EndParam);

                if (totalLength < 10.0)
                    return result;

                List<double> boundaries =
                    new List<double>();

                boundaries.Add(0.0);

                for (int i = 0; i < ordered.Count - 1; i++)
                {
                    double middle =
                        (ordered[i].DistanceAlongCurve +
                         ordered[i + 1].DistanceAlongCurve) / 2.0;

                    if (middle > 1.0 &&
                        middle < totalLength - 1.0)
                    {
                        boundaries.Add(middle);
                    }
                }

                boundaries.Add(totalLength);

                if (boundaries.Count != ordered.Count + 1)
                    return result;

                for (int i = 0; i < ordered.Count; i++)
                {
                    double d1 = boundaries[i];
                    double d2 = boundaries[i + 1];

                    if (d2 - d1 < 5.0)
                        continue;

                    Point3d p1 =
                        curve.GetPointAtDist(d1);
                    Point3d p2 =
                        curve.GetPointAtDist(d2);

                    if (p1.DistanceTo(p2) < 5.0)
                        continue;

                    Line segment =
                        new Line(p1, p2);

                    ShopPipeCandidate candidate =
                        CreateShopPipeCandidate(
                            segment,
                            ordered[i].Text.TextString,
                            ordered[i].Text.Width);

                    if (candidate != null)
                        result.Add(candidate);
                }
            }
            catch
            {
                result.Clear();
            }

            return result;
        }

        private Vector3d GetShopCurveDirection(
            Curve curve,
            bool atStart)
        {
            try
            {
                double param =
                    atStart
                        ? curve.StartParam
                        : curve.EndParam;

                Vector3d dir =
                    curve.GetFirstDerivative(param);

                if (dir.Length < 1e-9)
                    return Vector3d.XAxis;

                return new Vector3d(
                    dir.X,
                    dir.Y,
                    0.0).GetNormal();
            }
            catch
            {
                try
                {
                    Vector3d dir =
                        curve.EndPoint - curve.StartPoint;

                    if (dir.Length < 1e-9)
                        return Vector3d.XAxis;

                    return new Vector3d(
                        dir.X,
                        dir.Y,
                        0.0).GetNormal();
                }
                catch
                {
                    return Vector3d.XAxis;
                }
            }
        }

        private static Vector3d GetPlanNormal(Vector3d direction)
        {
            Vector3d dir =
                new Vector3d(
                    direction.X,
                    direction.Y,
                    0.0);

            if (dir.Length < 1e-9)
                return Vector3d.YAxis;

            dir = dir.GetNormal();
            return new Vector3d(-dir.Y, dir.X, 0.0).GetNormal();
        }

        private static double ComputeShopFittingGap(double pipeWidth)
        {
            // gap ≈ 1/4 bề rộng ống, kẹp trong [min, max]
            // đủ chỗ cho mặt bích block, không dư khúc dài.
            double g =
                Math.Max(
                    ShopFittingGapMin,
                    pipeWidth * ShopFittingGapRatio);

            if (g > ShopFittingGapMax)
                g = ShopFittingGapMax;

            return g;
        }

        private HashSet<string> BuildShopConnectedEndKeys(
            List<ShopJointNode> nodes)
        {
            HashSet<string> keys =
                new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);

            if (nodes == null)
                return keys;

            foreach (ShopJointNode node in nodes)
            {
                if (node == null ||
                    node.Arms == null ||
                    node.Arms.Count < 2)
                {
                    continue;
                }

                // CHỈ chừa khe khi thật sự sẽ có phụ kiện.
                // Đoạn thẳng cùng DN (2 nhánh thẳng hàng) KHÔNG cắt.
                if (!ShopNodeNeedsFitting(node))
                    continue;

                keys.Add(ShopPointKey(node.Point));
            }

            return keys;
        }

        /// <summary>
        /// Nút cần phụ kiện (co/tê/giảm) — mới được rút ngắn ống.
        /// </summary>
        private bool ShopNodeNeedsFitting(ShopJointNode node)
        {
            if (node == null || node.Arms == null)
                return false;

            int n = node.Arms.Count;

            // Tê / chữ thập
            if (n >= 3)
                return true;

            if (n != 2)
                return false;

            ShopJointArm a = node.Arms[0];
            ShopJointArm b = node.Arms[1];
            if (a == null || b == null)
                return false;

            double included =
                GetShopAngleDegrees(a.Direction, b.Direction);
            double turn =
                Math.Abs(180.0 - included);

            // Cùng hướng (thẳng): chỉ cần giảm nếu khác DN
            if (turn <= ShopStraightAngleToleranceDeg)
            {
                string sa = CleanLayerText(a.SizeText ?? "");
                string sb = CleanLayerText(b.SizeText ?? "");
                if (string.IsNullOrWhiteSpace(sa) ||
                    string.IsNullOrWhiteSpace(sb))
                    return false;

                // Cùng size → nối thẳng, không cắt ống
                if (string.Equals(
                        sa,
                        sb,
                        StringComparison.OrdinalIgnoreCase))
                    return false;

                // Khác size → có giảm
                return true;
            }

            // Co 45 / co 90
            if (Math.Abs(turn - 90.0) <= ShopElbowAngleToleranceDeg)
                return true;

            if (Math.Abs(turn - 45.0) <= ShopElbowAngleToleranceDeg)
                return true;

            return false;
        }

        private static string ShopPointKey(Point3d p)
        {
            // Làm tròn theo tolerance để so khớp điểm nút
            double t = ShopDuplicateNodeTolerance;
            long x = (long)Math.Round(p.X / t);
            long y = (long)Math.Round(p.Y / t);
            return x.ToString() + ":" + y.ToString();
        }

        private bool IsShopConnectedEnd(
            Point3d point,
            List<ShopFittingGapInfo> fittingGaps)
        {
            return TryFindShopFittingGap(
                point,
                fittingGaps,
                out _,
                out double half) && half > 1.0;
        }

        private double GetShopGapAtPoint(
            Point3d point,
            List<ShopFittingGapInfo> fittingGaps,
            double pipeWidth)
        {
            if (TryFindShopFittingGap(
                    point,
                    fittingGaps,
                    out _,
                    out double half))
            {
                return half;
            }
            return 0;
        }

        /// <summary>
        /// Tìm phụ kiện gần đầu ống (trong bán kính half + tol).
        /// </summary>
        private bool TryFindShopFittingGap(
            Point3d pipeEnd,
            List<ShopFittingGapInfo> fittingGaps,
            out Point3d joint,
            out double half)
        {
            joint = Point3d.Origin;
            half = 0;

            if (fittingGaps == null || fittingGaps.Count == 0)
                return false;

            double bestDist = double.MaxValue;
            ShopFittingGapInfo best = null;

            foreach (ShopFittingGapInfo g in fittingGaps)
            {
                if (g == null || g.HalfLength <= 1.0)
                    continue;

                double d = pipeEnd.DistanceTo(g.Joint);
                // Cho phép đầu ống lệch khỏi nút tới half + 150
                double maxReach =
                    g.HalfLength + Math.Max(150.0, ShopJointTolerance);

                if (d <= maxReach && d < bestDist)
                {
                    bestDist = d;
                    best = g;
                }
            }

            if (best == null)
                return false;

            joint = best.Joint;
            half = best.HalfLength;
            return true;
        }

        private void RecordShopFittingGap(
            List<ShopFittingGapInfo> fittingGaps,
            Point3d joint,
            double half)
        {
            // GIỮ NGUYÊN hành vi cũ cho REDUCER:
            // không hướng, không DN => áp cho hai đầu giảm như trước.
            RecordShopFittingGapDirectional(
                fittingGaps,
                joint,
                half,
                new Vector3d(0.0, 0.0, 0.0),
                "");
        }

        private void RecordShopFittingGapDirectional(
            List<ShopFittingGapInfo> fittingGaps,
            Point3d joint,
            double half,
            Vector3d direction,
            string sizeText)
        {
            if (fittingGaps == null || half <= 1.0)
                return;

            Vector3d dir =
                new Vector3d(
                    direction.X,
                    direction.Y,
                    0.0);

            if (dir.Length > 1e-9)
                dir = dir.GetNormal();

            string sizeKey =
                CleanLayerText(sizeText ?? "");

            for (int i = 0; i < fittingGaps.Count; i++)
            {
                ShopFittingGapInfo oldGap =
                    fittingGaps[i];

                if (oldGap == null ||
                    oldGap.Joint.DistanceTo(joint) >
                        ShopDuplicateNodeTolerance)
                {
                    continue;
                }

                // Gap legacy của REDUCER: chỉ gộp với legacy khác.
                bool oldDirectional =
                    oldGap.Direction.Length > 1e-9 ||
                    !string.IsNullOrWhiteSpace(
                        oldGap.SizeText);

                bool newDirectional =
                    dir.Length > 1e-9 ||
                    !string.IsNullOrWhiteSpace(
                        sizeKey);

                if (oldDirectional != newDirectional)
                    continue;

                if (!newDirectional)
                {
                    if (half > oldGap.HalfLength)
                        oldGap.HalfLength = half;
                    return;
                }

                string oldSize =
                    CleanLayerText(
                        oldGap.SizeText ?? "");

                if (!string.Equals(
                        oldSize,
                        sizeKey,
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (oldGap.Direction.Length < 1e-9 ||
                    dir.Length < 1e-9)
                {
                    continue;
                }

                double angle =
                    GetShopAngleDegrees(
                        oldGap.Direction,
                        dir);

                // Cùng chân/cùng hướng mới gộp.
                if (angle > 8.0)
                    continue;

                if (half > oldGap.HalfLength)
                    oldGap.HalfLength = half;

                return;
            }

            fittingGaps.Add(
                new ShopFittingGapInfo
                {
                    Joint = joint,
                    HalfLength = half,
                    Direction = dir,
                    SizeText = sizeText ?? ""
                });
        }

        private bool ShopFittingGapAppliesToPipe(
            ShopFittingGapInfo gap,
            ShopPipeCandidate pipe,
            Vector3d pipeDirection)
        {
            if (gap == null ||
                pipe == null ||
                gap.HalfLength <= 1.0)
            {
                return false;
            }

            // Legacy gap = reducer cũ => GIỮ NGUYÊN, áp như code đang chạy tốt.
            bool directional =
                gap.Direction.Length > 1e-9 ||
                !string.IsNullOrWhiteSpace(
                    gap.SizeText);

            if (!directional)
                return true;

            string gapSize =
                CleanLayerText(
                    gap.SizeText ?? "");
            string pipeSize =
                CleanLayerText(
                    pipe.SizeText ?? "");

            if (!string.IsNullOrWhiteSpace(gapSize) &&
                !string.IsNullOrWhiteSpace(pipeSize) &&
                !string.Equals(
                    gapSize,
                    pipeSize,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3d pd =
                new Vector3d(
                    pipeDirection.X,
                    pipeDirection.Y,
                    0.0);

            if (gap.Direction.Length < 1e-9 ||
                pd.Length < 1e-9)
            {
                return true;
            }

            pd = pd.GetNormal();

            double angle =
                GetShopAngleDegrees(
                    gap.Direction,
                    pd);

            // Pipe có thể đang duyệt theo chiều ngược lại:
            // so theo TRỤC, không bắt dấu vector.
            double axisError =
                Math.Min(
                    angle,
                    Math.Abs(180.0 - angle));

            return axisError <=
                Math.Max(
                    10.0,
                    ShopStraightAngleToleranceDeg);
        }

        private int DrawShopParallelPipeWithGaps(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            ShopPipeCandidate pipe,
            List<ShopFittingGapInfo> fittingGaps)
        {
            if (pipe == null || pipe.Curve == null)
                return 0;

            // Line thẳng: rút khe tại đầu VÀ tại phụ kiện nằm giữa đoạn (tê)
            if (pipe.Curve is Line)
            {
                Point3d start = pipe.Start;
                Point3d end = pipe.End;
                Vector3d dir = end - start;
                double len = dir.Length;
                if (len < 1e-6)
                    return 0;
                dir = dir.GetNormal();

                // Danh sách mốc dọc đoạn: 0, joints, len
                List<Tuple<double, double>> cuts =
                    new List<Tuple<double, double>>();
                // Tuple: distanceAlong, halfGap (0 = endpoint no gap)

                cuts.Add(Tuple.Create(0.0, 0.0));

                if (fittingGaps != null)
                {
                    double reach =
                        Math.Max(
                            ShopJointTolerance,
                            Math.Max(pipe.Width * 3.0, 150.0));

                    foreach (ShopFittingGapInfo g in fittingGaps)
                    {
                        if (!ShopFittingGapAppliesToPipe(
                                g,
                                pipe,
                                dir))
                        {
                            continue;
                        }

                        Vector3d toJ = g.Joint - start;
                        double along = toJ.DotProduct(dir);

                        // Cho phép joint hơi ngoài 2 đầu đoạn
                        if (along < -reach || along > len + reach)
                            continue;

                        along = Math.Max(0.0, Math.Min(len, along));
                        Point3d proj = start + dir * along;

                        // Khoảng cách vuông góc tới tâm ống
                        if (PlanDistance(proj, g.Joint) > reach)
                            continue;

                        // Dùng đúng half đã đo — không phóng to (gây hở)
                        cuts.Add(Tuple.Create(along, g.HalfLength));
                    }
                }

                cuts.Add(Tuple.Create(len, 0.0));
                cuts = cuts
                    .OrderBy(c => c.Item1)
                    .ToList();

                // Gộp mốc trùng
                List<Tuple<double, double>> merged =
                    new List<Tuple<double, double>>();
                foreach (var c in cuts)
                {
                    if (merged.Count == 0)
                    {
                        merged.Add(c);
                        continue;
                    }
                    var last = merged[merged.Count - 1];
                    if (Math.Abs(c.Item1 - last.Item1) <= 1.0)
                    {
                        // Giữ half lớn hơn
                        if (c.Item2 > last.Item2)
                            merged[merged.Count - 1] =
                                Tuple.Create(last.Item1, c.Item2);
                    }
                    else
                        merged.Add(c);
                }

                Vector3d normal = GetPlanNormal(dir);
                double half = pipe.Width / 2.0;
                int drawn = 0;

                for (int i = 0; i < merged.Count - 1; i++)
                {
                    double d0 = merged[i].Item1;
                    double gap0 = merged[i].Item2;
                    double d1 = merged[i + 1].Item1;
                    double gap1 = merged[i + 1].Item2;

                    // Rút half tại mỗi đầu mốc (phụ kiện)
                    double a = d0 + gap0;
                    double b = d1 - gap1;
                    if (b - a < 5.0)
                        continue;

                    Point3d p0 = start + dir * a;
                    Point3d p1 = start + dir * b;

                    AppendShopLine(
                        tr, db, btr,
                        p0 + normal * half,
                        p1 + normal * half,
                        pipe.LayerName);
                    AppendShopLine(
                        tr, db, btr,
                        p0 - normal * half,
                        p1 - normal * half,
                        pipe.LayerName);
                    AppendShopCenterline(
                        tr, db, btr, p0, p1, pipe.LayerName);
                    drawn += 3;
                }

                return drawn;
            }

            // Polyline: vẽ từng đoạn + rút khe tại nút phụ kiện
            return DrawShopParallelPipe(
                tr, db, btr, pipe, fittingGaps);
        }

        private int DrawShopParallelPipe(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            ShopPipeCandidate pipe,
            List<ShopFittingGapInfo> fittingGaps = null)
        {
            if (pipe == null || pipe.Curve == null)
                return 0;

            int count = 0;
            double half = pipe.Width / 2.0;

            count += DrawShopManualParallelCurves(
                tr,
                db,
                btr,
                pipe.Curve,
                pipe,
                half,
                pipe.LayerName,
                fittingGaps);

            if (count > 0)
            {
                count += DrawShopCenterlineForCurve(
                    tr, db, btr, pipe);
                return count;
            }

            // Chỉ fallback Start→End khi nguồn là 1 đoạn thẳng.
            // Polyline gãy góc: CẤM vẽ chéo từ đầu tới cuối.
            if (!IsShopStraightCurve(pipe.Curve))
                return 0;

            AppendShopLine(
                tr,
                db,
                btr,
                pipe.StartLeft,
                pipe.EndLeft,
                pipe.LayerName);

            AppendShopLine(
                tr,
                db,
                btr,
                pipe.StartRight,
                pipe.EndRight,
                pipe.LayerName);

            AppendShopCenterline(
                tr, db, btr,
                pipe.Start, pipe.End,
                pipe.LayerName);

            return 3;
        }

        private int DrawShopManualParallelCurves(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Curve curve,
            ShopPipeCandidate pipe,
            double half,
            string layerName,
            List<ShopFittingGapInfo> fittingGaps = null)
        {
            if (curve == null || pipe == null)
                return 0;

            if (curve is Arc arc)
            {
                return DrawShopParallelArcPair(
                    tr,
                    db,
                    btr,
                    arc,
                    half,
                    layerName);
            }

            if (curve is Line)
            {
                AppendShopLine(
                    tr,
                    db,
                    btr,
                    pipe.StartLeft,
                    pipe.EndLeft,
                    layerName);

                AppendShopLine(
                    tr,
                    db,
                    btr,
                    pipe.StartRight,
                    pipe.EndRight,
                    layerName);

                return 2;
            }

            if (curve is Polyline pl &&
                pl.NumberOfVertices >= 2)
            {
                int count = 0;

                // Từng đoạn thẳng polyline — góc vuông giữ nguyên.
                // Rút khe CHỈ tại nút có phụ kiện (co/tê/giảm).
                for (int i = 0; i < pl.NumberOfVertices - 1; i++)
                {
                    if (pl.GetSegmentType(i) != SegmentType.Line)
                        continue;

                    Point2d p1 = pl.GetPoint2dAt(i);
                    Point2d p2 = pl.GetPoint2dAt(i + 1);
                    Vector3d dir =
                        new Vector3d(
                            p2.X - p1.X,
                            p2.Y - p1.Y,
                            0.0);

                    if (dir.Length < 1e-9)
                        continue;

                    dir = dir.GetNormal();
                    Vector3d normal = GetPlanNormal(dir);

                    Point3d a =
                        new Point3d(p1.X, p1.Y, curve.StartPoint.Z);
                    Point3d b =
                        new Point3d(p2.X, p2.Y, curve.StartPoint.Z);

                    double segLen = a.DistanceTo(b);
                    if (segLen < 1e-9)
                        continue;

                    // Cắt tại mọi phụ kiện nằm trên đoạn (kể cả tê giữa đoạn)
                    List<Tuple<double, double>> cuts =
                        new List<Tuple<double, double>>();
                    cuts.Add(Tuple.Create(0.0, 0.0));
                    cuts.Add(Tuple.Create(segLen, 0.0));

                    if (fittingGaps != null)
                    {
                        double reach =
                            Math.Max(
                                ShopJointTolerance,
                                Math.Max(half * 6.0, 150.0));

                        foreach (ShopFittingGapInfo g in fittingGaps)
                        {
                            if (!ShopFittingGapAppliesToPipe(
                                    g,
                                    pipe,
                                    dir))
                            {
                                continue;
                            }

                            Vector3d toJ = g.Joint - a;
                            double along = toJ.DotProduct(dir);
                            if (along < -reach || along > segLen + reach)
                                continue;

                            along = Math.Max(0.0, Math.Min(segLen, along));
                            Point3d proj = a + dir * along;
                            if (PlanDistance(proj, g.Joint) > reach)
                                continue;

                            cuts.Add(Tuple.Create(along, g.HalfLength));
                        }
                    }

                    cuts = cuts.OrderBy(c => c.Item1).ToList();
                    List<Tuple<double, double>> merged =
                        new List<Tuple<double, double>>();
                    foreach (var c in cuts)
                    {
                        if (merged.Count == 0)
                        {
                            merged.Add(c);
                            continue;
                        }
                        var last = merged[merged.Count - 1];
                        if (Math.Abs(c.Item1 - last.Item1) <= 1.0)
                        {
                            if (c.Item2 > last.Item2)
                                merged[merged.Count - 1] =
                                    Tuple.Create(last.Item1, c.Item2);
                        }
                        else
                            merged.Add(c);
                    }

                    for (int k = 0; k < merged.Count - 1; k++)
                    {
                        double d0 = merged[k].Item1;
                        double g0 = merged[k].Item2;
                        double d1 = merged[k + 1].Item1;
                        double g1 = merged[k + 1].Item2;
                        double aa = d0 + g0;
                        double bb = d1 - g1;
                        if (bb - aa < 5.0)
                            continue;

                        Point3d p0 = a + dir * aa;
                        Point3d p1pt = a + dir * bb;

                        AppendShopLine(
                            tr, db, btr,
                            p0 + normal * half,
                            p1pt + normal * half,
                            layerName);
                        AppendShopLine(
                            tr, db, btr,
                            p0 - normal * half,
                            p1pt - normal * half,
                            layerName);
                        count += 2;
                    }
                }

                return count;
            }

            return 0;
        }

        private int DrawShopParallelArcPair(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Arc arc,
            double half,
            string layerName)
        {
            int count = 0;

            double r1 = arc.Radius + half;
            double r2 = arc.Radius - half;

            if (r1 > 1.0)
            {
                Arc a1 =
                    new Arc(
                        arc.Center,
                        r1,
                        arc.StartAngle,
                        arc.EndAngle);

                a1.SetDatabaseDefaults(db);
                ApplyShopEntityStyle(a1, layerName);
                btr.AppendEntity(a1);
                tr.AddNewlyCreatedDBObject(a1, true);
                count++;
            }

            if (r2 > 1.0)
            {
                Arc a2 =
                    new Arc(
                        arc.Center,
                        r2,
                        arc.StartAngle,
                        arc.EndAngle);

                a2.SetDatabaseDefaults(db);
                ApplyShopEntityStyle(a2, layerName);
                btr.AppendEntity(a2);
                tr.AddNewlyCreatedDBObject(a2, true);
                count++;
            }

            return count;
        }

        private int DrawShopOffsetCurves(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Curve curve,
            double offset,
            string layerName)
        {
            int count = 0;
            DBObjectCollection offsets = null;

            try
            {
                offsets = curve.GetOffsetCurves(offset);

                foreach (DBObject obj in offsets)
                {
                    if (obj is Entity ent)
                    {
                        ent.SetDatabaseDefaults(db);
                        ApplyShopEntityStyle(ent, layerName);

                        btr.AppendEntity(ent);
                        tr.AddNewlyCreatedDBObject(ent, true);
                        count++;
                    }
                    else
                    {
                        obj.Dispose();
                    }
                }
            }
            catch
            {
                if (offsets != null)
                {
                    foreach (DBObject obj in offsets)
                    {
                        try { obj.Dispose(); }
                        catch { }
                    }
                }
            }

            return count;
        }

        private int TryDrawShopReducer(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            ShopPipeCandidate a,
            ShopPipeCandidate b,
            string libraryPath,
            List<Point3d> reducerJointPoints)
        {
            if (a == null || b == null ||
                Math.Abs(a.Width - b.Width) < 0.5)
                return 0;

            const double jointTolerance = 150.0;

            if (a.End.DistanceTo(b.Start) <= jointTolerance)
            {
                if (!RegisterShopReducerJoint(
                        reducerJointPoints,
                        a.End,
                        b.Start))
                    return 0;

                return DrawShopReducerFromLibraryOrOutline(
                    tr, db, btr,
                    a.EndLeft, a.EndRight,
                    b.StartLeft, b.StartRight,
                    a, b, libraryPath);
            }

            if (a.Start.DistanceTo(b.End) <= jointTolerance)
            {
                if (!RegisterShopReducerJoint(
                        reducerJointPoints,
                        a.Start,
                        b.End))
                    return 0;

                return DrawShopReducerFromLibraryOrOutline(
                    tr, db, btr,
                    a.StartLeft, a.StartRight,
                    b.EndLeft, b.EndRight,
                    a, b, libraryPath);
            }

            if (a.Start.DistanceTo(b.Start) <= jointTolerance)
            {
                if (!RegisterShopReducerJoint(
                        reducerJointPoints,
                        a.Start,
                        b.Start))
                    return 0;

                return DrawShopReducerFromLibraryOrOutline(
                    tr, db, btr,
                    a.StartLeft, a.StartRight,
                    b.StartLeft, b.StartRight,
                    a, b, libraryPath);
            }

            if (a.End.DistanceTo(b.End) <= jointTolerance)
            {
                if (!RegisterShopReducerJoint(
                        reducerJointPoints,
                        a.End,
                        b.End))
                    return 0;

                return DrawShopReducerFromLibraryOrOutline(
                    tr, db, btr,
                    a.EndLeft, a.EndRight,
                    b.EndLeft, b.EndRight,
                    a, b, libraryPath);
            }

            return 0;
        }

        private static bool RegisterShopReducerJoint(
            List<Point3d> reducerJointPoints,
            Point3d a,
            Point3d b)
        {
            if (reducerJointPoints == null)
                return true;

            // Dùng đúng vị trí hình học thay vì key làm tròn 50 mm.
            // Nếu nhiều cặp segment cùng gặp tại một nút, chỉ chèn 1 phụ kiện.
            const double duplicateTolerance = 150.0;

            Point3d mid =
                MidPoint(a, b);

            if (reducerJointPoints.Any(
                    p => p.DistanceTo(mid) <= duplicateTolerance))
            {
                return false;
            }

            reducerJointPoints.Add(mid);
            return true;
        }

        private int DrawShopReducerFromLibraryOrOutline(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d aLeft,
            Point3d aRight,
            Point3d bLeft,
            Point3d bRight,
            ShopPipeCandidate a,
            ShopPipeCandidate b,
            string libraryPath)
        {
            string layerName =
                "FF_SHOP_GIAM_" +
                CleanLayerText(a.SizeText) +
                "-" +
                CleanLayerText(b.SizeText);

            EnsureShopLayerExists(tr, db, layerName);

            Point3d centerA =
                MidPoint(aLeft, aRight);
            Point3d centerB =
                MidPoint(bLeft, bRight);
            Point3d insertPoint =
                MidPoint(centerA, centerB);
            Vector3d direction =
                centerB - centerA;

            double rotation =
                direction.Length > 1e-9
                    ? Math.Atan2(direction.Y, direction.X)
                    : 0.0;

            if (TryInsertShopLibraryFitting(
                    tr,
                    db,
                    btr,
                    libraryPath,
                    "REDUCER",
                    a.SizeText,
                    b.SizeText,
                    insertPoint,
                    rotation,
                    layerName))
                return 1;

            return DrawShopReducerLines(
                tr,
                db,
                btr,
                aLeft,
                aRight,
                bLeft,
                bRight,
                a,
                b);
        }

        private int DrawShopReducerLines(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d aLeft,
            Point3d aRight,
            Point3d bLeft,
            Point3d bRight,
            ShopPipeCandidate a,
            ShopPipeCandidate b)
        {
            string layerName =
                "FF_SHOP_GIAM_" +
                CleanLayerText(a.SizeText) +
                "-" +
                CleanLayerText(b.SizeText);

            EnsureShopLayerExists(tr, db, layerName);

            double normalPair =
                aLeft.DistanceTo(bLeft) +
                aRight.DistanceTo(bRight);
            double crossPair =
                aLeft.DistanceTo(bRight) +
                aRight.DistanceTo(bLeft);

            if (crossPair < normalPair)
            {
                AppendShopLine(tr, db, btr, aLeft, aRight, layerName);
                AppendShopLine(tr, db, btr, bLeft, bRight, layerName);
                AppendShopLine(tr, db, btr, aLeft, bRight, layerName);
                AppendShopLine(tr, db, btr, aRight, bLeft, layerName);
            }
            else
            {
                AppendShopLine(tr, db, btr, aLeft, aRight, layerName);
                AppendShopLine(tr, db, btr, bLeft, bRight, layerName);
                AppendShopLine(tr, db, btr, aLeft, bLeft, layerName);
                AppendShopLine(tr, db, btr, aRight, bRight, layerName);
            }

            return 1;
        }

        private int DrawShopCenterlineForCurve(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            ShopPipeCandidate pipe)
        {
            if (pipe == null || pipe.Curve == null)
                return 0;

            if (pipe.Curve is Line)
            {
                AppendShopCenterline(
                    tr, db, btr,
                    pipe.Start, pipe.End,
                    pipe.LayerName);
                return 1;
            }

            if (pipe.Curve is Polyline pl &&
                pl.NumberOfVertices >= 2)
            {
                int count = 0;
                for (int i = 0; i < pl.NumberOfVertices - 1; i++)
                {
                    if (pl.GetSegmentType(i) != SegmentType.Line)
                        continue;

                    Point3d a = pl.GetPoint3dAt(i);
                    Point3d b = pl.GetPoint3dAt(i + 1);
                    if (a.DistanceTo(b) < 1e-6)
                        continue;

                    AppendShopCenterline(
                        tr, db, btr, a, b, pipe.LayerName);
                    count++;
                }
                return count;
            }

            try
            {
                AppendShopCenterline(
                    tr, db, btr,
                    pipe.Start, pipe.End,
                    pipe.LayerName);
                return 1;
            }
            catch
            {
                return 0;
            }
        }

        private void AppendShopCenterline(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d start,
            Point3d end,
            string pipeLayerName)
        {
            if (tr == null || db == null || btr == null)
                return;

            if (start.DistanceTo(end) < 1e-6)
                return;

            string pipeLayer =
                (pipeLayerName ?? "")
                    .Trim();

            string centerLayer;

            if (pipeLayer.StartsWith(
                    "CTN_SHOP_",
                    StringComparison.OrdinalIgnoreCase))
            {
                centerLayer =
                    "CTN_SHOP_TAM_" +
                    CleanLayerText(
                        pipeLayer.Substring(
                            "CTN_SHOP_".Length));
            }
            else
            {
                centerLayer =
                    "FF_SHOP_TAM_" +
                    CleanLayerText(
                        pipeLayer.Replace(
                            "FF_SHOP_",
                            ""));
            }

            EnsureShopLayerExists(tr, db, centerLayer);

            string dashName =
                EnsureShopDashedLinetype(tr, db);

            // Gán linetype nét đứt cho layer tâm
            try
            {
                if (!string.IsNullOrEmpty(dashName))
                {
                    LayerTable lt =
                        (LayerTable)tr.GetObject(
                            db.LayerTableId,
                            OpenMode.ForRead);

                    if (lt.Has(centerLayer))
                    {
                        LayerTableRecord ltr =
                            (LayerTableRecord)tr.GetObject(
                                lt[centerLayer],
                                OpenMode.ForWrite);

                        ltr.LinetypeObjectId =
                            ((LinetypeTable)tr.GetObject(
                                db.LinetypeTableId,
                                OpenMode.ForRead))[dashName];
                    }
                }
            }
            catch { }

            Line line = new Line(start, end);
            line.SetDatabaseDefaults(db);
            line.Layer = centerLayer;
            line.Color =
                Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                    ColorMethod.ByAci,
                    8); // xám — đường tâm
            line.LineWeight = Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight000;

            if (!string.IsNullOrEmpty(dashName))
            {
                try { line.Linetype = dashName; }
                catch { }
            }

            // Bản vẽ mm: scale đủ lớn để thấy nét đứt rõ
            double segLen = start.DistanceTo(end);
            double ltScale =
                segLen > 5000 ? 200.0 :
                segLen > 1000 ? 100.0 :
                50.0;

            try { line.LinetypeScale = ltScale; }
            catch { }

            btr.AppendEntity(line);
            tr.AddNewlyCreatedDBObject(line, true);
        }

        private string EnsureShopDashedLinetype(
            Transaction tr,
            Database db)
        {
            string[] candidates =
            {
                "DASHED", "DASH", "HIDDEN", "CENTER",
                "ACAD_ISO02W100", "ACAD_ISO04W100",
                "ACAD_ISO03W100"
            };

            try
            {
                LinetypeTable ltt =
                    (LinetypeTable)tr.GetObject(
                        db.LinetypeTableId,
                        OpenMode.ForRead);

                foreach (string name in candidates)
                {
                    if (ltt.Has(name))
                        return name;
                }
            }
            catch { }

            // Load từ acad.lin / acadiso.lin nếu chưa có
            string[] linFiles =
            {
                "acad.lin",
                "acadiso.lin"
            };

            foreach (string lin in linFiles)
            {
                foreach (string name in candidates)
                {
                    try
                    {
                        db.LoadLineTypeFile(name, lin);

                        LinetypeTable ltt2 =
                            (LinetypeTable)tr.GetObject(
                                db.LinetypeTableId,
                                OpenMode.ForRead);

                        if (ltt2.Has(name))
                            return name;
                    }
                    catch { }
                }
            }

            return "";
        }

        private void AppendShopLine(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            Point3d start,
            Point3d end,
            string layerName)
        {
            if (start.DistanceTo(end) < 1.0)
                return;

            Line line = new Line(start, end);
            line.SetDatabaseDefaults(db);
            ApplyShopEntityStyle(line, layerName);

            btr.AppendEntity(line);
            tr.AddNewlyCreatedDBObject(line, true);
        }

        private string InferShopMaterialFromPipes(
            List<ShopPipeCandidate> shopPipes,
            string fallbackMaterial)
        {
            if (shopPipes == null || shopPipes.Count == 0)
                return fallbackMaterial ?? "TRÁNG KẼM";

            Dictionary<string, int> votes =
                new Dictionary<string, int>(
                    StringComparer.OrdinalIgnoreCase);

            foreach (ShopPipeCandidate pipe in shopPipes)
            {
                string layer = "";
                try
                {
                    layer = pipe?.Curve?.Layer ?? "";
                }
                catch
                {
                    layer = "";
                }

                if (string.IsNullOrWhiteSpace(layer))
                    layer = pipe?.LayerName ?? "";

                string mat =
                    DetectShopMaterialFromLayerOrText(layer);

                if (string.IsNullOrWhiteSpace(mat))
                    continue;

                if (!votes.ContainsKey(mat))
                    votes[mat] = 0;
                votes[mat]++;
            }

            if (votes.Count > 0)
            {
                return votes
                    .OrderByDescending(x => x.Value)
                    .ThenBy(x => x.Key)
                    .First()
                    .Key;
            }

            return fallbackMaterial ?? "TRÁNG KẼM";
        }

        private string DetectShopMaterialFromLayerOrText(
            string text)
        {
            string u =
                BoDauTiengViet(text ?? "")
                    .ToUpperInvariant();

            if (string.IsNullOrWhiteSpace(u))
                return "";

            if (u.Contains("PPR"))
                return "PPR";
            if (u.Contains("UPVC") ||
                (u.Contains("PVC") && !u.Contains("PPR")))
                return "UPVC";
            if (u.Contains("HDPE"))
                return "HDPE";
            if (u.Contains("INOX") || u.Contains("STAINLESS"))
                return "INOX";
            if (u.Contains("NHUNG") || u.Contains("HOTDIP"))
                return "NHÚNG NÓNG";
            if (u.Contains("THEPDEN") ||
                (u.Contains("THEP") && u.Contains("DEN")) ||
                u.Contains("BLACKSTEEL"))
                return "THÉP ĐEN";
            if (u.Contains("TRANG") ||
                u.Contains("KEM") ||
                u.Contains("GALV") ||
                u.Contains("STEEL"))
                return "TRÁNG KẼM";

            return "";
        }

        private string FindShopFittingLibraryPath(
            string materialName,
            Database db)
        {
            List<string> fileNames =
                GetShopLibraryFileNames(materialName);

            if (fileNames == null || fileNames.Count == 0)
                return "";

            List<string> folders =
                new List<string>();

            try
            {
                string dllFolder =
                    Path.GetDirectoryName(
                        Assembly.GetExecutingAssembly().Location);

                if (!string.IsNullOrWhiteSpace(dllFolder))
                    folders.Add(dllFolder);
            }
            catch { }

            try
            {
                string dwgFolder =
                    Path.GetDirectoryName(db?.Filename ?? "");

                if (!string.IsNullOrWhiteSpace(dwgFolder))
                    folders.Add(dwgFolder);
            }
            catch { }

            try
            {
                string current = Directory.GetCurrentDirectory();
                if (!string.IsNullOrWhiteSpace(current))
                    folders.Add(current);
            }
            catch { }

            // Dùng đúng tên 3 file thư viện hiện tại của người dùng.
            foreach (string folder in folders.Distinct(
                StringComparer.OrdinalIgnoreCase))
            {
                foreach (string fileName in fileNames)
                {
                    try
                    {
                        string path = Path.Combine(folder, fileName);
                        if (File.Exists(path))
                            return path;
                    }
                    catch { }
                }

                // Fallback: quét thư mục theo tên gần đúng (không phân biệt hoa thường)
                try
                {
                    if (!Directory.Exists(folder))
                        continue;

                    string[] existing =
                        Directory.GetFiles(folder, "*.dwg");

                    foreach (string fileName in fileNames)
                    {
                        string target =
                            Path.GetFileName(fileName)
                                .ToLowerInvariant()
                                .Replace(" ", "");

                        foreach (string existingPath in existing)
                        {
                            string name =
                                Path.GetFileName(existingPath)
                                    .ToLowerInvariant()
                                    .Replace(" ", "");

                            if (name == target ||
                                name.Contains(
                                    target.Replace(".dwg", "")))
                            {
                                return existingPath;
                            }
                        }
                    }
                }
                catch { }
            }

            return "";
        }

        private List<string> GetShopLibraryFileNames(string materialName)
        {
            string u =
                BoDauTiengViet(materialName ?? "");

            if (u.Contains("PPR"))
            {
                return new List<string>
                {
                    "Thu vien PPR.dwg",
                    "Thu vien PPR.DWG",
                    "ThuvienPPR.dwg",
                    "PPR.dwg"
                };
            }

            if (u.Contains("UPVC") ||
                u.Contains("PVC") ||
                u.Contains("HDPE"))
            {
                return new List<string>
                {
                    // TÊN MỚI người dùng đang dùng.
                    "Thu vien uPVC.dwg",
                    "Thu vien uPVC.DWG",
                    "Thu vien UPVC.dwg",
                    "ThuvienuPVC.dwg",
                    "uPVC.dwg",
                    "UPVC.dwg"
                };
            }

            if (u.Contains("TRANG") ||
                u.Contains("KEM") ||
                u.Contains("THEP") ||
                u.Contains("NHUNG") ||
                u.Contains("STEEL") ||
                u.Contains("INOX") ||
                u.Contains("DEN"))
            {
                return new List<string>
                {
                    "Thu vien STEEL.dwg",
                    "Thu vien STEEL.DWG",
                    "ThuvienSTEEL.dwg",
                    "STEEL.dwg"
                };
            }

            // Mặc định thử STEEL (thép/tráng kẽm phổ biến cho chữa cháy)
            return new List<string>
            {
                "Thu vien STEEL.dwg",
                "Thu vien STEEL.DWG"
            };
        }

        /// <summary>
        /// Block thư viện SCREW/WELD: tâm hình học = điểm chèn trên đường tâm.
        /// Không offset theo AnalyzeShopFittingPlacement (dễ lệch 1 bên).
        /// </summary>
        /// <summary>
        /// Tâm hình học + nửa chiều dài theo trục dài của block (local).
        /// </summary>
        /// <summary>
        /// Khoảng rút ống tại co/tê = khoảng từ base point tới mép xa nhất
        /// theo phương X hoặc Y (chân co).
        /// </summary>
        private double EstimateShopElbowLegGap(
            Transaction tr,
            ObjectId blockId)
        {
            try
            {
                BlockTableRecord rec =
                    tr.GetObject(blockId, OpenMode.ForRead, false)
                        as BlockTableRecord;
                if (rec == null)
                    return 0;

                Extents3d? ext = null;
                foreach (ObjectId id in rec)
                {
                    Entity ent =
                        tr.GetObject(id, OpenMode.ForRead, false)
                            as Entity;
                    if (ent == null || ent.IsErased)
                        continue;
                    try
                    {
                        Extents3d e = ent.GeometricExtents;
                        if (ext == null) ext = e;
                        else
                        {
                            Extents3d cur = ext.Value;
                            cur.AddExtents(e);
                            ext = cur;
                        }
                    }
                    catch { }
                }

                if (ext == null)
                    return 0;

                Extents3d box = ext.Value;
                // Từ origin (0,0) ra mép — lấy cạnh lớn hơn (chân co)
                double toX =
                    Math.Max(
                        Math.Abs(box.MinPoint.X),
                        Math.Abs(box.MaxPoint.X));
                double toY =
                    Math.Max(
                        Math.Abs(box.MinPoint.Y),
                        Math.Abs(box.MaxPoint.Y));
                // Lấy cạnh NHỎ hơn = chân co/tê thật (max sẽ lấy luôn nhánh dài → hở to)
                double leg = Math.Min(toX, toY);
                if (leg < 1.0)
                    leg = Math.Max(toX, toY);
                // 0.82: ống chạm sát mặt bích, không hở khúc
                return leg > 1.0 ? leg * 0.82 : 0;
            }
            catch
            {
                return 0;
            }
        }

        private bool TryGetShopBlockLocalCenter(
            Transaction tr,
            ObjectId blockId,
            out Point3d localCenter,
            out double halfAlongAxis)
        {
            localCenter = Point3d.Origin;
            halfAlongAxis = 0;

            try
            {
                BlockTableRecord rec =
                    tr.GetObject(blockId, OpenMode.ForRead, false)
                        as BlockTableRecord;

                if (rec == null)
                    return false;

                Extents3d? ext = null;

                foreach (ObjectId id in rec)
                {
                    Entity ent =
                        tr.GetObject(id, OpenMode.ForRead, false)
                            as Entity;

                    if (ent == null || ent.IsErased)
                        continue;

                    try
                    {
                        Extents3d e = ent.GeometricExtents;
                        if (ext == null)
                            ext = e;
                        else
                        {
                            Extents3d cur = ext.Value;
                            cur.AddExtents(e);
                            ext = cur;
                        }
                    }
                    catch { }
                }

                if (ext == null)
                    return false;

                Extents3d box = ext.Value;
                localCenter =
                    new Point3d(
                        (box.MinPoint.X + box.MaxPoint.X) * 0.5,
                        (box.MinPoint.Y + box.MaxPoint.Y) * 0.5,
                        (box.MinPoint.Z + box.MaxPoint.Z) * 0.5);

                double dx = Math.Abs(box.MaxPoint.X - box.MinPoint.X);
                double dy = Math.Abs(box.MaxPoint.Y - box.MinPoint.Y);
                // Trục ống trong block giảm/co thường là X
                double along = dx >= dy ? dx : dy;
                halfAlongAxis = along * 0.5;

                return halfAlongAxis > 1.0;
            }
            catch
            {
                return false;
            }
        }

        private static bool IsShopSimpleCenterBlock(
            string blockName,
            string fittingType)
        {
            string key = NormalizeShopKey(blockName ?? "");
            string typeKey = NormalizeShopKey(fittingType ?? "");

            if (key.StartsWith("SCREW") ||
                key.StartsWith("WELD"))
            {
                return true;
            }

            // Co / giảm / tê chuẩn thư viện user
            if (key.Contains("ELB90") ||
                key.Contains("ELB45") ||
                key.Contains("ELBOW") ||
                (key.Contains("RED") && !key.Contains("THREAD")) ||
                IsStrictShopTeeName(key) ||
                key.Contains("GIAM"))
            {
                return true;
            }

            if (IsElbow90Key(typeKey) ||
                IsElbow45Key(typeKey) ||
                IsTeeKey(typeKey) ||
                IsReducerKey(typeKey))
            {
                // Mặc định phụ kiện shop: chèn tâm
                return true;
            }

            return false;
        }

        private bool TryInsertShopLibraryFitting(
            Transaction tr,
            Database db,
            BlockTableRecord btr,
            string libraryPath,
            string fittingType,
            string fromSize,
            string toSize,
            Point3d insertPoint,
            double rotation,
            string layerName,
            bool mirrorY = false,
            List<ShopFittingGapInfo> fittingGaps = null,
            List<Vector3d> exactTargetDirections = null)
        {
            if (string.IsNullOrWhiteSpace(libraryPath) ||
                !File.Exists(libraryPath))
                return false;

            string blockName =
                FindShopFittingBlockName(
                    libraryPath,
                    fittingType,
                    fromSize,
                    toSize);

            if (string.IsNullOrWhiteSpace(blockName))
            {
                try
                {
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .DocumentManager
                        .MdiActiveDocument?
                        .Editor
                        .WriteMessage(
                            $"\n[SHOP {ShopSmartBuild}] KHÔNG TÌM BLOCK " +
                            $"{fittingType} {fromSize}->{toSize}");
                }
                catch { }

                return false;
            }

            ObjectId blockId =
                EnsureExternalBlockImported(
                    tr,
                    db,
                    libraryPath,
                    blockName);

            if (blockId.IsNull)
                return false;

            NormalizeShopImportedBlock(tr, blockId);

            // QUAN TRỌNG: không dùng Base Point của block làm tâm nối.
            // Đọc hình học thật của block, tìm các cổng nối rồi suy ra tâm
            // hình học (virtual intersection) của Co/Tê/Giảm.
            ShopFittingPlacementInfo placement =
                AnalyzeShopFittingPlacement(
                    blockId,
                    fittingType,
                    fromSize,
                    toSize);

            // FIX40P: PPR phải đọc đúng tâm các mặt nối ngoài thật.
            bool isCtnPprFitting =
                IsCtnPprLibraryBlockName(
                    blockName);

            if (isCtnPprFitting)
            {
                ShopFittingPlacementInfo pprPlacement =
                    AnalyzeCtnPprFittingTruePorts(
                        blockId,
                        fittingType,
                        fromSize,
                        toSize);

                if (pprPlacement != null)
                    placement = pprPlacement;
            }

            // FIX41 - CTN PPR:
            // OutwardDirection lấy từ tiếp tuyến/normal của nét block có thể
            // bị đảo 180 độ, nhất là block PPR có nested/dynamic geometry.
            // Tâm cổng so với Anchor mới là hướng nối thật và ổn định nhất.
            // Chuẩn hóa trước khi giải rotation để Co/Tê không quay ngược
            // (ví dụ tuyến rẽ xuống nhưng block lại quay chân lên trên).
            NormalizeShopPlacementPortDirections(
                placement);

            double desiredPrimaryAngle = rotation;
            double finalRotation = rotation;

            // FIX33: không mirror block bằng scale âm.
            // mirrorY chỉ còn dùng như "hướng rẽ trái/phải" để tính desired ports.
            double finalMirrorY = 1.0;
            Point3d basePoint = insertPoint;

            // REDUCER: căn tâm hình học trên đường tâm (thẳng).
            // CO / TÊ: dùng Base Point gốc block tại nút (thường là giao 2 trục tâm).
            //   Không dùng bbox center — sẽ lệch, ống đâm vào thân phụ kiện.
            bool isReducer =
                IsReducerKey(NormalizeShopKey(fittingType ?? "")) ||
                NormalizeShopKey(blockName ?? "").Contains("RED") ||
                NormalizeShopKey(blockName ?? "").Contains("GIAM");

            bool isElbowOrTee =
                IsElbow90Key(NormalizeShopKey(fittingType ?? "")) ||
                IsElbow45Key(NormalizeShopKey(fittingType ?? "")) ||
                IsTeeKey(NormalizeShopKey(fittingType ?? "")) ||
                NormalizeShopKey(blockName ?? "").Contains("ELB") ||
                IsStrictShopTeeName(blockName ?? "") ||
                NormalizeShopKey(blockName ?? "").Contains("CO");

            finalRotation = rotation;
            finalMirrorY = 1.0;
            basePoint = insertPoint;

            if (isReducer &&
                !isCtnPprFitting &&
                IsShopSimpleCenterBlock(blockName, fittingType))
            {
                Point3d localCenter;
                double halfAlong;
                if (TryGetShopBlockLocalCenter(
                        tr,
                        blockId,
                        out localCenter,
                        out halfAlong))
                {
                    Vector3d local =
                        new Vector3d(
                            localCenter.X,
                            localCenter.Y * finalMirrorY,
                            localCenter.Z);

                    Vector3d world =
                        local.RotateBy(
                            finalRotation,
                            Vector3d.ZAxis);

                    basePoint = insertPoint - world;

                    RecordShopFittingGap(
                        fittingGaps,
                        insertPoint,
                        halfAlong);
                }
            }
            else if (isElbowOrTee ||
                     (isCtnPprFitting &&
                      isReducer))
            {
                // FIX40P: CO/TÊ và riêng reducer PPR đều căn theo port thật.
                // Reducer thép vẫn giữ nguyên logic cũ.

                bool hasExactTargets =
                    exactTargetDirections != null &&
                    exactTargetDirections.Count >= 2;

                bool resolvedByExactTargets =
                    placement != null &&
                    hasExactTargets &&
                    TryResolveShopFittingTransformToTargets(
                        fittingType,
                        placement,
                        exactTargetDirections,
                        out finalRotation,
                        out finalMirrorY);

                bool resolvedByLegacyDirection =
                    placement != null &&
                    !hasExactTargets &&
                    TryResolveShopFittingTransform(
                        fittingType,
                        placement,
                        desiredPrimaryAngle,
                        mirrorY,
                        out finalRotation,
                        out finalMirrorY);

                if (placement != null &&
                    placement.Ports != null &&
                    placement.Ports.Count >= 2 &&
                    (resolvedByExactTargets ||
                     resolvedByLegacyDirection))
                {
                    Vector3d localAnchor =
                        new Vector3d(
                            placement.Anchor.X,
                            placement.Anchor.Y * finalMirrorY,
                            placement.Anchor.Z);

                    Vector3d transformedAnchor =
                        localAnchor.RotateBy(
                            finalRotation,
                            Vector3d.ZAxis);

                    // Đưa giao tâm thật của các port vào đúng node mạng ống.
                    basePoint =
                        insertPoint -
                        transformedAnchor;

                }
                else
                {
                    // Không đoán orientation cho Co/Tê.
                    // Nếu không đọc được port thật thì thà KHÔNG CHÈN
                    // còn hơn chèn sai hướng / sai vị trí.
                    try
                    {
                        Autodesk.AutoCAD.ApplicationServices.Core.Application
                            .DocumentManager
                            .MdiActiveDocument?
                            .Editor
                            .WriteMessage(
                                $"\n[SHOP FIX39] BỎ QUA {fittingType} " +
                                $"{fromSize}->{toSize}: không xác định được port/rotation.");
                    }
                    catch
                    {
                    }

                    return false;
                }
            }
            else if (placement != null &&
                     placement.Ports.Count > 0 &&
                     TryResolveShopFittingTransform(
                         fittingType,
                         placement,
                         desiredPrimaryAngle,
                         mirrorY,
                         out finalRotation,
                         out finalMirrorY))
            {
                Vector3d localAnchor =
                    new Vector3d(
                        placement.Anchor.X,
                        placement.Anchor.Y * finalMirrorY,
                        placement.Anchor.Z);

                Vector3d transformedAnchor =
                    localAnchor.RotateBy(
                        finalRotation,
                        Vector3d.ZAxis);

                basePoint = insertPoint - transformedAnchor;
            }

            // Chống chèn trùng theo tâm nối / vị trí chèn trên đường tâm.
            foreach (ObjectId existingId in btr)
            {
                BlockReference existing =
                    tr.GetObject(
                        existingId,
                        OpenMode.ForRead,
                        false) as BlockReference;

                if (existing == null ||
                    existing.IsErased ||
                    existing.BlockTableRecord != blockId)
                {
                    continue;
                }

                try
                {
                    if (placement != null &&
                        placement.Ports.Count > 0)
                    {
                        Point3d existingAnchor =
                            placement.Anchor.TransformBy(
                                existing.BlockTransform);

                        if (existingAnchor.DistanceTo(insertPoint) <= 100.0)
                            return true;
                    }
                    else if (existing.Position.DistanceTo(insertPoint) <= 100.0)
                    {
                        return true;
                    }
                }
                catch
                {
                    if (existing.Position.DistanceTo(basePoint) <= 100.0)
                        return true;
                }
            }

            BlockReference br =
                new BlockReference(
                    basePoint,
                    blockId);

            br.SetDatabaseDefaults(db);
            br.Layer = layerName;
            br.Rotation = finalRotation;
            // Dynamic Block: chỉ xoay, không dùng scale âm để mirror.
            br.ScaleFactors =
                new Scale3d(
                    1.0,
                    1.0,
                    1.0);
            br.Color =
                Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                    ColorMethod.ByAci,
                    GetShopVisibleAciColor(layerName));
            br.LineWeight = Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight000;
            br.Transparency =
                new Autodesk.AutoCAD.Colors.Transparency((byte)255);
            br.Visible = true;

            btr.AppendEntity(br);
            tr.AddNewlyCreatedDBObject(br, true);

            try
            {
                double degree =
                    finalRotation * 180.0 / Math.PI;

                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument?
                    .Editor
                    .WriteMessage(
                        $"\n[SHOP FIX39] {fittingType} {fromSize}->{toSize} " +
                        $"| block={blockName} | rotation={degree:0.##}° | mirror=NO" +
                        (IsTeeKey(NormalizeShopKey(fittingType ?? ""))
                            ? $" | teePorts={(placement?.Ports?.Count ?? 0)}"
                            : ""));
            }
            catch
            {
            }

            // FIX24: riêng co cuối đầu phun, đổi CHÍNH block vừa chèn
            // sang trạng thái "đi xuống". Không dùng mirror mặt bằng.
            bool isSprinklerDropElbow =
                layerName != null &&
                layerName.StartsWith(
                    "FF_SHOP_CO90_DAUPHUN_",
                    StringComparison.OrdinalIgnoreCase);

            if (isSprinklerDropElbow)
            {
                TrySetShopFittingVisibilityOnReference(
                    br,
                    preferDown: true,
                    preferHorizontal: false);
            }

            // FIX23: CO/TÊ rút từng ống đúng tới mặt cổng thật.
            // REDUCER không đi qua đoạn này => giữ nguyên cơ chế đang chạy tốt.
            bool useTrueDirectionalPortGaps =
                isElbowOrTee ||
                (isCtnPprFitting &&
                 isReducer);

            if (useTrueDirectionalPortGaps &&
                !isSprinklerDropElbow &&
                placement != null &&
                placement.Ports != null &&
                placement.Ports.Count >= 2 &&
                fittingGaps != null)
            {
                string typeKey =
                    NormalizeShopKey(
                        fittingType ?? "");

                for (int portIndex = 0;
                    portIndex < placement.Ports.Count;
                    portIndex++)
                {
                    ShopFittingPortInfo port =
                        placement.Ports[portIndex];

                    if (port == null)
                        continue;

                    Point3d worldPort;

                    try
                    {
                        worldPort =
                            port.Center.TransformBy(
                                br.BlockTransform);
                    }
                    catch
                    {
                        continue;
                    }

                    Vector3d portDir =
                        new Vector3d(
                            worldPort.X - insertPoint.X,
                            worldPort.Y - insertPoint.Y,
                            0.0);

                    double portGap =
                        portDir.Length;

                    if (portGap <= 1.0)
                        continue;

                    portDir =
                        portDir.GetNormal();

                    // FIX41 - CTN PPR:
                    // Một số block động còn chứa geometry của trạng thái ẩn.
                    // Bộ dò port có thể chọn một điểm rất xa, làm ống bị cắt
                    // hụt khỏi mặt Co/Giảm như hình người dùng gửi.
                    // GeometricExtents của chính reference vừa chèn phản ánh
                    // phần đang hiển thị; không cho gap vượt quá biên đó.
                    if (isCtnPprFitting)
                    {
                        double visibleReach =
                            GetShopVisibleBlockReach(
                                br,
                                insertPoint,
                                portDir);

                        if (visibleReach > 1.0)
                        {
                            portGap =
                                Math.Min(
                                    portGap,
                                    visibleReach);
                        }
                    }

                    string portSize =
                        fromSize;

                    if (IsTeeKey(typeKey) &&
                        placement.Ports.Count >= 3)
                    {
                        // AnalyzeShopTeePorts luôn xếp:
                        // 0,1 = main ; 2 = branch.
                        portSize =
                            portIndex == 2
                                ? toSize
                                : fromSize;
                    }
                    else if (isCtnPprFitting &&
                             isReducer)
                    {
                        // RED-D25x20 PPR: gán đúng size cho từng mặt nối.
                        portSize =
                            GetCtnPprGapPortSize(
                                port,
                                fromSize,
                                toSize);
                    }

                    // PPR cho overlap 1.5 mm vào mặt phụ kiện để không hở khi regen.
                    double faceOverlap =
                        isCtnPprFitting
                            ? 1.5
                            : 0.5;

                    double finalPortGap =
                        Math.Max(
                            1.0,
                            portGap -
                            faceOverlap);

                    RecordShopFittingGapDirectional(
                        fittingGaps,
                        insertPoint,
                        finalPortGap,
                        portDir,
                        portSize);

                    if (isCtnPprFitting)
                    {
                        try
                        {
                            Autodesk.AutoCAD.ApplicationServices.Core.Application
                                .DocumentManager
                                .MdiActiveDocument?
                                .Editor
                                .WriteMessage(
                                    $"\n[CTN PPR GAP FIX40P] " +
                                    $"{blockName} | port={portIndex + 1} | " +
                                    $"size={portSize} | gap={finalPortGap:0.##}");
                        }
                        catch
                        {
                        }
                    }
                }
            }

            // Co đầu phun: chỉ cần rút ống ngang tới thân co.
            // Chân còn lại đi xuống Z nên không tạo gap thứ hai trên mặt bằng.
            if (isSprinklerDropElbow &&
                fittingGaps != null)
            {
                double legGap =
                    EstimateShopElbowLegGap(
                        tr,
                        blockId);

                if (legGap < 1.0)
                {
                    double dn =
                        ParseShopDnNumber(
                            NormalizeShopDnToken(
                                fromSize));

                    if (dn <= 0)
                        dn = 25.0;

                    legGap =
                        Math.Max(
                            8.0,
                            dn * 0.40);
                }

                Vector3d inletDir =
                    new Vector3d(
                        Math.Cos(rotation),
                        Math.Sin(rotation),
                        0.0);

                RecordShopFittingGapDirectional(
                    fittingGaps,
                    insertPoint,
                    Math.Max(
                        1.0,
                        legGap),
                    inletDir,
                    fromSize);
            }

            // Fallback gap:
            // - REDUCER: giữ nguyên logic cũ.
            // - CO/TÊ: chỉ fallback nếu thực sự không có directional port gap.
            if (fittingGaps != null)
            {
                bool already = false;

                foreach (ShopFittingGapInfo g in fittingGaps)
                {
                    if (g == null ||
                        g.Joint.DistanceTo(insertPoint) >
                            ShopDuplicateNodeTolerance)
                    {
                        continue;
                    }

                    if (!useTrueDirectionalPortGaps ||
                        isSprinklerDropElbow ||
                        g.Direction.Length > 1e-9)
                    {
                        already = true;
                        break;
                    }
                }

                if (!already)
                {
                    double half =
                        EstimateShopFittingHalfLength(
                            tr,
                            blockId,
                            placement,
                            fromSize,
                            toSize);

                    RecordShopFittingGap(
                        fittingGaps,
                        insertPoint,
                        half);
                }
            }

            return true;
        }

        private double EstimateShopFittingHalfLength(
            Transaction tr,
            ObjectId blockId,
            ShopFittingPlacementInfo placement,
            string fromSize,
            string toSize)
        {
            // 1) Extents block — ưu tiên cho SCREW/WELD chèn tâm
            //    Giảm/co thường dài theo trục X trong định nghĩa block.
            try
            {
                BlockTableRecord rec =
                    tr.GetObject(blockId, OpenMode.ForRead, false)
                        as BlockTableRecord;
                if (rec != null)
                {
                    Extents3d? ext = null;
                    foreach (ObjectId id in rec)
                    {
                        Entity ent =
                            tr.GetObject(id, OpenMode.ForRead, false)
                                as Entity;
                        if (ent == null || ent.IsErased)
                            continue;
                        try
                        {
                            Extents3d e = ent.GeometricExtents;
                            if (ext == null)
                                ext = e;
                            else
                            {
                                Extents3d cur = ext.Value;
                                cur.AddExtents(e);
                                ext = cur;
                            }
                        }
                        catch { }
                    }
                    if (ext != null)
                    {
                        Extents3d e = ext.Value;
                        double dx = Math.Abs(e.MaxPoint.X - e.MinPoint.X);
                        double dy = Math.Abs(e.MaxPoint.Y - e.MinPoint.Y);
                        // Trục dọc ống = cạnh dài hơn (giảm/co)
                        double along = Math.Max(dx, dy);
                        if (along > 2.0)
                        {
                            // Một chút nhỏ hơn 0.5 để nét ống chạm mặt bích, không hở
                            return along * 0.48;
                        }
                    }
                }
            }
            catch { }

            // 2) Từ cổng nối đã phân tích
            if (placement != null &&
                placement.Ports != null &&
                placement.Ports.Count > 0)
            {
                double maxDist = 0;
                foreach (ShopFittingPortInfo port in placement.Ports)
                {
                    if (port == null)
                        continue;
                    double d =
                        port.Center.DistanceTo(placement.Anchor);
                    if (d > maxDist)
                        maxDist = d;
                }
                if (maxDist > 1.0)
                    return maxDist;
            }

            // 3) Ước lượng theo DN
            double n1 = ParseShopDnNumber(NormalizeShopDnToken(fromSize));
            double n2 = ParseShopDnNumber(NormalizeShopDnToken(toSize));
            double refN = Math.Max(n1, n2);
            if (refN <= 0)
                refN = 25;
            return Math.Max(12.0, Math.Min(80.0, refN * 0.70));
        }

        private static bool IsCtnPprLibraryBlockName(string blockName)
        {
            if (string.IsNullOrWhiteSpace(blockName)) return false;
            string u = blockName.Trim().ToUpperInvariant();
            return u.Contains(" PPR") || u.EndsWith("PPR", StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>
        /// Ép hướng mỗi port đi từ Anchor ra đúng tâm mặt nối.
        /// Cách này loại bỏ lỗi normal của nét block bị đảo 180 độ.
        /// </summary>
        private void NormalizeShopPlacementPortDirections(
            ShopFittingPlacementInfo placement)
        {
            if (placement == null ||
                placement.Ports == null ||
                placement.Ports.Count == 0)
            {
                return;
            }

            foreach (ShopFittingPortInfo port
                in placement.Ports)
            {
                if (port == null)
                    continue;

                Vector3d radial =
                    new Vector3d(
                        port.Center.X - placement.Anchor.X,
                        port.Center.Y - placement.Anchor.Y,
                        0.0);

                if (radial.Length > 1e-6)
                {
                    port.OutwardDirection =
                        radial.GetNormal();
                }
            }
        }

        /// <summary>
        /// Khoảng từ nút tim ống tới biên hình học đang hiển thị của block
        /// theo một hướng cổng. Dùng để chặn port ảo của block động PPR.
        /// </summary>
        private double GetShopVisibleBlockReach(
            BlockReference blockReference,
            Point3d joint,
            Vector3d direction)
        {
            if (blockReference == null ||
                blockReference.IsErased)
            {
                return 0.0;
            }

            Vector3d dir =
                new Vector3d(
                    direction.X,
                    direction.Y,
                    0.0);

            if (dir.Length < 1e-9)
                return 0.0;

            dir = dir.GetNormal();

            try
            {
                Extents3d ext =
                    blockReference.GeometricExtents;

                Point3d[] corners =
                    new Point3d[]
                    {
                        new Point3d(ext.MinPoint.X, ext.MinPoint.Y, joint.Z),
                        new Point3d(ext.MinPoint.X, ext.MaxPoint.Y, joint.Z),
                        new Point3d(ext.MaxPoint.X, ext.MinPoint.Y, joint.Z),
                        new Point3d(ext.MaxPoint.X, ext.MaxPoint.Y, joint.Z)
                    };

                double reach = 0.0;

                foreach (Point3d corner in corners)
                {
                    Vector3d fromJoint =
                        new Vector3d(
                            corner.X - joint.X,
                            corner.Y - joint.Y,
                            0.0);

                    double projected =
                        fromJoint.DotProduct(dir);

                    if (projected > reach)
                        reach = projected;
                }

                return reach;
            }
            catch
            {
                return 0.0;
            }
        }

        /// <summary>
        /// FIX42 - CTN PPR:
        /// Đọc các mặt nối thật của block PPR ở BẤT KỲ hướng nào.
        /// Không giả định mặt nối phải nằm đúng min/max X,Y của bbox.
        /// Tâm của mỗi đoạn mặt nối là tâm cổng; pháp tuyến hướng ra ngoài
        /// là trục cổng. Sau đó Anchor được tính bằng giao các trục này.
        /// </summary>
        private List<ShopFittingPortInfo>
            BuildCtnPprConnectionFacePorts(
                ObjectId blockId,
                double sizeA,
                double sizeB)
        {
            List<ShopFittingPortInfo> result =
                new List<ShopFittingPortInfo>();

            if (blockId.IsNull)
                return result;

            double minSize =
                new[] { sizeA, sizeB }
                    .Where(x => x > 0.0)
                    .DefaultIfEmpty(20.0)
                    .Min();

            double maxSize =
                new[] { sizeA, sizeB }
                    .Where(x => x > 0.0)
                    .DefaultIfEmpty(20.0)
                    .Max();

            List<ShopStraightSegmentSample> segments =
                new List<ShopStraightSegmentSample>();

            Extents3d? extents = null;
            DBObjectCollection exploded =
                new DBObjectCollection();

            try
            {
                using (BlockReference temp =
                    new BlockReference(
                        Point3d.Origin,
                        blockId))
                {
                    temp.Explode(exploded);
                }

                CollectShopBoundarySegmentsFromObjects(
                    exploded,
                    segments,
                    ref extents,
                    0);
            }
            catch
            {
            }
            finally
            {
                foreach (DBObject obj in exploded)
                {
                    try { obj?.Dispose(); } catch { }
                }
            }

            if (extents == null ||
                segments.Count == 0)
            {
                return result;
            }

            Extents3d box = extents.Value;

            Point3d blockCenter =
                new Point3d(
                    (box.MinPoint.X + box.MaxPoint.X) * 0.5,
                    (box.MinPoint.Y + box.MaxPoint.Y) * 0.5,
                    0.0);

            double boxSpan =
                Math.Max(
                    Math.Abs(box.MaxPoint.X - box.MinPoint.X),
                    Math.Abs(box.MaxPoint.Y - box.MinPoint.Y));

            double minFace =
                Math.Max(2.0, minSize * 0.45);

            double maxFace =
                Math.Max(minFace + 1.0, maxSize * 2.20);

            List<ShopFittingPortInfo> candidates =
                new List<ShopFittingPortInfo>();

            foreach (ShopStraightSegmentSample seg
                in segments)
            {
                if (seg == null ||
                    seg.Length < minFace ||
                    seg.Length > maxFace)
                {
                    continue;
                }

                Vector3d tangent =
                    new Vector3d(
                        seg.B.X - seg.A.X,
                        seg.B.Y - seg.A.Y,
                        0.0);

                if (tangent.Length < 1e-9)
                    continue;

                tangent = tangent.GetNormal();

                Vector3d normal =
                    new Vector3d(
                        -tangent.Y,
                        tangent.X,
                        0.0);

                Vector3d radial =
                    new Vector3d(
                        seg.Mid.X - blockCenter.X,
                        seg.Mid.Y - blockCenter.Y,
                        0.0);

                if (radial.Length < 1e-9)
                    continue;

                radial = radial.GetNormal();

                Vector3d outward =
                    normal.DotProduct(radial) >= 0.0
                        ? normal
                        : -normal;

                // Mặt nối phải gần vuông góc với hướng đi ra ngoài block.
                if (outward.DotProduct(radial) < 0.55)
                    continue;

                double radialDistance =
                    PlanDistance(
                        seg.Mid,
                        blockCenter);

                if (boxSpan > 1e-9 &&
                    radialDistance < boxSpan * 0.16)
                {
                    continue;
                }

                candidates.Add(
                    new ShopFittingPortInfo
                    {
                        Center = seg.Mid,
                        OutwardDirection = outward.GetNormal(),
                        Width = seg.Length,
                        SampleCount = 2
                    });
            }

            if (candidates.Count == 0)
                return result;

            // Gom các mặt cùng hướng. Trong mỗi hướng chỉ giữ mặt ngoài cùng,
            // tránh lấy nhầm đường gân/đường trong thân phụ kiện.
            List<List<ShopFittingPortInfo>> groups =
                new List<List<ShopFittingPortInfo>>();

            foreach (ShopFittingPortInfo candidate
                in candidates)
            {
                List<ShopFittingPortInfo> group =
                    groups.FirstOrDefault(g =>
                    {
                        Vector3d avg =
                            AverageShopDirection(
                                g.Select(x =>
                                    x.OutwardDirection));

                        return avg.Length > 1e-9 &&
                               GetShopAngleDegrees(
                                   avg,
                                   candidate.OutwardDirection) <= 12.0;
                    });

                if (group == null)
                {
                    group =
                        new List<ShopFittingPortInfo>();

                    groups.Add(group);
                }

                group.Add(candidate);
            }

            foreach (List<ShopFittingPortInfo> group
                in groups)
            {
                if (group == null || group.Count == 0)
                    continue;

                Vector3d outward =
                    AverageShopDirection(
                        group.Select(x =>
                            x.OutwardDirection));

                if (outward.Length < 1e-9)
                    continue;

                outward = outward.GetNormal();

                double outerMost =
                    group.Max(p =>
                        p.Center.GetAsVector()
                            .DotProduct(outward));

                double outerBand =
                    Math.Max(
                        1.5,
                        Math.Min(
                            8.0,
                            maxSize * 0.12));

                List<ShopFittingPortInfo> outerFaces =
                    group.Where(p =>
                        Math.Abs(
                            outerMost -
                            p.Center.GetAsVector()
                                .DotProduct(outward)) <= outerBand)
                        .ToList();

                ShopFittingPortInfo best =
                    outerFaces
                        .OrderBy(p =>
                        {
                            double e1 =
                                sizeA > 0.0
                                    ? Math.Abs(p.Width - sizeA)
                                    : double.MaxValue;

                            double e2 =
                                sizeB > 0.0
                                    ? Math.Abs(p.Width - sizeB)
                                    : double.MaxValue;

                            return Math.Min(e1, e2);
                        })
                        .ThenByDescending(p => p.SampleCount)
                        .FirstOrDefault();

                if (best == null)
                    continue;

                result.Add(
                    new ShopFittingPortInfo
                    {
                        Center = best.Center,
                        OutwardDirection = outward,
                        Width = best.Width,
                        SampleCount = best.SampleCount
                    });
            }

            return result;
        }

        private ShopFittingPlacementInfo AnalyzeCtnPprFittingTruePorts(
            ObjectId blockId,
            string fittingType,
            string fromSize,
            string toSize)
        {
            if (blockId.IsNull) return null;

            string key = NormalizeShopKey(fittingType ?? "");

            double d1 = ParseShopDnNumber(NormalizeShopDnToken(fromSize));
            double d2 = ParseShopDnNumber(NormalizeShopDnToken(toSize));
            double refD = Math.Max(d1, d2);
            if (refD <= 0.0) refD = 20.0;

            ShopFittingPlacementInfo placement = null;

            // PASS 1 - đúng nguyên tắc SHOP:
            // tâm mặt nối + trục mặt nối của block phải trùng tim ống.
            List<ShopFittingPortInfo> facePorts =
                BuildCtnPprConnectionFacePorts(
                    blockId,
                    d1,
                    d2);

            placement =
                AnalyzeShopPlacementFromPorts(
                    facePorts,
                    key,
                    fromSize,
                    toSize);

            if (placement != null)
            {
                WriteCtnPprTruePortDiagnostic(
                    "FACE-CENTER",
                    fromSize,
                    toSize,
                    placement);

                return placement;
            }

            // PASS 2 - block có miệng hở không vẽ đường ngang mặt nối:
            // gom hai đầu nét ngoài cùng thành tâm miệng nối.
            List<ShopFittingEndpointSample> outerSamples =
                CollectShopFittingEndpointSamples(
                    blockId,
                    true);

            List<ShopFittingPortInfo> outerPorts =
                BuildShopFittingOuterPortsForLargeWeld(
                    outerSamples,
                    refD);

            placement =
                AnalyzeShopPlacementFromPorts(
                    outerPorts,
                    key,
                    fromSize,
                    toSize);

            if (placement != null)
            {
                WriteCtnPprTruePortDiagnostic(
                    "OPEN-END-CENTER",
                    fromSize,
                    toSize,
                    placement);

                return placement;
            }

            if (IsElbow45Key(key))
            {
                List<ShopFittingPortInfo> obliquePorts =
                    BuildShopElbow45ObliquePorts(blockId, refD);

                placement =
                    AnalyzeShopElbowPorts(
                        obliquePorts,
                        135.0,
                        refD);
                if (placement != null)
                {
                    WriteCtnPprTruePortDiagnostic(
                        "ELB45-OBLIQUE",
                        fromSize,
                        toSize,
                        placement);
                    return placement;
                }
            }

            List<ShopFittingPortInfo> boundaryPorts =
                BuildShopFittingBoundaryPortsForLargeWeld(blockId, refD);

            placement =
                AnalyzeShopPlacementFromPorts(
                    boundaryPorts,
                    key,
                    fromSize,
                    toSize);

            if (placement != null)
            {
                WriteCtnPprTruePortDiagnostic(
                    "BOUNDARY",
                    fromSize,
                    toSize,
                    placement);
                return placement;
            }

            List<ShopFittingEndpointSample> samples =
                CollectShopFittingEndpointSamples(blockId, false);

            List<ShopFittingPortInfo> ports =
                BuildShopFittingPorts(samples);

            placement =
                AnalyzeShopPlacementFromPorts(
                    ports,
                    key,
                    fromSize,
                    toSize);

            if (placement != null)
            {
                WriteCtnPprTruePortDiagnostic(
                    "GENERIC-FALLBACK",
                    fromSize,
                    toSize,
                    placement);
            }

            return placement;
        }

        private void WriteCtnPprTruePortDiagnostic(
            string mode,
            string fromSize,
            string toSize,
            ShopFittingPlacementInfo placement)
        {
            if (placement == null) return;

            try
            {
                string ports =
                    string.Join(
                        " ; ",
                        placement.Ports.Select(
                            (p, i) =>
                                $"P{i + 1}=({p.Center.X:0.##},{p.Center.Y:0.##})/W={p.Width:0.##}"));

                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument?
                    .Editor
                    .WriteMessage(
                        $"\n[CTN PPR PORT FIX42] {mode} " +
                        $"{fromSize}->{toSize} | " +
                        $"Anchor=({placement.Anchor.X:0.##},{placement.Anchor.Y:0.##}) | " +
                        $"{ports}");
            }
            catch
            {
            }
        }

        private string GetCtnPprGapPortSize(
            ShopFittingPortInfo port,
            string fromSize,
            string toSize)
        {
            if (port == null) return fromSize ?? "";

            double fromD = ParseShopDnNumber(NormalizeShopDnToken(fromSize));
            double toD = ParseShopDnNumber(NormalizeShopDnToken(toSize));

            if (fromD <= 0.0) return toSize ?? "";
            if (toD <= 0.0 || Math.Abs(fromD - toD) <= 0.01)
                return fromSize ?? "";

            if (port.Width > 0.0)
            {
                double eFrom = Math.Abs(port.Width - fromD);
                double eTo = Math.Abs(port.Width - toD);
                return eTo < eFrom ? (toSize ?? "") : (fromSize ?? "");
            }

            return fromSize ?? "";
        }


        private ShopFittingPlacementInfo AnalyzeShopFittingPlacement(
            ObjectId blockId,
            string fittingType,
            string fromSize = "",
            string toSize = "")
        {
            if (blockId.IsNull)
                return null;

            string key =
                NormalizeShopKey(
                    fittingType);

            // ========================================================
            // PASS 1 - logic chuẩn FIX34
            // ========================================================
            List<ShopFittingEndpointSample> samples =
                CollectShopFittingEndpointSamples(
                    blockId,
                    false);

            List<ShopFittingPortInfo> ports =
                BuildShopFittingPorts(
                    samples);

            ShopFittingPlacementInfo placement =
                AnalyzeShopPlacementFromPorts(
                    ports,
                    key,
                    fromSize,
                    toSize);

            if (placement != null)
                return placement;

            // ========================================================
            // PASS 1B - FIX37: riêng ELB45 ở MỌI DN.
            //
            // Block ELB45 có một mặt nối nghiêng nên endpoint/biên ngang-dọc
            // dễ bị bỏ sót. Đọc trực tiếp các đoạn thẳng có kích thước giống
            // "mặt cổng", suy ra outward normal và chọn cặp tạo ~135°.
            // ========================================================
            if (IsElbow45Key(key))
            {
                double elbowDn =
                    Math.Max(
                        ParseShopDnNumber(
                            NormalizeShopDnToken(
                                fromSize)),
                        ParseShopDnNumber(
                            NormalizeShopDnToken(
                                toSize)));

                if (elbowDn <= 0.0)
                    elbowDn = 25.0;

                List<ShopFittingPortInfo> obliquePorts =
                    BuildShopElbow45ObliquePorts(
                        blockId,
                        elbowDn);

                placement =
                    AnalyzeShopElbowPorts(
                        obliquePorts,
                        135.0,
                        elbowDn);

                if (placement != null)
                {
                    try
                    {
                        Autodesk.AutoCAD.ApplicationServices.Core.Application
                            .DocumentManager
                            .MdiActiveDocument?
                            .Editor
                            .WriteMessage(
                                $"\n[SHOP FIX39] ELB45 PORT FALLBACK OK: " +
                                $"{fromSize} | ports={obliquePorts.Count}");
                    }
                    catch
                    {
                    }

                    return placement;
                }
            }

            // ========================================================
            // PASS 2 - FIX35:
            // WELD DN100 / DN125 / DN150 có block lớn và geometry phức tạp.
            // Nhiều corner của mặt bích/cổ nối bị bộ lọc "giao điểm nội bộ"
            // của PASS 1 loại mất, dẫn đến không đủ 2/3 port.
            //
            // Chỉ mở fallback cho DN >= 100 để KHÔNG làm thay đổi
            // behavior của DN15...DN80 đang chạy ổn.
            // ========================================================
            double dn1 =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        fromSize));

            double dn2 =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        toSize));

            double refDn =
                Math.Max(
                    dn1,
                    dn2);

            if (refDn < 100.0)
                return null;

            // Reducer đang chạy ổn bằng logic riêng -> không đụng.
            if (IsReducerKey(key))
                return null;

            // ========================================================
            // PASS 2A - FIX36: đọc CỔNG theo BIÊN NGOÀI block.
            // WELD DN100-150 có nhiều nét trong thân/mặt bích; endpoint
            // nội bộ không đáng tin bằng các mặt nối nằm ở biên ngoài.
            // ========================================================
            List<ShopFittingPortInfo> boundaryPorts =
                BuildShopFittingBoundaryPortsForLargeWeld(
                    blockId,
                    refDn);

            placement =
                AnalyzeShopPlacementFromPorts(
                    boundaryPorts,
                    key,
                    fromSize,
                    toSize);

            if (placement != null)
            {
                try
                {
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .DocumentManager
                        .MdiActiveDocument?
                        .Editor
                        .WriteMessage(
                            $"\n[SHOP FIX39] BOUNDARY PORTS OK: " +
                            $"{fittingType} {fromSize}->{toSize} | " +
                            $"DNref={refDn:0.##} | ports={boundaryPorts.Count}");
                }
                catch
                {
                }

                return placement;
            }

            // PASS 2B - fallback endpoint thô của FIX35.
            List<ShopFittingEndpointSample> rawSamples =
                CollectShopFittingEndpointSamples(
                    blockId,
                    true);

            if (rawSamples == null ||
                rawSamples.Count < 2)
            {
                return null;
            }

            List<ShopFittingPortInfo> outerPorts =
                BuildShopFittingOuterPortsForLargeWeld(
                    rawSamples,
                    refDn);

            placement =
                AnalyzeShopPlacementFromPorts(
                    outerPorts,
                    key,
                    fromSize,
                    toSize);

            if (placement != null)
            {
                try
                {
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .DocumentManager
                        .MdiActiveDocument?
                        .Editor
                        .WriteMessage(
                            $"\n[SHOP FIX39] LARGE-WELD PORT FALLBACK OK: " +
                            $"{fittingType} {fromSize}->{toSize} | " +
                            $"DNref={refDn:0.##} | raw={rawSamples.Count} | " +
                            $"ports={outerPorts.Count}");
                }
                catch
                {
                }

                return placement;
            }

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument?
                    .Editor
                    .WriteMessage(
                        $"\n[SHOP FIX39] LARGE-WELD PORT FALLBACK FAIL: " +
                        $"{fittingType} {fromSize}->{toSize} | " +
                        $"DNref={refDn:0.##} | raw={rawSamples.Count} | " +
                        $"ports={outerPorts.Count}");
            }
            catch
            {
            }

            return null;
        }

        private ShopFittingPlacementInfo AnalyzeShopPlacementFromPorts(
            List<ShopFittingPortInfo> ports,
            string fittingKey,
            string fromSize,
            string toSize)
        {
            if (ports == null ||
                ports.Count < 2)
            {
                return null;
            }

            if (IsReducerKey(fittingKey))
                return AnalyzeShopReducerPorts(
                    ports,
                    fromSize,
                    toSize);

            if (IsTeeKey(fittingKey))
            {
                return AnalyzeShopTeePorts(
                    ports,
                    fromSize,
                    toSize);
            }

            if (IsElbow45Key(fittingKey))
                return AnalyzeShopElbowPorts(
                    ports,
                    135.0,
                    Math.Max(
                        ParseShopDnNumber(
                            NormalizeShopDnToken(fromSize)),
                        ParseShopDnNumber(
                            NormalizeShopDnToken(toSize))));

            if (IsElbow90Key(fittingKey))
                return AnalyzeShopElbowPorts(
                    ports,
                    90.0,
                    Math.Max(
                        ParseShopDnNumber(
                            NormalizeShopDnToken(fromSize)),
                        ParseShopDnNumber(
                            NormalizeShopDnToken(toSize))));

            return null;
        }

        private List<ShopFittingEndpointSample> CollectShopFittingEndpointSamples(
            ObjectId blockId,
            bool keepJunctionSamples = false)
        {
            List<ShopFittingEndpointSample> result =
                new List<ShopFittingEndpointSample>();

            DBObjectCollection exploded =
                new DBObjectCollection();

            try
            {
                using (BlockReference temp =
                    new BlockReference(Point3d.Origin, blockId))
                {
                    temp.Explode(exploded);
                }

                CollectShopFittingEndpointSamplesFromObjects(
                    exploded,
                    result,
                    0);
            }
            catch
            {
            }
            finally
            {
                foreach (DBObject obj in exploded)
                {
                    try { obj?.Dispose(); } catch { }
                }
            }

            // FIX35: ở fallback cho WELD DN100-150, giữ endpoint thô.
            // Các block lớn thường dùng nhiều line/polyline tạo mặt bích,
            // nên corner của CỔNG THẬT cũng có nhiều hướng và sẽ bị bộ lọc
            // topology phía dưới loại nhầm.
            if (keepJunctionSamples)
            {
                return result
                    .Where(s =>
                        s != null &&
                        s.OutwardDirection.Length > 1e-9)
                    .ToList();
            }

            // Lọc theo topology: góc kín của hình vẽ thường có từ 2 đường
            // cùng chạm một điểm nhưng khác hướng. Đó KHÔNG phải cổng nối.
            // Cổng thật thường là đầu hở: chỉ có một hướng đi vào fitting.
            List<List<ShopFittingEndpointSample>> pointClusters =
                new List<List<ShopFittingEndpointSample>>();

            foreach (ShopFittingEndpointSample sample in result)
            {
                if (sample == null ||
                    sample.OutwardDirection.Length < 1e-9)
                    continue;

                List<ShopFittingEndpointSample> cluster =
                    pointClusters.FirstOrDefault(g =>
                        g.Count > 0 &&
                        g[0].Point.DistanceTo(sample.Point) <= 0.75);

                if (cluster == null)
                {
                    cluster =
                        new List<ShopFittingEndpointSample>();
                    pointClusters.Add(cluster);
                }

                cluster.Add(sample);
            }

            List<ShopFittingEndpointSample> dedup =
                new List<ShopFittingEndpointSample>();

            foreach (List<ShopFittingEndpointSample> cluster in pointClusters)
            {
                if (cluster.Count == 0)
                    continue;

                Vector3d first =
                    cluster[0].OutwardDirection.GetNormal();

                bool hasDifferentDirection =
                    cluster.Skip(1).Any(x =>
                        GetShopAngleDegrees(
                            first,
                            x.OutwardDirection) > 8.0);

                if (hasDifferentDirection)
                {
                    // Đây là giao điểm hình học nội bộ của block.
                    continue;
                }

                Vector3d avg =
                    AverageShopDirection(
                        cluster.Select(x => x.OutwardDirection));

                if (avg.Length < 1e-9)
                    continue;

                dedup.Add(
                    new ShopFittingEndpointSample
                    {
                        Point = new Point3d(
                            cluster.Average(x => x.Point.X),
                            cluster.Average(x => x.Point.Y),
                            0.0),
                        OutwardDirection = avg.GetNormal()
                    });
            }

            return dedup;
        }

        private void CollectShopFittingEndpointSamplesFromObjects(
            DBObjectCollection objects,
            List<ShopFittingEndpointSample> result,
            int depth)
        {
            if (objects == null ||
                result == null ||
                depth > 6)
            {
                return;
            }

            foreach (DBObject obj in objects)
            {
                if (obj is BlockReference nested)
                {
                    DBObjectCollection nestedObjects =
                        new DBObjectCollection();

                    try
                    {
                        nested.Explode(nestedObjects);
                        CollectShopFittingEndpointSamplesFromObjects(
                            nestedObjects,
                            result,
                            depth + 1);
                    }
                    catch { }
                    finally
                    {
                        foreach (DBObject nestedObj in nestedObjects)
                        {
                            try { nestedObj?.Dispose(); } catch { }
                        }
                    }

                    continue;
                }

                if (obj is Line line)
                {
                    AddShopCurveEndSamples(
                        line,
                        result);
                    continue;
                }

                if (obj is Arc arc)
                {
                    AddShopCurveEndSamples(
                        arc,
                        result);
                    continue;
                }

                if (obj is Polyline pl)
                {
                    if (!pl.Closed &&
                        pl.NumberOfVertices >= 2)
                    {
                        AddShopCurveEndSamples(
                            pl,
                            result);
                    }

                    continue;
                }

                if (obj is Polyline2d pl2)
                {
                    if (!pl2.Closed)
                    {
                        AddShopCurveEndSamples(
                            pl2,
                            result);
                    }
                }
            }
        }

        private void AddShopCurveEndSamples(
            Curve curve,
            List<ShopFittingEndpointSample> result)
        {
            if (curve == null || result == null)
                return;

            try
            {
                Point3d start = curve.StartPoint;
                Point3d end = curve.EndPoint;

                if (start.DistanceTo(end) <= 1e-6)
                    return;

                Vector3d startInward =
                    curve.GetFirstDerivative(
                        curve.StartParam);

                Vector3d endInward =
                    -curve.GetFirstDerivative(
                        curve.EndParam);

                if (startInward.Length > 1e-9)
                {
                    result.Add(
                        new ShopFittingEndpointSample
                        {
                            Point = start,
                            OutwardDirection =
                                -startInward.GetNormal()
                        });
                }

                if (endInward.Length > 1e-9)
                {
                    result.Add(
                        new ShopFittingEndpointSample
                        {
                            Point = end,
                            OutwardDirection =
                                -endInward.GetNormal()
                        });
                }
            }
            catch { }
        }

        private List<ShopFittingPortInfo> BuildShopFittingPorts(
            List<ShopFittingEndpointSample> samples)
        {
            List<ShopFittingPortInfo> result =
                new List<ShopFittingPortInfo>();

            if (samples == null ||
                samples.Count == 0)
            {
                return result;
            }

            Point3d center =
                new Point3d(
                    samples.Average(s => s.Point.X),
                    samples.Average(s => s.Point.Y),
                    0.0);

            // Bỏ endpoint có outward chĩa sâu vào giữa fitting.
            List<ShopFittingEndpointSample> filtered =
                samples.Where(s =>
                {
                    if (s == null ||
                        s.OutwardDirection.Length < 1e-9)
                    {
                        return false;
                    }

                    Vector3d radial =
                        s.Point - center;

                    if (radial.Length < 1e-6)
                        return true;

                    return s.OutwardDirection
                        .GetNormal()
                        .DotProduct(
                            radial.GetNormal()) >= -0.15;
                })
                .ToList();

            if (filtered.Count < 2)
                filtered = samples.ToList();

            const double directionToleranceDeg = 18.0;

            List<List<ShopFittingEndpointSample>> directionGroups =
                new List<List<ShopFittingEndpointSample>>();

            foreach (ShopFittingEndpointSample sample in filtered)
            {
                if (sample == null ||
                    sample.OutwardDirection.Length < 1e-9)
                {
                    continue;
                }

                List<ShopFittingEndpointSample> bestGroup = null;
                double bestAngle = double.MaxValue;

                foreach (List<ShopFittingEndpointSample> group
                    in directionGroups)
                {
                    Vector3d avg =
                        AverageShopDirection(
                            group.Select(
                                x => x.OutwardDirection));

                    if (avg.Length < 1e-9)
                        continue;

                    double angle =
                        GetShopAngleDegrees(
                            avg,
                            sample.OutwardDirection);

                    if (angle <= directionToleranceDeg &&
                        angle < bestAngle)
                    {
                        bestAngle = angle;
                        bestGroup = group;
                    }
                }

                if (bestGroup == null)
                {
                    bestGroup =
                        new List<ShopFittingEndpointSample>();

                    directionGroups.Add(
                        bestGroup);
                }

                bestGroup.Add(
                    sample);
            }

            // FIX34:
            // Một Tê giảm có thể có NHIỀU endpoint cùng hướng:
            // - mặt cổng thật ở ngoài fitting
            // - mép trong của đoạn thu/côn.
            // Nếu gom tất cả theo hướng, port center bị kéo vào giữa.
            // Vì vậy tách tiếp theo "tọa độ mặt nối" dọc outward direction.
            foreach (List<ShopFittingEndpointSample> directionGroup
                in directionGroups)
            {
                if (directionGroup == null ||
                    directionGroup.Count == 0)
                {
                    continue;
                }

                Vector3d outward =
                    AverageShopDirection(
                        directionGroup.Select(
                            x => x.OutwardDirection));

                if (outward.Length < 1e-9)
                    continue;

                outward =
                    outward.GetNormal();

                List<Tuple<ShopFittingEndpointSample, double>> projectedAlong =
                    directionGroup
                        .Select(s =>
                            Tuple.Create(
                                s,
                                s.Point.GetAsVector()
                                    .DotProduct(outward)))
                        .OrderBy(x => x.Item2)
                        .ToList();

                if (projectedAlong.Count == 0)
                    continue;

                // Tolerance rất nhỏ so với DN để chỉ gom hai mép
                // thuộc CÙNG một mặt cổng.
                double minAlong =
                    projectedAlong.First().Item2;

                double maxAlong =
                    projectedAlong.Last().Item2;

                double alongSpan =
                    Math.Abs(
                        maxAlong - minAlong);

                double faceTolerance =
                    Math.Max(
                        0.75,
                        Math.Min(
                            3.0,
                            alongSpan * 0.04));

                List<List<ShopFittingEndpointSample>> faceGroups =
                    new List<List<ShopFittingEndpointSample>>();

                List<ShopFittingEndpointSample> current =
                    new List<ShopFittingEndpointSample>();

                double currentCenterAlong =
                    double.NaN;

                foreach (Tuple<ShopFittingEndpointSample, double> item
                    in projectedAlong)
                {
                    if (current.Count == 0)
                    {
                        current.Add(
                            item.Item1);

                        currentCenterAlong =
                            item.Item2;

                        continue;
                    }

                    if (Math.Abs(
                            item.Item2 -
                            currentCenterAlong) <=
                        faceTolerance)
                    {
                        current.Add(
                            item.Item1);

                        currentCenterAlong =
                            current.Average(s =>
                                s.Point.GetAsVector()
                                    .DotProduct(outward));
                    }
                    else
                    {
                        faceGroups.Add(
                            current);

                        current =
                            new List<ShopFittingEndpointSample>
                            {
                                item.Item1
                            };

                        currentCenterAlong =
                            item.Item2;
                    }
                }

                if (current.Count > 0)
                    faceGroups.Add(current);

                Vector3d normal =
                    new Vector3d(
                        -outward.Y,
                        outward.X,
                        0.0);

                foreach (List<ShopFittingEndpointSample> face
                    in faceGroups)
                {
                    if (face == null ||
                        face.Count == 0)
                    {
                        continue;
                    }

                    Point3d portCenter =
                        new Point3d(
                            face.Average(x => x.Point.X),
                            face.Average(x => x.Point.Y),
                            0.0);

                    List<double> across =
                        face.Select(x =>
                            (x.Point - portCenter)
                                .DotProduct(normal))
                            .ToList();

                    double width = 0.0;

                    if (across.Count >= 2)
                    {
                        width =
                            Math.Abs(
                                across.Max() -
                                across.Min());
                    }

                    result.Add(
                        new ShopFittingPortInfo
                        {
                            Center = portCenter,
                            OutwardDirection = outward,
                            Width = width,
                            SampleCount = face.Count
                        });
                }
            }

            return result;
        }

        private class ShopStraightSegmentSample
        {
            public Point3d A { get; set; }
            public Point3d B { get; set; }

            public Point3d Mid
            {
                get { return MidPoint(A, B); }
            }

            public double Length
            {
                get { return A.DistanceTo(B); }
            }
        }

        private List<ShopFittingPortInfo> BuildShopElbow45ObliquePorts(
            ObjectId blockId,
            double nominalDn)
        {
            List<ShopFittingPortInfo> result =
                new List<ShopFittingPortInfo>();

            if (blockId.IsNull ||
                nominalDn <= 0.0)
            {
                return result;
            }

            List<ShopStraightSegmentSample> segments =
                new List<ShopStraightSegmentSample>();

            Extents3d? extents =
                null;

            DBObjectCollection exploded =
                new DBObjectCollection();

            try
            {
                using (BlockReference temp =
                    new BlockReference(
                        Point3d.Origin,
                        blockId))
                {
                    temp.Explode(
                        exploded);
                }

                CollectShopBoundarySegmentsFromObjects(
                    exploded,
                    segments,
                    ref extents,
                    0);
            }
            catch
            {
            }
            finally
            {
                foreach (DBObject obj in exploded)
                {
                    try { obj?.Dispose(); } catch { }
                }
            }

            if (extents == null ||
                segments.Count == 0)
            {
                return result;
            }

            Extents3d box =
                extents.Value;

            Point3d center =
                new Point3d(
                    (box.MinPoint.X + box.MaxPoint.X) / 2.0,
                    (box.MinPoint.Y + box.MaxPoint.Y) / 2.0,
                    0.0);

            double dxBox =
                Math.Abs(
                    box.MaxPoint.X -
                    box.MinPoint.X);

            double dyBox =
                Math.Abs(
                    box.MaxPoint.Y -
                    box.MinPoint.Y);

            double radiusRef =
                Math.Max(
                    dxBox,
                    dyBox) /
                2.0;

            double minFace =
                nominalDn * 0.28;

            double maxFace =
                nominalDn * 3.20;

            List<ShopFittingPortInfo> candidates =
                new List<ShopFittingPortInfo>();

            foreach (ShopStraightSegmentSample seg
                in segments)
            {
                if (seg == null ||
                    seg.Length < minFace ||
                    seg.Length > maxFace)
                {
                    continue;
                }

                Vector3d tangent =
                    seg.B -
                    seg.A;

                tangent =
                    new Vector3d(
                        tangent.X,
                        tangent.Y,
                        0.0);

                if (tangent.Length < 1e-9)
                    continue;

                tangent =
                    tangent.GetNormal();

                Vector3d n1 =
                    new Vector3d(
                        -tangent.Y,
                        tangent.X,
                        0.0);

                Vector3d radial =
                    seg.Mid -
                    center;

                if (radial.Length < 1e-9)
                    continue;

                radial =
                    radial.GetNormal();

                // Chọn normal hướng RA NGOÀI fitting.
                Vector3d outward =
                    n1.DotProduct(radial) >= 0.0
                        ? n1
                        : -n1;

                double radialAlignment =
                    outward.DotProduct(
                        radial);

                // Mặt cổng thật thường nằm ở vùng ngoài và normal của nó
                // hướng tương đối ra khỏi tâm block.
                if (radialAlignment < 0.35)
                    continue;

                double radialDistance =
                    PlanDistance(
                        seg.Mid,
                        center);

                if (radiusRef > 1e-9 &&
                    radialDistance <
                        radiusRef * 0.28)
                {
                    continue;
                }

                candidates.Add(
                    new ShopFittingPortInfo
                    {
                        Center = seg.Mid,
                        OutwardDirection =
                            outward.GetNormal(),
                        Width = seg.Length,
                        SampleCount = 2
                    });
            }

            // Dedup các line trùng/face kép gần nhau.
            foreach (ShopFittingPortInfo port
                in candidates
                    .OrderByDescending(p =>
                        PlanDistance(
                            p.Center,
                            center))
                    .ThenBy(p =>
                        Math.Abs(
                            p.Width -
                            nominalDn)))
            {
                bool dup =
                    result.Any(old =>
                    {
                        double angle =
                            GetShopAngleDegrees(
                                old.OutwardDirection,
                                port.OutwardDirection);

                        return angle <= 7.0 &&
                               PlanDistance(
                                   old.Center,
                                   port.Center) <=
                               Math.Max(
                                   4.0,
                                   nominalDn * 0.08);
                    });

                if (!dup)
                    result.Add(port);
            }

            // Không cần trả hàng chục face. Giữ các candidate ngoài cùng,
            // AnalyzeShopElbowPorts sẽ chọn đúng cặp ~135°.
            return result
                .OrderByDescending(p =>
                    PlanDistance(
                        p.Center,
                        center))
                .Take(12)
                .ToList();
        }


        private List<ShopFittingPortInfo> BuildShopFittingBoundaryPortsForLargeWeld(
            ObjectId blockId,
            double nominalDn)
        {
            List<ShopFittingPortInfo> result =
                new List<ShopFittingPortInfo>();

            if (blockId.IsNull || nominalDn <= 0.0)
                return result;

            List<ShopStraightSegmentSample> segments =
                new List<ShopStraightSegmentSample>();

            Extents3d? extents = null;

            DBObjectCollection exploded =
                new DBObjectCollection();

            try
            {
                using (BlockReference temp =
                    new BlockReference(
                        Point3d.Origin,
                        blockId))
                {
                    temp.Explode(exploded);
                }

                CollectShopBoundarySegmentsFromObjects(
                    exploded,
                    segments,
                    ref extents,
                    0);
            }
            catch
            {
            }
            finally
            {
                foreach (DBObject obj in exploded)
                {
                    try { obj?.Dispose(); } catch { }
                }
            }

            if (extents == null || segments.Count == 0)
                return result;

            Extents3d box = extents.Value;

            double minX = box.MinPoint.X;
            double maxX = box.MaxPoint.X;
            double minY = box.MinPoint.Y;
            double maxY = box.MaxPoint.Y;

            double sideTolerance =
                Math.Max(
                    2.0,
                    Math.Min(
                        12.0,
                        nominalDn * 0.045));

            // Chỉ xét mặt có bề rộng hợp lý với DN/mặt bích.
            double minFace = nominalDn * 0.30;
            double maxFace = nominalDn * 2.80;

            TryAddShopBoundaryPort(
                result,
                segments,
                p => Math.Abs(p.X - minX) <= sideTolerance,
                new Vector3d(-1.0, 0.0, 0.0),
                true,
                nominalDn,
                minFace,
                maxFace);

            TryAddShopBoundaryPort(
                result,
                segments,
                p => Math.Abs(p.X - maxX) <= sideTolerance,
                new Vector3d(1.0, 0.0, 0.0),
                true,
                nominalDn,
                minFace,
                maxFace);

            TryAddShopBoundaryPort(
                result,
                segments,
                p => Math.Abs(p.Y - minY) <= sideTolerance,
                new Vector3d(0.0, -1.0, 0.0),
                false,
                nominalDn,
                minFace,
                maxFace);

            TryAddShopBoundaryPort(
                result,
                segments,
                p => Math.Abs(p.Y - maxY) <= sideTolerance,
                new Vector3d(0.0, 1.0, 0.0),
                false,
                nominalDn,
                minFace,
                maxFace);

            return result;
        }

        private void TryAddShopBoundaryPort(
            List<ShopFittingPortInfo> result,
            List<ShopStraightSegmentSample> segments,
            Func<Point3d, bool> onBoundary,
            Vector3d outward,
            bool expectVerticalFace,
            double nominalDn,
            double minFace,
            double maxFace)
        {
            if (result == null ||
                segments == null ||
                onBoundary == null)
            {
                return;
            }

            List<ShopStraightSegmentSample> candidates =
                new List<ShopStraightSegmentSample>();

            foreach (ShopStraightSegmentSample seg in segments)
            {
                if (seg == null || seg.Length < 1.0)
                    continue;

                if (!onBoundary(seg.A) ||
                    !onBoundary(seg.B))
                {
                    continue;
                }

                double dx = Math.Abs(seg.B.X - seg.A.X);
                double dy = Math.Abs(seg.B.Y - seg.A.Y);

                bool orientationOk =
                    expectVerticalFace
                        ? dy >= dx * 3.0
                        : dx >= dy * 3.0;

                if (!orientationOk)
                    continue;

                if (seg.Length < minFace ||
                    seg.Length > maxFace)
                {
                    continue;
                }

                candidates.Add(seg);
            }

            if (candidates.Count == 0)
                return;

            // Chọn mặt có kích thước gần DN nhất. Nếu block có mặt bích,
            // OD thường lớn hơn DN nhưng vẫn gần hơn cạnh thân dài.
            ShopStraightSegmentSample best =
                candidates
                    .OrderBy(s =>
                    {
                        double ratio =
                            Math.Max(
                                1e-9,
                                s.Length / nominalDn);

                        return Math.Abs(
                            Math.Log(ratio));
                    })
                    .ThenByDescending(s => s.Length)
                    .FirstOrDefault();

            if (best == null)
                return;

            result.Add(
                new ShopFittingPortInfo
                {
                    Center = best.Mid,
                    OutwardDirection = outward,
                    Width = best.Length,
                    SampleCount = 2
                });
        }

        private void CollectShopBoundarySegmentsFromObjects(
            DBObjectCollection objects,
            List<ShopStraightSegmentSample> segments,
            ref Extents3d? extents,
            int depth)
        {
            if (objects == null ||
                segments == null ||
                depth > 8)
            {
                return;
            }

            foreach (DBObject obj in objects)
            {
                if (obj == null)
                    continue;

                if (obj is Entity ent)
                {
                    try
                    {
                        Extents3d e = ent.GeometricExtents;

                        if (extents == null)
                        {
                            extents = e;
                        }
                        else
                        {
                            Extents3d cur = extents.Value;
                            cur.AddExtents(e);
                            extents = cur;
                        }
                    }
                    catch
                    {
                    }
                }

                if (obj is BlockReference nested)
                {
                    DBObjectCollection nestedObjects =
                        new DBObjectCollection();

                    try
                    {
                        nested.Explode(nestedObjects);

                        CollectShopBoundarySegmentsFromObjects(
                            nestedObjects,
                            segments,
                            ref extents,
                            depth + 1);
                    }
                    catch
                    {
                    }
                    finally
                    {
                        foreach (DBObject nestedObj in nestedObjects)
                        {
                            try { nestedObj?.Dispose(); } catch { }
                        }
                    }

                    continue;
                }

                if (obj is Line line)
                {
                    AddShopBoundarySegment(
                        segments,
                        line.StartPoint,
                        line.EndPoint);

                    continue;
                }

                if (obj is Polyline pl)
                {
                    int count = pl.NumberOfVertices;

                    if (count < 2)
                        continue;

                    int segmentCount =
                        pl.Closed
                            ? count
                            : count - 1;

                    for (int i = 0;
                        i < segmentCount;
                        i++)
                    {
                        int next =
                            (i + 1) % count;

                        try
                        {
                            // Chỉ lấy đoạn thẳng; cung cong không phải mặt nối.
                            if (Math.Abs(pl.GetBulgeAt(i)) > 1e-9)
                                continue;

                            AddShopBoundarySegment(
                                segments,
                                pl.GetPoint3dAt(i),
                                pl.GetPoint3dAt(next));
                        }
                        catch
                        {
                        }
                    }

                    continue;
                }
            }
        }

        private static void AddShopBoundarySegment(
            List<ShopStraightSegmentSample> segments,
            Point3d a,
            Point3d b)
        {
            if (segments == null ||
                a.DistanceTo(b) < 1.0)
            {
                return;
            }

            segments.Add(
                new ShopStraightSegmentSample
                {
                    A = a,
                    B = b
                });
        }

        private List<ShopFittingPortInfo> BuildShopFittingOuterPortsForLargeWeld(
            List<ShopFittingEndpointSample> samples,
            double nominalDn)
        {
            List<ShopFittingPortInfo> result =
                new List<ShopFittingPortInfo>();

            if (samples == null ||
                samples.Count == 0)
            {
                return result;
            }

            // DN150 có thể có rất nhiều endpoint do flange/cổ hàn.
            // Gom hướng hơi rộng hơn FIX34, sau đó CHỈ giữ mặt ngoài cùng.
            const double directionToleranceDeg = 25.0;

            List<List<ShopFittingEndpointSample>> directionGroups =
                new List<List<ShopFittingEndpointSample>>();

            foreach (ShopFittingEndpointSample sample in samples)
            {
                if (sample == null ||
                    sample.OutwardDirection.Length < 1e-9)
                {
                    continue;
                }

                Vector3d sd =
                    sample.OutwardDirection.GetNormal();

                List<ShopFittingEndpointSample> bestGroup =
                    null;

                double bestAngle =
                    double.MaxValue;

                foreach (List<ShopFittingEndpointSample> group
                    in directionGroups)
                {
                    Vector3d avg =
                        AverageShopDirection(
                            group.Select(
                                x => x.OutwardDirection));

                    if (avg.Length < 1e-9)
                        continue;

                    double angle =
                        GetShopAngleDegrees(
                            avg,
                            sd);

                    if (angle <= directionToleranceDeg &&
                        angle < bestAngle)
                    {
                        bestAngle = angle;
                        bestGroup = group;
                    }
                }

                if (bestGroup == null)
                {
                    bestGroup =
                        new List<ShopFittingEndpointSample>();

                    directionGroups.Add(
                        bestGroup);
                }

                bestGroup.Add(sample);
            }

            double faceTolerance =
                Math.Max(
                    2.0,
                    Math.Min(
                        10.0,
                        nominalDn * 0.035));

            foreach (List<ShopFittingEndpointSample> group
                in directionGroups)
            {
                if (group == null ||
                    group.Count == 0)
                {
                    continue;
                }

                Vector3d outward =
                    AverageShopDirection(
                        group.Select(
                            x => x.OutwardDirection));

                if (outward.Length < 1e-9)
                    continue;

                outward =
                    outward.GetNormal();

                // CỔNG THẬT phải là mặt nằm XA NHẤT theo chiều outward.
                // Mép trong của côn / thân Tê luôn có projection nhỏ hơn.
                List<Tuple<ShopFittingEndpointSample, double>> projected =
                    group.Select(s =>
                        Tuple.Create(
                            s,
                            s.Point.GetAsVector()
                                .DotProduct(outward)))
                        .OrderByDescending(x => x.Item2)
                        .ToList();

                if (projected.Count == 0)
                    continue;

                double outerMost =
                    projected[0].Item2;

                List<ShopFittingEndpointSample> outerFace =
                    projected
                        .Where(x =>
                            Math.Abs(
                                outerMost -
                                x.Item2) <=
                            faceTolerance)
                        .Select(x => x.Item1)
                        .ToList();

                if (outerFace.Count == 0)
                    continue;

                Point3d center =
                    new Point3d(
                        outerFace.Average(s => s.Point.X),
                        outerFace.Average(s => s.Point.Y),
                        0.0);

                Vector3d normal =
                    new Vector3d(
                        -outward.Y,
                        outward.X,
                        0.0);

                List<double> across =
                    outerFace
                        .Select(s =>
                            (s.Point - center)
                                .DotProduct(normal))
                        .ToList();

                double width = 0.0;

                if (across.Count >= 2)
                {
                    width =
                        Math.Abs(
                            across.Max() -
                            across.Min());
                }

                result.Add(
                    new ShopFittingPortInfo
                    {
                        Center = center,
                        OutwardDirection = outward,
                        Width = width,
                        SampleCount = outerFace.Count
                    });
            }

            // Loại port gần trùng: có thể phát sinh khi một mặt bích gồm
            // nhiều entity có hướng gần nhau.
            List<ShopFittingPortInfo> dedup =
                new List<ShopFittingPortInfo>();

            foreach (ShopFittingPortInfo port
                in result
                    .OrderByDescending(p =>
                        p.SampleCount)
                    .ThenByDescending(p =>
                        p.Width))
            {
                bool duplicate =
                    dedup.Any(old =>
                    {
                        double angle =
                            GetShopAngleDegrees(
                                old.OutwardDirection,
                                port.OutwardDirection);

                        return angle <= 10.0 &&
                               old.Center.DistanceTo(
                                   port.Center) <=
                               Math.Max(
                                   5.0,
                                   nominalDn * 0.08);
                    });

                if (!duplicate)
                    dedup.Add(port);
            }

            return dedup;
        }


        private Vector3d AverageShopDirection(
            IEnumerable<Vector3d> directions)
        {
            if (directions == null)
                return new Vector3d(0.0, 0.0, 0.0);

            double x = 0.0;
            double y = 0.0;
            int count = 0;

            foreach (Vector3d d in directions)
            {
                if (d.Length < 1e-9)
                    continue;

                Vector3d n = d.GetNormal();
                x += n.X;
                y += n.Y;
                count++;
            }

            if (count == 0)
                return new Vector3d(0.0, 0.0, 0.0);

            Vector3d result =
                new Vector3d(x, y, 0.0);

            return result.Length > 1e-9
                ? result.GetNormal()
                : new Vector3d(0.0, 0.0, 0.0);
        }

        private ShopFittingPlacementInfo AnalyzeShopReducerPorts(
            List<ShopFittingPortInfo> ports,
            string fromSize = "",
            string toSize = "")
        {
            if (ports == null || ports.Count < 2)
                return null;

            double n1 =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        fromSize));

            double n2 =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        toSize));

            double expectedLarge =
                Math.Max(n1, n2);

            double expectedSmall =
                Math.Min(
                    n1 > 0.0 ? n1 : double.MaxValue,
                    n2 > 0.0 ? n2 : double.MaxValue);

            if (expectedSmall == double.MaxValue)
                expectedSmall = 0.0;

            ShopFittingPortInfo pa = null;
            ShopFittingPortInfo pb = null;
            int largeIndex = -1;
            int smallIndex = -1;
            double bestScore = double.MaxValue;
            double bestAngleError = double.MaxValue;

            for (int i = 0; i < ports.Count; i++)
            {
                for (int j = i + 1; j < ports.Count; j++)
                {
                    if (ports[i] == null ||
                        ports[j] == null ||
                        ports[i].OutwardDirection.Length < 1e-9 ||
                        ports[j].OutwardDirection.Length < 1e-9)
                    {
                        continue;
                    }

                    double angle =
                        GetShopAngleDegrees(
                            ports[i].OutwardDirection,
                            ports[j].OutwardDirection);

                    double angleError =
                        Math.Abs(180.0 - angle);

                    if (angleError > 30.0)
                        continue;

                    Point3d anchor =
                        MidPoint(
                            ports[i].Center,
                            ports[j].Center);

                    Vector3d va =
                        ports[i].Center - anchor;

                    Vector3d vb =
                        ports[j].Center - anchor;

                    if (va.Length < 1e-6 ||
                        vb.Length < 1e-6)
                    {
                        continue;
                    }

                    double radialA =
                        va.GetNormal().DotProduct(
                            ports[i].OutwardDirection.GetNormal());

                    double radialB =
                        vb.GetNormal().DotProduct(
                            ports[j].OutwardDirection.GetNormal());

                    if (radialA < 0.55 ||
                        radialB < 0.55)
                    {
                        continue;
                    }

                    double distance =
                        ports[i].Center.DistanceTo(
                            ports[j].Center);

                    double widthPenalty = 0.0;
                    bool iIsLarge =
                        ports[i].Width >= ports[j].Width;

                    if (expectedLarge > 0.0 &&
                        expectedSmall > 0.0 &&
                        ports[i].Width > 0.0 &&
                        ports[j].Width > 0.0)
                    {
                        double directError =
                            Math.Abs(
                                ports[i].Width - expectedLarge) +
                            Math.Abs(
                                ports[j].Width - expectedSmall);

                        double reverseError =
                            Math.Abs(
                                ports[j].Width - expectedLarge) +
                            Math.Abs(
                                ports[i].Width - expectedSmall);

                        iIsLarge =
                            directError <= reverseError;

                        widthPenalty =
                            Math.Min(
                                directError,
                                reverseError) /
                            Math.Max(expectedLarge, 1.0) *
                            240.0;

                        double observedLarge =
                            Math.Max(
                                ports[i].Width,
                                ports[j].Width);

                        double observedSmall =
                            Math.Min(
                                ports[i].Width,
                                ports[j].Width);

                        double expectedRatio =
                            expectedSmall /
                            expectedLarge;

                        double observedRatio =
                            observedLarge > 1e-9
                                ? observedSmall / observedLarge
                                : 1.0;

                        widthPenalty +=
                            Math.Abs(
                                observedRatio -
                                expectedRatio) *
                            180.0;
                    }

                    // Đúng trục là điều kiện chính; sau đó ưu tiên hai mặt nối
                    // đúng D lớn/D nhỏ và nằm xa nhau nhất.
                    double score =
                        angleError * 1000.0 +
                        widthPenalty -
                        Math.Min(
                            distance,
                            100000.0) *
                        0.10;

                    if (score < bestScore)
                    {
                        bestScore = score;
                        bestAngleError = angleError;
                        pa = ports[i];
                        pb = ports[j];
                        largeIndex = iIsLarge ? 0 : 1;
                        smallIndex = iIsLarge ? 1 : 0;
                    }
                }
            }

            if (pa == null ||
                pb == null ||
                bestAngleError > 30.0)
                return null;

            ShopFittingPlacementInfo info =
                new ShopFittingPlacementInfo();

            info.Ports.Add(pa);
            info.Ports.Add(pb);
            info.Anchor = MidPoint(pa.Center, pb.Center);

            info.LargePortIndex =
                largeIndex >= 0
                    ? largeIndex
                    : (pa.Width >= pb.Width ? 0 : 1);

            info.SmallPortIndex =
                smallIndex >= 0
                    ? smallIndex
                    : (pa.Width >= pb.Width ? 1 : 0);

            return info;
        }

        private ShopFittingPlacementInfo AnalyzeShopElbowPorts(
            List<ShopFittingPortInfo> ports,
            double expectedIncludedAngle,
            double expectedPortWidth = 0.0)
        {
            if (ports == null || ports.Count < 2)
                return null;

            ShopFittingPortInfo pa = null;
            ShopFittingPortInfo pb = null;
            Point3d bestAnchor =
                Point3d.Origin;
            double bestScore = double.MaxValue;

            for (int i = 0; i < ports.Count; i++)
            {
                for (int j = i + 1; j < ports.Count; j++)
                {
                    if (ports[i] == null ||
                        ports[j] == null ||
                        ports[i].OutwardDirection.Length < 1e-9 ||
                        ports[j].OutwardDirection.Length < 1e-9)
                    {
                        continue;
                    }

                    double angle =
                        GetShopAngleDegrees(
                            ports[i].OutwardDirection,
                            ports[j].OutwardDirection);

                    double angleError =
                        Math.Abs(expectedIncludedAngle - angle);

                    if (angleError > 35.0)
                        continue;

                    Point3d anchor;

                    // Cổng Co thật phải có hai trục giao nhau tại tâm co.
                    // Không dùng midpoint vì midpoint làm block đúng góc nhưng sai chiều.
                    if (!TryIntersectShopAxes(
                            ports[i].Center,
                            ports[i].OutwardDirection,
                            ports[j].Center,
                            ports[j].OutwardDirection,
                            out anchor))
                    {
                        continue;
                    }

                    Vector3d va =
                        ports[i].Center - anchor;

                    Vector3d vb =
                        ports[j].Center - anchor;

                    if (va.Length < 1e-6 ||
                        vb.Length < 1e-6)
                    {
                        continue;
                    }

                    double radialA =
                        va.GetNormal().DotProduct(
                            ports[i].OutwardDirection.GetNormal());

                    double radialB =
                        vb.GetNormal().DotProduct(
                            ports[j].OutwardDirection.GetNormal());

                    if (radialA < 0.60 ||
                        radialB < 0.60)
                    {
                        continue;
                    }

                    double distance =
                        ports[i].Center.DistanceTo(ports[j].Center);

                    double widthPenalty = 0.0;

                    if (expectedPortWidth > 0.0)
                    {
                        if (ports[i].Width > 0.0)
                        {
                            widthPenalty +=
                                Math.Abs(
                                    ports[i].Width -
                                    expectedPortWidth) /
                                expectedPortWidth *
                                140.0;
                        }

                        if (ports[j].Width > 0.0)
                        {
                            widthPenalty +=
                                Math.Abs(
                                    ports[j].Width -
                                    expectedPortWidth) /
                                expectedPortWidth *
                                140.0;
                        }
                    }

                    // Ưu tiên đúng góc + đúng bề rộng D, sau đó mới tới khoảng cách.
                    double score =
                        angleError * 1000.0 +
                        widthPenalty -
                        Math.Min(distance, 100000.0);

                    if (score < bestScore)
                    {
                        bestScore = score;
                        pa = ports[i];
                        pb = ports[j];
                        bestAnchor = anchor;
                    }
                }
            }

            if (pa == null || pb == null)
                return null;

            double finalAngle =
                GetShopAngleDegrees(
                    pa.OutwardDirection,
                    pb.OutwardDirection);

            if (Math.Abs(finalAngle - expectedIncludedAngle) > 35.0)
                return null;

            ShopFittingPlacementInfo info =
                new ShopFittingPlacementInfo
                {
                    Anchor = bestAnchor
                };

            info.Ports.Add(pa);
            info.Ports.Add(pb);
            return info;
        }

        private ShopFittingPlacementInfo AnalyzeShopTeePorts(
            List<ShopFittingPortInfo> ports,
            string mainSize = "",
            string branchSize = "")
        {
            if (ports == null ||
                ports.Count < 3)
            {
                return null;
            }

            double expectedMain =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        mainSize));

            double expectedBranch =
                ParseShopDnNumber(
                    NormalizeShopDnToken(
                        branchSize));

            double expectedRatio =
                expectedMain > 0.0 &&
                expectedBranch > 0.0
                    ? expectedBranch / expectedMain
                    : 1.0;

            int bestMainA = -1;
            int bestMainB = -1;
            int bestBranch = -1;
            Point3d bestAnchor =
                Point3d.Origin;

            double bestScore =
                double.MaxValue;

            for (int i = 0;
                i < ports.Count;
                i++)
            {
                ShopFittingPortInfo pa =
                    ports[i];

                if (pa == null ||
                    pa.OutwardDirection.Length < 1e-9)
                {
                    continue;
                }

                for (int j = i + 1;
                    j < ports.Count;
                    j++)
                {
                    ShopFittingPortInfo pb =
                        ports[j];

                    if (pb == null ||
                        pb.OutwardDirection.Length < 1e-9)
                    {
                        continue;
                    }

                    double mainAngle =
                        GetShopAngleDegrees(
                            pa.OutwardDirection,
                            pb.OutwardDirection);

                    double oppositeError =
                        Math.Abs(
                            180.0 - mainAngle);

                    if (oppositeError > 25.0)
                        continue;

                    // Hai port main phải có width gần nhau nếu đo được.
                    double mainWidthPenalty = 0.0;

                    if (pa.Width > 1.0 &&
                        pb.Width > 1.0)
                    {
                        double maxW =
                            Math.Max(
                                pa.Width,
                                pb.Width);

                        double minW =
                            Math.Min(
                                pa.Width,
                                pb.Width);

                        mainWidthPenalty =
                            maxW > 1e-9
                                ? (maxW - minW) /
                                  maxW * 120.0
                                : 0.0;

                        // Chênh quá lớn => không thể là hai đầu through.
                        if (maxW > 1e-9 &&
                            (maxW - minW) /
                                maxW > 0.28)
                        {
                            continue;
                        }
                    }

                    for (int k = 0;
                        k < ports.Count;
                        k++)
                    {
                        if (k == i ||
                            k == j)
                        {
                            continue;
                        }

                        ShopFittingPortInfo pc =
                            ports[k];

                        if (pc == null ||
                            pc.OutwardDirection.Length < 1e-9)
                        {
                            continue;
                        }

                        double a90 =
                            Math.Abs(
                                90.0 -
                                GetShopAngleDegrees(
                                    pa.OutwardDirection,
                                    pc.OutwardDirection));

                        double b90 =
                            Math.Abs(
                                90.0 -
                                GetShopAngleDegrees(
                                    pb.OutwardDirection,
                                    pc.OutwardDirection));

                        if (a90 > 28.0 ||
                            b90 > 28.0)
                        {
                            continue;
                        }

                        Point3d mainMid =
                            MidPoint(
                                pa.Center,
                                pb.Center);

                        Point3d anchor;

                        if (!TryIntersectShopAxes(
                                mainMid,
                                pa.OutwardDirection,
                                pc.Center,
                                pc.OutwardDirection,
                                out anchor))
                        {
                            continue;
                        }

                        // Anchor phải nằm "phía trong" cả 3 port:
                        // từ anchor ra port phải cùng hướng outward.
                        Vector3d va =
                            pa.Center - anchor;

                        Vector3d vb =
                            pb.Center - anchor;

                        Vector3d vc =
                            pc.Center - anchor;

                        if (va.Length < 1e-6 ||
                            vb.Length < 1e-6 ||
                            vc.Length < 1e-6)
                        {
                            continue;
                        }

                        double da =
                            va.GetNormal()
                                .DotProduct(
                                    pa.OutwardDirection.GetNormal());

                        double db =
                            vb.GetNormal()
                                .DotProduct(
                                    pb.OutwardDirection.GetNormal());

                        double dc =
                            vc.GetNormal()
                                .DotProduct(
                                    pc.OutwardDirection.GetNormal());

                        if (da < 0.55 ||
                            db < 0.55 ||
                            dc < 0.55)
                        {
                            continue;
                        }

                        double score =
                            oppositeError * 10.0 +
                            a90 * 8.0 +
                            b90 * 8.0 +
                            mainWidthPenalty;

                        // Với Tê giảm, ưu tiên width ratio gần tỷ lệ DN.
                        if (pa.Width > 1.0 &&
                            pb.Width > 1.0 &&
                            pc.Width > 1.0 &&
                            expectedMain > 0.0 &&
                            expectedBranch > 0.0)
                        {
                            double observedMain =
                                (pa.Width + pb.Width) /
                                2.0;

                            if (observedMain > 1e-9)
                            {
                                double observedRatio =
                                    pc.Width /
                                    observedMain;

                                // Nếu branch nhỏ hơn main mà hình học lại
                                // rộng hơn main rõ rệt => sai port.
                                if (expectedRatio < 0.98 &&
                                    observedRatio > 1.12)
                                {
                                    continue;
                                }

                                score +=
                                    Math.Abs(
                                        observedRatio -
                                        expectedRatio) *
                                    160.0;
                            }
                        }

                        // Ưu tiên các cổng thật nằm xa anchor hơn
                        // so với mép hình học nội bộ.
                        double reach =
                            va.Length +
                            vb.Length +
                            vc.Length;

                        score -=
                            Math.Min(
                                reach,
                                10000.0) *
                            0.01;

                        if (score < bestScore)
                        {
                            bestScore =
                                score;

                            bestMainA = i;
                            bestMainB = j;
                            bestBranch = k;
                            bestAnchor = anchor;
                        }
                    }
                }
            }

            if (bestMainA < 0 ||
                bestMainB < 0 ||
                bestBranch < 0)
            {
                return null;
            }

            ShopFittingPlacementInfo info =
                new ShopFittingPlacementInfo
                {
                    Anchor = bestAnchor,
                    BranchPortIndex = 2
                };

            // CỐ ĐỊNH vai trò:
            // 0/1 = hai đầu main, 2 = branch.
            info.Ports.Add(
                ports[bestMainA]);

            info.Ports.Add(
                ports[bestMainB]);

            info.Ports.Add(
                ports[bestBranch]);

            return info;
        }

        private bool TryIntersectShopAxes(
            Point3d p1,
            Vector3d d1,
            Point3d p2,
            Vector3d d2,
            out Point3d intersection)
        {
            intersection = MidPoint(p1, p2);

            Vector3d a =
                new Vector3d(d1.X, d1.Y, 0.0);
            Vector3d b =
                new Vector3d(d2.X, d2.Y, 0.0);

            if (a.Length < 1e-9 || b.Length < 1e-9)
                return false;

            double cross = a.X * b.Y - a.Y * b.X;
            if (Math.Abs(cross) < 1e-9)
                return false;

            double dx = p2.X - p1.X;
            double dy = p2.Y - p1.Y;

            double t =
                (dx * b.Y - dy * b.X) / cross;

            intersection =
                new Point3d(
                    p1.X + a.X * t,
                    p1.Y + a.Y * t,
                    0.0);

            return true;
        }

        private bool TryResolveShopFittingTransform(
            string fittingType,
            ShopFittingPlacementInfo info,
            double desiredPrimaryAngle,
            bool desiredMirrorY,
            out double rotation,
            out double mirrorY)
        {
            rotation = desiredPrimaryAngle;
            mirrorY = desiredMirrorY ? -1.0 : 1.0;

            if (info == null || info.Ports.Count == 0)
                return false;

            string key = NormalizeShopKey(fittingType);
            Vector3d desired1 =
                new Vector3d(
                    Math.Cos(desiredPrimaryAngle),
                    Math.Sin(desiredPrimaryAngle),
                    0.0);

            if (IsReducerKey(key))
            {
                if (info.Ports.Count < 2 ||
                    info.LargePortIndex < 0 ||
                    info.SmallPortIndex < 0)
                {
                    return false;
                }

                // Caller truyền desired1 = hướng DN lớn -> DN nhỏ.
                // Vì outward của đầu nhỏ cũng chính là hướng lớn -> nhỏ,
                // căn đầu nhỏ của block theo desired1 là đủ để không đảo reducer.
                Vector3d localSmall =
                    info.Ports[info.SmallPortIndex]
                        .OutwardDirection;

                rotation =
                    desiredPrimaryAngle -
                    Math.Atan2(localSmall.Y, localSmall.X);

                mirrorY = 1.0;
                return true;
            }

            if (IsElbow90Key(key) ||
                IsElbow45Key(key))
            {
                if (info.Ports.Count < 2)
                    return false;

                double included =
                    IsElbow45Key(key) ? 135.0 : 90.0;

                double sign = desiredMirrorY ? -1.0 : 1.0;
                Vector3d desired2 =
                    RotateShopVector(
                        desired1,
                        sign * included);

                // Không mirror Dynamic Block bằng ScaleY=-1.
                // Đảo thứ tự 2 port + rotation là đủ cho mọi hướng Co.
                return TryMatchShopPortsToDirections(
                    info.Ports.Take(2).ToList(),
                    new List<Vector3d>
                    {
                        desired1,
                        desired2
                    },
                    false,
                    out rotation,
                    out mirrorY);
            }

            if (IsTeeKey(key))
            {
                if (info.Ports.Count < 3)
                    return false;

                Vector3d desiredMain2 = -desired1;
                Vector3d desiredBranch =
                    RotateShopVector(
                        desired1,
                        desiredMirrorY ? -90.0 : 90.0);

                // Ports của info Tê đã được xếp: main1, main2, branch.
                // Cho phép đảo 2 đầu main nhưng không đổi branch.
                List<List<int>> permutations =
                    new List<List<int>>
                    {
                        new List<int> { 0, 1, 2 },
                        new List<int> { 1, 0, 2 }
                    };

                // Tê cũng chỉ ROTATE. Hai đầu main được phép đổi chỗ,
                // nên không cần ScaleY=-1.
                return TryMatchShopPortsToDirections(
                    info.Ports.Take(3).ToList(),
                    new List<Vector3d>
                    {
                        desired1,
                        desiredMain2,
                        desiredBranch
                    },
                    false,
                    out rotation,
                    out mirrorY,
                    permutations);
            }

            return false;
        }

        private bool TryResolveShopFittingTransformToTargets(
            string fittingType,
            ShopFittingPlacementInfo info,
            List<Vector3d> targetDirections,
            out double rotation,
            out double mirrorY)
        {
            rotation = 0.0;
            mirrorY = 1.0;

            if (info == null ||
                info.Ports == null ||
                targetDirections == null)
            {
                return false;
            }

            string key =
                NormalizeShopKey(
                    fittingType ?? "");

            if (IsReducerKey(key))
            {
                if (info.Ports.Count < 2 ||
                    targetDirections.Count < 2 ||
                    info.LargePortIndex < 0 ||
                    info.SmallPortIndex < 0)
                {
                    return false;
                }

                List<ShopFittingPortInfo> rolePorts =
                    new List<ShopFittingPortInfo>
                    {
                        info.Ports[info.LargePortIndex],
                        info.Ports[info.SmallPortIndex]
                    };

                // target[0] = ống lớn, target[1] = ống nhỏ.
                return TryMatchShopPortsToDirections(
                    rolePorts,
                    targetDirections.Take(2).ToList(),
                    false,
                    out rotation,
                    out mirrorY,
                    new List<List<int>>
                    {
                        new List<int> { 0, 1 }
                    });
            }

            if (IsElbow90Key(key) ||
                IsElbow45Key(key))
            {
                if (info.Ports.Count < 2 ||
                    targetDirections.Count < 2)
                {
                    return false;
                }

                // Co không dựa vào thứ tự arm. Thử cả hai ánh xạ cổng,
                // nhưng chỉ chấp nhận phép ROTATE làm cả hai tim trùng nhau.
                return TryMatchShopPortsToDirections(
                    info.Ports.Take(2).ToList(),
                    targetDirections.Take(2).ToList(),
                    false,
                    out rotation,
                    out mirrorY,
                    new List<List<int>>
                    {
                        new List<int> { 0, 1 },
                        new List<int> { 1, 0 }
                    });
            }

            if (IsTeeKey(key))
            {
                if (info.Ports.Count < 3 ||
                    targetDirections.Count < 3)
                {
                    return false;
                }

                // placement: 0/1 = main, 2 = branch.
                // target:    0/1 = main thật, 2 = branch thật.
                return TryMatchShopPortsToDirections(
                    info.Ports.Take(3).ToList(),
                    targetDirections.Take(3).ToList(),
                    false,
                    out rotation,
                    out mirrorY,
                    new List<List<int>>
                    {
                        new List<int> { 0, 1, 2 },
                        new List<int> { 1, 0, 2 }
                    });
            }

            return false;
        }

        private bool TryMatchShopPortsToDirections(
            List<ShopFittingPortInfo> ports,
            List<Vector3d> desiredDirections,
            bool allowMirror,
            out double bestRotation,
            out double bestMirrorY,
            List<List<int>> explicitPermutations = null)
        {
            bestRotation = 0.0;
            bestMirrorY = 1.0;

            if (ports == null ||
                desiredDirections == null ||
                ports.Count != desiredDirections.Count ||
                ports.Count == 0)
            {
                return false;
            }

            List<List<int>> permutations =
                explicitPermutations ??
                BuildShopIndexPermutations(ports.Count);

            double bestScore = double.MaxValue;
            double bestWorstPortError = double.MaxValue;

            foreach (double mirror in
                (allowMirror
                    ? new[] { 1.0, -1.0 }
                    : new[] { 1.0 }))
            {
                foreach (List<int> perm in permutations)
                {
                    if (perm == null || perm.Count != ports.Count)
                        continue;

                    Vector3d local0 =
                        MirrorShopVectorY(
                            ports[perm[0]].OutwardDirection,
                            mirror);

                    Vector3d desired0 =
                        desiredDirections[0].GetNormal();

                    if (local0.Length < 1e-9 ||
                        desired0.Length < 1e-9)
                    {
                        continue;
                    }

                    double candidateRotation =
                        Math.Atan2(desired0.Y, desired0.X) -
                        Math.Atan2(local0.Y, local0.X);

                    double score = 0.0;
                    double worstPortError = 0.0;

                    for (int i = 0; i < ports.Count; i++)
                    {
                        Vector3d local =
                            MirrorShopVectorY(
                                ports[perm[i]].OutwardDirection,
                                mirror);

                        local = local.RotateBy(
                            candidateRotation,
                            Vector3d.ZAxis);

                        double portError =
                            GetShopAngleDegrees(
                                local,
                                desiredDirections[i]);

                        score += portError;
                        worstPortError =
                            Math.Max(
                                worstPortError,
                                portError);
                    }

                    if (score < bestScore)
                    {
                        bestScore = score;
                        bestRotation = candidateRotation;
                        bestMirrorY = mirror;
                        bestWorstPortError =
                            worstPortError;
                    }
                }
            }

            // Sai tổng quá lớn nghĩa là block được nhận không đúng loại.
            double maxScore = ports.Count * 22.0;
            return bestScore <= maxScore &&
                   bestWorstPortError <= 22.0;
        }

        private List<List<int>> BuildShopIndexPermutations(int count)
        {
            List<List<int>> result =
                new List<List<int>>();

            void Recurse(List<int> current, HashSet<int> used)
            {
                if (current.Count == count)
                {
                    result.Add(new List<int>(current));
                    return;
                }

                for (int i = 0; i < count; i++)
                {
                    if (used.Contains(i))
                        continue;

                    used.Add(i);
                    current.Add(i);
                    Recurse(current, used);
                    current.RemoveAt(current.Count - 1);
                    used.Remove(i);
                }
            }

            Recurse(new List<int>(), new HashSet<int>());
            return result;
        }

        private Vector3d MirrorShopVectorY(
            Vector3d vector,
            double mirrorY)
        {
            Vector3d result =
                new Vector3d(
                    vector.X,
                    vector.Y * mirrorY,
                    0.0);

            return result.Length > 1e-9
                ? result.GetNormal()
                : new Vector3d(0.0, 0.0, 0.0);
        }

        private Vector3d RotateShopVector(
            Vector3d vector,
            double degrees)
        {
            if (vector.Length < 1e-9)
                return new Vector3d(0.0, 0.0, 0.0);

            return vector.GetNormal().RotateBy(
                degrees * Math.PI / 180.0,
                Vector3d.ZAxis);
        }

        private int GetShopReducerLargeToSmallLocalSign(
            Transaction tr,
            ObjectId blockId)
        {
            // +1: đầu lớn ở -X, đầu nhỏ ở +X => chiều lớn->nhỏ là +X.
            // -1: đầu lớn ở +X, đầu nhỏ ở -X => chiều lớn->nhỏ là -X.
            // Không đọc chắc chắn được thì giữ +1 để tương thích thư viện cũ.
            if (tr == null || blockId.IsNull)
                return 1;

            try
            {
                BlockTableRecord def =
                    tr.GetObject(
                        blockId,
                        OpenMode.ForRead,
                        false) as BlockTableRecord;

                if (def == null)
                    return 1;

                List<Point2d> samples =
                    new List<Point2d>();

                foreach (ObjectId id in def)
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null)
                        continue;

                    if (ent is Line line)
                    {
                        samples.Add(
                            new Point2d(
                                line.StartPoint.X,
                                line.StartPoint.Y));
                        samples.Add(
                            new Point2d(
                                line.EndPoint.X,
                                line.EndPoint.Y));
                    }
                    else if (ent is Polyline pl)
                    {
                        for (int i = 0;
                            i < pl.NumberOfVertices;
                            i++)
                        {
                            Point2d pt = pl.GetPoint2dAt(i);
                            samples.Add(pt);
                        }
                    }
                    else if (ent is Arc arc)
                    {
                        samples.Add(
                            new Point2d(
                                arc.StartPoint.X,
                                arc.StartPoint.Y));
                        samples.Add(
                            new Point2d(
                                arc.EndPoint.X,
                                arc.EndPoint.Y));
                    }
                }

                if (samples.Count < 4)
                    return 1;

                double minX = samples.Min(p => p.X);
                double maxX = samples.Max(p => p.X);
                double spanX = maxX - minX;

                if (spanX < 1e-6)
                    return 1;

                double edgeBand =
                    Math.Max(1.0, spanX * 0.15);

                List<Point2d> left =
                    samples.Where(p =>
                        p.X <= minX + edgeBand)
                        .ToList();
                List<Point2d> right =
                    samples.Where(p =>
                        p.X >= maxX - edgeBand)
                        .ToList();

                if (left.Count < 2 || right.Count < 2)
                    return 1;

                double leftSpread =
                    left.Max(p => p.Y) -
                    left.Min(p => p.Y);
                double rightSpread =
                    right.Max(p => p.Y) -
                    right.Min(p => p.Y);

                if (leftSpread > rightSpread * 1.10)
                    return 1;

                if (rightSpread > leftSpread * 1.10)
                    return -1;
            }
            catch { }

            return 1;
        }

        private void NormalizeShopImportedBlock(
            Transaction tr,
            ObjectId blockId)
        {
            if (tr == null || blockId.IsNull)
                return;

            try
            {
                BlockTableRecord blockDef =
                    tr.GetObject(
                        blockId,
                        OpenMode.ForWrite) as BlockTableRecord;

                if (blockDef == null)
                    return;

                foreach (ObjectId id in blockDef)
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForWrite,
                            false) as Entity;

                    if (ent == null)
                        continue;

                    ent.Layer = "0";
                    ent.Color =
                        Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                            ColorMethod.ByBlock,
                            0);
                    // Giữ nguyên Visible / Polyline Width của block thư viện.
                    // Dynamic Block có thể dùng các trạng thái ẩn/hiện khác nhau;
                    // ép Visible=true sẽ làm nhiều hình cùng hiện chồng nhau.
                    ent.Transparency =
                        new Autodesk.AutoCAD.Colors.Transparency((byte)255);
                }
            }
            catch { }
        }

        private ObjectId EnsureExternalBlockImported(
            Transaction targetTr,
            Database targetDb,
            string libraryPath,
            string blockName)
        {
            if (targetTr == null ||
                targetDb == null ||
                string.IsNullOrWhiteSpace(libraryPath) ||
                string.IsNullOrWhiteSpace(blockName))
            {
                return ObjectId.Null;
            }

            // QUAN TRỌNG:
            // Không được lấy thẳng block cùng tên đang có trong bản vẽ đích.
            // Thư viện MEP thường có các tên block rất chung; nếu trùng tên với
            // block kiến trúc (cửa, hatch, thiết bị...) thì code cũ có thể chèn
            // nhầm block của bản vẽ hiện tại thay vì block trong file thư viện.
            string safeTargetName =
                BuildShopImportedBlockName(
                    libraryPath,
                    blockName);

            BlockTable targetBt =
                (BlockTable)targetTr.GetObject(
                    targetDb.BlockTableId,
                    OpenMode.ForRead);

            // Chỉ tái sử dụng block đã được chính SHOP import trước đó.
            if (!string.IsNullOrWhiteSpace(safeTargetName) &&
                targetBt.Has(safeTargetName))
            {
                return targetBt[safeTargetName];
            }

            try
            {
                using (Database sourceDb =
                    new Database(false, true))
                {
                    sourceDb.ReadDwgFile(
                        libraryPath,
                        FileOpenMode.OpenForReadAndAllShare,
                        true,
                        "");

                    ObjectId sourceBlockId = ObjectId.Null;

                    using (Transaction sourceTr =
                        sourceDb.TransactionManager
                            .StartTransaction())
                    {
                        BlockTable sourceBt =
                            (BlockTable)sourceTr.GetObject(
                                sourceDb.BlockTableId,
                                OpenMode.ForRead);

                        if (!sourceBt.Has(blockName))
                            return ObjectId.Null;

                        sourceBlockId = sourceBt[blockName];
                        sourceTr.Commit();
                    }

                    ObjectIdCollection ids =
                        new ObjectIdCollection();
                    ids.Add(sourceBlockId);

                    IdMapping mapping =
                        new IdMapping();

                    // MangleName bắt buộc incoming record dùng tên riêng khi
                    // đụng tên với block/layer/style đã có trong bản vẽ đích.
                    // Tuyệt đối không dùng Ignore ở đây vì Ignore sẽ tái dùng
                    // record cùng tên của bản vẽ đích và có thể thành "cửa".
                    sourceDb.WblockCloneObjects(
                        ids,
                        targetDb.BlockTableId,
                        mapping,
                        DuplicateRecordCloning.MangleName,
                        false);

                    ObjectId clonedBlockId =
                        ObjectId.Null;

                    foreach (IdPair pair in mapping)
                    {
                        if (pair.Key == sourceBlockId)
                        {
                            clonedBlockId = pair.Value;
                            break;
                        }
                    }

                    if (clonedBlockId.IsNull ||
                        !clonedBlockId.IsValid)
                    {
                        return ObjectId.Null;
                    }

                    // Đặt tên namespace riêng cho block SHOP để lần chèn kế tiếp
                    // dùng đúng block đã import từ đúng file thư viện.
                    try
                    {
                        BlockTableRecord clonedRecord =
                            targetTr.GetObject(
                                clonedBlockId,
                                OpenMode.ForWrite,
                                false) as BlockTableRecord;

                        if (clonedRecord != null &&
                            !clonedRecord.IsLayout &&
                            !clonedRecord.IsAnonymous &&
                            !string.IsNullOrWhiteSpace(safeTargetName))
                        {
                            targetBt =
                                (BlockTable)targetTr.GetObject(
                                    targetDb.BlockTableId,
                                    OpenMode.ForRead);

                            if (!targetBt.Has(safeTargetName))
                                clonedRecord.Name = safeTargetName;
                        }
                    }
                    catch
                    {
                        // Nếu block động/anonymous không cho đổi tên thì vẫn
                        // dùng ObjectId clone vừa nhận từ IdMapping.
                    }

                    return clonedBlockId;
                }
            }
            catch
            {
                return ObjectId.Null;
            }
        }

        private static string BuildShopImportedBlockName(
            string libraryPath,
            string sourceBlockName)
        {
            string lib =
                Path.GetFileNameWithoutExtension(
                    libraryPath ?? "") ?? "LIB";

            string raw =
                "__SHOPLIB_" +
                lib +
                "_" +
                (sourceBlockName ?? "BLOCK");

            raw =
                BoDauTiengViet(raw)
                    .ToUpperInvariant();

            // Chỉ giữ các ký tự an toàn cho tên SymbolTableRecord.
            raw = Regex.Replace(
                raw,
                @"[^A-Z0-9_\-$]+",
                "_");

            raw = Regex.Replace(
                raw,
                @"_+",
                "_");

            if (raw.Length > 200)
                raw = raw.Substring(0, 200);

            return raw;
        }

        private string FindShopFittingBlockName(
            string libraryPath,
            string fittingType,
            string fromSize,
            string toSize)
        {
            try
            {
                using (Database libDb =
                    new Database(false, true))
                {
                    libDb.ReadDwgFile(
                        libraryPath,
                        FileOpenMode.OpenForReadAndAllShare,
                        true,
                        "");

                    using (Transaction tr =
                        libDb.TransactionManager
                            .StartTransaction())
                    {
                        // Ưu tiên tên block trước. Nếu thư viện đã đặt tên rõ
                        // CO90 / TEE / REDUCER + DN thì đây là cách chắc nhất.
                        string byName =
                            FindShopBlockByName(
                                tr,
                                libDb,
                                fittingType,
                                fromSize,
                                toSize);

                        if (!string.IsNullOrWhiteSpace(byName))
                        {
                            try
                            {
                                double dbgDn1 =
                                    ParseShopDnNumber(
                                        NormalizeShopDnToken(
                                            fromSize));

                                double dbgDn2 =
                                    ParseShopDnNumber(
                                        NormalizeShopDnToken(
                                            toSize));

                                if (Math.Max(dbgDn1, dbgDn2) >= 100.0)
                                {
                                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                                        .DocumentManager
                                        .MdiActiveDocument?
                                        .Editor
                                        .WriteMessage(
                                            $"\n[SHOP FIX39] LARGE BLOCK FOUND: " +
                                            $"{fittingType} {fromSize}->{toSize} = {byName}");
                                }
                            }
                            catch
                            {
                            }

                            try
                            {
                                Autodesk.AutoCAD.ApplicationServices.Core.Application
                                    .DocumentManager
                                    .MdiActiveDocument?
                                    .Editor
                                    .WriteMessage(
                                        $"\n[SHOP FIX40C] EXACT BLOCK: " +
                                        $"{fittingType} {fromSize}->{toSize} = {byName}");
                            }
                            catch
                            {
                            }

                            return byName;
                        }

                        // FIX33:
                        // Thư viện STEEL của user đã có tên block chuẩn:
                        // SCREW/WELD-ELB90, ELB45, TEE, RED...
                        // Nếu không tìm thấy đúng tên thì KHÔNG dò theo vị trí bảng,
                        // tránh lấy nhầm van / Y lọc / sprinkler / block khác.
                        string libraryKey =
                            NormalizeShopKey(
                                Path.GetFileNameWithoutExtension(
                                    libraryPath ?? ""));

                        // FIX42:
                        // STEEL và PPR đều đã có quy ước tên block rõ ràng.
                        // Không được dò theo vị trí bảng vì có thể lấy trúng
                        // van/phụ kiện khác nằm gần chữ size và chèn hình lạ.
                        if (libraryKey.Contains("STEEL") ||
                            libraryKey.Contains("PPR"))
                            return "";

                        // Chỉ uPVC/HDPE cũ còn cho phép fallback theo bảng.
                        string byGrid =
                            FindShopBlockByLibraryGrid(
                                tr,
                                libDb,
                                fittingType,
                                fromSize,
                                toSize);

                        if (!string.IsNullOrWhiteSpace(byGrid))
                            return byGrid;

                        tr.Commit();
                    }
                }
            }
            catch { }

            return "";
        }

        private string FindShopBlockByExactCandidates(
            BlockTable bt,
            string fittingType,
            string fromSize,
            string toSize)
        {
            if (bt == null)
                return "";

            string dn =
                NormalizeShopDnToken(fromSize);
            string dn2 =
                NormalizeShopDnToken(toSize);

            // Số DN thuần: "DN50" -> 50
            double n1 = ParseShopDnNumber(dn);
            double n2 = ParseShopDnNumber(dn2);

            if (n1 <= 0 && n2 <= 0)
                return "";

            // Ống nhỏ (≤50) = ren SCREW; lớn (≥65) = hàn WELD
            // Một số thư viện có cả hai — thử cả hai prefix.
            List<string> prefixes =
                BuildShopConnectionPrefixes(n1, n2);

            List<string> candidates =
                new List<string>();

            string typeKey =
                NormalizeShopKey(fittingType ?? "");

            // ---- CO 90 ----
            if (IsElbow90Key(typeKey) ||
                typeKey == "ELBOW90" ||
                typeKey.Contains("ELBOW90"))
            {
                string sizeTok = dn;
                if (string.IsNullOrWhiteSpace(sizeTok) && n2 > 0)
                    sizeTok = dn2;

                // PPR library thật:
                // ELB90-D20 PPR
                string pprD =
                    "D" +
                    FormatShopDnNumber(
                        n1 > 0 ? n1 : n2);

                candidates.Add(
                    "ELB90-" +
                    pprD +
                    " PPR");

                candidates.Add(
                    "ELB90-" +
                    pprD +
                    "PPR");

                foreach (string p in prefixes)
                {
                    candidates.Add(p + "-ELB90-" + sizeTok);
                    candidates.Add(p + "-ELBOW90-" + sizeTok);
                }
                candidates.Add("ELB90-" + sizeTok);
                candidates.Add("CO90-" + sizeTok);
            }
            // ---- CO 45 ----
            else if (IsElbow45Key(typeKey) ||
                     typeKey == "ELBOW45" ||
                     typeKey.Contains("ELBOW45"))
            {
                string sizeTok = dn;
                if (string.IsNullOrWhiteSpace(sizeTok) && n2 > 0)
                    sizeTok = dn2;

                // PPR library thật:
                // ELB45-D20 PPR
                string pprD =
                    "D" +
                    FormatShopDnNumber(
                        n1 > 0 ? n1 : n2);

                candidates.Add(
                    "ELB45-" +
                    pprD +
                    " PPR");

                candidates.Add(
                    "ELB45-" +
                    pprD +
                    "PPR");

                foreach (string p in prefixes)
                {
                    candidates.Add(p + "-ELB45-" + sizeTok);
                    candidates.Add(p + "-ELBOW45-" + sizeTok);
                }
                candidates.Add("ELB45-" + sizeTok);
                candidates.Add("CO45-" + sizeTok);
                candidates.Add("COLOI45-" + sizeTok);
            }
            // ---- TÊ ----
            // TÊ ĐỀU:  SCREW-TEE-DN15x15
            // TÊ GIẢM: SCREW-TEED-DN20x15
            else if (IsTeeKey(typeKey) ||
                     typeKey == "TEE" ||
                     typeKey == "TE" ||
                     typeKey == "TEED")
            {
                double mainN = n1;
                double branchN = n2 > 0 ? n2 : n1;

                if (mainN <= 0 || branchN <= 0)
                    return "";

                if (branchN > mainN + 0.01)
                    return "";

                string mainTok =
                    "DN" + FormatShopDnNumber(mainN);

                string branchTok =
                    FormatShopDnNumber(branchN);

                string pair =
                    mainTok + "x" + branchTok;

                string pairFull =
                    mainTok + "xDN" + branchTok;

                bool sameSize =
                    Math.Abs(mainN - branchN) <= 0.01;

                bool reducing =
                    typeKey == "TEED" ||
                    typeKey.Contains("TEGIAM") ||
                    typeKey.Contains("TETHU") ||
                    !sameSize;

                // PPR library thật:
                // TÊ ĐỀU  = TEE-D20x20 PPR
                // TÊ GIẢM = TEED-D25x20 PPR
                string pprMain =
                    "D" +
                    FormatShopDnNumber(
                        mainN);

                string pprBranch =
                    FormatShopDnNumber(
                        branchN);

                string pprPair =
                    pprMain +
                    "x" +
                    pprBranch;

                candidates.Add(
                    (reducing
                        ? "TEED-"
                        : "TEE-") +
                    pprPair +
                    " PPR");

                candidates.Add(
                    (reducing
                        ? "TEED-"
                        : "TEE-") +
                    pprPair +
                    "PPR");

                foreach (string p in prefixes)
                {
                    if (!reducing)
                    {
                        // EXACT TÊ ĐỀU
                        candidates.Add(p + "-TEE-" + pair);
                        candidates.Add(p + "-TEE-" + pairFull);
                    }
                    else
                    {
                        // EXACT TÊ GIẢM
                        candidates.Add(p + "-TEED-" + pair);
                        candidates.Add(p + "-TEED-" + pairFull);

                        // Nếu nhánh hàn WELD trong thư viện cũ dùng TEE cho tê giảm,
                        // chỉ thử sau TEED exact.
                        if (string.Equals(
                                p,
                                "WELD",
                                StringComparison.OrdinalIgnoreCase))
                        {
                            candidates.Add(p + "-TEE-" + pair);
                            candidates.Add(p + "-TEE-" + pairFull);
                        }
                    }
                }

                candidates.Add(
                    (reducing ? "TEED-" : "TEE-") +
                    pair);
            }
            // ---- GIẢM : SCREW-RED-DN50x40 / WELD-RED-DN80x50 ----
            else if (IsReducerKey(typeKey) ||
                     typeKey.Contains("REDUC"))
            {
                if (n1 > 0 && n2 > 0 &&
                    Math.Abs(n1 - n2) > 0.01)
                {
                    double big = Math.Max(n1, n2);
                    double small = Math.Min(n1, n2);
                    string bigTok = "DN" + FormatShopDnNumber(big);
                    string smallTok = FormatShopDnNumber(small);
                    string pair = bigTok + "x" + smallTok;
                    string pairFull = bigTok + "xDN" + smallTok;

                    // PPR library thật:
                    // RED-D25x20 PPR
                    string pprPair =
                        "D" +
                        FormatShopDnNumber(
                            big) +
                        "x" +
                        FormatShopDnNumber(
                            small);

                    candidates.Add(
                        "RED-" +
                        pprPair +
                        " PPR");

                    candidates.Add(
                        "RED-" +
                        pprPair +
                        "PPR");

                    foreach (string p in prefixes)
                    {
                        candidates.Add(p + "-RED-" + pair);
                        candidates.Add(p + "-RED-" + pairFull);
                        candidates.Add(p + "-REDUCER-" + pair);
                        candidates.Add(p + "-GIAM-" + pair);
                    }
                    candidates.Add("RED-" + pair);
                    candidates.Add("REDUCER-" + pair);
                    candidates.Add("GIAM-" + pair);
                }
            }
            // ---- NẮP / CAP ----
            else if (typeKey.Contains("CAP") ||
                     typeKey.Contains("NAP"))
            {
                string sizeTok = dn;
                if (string.IsNullOrWhiteSpace(sizeTok) && n2 > 0)
                    sizeTok = dn2;

                foreach (string p in prefixes)
                    candidates.Add(p + "-CAP-" + sizeTok);
                candidates.Add("CAP-" + sizeTok);
            }

            // Build name map từ BlockTable
            Dictionary<string, string> map =
                new Dictionary<string, string>(
                    StringComparer.OrdinalIgnoreCase);

            Transaction tr =
                bt.Database.TransactionManager.TopTransaction;

            if (tr == null)
                return "";

            foreach (ObjectId id in bt)
            {
                BlockTableRecord record = null;
                try
                {
                    record =
                        tr.GetObject(id, OpenMode.ForRead, false)
                            as BlockTableRecord;
                }
                catch
                {
                    continue;
                }

                if (record == null ||
                    record.IsLayout ||
                    record.IsAnonymous ||
                    record.IsFromExternalReference)
                {
                    continue;
                }

                string name = record.Name ?? "";
                if (string.IsNullOrWhiteSpace(name))
                    continue;

                map[name] = name;
                map[NormalizeShopKey(name)] = name;
            }

            // 1) Khớp đúng tên candidate
            foreach (string cand in candidates)
            {
                if (string.IsNullOrWhiteSpace(cand))
                    continue;

                if (map.TryGetValue(cand, out string hit))
                    return hit;

                string norm = NormalizeShopKey(cand);
                if (map.TryGetValue(norm, out hit))
                    return hit;
            }

            // 2) Khớp lỏng theo Normalize key + đúng DN
            foreach (string cand in candidates)
            {
                string normCand = NormalizeShopKey(cand);
                if (string.IsNullOrWhiteSpace(normCand))
                    continue;

                foreach (KeyValuePair<string, string> kv in map)
                {
                    string normName = NormalizeShopKey(kv.Value);
                    if (normName == normCand)
                        return kv.Value;
                }
            }

            // 3) Fallback: block chứa type + đủ size (SCREWELB90DN50, WELDREDDN80X50...)
            foreach (KeyValuePair<string, string> kv in map)
            {
                string normName = NormalizeShopKey(kv.Value);
                if (!IsShopFittingTypeText(fittingType, kv.Value))
                    continue;

                bool okFrom =
                    string.IsNullOrWhiteSpace(fromSize) ||
                    ShopKeyContainsSize(kv.Value, fromSize);
                bool okTo =
                    string.IsNullOrWhiteSpace(toSize) ||
                    string.Equals(
                        CleanLayerText(fromSize ?? ""),
                        CleanLayerText(toSize ?? ""),
                        StringComparison.OrdinalIgnoreCase) ||
                    ShopKeyContainsSize(kv.Value, toSize);

                if (okFrom && okTo)
                    return kv.Value;
            }

            return "";
        }

        private static List<string> BuildShopConnectionPrefixes(
            double sizeA,
            double sizeB)
        {
            List<string> result = new List<string>();

            double refSize =
                sizeA > 0 && sizeB > 0
                    ? Math.Max(sizeA, sizeB)
                    : (sizeA > 0 ? sizeA : sizeB);

            // ≤50: ưu tiên SCREW; ≥65: ưu tiên WELD; thử cả hai
            if (refSize > 0 && refSize <= 50.0)
            {
                result.Add("SCREW");
                result.Add("WELD");
            }
            else if (refSize >= 65.0)
            {
                result.Add("WELD");
                result.Add("SCREW");
            }
            else
            {
                // DN50–65 vùng chuyển
                result.Add("SCREW");
                result.Add("WELD");
            }

            return result;
        }

        private static double ParseShopDnNumber(string dnToken)
        {
            if (string.IsNullOrWhiteSpace(dnToken))
                return 0;

            Match m =
                Regex.Match(
                    dnToken,
                    @"(\d+(?:[.,]\d+)?)",
                    RegexOptions.IgnoreCase);

            if (!m.Success)
                return 0;

            if (double.TryParse(
                    m.Groups[1].Value.Replace(',', '.'),
                    NumberStyles.AllowDecimalPoint,
                    CultureInfo.InvariantCulture,
                    out double v))
            {
                return v;
            }

            return 0;
        }

        private static string FormatShopDnNumber(double n)
        {
            if (n <= 0)
                return "";

            // DN nguyên phổ biến: 15,20,25,32,40,50,65,80,100...
            if (Math.Abs(n - Math.Round(n)) < 0.01)
                return ((int)Math.Round(n)).ToString(
                    CultureInfo.InvariantCulture);

            return n.ToString(
                "0.##",
                CultureInfo.InvariantCulture);
        }

        private static string NormalizeShopDnToken(string sizeText)
        {
            string raw = (sizeText ?? "").Trim().ToUpperInvariant();
            if (string.IsNullOrWhiteSpace(raw))
                return "";

            // "DN50" / "50" / "dn 50" -> "DN50"
            Match m =
                Regex.Match(
                    raw,
                    @"DN\s*(\d{1,4}(?:\.\d+)?)",
                    RegexOptions.IgnoreCase);

            if (m.Success)
                return "DN" + m.Groups[1].Value.Replace(',', '.');

            m = Regex.Match(raw, @"(\d{1,4}(?:\.\d+)?)");
            if (m.Success)
                return "DN" + m.Groups[1].Value.Replace(',', '.');

            return NormalizeShopKey(raw);
        }

        private string FindShopBlockByName(
            Transaction tr,
            Database db,
            string fittingType,
            string fromSize,
            string toSize)
        {
            BlockTable bt =
                (BlockTable)tr.GetObject(
                    db.BlockTableId,
                    OpenMode.ForRead);

            // Ưu tiên tên block đúng chuẩn thư viện user:
            // SCREW-ELB90-DN15, SCREW-ELB45-DN50, SCREW-TEE-DN40...
            string exact =
                FindShopBlockByExactCandidates(
                    bt,
                    fittingType,
                    fromSize,
                    toSize);

            if (!string.IsNullOrWhiteSpace(exact))
                return exact;

            string bestName = "";
            int bestScore = -1;

            foreach (ObjectId id in bt)
            {
                BlockTableRecord record =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as BlockTableRecord;

                if (record == null ||
                    record.IsLayout ||
                    record.IsAnonymous ||
                    record.IsFromExternalReference)
                {
                    continue;
                }

                string name =
                    record.Name ?? "";

                // Tên block phải thể hiện ĐÚNG loại phụ kiện.
                // Không còn cho phép "chỉ trùng DN" đạt đủ điểm rồi bị chọn.
                // Nếu thư viện dùng tên generic (Block1, A$C...) thì hàm này
                // trả rỗng và chuyển sang dò theo bảng thư viện có kiểm soát.
                if (!IsShopFittingTypeText(
                        fittingType,
                        name))
                {
                    continue;
                }

                int score = 100;

                bool sameSize =
                    string.Equals(
                        CleanLayerText(
                            fromSize ?? ""),
                        CleanLayerText(
                            toSize ?? ""),
                        StringComparison.OrdinalIgnoreCase);

                bool hasFrom =
                    ShopKeyContainsSize(
                        name,
                        fromSize);

                bool hasTo =
                    ShopKeyContainsSize(
                        name,
                        toSize);

                if (hasFrom)
                    score += 30;

                if (sameSize)
                {
                    if (hasFrom)
                        score += 20;
                }
                else if (hasTo)
                {
                    score += 30;
                }

                if (ShopSizeLabelMatches(
                        name,
                        fromSize,
                        toSize))
                {
                    score += 40;
                }

                // Với giảm/tê giảm cần cả hai DN nếu tên block có DN.
                // Nếu tên không có DN thì vẫn cho phép fallback grid xử lý,
                // không tự chèn dựa vào tên loại chung chung.
                bool nameHasAnyDn =
                    Regex.IsMatch(
                        NormalizeShopKey(name),
                        @"(?:DN)?\d{1,4}");

                if (nameHasAnyDn)
                {
                    if (sameSize && !hasFrom)
                        continue;

                    if (!sameSize &&
                        (!hasFrom || !hasTo))
                    {
                        continue;
                    }
                }
                else
                {
                    // Tên chỉ nói loại phụ kiện nhưng không nói size:
                    // không đủ chắc chắn để lấy thẳng theo tên.
                    continue;
                }

                if (score > bestScore)
                {
                    bestScore = score;
                    bestName = name;
                }
            }

            return bestName;
        }

        private string FindShopBlockByLibraryGrid(
            Transaction tr,
            Database db,
            string fittingType,
            string fromSize,
            string toSize)
        {
            BlockTable bt =
                (BlockTable)tr.GetObject(
                    db.BlockTableId,
                    OpenMode.ForRead);

            BlockTableRecord ms =
                (BlockTableRecord)tr.GetObject(
                    bt[BlockTableRecord.ModelSpace],
                    OpenMode.ForRead);

            List<Tuple<string, Point3d>> texts =
                new List<Tuple<string, Point3d>>();

            List<BlockReference> blocks =
                new List<BlockReference>();

            foreach (ObjectId id in ms)
            {
                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent is DBText dbText)
                {
                    texts.Add(
                        Tuple.Create(
                            dbText.TextString ?? "",
                            dbText.Position));
                }
                else if (ent is MText mText)
                {
                    texts.Add(
                        Tuple.Create(
                            LayPlainTextTuMText(
                                mText.Contents),
                            mText.Location));
                }
                else if (ent is BlockReference br)
                {
                    // Bỏ xref/layout và các reference không có definition hợp lệ.
                    try
                    {
                        BlockTableRecord def =
                            tr.GetObject(
                                br.BlockTableRecord,
                                OpenMode.ForRead,
                                false) as BlockTableRecord;

                        if (def == null ||
                            def.IsLayout ||
                            def.IsFromExternalReference)
                        {
                            continue;
                        }
                    }
                    catch
                    {
                        continue;
                    }

                    blocks.Add(br);
                }
            }

            if (texts.Count == 0 ||
                blocks.Count == 0)
            {
                return "";
            }

            List<Tuple<string, Point3d>> typeLabels =
                texts.Where(t =>
                    IsShopFittingTypeText(
                        fittingType,
                        t.Item1))
                    .ToList();

            List<Tuple<string, Point3d>> sizeLabels =
                texts.Where(t =>
                    ShopSizeLabelMatches(
                        t.Item1,
                        fromSize,
                        toSize))
                    .ToList();

            if (typeLabels.Count == 0 ||
                sizeLabels.Count == 0)
            {
                return "";
            }

            // Code cũ dùng:
            //   min khoảng cách Y tới BẤT KỲ label loại
            // + min khoảng cách X tới BẤT KỲ label size.
            // Hai label đó có thể thuộc hai bảng khác nhau -> chọn nhầm block.
            //
            // Cách mới: tạo giao điểm thật của từng cặp
            // (cột SIZE.X, hàng TYPE.Y), rồi tìm block gần giao điểm đó nhất.
            BlockReference bestBlock = null;
            double bestDistance =
                double.MaxValue;

            foreach (Tuple<string, Point3d> typeLabel
                in typeLabels)
            {
                foreach (Tuple<string, Point3d> sizeLabel
                    in sizeLabels)
                {
                    Point3d expectedCell =
                        new Point3d(
                            sizeLabel.Item2.X,
                            typeLabel.Item2.Y,
                            0.0);

                    foreach (BlockReference br in blocks)
                    {
                        double dx =
                            br.Position.X -
                            expectedCell.X;

                        double dy =
                            br.Position.Y -
                            expectedCell.Y;

                        double dist =
                            Math.Sqrt(
                                dx * dx +
                                dy * dy);

                        if (dist < bestDistance)
                        {
                            bestDistance = dist;
                            bestBlock = br;
                        }
                    }
                }
            }

            if (bestBlock == null)
                return "";

            // Không "đoán đại": nếu block nằm quá xa ô hàng/cột dự kiến,
            // trả về rỗng để SHOP vẽ fallback bằng line thay vì chèn sai block.
            double gridSpacing =
                EstimateShopLibraryBlockSpacing(
                    blocks);

            double maxAllowedDistance =
                gridSpacing > 1.0
                    ? Math.Max(
                        250.0,
                        gridSpacing * 0.40)
                    : 500.0;

            if (bestDistance >
                maxAllowedDistance)
            {
                return "";
            }

            BlockTableRecord blockDef =
                tr.GetObject(
                    bestBlock.BlockTableRecord,
                    OpenMode.ForRead,
                    false) as BlockTableRecord;

            if (blockDef == null)
                return "";

            // Loại nhanh các block có tên thể hiện rõ là kiến trúc/nội thất.
            // Tên generic vẫn được phép vì nhiều thư viện MEP dùng tên Block1...
            if (IsObviouslyNonShopFittingBlockName(
                    blockDef.Name))
            {
                return "";
            }

            return blockDef.Name ?? "";
        }

        private static double EstimateShopLibraryBlockSpacing(
            List<BlockReference> blocks)
        {
            if (blocks == null ||
                blocks.Count < 2)
            {
                return 0.0;
            }

            List<double> nearestDistances =
                new List<double>();

            for (int i = 0;
                i < blocks.Count;
                i++)
            {
                Point3d a =
                    blocks[i].Position;

                double nearest =
                    double.MaxValue;

                for (int j = 0;
                    j < blocks.Count;
                    j++)
                {
                    if (i == j)
                        continue;

                    Point3d b =
                        blocks[j].Position;

                    double dx = a.X - b.X;
                    double dy = a.Y - b.Y;

                    double d =
                        Math.Sqrt(
                            dx * dx +
                            dy * dy);

                    if (d > 1.0 &&
                        d < nearest)
                    {
                        nearest = d;
                    }
                }

                if (nearest < double.MaxValue)
                    nearestDistances.Add(nearest);
            }

            if (nearestDistances.Count == 0)
                return 0.0;

            nearestDistances.Sort();

            int mid =
                nearestDistances.Count / 2;

            if (nearestDistances.Count % 2 == 1)
                return nearestDistances[mid];

            return
                (nearestDistances[mid - 1] +
                 nearestDistances[mid]) /
                2.0;
        }

        private static bool IsObviouslyNonShopFittingBlockName(
            string blockName)
        {
            string key =
                NormalizeShopKey(
                    blockName ?? "");

            if (string.IsNullOrWhiteSpace(key))
                return false;

            string[] rejectTokens =
            {
                "DOOR",
                "WINDOW",
                "CUA",
                "FURN",
                "FURNITURE",
                "TABLE",
                "CHAIR",
                "BED",
                "WC",
                "SANITARY",
                "HATCH",
                "TITLEBLOCK"
            };

            return rejectTokens.Any(
                token =>
                    key.Contains(token));
        }

        private static bool IsShopFittingTypeText(
            string fittingType,
            string text)
        {
            string typeKey = NormalizeShopKey(fittingType);
            string key = NormalizeShopKey(text);

            if (IsReducerKey(typeKey))
            {
                return key.Contains("REDUC") ||
                       key.Contains("GIAM") ||
                       key.Contains("BAUGIAM") ||
                       key.Contains("CONGIAM") ||
                       key.Contains("CONTHU") ||
                       key.Contains("RED") ||
                       key.Contains("SOCKET") && key.Contains("RED");
            }

            if (IsElbow90Key(typeKey))
            {
                // Thư viện user: SCREW-ELB90-DN15, SCREW-ELB90-DN50...
                return key.Contains("ELB90") ||
                       key.Contains("ELBOW90") ||
                       key.Contains("EL90") ||
                       key.Contains("CO90") ||
                       key.Contains("C90") ||
                       (key.Contains("CO") && key.Contains("90") &&
                        !key.Contains("ELB45") && !key.Contains("45"));
            }

            if (IsElbow45Key(typeKey))
            {
                // Thư viện user: SCREW-ELB45-DN15...
                return key.Contains("ELB45") ||
                       key.Contains("ELBOW45") ||
                       key.Contains("EL45") ||
                       key.Contains("CO45") ||
                       key.Contains("COLOI") ||
                       key.Contains("LOI45") ||
                       key.Contains("C45") ||
                       (key.Contains("CO") && key.Contains("45"));
            }

            if (IsTeeKey(typeKey))
            {
                bool wantsReducing =
                    typeKey == "TEED" ||
                    typeKey.Contains("TEGIAM") ||
                    typeKey.Contains("TETHU");

                bool isTeed =
                    Regex.IsMatch(
                        key,
                        @"(?:^|SCREW|WELD)TEED(?:DN|\d|$)",
                        RegexOptions.IgnoreCase);

                bool isTee =
                    Regex.IsMatch(
                        key,
                        @"(?:^|SCREW|WELD)TEE(?:DN|\d|$)",
                        RegexOptions.IgnoreCase);

                // Tên block PPR thật:
                // TEE-D32x32 PPR  -> TEED32X32PPR
                // TEED-D32x25 PPR -> TEEDD32X25PPR
                bool isPprReducingTee =
                    Regex.IsMatch(
                        key,
                        @"(?:^|PPR)TEEDD\d",
                        RegexOptions.IgnoreCase);

                bool isPprEqualTee =
                    !isPprReducingTee &&
                    Regex.IsMatch(
                        key,
                        @"(?:^|PPR)TEED\d",
                        RegexOptions.IgnoreCase);

                if (wantsReducing)
                {
                    return isTeed ||
                           isPprReducingTee ||
                           key.Contains("TEGIAM") ||
                           key.Contains("TETHU");
                }

                // TÊ ĐỀU không được lấy nhầm TEED.
                return isTee ||
                       isPprEqualTee ||
                       key == "TEE" ||
                       key == "TE";
            }

            // Nắp / cap
            if (typeKey.Contains("CAP") || typeKey.Contains("NAP"))
            {
                return key.Contains("CAP") ||
                       key.Contains("NAP") ||
                       key.Contains("ENDCAP");
            }

            return key.Contains(typeKey);
        }

        private bool ShopSizeLabelMatches(
            string text,
            string fromSize,
            string toSize)
        {
            if (!ShopKeyContainsSize(text, fromSize))
                return false;

            string a = CleanLayerText(fromSize ?? "");
            string b = CleanLayerText(toSize ?? "");

            if (string.Equals(
                    a,
                    b,
                    StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            return ShopKeyContainsSize(text, toSize);
        }

        private static bool ShopKeyContainsSize(
            string text,
            string sizeText)
        {
            string key = NormalizeShopKey(text);
            string sizeKey = NormalizeShopKey(sizeText);

            Match match =
                Regex.Match(
                    sizeKey,
                    @"(?:DN)?(?<N>\d{1,4}(?:\.\d+)?)");

            if (!match.Success)
                return key.Contains(sizeKey);

            string number =
                Regex.Escape(match.Groups["N"].Value);

            return Regex.IsMatch(
                key,
                @"(?<!\d)(?:DN)?" + number + @"(?!\d)",
                RegexOptions.IgnoreCase);
        }

        private static bool IsReducerKey(string key)
        {
            key = NormalizeShopKey(key);
            return key.Contains("REDUC") ||
                   key.Contains("GIAM") ||
                   key.Contains("RED");
        }

        private static bool IsElbow90Key(string key)
        {
            key = NormalizeShopKey(key);
            return key.Contains("ELB90") ||
                   key.Contains("ELBOW90") ||
                   key.Contains("EL90") ||
                   key.Contains("CO90") ||
                   key.Contains("C90");
        }

        private static bool IsElbow45Key(string key)
        {
            key = NormalizeShopKey(key);
            return key.Contains("ELB45") ||
                   key.Contains("ELBOW45") ||
                   key.Contains("EL45") ||
                   key.Contains("CO45") ||
                   key.Contains("COLOI") ||
                   key.Contains("LOI45") ||
                   key.Contains("C45");
        }

        private static bool IsTeeKey(string key)
        {
            key = NormalizeShopKey(key);

            if (key == "TEE" ||
                key == "TE" ||
                key == "TEED")
            {
                return true;
            }

            // TÊ ĐỀU  = ...-TEE-DNxxXxx
            // TÊ GIẢM = ...-TEED-DNxxXxx
            // Không dùng Contains("TEE") vì "STEEL" cũng chứa "TEE".
            return Regex.IsMatch(
                       key,
                       @"(?:^|SCREW|WELD)TEED(?:DN|\d|$)",
                       RegexOptions.IgnoreCase) ||
                   Regex.IsMatch(
                       key,
                       @"(?:^|SCREW|WELD)TEE(?:DN|\d|$)",
                       RegexOptions.IgnoreCase) ||
                   Regex.IsMatch(
                       key,
                       @"(?:^|SCREW|WELD)TE(?:DN|\d|$)",
                       RegexOptions.IgnoreCase) ||
                   key.Contains("TEGIAM") ||
                   key.Contains("TETHU");
        }

        private static bool IsStrictShopTeeName(string text)
        {
            string key =
                NormalizeShopKey(
                    text ?? "");

            return Regex.IsMatch(
                       key,
                       @"(?:^|SCREW|WELD)TEED(?:DN|\d|$)",
                       RegexOptions.IgnoreCase) ||
                   Regex.IsMatch(
                       key,
                       @"(?:^|SCREW|WELD)TEE(?:DN|\d|$)",
                       RegexOptions.IgnoreCase) ||
                   Regex.IsMatch(
                       key,
                       @"(?:^|SCREW|WELD)TE(?:DN|\d|$)",
                       RegexOptions.IgnoreCase) ||
                   key.Contains("TEGIAM") ||
                   key.Contains("TETHU");
        }

        private static bool IsReducerText(string text)
        {
            return IsShopFittingTypeText("REDUCER", text);
        }

        private static string NormalizeShopKey(string text)
        {
            string u =
                BoDauTiengViet(text ?? "")
                    .ToUpperInvariant();

            return Regex.Replace(
                u,
                @"[^A-Z0-9]+",
                "");
        }

        private void EnsureShopLayerExists(
            Transaction tr,
            Database db,
            string layerName)
        {
            EnsureLayerExists(tr, db, layerName, false);

            try
            {
                LayerTable lt =
                    (LayerTable)tr.GetObject(
                        db.LayerTableId,
                        OpenMode.ForRead);

                if (!lt.Has(layerName))
                    return;

                LayerTableRecord ltr =
                    (LayerTableRecord)tr.GetObject(
                        lt[layerName],
                        OpenMode.ForWrite);

                ltr.LineWeight = Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight000;
                ltr.Color =
                    Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                        ColorMethod.ByAci,
                        GetShopVisibleAciColor(layerName));
                ltr.Transparency =
                    new Autodesk.AutoCAD.Colors.Transparency((byte)255);
                ltr.IsOff = false;
                ltr.IsFrozen = false;
                ltr.IsLocked = false;
            }
            catch { }
        }

        private static void ApplyShopEntityStyle(
            Entity ent,
            string layerName)
        {
            if (ent == null)
                return;

            ent.Layer = layerName;
            ent.Color =
                Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                    ColorMethod.ByAci,
                    GetShopVisibleAciColor(layerName));
            ent.LineWeight = Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight000;
            ent.Transparency =
                new Autodesk.AutoCAD.Colors.Transparency((byte)255);
            ent.Visible = true;

            if (ent is Polyline pl)
                pl.ConstantWidth = 0.0;
        }

        private static short GetShopVisibleAciColor(string layerName)
        {
            string key =
                NormalizeShopKey(layerName ?? "");

            // CTN PPR dùng D ngoài thực.
            if (key.Contains("PPRD20"))
                return 3;
            if (key.Contains("PPRD25"))
                return 4;
            if (key.Contains("PPRD32"))
                return 5;
            if (key.Contains("PPRD40"))
                return 3;
            if (key.Contains("PPRD50"))
                return 1;
            if (key.Contains("PPRD63"))
                return 6;
            if (key.Contains("PPRD75"))
                return 4;
            if (key.Contains("PPRD90"))
                return 2;
            if (key.Contains("PPRD110"))
                return 5;
            if (key.Contains("PPRD125"))
                return 1;

            if (key.Contains("DN15"))
                return 2;
            if (key.Contains("DN20"))
                return 3;
            if (key.Contains("DN25"))
                return 4;
            if (key.Contains("DN32"))
                return 5;
            if (key.Contains("DN40"))
                return 3;
            if (key.Contains("DN50"))
                return 1;
            if (key.Contains("DN65"))
                return 6;
            if (key.Contains("DN80"))
                return 4;
            if (key.Contains("DN100"))
                return 2;
            if (key.Contains("DN125"))
                return 5;
            if (key.Contains("DN150"))
                return 1;

            if (key.Contains("GIAM") ||
                key.Contains("REDUC"))
                return 7;

            return 7;
        }

        /// <summary>
        /// Layer do tool tạo luôn bắt đầu bằng mã hệ thống: FF_ / ACMV_ / CTN_
        /// </summary>
        private static bool LaLayerCuaTool(string layerName)
        {
            if (string.IsNullOrWhiteSpace(layerName))
                return false;

            string u = layerName.Trim().ToUpperInvariant();

            return u.StartsWith("FF_") ||
                   u.StartsWith("ACMV_") ||
                   u.StartsWith("CTN_") ||
                   u.StartsWith("CHUA_CHAY_") ||
                   u.StartsWith("CHỮA_CHÁY_");
        }

        /// <summary>
        /// Phân biệt layer ống (vật liệu + DN) với layer van / thiết bị.
        /// </summary>
        private static string BoDauTiengViet(string s)
        {
            if (string.IsNullOrEmpty(s))
                return "";

            string u = s.ToUpperInvariant();
            // A
            u = u.Replace("Á", "A").Replace("À", "A").Replace("Ả", "A")
                 .Replace("Ã", "A").Replace("Ạ", "A")
                 .Replace("Ă", "A").Replace("Ắ", "A").Replace("Ằ", "A")
                 .Replace("Ẳ", "A").Replace("Ẵ", "A").Replace("Ặ", "A")
                 .Replace("Â", "A").Replace("Ấ", "A").Replace("Ầ", "A")
                 .Replace("Ẩ", "A").Replace("Ẫ", "A").Replace("Ậ", "A");
            // E
            u = u.Replace("É", "E").Replace("È", "E").Replace("Ẻ", "E")
                 .Replace("Ẽ", "E").Replace("Ẹ", "E")
                 .Replace("Ê", "E").Replace("Ế", "E").Replace("Ề", "E")
                 .Replace("Ể", "E").Replace("Ễ", "E").Replace("Ệ", "E");
            // O
            u = u.Replace("Ó", "O").Replace("Ò", "O").Replace("Ỏ", "O")
                 .Replace("Õ", "O").Replace("Ọ", "O")
                 .Replace("Ô", "O").Replace("Ố", "O").Replace("Ồ", "O")
                 .Replace("Ổ", "O").Replace("Ỗ", "O").Replace("Ộ", "O")
                 .Replace("Ơ", "O").Replace("Ớ", "O").Replace("Ờ", "O")
                 .Replace("Ở", "O").Replace("Ỡ", "O").Replace("Ợ", "O");
            // U
            u = u.Replace("Ú", "U").Replace("Ù", "U").Replace("Ủ", "U")
                 .Replace("Ũ", "U").Replace("Ụ", "U")
                 .Replace("Ư", "U").Replace("Ứ", "U").Replace("Ừ", "U")
                 .Replace("Ử", "U").Replace("Ữ", "U").Replace("Ự", "U");
            // I Y D
            u = u.Replace("Í", "I").Replace("Ì", "I").Replace("Ỉ", "I")
                 .Replace("Ĩ", "I").Replace("Ị", "I")
                 .Replace("Ý", "Y").Replace("Ỳ", "Y").Replace("Ỷ", "Y")
                 .Replace("Ỹ", "Y").Replace("Ỵ", "Y")
                 .Replace("Đ", "D");
            return u;
        }

        private static bool LaLayerOng(string layerName)
        {
            if (string.IsNullOrWhiteSpace(layerName))
                return false;

            // Nếu đã nhận là van/thiết bị → không coi là ống
            if (LaLayerThietBiHoacVan(layerName))
                return false;

            string u = BoDauTiengViet(layerName.Trim());

            string[] vatLieuOng =
            {
                "TRANG KEM", "TRANGKEM", "HDPE", "THEP DEN", "THEPDEN",
                "INOX", "NHUNG NONG", "NHUNGNONG", "UPVC", "ONG DONG",
                "ONGDONG", "OG THAI", "OG HUT", "OG LANH", "OG CAP",
                "OG HOI", "PPR", "PVC", "PEHD", "THEP"
            };

            foreach (var vl in vatLieuOng)
            {
                if (u.Contains(vl))
                    return true;
            }

            // Size ống gió WxH trên layer OG
            if (Regex.IsMatch(u, @"\d+\s*X\s*\d+") &&
                (u.Contains("OG ") || u.Contains("OG_") || u.Contains("_OG")))
                return true;

            // DN + vật liệu ống (không phải van)
            if (Regex.IsMatch(u, @"DN\s*\d+") &&
                (u.Contains("TRANG") || u.Contains("HDPE") ||
                 u.Contains("THEP") || u.Contains("INOX") ||
                 u.Contains("UPVC") || u.Contains("DONG")))
                return true;

            return false;
        }

        private static bool LaLayerThietBiHoacVan(string layerName)
        {
            if (string.IsNullOrWhiteSpace(layerName))
                return false;

            string u = BoDauTiengViet(layerName.Trim());

            string[] keywords =
            {
                // Van (kể cả V.CỔNG sau khi bỏ dấu → V.CONG)
                "VAN", "V.CONG", "VCONG", "V. CONG", "CONG TN", "CONG TC",
                "CONG DIEN", "Y LOC", "YLOC", "KNM",
                "VCD", "MFD", "PRD", "LOUVER", "DAMPER",
                "MG CAP", "MG THAI", "VAN 1C", "VAN1C",
                // Thiết bị FF / ACMV / CTN
                "BINH", "DAU PHUN", "DAUPHUN", "PHUN",
                "MAY LANH", "MAYLANH", "QUAT", "BOM",
                "DONG HO", "DONGHO", "BON NUOC", "BON ",
                "CASSETTE", "GAN TUONG", "AM TRAN", "AP TRAN", "DAN NONG",
                "HL-", "HX-", "HN-", " HL ", " HX ", " HN ",
                "BE NUOC", "BE GOI", "THIET BI"
            };

            foreach (var k in keywords)
            {
                if (u.Contains(k))
                    return true;
            }

            return false;
        }


        // ============================================================
        // THỐNG KÊ PHỤ KIỆN VẼ SHOP CHỮA CHÁY
        // Chỉ đọc BlockReference nằm trên các layer FF_SHOP_* phụ kiện.
        // Không can thiệp vào logic VẼ SHOP / chèn reducer / co / tê.
        // ============================================================

        private class ShopFittingStatRow
        {
            public int STT { get; set; }
            public string Loai { get; set; }
            public string KichThuoc { get; set; }
            public string KieuNoi { get; set; }
            public double SoLuong { get; set; }
            public int LoaiSort { get; set; }
            public double KichThuocSort { get; set; }
        }

        private void BtnThongKePhuKienShop_Click(
            object sender,
            RoutedEventArgs e)
        {
            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var ed = doc.Editor;
            var db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            using (doc.LockDocument())
            {
                PromptSelectionOptions pso =
                    new PromptSelectionOptions();

                pso.MessageForAdding =
                    "\n[THỐNG KÊ PHỤ KIỆN SHOP] " +
                    "Quét chọn khu vực có Co / Tê / Giảm cần thống kê: ";

                SelectionFilter filter =
                    new SelectionFilter(
                        new TypedValue[]
                        {
                            new TypedValue(
                                (int)DxfCode.Start,
                                "INSERT")
                        });

                PromptSelectionResult psr =
                    ed.GetSelection(
                        pso,
                        filter);

                if (psr.Status != PromptStatus.OK ||
                    psr.Value == null ||
                    psr.Value.Count == 0)
                {
                    return;
                }

                Dictionary<string, ShopFittingStatRow> dict =
                    new Dictionary<string, ShopFittingStatRow>(
                        StringComparer.OrdinalIgnoreCase);

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    foreach (SelectedObject so in psr.Value)
                    {
                        if (so == null ||
                            so.ObjectId.IsNull)
                        {
                            continue;
                        }

                        BlockReference br =
                            tr.GetObject(
                                so.ObjectId,
                                OpenMode.ForRead,
                                false) as BlockReference;

                        if (br == null ||
                            br.IsErased)
                        {
                            continue;
                        }

                        string layer =
                            br.Layer ?? "";

                        if (!TryGetShopFittingStatIdentity(
                                tr,
                                br,
                                layer,
                                out string loai,
                                out string kichThuoc,
                                out string kieuNoi,
                                out int loaiSort,
                                out double sizeSort))
                        {
                            continue;
                        }

                        string key =
                            loai + "|" +
                            kichThuoc + "|" +
                            kieuNoi;

                        if (!dict.TryGetValue(
                                key,
                                out ShopFittingStatRow row))
                        {
                            row =
                                new ShopFittingStatRow
                                {
                                    Loai = loai,
                                    KichThuoc = kichThuoc,
                                    KieuNoi = kieuNoi,
                                    SoLuong = 0.0,
                                    LoaiSort = loaiSort,
                                    KichThuocSort = sizeSort
                                };

                            dict[key] = row;
                        }

                        row.SoLuong += 1.0;
                    }

                    tr.Commit();
                }

                if (dict.Count == 0)
                {
                    MessageBox.Show(
                        "Không tìm thấy phụ kiện SHOP trong vùng chọn.\n\n" +
                        "Chỉ đếm block trên các layer:\n" +
                        "FF_SHOP_CO90_...\n" +
                        "FF_SHOP_COLOI45_...\n" +
                        "FF_SHOP_TE_...\n" +
                        "FF_SHOP_GIAM_...",
                        "THỐNG KÊ PHỤ KIỆN SHOP");
                    return;
                }

                List<ShopFittingStatRow> data =
                    dict.Values
                        .OrderBy(x => x.LoaiSort)
                        .ThenByDescending(x => x.KichThuocSort)
                        .ThenBy(x => x.KichThuoc)
                        .ThenBy(x => x.KieuNoi)
                        .ToList();

                for (int i = 0; i < data.Count; i++)
                    data[i].STT = i + 1;

                double tong =
                    data.Sum(x => x.SoLuong);

                ed.WriteMessage(
                    $"\n[THỐNG KÊ PHỤ KIỆN SHOP] " +
                    $"Tìm thấy {FormatSoThongKe(tong)} phụ kiện, " +
                    $"{data.Count} chủng loại/kích thước.");

                XuatBangThongKePhuKienShop(
                    data);
            }
        }

        private bool TryGetShopFittingStatIdentity(
            Transaction tr,
            BlockReference br,
            string layer,
            out string loai,
            out string kichThuoc,
            out string kieuNoi,
            out int loaiSort,
            out double sizeSort)
        {
            loai = "";
            kichThuoc = "";
            kieuNoi = "";
            loaiSort = 999;
            sizeSort = 0.0;

            if (tr == null ||
                br == null)
            {
                return false;
            }

            string layerUpper =
                (layer ?? "")
                    .Trim()
                    .ToUpperInvariant();

            // Chỉ nhận đúng phụ kiện do VẼ SHOP tạo.
            // Thứ tự phải kiểm tra CO90_DAUPHUN trước CO90 thường.
            if (layerUpper.StartsWith(
                    "FF_SHOP_CO90_DAUPHUN_",
                    StringComparison.OrdinalIgnoreCase))
            {
                loai = "CO 90 ĐẦU PHUN";
                loaiSort = 11;
                kichThuoc =
                    ExtractShopStatSingleSize(
                        layer,
                        "FF_SHOP_CO90_DAUPHUN_");
            }
            else if (layerUpper.StartsWith(
                         "FF_SHOP_CO90_",
                         StringComparison.OrdinalIgnoreCase))
            {
                loai = "CO 90";
                loaiSort = 10;
                kichThuoc =
                    ExtractShopStatSingleSize(
                        layer,
                        "FF_SHOP_CO90_");
            }
            else if (layerUpper.StartsWith(
                         "FF_SHOP_COLOI45_",
                         StringComparison.OrdinalIgnoreCase))
            {
                loai = "CO 45 / CO LƠI";
                loaiSort = 20;
                kichThuoc =
                    ExtractShopStatSingleSize(
                        layer,
                        "FF_SHOP_COLOI45_");
            }
            else if (layerUpper.StartsWith(
                         "FF_SHOP_TE_",
                         StringComparison.OrdinalIgnoreCase))
            {
                loai = "TÊ";
                loaiSort = 30;
                kichThuoc =
                    ExtractShopStatPairSize(
                        layer,
                        "FF_SHOP_TE_");
            }
            else if (layerUpper.StartsWith(
                         "FF_SHOP_GIAM_",
                         StringComparison.OrdinalIgnoreCase))
            {
                loai = "GIẢM";
                loaiSort = 40;
                kichThuoc =
                    ExtractShopStatPairSize(
                        layer,
                        "FF_SHOP_GIAM_");
            }
            else
            {
                return false;
            }

            string blockName =
                GetShopStatBlockName(
                    tr,
                    br);

            kieuNoi =
                GetShopStatConnectionType(
                    blockName);

            // Nếu layer cũ thiếu size, lấy lại từ tên block.
            if (string.IsNullOrWhiteSpace(kichThuoc))
            {
                kichThuoc =
                    ExtractShopStatSizeFromBlockName(
                        blockName,
                        loai);
            }

            if (string.IsNullOrWhiteSpace(kichThuoc))
                kichThuoc = "-";

            sizeSort =
                GetShopStatSortSize(
                    kichThuoc);

            return true;
        }

        private string GetSmartBlockIdentityKey(
            Transaction tr,
            BlockReference br)
        {
            if (tr == null ||
                br == null)
            {
                return "";
            }

            string baseName =
                GetShopStatBlockName(
                    tr,
                    br);

            string baseKey =
                NormalizeSmartSymbolKey(
                    baseName);

            if (string.IsNullOrWhiteSpace(
                    baseKey))
            {
                return "";
            }

            string state =
                GetSmartDynamicBlockStateKey(
                    br);

            return
                string.IsNullOrWhiteSpace(
                    state)
                    ? baseKey
                    : baseKey +
                      "|STATE=" +
                      state;
        }

        private string GetSmartDynamicBlockStateKey(
            BlockReference br)
        {
            if (br == null ||
                !br.IsDynamicBlock)
            {
                return "";
            }

            List<string> pieces =
                new List<string>();

            try
            {
                DynamicBlockReferencePropertyCollection props =
                    br.DynamicBlockReferencePropertyCollection;

                foreach (DynamicBlockReferenceProperty prop
                    in props)
                {
                    if (prop == null)
                        continue;

                    string propertyName =
                        NormalizeSmartSymbolKey(
                            prop.PropertyName ?? "");

                    if (string.IsNullOrWhiteSpace(
                            propertyName))
                    {
                        continue;
                    }

                    string plainName =
                        BoDauTiengViet(
                            propertyName)
                            .ToUpperInvariant();

                    bool isStateProperty =
                        plainName.Contains("VISIBILITY") ||
                        plainName.Contains("LOOKUP") ||
                        plainName.Contains("STATE") ||
                        plainName.Contains("TYPE") ||
                        plainName.Contains("KIEU") ||
                        plainName.Contains("LOAI") ||
                        plainName.Contains("TRANG THAI");

                    if (!isStateProperty)
                        continue;

                    string value =
                        "";

                    try
                    {
                        value =
                            Convert.ToString(
                                prop.Value,
                                CultureInfo.InvariantCulture) ?? "";
                    }
                    catch
                    {
                    }

                    value =
                        NormalizeSmartSymbolKey(
                            value);

                    if (!string.IsNullOrWhiteSpace(
                            value))
                    {
                        pieces.Add(
                            propertyName +
                            "=" +
                            value);
                    }
                }
            }
            catch
            {
            }

            return
                pieces.Count == 0
                    ? ""
                    : string.Join(
                        ";",
                        pieces
                            .Distinct(
                                StringComparer.OrdinalIgnoreCase)
                            .OrderBy(
                                x => x,
                                StringComparer.OrdinalIgnoreCase));
        }

        private string GetShopStatBlockName(
            Transaction tr,
            BlockReference br)
        {
            if (tr == null ||
                br == null)
            {
                return "";
            }

            try
            {
                ObjectId defId =
                    br.BlockTableRecord;

                if (br.IsDynamicBlock &&
                    !br.DynamicBlockTableRecord.IsNull &&
                    br.DynamicBlockTableRecord.IsValid)
                {
                    defId =
                        br.DynamicBlockTableRecord;
                }

                BlockTableRecord rec =
                    tr.GetObject(
                        defId,
                        OpenMode.ForRead,
                        false) as BlockTableRecord;

                return rec?.Name ?? "";
            }
            catch
            {
                return "";
            }
        }

        private static string GetShopStatConnectionType(
            string blockName)
        {
            string key =
                NormalizeShopKey(
                    blockName ?? "");

            if (key.Contains("SCREW"))
                return "SCREW";

            if (key.Contains("WELD"))
                return "WELD";

            if (key.Contains("PPR"))
                return "PPR";

            if (key.Contains("UPVC") ||
                key.Contains("PVC"))
            {
                return "uPVC";
            }

            return "-";
        }

        private string ExtractShopStatSingleSize(
            string layer,
            string prefix)
        {
            if (string.IsNullOrWhiteSpace(layer) ||
                string.IsNullOrWhiteSpace(prefix))
            {
                return "";
            }

            string tail =
                layer.Length >= prefix.Length
                    ? layer.Substring(prefix.Length)
                    : "";

            Match m =
                Regex.Match(
                    tail,
                    @"DN\s*(\d{1,4}(?:[.,]\d+)?)",
                    RegexOptions.IgnoreCase);

            if (!m.Success)
            {
                m =
                    Regex.Match(
                        tail,
                        @"(\d{1,4}(?:[.,]\d+)?)");
            }

            if (!m.Success)
                return "";

            return "DN" +
                m.Groups[1]
                    .Value
                    .Replace(',', '.');
        }

        private string ExtractShopStatPairSize(
            string layer,
            string prefix)
        {
            if (string.IsNullOrWhiteSpace(layer) ||
                string.IsNullOrWhiteSpace(prefix))
            {
                return "";
            }

            string tail =
                layer.Length >= prefix.Length
                    ? layer.Substring(prefix.Length)
                    : "";

            MatchCollection ms =
                Regex.Matches(
                    tail,
                    @"(?:DN\s*)?(\d{1,4}(?:[.,]\d+)?)",
                    RegexOptions.IgnoreCase);

            if (ms.Count < 2)
                return "";

            string a =
                ms[0].Groups[1]
                    .Value
                    .Replace(',', '.');

            string b =
                ms[1].Groups[1]
                    .Value
                    .Replace(',', '.');

            return "DN" + a + "x" + b;
        }

        private string ExtractShopStatSizeFromBlockName(
            string blockName,
            string loai)
        {
            if (string.IsNullOrWhiteSpace(blockName))
                return "";

            string raw =
                blockName
                    .Replace('_', '-')
                    .ToUpperInvariant();

            bool isPair =
                string.Equals(
                    loai,
                    "TÊ",
                    StringComparison.OrdinalIgnoreCase) ||
                string.Equals(
                    loai,
                    "GIẢM",
                    StringComparison.OrdinalIgnoreCase);

            if (isPair)
            {
                Match pair =
                    Regex.Match(
                        raw,
                        @"DN\s*(\d{1,4}(?:[.,]\d+)?)\s*[xX×]\s*(?:DN\s*)?(\d{1,4}(?:[.,]\d+)?)",
                        RegexOptions.IgnoreCase);

                if (pair.Success)
                {
                    return "DN" +
                        pair.Groups[1].Value.Replace(',', '.') +
                        "x" +
                        pair.Groups[2].Value.Replace(',', '.');
                }
            }

            Match one =
                Regex.Match(
                    raw,
                    @"DN\s*(\d{1,4}(?:[.,]\d+)?)",
                    RegexOptions.IgnoreCase);

            if (one.Success)
            {
                return "DN" +
                    one.Groups[1]
                        .Value
                        .Replace(',', '.');
            }

            return "";
        }

        private static double GetShopStatSortSize(
            string size)
        {
            if (string.IsNullOrWhiteSpace(size))
                return 0.0;

            MatchCollection ms =
                Regex.Matches(
                    size,
                    @"\d+(?:[.,]\d+)?");

            double max = 0.0;

            foreach (Match m in ms)
            {
                if (double.TryParse(
                        m.Value.Replace(',', '.'),
                        NumberStyles.Any,
                        CultureInfo.InvariantCulture,
                        out double value))
                {
                    if (value > max)
                        max = value;
                }
            }

            return max;
        }

        private void XuatBangThongKePhuKienShop(
            List<ShopFittingStatRow> data)
        {
            if (data == null ||
                data.Count == 0)
            {
                return;
            }

            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var db = doc.Database;
            var ed = doc.Editor;

            PromptPointResult ppr =
                ed.GetPoint(
                    new PromptPointOptions(
                        "\nKích chọn vị trí đặt BẢNG THỐNG KÊ PHỤ KIỆN SHOP: "));

            if (ppr.Status != PromptStatus.OK)
                return;

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                BlockTableRecord btr =
                    (BlockTableRecord)tr.GetObject(
                        db.CurrentSpaceId,
                        OpenMode.ForWrite);

                Table tb =
                    new Table
                    {
                        TableStyle = db.Tablestyle,
                        Position = ppr.Value
                    };

                tb.Color =
                    Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                        ColorMethod.ByAci,
                        2);

                const int soCot = 5;
                int soDong =
                    data.Count + 3;

                tb.SetSize(
                    soDong,
                    soCot);

                // Tỷ lệ tương thích bản vẽ mm nhưng nhỏ gọn hơn bảng tổng hợp cũ.
                // FIX29: bảng cũ đang quá lớn. Thu nhỏ khoảng 3 lần.
                double sf = 1.35;
                double textH = 100.0 * sf;

                for (int r = 0;
                    r < tb.Rows.Count;
                    r++)
                {
                    tb.Rows[r].Height =
                        (r == 0 ? 330.0 : 240.0) * sf;

                    for (int c = 0;
                        c < tb.Columns.Count;
                        c++)
                    {
                        tb.Cells[r, c].TextStyleId =
                            db.Textstyle;

                        tb.Cells[r, c].TextHeight =
                            textH;
                    }
                }

                tb.Columns[0].Width = 650.0 * sf;
                tb.Columns[1].Width = 2450.0 * sf;
                tb.Columns[2].Width = 1750.0 * sf;
                tb.Columns[3].Width = 1250.0 * sf;
                tb.Columns[4].Width = 1350.0 * sf;

                // FIX31: Không dùng API margin của Table/Cell vì khác nhau
                // giữa các phiên bản AutoCAD. Độ thoáng được xử lý bằng
                // chiều rộng cột + text height để tương thích ổn định.

                try
                {
                    tb.MergeCells(
                        CellRange.Create(
                            tb,
                            0,
                            0,
                            0,
                            soCot - 1));
                }
                catch
                {
                }

                tb.Cells[0, 0].TextString =
                    "BẢNG THỐNG KÊ PHỤ KIỆN SHOP CHỮA CHÁY";

                tb.Cells[0, 0].Alignment =
                    CellAlignment.MiddleCenter;

                tb.Cells[1, 0].TextString = "STT";
                tb.Cells[1, 1].TextString = "LOẠI PHỤ KIỆN";
                tb.Cells[1, 2].TextString = "KÍCH THƯỚC";
                tb.Cells[1, 3].TextString = "KIỂU NỐI";
                tb.Cells[1, 4].TextString = "SỐ LƯỢNG (cái)";

                for (int c = 0; c < soCot; c++)
                {
                    tb.Cells[1, c].Alignment =
                        CellAlignment.MiddleCenter;
                }

                int rowIndex = 2;

                foreach (ShopFittingStatRow item in data)
                {
                    tb.Cells[rowIndex, 0].TextString =
                        item.STT.ToString();

                    tb.Cells[rowIndex, 1].TextString =
                        item.Loai ?? "";

                    tb.Cells[rowIndex, 2].TextString =
                        item.KichThuoc ?? "";

                    tb.Cells[rowIndex, 3].TextString =
                        item.KieuNoi ?? "";

                    tb.Cells[rowIndex, 4].TextString =
                        FormatSoThongKe(
                            item.SoLuong);

                    tb.Cells[rowIndex, 0].Alignment =
                        CellAlignment.MiddleCenter;

                    tb.Cells[rowIndex, 1].Alignment =
                        CellAlignment.MiddleLeft;

                    tb.Cells[rowIndex, 2].Alignment =
                        CellAlignment.MiddleCenter;

                    tb.Cells[rowIndex, 3].Alignment =
                        CellAlignment.MiddleCenter;

                    tb.Cells[rowIndex, 4].Alignment =
                        CellAlignment.MiddleCenter;

                    rowIndex++;
                }

                try
                {
                    tb.MergeCells(
                        CellRange.Create(
                            tb,
                            rowIndex,
                            0,
                            rowIndex,
                            3));
                }
                catch
                {
                }

                tb.Cells[rowIndex, 0].TextString =
                    "TỔNG";

                tb.Cells[rowIndex, 0].Alignment =
                    CellAlignment.MiddleCenter;

                tb.Cells[rowIndex, 4].TextString =
                    FormatSoThongKe(
                        data.Sum(x => x.SoLuong));

                tb.Cells[rowIndex, 4].Alignment =
                    CellAlignment.MiddleCenter;

                tb.GenerateLayout();

                btr.AppendEntity(tb);
                tr.AddNewlyCreatedDBObject(
                    tb,
                    true);

                tr.Commit();
            }
        }


        private void BtnThongKeOng_Click(
            object sender,
            RoutedEventArgs e)
        {
            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var ed = doc.Editor;
            var db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            using (doc.LockDocument())
            {
                // FIX40:
                // Trước đây chỉ chọn LWPOLYLINE nên:
                // - ống vẽ bằng LINE không thống kê được;
                // - ống SHOP cũng không thống kê được vì SHOP chủ yếu là LINE.
                //
                // Mở rộng cho LINE / LWPOLYLINE / ARC.
                // TRỤC ĐỨNG được lưu bằng BlockReference có XData riêng,
                // nên bổ sung INSERT vào bộ lọc.
                TypedValue[] tvs =
                    new TypedValue[]
                    {
                        new TypedValue(
                            (int)DxfCode.Start,
                            "LINE,LWPOLYLINE,ARC,INSERT")
                    };

                SelectionFilter filter =
                    new SelectionFilter(tvs);

                PromptSelectionOptions pso =
                    new PromptSelectionOptions();

                pso.MessageForAdding =
                    "\nQuét chọn khu vực ống cần thống kê " +
                    "(hỗ trợ ống thường + ống SHOP + TRỤC ĐỨNG): ";

                PromptSelectionResult psr =
                    ed.GetSelection(
                        pso,
                        filter);

                if (psr.Status != PromptStatus.OK ||
                    psr.Value == null ||
                    psr.Value.Count == 0)
                {
                    return;
                }

                Dictionary<string, double> dictChieuDaiNgang =
                    new Dictionary<string, double>(
                        StringComparer.OrdinalIgnoreCase);

                Dictionary<string, double> dictChieuDaiDung =
                    new Dictionary<string, double>(
                        StringComparer.OrdinalIgnoreCase);

                int shopCenterCount = 0;
                int normalPipeCount = 0;
                int verticalRiserCount = 0;

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    foreach (SelectedObject so in psr.Value)
                    {
                        if (so == null ||
                            so.ObjectId.IsNull)
                        {
                            continue;
                        }

                        Entity ent =
                            tr.GetObject(
                                so.ObjectId,
                                OpenMode.ForRead,
                                false) as Entity;

                        if (ent == null ||
                            ent.IsErased)
                        {
                            continue;
                        }

                        // ==================================================
                        // TRỤC ĐỨNG
                        // ==================================================
                        // Chiều cao đã nhập là mét. Đổi sang mm khi đưa vào
                        // dictionary để cùng đơn vị với Curve hiện tại.
                        if (ent is BlockReference &&
                            TryReadVerticalRiserData(
                                ent,
                                out VerticalRiserData riser))
                        {
                            string riserLayer =
                                (riser.PipeLayer ?? ent.Layer ?? "")
                                    .Trim();

                            if (string.IsNullOrWhiteSpace(riserLayer) ||
                                !LaLayerCuaTool(riserLayer) ||
                                riser.HeightMeters <= 0.0)
                            {
                                continue;
                            }

                            if (!dictChieuDaiDung.ContainsKey(riserLayer))
                                dictChieuDaiDung[riserLayer] = 0.0;

                            dictChieuDaiDung[riserLayer] +=
                                riser.HeightMeters * 1000.0;

                            verticalRiserCount++;
                            continue;
                        }

                        Curve curve =
                            ent as Curve;

                        if (curve == null)
                            continue;

                        string layer =
                            (ent.Layer ?? "")
                                .Trim();

                        if (string.IsNullOrWhiteSpace(layer))
                            continue;

                        // Chỉ thống kê layer do tool tạo.
                        if (!LaLayerCuaTool(layer))
                            continue;

                        // ==================================================
                        // ỐNG SHOP
                        // ==================================================
                        // Khi VẼ SHOP, mỗi đoạn có:
                        // 1) hai nét biên: FF_SHOP_DNxx
                        // 2) một nét tâm: FF_SHOP_TAM_DNxx
                        //
                        // Nếu cộng hai nét biên => chiều dài x2.
                        // Vì vậy CHỈ lấy FF_SHOP_TAM_* để thống kê.
                        if (LaLayerTamOngShop(layer))
                        {
                            string outputLayer =
                                LayTenLayerOngShopTuLayerTam(
                                    layer);

                            if (string.IsNullOrWhiteSpace(outputLayer))
                                continue;

                            double length =
                                LayChieuDaiCurveThongKe(
                                    curve);

                            if (length <= 1e-9)
                                continue;

                            if (!dictChieuDaiNgang.ContainsKey(outputLayer))
                                dictChieuDaiNgang[outputLayer] = 0.0;

                            dictChieuDaiNgang[outputLayer] += length;
                            shopCenterCount++;
                            continue;
                        }

                        // Hai nét biên SHOP không tính, vì đã có đường tâm.
                        if (LaLayerBienOngShop(layer))
                            continue;

                        // Bỏ các layer phụ kiện SHOP / layer tạm SHOP.
                        if (LaLayerPhuKienHoacTamShop(layer))
                            continue;

                        // ==================================================
                        // ỐNG THƯỜNG
                        // ==================================================
                        // Giữ logic cũ nhưng cho phép cả LINE + ARC.
                        if (!LaLayerOng(layer))
                            continue;

                        double normalLength =
                            LayChieuDaiCurveThongKe(
                                curve);

                        if (normalLength <= 1e-9)
                            continue;

                        if (!dictChieuDaiNgang.ContainsKey(layer))
                            dictChieuDaiNgang[layer] = 0.0;

                        dictChieuDaiNgang[layer] += normalLength;
                        normalPipeCount++;
                    }

                    tr.Commit();
                }

                if (dictChieuDaiNgang.Count == 0 &&
                    dictChieuDaiDung.Count == 0)
                {
                    MessageBox.Show(
                        "Không tìm thấy ống hợp lệ trong vùng chọn.\n\n" +
                        "Hỗ trợ:\n" +
                        "• Ống thường: LINE / POLYLINE / ARC trên layer ống của tool.\n" +
                        "• Ống SHOP: tự lấy đường tâm FF_SHOP_TAM_DN... " +
                        "để không bị nhân đôi chiều dài.\n" +
                        "• TRỤC ĐỨNG: block được tạo bằng nút TRỤC ĐỨNG.",
                        "THỐNG KÊ ỐNG");
                    return;
                }

                List<ThongKeOng> danhSachThongKe =
                    new List<ThongKeOng>();

                HashSet<string> statisticLayers =
                    new HashSet<string>(
                        dictChieuDaiNgang.Keys,
                        StringComparer.OrdinalIgnoreCase);

                statisticLayers.UnionWith(
                    dictChieuDaiDung.Keys);

                foreach (string statisticLayer in statisticLayers)
                {
                    double horizontalDrawingLength =
                        dictChieuDaiNgang.TryGetValue(
                            statisticLayer,
                            out double horizontalValue)
                            ? horizontalValue
                            : 0.0;

                    double verticalDrawingLength =
                        dictChieuDaiDung.TryGetValue(
                            statisticLayer,
                            out double verticalValue)
                            ? verticalValue
                            : 0.0;

                    double kichThuoc = 0.0;

                    Match match =
                        Regex.Match(
                            statisticLayer,
                            @"\d+(\.\d+)?");

                    if (match.Success)
                    {
                        double.TryParse(
                            match.Value,
                            NumberStyles.Any,
                            CultureInfo.InvariantCulture,
                            out kichThuoc);
                    }

                    string heThongSort =
                        statisticLayer;

                    if (heThongSort.StartsWith(
                            "FF_SHOP_",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        heThongSort = "FF_SHOP";
                    }
                    else if (heThongSort.StartsWith(
                            "CTN_SHOP_",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        heThongSort = "CTN_SHOP";
                    }
                    else if (heThongSort.Contains("_"))
                    {
                        heThongSort =
                            heThongSort.Split('_')[0];
                    }

                    double horizontalLengthM =
                        horizontalDrawingLength / 1000.0;

                    double verticalLengthM =
                        verticalDrawingLength / 1000.0;

                    double lengthM =
                        horizontalLengthM +
                        verticalLengthM;

                    danhSachThongKe.Add(
                        new ThongKeOng
                        {
                            TenLayer = statisticLayer,
                            SoLuong =
                                Math.Round(
                                    lengthM,
                                    2),

                            ChieuDaiNgang =
                                Math.Round(
                                    horizontalLengthM,
                                    2),

                            ChieuDaiDung =
                                Math.Round(
                                    verticalLengthM,
                                    2),

                            // Ống SHOP tròn không tính M2 bằng công thức ống gió.
                            // Các layer ống thường vẫn giữ nguyên logic cũ.
                            M2 =
                                (statisticLayer.StartsWith(
                                     "FF_SHOP_",
                                     StringComparison.OrdinalIgnoreCase) ||
                                 statisticLayer.StartsWith(
                                     "CTN_SHOP_",
                                     StringComparison.OrdinalIgnoreCase))
                                    ? 0.0
                                    : Math.Round(
                                        TinhM2OngGioTuLayer(
                                            statisticLayer,
                                            lengthM),
                                        2),

                            HeThongSort =
                                heThongSort,

                            KichThuocSort =
                                kichThuoc
                        });
                }

                List<ThongKeOng> danhSachDaSapXep =
                    danhSachThongKe
                        .OrderBy(x => x.HeThongSort)
                        .ThenByDescending(
                            x => x.KichThuocSort)
                        .ThenBy(x => x.TenLayer)
                        .ToList();

                for (int i = 0;
                    i < danhSachDaSapXep.Count;
                    i++)
                {
                    danhSachDaSapXep[i].STT = i + 1;
                }

                ed.WriteMessage(
                    $"\n[THỐNG KÊ ỐNG + TRỤC ĐỨNG] " +
                    $"Ống thường={normalPipeCount} entity | " +
                    $"SHOP tâm={shopCenterCount} entity | " +
                    $"Trục đứng={verticalRiserCount} block | " +
                    $"Chủng loại={danhSachDaSapXep.Count}");

                XuatBangRaCad(
                    danhSachDaSapXep,
                    "BẢNG THỐNG KÊ KHỐI LƯỢNG ỐNG",
                    "SỐ LƯỢNG (m)",
                    true,
                    true);
            }
        }

        private static bool LaLayerTamOngShop(
            string layerName)
        {
            if (string.IsNullOrWhiteSpace(layerName))
                return false;

            string u =
                layerName
                    .Trim()
                    .ToUpperInvariant();

            return
                u.StartsWith("FF_SHOP_TAM_") ||
                u.StartsWith("CTN_SHOP_TAM_");
        }

        private static bool LaLayerBienOngShop(
            string layerName)
        {
            if (string.IsNullOrWhiteSpace(
                    layerName))
            {
                return false;
            }

            string u =
                layerName
                    .Trim()
                    .ToUpperInvariant();

            if (u.StartsWith(
                    "FF_SHOP_"))
            {
                if (u.StartsWith("FF_SHOP_TAM_") ||
                    u.StartsWith("FF_SHOP_CO90_") ||
                    u.StartsWith("FF_SHOP_COLOI45_") ||
                    u.StartsWith("FF_SHOP_TE_") ||
                    u.StartsWith("FF_SHOP_GIAM_") ||
                    u.StartsWith("FF_SHOP_PK_"))
                {
                    return false;
                }

                return Regex.IsMatch(
                    u,
                    @"^FF_SHOP_DN\s*\d+(?:[.,]\d+)?$",
                    RegexOptions.IgnoreCase);
            }

            if (u.StartsWith(
                    "CTN_SHOP_"))
            {
                if (u.StartsWith("CTN_SHOP_TAM_") ||
                    u.StartsWith("CTN_SHOP_CO90_") ||
                    u.StartsWith("CTN_SHOP_COLOI45_") ||
                    u.StartsWith("CTN_SHOP_TE_") ||
                    u.StartsWith("CTN_SHOP_GIAM_") ||
                    u.StartsWith("CTN_SHOP_PK_"))
                {
                    return false;
                }

                // PPR hiện tại:
                // CTN_SHOP_PPR_D20 / CTN_SHOP_PPR_D25 / ...
                return Regex.IsMatch(
                    u,
                    @"^CTN_SHOP_PPR_D\s*\d+(?:[.,]\d+)?$",
                    RegexOptions.IgnoreCase);
            }

            return false;
        }


        private static bool LaLayerPhuKienHoacTamShop(
            string layerName)
        {
            if (string.IsNullOrWhiteSpace(layerName))
                return false;

            string u =
                layerName
                    .Trim()
                    .ToUpperInvariant();

            return
                u.StartsWith("FF_SHOP_CO90_") ||
                u.StartsWith("FF_SHOP_COLOI45_") ||
                u.StartsWith("FF_SHOP_TE_") ||
                u.StartsWith("FF_SHOP_GIAM_") ||
                u.StartsWith("FF_SHOP_TAM_") ||
                u.StartsWith("CTN_SHOP_CO90_") ||
                u.StartsWith("CTN_SHOP_COLOI45_") ||
                u.StartsWith("CTN_SHOP_TE_") ||
                u.StartsWith("CTN_SHOP_GIAM_") ||
                u.StartsWith("CTN_SHOP_TAM_");
        }

        private static string LayTenLayerOngShopTuLayerTam(
            string centerLayer)
        {
            if (!LaLayerTamOngShop(
                    centerLayer))
            {
                return "";
            }

            string value =
                centerLayer
                    .Trim();

            if (value.StartsWith(
                    "CTN_SHOP_TAM_",
                    StringComparison.OrdinalIgnoreCase))
            {
                string tail =
                    value.Substring(
                        "CTN_SHOP_TAM_".Length)
                        .Trim();

                return string.IsNullOrWhiteSpace(
                        tail)
                    ? ""
                    : "CTN_SHOP_" +
                      tail;
            }

            if (value.StartsWith(
                    "FF_SHOP_TAM_",
                    StringComparison.OrdinalIgnoreCase))
            {
                string tail =
                    value.Substring(
                        "FF_SHOP_TAM_".Length)
                        .Trim();

                return string.IsNullOrWhiteSpace(
                        tail)
                    ? ""
                    : "FF_SHOP_" +
                      tail;
            }

            return "";
        }


        private static double LayChieuDaiCurveThongKe(
            Curve curve)
        {
            if (curve == null)
                return 0.0;

            try
            {
                if (curve is Line ln)
                    return ln.Length;

                if (curve is Polyline pl)
                    return pl.Length;

                if (curve is Arc arc)
                    return arc.Length;

                // Fallback cho Curve khác nếu sau này mở rộng.
                double endParam =
                    curve.EndParam;

                return curve.GetDistanceAtParameter(
                    endParam);
            }
            catch
            {
                try
                {
                    return curve.StartPoint.DistanceTo(
                        curve.EndPoint);
                }
                catch
                {
                    return 0.0;
                }
            }
        }


