        private string SmartSymbolLibraryPath
        {
            get
            {
                try
                {
                    string baseFolder =
                        Environment.GetFolderPath(
                            Environment.SpecialFolder.LocalApplicationData);

                    if (string.IsNullOrWhiteSpace(
                            baseFolder))
                    {
                        baseFolder =
                            Path.GetTempPath();
                    }

                    string folder =
                        Path.Combine(
                            baseFolder,
                            "TDL_MEP");

                    if (!Directory.Exists(
                            folder))
                    {
                        Directory.CreateDirectory(
                            folder);
                    }

                    return
                        Path.Combine(
                            folder,
                            "smart_valve_device_library.txt");
                }
                catch
                {
                    return
                        Path.Combine(
                            Path.GetTempPath(),
                            "smart_valve_device_library.txt");
                }
            }
        }


        // ============================================================
        // STEP 18 - AI LEARNING CORE (LOCAL)
        // ------------------------------------------------------------
        // Positive memory:
        //   - Legend đã review
        //   - Người dùng sửa tên / THEO DN
        //   - Ký hiệu CHƯA HỌC được xác nhận
        //
        // Negative memory:
        //   - Ứng viên đỏ bị người dùng BỎ QUA
        //
        // Memory chỉ lưu fingerprint / block key / nhãn / rule.
        // Không lưu DWG, tên dự án hay toàn bộ bản vẽ.
        // ============================================================

        private string AiLearningMemoryPath
        {
            get
            {
                try
                {
                    string baseFolder =
                        Environment.GetFolderPath(
                            Environment.SpecialFolder.ApplicationData);

                    if (string.IsNullOrWhiteSpace(
                            baseFolder))
                    {
                        baseFolder =
                            Path.GetTempPath();
                    }

                    string folder =
                        Path.Combine(
                            baseFolder,
                            "TDL_MEP");

                    if (!Directory.Exists(
                            folder))
                    {
                        Directory.CreateDirectory(
                            folder);
                    }

                    return
                        Path.Combine(
                            folder,
                            "ai_learning_memory_v1.tsv");
                }
                catch
                {
                    return
                        Path.Combine(
                            Path.GetTempPath(),
                            "ai_learning_memory_v1.tsv");
                }
            }
        }

        private List<AiLearningMemoryEntry> LoadAiLearningMemory()
        {
            List<AiLearningMemoryEntry> result =
                new List<AiLearningMemoryEntry>();

            try
            {
                string path =
                    AiLearningMemoryPath;

                if (!File.Exists(
                        path))
                {
                    return result;
                }

                foreach (string line
                    in File.ReadAllLines(
                        path,
                        Encoding.UTF8))
                {
                    if (string.IsNullOrWhiteSpace(
                            line))
                    {
                        continue;
                    }

                    string[] p =
                        line.Split('\t');

                    if (p.Length < 12)
                        continue;

                    AiLearningMemoryEntry entry =
                        new AiLearningMemoryEntry
                        {
                            Signature =
                                DecodeSmartField(
                                    p[0]),
                            MatchMode =
                                DecodeSmartField(
                                    p[1]),
                            BlockKey =
                                DecodeSmartField(
                                    p[2]),
                            GeometryFingerprint =
                                DecodeSmartField(
                                    p[3]),
                            Label =
                                NormalizeSmartDisplayName(
                                    DecodeSmartField(
                                        p[4])),
                            Decision =
                                DecodeSmartField(
                                    p[5]),
                            FollowDn =
                                p[6] == "1",
                            Scope =
                                DecodeSmartField(
                                    p[9]),
                            UpdatedUtc =
                                DecodeSmartField(
                                    p[10]),
                            LastSource =
                                DecodeSmartField(
                                    p[11])
                        };

                    int.TryParse(
                        p[7],
                        out int confirmations);

                    int.TryParse(
                        p[8],
                        out int rejections);

                    entry.Confirmations =
                        confirmations;

                    entry.Rejections =
                        rejections;

                    if (string.IsNullOrWhiteSpace(
                            entry.Signature))
                    {
                        continue;
                    }

                    result.Add(
                        entry);
                }
            }
            catch
            {
            }

            return
                result
                    .GroupBy(
                        e =>
                            e.Signature,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(
                        g =>
                            g.OrderByDescending(
                                x =>
                                    x.UpdatedUtc)
                             .First())
                    .ToList();
        }

        private void SaveAiLearningMemory(
            List<AiLearningMemoryEntry> entries)
        {
            try
            {
                string path =
                    AiLearningMemoryPath;

                List<string> lines =
                    (entries ??
                     new List<AiLearningMemoryEntry>())
                        .Where(
                            e =>
                                e != null &&
                                !string.IsNullOrWhiteSpace(
                                    e.Signature))
                        .OrderBy(
                            e =>
                                e.MatchMode)
                        .ThenBy(
                            e =>
                                e.Label)
                        .Select(
                            e =>
                                string.Join(
                                    "\t",
                                    EncodeSmartField(
                                        e.Signature),
                                    EncodeSmartField(
                                        e.MatchMode),
                                    EncodeSmartField(
                                        e.BlockKey),
                                    EncodeSmartField(
                                        e.GeometryFingerprint),
                                    EncodeSmartField(
                                        e.Label),
                                    EncodeSmartField(
                                        e.Decision),
                                    e.FollowDn
                                        ? "1"
                                        : "0",
                                    e.Confirmations.ToString(
                                        CultureInfo.InvariantCulture),
                                    e.Rejections.ToString(
                                        CultureInfo.InvariantCulture),
                                    EncodeSmartField(
                                        e.Scope),
                                    EncodeSmartField(
                                        e.UpdatedUtc),
                                    EncodeSmartField(
                                        e.LastSource)))
                        .ToList();

                File.WriteAllLines(
                    path,
                    lines,
                    Encoding.UTF8);
            }
            catch (System.Exception ex)
            {
                try
                {
                    MessageBox.Show(
                        "Không lưu được bộ nhớ AI Local:\n" +
                        ex.Message,
                        "AI LEARNING");
                }
                catch
                {
                }
            }
        }

        private static string GetAiLearningSignature(
            string matchMode,
            string blockKey,
            string geometryFingerprint)
        {
            if (string.Equals(
                    matchMode,
                    "GEOMETRY",
                    StringComparison.OrdinalIgnoreCase))
            {
                return
                    string.IsNullOrWhiteSpace(
                        geometryFingerprint)
                        ? ""
                        : "GEO|" +
                          geometryFingerprint;
            }

            string key =
                NormalizeSmartSymbolKey(
                    blockKey);

            if (string.IsNullOrWhiteSpace(
                    key))
            {
                return "";
            }

            if (string.Equals(
                    matchMode,
                    "POINT",
                    StringComparison.OrdinalIgnoreCase))
            {
                return
                    "POINT|" +
                    key;
            }

            return
                "BLOCK|" +
                key;
        }

        private void UpsertAiLearningMemory(
            string matchMode,
            string blockKey,
            string geometryFingerprint,
            string label,
            bool followDn,
            string decision,
            string source,
            bool reinforce)
        {
            string signature =
                GetAiLearningSignature(
                    matchMode,
                    blockKey,
                    geometryFingerprint);

            if (string.IsNullOrWhiteSpace(
                    signature))
            {
                return;
            }

            List<AiLearningMemoryEntry> memory =
                LoadAiLearningMemory();

            AiLearningMemoryEntry existing =
                memory.FirstOrDefault(
                    e =>
                        string.Equals(
                            e.Signature,
                            signature,
                            StringComparison.OrdinalIgnoreCase));

            string normalizedDecision =
                string.Equals(
                    decision,
                    "NEGATIVE",
                    StringComparison.OrdinalIgnoreCase)
                    ? "NEGATIVE"
                    : "POSITIVE";

            string normalizedLabel =
                NormalizeSmartDisplayName(
                    label);

            if (existing == null)
            {
                existing =
                    new AiLearningMemoryEntry
                    {
                        Signature =
                            signature,
                        MatchMode =
                            string.Equals(
                                matchMode,
                                "GEOMETRY",
                                StringComparison.OrdinalIgnoreCase)
                                ? "GEOMETRY"
                                : "BLOCK",
                        BlockKey =
                            blockKey ?? "",
                        GeometryFingerprint =
                            geometryFingerprint ?? "",
                        Label =
                            normalizedDecision == "POSITIVE"
                                ? normalizedLabel
                                : "",
                        Decision =
                            normalizedDecision,
                        FollowDn =
                            followDn,
                        Confirmations =
                            normalizedDecision == "POSITIVE"
                                ? 1
                                : 0,
                        Rejections =
                            normalizedDecision == "NEGATIVE"
                                ? 1
                                : 0,
                        Scope =
                            "GLOBAL",
                        UpdatedUtc =
                            DateTime.UtcNow.ToString(
                                "O",
                                CultureInfo.InvariantCulture),
                        LastSource =
                            source ?? ""
                    };

                memory.Add(
                    existing);
            }
            else
            {
                bool changed =
                    !string.Equals(
                        existing.Decision,
                        normalizedDecision,
                        StringComparison.OrdinalIgnoreCase) ||
                    (normalizedDecision == "POSITIVE" &&
                     (!string.Equals(
                          existing.Label,
                          normalizedLabel,
                          StringComparison.OrdinalIgnoreCase) ||
                      existing.FollowDn !=
                          followDn));

                existing.MatchMode =
                    string.Equals(
                        matchMode,
                        "GEOMETRY",
                        StringComparison.OrdinalIgnoreCase)
                        ? "GEOMETRY"
                        : "BLOCK";

                existing.BlockKey =
                    blockKey ?? "";

                existing.GeometryFingerprint =
                    geometryFingerprint ?? "";

                existing.Decision =
                    normalizedDecision;

                existing.Label =
                    normalizedDecision == "POSITIVE"
                        ? normalizedLabel
                        : "";

                existing.FollowDn =
                    followDn;

                if (reinforce ||
                    changed)
                {
                    if (normalizedDecision ==
                        "POSITIVE")
                    {
                        existing.Confirmations++;
                    }
                    else
                    {
                        existing.Rejections++;
                    }
                }

                existing.UpdatedUtc =
                    DateTime.UtcNow.ToString(
                        "O",
                        CultureInfo.InvariantCulture);

                existing.LastSource =
                    source ?? "";
            }

            SaveAiLearningMemory(
                memory);

            // STEP21C:
            // Correction local được queue để sync. Dữ liệu vừa kéo từ Cloud
            // không được gửi ngược lên như một "phiếu" mới của máy này.
            if (!string.Equals(
                    source,
                    "CLOUD_SYNC",
                    StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(
                    source,
                    "CLOUD_APPROVED",
                    StringComparison.OrdinalIgnoreCase))
            {
                EnqueueAiCloudVote(
                    existing);
            }

            UpdateAiLearningStatusUi();
            UpdateAiCloudStatusUi();
        }

        private void LearnAiFromLegendRows(
            List<SmartLegendAutoRow> rows)
        {
            if (rows == null)
                return;

            foreach (SmartLegendAutoRow row
                in rows)
            {
                if (row == null ||
                    string.IsNullOrWhiteSpace(
                        row.DisplayName))
                {
                    continue;
                }

                UpsertAiLearningMemory(
                    row.MatchMode,
                    row.BlockKey,
                    row.GeometryFingerprint,
                    row.DisplayName,
                    row.FollowDn,
                    "POSITIVE",
                    "LEGEND_REVIEW",
                    false);
            }
        }

        private void LearnAiFromSymbolRules(
            List<SmartSymbolRule> rules,
            string source)
        {
            if (rules == null)
                return;

            foreach (SmartSymbolRule rule
                in rules)
            {
                if (rule == null ||
                    string.IsNullOrWhiteSpace(
                        rule.DisplayName))
                {
                    continue;
                }

                UpsertAiLearningMemory(
                    rule.MatchMode,
                    rule.BlockKey,
                    rule.GeometryFingerprint,
                    rule.DisplayName,
                    string.Equals(
                        rule.SizeRule,
                        "THEO_ONG",
                        StringComparison.OrdinalIgnoreCase),
                    "POSITIVE",
                    source,
                    false);
            }
        }

        private void LearnAiNegativeFromAuditRow(
            SmartAuditRow row)
        {
            if (row == null ||
                row.NegativeLearned)
            {
                return;
            }

            bool isUnrecognizedCandidate =
                string.Equals(
                    row.Status,
                    "MISSING",
                    StringComparison.OrdinalIgnoreCase) ||
                (row.Source ?? "")
                    .IndexOf(
                        "CHƯA HỌC",
                        StringComparison.OrdinalIgnoreCase) >=
                    0;

            // BỎ QUA một dòng đã nhận diện OK chỉ loại instance khỏi thống kê hiện tại.
            // Không biến cả signature thành NEGATIVE để tránh học quá tay.
            if (!isUnrecognizedCandidate)
                return;

            UpsertAiLearningMemory(
                row.MatchMode,
                row.BlockKey,
                row.GeometryFingerprint,
                "",
                false,
                "NEGATIVE",
                "AUDIT_IGNORE",
                true);

            CaptureAiDatasetFromAuditRow(
                row,
                "NEGATIVE",
                "AUDIT_IGNORE",
                "");

            row.NegativeLearned =
                true;
        }

        private void LearnAiFromAuditCorrections(
            List<SmartAuditRow> rows)
        {
            if (rows == null)
                return;

            foreach (SmartAuditRow row
                in rows)
            {
                if (row == null ||
                    string.Equals(
                        row.Status,
                        "MISSING",
                        StringComparison.OrdinalIgnoreCase) ||
                    string.IsNullOrWhiteSpace(
                        row.Name) ||
                    string.Equals(
                        row.Name,
                        "CHƯA NHẬN DIỆN",
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                bool wasNewlyConfirmed =
                    (row.Source ?? "")
                        .IndexOf(
                            "BỔ SUNG",
                            StringComparison.OrdinalIgnoreCase) >=
                    0;

                if (!row.UserEdited &&
                    !wasNewlyConfirmed)
                {
                    continue;
                }

                string previousLabelForHardNegative =
                    row.UserEdited &&
                    !string.IsNullOrWhiteSpace(
                        row.OriginalName) &&
                    !string.Equals(
                        row.OriginalName,
                        row.Name,
                        StringComparison.OrdinalIgnoreCase)
                        ? row.OriginalName
                        : "";

                string auditDatasetSource =
                    row.UserEdited
                        ? "AUDIT_USER_EDIT"
                        : "AUDIT_CONFIRM_NEW";

                UpsertAiLearningMemory(
                    row.MatchMode,
                    row.BlockKey,
                    row.GeometryFingerprint,
                    row.Name,
                    row.FollowDn,
                    "POSITIVE",
                    auditDatasetSource,
                    true);

                CaptureAiDatasetFromAuditRow(
                    row,
                    "POSITIVE",
                    auditDatasetSource,
                    previousLabelForHardNegative);

                row.UserEdited =
                    false;

                row.OriginalName =
                    row.Name;

                row.OriginalFollowDn =
                    row.FollowDn;

                row.ReviewBaselineInitialized =
                    true;
            }
        }

        private List<SmartSymbolRule> EnrichSmartRulesWithAiLearning(
            List<SmartSymbolRule> currentRules)
        {
            List<SmartSymbolRule> result =
                CloneSmartRulesForSession(
                    currentRules ??
                    new List<SmartSymbolRule>());

            List<AiLearningMemoryEntry> memory =
                LoadAiLearningMemory();

            foreach (AiLearningMemoryEntry entry
                in memory)
            {
                if (entry == null ||
                    !string.Equals(
                        entry.Decision,
                        "POSITIVE",
                        StringComparison.OrdinalIgnoreCase) ||
                    string.IsNullOrWhiteSpace(
                        entry.Label))
                {
                    continue;
                }

                bool exists;

                if (string.Equals(
                        entry.MatchMode,
                        "GEOMETRY",
                        StringComparison.OrdinalIgnoreCase))
                {
                    exists =
                        result.Any(
                            r =>
                                r != null &&
                                string.Equals(
                                    r.MatchMode,
                                    "GEOMETRY",
                                    StringComparison.OrdinalIgnoreCase) &&
                                string.Equals(
                                    r.GeometryFingerprint,
                                    entry.GeometryFingerprint,
                                    StringComparison.Ordinal));
                }
                else
                {
                    exists =
                        result.Any(
                            r =>
                                r != null &&
                                !string.Equals(
                                    r.MatchMode,
                                    "GEOMETRY",
                                    StringComparison.OrdinalIgnoreCase) &&
                                string.Equals(
                                    r.BlockKey,
                                    entry.BlockKey,
                                    StringComparison.OrdinalIgnoreCase));
                }

                // Legend hiện tại luôn ưu tiên hơn memory cũ.
                if (exists)
                    continue;

                result.Add(
                    new SmartSymbolRule
                    {
                        BlockKey =
                            entry.BlockKey,
                        DisplayName =
                            entry.Label,
                        SizeRule =
                            entry.FollowDn
                                ? "THEO_ONG"
                                : "KHONG_SIZE",
                        MatchMode =
                            entry.MatchMode,
                        GeometryFingerprint =
                            entry.GeometryFingerprint
                    });
            }

            return result;
        }

        private bool IsAiLearningNegativeBlock(
            string blockKey)
        {
            string signature =
                GetAiLearningSignature(
                    "BLOCK",
                    blockKey,
                    "");

            if (string.IsNullOrWhiteSpace(
                    signature))
            {
                return false;
            }

            return
                LoadAiLearningMemory()
                    .Any(
                        e =>
                            e != null &&
                            string.Equals(
                                e.Decision,
                                "NEGATIVE",
                                StringComparison.OrdinalIgnoreCase) &&
                            string.Equals(
                                e.Signature,
                                signature,
                                StringComparison.OrdinalIgnoreCase));
        }

        private bool IsAiLearningNegativeGeometry(
            string fingerprint)
        {
            if (string.IsNullOrWhiteSpace(
                    fingerprint))
            {
                return false;
            }

            List<AiLearningMemoryEntry> negatives =
                LoadAiLearningMemory()
                    .Where(
                        e =>
                            e != null &&
                            string.Equals(
                                e.Decision,
                                "NEGATIVE",
                                StringComparison.OrdinalIgnoreCase) &&
                            string.Equals(
                                e.MatchMode,
                                "GEOMETRY",
                                StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(
                                e.GeometryFingerprint))
                    .ToList();

            foreach (AiLearningMemoryEntry entry
                in negatives)
            {
                if (string.Equals(
                        entry.GeometryFingerprint,
                        fingerprint,
                        StringComparison.Ordinal))
                {
                    return true;
                }

                double score =
                    CompareSmartGeometryFingerprints(
                        entry.GeometryFingerprint,
                        fingerprint);

                // Negative memory dùng ngưỡng chặt hơn positive match
                // để tránh loại nhầm ký hiệu gần giống.
                if (score <= 0.045)
                {
                    return true;
                }
            }

            return false;
        }

