                int negative =
                    memory.Count(
                        e =>
                            string.Equals(
                                e.Decision,
                                "NEGATIVE",
                                StringComparison.OrdinalIgnoreCase));

                TxtAiLearningStatus.Text =
                    "AI Learning: LOCAL  •  " +
                    positive +
                    " mẫu đã học  •  " +
                    negative +
                    " mẫu loại trừ";
            }
            catch
            {
            }
        }

