        private void BtnAiGnnLoad_Click(
            object sender,
            RoutedEventArgs e)
        {
            Microsoft.Win32.OpenFileDialog dialog =
                new Microsoft.Win32.OpenFileDialog();

            dialog.Title =
                "Chọn mep_graph_context.onnx";

            dialog.Filter =
                "ONNX model (*.onnx)|*.onnx|All files (*.*)|*.*";

            dialog.Multiselect =
                false;

            if (dialog.ShowDialog() !=
                true)
            {
                return;
            }

            string modelPath =
                dialog.FileName;

            string folder =
                Path.GetDirectoryName(
                    modelPath) ??
                "";

            string labelsPath =
                Path.Combine(
                    folder,
                    "mep_graph_dn_labels.txt");

            if (!File.Exists(
                    labelsPath))
            {
                Microsoft.Win32.OpenFileDialog labelsDialog =
                    new Microsoft.Win32.OpenFileDialog();

                labelsDialog.Title =
                    "Chọn mep_graph_dn_labels.txt";

                labelsDialog.Filter =
                    "Text labels (*.txt)|*.txt|All files (*.*)|*.*";

                labelsDialog.Multiselect =
                    false;

                if (labelsDialog.ShowDialog() !=
                    true)
                {
                    return;
                }

                labelsPath =
                    labelsDialog.FileName;
            }

            LoadMepGraphGnnModel(
                modelPath,
                labelsPath,
                true);
        }

        private void BtnAiGnnExport_Click(
            object sender,
            RoutedEventArgs e)
        {
            MepGraphTrainingPackResult result =
                GetMepGraphTrainingPackExporter()
                    .Export();

            if (!result.Success)
            {
                MessageBox.Show(
                    "Chưa xuất được GNN Dataset:\n\n" +
                    result.Message,
                    "GNN DATASET");

                return;
            }

            _lastMepGnnTrainingFolder =
                result.ExportFolder ?? "";

            List<string> low =
                result.DnCounts
                    .Where(
                        kv =>
                            kv.Value < 10)
                    .OrderBy(
                        kv =>
                            kv.Key)
                    .Select(
                        kv =>
                            kv.Key +
                            "=" +
                            kv.Value)
                    .ToList();

            string warning =
                "";

            if (result.DnClassCount < 2)
            {
                warning =
                    "\n\n⚠ Chưa đủ 2 DN class để train GNN.";
            }
            else if (low.Count > 0)
            {
                warning =
                    "\n\n⚠ DN dưới 10 target đáng tin:\n" +
                    string.Join(
                        ", ",
                        low);
            }

            MessageBox.Show(
                "ĐÃ XUẤT GNN TRAINING PACK\n\n" +
                "Graphs: " +
                result.GraphCount +
                "\n" +
                "Pipes: " +
                result.PipeCount +
                "\n" +
                "Ground-truth DN: " +
                result.ExplicitLabelCount +
                "\n" +
                "DN classes: " +
                result.DnClassCount +
                "\n\nFolder:\n" +
                result.ExportFolder +
                (string.IsNullOrWhiteSpace(
                     result.ZipPath)
                    ? ""
                    : "\n\nZIP:\n" +
                      result.ZipPath) +
                warning +
                "\n\nBộ train đã gộp LOCAL HISTORY + CLOUD APPROVED.\n" +
                "Copy 3 file STEP22B vào folder rồi chạy RUN_TRAIN_GNN_PY312.bat.",
                "GNN DATASET");
        }

