        private void CaptureReviewedLegendRowsIntoDataset(
            List<SmartLegendAutoRow> rows,
            bool showSummary)
        {
            if (rows == null ||
                rows.Count == 0)
            {
                return;
            }

            try
            {
                AiDatasetManager manager =
                    GetAiDatasetManager();

                AiDatasetLocalSummary before =
                    manager.GetLocalSummary();

                int attempted =
                    0;

                foreach (SmartLegendAutoRow row
                    in rows)
                {
                    if (row == null ||
                        row.Preview == null ||
                        string.IsNullOrWhiteSpace(
                            row.DisplayName))
                    {
                        continue;
                    }

                    string signature =
                        GetAiLearningSignature(
                            row.MatchMode,
                            row.BlockKey,
                            row.GeometryFingerprint);

                    if (string.IsNullOrWhiteSpace(
                            signature))
                    {
                        continue;
                    }

                    AiDatasetSample sample =
                        manager.CaptureSample(
                            row.Preview,
                            signature,
                            row.MatchMode,
                            row.BlockKey,
                            row.GeometryFingerprint,
                            row.DisplayName,
                            row.FollowDn,
                            "POSITIVE",
                            "LEGEND_REVIEW_ACCEPTED",
                            "");

                    if (sample != null)
                    {
                        attempted++;
                    }
                }

                AiDatasetLocalSummary after =
                    manager.GetLocalSummary();

                int newSamples =
                    Math.Max(
                        0,
                        after.Total -
                        before.Total);

                int duplicates =
                    Math.Max(
                        0,
                        attempted -
                        newSamples);

                UpdateAiDatasetStatusUi();

                if (showSummary &&
                    attempted > 0)
                {
                    MessageBox.Show(
                        "ĐÃ HỌC TOÀN BỘ BẢNG LEGEND\\n\\n" +
                        "Ký hiệu hợp lệ: " +
                        attempted +
                        "\\n" +
                        "Mẫu Dataset mới: " +
                        newSamples +
                        "\\n" +
                        "Trùng hash / đã có: " +
                        duplicates +
                        "\\n" +
                        "Chờ Cloud: " +
                        after.Pending +
                        "\\n\\n" +
                        "Các mẫu hợp lệ đã được lưu Local AI Memory + AI Dataset.\\n" +
                        "Tiếp theo tool sẽ quét bản vẽ để thống kê.",
                        "AI DATASET - LEGEND");
                }
            }
            catch (System.Exception ex)
            {
                try
                {
                    MessageBox.Show(
                        "Đã lưu Legend vào thư viện nhưng chưa tạo đủ Dataset:\\n" +
                        ex.Message +
                        "\\n\\nBạn vẫn có thể tiếp tục quét bản vẽ.",
                        "AI DATASET - LEGEND");
                }
                catch
                {
                }
            }
        }


        private void CaptureAiDatasetFromLegendRow(
            SmartLegendAutoRow row,
            string decision,
            string source,
            string hardNegativeLabel)
        {
            if (row == null ||
                row.Preview == null)
            {
                return;
            }

            try
            {
                string signature =
                    GetAiLearningSignature(
                        row.MatchMode,
                        row.BlockKey,
                        row.GeometryFingerprint);

                GetAiDatasetManager()
                    .CaptureSample(
                        row.Preview,
                        signature,
                        row.MatchMode,
                        row.BlockKey,
                        row.GeometryFingerprint,
                        row.DisplayName,
                        row.FollowDn,
                        decision,
                        source,
                        hardNegativeLabel);

                UpdateAiDatasetStatusUi();
            }
            catch
            {
                // Dataset không được làm gián đoạn workflow chính.
            }
        }

