        private void ApplyAiCloudConsensus(
            List<AiCloudConsensusRow> rows,
            out int approvedCount,
            out int pendingCount,
            out int conflictCount)
        {
            approvedCount = 0;
            pendingCount = 0;
            conflictCount = 0;

            if (rows == null ||
                rows.Count == 0)
            {
                return;
            }

            List<AiLearningMemoryEntry> memory =
                LoadAiLearningMemory();

            foreach (IGrouping<string, AiCloudConsensusRow> signatureGroup
                in rows
                    .Where(
                        r =>
                            r != null &&
                            !string.IsNullOrWhiteSpace(
                                r.Signature) &&
                            (string.IsNullOrWhiteSpace(
                                 r.Scope) ||
                             string.Equals(
                                 r.Scope,
                                 "GLOBAL",
                                 StringComparison.OrdinalIgnoreCase)))
                    .GroupBy(
                        r =>
                            r.Signature,
                        StringComparer.OrdinalIgnoreCase))
            {
                List<AiCloudConsensusRow> positiveRows =
                    signatureGroup
                        .Where(
                            r =>
                                r.PositiveVotes > 0 &&
                                !string.IsNullOrWhiteSpace(
                                    r.Label))
                        .OrderByDescending(
                            r =>
                                r.PositiveVotes)
                        .ToList();

                int negativeVotes =
                    signatureGroup.Sum(
                        r =>
                            Math.Max(
                                0,
                                r.NegativeVotes));

                AiCloudConsensusRow best =
                    positiveRows.FirstOrDefault();

                int bestVotes =
                    best != null
                        ? best.PositiveVotes
                        : 0;

                int secondVotes =
                    positiveRows.Count > 1
                        ? positiveRows[1].PositiveVotes
                        : 0;

                bool positiveApproved =
                    best != null &&
                    bestVotes >=
                        AiCloudMinConsensusVotes &&
                    (
                        secondVotes == 0 ||
                        bestVotes - secondVotes >= 2 ||
                        bestVotes >= secondVotes * 2
                    ) &&
                    bestVotes >
                        negativeVotes;

                bool negativeApproved =
                    negativeVotes >=
                        AiCloudMinConsensusVotes &&
                    negativeVotes >=
                        bestVotes + 2;

                if (positiveApproved)
                {
                    UpsertCloudApprovedMemory(
                        memory,
                        best.Signature,
                        best.MatchMode,
                        best.BlockKey,
                        best.GeometryFingerprint,
                        best.Label,
                        best.FollowDn,
                        "POSITIVE",
                        bestVotes,
                        negativeVotes,
                        best.LastEventAt);

                    approvedCount++;
                    continue;
                }

                if (negativeApproved)
                {
                    AiCloudConsensusRow template =
                        best ??
                        signatureGroup.First();

                    UpsertCloudApprovedMemory(
                        memory,
                        template.Signature,
                        template.MatchMode,
                        template.BlockKey,
                        template.GeometryFingerprint,
                        "",
                        false,
                        "NEGATIVE",
                        bestVotes,
                        negativeVotes,
                        template.LastEventAt);

                    approvedCount++;
                    continue;
                }

                bool hasRealConflict =
                    best != null &&
                    secondVotes > 0 &&
                    Math.Abs(
                        bestVotes -
                        secondVotes) <=
                        1;

                if (hasRealConflict)
                {
                    conflictCount++;
                }
                else
                {
                    pendingCount++;
                }
            }

            SaveAiLearningMemory(
                memory);
        }

        private void UpsertCloudApprovedMemory(
            List<AiLearningMemoryEntry> memory,
            string signature,
            string matchMode,
            string blockKey,
            string geometryFingerprint,
            string label,
            bool followDn,
            string decision,
            int positiveVotes,
            int negativeVotes,
            string cloudUpdatedAt)
        {
            if (memory == null ||
                string.IsNullOrWhiteSpace(
                    signature))
            {
                return;
            }

            AiLearningMemoryEntry entry =
                memory.FirstOrDefault(
                    x =>
                        x != null &&
                        string.Equals(
                            x.Signature,
                            signature,
                            StringComparison.OrdinalIgnoreCase));

            if (entry == null)
            {
                entry =
                    new AiLearningMemoryEntry
                    {
                        Signature =
                            signature
                    };

                memory.Add(
                    entry);
            }

            entry.MatchMode =
                string.IsNullOrWhiteSpace(
                    matchMode)
                    ? "BLOCK"
                    : matchMode;

            entry.BlockKey =
                blockKey ?? "";

            entry.GeometryFingerprint =
                geometryFingerprint ?? "";

            entry.Decision =
                string.Equals(
                    decision,
                    "NEGATIVE",
                    StringComparison.OrdinalIgnoreCase)
                    ? "NEGATIVE"
                    : "POSITIVE";

            entry.Label =
                entry.Decision ==
                    "POSITIVE"
                    ? NormalizeSmartDisplayName(
                        label)
                    : "";

            entry.FollowDn =
                entry.Decision ==
                    "POSITIVE" &&
                followDn;

            entry.Confirmations =
                Math.Max(
                    entry.Confirmations,
                    positiveVotes);

            entry.Rejections =
                Math.Max(
                    entry.Rejections,
                    negativeVotes);

            entry.Scope =
                "GLOBAL";

            entry.UpdatedUtc =
                string.IsNullOrWhiteSpace(
                    cloudUpdatedAt)
                    ? DateTime.UtcNow.ToString(
                        "O",
                        CultureInfo.InvariantCulture)
                    : cloudUpdatedAt;

            entry.LastSource =
                "CLOUD_SYNC";
        }

