        private void HandleSmartValveFatalSafe(
            string stage,
            System.Exception ex)
        {
            string message =
                ex == null
                    ? "Lỗi không xác định."
                    : ex.ToString();

            string logPath =
                "";

            try
            {
                string folder =
                    Path.Combine(
                        Environment.GetFolderPath(
                            Environment.SpecialFolder.ApplicationData),
                        "TDL_MEP");

                if (!Directory.Exists(
                        folder))
                {
                    Directory.CreateDirectory(
                        folder);
                }

                logPath =
                    Path.Combine(
                        folder,
                        "smart_valve_error.log");

                string log =
                    "========================================\r\n" +
                    DateTime.Now.ToString(
                        "yyyy-MM-dd HH:mm:ss",
                        CultureInfo.InvariantCulture) +
                    "\r\nSTAGE: " +
                    (stage ?? "") +
                    "\r\n" +
                    message +
                    "\r\n";

                File.AppendAllText(
                    logPath,
                    log,
                    Encoding.UTF8);
            }
            catch
            {
            }

            try
            {
                Document doc =
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .DocumentManager
                        .MdiActiveDocument;

                if (doc != null)
                {
                    doc.Editor.WriteMessage(
                        "\n[THỐNG KÊ VAN/TB] Chức năng đã chặn lỗi để AutoCAD không bị crash.");

                    doc.Editor.WriteMessage(
                        "\nChi tiết: " +
                        (ex?.GetType().FullName ??
                         "Unknown") +
                        " - " +
                        (ex?.Message ??
                         ""));
                }
            }
            catch
            {
            }

            string userText =
                "Chức năng NHẬN DIỆN VAN/TB vừa gặp lỗi, " +
                "nhưng đã được chặn để không làm AutoCAD thoát.\n\n" +
                "Giai đoạn: " +
                (stage ?? "") +
                "\nLoại lỗi: " +
                (ex?.GetType().Name ??
                 "Unknown") +
                "\nNội dung: " +
                (ex?.Message ??
                 "Không có thông tin.");

            if (!string.IsNullOrWhiteSpace(
                    logPath))
            {
                userText +=
                    "\n\nĐã ghi log tại:\n" +
                    logPath;
            }

            try
            {
                MessageBox.Show(
                    userText,
                    "NHẬN DIỆN VAN / THIẾT BỊ");
            }
            catch
            {
            }
        }


        private void ThongKeThietBiVanThongMinh(
            Document doc)
        {
            try
            {
                ThongKeThietBiVanThongMinh_Core(
                    doc);
            }
            catch (System.Exception ex)
            {
                HandleSmartValveFatalSafe(
                    "ThongKeThietBiVanThongMinh / " +
                    (_smartValveStage ?? "UNKNOWN"),
                    ex);
            }
        }

        private void ThongKeThietBiVanThongMinh_Core(
            Document doc)
        {
            if (doc == null)
                return;

            Editor ed =
                doc.Editor;

            if (_lastSmartAuditRows != null &&
                _lastSmartAuditRows.Count > 0)
            {
                _smartValveStage =
                    "SESSION_MENU";

                int sessionAction =
                    GetSmartMenuChoice(
                        ed,
                        "\n[NHẬN DIỆN VAN/TB] Phiên gần nhất vẫn còn. " +
                        "1=QUÉT MỚI, " +
                        "2=MỞ LẠI BẢNG KIỂM TRA, " +
                        "3=SỬA LẠI BẢNG KÝ HIỆU",
                        1,
                        3,
                        2);

                if (sessionAction <= 0)
                {
                    _smartValveStage =
                        "IDLE";
                    return;
                }

                if (sessionAction == 2)
                {
                    ReopenLastSmartAuditSession(
                        doc);

                    _smartValveStage =
                        "IDLE";
                    return;
                }

                if (sessionAction == 3)
                {
                    ReopenLastSmartLegendSession(
                        doc);

                    _smartValveStage =
                        "IDLE";
                    return;
                }

                // 1 = QUÉT MỚI:
                // xóa preview legend của phiên cũ để giải phóng RAM,
                // nhưng bảng CAD cũ vẫn giữ cho đến khi xuất bảng mới.
                DisposeSmartLegendPreviews(
                    _lastSmartLegendRows);

                _lastSmartLegendRows =
                    new List<SmartLegendAutoRow>();

                _lastSmartAuditRows =
                    new List<SmartAuditRow>();

                _lastSmartLegendZero =
                    new List<string>();

                _lastSmartRules =
                    new List<SmartSymbolRule>();
            }

            _smartValveStage =
                "AUTO_LEGEND_SELECT";

            PromptSelectionOptions legendOptions =
                new PromptSelectionOptions();

            legendOptions.MessageForAdding =
                "\n[NHẬN DIỆN VAN/TB] Quét TOÀN BỘ bảng KÝ HIỆU + TÊN THIẾT BỊ/VẬT TƯ: ";

            PromptSelectionResult legendResult =
                ed.GetSelection(
                    legendOptions);

            if (legendResult.Status !=
                    PromptStatus.OK ||
                legendResult.Value == null ||
                legendResult.Value.Count == 0)
            {
                _smartValveStage =
                    "IDLE";
                return;
            }

            _smartValveStage =
                "AUTO_LEGEND_ANALYZE";

            List<SmartLegendAutoRow> rows =
                BuildSmartLegendRowsAutomatically(
                    doc,
                    legendResult.Value
                        .GetObjectIds());

            if (rows.Count == 0)
            {
                MessageBox.Show(
                    "Không tự tách được dòng KÝ HIỆU / TÊN THIẾT BỊ từ vùng vừa quét.\n\n" +
                    "Hãy quét trọn bảng gồm cả cột KÝ HIỆU và cột TÊN THIẾT BỊ/VẬT TƯ.",
                    "NHẬN DIỆN VAN / THIẾT BỊ");

                _smartValveStage =
                    "IDLE";
                return;
            }

            _smartValveStage =
                "AUTO_LEGEND_REVIEW";

            bool accepted =
                ShowSmartLegendReviewDialog(
                    doc,
                    rows);

            if (!accepted)
            {
                DisposeSmartLegendPreviews(
                    rows);

                _smartValveStage =
                    "IDLE";
                return;
            }

            rows =
                rows
                    .Where(
                        r =>
                            r != null &&
                            !string.IsNullOrWhiteSpace(
                                r.DisplayName) &&
                            (!string.IsNullOrWhiteSpace(
                                 r.BlockKey) ||
                             !string.IsNullOrWhiteSpace(
                                 r.GeometryFingerprint)))
                    .ToList();

            if (rows.Count == 0)
            {
                DisposeSmartLegendPreviews(
                    rows);

                MessageBox.Show(
                    "Không còn dòng hợp lệ để nhận diện.",
                    "NHẬN DIỆN VAN / THIẾT BỊ");

                _smartValveStage =
                    "IDLE";
                return;
            }

            _smartValveStage =
                "AUTO_LEGEND_SAVE";

            List<SmartSymbolRule> rules =
                MergeSmartLegendRowsIntoLibrary(
                    rows);

            DisposeSmartLegendPreviews(
                _lastSmartLegendRows);

            _lastSmartLegendRows =
                CloneSmartLegendRowsForSession(
                    rows);

            _lastSmartRules =
                CloneSmartRulesForSession(
                    rules);

            DisposeSmartLegendPreviews(
                rows);

            if (rules.Count == 0)
            {
                _smartValveStage =
                    "IDLE";
                return;
            }

            _smartValveStage =
                "AUTO_SCAN_DRAWING";

            // Sau khi người dùng bấm OK ở bảng kiểm tra:
            // chuyển thẳng sang quét mặt bằng để thống kê, không hỏi menu vòng nữa.
            ScanSmartValveDeviceStatistics(
                doc,
                rules);

            _smartValveStage =
                "IDLE";
        }


        private List<SmartLegendAutoRow> BuildSmartLegendRowsAutomatically(
            Document doc,
            ObjectId[] selectedIds)
        {
            List<SmartLegendAutoRow> rows =
                new List<SmartLegendAutoRow>();

            if (doc == null ||
                selectedIds == null ||
                selectedIds.Length == 0)
            {
                return rows;
            }

            Database db =
                doc.Database;

            List<SmartLegendTextCandidate> texts =
                new List<SmartLegendTextCandidate>();

            List<ObjectId> symbolObjectIds =
                new List<ObjectId>();

            Extents3d overallExtents =
                default(Extents3d);

            bool hasOverallExtents =
                false;

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (ObjectId id
                    in selectedIds)
                {
                    if (id.IsNull ||
                        !id.IsValid)
                    {
                        continue;
                    }

                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased)
                    {
                        continue;
                    }

                    try
                    {
                        Extents3d ex =
                            ent.GeometricExtents;

                        if (!hasOverallExtents)
                        {
                            overallExtents =
                                ex;

                            hasOverallExtents =
                                true;
                        }
                        else
                        {
                            overallExtents.AddExtents(
                                ex);
                        }
                    }
                    catch
                    {
                    }

                    if (ent is DBText ||
                        ent is MText)
                    {
                        string raw =
                            GetSmartLegendText(
                                ent);

                        string normalized =
                            NormalizeSmartDisplayName(
                                raw);

                        if (string.IsNullOrWhiteSpace(
                                normalized))
                        {
                            continue;
                        }

                        string key =
                            BoDauTiengViet(
                                normalized)
                                .ToUpperInvariant();

                        // Bỏ header của bảng.
                        if (key.Contains(
                                "KY HIEU") ||
                            key.Contains(
                                "TEN THIET BI") ||
                            key.Contains(
                                "TEN VAT TU"))
                        {
                            continue;
                        }

                        try
                        {
                            Extents3d ex =
                                ent.GeometricExtents;

                            Point3d center =
                                new Point3d(
                                    (ex.MinPoint.X +
                                     ex.MaxPoint.X) * 0.5,
                                    (ex.MinPoint.Y +
                                     ex.MaxPoint.Y) * 0.5,
                                    0.0);

                            texts.Add(
                                new SmartLegendTextCandidate
                                {
                                    Id =
                                        id,
                                    Text =
                                        normalized,
                                    Center =
                                        center,
                                    Extents =
                                        ex
                                });
                        }
                        catch
                        {
                        }

                        continue;
                    }

                    // STEP18H:
                    // Không whitelist Block/Line/Arc/Circle... nữa.
                    // Ký hiệu thực tế có thể là POINT, SOLID, HATCH, ELLIPSE,
                    // SPLINE, WIPEOUT hoặc custom entity. Cứ giữ Entity,
                    // sau đó row-level geometry + table-grid filter sẽ quyết định.
                    symbolObjectIds.Add(
                        id);
                }

                tr.Commit();
            }

            if (texts.Count == 0 ||
                symbolObjectIds.Count == 0 ||
                !hasOverallExtents)
            {
                return rows;
            }

            double tableWidth =
                Math.Max(
                    overallExtents.MaxPoint.X -
                    overallExtents.MinPoint.X,
                    1.0);

            double tableHeight =
                Math.Max(
                    overallExtents.MaxPoint.Y -
                    overallExtents.MinPoint.Y,
                    1.0);

            // Mô tả thường nằm ở cột phải.
            // Dùng median X của text để tự tìm nhóm text bên phải,
            // tránh phụ thuộc đúng vị trí cột của từng bản vẽ.
            List<double> textX =
                texts
                    .Select(
                        t =>
                            t.Center.X)
                    .OrderBy(
                        x =>
                            x)
                    .ToList();

            double medianX =
                textX[
                    textX.Count / 2];

            List<SmartLegendTextCandidate> descriptions =
                texts
                    .Where(
                        t =>
                            t.Center.X >=
                            medianX -
                            tableWidth * 0.08)
                    .OrderByDescending(
                        t =>
                            t.Center.Y)
                    .ToList();

            if (descriptions.Count == 0)
            {
                descriptions =
                    texts
                        .OrderByDescending(
                            t =>
                                t.Center.Y)
                        .ToList();
            }

            // Gộp text nhiều dòng cùng một hàng:
            // nếu Y rất gần và X cùng vùng mô tả thì nối thành một tên.
            descriptions =
                MergeSmartLegendTextLines(
                    descriptions,
                    tableHeight);

            if (descriptions.Count == 0)
                return rows;

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                for (int i = 0;
                    i < descriptions.Count;
                    i++)
                {
                    SmartLegendTextCandidate desc =
                        descriptions[i];

                    double upper =
                        i == 0
                            ? overallExtents.MaxPoint.Y
                            : (descriptions[i - 1].Center.Y +
                               desc.Center.Y) * 0.5;

                    double lower =
                        i ==
                            descriptions.Count - 1
                            ? overallExtents.MinPoint.Y
                            : (desc.Center.Y +
                               descriptions[i + 1].Center.Y) * 0.5;

                    double splitX =
                        desc.Extents.MinPoint.X -
                        tableWidth * 0.025;

                    List<ObjectId> rowSymbols =
                        new List<ObjectId>();

                    foreach (ObjectId id
                        in symbolObjectIds)
                    {
                        Entity ent =
                            tr.GetObject(
                                id,
                                OpenMode.ForRead,
                                false) as Entity;

                        if (ent == null ||
                            ent.IsErased)
                        {
                            continue;
                        }

                        Extents3d ex;

                        try
                        {
                            ex =
                                ent.GeometricExtents;
                        }
                        catch
                        {
                            continue;
                        }

                        Point3d c =
                            new Point3d(
                                (ex.MinPoint.X +
                                 ex.MaxPoint.X) * 0.5,
                                (ex.MinPoint.Y +
                                 ex.MaxPoint.Y) * 0.5,
                                0.0);

                        double dx =
                            Math.Abs(
                                ex.MaxPoint.X -
                                ex.MinPoint.X);

                        double dy =
                            Math.Abs(
                                ex.MaxPoint.Y -
                                ex.MinPoint.Y);

                        bool yInside =
                            c.Y <= upper &&
                            c.Y >= lower;

                        bool leftOfDescription =
                            c.X <
                            splitX;

                        // STEP 18F:
                        // Không được lấy "độ cao > 18% bảng" để loại symbol:
                        // với bảng chỉ 3 dòng thì CIRCLE/BLOCK thật dễ cao 25-30% bảng.
                        // Chỉ loại entity thật sự giống GRID LINE / BORDER.
                        bool looksLikeTableGrid =
                            IsSmartLegendTableGridEntity(
                                ent,
                                dx,
                                dy,
                                tableWidth,
                                tableHeight);

                        if (yInside &&
                            leftOfDescription &&
                            !looksLikeTableGrid)
                        {
                            rowSymbols.Add(
                                id);
                        }
                    }

                    if (rowSymbols.Count == 0)
                        continue;

                    // Ưu tiên BlockReference nếu trong hàng có block.
                    ObjectId blockId =
                        ObjectId.Null;

                    // STEP18G:
                    // AutoCAD POINT nhìn trên màn hình có thể là vòng tròn/chấm giữa,
                    // nhưng entity thực tế là DBPoint. Nếu không bắt DBPoint,
                    // dòng Legend sẽ biến mất hoàn toàn.
                    ObjectId pointId =
                        ObjectId.Null;

                    foreach (ObjectId id
                        in rowSymbols)
                    {
                        Entity ent =
                            tr.GetObject(
                                id,
                                OpenMode.ForRead,
                                false) as Entity;

                        if (ent is BlockReference)
                        {
                            blockId =
                                id;
                            break;
                        }

                        if (ent is DBPoint &&
                            pointId.IsNull)
                        {
                            pointId =
                                id;
                        }
                    }

                    SmartLegendAutoRow row =
                        new SmartLegendAutoRow();

                    row.STT =
                        rows.Count + 1;

                    row.DisplayName =
                        desc.Text;

                    row.FollowDn =
                        GuessSmartLegendFollowDn(
                            desc.Text);

                    List<ObjectId> previewIds =
                        rowSymbols;

                    if (!blockId.IsNull)
                    {
                        BlockReference br =
                            tr.GetObject(
                                blockId,
                                OpenMode.ForRead,
                                false) as BlockReference;

                        string blockName =
                            br != null
                                ? GetShopStatBlockName(
                                    tr,
                                    br)
                                : "";

                        row.MatchMode =
                            "BLOCK";

                        row.BlockKey =
                            br != null
                                ? GetSmartBlockIdentityKey(
                                    tr,
                                    br)
                                : NormalizeSmartSymbolKey(
                                    blockName);

                        // STEP18F:
                        // Một ký hiệu BLOCK được học theo 2 khóa:
                        // 1) BlockKey - nhanh/chuẩn khi tên block giống nhau.
                        // 2) Geometry fingerprint - fallback khi copy/explode/
                        //    đổi tên block nhưng hình vẫn giống Legend.
                        row.GeometryFingerprint =
                            br != null
                                ? BuildSmartBlockGeometryFingerprint(
                                    tr,
                                    br)
                                : "";

                        string dynamicState =
                            br != null
                                ? GetSmartDynamicBlockStateKey(
                                    br)
                                : "";

                        row.SymbolSummary =
                            string.IsNullOrWhiteSpace(
                                blockName)
                                ? "BLOCK"
                                : blockName +
                                  (string.IsNullOrWhiteSpace(
                                       dynamicState)
                                      ? ""
                                      : " / STATE: " +
                                        dynamicState);

                        if (br != null)
                        {
                            row.SymbolCenter =
                                new Point3d(
                                    br.Position.X,
                                    br.Position.Y,
                                    0.0);
                        }

                        previewIds =
                            new List<ObjectId>
                            {
                                blockId
                            };
                    }
                    else if (!pointId.IsNull)
                    {
                        DBPoint point =
                            tr.GetObject(
                                pointId,
                                OpenMode.ForRead,
                                false) as DBPoint;

                        if (point == null)
                        {
                            continue;
                        }

                        row.MatchMode =
                            "POINT";

                        row.BlockKey =
                            GetSmartPointSignature(
                                point);

                        row.GeometryFingerprint =
                            "";

                        row.SymbolSummary =
                            GetSmartPointSummary(
                                point);

                        row.SymbolCenter =
                            new Point3d(
                                point.Position.X,
                                point.Position.Y,
                                0.0);

                        previewIds =
                            new List<ObjectId>
                            {
                                pointId
                            };
                    }
                    else
                    {
                        string fingerprint =
                            BuildSmartGeometryFingerprint(
                                tr,
                                rowSymbols);

                        if (string.IsNullOrWhiteSpace(
                                fingerprint))
                        {
                            fingerprint =
                                BuildSmartGenericLegendFingerprint(
                                    tr,
                                    rowSymbols);

                            if (string.IsNullOrWhiteSpace(
                                    fingerprint))
                            {
                                continue;
                            }

                            row.MatchMode =
                                "GENERIC";
                        }
                        else
                        {
                            row.MatchMode =
                                "GEOMETRY";
                        }

                        row.GeometryFingerprint =
                            fingerprint;

                        row.BlockKey =
                            (string.Equals(
                                 row.MatchMode,
                                 "GENERIC",
                                 StringComparison.OrdinalIgnoreCase)
                                ? "GEN_"
                                : "GEO_") +
                            Convert.ToBase64String(
                                Encoding.UTF8.GetBytes(
                                    fingerprint));

                        row.SymbolSummary =
                            string.Equals(
                                row.MatchMode,
                                "GENERIC",
                                StringComparison.OrdinalIgnoreCase)
                                ? "GENERIC / " +
                                  GetSmartGenericLegendSummary(
                                      tr,
                                      rowSymbols)
                                : GetSmartGeometryFingerprintSummary(
                                      fingerprint);

                        List<Point3d> centers =
                            new List<Point3d>();

                        foreach (ObjectId id
                            in rowSymbols)
                        {
                            Entity ent =
                                tr.GetObject(
                                    id,
                                    OpenMode.ForRead,
                                    false) as Entity;

                            if (ent == null)
                                continue;

                            try
                            {
                                Extents3d ex =
                                    ent.GeometricExtents;

                                centers.Add(
                                    new Point3d(
                                        (ex.MinPoint.X +
                                         ex.MaxPoint.X) * 0.5,
                                        (ex.MinPoint.Y +
                                         ex.MaxPoint.Y) * 0.5,
                                        0.0));
                            }
                            catch
                            {
                            }
                        }

                        if (centers.Count > 0)
                        {
                            row.SymbolCenter =
                                new Point3d(
                                    centers.Average(
                                        p =>
                                            p.X),
                                    centers.Average(
                                        p =>
                                            p.Y),
                                    0.0);
                        }
                    }

                    // STEP19 - CV-Lite:
                    // Ảnh vuông chỉ dùng làm visual fingerprint, không hiển thị.
                    using (System.Drawing.Bitmap visionBitmap =
                        CreateSmartLegendPreviewBitmap(
                            tr,
                            previewIds,
                            96,
                            96))
                    {
                        row.RasterSignature =
                            BuildSmartRasterSignature(
                                visionBitmap);
                    }

                    row.Preview =
                        CreateSmartLegendPreviewBitmap(
                            tr,
                            previewIds,
                            130,
                            60);

                    rows.Add(
                        row);
                }

                tr.Commit();
            }

            return
                rows
                    .OrderBy(
                        r =>
                            r.STT)
                    .ToList();
        }

        private bool IsSmartLegendTableGridEntity(
            Entity ent,
            double dx,
            double dy,
            double tableWidth,
            double tableHeight)
        {
            if (ent == null)
                return false;

            // Block/Circle/Arc gần như chắc chắn là symbol, không phải grid.
            if (ent is BlockReference ||
                ent is Circle ||
                ent is Arc ||
                ent is DBPoint)
            {
                return false;
            }

            double widthRatio =
                dx /
                Math.Max(
                    tableWidth,
                    1.0);

            double heightRatio =
                dy /
                Math.Max(
                    tableHeight,
                    1.0);

            double maxSpan =
                Math.Max(
                    dx,
                    dy);

            double minSpan =
                Math.Min(
                    dx,
                    dy);

            double aspect =
                maxSpan /
                Math.Max(
                    minSpan,
                    1.0);

            if (ent is Line)
            {
                return
                    (widthRatio >= 0.34 ||
                     heightRatio >= 0.55) &&
                    aspect >= 8.0;
            }

            if (ent is Polyline pl)
            {
                // Border/khung bảng thường rất dài hoặc bao gần toàn row/table.
                if (widthRatio >= 0.55 ||
                    heightRatio >= 0.70)
                {
                    return true;
                }

                // Polyline symbol có thể lớn nhưng thường không phải một nét siêu dài/mảnh.
                if (!pl.Closed &&
                    aspect >= 10.0 &&
                    (widthRatio >= 0.30 ||
                     heightRatio >= 0.45))
                {
                    return true;
                }
            }

            return false;
        }

        private List<SmartLegendTextCandidate> MergeSmartLegendTextLines(
            List<SmartLegendTextCandidate> descriptions,
            double tableHeight)
        {
            List<SmartLegendTextCandidate> result =
                new List<SmartLegendTextCandidate>();

            if (descriptions == null ||
                descriptions.Count == 0)
            {
                return result;
            }

            double yTolerance =
                Math.Max(
                    tableHeight * 0.018,
                    35.0);

            foreach (SmartLegendTextCandidate item
                in descriptions)
            {
                SmartLegendTextCandidate existing =
                    result.FirstOrDefault(
                        r =>
                            Math.Abs(
                                r.Center.Y -
                                item.Center.Y) <=
                            yTolerance);

                if (existing == null)
                {
                    result.Add(
                        new SmartLegendTextCandidate
                        {
                            Id =
                                item.Id,
                            Text =
                                item.Text,
                            Center =
                                item.Center,
                            Extents =
                                item.Extents
                        });
                }
                else
                {
                    // Một MText/Text nhiều dòng trong cùng row:
                    // nối nội dung theo thứ tự trái -> phải.
                    if (!existing.Text.Contains(
                            item.Text,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        existing.Text =
                            (existing.Text +
                             " " +
                             item.Text)
                                .Trim();
                    }

                    existing.Center =
                        new Point3d(
                            Math.Max(
                                existing.Center.X,
                                item.Center.X),
                            (existing.Center.Y +
                             item.Center.Y) * 0.5,
                            0.0);

                    Extents3d merged =
                        existing.Extents;

                    merged.AddExtents(
                        item.Extents);

                    existing.Extents =
                        merged;
                }
            }

            return
                result
                    .OrderByDescending(
                        r =>
                            r.Center.Y)
                    .ToList();
        }

        private string GetSmartPointSignature(
            DBPoint point)
        {
            if (point == null)
                return "";

            string layer =
                NormalizeSmartSymbolKey(
                    point.Layer ??
                    "");

            int colorIndex =
                256;

            try
            {
                colorIndex =
                    point.ColorIndex;
            }
            catch
            {
            }

            int pdMode =
                0;

            try
            {
                object raw =
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .GetSystemVariable(
                            "PDMODE");

                if (raw != null)
                {
                    int.TryParse(
                        Convert.ToString(
                            raw,
                            CultureInfo.InvariantCulture),
                        out pdMode);
                }
            }
            catch
            {
            }

            return
                "POINT|L=" +
                layer +
                "|C=" +
                colorIndex.ToString(
                    CultureInfo.InvariantCulture) +
                "|M=" +
                pdMode.ToString(
                    CultureInfo.InvariantCulture);
        }

        private string GetSmartPointSummary(
            DBPoint point)
        {
            int pdMode =
                0;

            try
            {
                object raw =
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .GetSystemVariable(
                            "PDMODE");

                if (raw != null)
                {
                    int.TryParse(
                        Convert.ToString(
                            raw,
                            CultureInfo.InvariantCulture),
                        out pdMode);
                }
            }
            catch
            {
            }

            return
                "POINT / DBPoint / PDMODE=" +
                pdMode.ToString(
                    CultureInfo.InvariantCulture);
        }

        private static bool GuessSmartLegendFollowDn(
            string displayName)
        {
            if (string.IsNullOrWhiteSpace(
                    displayName))
            {
                return false;
            }

            string key =
                BoDauTiengViet(
                    displayName)
                    .ToUpperInvariant();

            // Chỉ auto tick những loại có xác suất cao thực sự lấy size theo ống.
            // Người dùng vẫn sửa checkbox trong bảng review trước khi OK.
            if (key.Contains("VAN ") ||
                key.StartsWith("VAN") ||
                key.Contains("VALVE") ||
                key.Contains("Y LOC") ||
                key.Contains("LOC Y") ||
                key.Contains("CHECK VALVE") ||
                key.Contains("CONG TAC DONG CHAY") ||
                key.Contains("FLOW SWITCH"))
            {
                return true;
            }

            return false;
        }

        private bool ShowSmartLegendReviewDialog(
            Document doc,
            List<SmartLegendAutoRow> rows)
        {
            if (doc == null ||
                rows == null ||
                rows.Count == 0)
