                            }

                            SmartLegendAutoRow row =
                                grid.Rows[e.RowIndex].Tag as SmartLegendAutoRow;

                            if (row == null)
                                return;

                            if (string.Equals(
                                    columnName,
                                    "EDIT_INFO",
