                                    grid.Rows[e.RowIndex]
                                        .Cells["MODE"].Value =
                                        GetSmartLegendMatchModeDisplay(
                                            row.MatchMode);
                                }

                                return;
                            }

                            if (!string.Equals(
                                    columnName,
                                    "RESELECT",
                                    StringComparison.OrdinalIgnoreCase))
                            {
                                return;
                            }

                            syncGridToRows();

                            reselectRow =
                                row;

                            form.DialogResult =
                                System.Windows.Forms.DialogResult.Retry;

                            form.Close();
                        };

                    grid.RowsRemoved +=
                        (s, e) =>
                        {
                            for (int i = 0;
                                i < grid.Rows.Count;
                                i++)
                            {
                                if (!grid.Rows[i].IsNewRow)
                                {
                                    grid.Rows[i].Cells["STT"].Value =
