                            form.Close();
                        };

                    okButton.Text =
                        "OK - QUÉT BẢN VẼ";

                    okButton.Width =
                        190;

                    okButton.Height =
                        40;

                    okButton.Left =
                        785;

                    okButton.Top =
                        654;

                    okButton.DialogResult =
                        System.Windows.Forms.DialogResult.OK;

                    okButton.Font =
                        new System.Drawing.Font(
                            "Segoe UI",
                            10.0f,
                            System.Drawing.FontStyle.Bold);

                    okButton.BackColor =
                        System.Drawing.Color.FromArgb(
                            37,
                            99,
                            235);

                    okButton.ForeColor =
                        System.Drawing.Color.White;

                    okButton.FlatStyle =
                        System.Windows.Forms.FlatStyle.Flat;

                    cancelButton.Text =
                        "HỦY";

                    cancelButton.Width =
                        120;

                    cancelButton.Height =
                        40;

                    cancelButton.Left =
                        1005;

                    cancelButton.Top =
                        654;

                    cancelButton.DialogResult =
                        System.Windows.Forms.DialogResult.Cancel;

                    cancelButton.Font =
                        new System.Drawing.Font(
                            "Segoe UI",
                            10.0f,
                            System.Drawing.FontStyle.Bold);

                    form.Controls.Add(
                        title);

                    form.Controls.Add(
                        subTitle);

                    form.Controls.Add(
                        grid);

                    form.Controls.Add(
                        addButton);

                    form.Controls.Add(
                        okButton);

                    form.Controls.Add(
                        cancelButton);

                    form.AcceptButton =
                        okButton;

                    form.CancelButton =
                        cancelButton;

                    System.Windows.Forms.DialogResult result =
                        form.ShowDialog();

                    syncGridToRows();

                    // Đồng bộ việc người dùng xóa row trên DataGridView về List gốc.
                    HashSet<SmartLegendAutoRow> remaining =
                        new HashSet<SmartLegendAutoRow>(
                            grid.Rows
                                .Cast<System.Windows.Forms.DataGridViewRow>()
                                .Where(
                                    r =>
                                        !r.IsNewRow &&
                                        r.Tag is SmartLegendAutoRow)
                                .Select(
                                    r =>
                                        (SmartLegendAutoRow)r.Tag));

                    rows.RemoveAll(
                        r =>
                            !remaining.Contains(
                                r));

                    if (result ==
                        System.Windows.Forms.DialogResult.Yes)
                    {
                        _smartValveStage =
                            "LEGEND_ADD_SYMBOL_FROM_CAD";

                        if (CreateSmartLegendRowFromCad(
                                doc,
                                out SmartLegendAutoRow newRow) &&
                            newRow != null)
                        {
                            rows.Add(
                                newRow);
                        }

                        continue;
                    }

                    if (result ==
                            System.Windows.Forms.DialogResult.Retry &&
                        reselectRow != null)
                    {
                        _smartValveStage =
                            "LEGEND_RESELECT_SYMBOL";

                        ReselectSmartLegendSymbol(
                            doc,
                            reselectRow);

                        continue;
                    }

                    if (result !=
                        System.Windows.Forms.DialogResult.OK)
                    {
                        return false;
                    }

                    int number =
                        1;

                    foreach (SmartLegendAutoRow row
                        in rows)
                    {
                        row.STT =
                            number++;
                    }

                    return true;
                }
            }
        }

        private string GetSmartLegendMatchModeDisplay(
            string matchMode)
        {
            if (string.Equals(
                    matchMode,
                    "GEOMETRY",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "HÌNH EXPLODE";
            }

            if (string.Equals(
                    matchMode,
                    "POINT",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "POINT";
            }

            if (string.Equals(
                    matchMode,
                    "GENERIC",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "HÌNH GENERIC";
            }

            return "BLOCK";
        }

        private bool CreateSmartLegendRowFromCad(
            Document doc,
            out SmartLegendAutoRow row)
        {
            row =
                new SmartLegendAutoRow
                {
                    DisplayName =
                        "KÝ HIỆU MỚI",
                    FollowDn =
                        false
                };

            if (!ReselectSmartLegendSymbol(
                    doc,
                    row))
            {
                DisposeSmartLegendRowPreview(
                    row);

                row =
                    null;

                return false;
            }

            row.DisplayName =
                "";

            if (!ShowSmartLegendRowEditDialog(
                    row,
                    true))
            {
                DisposeSmartLegendRowPreview(
                    row);

                row =
                    null;

                return false;
            }

            return
                !string.IsNullOrWhiteSpace(
                    row.DisplayName);
        }

        private void DisposeSmartLegendRowPreview(
            SmartLegendAutoRow row)
        {
            if (row?.Preview == null)
                return;

            try
            {
                row.Preview.Dispose();
            }
            catch
            {
            }

            row.Preview =
                null;
        }

