        private bool TryPickSmartLegendTextFromCad(
            out string pickedText)
        {
            pickedText =
                "";

            Document doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return false;

            Editor ed =
                doc.Editor;

            Database db =
                doc.Database;

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .MainWindow
                    .Focus();
            }
            catch
            {
            }

            PromptEntityOptions peo =
                new PromptEntityOptions(
                    "\nChọn TEXT / MTEXT / ATTRIBUTE / MLEADER chứa TÊN THIẾT BỊ: ");

            peo.SetRejectMessage(
                "\nĐối tượng này không phải text. Hãy chọn TEXT, MTEXT, ATTRIBUTE hoặc MLEADER có chữ.");

            peo.AddAllowedClass(
                typeof(DBText),
                true);

            peo.AddAllowedClass(
                typeof(MText),
                true);

            peo.AddAllowedClass(
                typeof(AttributeReference),
                true);

            peo.AddAllowedClass(
                typeof(MLeader),
                true);

            PromptEntityResult per =
                ed.GetEntity(
                    peo);

            if (per.Status !=
                PromptStatus.OK)
            {
                return false;
            }

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                Entity ent =
                    tr.GetObject(
                        per.ObjectId,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent == null)
                {
                    tr.Commit();
                    return false;
                }

                string raw =
                    "";

                if (ent is DBText dbText)
                {
                    raw =
                        dbText.TextString ??
                        "";
                }
                else if (ent is MText mText)
                {
                    raw =
                        mText.Text ??
                        "";
                }
                else if (ent is AttributeReference attribute)
                {
                    raw =
                        attribute.TextString ??
                        "";
                }
                else if (ent is MLeader leader)
                {
                    try
                    {
                        MText leaderText =
                            leader.MText;

                        if (leaderText != null)
                        {
                            raw =
                                leaderText.Text ??
                                "";
                        }
                    }
                    catch
                    {
                    }
                }

                tr.Commit();

                pickedText =
                    CleanSmartCadPickedText(
                        raw);
            }

            if (string.IsNullOrWhiteSpace(
                    pickedText))
            {
                MessageBox.Show(
                    "Text vừa chọn không có nội dung đọc được.",
                    "ĐỌC TEXT TRÊN CAD");

                return false;
            }

            return true;
        }

        private string CleanSmartCadPickedText(
            string value)
        {
            string result =
                value ??
                "";

            result =
                result
                    .Replace(
                        "\\P",
                        " ")
                    .Replace(
                        "\r",
                        " ")
                    .Replace(
                        "\n",
                        " ")
                    .Replace(
                        "\t",
                        " ");

            // Bỏ một số format code MText thường gặp nhưng giữ nguyên tiếng Việt.
            result =
                Regex.Replace(
                    result,
                    @"\\[ACFHQTW][^;]*;",
                    "");

            result =
                Regex.Replace(
                    result,
                    @"\{|\}",
                    "");

            result =
                Regex.Replace(
                    result,
                    @"\s+",
                    " ");

            return
                result.Trim();
        }

        private void PersistSmartLegendRowImmediately(
            SmartLegendAutoRow row,
            string source)
        {
            if (row == null ||
                string.IsNullOrWhiteSpace(
                    row.DisplayName) ||
                (string.IsNullOrWhiteSpace(
                     row.BlockKey) &&
                 string.IsNullOrWhiteSpace(
                     row.GeometryFingerprint)))
            {
                return;
            }

            string sizeRule =
                row.FollowDn
                    ? "THEO_ONG"
                    : "KHONG_SIZE";

            List<SmartSymbolRule> library =
                LoadSmartSymbolRules();

            SmartSymbolRule primaryRule =
                new SmartSymbolRule
                {
                    BlockKey =
                        row.BlockKey,
                    DisplayName =
                        row.DisplayName,
                    SizeRule =
                        sizeRule,
                    MatchMode =
                        row.MatchMode,
                    GeometryFingerprint =
                        row.GeometryFingerprint ?? "",
                    RasterSignature =
                        row.RasterSignature ?? ""
                };

            UpsertSmartRuleList(
                library,
                primaryRule);

            List<SmartSymbolRule> learnedRules =
                new List<SmartSymbolRule>
                {
                    primaryRule
                };

            // BLOCK có thêm fallback theo hình học để lần sau tên block đổi
            // nhưng hình ký hiệu giống thì vẫn còn cơ hội nhận đúng.
            if (string.Equals(
                    row.MatchMode,
                    "BLOCK",
                    StringComparison.OrdinalIgnoreCase) &&
                !string.IsNullOrWhiteSpace(
                    row.GeometryFingerprint))
            {
                SmartSymbolRule geometryRule =
                    new SmartSymbolRule
                    {
                        BlockKey =
                            "GEO_BLOCK_" +
                            Convert.ToBase64String(
                                Encoding.UTF8.GetBytes(
                                    row.GeometryFingerprint)),
                        DisplayName =
                            row.DisplayName,
                        SizeRule =
                            sizeRule,
                        MatchMode =
                            "GEOMETRY",
                        GeometryFingerprint =
                            row.GeometryFingerprint,
                        RasterSignature =
                            row.RasterSignature ?? ""
                    };

                UpsertSmartRuleList(
                    library,
                    geometryRule);

                learnedRules.Add(
                    geometryRule);
            }

            SaveSmartSymbolRules(
                library);

            // Local AI Memory cũng ghi ngay.
            string normalizedSource =
                string.IsNullOrWhiteSpace(
                    source)
                    ? "MANUAL_SYMBOL_EDIT"
                    : source;

            LearnAiFromSymbolRules(
                learnedRules,
                normalizedSource);

            CaptureAiDatasetFromLegendRow(
                row,
                "POSITIVE",
                normalizedSource,
                "");

            UpdateAiLearningStatusUi();
            UpdateAiDatasetStatusUi();
        }

        private bool ReselectSmartLegendSymbol(
            Document doc,
            SmartLegendAutoRow row)
        {
            if (doc == null ||
                row == null)
            {
                return false;
            }

            Editor ed =
                doc.Editor;

            Database db =
                doc.Database;

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .MainWindow
                    .Focus();
            }
            catch
            {
            }

            PromptSelectionOptions pso =
                new PromptSelectionOptions();

            pso.MessageForAdding =
                "\nChọn ĐÚNG KÝ HIỆU cho \"" +
                (string.IsNullOrWhiteSpace(
                     row.DisplayName)
                    ? "KÝ HIỆU MỚI"
                    : row.DisplayName) +
                "\". Có thể chọn BLOCK, POINT hoặc quét các nét EXPLODE/HATCH/SOLID của ký hiệu: ";

            PromptSelectionResult psr =
                ed.GetSelection(
                    pso);

            if (psr.Status !=
                    PromptStatus.OK ||
                psr.Value == null ||
                psr.Value.Count == 0)
            {
                return false;
            }

            List<ObjectId> selectedIds =
                psr.Value
                    .GetObjectIds()
                    .ToList();

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                ObjectId blockId =
                    ObjectId.Null;

                ObjectId pointId =
                    ObjectId.Null;

                List<ObjectId> graphicalIds =
                    new List<ObjectId>();

                foreach (ObjectId id
                    in selectedIds)
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased)
                    {
                        continue;
                    }

                    if (ent is DBText ||
                        ent is MText)
                    {
                        continue;
                    }

                    graphicalIds.Add(
                        id);

                    if (ent is BlockReference &&
                        blockId.IsNull)
                    {
                        blockId =
                            id;

                        continue;
                    }

                    if (ent is DBPoint &&
                        pointId.IsNull)
                    {
                        pointId =
                            id;
                    }
                }

                if (graphicalIds.Count == 0)
                {
                    tr.Commit();

                    MessageBox.Show(
                        "Vùng vừa chọn không có đối tượng đồ họa hợp lệ.",
                        "CHỌN KÝ HIỆU");

                    return false;
                }

                List<ObjectId> previewIds =
                    new List<ObjectId>();

                if (!blockId.IsNull)
                {
                    BlockReference br =
                        tr.GetObject(
                            blockId,
                            OpenMode.ForRead,
                            false) as BlockReference;

                    string blockName =
                        br != null
                            ? GetShopStatBlockName(
                                tr,
                                br)
                            : "";

                    string blockKey =
                        br != null
                            ? GetSmartBlockIdentityKey(
                                tr,
                                br)
                            : NormalizeSmartSymbolKey(
                                blockName);

                    if (string.IsNullOrWhiteSpace(
                            blockKey))
                    {
                        tr.Commit();
                        return false;
                    }

                    row.MatchMode =
                        "BLOCK";

                    row.BlockKey =
                        blockKey;

                    row.GeometryFingerprint =
                        br != null
                            ? BuildSmartBlockGeometryFingerprint(
                                tr,
                                br)
                            : "";

                    row.SymbolSummary =
                        blockName +
                        (br != null &&
                         !string.IsNullOrWhiteSpace(
                             GetSmartDynamicBlockStateKey(
                                 br))
                            ? " / STATE: " +
                              GetSmartDynamicBlockStateKey(
                                  br)
                            : "");

                    if (br != null)
                    {
                        row.SymbolCenter =
                            new Point3d(
                                br.Position.X,
                                br.Position.Y,
                                0.0);
                    }

                    previewIds.Add(
                        blockId);
                }
                else if (!pointId.IsNull &&
                         graphicalIds.Count == 1)
                {
                    DBPoint point =
                        tr.GetObject(
                            pointId,
                            OpenMode.ForRead,
                            false) as DBPoint;

                    if (point == null)
                    {
                        tr.Commit();
                        return false;
                    }

                    row.MatchMode =
                        "POINT";

                    row.BlockKey =
                        GetSmartPointSignature(
                            point);

                    row.GeometryFingerprint =
                        "";

                    row.SymbolSummary =
                        GetSmartPointSummary(
                            point);

                    row.SymbolCenter =
                        new Point3d(
                            point.Position.X,
                            point.Position.Y,
                            0.0);

                    previewIds.Add(
                        pointId);
                }
                else
                {
                    string fingerprint =
                        BuildSmartGeometryFingerprint(
                            tr,
                            graphicalIds);

                    if (!string.IsNullOrWhiteSpace(
                            fingerprint))
                    {
                        row.MatchMode =
                            "GEOMETRY";

                        row.GeometryFingerprint =
                            fingerprint;

                        row.BlockKey =
                            "GEO_" +
                            Convert.ToBase64String(
                                Encoding.UTF8.GetBytes(
                                    fingerprint));

                        row.SymbolSummary =
                            GetSmartGeometryFingerprintSummary(
                                fingerprint);
                    }
                    else
                    {
                        fingerprint =
                            BuildSmartGenericLegendFingerprint(
                                tr,
                                graphicalIds);

                        if (string.IsNullOrWhiteSpace(
                                fingerprint))
                        {
                            tr.Commit();

                            MessageBox.Show(
                                "Không tạo được dấu vân tay cho ký hiệu. Hãy chọn riêng phần hình của ký hiệu, không chọn text/khung bảng.",
                                "CHỌN KÝ HIỆU");

                            return false;
                        }

                        row.MatchMode =
                            "GENERIC";

                        row.GeometryFingerprint =
                            fingerprint;

                        row.BlockKey =
                            "GEN_" +
                            Convert.ToBase64String(
                                Encoding.UTF8.GetBytes(
                                    fingerprint));

                        row.SymbolSummary =
                            "GENERIC / " +
                            GetSmartGenericLegendSummary(
                                tr,
                                graphicalIds);
                    }

                    List<Point3d> centers =
                        new List<Point3d>();

                    foreach (ObjectId id
                        in graphicalIds)
                    {
                        Entity ent =
                            tr.GetObject(
                                id,
                                OpenMode.ForRead,
                                false) as Entity;

                        if (ent == null)
                            continue;

                        try
                        {
                            Extents3d ex =
                                ent.GeometricExtents;

                            centers.Add(
                                new Point3d(
                                    (ex.MinPoint.X +
                                     ex.MaxPoint.X) * 0.5,
                                    (ex.MinPoint.Y +
                                     ex.MaxPoint.Y) * 0.5,
                                    0.0));
                        }
                        catch
                        {
                        }
                    }

                    if (centers.Count > 0)
                    {
                        row.SymbolCenter =
                            new Point3d(
                                centers.Average(
                                    p => p.X),
                                centers.Average(
                                    p => p.Y),
                                0.0);
                    }

                    previewIds =
                        graphicalIds;
                }

                if (row.Preview != null)
                {
                    try
                    {
                        row.Preview.Dispose();
                    }
                    catch
                    {
                    }

                    row.Preview =
                        null;
                }

                using (System.Drawing.Bitmap visionBitmap =
                    CreateSmartLegendPreviewBitmap(
                        tr,
                        previewIds,
                        96,
                        96))
                {
                    row.RasterSignature =
                        BuildSmartRasterSignature(
                            visionBitmap);
                }

                row.Preview =
                    CreateSmartLegendPreviewBitmap(
                        tr,
                        previewIds,
                        130,
                        60);

                tr.Commit();
            }

            return true;
        }


        private List<SmartLegendAutoRow> CloneSmartLegendRowsForSession(
            List<SmartLegendAutoRow> rows)
        {
            List<SmartLegendAutoRow> result =
                new List<SmartLegendAutoRow>();

            if (rows == null)
                return result;

            foreach (SmartLegendAutoRow row
                in rows)
            {
                if (row == null)
                    continue;

                System.Drawing.Bitmap preview =
                    null;

                if (row.Preview != null)
                {
                    try
                    {
                        preview =
                            new System.Drawing.Bitmap(
                                row.Preview);
                    }
                    catch
                    {
                    }
                }

                result.Add(
                    new SmartLegendAutoRow
                    {
                        STT =
                            row.STT,
                        DisplayName =
                            row.DisplayName,
                        FollowDn =
                            row.FollowDn,
                        MatchMode =
                            row.MatchMode,
                        BlockKey =
                            row.BlockKey,
                        GeometryFingerprint =
                            row.GeometryFingerprint,
                        RasterSignature =
                            row.RasterSignature,
                        SymbolSummary =
                            row.SymbolSummary,
                        SymbolCenter =
                            row.SymbolCenter,
                        Preview =
                            preview
                    });
            }

            return result;
        }

        private static List<SmartSymbolRule> CloneSmartRulesForSession(
            List<SmartSymbolRule> rules)
        {
            List<SmartSymbolRule> result =
                new List<SmartSymbolRule>();

            if (rules == null)
                return result;

            foreach (SmartSymbolRule rule
                in rules)
            {
                if (rule == null)
                    continue;

                result.Add(
                    new SmartSymbolRule
                    {
                        BlockKey =
                            rule.BlockKey,
                        DisplayName =
                            rule.DisplayName,
                        SizeRule =
                            rule.SizeRule,
                        MatchMode =
                            rule.MatchMode,
                        GeometryFingerprint =
                            rule.GeometryFingerprint,
                        RasterSignature =
                            rule.RasterSignature
                    });
            }

            return result;
        }

        private void SaveLastSmartAuditSession(
            List<SmartAuditRow> auditRows,
            List<string> legendZero,
            List<SmartSymbolRule> rules)
        {
            _lastSmartAuditRows =
                auditRows != null
                    ? new List<SmartAuditRow>(
                        auditRows)
                    : new List<SmartAuditRow>();

            _lastSmartLegendZero =
                legendZero != null
                    ? new List<string>(
                        legendZero)
                    : new List<string>();

            _lastSmartRules =
                CloneSmartRulesForSession(
                    rules);
        }

        private void ReopenLastSmartAuditSession(
            Document doc)
        {
            if (doc == null ||
                _lastSmartAuditRows == null ||
                _lastSmartAuditRows.Count == 0)
            {
                MessageBox.Show(
                    "Chưa có phiên kiểm tra gần nhất để mở lại.",
                    "NHẬN DIỆN VAN / THIẾT BỊ");
                return;
            }

            AttachPreviewToAuditRows(
                doc,
                _lastSmartAuditRows,
                _lastSmartLegendRows);

            bool accepted =
                ShowSmartAuditReportDialog(
                    doc,
                    _lastSmartAuditRows,
                    _lastSmartLegendZero);

            if (!accepted)
                return;

            ApplySmartAuditCorrections(
                _lastSmartAuditRows);

            UpdateSmartRulesFromAuditRows(
                _lastSmartRules,
                _lastSmartAuditRows);


            LearnAiFromAuditCorrections(
                _lastSmartAuditRows);
            HashSet<string> detected =
                new HashSet<string>(
                    _lastSmartAuditRows
                        .Where(
                            r =>
                                r != null &&
                                !string.Equals(
                                    r.Status,
                                    "MISSING",
                                    StringComparison.OrdinalIgnoreCase) &&
                                !string.IsNullOrWhiteSpace(
                                    r.Name))
                        .Select(
                            r =>
                                r.Name),
                    StringComparer.OrdinalIgnoreCase);

            _lastSmartLegendZero =
                _lastSmartRules
                    .Select(
                        r =>
                            r.DisplayName)
                    .Where(
                        n =>
                            !detected.Contains(
                                n))
                    .Distinct(
                        StringComparer.OrdinalIgnoreCase)
                    .OrderBy(
                        n =>
                            n)
                    .ToList();

            _lastSmartAuditRows =
                DeduplicateSmartAuditRows(
                    _lastSmartAuditRows);

            DrawSmartAuditMarkers(
                doc,
                _lastSmartAuditRows);

            List<SmartValveStatRow> stats =
                BuildSmartStatsFromAuditRows(
                    _lastSmartAuditRows);

            if (stats.Count > 0)
            {
                // Nếu bảng thống kê cũ vẫn còn,
                // hàm xuất bảng sẽ thay nó tại đúng vị trí thay vì tạo thêm bảng mới.
                XuatBangThongKeVanThongMinh(
                    stats);
            }

            MessageBox.Show(
                "Đã cập nhật lại phiên kiểm tra và bảng thống kê gần nhất.",
                "NHẬN DIỆN VAN / THIẾT BỊ");
        }

        private void ReopenLastSmartLegendSession(
            Document doc)
        {
            if (doc == null ||
                _lastSmartLegendRows == null ||
                _lastSmartLegendRows.Count == 0)
            {
                MessageBox.Show(
                    "Chưa có bảng ký hiệu gần nhất để sửa.",
                    "NHẬN DIỆN VAN / THIẾT BỊ");
                return;
            }

            bool accepted =
                ShowSmartLegendReviewDialog(
                    doc,
                    _lastSmartLegendRows);

            if (!accepted)
                return;

            _lastSmartRules =
                MergeSmartLegendRowsIntoLibrary(
                    _lastSmartLegendRows);

            int action =
                GetSmartMenuChoice(
                    doc.Editor,
                    "\nĐã sửa lại bảng KÝ HIỆU. " +
                    "1=QUÉT LẠI MẶT BẰNG, " +
                    "2=CHỈ LƯU THƯ VIỆN",
                    1,
                    2,
                    1);

            if (action == 1)
            {
                ScanSmartValveDeviceStatistics(
                    doc,
                    _lastSmartRules);
            }
        }

        private List<SmartSymbolRule> MergeSmartLegendRowsIntoLibrary(
            List<SmartLegendAutoRow> rows)
        {
            List<SmartSymbolRule> library =
                LoadSmartSymbolRules();

            List<SmartSymbolRule> currentProjectRules =
                new List<SmartSymbolRule>();

            if (rows == null)
                return currentProjectRules;

            foreach (SmartLegendAutoRow row
                in rows)
            {
                if (row == null ||
                    string.IsNullOrWhiteSpace(
                        row.DisplayName))
                {
                    continue;
                }

                string sizeRule =
                    row.FollowDn
                        ? "THEO_ONG"
                        : "KHONG_SIZE";

                SmartSymbolRule currentRule =
                    new SmartSymbolRule
                    {
                        BlockKey =
                            row.BlockKey,
                        DisplayName =
                            row.DisplayName,
                        SizeRule =
                            sizeRule,
                        MatchMode =
                            row.MatchMode,
                        GeometryFingerprint =
                            row.GeometryFingerprint ?? "",
                        RasterSignature =
                            row.RasterSignature ?? ""
                    };

                currentProjectRules.Add(
                    currentRule);

                // STEP18F:
                // BLOCK rule có thêm fallback GEOMETRY.
                // Nhờ vậy cùng ký hiệu nhưng block name khác vẫn nhận được.
                SmartSymbolRule geometryFallbackRule =
                    null;

                if (string.Equals(
                        row.MatchMode,
                        "BLOCK",
                        StringComparison.OrdinalIgnoreCase) &&
                    !string.IsNullOrWhiteSpace(
                        row.GeometryFingerprint))
                {
                    geometryFallbackRule =
                        new SmartSymbolRule
                        {
                            BlockKey =
                                "GEO_BLOCK_" +
                                Convert.ToBase64String(
                                    Encoding.UTF8.GetBytes(
                                        row.GeometryFingerprint)),
                            DisplayName =
                                row.DisplayName,
                            SizeRule =
                                sizeRule,
                            MatchMode =
                                "GEOMETRY",
                            GeometryFingerprint =
                                row.GeometryFingerprint,
                            RasterSignature =
                                row.RasterSignature ?? ""
                        };

                    currentProjectRules.Add(
                        geometryFallbackRule);
                }

                SmartSymbolRule existing =
                    null;

                if (string.Equals(
                        row.MatchMode,
                        "GEOMETRY",
                        StringComparison.OrdinalIgnoreCase))
                {
                    existing =
                        library.FirstOrDefault(
                            r =>
                                r != null &&
                                string.Equals(
                                    r.MatchMode,
                                    "GEOMETRY",
                                    StringComparison.OrdinalIgnoreCase) &&
                                string.Equals(
                                    r.GeometryFingerprint,
                                    row.GeometryFingerprint,
                                    StringComparison.Ordinal));
                }
                else
                {
                    existing =
                        library.FirstOrDefault(
                            r =>
                                r != null &&
                                !string.Equals(
                                    r.MatchMode,
                                    "GEOMETRY",
                                    StringComparison.OrdinalIgnoreCase) &&
                                string.Equals(
                                    r.BlockKey,
                                    row.BlockKey,
                                    StringComparison.OrdinalIgnoreCase));
                }

                if (existing == null)
                {
                    library.Add(
                        new SmartSymbolRule
                        {
                            BlockKey =
                                currentRule.BlockKey,
                            DisplayName =
                                currentRule.DisplayName,
                            SizeRule =
                                currentRule.SizeRule,
                            MatchMode =
                                currentRule.MatchMode,
                            GeometryFingerprint =
                                currentRule.GeometryFingerprint,
                            RasterSignature =
                                currentRule.RasterSignature
                        });
                }
                else
                {
                    existing.DisplayName =
                        currentRule.DisplayName;

                    existing.SizeRule =
                        currentRule.SizeRule;

                    existing.MatchMode =
                        currentRule.MatchMode;

                    existing.GeometryFingerprint =
                        currentRule.GeometryFingerprint;

                    existing.RasterSignature =
                        currentRule.RasterSignature;
                }

                if (geometryFallbackRule != null)
                {
                    UpsertSmartRuleList(
                        library,
                        geometryFallbackRule);
                }
            }

            SaveSmartSymbolRules(
                library);

            // STEP 18:
            // Legend đã được người dùng review là nguồn học Positive đáng tin cậy.
            LearnAiFromLegendRows(
                rows);

            LearnAiFromSymbolRules(
                currentProjectRules,
                "LEGEND_DUAL_FINGERPRINT");

            // STEP21F1 - LEGEND -> DATASET:
            // Sau khi người dùng đã review và bấm OK - QUÉT BẢN VẼ,
            // TOÀN BỘ dòng Legend hợp lệ trở thành Positive training sample.
            // CaptureSample dùng SHA256 nên quét lại cùng ký hiệu không tạo ảnh rác.
            CaptureReviewedLegendRowsIntoDataset(
                rows,
                true);

            // Quan trọng:
            // lần quét hiện tại chỉ dùng đúng Legend của dự án vừa quét,
            // không kéo ký hiệu cũ của dự án khác vào kiểm tra "0 lần".
            return
                currentProjectRules;
        }


        private void DisposeSmartLegendPreviews(
            List<SmartLegendAutoRow> rows)
        {
            if (rows == null)
                return;

            foreach (SmartLegendAutoRow row
                in rows)
            {
                if (row?.Preview == null)
                    continue;

                try
                {
                    row.Preview.Dispose();
                }
                catch
                {
                }

                row.Preview =
                    null;
            }
        }

        // ============================================================
        // STEP19 - HYBRID VISION LITE
        // ------------------------------------------------------------
        // Mục tiêu: bổ sung một tầng nhận dạng bằng HÌNH ẢNH nhưng không kéo
        // EmguCV/OpenCV native DLL vào AutoCAD ngay ở giai đoạn này.
        //
        // Flow:
        // Exact BlockKey -> Vector Fingerprint -> Raster Silhouette -> Pipe Context.
        // Raster được chuẩn hóa scale + vị trí và so cả 4 góc xoay 90 độ.
        // ============================================================

        private string BuildSmartRasterSignature(
            System.Drawing.Bitmap bitmap)
        {
            if (bitmap == null ||
                bitmap.Width <= 0 ||
                bitmap.Height <= 0)
            {
                return "";
            }

            const int gridSize = 16;

            byte[,] grid =
                BuildSmartRasterGrid(
                    bitmap,
                    gridSize);

            if (grid == null)
                return "";

            List<string> variants =
                new List<string>();

            byte[,] current = grid;

            for (int rotation = 0;
                rotation < 4;
                rotation++)
            {
                byte[] flat =
                    new byte[
                        gridSize *
                        gridSize];

                int k = 0;

                for (int y = 0;
                    y < gridSize;
                    y++)
                {
                    for (int x = 0;
                        x < gridSize;
                        x++)
                    {
                        flat[k++] =
                            current[x, y];
                    }
                }

                variants.Add(
                    Convert.ToBase64String(
                        flat));

                current =
                    RotateSmartRasterGrid90(
                        current);
            }

            return
                string.Join(
                    ";",
                    variants);
        }

        private byte[,] BuildSmartRasterGrid(
            System.Drawing.Bitmap bitmap,
            int gridSize)
        {
            if (bitmap == null ||
                gridSize <= 0)
            {
                return null;
            }

            System.Drawing.Color background =
                bitmap.GetPixel(
                    0,
                    0);

            int width =
                bitmap.Width;

            int height =
                bitmap.Height;

            bool[,] foreground =
                new bool[
                    width,
                    height];

            int minX = width;
            int minY = height;
            int maxX = -1;
            int maxY = -1;

            for (int y = 0;
                y < height;
                y++)
            {
                for (int x = 0;
                    x < width;
                    x++)
                {
                    System.Drawing.Color c =
                        bitmap.GetPixel(
                            x,
                            y);

                    int dr = c.R - background.R;
                    int dg = c.G - background.G;
                    int db = c.B - background.B;

                    double colorDistance =
                        Math.Sqrt(
                            dr * dr +
                            dg * dg +
                            db * db);

                    bool isForeground =
                        colorDistance >= 34.0;

                    foreground[x, y] =
                        isForeground;

                    if (!isForeground)
                        continue;

                    minX = Math.Min(minX, x);
                    minY = Math.Min(minY, y);
                    maxX = Math.Max(maxX, x);
                    maxY = Math.Max(maxY, y);
                }
            }

            if (maxX < minX ||
                maxY < minY)
            {
                return
                    new byte[
                        gridSize,
                        gridSize];
            }

            int cropWidth =
                Math.Max(
                    1,
                    maxX - minX + 1);

            int cropHeight =
                Math.Max(
                    1,
                    maxY - minY + 1);

            int square =
                Math.Max(
                    cropWidth,
                    cropHeight);

            double centerX =
                (minX + maxX) * 0.5;

            double centerY =
                (minY + maxY) * 0.5;

            double left =
                centerX - square * 0.5;

            double top =
                centerY - square * 0.5;

            byte[,] result =
                new byte[
                    gridSize,
                    gridSize];

            for (int gy = 0;
                gy < gridSize;
                gy++)
            {
                for (int gx = 0;
                    gx < gridSize;
                    gx++)
                {
                    double x0 =
                        left +
                        square * gx / gridSize;

                    double x1 =
                        left +
                        square * (gx + 1) / gridSize;

                    double y0 =
                        top +
                        square * gy / gridSize;

                    double y1 =
                        top +
                        square * (gy + 1) / gridSize;

                    int ix0 =
                        Math.Max(
                            0,
                            (int)Math.Floor(x0));

                    int ix1 =
                        Math.Min(
                            width - 1,
                            (int)Math.Ceiling(x1));

                    int iy0 =
                        Math.Max(
                            0,
                            (int)Math.Floor(y0));

                    int iy1 =
                        Math.Min(
                            height - 1,
                            (int)Math.Ceiling(y1));

                    int count = 0;
                    int total = 0;

                    for (int py = iy0;
                        py <= iy1;
                        py++)
                    {
                        for (int px = ix0;
                            px <= ix1;
                            px++)
                        {
                            total++;

                            if (foreground[px, py])
                            {
                                count++;
                            }
                        }
                    }

                    double occupancy =
                        total > 0
                            ? (double)count / total
                            : 0.0;

                    // Thin CAD strokes need amplification after downsampling.
                    occupancy =
                        Math.Min(
                            1.0,
                            occupancy * 3.2);

                    result[gx, gy] =
                        (byte)Math.Round(
                            occupancy * 255.0);
                }
            }

            return result;
        }

        private byte[,] RotateSmartRasterGrid90(
            byte[,] source)
        {
            if (source == null)
                return null;

            int width =
                source.GetLength(0);

            int height =
                source.GetLength(1);

            byte[,] result =
                new byte[
                    height,
                    width];

            for (int y = 0;
                y < height;
                y++)
            {
                for (int x = 0;
                    x < width;
                    x++)
                {
                    result[
                        height - 1 - y,
                        x] =
                        source[x, y];
                }
            }

            return result;
        }

        private double CompareSmartRasterSignatures(
            string a,
            string b)
        {
            if (string.IsNullOrWhiteSpace(a) ||
                string.IsNullOrWhiteSpace(b))
            {
                return double.MaxValue;
            }

            string[] variantsA =
                a.Split(
                    new char[] { ';' },
                    StringSplitOptions.RemoveEmptyEntries);

            string[] variantsB =
                b.Split(
                    new char[] { ';' },
                    StringSplitOptions.RemoveEmptyEntries);

            double best =
                double.MaxValue;

            foreach (string va in variantsA)
            {
                byte[] ba;

                try
                {
                    ba =
                        Convert.FromBase64String(
                            va);
                }
                catch
                {
                    continue;
                }

                foreach (string vb in variantsB)
                {
                    byte[] bb;

                    try
                    {
                        bb =
                            Convert.FromBase64String(
                                vb);
                    }
                    catch
                    {
                        continue;
                    }

                    int n =
                        Math.Min(
                            ba.Length,
                            bb.Length);

                    if (n <= 0)
                        continue;

                    double total = 0.0;

                    for (int i = 0;
                        i < n;
                        i++)
                    {
                        total +=
                            Math.Abs(
                                ba[i] - bb[i]) /
                            255.0;
                    }

                    double score =
                        total / n;

                    if (score < best)
                    {
                        best = score;
                    }
                }
            }

            return best;
        }

        private double CompareSmartGeometryStructureRelaxed(
            string learned,
            string candidate)
        {
            if (!TryParseSmartGeometryFingerprint(
                    learned,
                    out SmartGeometryFingerprintData a) ||
                !TryParseSmartGeometryFingerprint(
                    candidate,
                    out SmartGeometryFingerprintData b))
            {
                return double.MaxValue;
            }

            double[] ca =
                new double[]
                {
                    a.LineCount,
                    a.ArcCount,
                    a.CircleCount,
                    a.PolylineCount
                };

            double[] cb =
                new double[]
                {
                    b.LineCount,
                    b.ArcCount,
                    b.CircleCount,
                    b.PolylineCount
                };

            double countDiff =
                0.0;

            double countBase =
                0.0;

            for (int i = 0;
                i < ca.Length;
                i++)
            {
                countDiff +=
                    Math.Abs(
                        ca[i] -
                        cb[i]);

                countBase +=
                    Math.Max(
                        ca[i],
                        cb[i]);
            }

            double countScore =
                countBase > 0.0
                    ? countDiff /
                      countBase
                    : 0.0;

            double topologyPenalty =
                0.0;

            if ((a.CircleCount > 0) !=
                (b.CircleCount > 0))
            {
                topologyPenalty +=
                    0.28;
            }

            if ((a.ArcCount > 0) !=
                (b.ArcCount > 0))
            {
                topologyPenalty +=
                    0.18;
            }

            int totalA =
                a.LineCount +
                a.ArcCount +
                a.CircleCount +
                a.PolylineCount;

            int totalB =
                b.LineCount +
                b.ArcCount +
                b.CircleCount +
                b.PolylineCount;

            double entityCountScore =
                Math.Abs(
                    totalA -
                    totalB) /
                Math.Max(
                    1.0,
                    Math.Max(
                        totalA,
                        totalB));

            return
                Math.Min(
                    1.0,
                    countScore *
                        0.55 +
                    entityCountScore *
                        0.20 +
                    topologyPenalty);
        }

        private string BuildSmartBlockRasterSignature(
            Transaction tr,
            BlockReference br)
        {
            if (tr == null ||
                br == null)
            {
                return "";
            }

            try
            {
                using (System.Drawing.Bitmap bitmap =
                    CreateSmartLegendPreviewBitmap(
                        tr,
                        new List<ObjectId>
                        {
                            br.ObjectId
                        },
                        96,
                        96))
                {
                    return
                        BuildSmartRasterSignature(
                            bitmap);
                }
            }
            catch
            {
                return "";
            }
        }

        private bool TryMatchSmartBlockByRaster(
            Transaction tr,
            BlockReference br,
            List<SmartSymbolRule> rasterRules,
            out SmartSymbolRule bestRule,
            out double bestScore,
            out string candidateSignature)
        {
            bestRule =
                null;

            bestScore =
                double.MaxValue;

            candidateSignature =
                "";

            if (tr == null ||
                br == null ||
                rasterRules == null ||
                rasterRules.Count == 0)
            {
                return false;
            }

            using (System.Drawing.Bitmap bitmap =
                CreateSmartLegendPreviewBitmap(
                    tr,
                    new List<ObjectId>
                    {
                        br.ObjectId
                    },
                    96,
                    96))
            {
                candidateSignature =
                    BuildSmartRasterSignature(
                        bitmap);
            }

            if (string.IsNullOrWhiteSpace(
                    candidateSignature))
            {
                return false;
            }

            string candidateGeometry =
                BuildSmartBlockGeometryFingerprint(
                    tr,
                    br);

            List<SmartVisionCandidateScore> scores =
                new List<SmartVisionCandidateScore>();

            foreach (SmartSymbolRule rule
                in rasterRules)
            {
                if (rule == null ||
                    string.IsNullOrWhiteSpace(
                        rule.RasterSignature) ||
                    string.IsNullOrWhiteSpace(
                        rule.DisplayName))
                {
                    continue;
                }

                double rasterScore =
                    CompareSmartRasterSignatures(
                        rule.RasterSignature,
                        candidateSignature);

                if (rasterScore >=
                        double.MaxValue ||
                    double.IsNaN(
                        rasterScore) ||
                    double.IsInfinity(
                        rasterScore))
                {
                    continue;
                }

                double structureScore =
                    double.MaxValue;

                if (!string.IsNullOrWhiteSpace(
                        candidateGeometry) &&
                    !string.IsNullOrWhiteSpace(
                        rule.GeometryFingerprint))
                {
                    structureScore =
                        CompareSmartGeometryStructureRelaxed(
                            rule.GeometryFingerprint,
                            candidateGeometry);
                }

                // Hình học khác loại rõ rệt => không cho raster "cứ gần nhất là thắng".
                if (structureScore <
                        double.MaxValue &&
                    structureScore >
                        0.58)
                {
                    continue;
                }

                double combinedScore =
                    structureScore <
                        double.MaxValue
                        ? rasterScore *
                              0.72 +
                          structureScore *
                              0.28
                        : rasterScore +
                          0.018;

                scores.Add(
                    new SmartVisionCandidateScore
                    {
                        Rule =
                            rule,
                        RasterScore =
                            rasterScore,
                        StructureScore =
                            structureScore,
                        CombinedScore =
                            combinedScore
                    });
            }

            if (scores.Count == 0)
                return false;

            List<SmartVisionCandidateScore> ranked =
                scores
                    .GroupBy(
                        x =>
                            x.Rule.DisplayName,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(
                        g =>
                            g.OrderBy(
                                 x =>
                                     x.CombinedScore)
                             .ThenBy(
                                 x =>
                                     x.RasterScore)
                             .First())
                    .OrderBy(
                        x =>
                            x.CombinedScore)
                    .ThenBy(
                        x =>
                            x.RasterScore)
                    .ToList();

            SmartVisionCandidateScore best =
                ranked[0];

            bestRule =
                best.Rule;

            bestScore =
                best.RasterScore;

            bool acceptableRaster =
                best.RasterScore <=
                0.115;

            bool structureGood =
                best.StructureScore >=
                    double.MaxValue ||
                best.StructureScore <=
                    0.36;

            if (!acceptableRaster ||
                !structureGood ||
                best.CombinedScore >
                    0.165)
            {
                bestRule =
                    null;

                return false;
            }

            if (ranked.Count > 1)
            {
                SmartVisionCandidateScore second =
                    ranked[1];

                double combinedMargin =
                    second.CombinedScore -
                    best.CombinedScore;

                double rasterMargin =
                    second.RasterScore -
                    best.RasterScore;

                bool exceptional =
                    best.RasterScore <=
                        0.095 &&
                    best.StructureScore <
                        double.MaxValue &&
                    best.StructureScore <=
                        0.20 &&
                    combinedMargin >=
                        0.018;

                if (combinedMargin <
                        0.032 &&
                    rasterMargin <
                        0.030 &&
                    !exceptional)
                {
                    // Mơ hồ: trả về UNKNOWN, không nhận bừa.
                    bestRule =
                        null;

                    return false;
                }
            }

            return true;
        }


        private System.Drawing.Bitmap CreateSmartLegendPreviewBitmap(
            Transaction tr,
            List<ObjectId> ids,
            int width,
            int height)
        {
            System.Drawing.Bitmap bitmap =
                new System.Drawing.Bitmap(
                    Math.Max(
                        width,
                        40),
                    Math.Max(
                        height,
                        30));

            using (System.Drawing.Graphics g =
                System.Drawing.Graphics.FromImage(
                    bitmap))
            {
                // STEP18F: nền gần giống AutoCAD để Yellow/Cyan/Green/Red đều nhìn đúng.
                g.Clear(
                    System.Drawing.Color.FromArgb(
                        31,
                        42,
                        52));

                g.SmoothingMode =
                    System.Drawing.Drawing2D.SmoothingMode.AntiAlias;

                List<DBObject> explodedObjects =
                    new List<DBObject>();

                List<SmartPreviewDrawItem> drawItems =
                    new List<SmartPreviewDrawItem>();

                Extents3d overall =
                    default(Extents3d);

                bool hasExtents =
                    false;

                foreach (ObjectId id
                    in ids ??
                    new List<ObjectId>())
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased)
                    {
                        continue;
                    }

                    if (ent is BlockReference br)
                    {
                        DBObjectCollection exploded =
                            new DBObjectCollection();

                        try
                        {
                            br.Explode(
                                exploded);

                            foreach (DBObject obj
                                in exploded)
                            {
                                explodedObjects.Add(
                                    obj);

                                if (obj is Entity child)
                                {
                                    drawItems.Add(
                                        new SmartPreviewDrawItem
                                        {
                                            Entity =
                                                child,
                                            ParentBlock =
                                                br,
                                            Color =
                                                ResolveSmartPreviewEntityColor(
                                                    tr,
                                                    child,
                                                    br)
                                        });
                                }
                            }
                        }
                        catch
                        {
                            drawItems.Add(
                                new SmartPreviewDrawItem
                                {
                                    Entity =
                                        ent,
                                    ParentBlock =
                                        br,
                                    Color =
                                        ResolveSmartPreviewEntityColor(
                                            tr,
                                            ent,
                                            br)
                                });
                        }
                    }
                    else
                    {
                        drawItems.Add(
                            new SmartPreviewDrawItem
                            {
                                Entity =
                                    ent,
                                ParentBlock =
                                    null,
                                Color =
                                    ResolveSmartPreviewEntityColor(
                                        tr,
                                        ent,
                                        null)
                            });
                    }
                }

                foreach (SmartPreviewDrawItem item
                    in drawItems)
                {
                    Entity ent =
                        item?.Entity;

                    if (ent == null)
                        continue;

                    try
                    {
                        Extents3d ex =
                            ent.GeometricExtents;

                        if (!hasExtents)
                        {
                            overall =
                                ex;

                            hasExtents =
                                true;
                        }
                        else
                        {
                            overall.AddExtents(
                                ex);
                        }
                    }
                    catch
                    {
                    }
                }

                if (!hasExtents)
                {
                    using (System.Drawing.Font font =
                        new System.Drawing.Font(
                            "Segoe UI",
                            9.0f))
                    {
                        g.DrawString(
                            "KÝ HIỆU",
                            font,
                            System.Drawing.Brushes.White,
                            8.0f,
                            18.0f);
                    }
                }
                else
                {
                    double dx =
                        Math.Max(
                            overall.MaxPoint.X -
                            overall.MinPoint.X,
                            1.0);

                    double dy =
                        Math.Max(
                            overall.MaxPoint.Y -
                            overall.MinPoint.Y,
                            1.0);

                    double margin =
                        6.0;

                    double sx =
                        (bitmap.Width -
                         margin * 2.0) /
                        dx;

                    double sy =
                        (bitmap.Height -
                         margin * 2.0) /
                        dy;

                    double scale =
                        Math.Min(
                            sx,
                            sy);

                    if (double.IsNaN(
                            scale) ||
                        double.IsInfinity(
                            scale) ||
                        scale <= 0.0)
                    {
                        scale =
                            1.0;
                    }

                    Func<Point3d, System.Drawing.PointF> map =
                        p =>
                        {
                            float x =
                                (float)(
                                    margin +
                                    (p.X -
                                     overall.MinPoint.X) *
                                    scale);

                            float y =
                                (float)(
                                    bitmap.Height -
                                    margin -
                                    (p.Y -
                                     overall.MinPoint.Y) *
                                    scale);

                            return
                                new System.Drawing.PointF(
                                    x,
                                    y);
                        };

                    foreach (SmartPreviewDrawItem item
                        in drawItems)
                    {
                        Entity ent =
                            item?.Entity;

                        if (ent == null)
                            continue;

                        System.Drawing.Color color =
                            item.Color;

                        if (color.A == 0)
                        {
                            color =
                                System.Drawing.Color.White;
                        }

                        using (System.Drawing.Pen pen =
                            new System.Drawing.Pen(
                                color,
                                1.8f))
                        using (System.Drawing.Brush brush =
                            new System.Drawing.SolidBrush(
                                color))
                        {
                            try
                            {
                                if (ent is Line line)
                                {
                                    g.DrawLine(
                                        pen,
                                        map(
                                            line.StartPoint),
                                        map(
                                            line.EndPoint));
                                }
                                else if (ent is Circle circle)
                                {
                                    Point3d min =
                                        new Point3d(
                                            circle.Center.X -
                                            circle.Radius,
                                            circle.Center.Y -
                                            circle.Radius,
                                            0.0);

                                    Point3d max =
                                        new Point3d(
                                            circle.Center.X +
                                            circle.Radius,
                                            circle.Center.Y +
                                            circle.Radius,
                                            0.0);

                                    System.Drawing.PointF p1 =
                                        map(
                                            min);

                                    System.Drawing.PointF p2 =
                                        map(
                                            max);

                                    g.DrawEllipse(
                                        pen,
                                        Math.Min(
                                            p1.X,
                                            p2.X),
                                        Math.Min(
                                            p1.Y,
                                            p2.Y),
                                        Math.Abs(
                                            p2.X -
                                            p1.X),
                                        Math.Abs(
                                            p2.Y -
                                            p1.Y));
                                }
                                else if (ent is Arc arc)
                                {
                                    List<System.Drawing.PointF> pts =
                                        new List<System.Drawing.PointF>();

                                    int n =
                                        32;

                                    double sweep =
                                        arc.EndAngle -
                                        arc.StartAngle;

                                    if (sweep < 0.0)
                                    {
                                        sweep +=
                                            Math.PI *
                                            2.0;
                                    }

                                    for (int i = 0;
                                        i <= n;
                                        i++)
                                    {
                                        double t =
                                            arc.StartAngle +
                                            sweep *
                                            i /
                                            n;

                                        Point3d p =
                                            new Point3d(
                                                arc.Center.X +
                                                arc.Radius *
                                                Math.Cos(
                                                    t),
                                                arc.Center.Y +
                                                arc.Radius *
                                                Math.Sin(
                                                    t),
                                                0.0);

                                        pts.Add(
                                            map(
                                                p));
                                    }

                                    if (pts.Count >= 2)
                                    {
                                        g.DrawLines(
                                            pen,
                                            pts.ToArray());
                                    }
                                }
                                else if (ent is Polyline pl)
                                {
                                    // Sample theo chiều dài để giữ đúng bulge/curve,
                                    // không nối thẳng vertex như preview cũ.
                                    List<System.Drawing.PointF> pts =
                                        new List<System.Drawing.PointF>();

                                    double length =
                                        GetAiPipeCurveLength(
                                            pl);

                                    int n =
                                        Math.Max(
                                            12,
                                            Math.Min(
                                                64,
                                                pl.NumberOfVertices *
                                                12));

                                    if (length > 1e-6)
                                    {
                                        for (int i = 0;
                                            i <= n;
                                            i++)
                                        {
                                            try
                                            {
                                                Point3d p =
                                                    pl.GetPointAtDist(
                                                        length *
                                                        i /
                                                        n);

                                                pts.Add(
                                                    map(
                                                        p));
                                            }
                                            catch
                                            {
                                            }
                                        }
                                    }

                                    if (pts.Count >= 2)
                                    {
                                        g.DrawLines(
                                            pen,
                                            pts.ToArray());
                                    }
                                }
                                else if (ent is Solid solid)
                                {
                                    System.Drawing.PointF[] pts =
                                        new System.Drawing.PointF[]
                                        {
                                            map(
                                                solid.GetPointAt(
                                                    0)),
                                            map(
                                                solid.GetPointAt(
                                                    1)),
                                            map(
                                                solid.GetPointAt(
                                                    3)),
                                            map(
                                                solid.GetPointAt(
                                                    2))
                                        };

                                    g.FillPolygon(
                                        brush,
                                        pts);
                                }
                                else if (ent is DBPoint point)
                                {
                                    System.Drawing.PointF p =
                                        map(
                                            point.Position);

                                    DrawSmartPreviewDbPoint(
                                        g,
                                        pen,
                                        brush,
                                        p);
                                }
                                else if (ent is DBText dbText)
                                {
                                    using (System.Drawing.Font font =
                                        new System.Drawing.Font(
                                            "Segoe UI",
                                            7.5f,
                                            System.Drawing.FontStyle.Regular))
                                    {
                                        g.DrawString(
                                            dbText.TextString ??
                                            "",
                                            font,
                                            brush,
                                            map(
                                                dbText.Position));
                                    }
                                }
                                else if (ent is MText mText)
                                {
                                    using (System.Drawing.Font font =
                                        new System.Drawing.Font(
                                            "Segoe UI",
                                            7.5f,
                                            System.Drawing.FontStyle.Regular))
                                    {
                                        g.DrawString(
                                            mText.Text ??
                                            "",
                                            font,
                                            brush,
                                            map(
                                                mText.Location));
                                    }
                                }
                                else
                                {
                                    Extents3d ex =
                                        ent.GeometricExtents;

                                    System.Drawing.PointF p1 =
                                        map(
                                            ex.MinPoint);

                                    System.Drawing.PointF p2 =
                                        map(
                                            ex.MaxPoint);

                                    g.DrawRectangle(
                                        pen,
                                        Math.Min(
                                            p1.X,
                                            p2.X),
                                        Math.Min(
                                            p1.Y,
                                            p2.Y),
                                        Math.Abs(
                                            p2.X -
                                            p1.X),
                                        Math.Abs(
                                            p2.Y -
                                            p1.Y));
                                }
                            }
                            catch
                            {
                            }
                        }
                    }
                }

                foreach (DBObject obj
                    in explodedObjects)
                {
                    try
                    {
                        obj.Dispose();
                    }
                    catch
                    {
                    }
                }
            }

            return
                bitmap;
        }

        private void DrawSmartPreviewDbPoint(
            System.Drawing.Graphics g,
            System.Drawing.Pen pen,
            System.Drawing.Brush brush,
            System.Drawing.PointF p)
        {
            if (g == null ||
                pen == null ||
                brush == null)
            {
                return;
            }

            int pdMode =
                0;

            try
            {
                object raw =
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .GetSystemVariable(
                            "PDMODE");

                if (raw != null)
                {
                    int.TryParse(
                        Convert.ToString(
                            raw,
                            CultureInfo.InvariantCulture),
                        out pdMode);
                }
            }
            catch
            {
            }

            // Dot ở tâm.
            g.FillEllipse(
                brush,
                p.X - 2.6f,
                p.Y - 2.6f,
                5.2f,
                5.2f);

            // PDMODE >= 32 thường có vòng ngoài/square component.
            // Preview ưu tiên trực quan giống symbol trên CAD hơn là mô phỏng 100% bitmask.
            if (pdMode >= 32)
            {
                g.DrawEllipse(
                    pen,
                    p.X - 15.0f,
                    p.Y - 15.0f,
                    30.0f,
                    30.0f);
            }

            // Một số point-style có cross/X. Chỉ thêm khi mode khác kiểu dot thuần.
            if (pdMode != 0 &&
                pdMode != 32)
            {
                g.DrawLine(
                    pen,
                    p.X - 10.0f,
                    p.Y,
                    p.X + 10.0f,
                    p.Y);

                g.DrawLine(
                    pen,
                    p.X,
                    p.Y - 10.0f,
                    p.X,
                    p.Y + 10.0f);
            }
        }

        private System.Drawing.Color ResolveSmartPreviewEntityColor(
            Transaction tr,
            Entity ent,
            BlockReference parentBlock)
        {
            if (ent == null)
            {
                return
                    System.Drawing.Color.White;
            }

            try
            {
                // BYBLOCK
                if (ent.ColorIndex == 0)
                {
                    if (parentBlock != null)
                    {
                        if (parentBlock.ColorIndex != 0 &&
                            parentBlock.ColorIndex != 256)
                        {
                            return
                                parentBlock.Color.ColorValue;
                        }

                        return
                            ResolveSmartPreviewLayerColor(
                                tr,
                                parentBlock.Layer);
                    }

                    return
                        System.Drawing.Color.White;
                }

                // BYLAYER
                if (ent.ColorIndex == 256)
                {
                    string layerName =
                        ent.Layer;

                    // Entity bên trong block ở Layer 0 hiển thị theo layer insertion.
                    if (parentBlock != null &&
                        string.Equals(
                            layerName,
                            "0",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        layerName =
                            parentBlock.Layer;
                    }

                    return
                        ResolveSmartPreviewLayerColor(
                            tr,
                            layerName);
                }

                return
                    ent.Color.ColorValue;
            }
            catch
            {
                return
                    System.Drawing.Color.White;
            }
        }

        private System.Drawing.Color ResolveSmartPreviewLayerColor(
            Transaction tr,
            string layerName)
        {
            if (tr == null ||
                string.IsNullOrWhiteSpace(
                    layerName))
            {
                return
                    System.Drawing.Color.White;
            }

            try
            {
                Document doc =
                    Autodesk.AutoCAD.ApplicationServices.Core.Application
                        .DocumentManager
                        .MdiActiveDocument;

                Database db =
                    doc?.Database;

                if (db == null)
                {
                    return
                        System.Drawing.Color.White;
                }

                LayerTable lt =
                    tr.GetObject(
                        db.LayerTableId,
                        OpenMode.ForRead,
                        false) as LayerTable;

                if (lt == null ||
                    !lt.Has(
                        layerName))
                {
                    return
                        System.Drawing.Color.White;
                }

                LayerTableRecord ltr =
                    tr.GetObject(
                        lt[layerName],
                        OpenMode.ForRead,
                        false) as LayerTableRecord;

                if (ltr == null)
                {
                    return
                        System.Drawing.Color.White;
                }

                return
                    ltr.Color.ColorValue;
            }
            catch
            {
                return
                    System.Drawing.Color.White;
            }
        }


        private int GetSmartMenuChoice(
            Editor ed,
            string message,
            int minValue,
            int maxValue,
            int defaultValue)
        {
            if (ed == null)
                return -1;

            PromptIntegerOptions options =
                new PromptIntegerOptions(
                    message +
                    " <" +
                    defaultValue +
                    ">: ");

            options.AllowNone =
                true;
            options.AllowNegative =
                false;
            options.AllowZero =
                false;
            options.LowerLimit =
                minValue;
            options.UpperLimit =
                maxValue;

            PromptIntegerResult result =
                ed.GetInteger(
                    options);

            if (result.Status ==
                PromptStatus.Cancel)
            {
                return -1;
            }

            if (result.Status ==
                PromptStatus.None)
            {
                return defaultValue;
            }

            if (result.Status !=
                PromptStatus.OK)
            {
                return -1;
            }

            return result.Value;
        }


        private void LearnSmartSymbolRules(
            Document doc,
            List<SmartSymbolRule> currentRules)
        {
            if (doc == null)
                return;

            Editor ed =
                doc.Editor;

            Database db =
                doc.Database;

            List<SmartSymbolRule> rules =
                currentRules != null
                    ? new List<SmartSymbolRule>(
                        currentRules)
                    : new List<SmartSymbolRule>();

            int learned =
                0;

            ed.WriteMessage(
                "\n[HỌC KÝ HIỆU] " +
                "Mỗi mẫu: chọn BLOCK ký hiệu trong LEGEND -> " +
                "chọn TEXT giải thích. Enter tại bước chọn block để kết thúc.");

            while (true)
            {
                PromptEntityOptions blockOptions =
                    new PromptEntityOptions(
                        "\nChọn BLOCK ký hiệu mẫu (Enter kết thúc): ");

                blockOptions.AllowNone =
                    true;

                blockOptions.SetRejectMessage(
                    "\nHãy chọn một BLOCK ký hiệu.");

                blockOptions.AddAllowedClass(
                    typeof(BlockReference),
                    false);

                _smartValveStage =
                    "LEARN_PICK_BLOCK";

                PromptEntityResult blockResult =
                    ed.GetEntity(
                        blockOptions);

                if (blockResult.Status ==
                    PromptStatus.None)
                {
                    break;
                }

                if (blockResult.Status ==
                    PromptStatus.Cancel)
                {
                    break;
                }

                if (blockResult.Status !=
                    PromptStatus.OK)
                {
                    continue;
                }

                string blockKey =
                    "";

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    BlockReference br =
                        tr.GetObject(
                            blockResult.ObjectId,
                            OpenMode.ForRead,
                            false) as BlockReference;

                    if (br != null)
                    {
                        blockKey =
                            GetShopStatBlockName(
                                tr,
                                br);
                    }

                    tr.Commit();
                }

                blockKey =
                    NormalizeSmartSymbolKey(
                        blockKey);

                if (string.IsNullOrWhiteSpace(
                        blockKey))
                {
                    MessageBox.Show(
                        "Không đọc được tên block mẫu.",
                        "HỌC KÝ HIỆU");
                    continue;
                }

                PromptEntityOptions textOptions =
                    new PromptEntityOptions(
                        "\nChọn TEXT/MTEXT giải thích tên ký hiệu: ");

                _smartValveStage =
                    "LEARN_PICK_TEXT";

                PromptEntityResult textResult =
                    ed.GetEntity(
                        textOptions);

                if (textResult.Status !=
                    PromptStatus.OK)
                {
                    continue;
                }

                string displayName =
                    "";

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    Entity labelEntity =
                        tr.GetObject(
                            textResult.ObjectId,
                            OpenMode.ForRead,
                            false) as Entity;

                    displayName =
                        GetSmartLegendText(
                            labelEntity);

                    tr.Commit();
                }

                displayName =
                    NormalizeSmartDisplayName(
                        displayName);

                if (string.IsNullOrWhiteSpace(
                        displayName))
                {
                    MessageBox.Show(
                        "Đối tượng vừa chọn không phải TEXT/MTEXT hợp lệ.",
                        "HỌC KÝ HIỆU");
                    continue;
                }

                _smartValveStage =
                    "LEARN_SIZE_RULE";

                int sizeRuleChoice =
                    GetSmartMenuChoice(
                        ed,
                        "\nSize của \"" +
                        displayName +
                        "\": 1=THEO ỐNG, 2=KHÔNG SIZE",
                        1,
                        2,
                        1);

                if (sizeRuleChoice <= 0)
                {
                    break;
                }

                string sizeRule =
                    sizeRuleChoice == 2
                        ? "KHONG_SIZE"
                        : "THEO_ONG";

                SmartSymbolRule existing =
                    rules.FirstOrDefault(
                        x =>
                            string.Equals(
                                x.BlockKey,
                                blockKey,
                                StringComparison.OrdinalIgnoreCase));

                if (existing == null)
                {
                    rules.Add(
                        new SmartSymbolRule
                        {
                            BlockKey =
                                blockKey,
                            DisplayName =
                                displayName,
                            SizeRule =
                                sizeRule,
                            MatchMode =
                                "BLOCK",
                            GeometryFingerprint =
                                ""
                        });
                }
                else
                {
                    existing.DisplayName =
                        displayName;
                    existing.SizeRule =
                        sizeRule;
                    existing.MatchMode =
                        "BLOCK";
                    existing.GeometryFingerprint =
                        "";
                }

                learned++;

                ed.WriteMessage(
                    "\nĐã học: " +
                    displayName +
                    " | Block=" +
                    blockKey +
                    " | " +
                    (sizeRule == "THEO_ONG"
                        ? "Size theo ống"
                        : "Không lấy size"));
            }

            if (learned <= 0)
                return;

            _smartValveStage =
                "LEARN_SAVE_LIBRARY";

            SaveSmartSymbolRules(
                rules);

            LearnAiFromSymbolRules(
                rules,
                "MANUAL_BLOCK_LEARN");

            MessageBox.Show(
                "Đã lưu " +
                learned +
                " ký hiệu.\n\n" +
                "Tổng thư viện hiện có: " +
                rules.Count +
                " ký hiệu.\n" +
                "Các lần sau không cần học lại nếu bản vẽ dùng cùng block.",
                "HỌC KÝ HIỆU");
        }

        private void LearnSmartExplodedGeometryRules(
            Document doc,
            List<SmartSymbolRule> currentRules)
        {
            if (doc == null)
                return;

            Editor ed =
                doc.Editor;

            Database db =
                doc.Database;

            List<SmartSymbolRule> rules =
                currentRules != null
                    ? new List<SmartSymbolRule>(
                        currentRules)
                    : new List<SmartSymbolRule>();

            int learned =
                0;

            ed.WriteMessage(
                "\n[HỌC HÌNH EXPLODE] " +
                "Quét CHÍNH XÁC các nét Line/Arc/Circle/Polyline của 1 ký hiệu trong LEGEND. " +
                "Không quét text giải thích và không quét đường khung bảng.");

            while (true)
            {
                _smartValveStage =
                    "GEO_LEARN_SELECT_SYMBOL";

                PromptSelectionOptions symbolOptions =
                    new PromptSelectionOptions();

                symbolOptions.MessageForAdding =
                    "\nQuét các nét của 1 ký hiệu EXPLODE (ESC kết thúc): ";

                PromptSelectionResult symbolResult =
                    ed.GetSelection(
                        symbolOptions);

                if (symbolResult.Status ==
                    PromptStatus.Cancel)
                {
                    break;
                }

                if (symbolResult.Status !=
                        PromptStatus.OK ||
                    symbolResult.Value == null ||
                    symbolResult.Value.Count == 0)
                {
                    break;
                }

                string fingerprint =
                    "";

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    List<ObjectId> ids =
                        symbolResult.Value
                            .GetObjectIds()
                            .ToList();

                    fingerprint =
                        BuildSmartGeometryFingerprint(
                            tr,
                            ids);

                    tr.Commit();
                }

                if (string.IsNullOrWhiteSpace(
                        fingerprint))
                {
                    MessageBox.Show(
                        "Không tạo được dấu vân tay hình học.\n\n" +
                        "Chỉ quét các nét LINE / ARC / CIRCLE / POLYLINE của ký hiệu.",
                        "HỌC HÌNH EXPLODE");
                    continue;
                }

                _smartValveStage =
                    "GEO_LEARN_PICK_TEXT";

                PromptEntityOptions textOptions =
                    new PromptEntityOptions(
                        "\nChọn TEXT/MTEXT giải thích tên ký hiệu: ");

                PromptEntityResult textResult =
                    ed.GetEntity(
                        textOptions);

                if (textResult.Status !=
                    PromptStatus.OK)
                {
                    continue;
                }

                string displayName =
                    "";

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    Entity labelEntity =
                        tr.GetObject(
                            textResult.ObjectId,
                            OpenMode.ForRead,
                            false) as Entity;

                    displayName =
                        NormalizeSmartDisplayName(
                            GetSmartLegendText(
                                labelEntity));

                    tr.Commit();
                }

                if (string.IsNullOrWhiteSpace(
                        displayName))
                {
                    MessageBox.Show(
                        "Không đọc được tên ký hiệu từ TEXT/MTEXT.",
                        "HỌC HÌNH EXPLODE");
                    continue;
                }

                _smartValveStage =
                    "GEO_LEARN_SIZE_RULE";

                int sizeRuleChoice =
                    GetSmartMenuChoice(
                        ed,
                        "\nSize của \"" +
                        displayName +
                        "\": 1=THEO ỐNG, 2=KHÔNG SIZE",
                        1,
                        2,
                        1);

                if (sizeRuleChoice <= 0)
                    break;

                string sizeRule =
                    sizeRuleChoice == 2
                        ? "KHONG_SIZE"
                        : "THEO_ONG";

                string geometryKey =
                    "GEO_" +
                    Convert.ToBase64String(
                        Encoding.UTF8.GetBytes(
                            fingerprint));

                SmartSymbolRule existing =
                    rules.FirstOrDefault(
                        x =>
                            string.Equals(
                                x.MatchMode,
                                "GEOMETRY",
                                StringComparison.OrdinalIgnoreCase) &&
                            string.Equals(
                                x.GeometryFingerprint,
                                fingerprint,
                                StringComparison.Ordinal));

                if (existing == null)
                {
                    rules.Add(
                        new SmartSymbolRule
                        {
                            BlockKey =
                                geometryKey,
                            DisplayName =
                                displayName,
                            SizeRule =
                                sizeRule,
                            MatchMode =
                                "GEOMETRY",
                            GeometryFingerprint =
                                fingerprint
                        });
                }
                else
                {
                    existing.DisplayName =
                        displayName;
                    existing.SizeRule =
                        sizeRule;
                }

                learned++;

                ed.WriteMessage(
                    "\nĐã học HÌNH: " +
                    displayName +
                    " | " +
                    GetSmartGeometryFingerprintSummary(
                        fingerprint));
            }

            if (learned <= 0)
                return;

            _smartValveStage =
                "GEO_LEARN_SAVE_LIBRARY";

            SaveSmartSymbolRules(
                rules);

            LearnAiFromSymbolRules(
                rules,
                "MANUAL_GEOMETRY_LEARN");

            MessageBox.Show(
                "Đã lưu " +
                learned +
                " mẫu hình học EXPLODE.\n\n" +
                "Tool so sánh theo số lượng loại nét + tỷ lệ chiều dài + " +
                "khoảng cách tương đối giữa các nét, nên có thể nhận khi ký hiệu xoay hoặc scale nhẹ.",
                "HỌC HÌNH EXPLODE");
        }

        private string BuildSmartGenericLegendFingerprint(
            Transaction tr,
            List<ObjectId> ids)
        {
            if (tr == null ||
                ids == null ||
                ids.Count == 0)
            {
                return "";
            }

            List<Tuple<string, double, double, Point3d>> items =
                new List<Tuple<string, double, double, Point3d>>();

            foreach (ObjectId id
                in ids)
            {
                if (id.IsNull ||
                    !id.IsValid)
                {
                    continue;
                }

                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent == null ||
                    ent.IsErased)
                {
                    continue;
                }

                try
                {
                    Extents3d ex =
                        ent.GeometricExtents;

                    double dx =
                        Math.Abs(
                            ex.MaxPoint.X -
                            ex.MinPoint.X);

                    double dy =
                        Math.Abs(
                            ex.MaxPoint.Y -
                            ex.MinPoint.Y);

                    double maxSpan =
                        Math.Max(
                            Math.Max(
                                dx,
                                dy),
                            1e-6);

                    double minSpan =
                        Math.Min(
                            dx,
                            dy);

                    double aspect =
                        minSpan /
                        maxSpan;

                    string dxf =
                        ent.GetRXClass()?.DxfName ??
                        ent.GetType().Name;

                    Point3d center =
                        new Point3d(
                            (ex.MinPoint.X +
                             ex.MaxPoint.X) * 0.5,
                            (ex.MinPoint.Y +
                             ex.MaxPoint.Y) * 0.5,
                            0.0);

                    items.Add(
                        Tuple.Create(
                            dxf.ToUpperInvariant(),
                            maxSpan,
                            aspect,
                            center));
                }
                catch
                {
                }
            }

            if (items.Count == 0)
                return "";

            double globalSpan =
                items.Max(
                    x =>
                        x.Item2);

            if (globalSpan <= 1e-9)
                globalSpan = 1.0;

            List<string> entityTokens =
                items
                    .Select(
                        x =>
                            x.Item1 +
                            ":" +
                            Math.Round(
                                x.Item2 /
                                globalSpan,
                                2)
                                .ToString(
                                    "0.00",
                                    CultureInfo.InvariantCulture) +
                            ":" +
                            Math.Round(
                                x.Item3,
                                2)
                                .ToString(
                                    "0.00",
                                    CultureInfo.InvariantCulture))
                    .OrderBy(
                        x =>
                            x)
                    .ToList();

            List<double> pairDistances =
                new List<double>();

            for (int i = 0;
                i < items.Count;
                i++)
            {
                for (int j = i + 1;
                    j < items.Count;
                    j++)
                {
                    pairDistances.Add(
                        PlanDistance(
                            items[i].Item4,
                            items[j].Item4));
                }
            }

            string distanceToken =
                "";

            if (pairDistances.Count > 0)
            {
                double maxPair =
                    pairDistances.Max();

                if (maxPair <= 1e-9)
                    maxPair = 1.0;

                distanceToken =
                    string.Join(
                        ",",
                        pairDistances
                            .Select(
                                d =>
                                    Math.Round(
                                        d /
                                        maxPair,
                                        2)
                                        .ToString(
                                            "0.00",
                                            CultureInfo.InvariantCulture))
                            .OrderBy(
                                x =>
                                    x));
            }

            return
                "GENERIC|N=" +
                items.Count.ToString(
                    CultureInfo.InvariantCulture) +
                "|E=" +
                string.Join(
                    ",",
                    entityTokens) +
                "|D=" +
                distanceToken;
        }

        private string GetSmartGenericLegendSummary(
            Transaction tr,
            List<ObjectId> ids)
        {
            if (tr == null ||
                ids == null)
            {
                return "";
            }

            List<string> types =
                new List<string>();

            foreach (ObjectId id
                in ids)
            {
                try
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null)
                        continue;

                    string dxf =
                        ent.GetRXClass()?.DxfName ??
                        ent.GetType().Name;

                    types.Add(
                        dxf);
                }
                catch
                {
                }
            }

            return
                string.Join(
                    " + ",
                    types
                        .Distinct(
                            StringComparer.OrdinalIgnoreCase)
                        .OrderBy(
                            x =>
                                x));
        }

        private string BuildSmartGeometryFingerprint(
            Transaction tr,
            List<ObjectId> ids)
        {
            if (tr == null ||
                ids == null ||
                ids.Count == 0)
            {
                return "";
            }

            SmartGeometryFingerprintData data =
                new SmartGeometryFingerprintData();

            List<double> lengths =
                new List<double>();

            List<Point3d> centers =
                new List<Point3d>();

            foreach (ObjectId id in ids)
            {
                if (id.IsNull ||
                    !id.IsValid)
                {
                    continue;
                }

                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent == null ||
                    ent.IsErased)
                {
                    continue;
                }

                if (!(ent is Curve curve))
                    continue;

                if (ent is Line)
                    data.LineCount++;
                else if (ent is Arc)
                    data.ArcCount++;
                else if (ent is Circle)
                    data.CircleCount++;
                else if (ent is Polyline)
                    data.PolylineCount++;
                else
                    continue;

                double length =
                    LayChieuDaiCurveThongKe(
                        curve);

                if (length <= 1e-6)
                {
                    try
                    {
                        Extents3d ex =
                            ent.GeometricExtents;

                        length =
                            ex.MinPoint.DistanceTo(
                                ex.MaxPoint);
                    }
                    catch
                    {
                        length = 1.0;
                    }
                }

                lengths.Add(
                    Math.Max(
                        length,
                        1e-6));

                try
                {
                    Extents3d ex =
                        ent.GeometricExtents;

                    centers.Add(
                        new Point3d(
                            (ex.MinPoint.X +
                             ex.MaxPoint.X) * 0.5,
                            (ex.MinPoint.Y +
                             ex.MaxPoint.Y) * 0.5,
                            0.0));
                }
                catch
                {
                    try
                    {
                        centers.Add(
                            LayDiemDaiDien(
                                ent));
                    }
                    catch
                    {
                    }
                }
            }

            int entityCount =
                data.LineCount +
                data.ArcCount +
                data.CircleCount +
                data.PolylineCount;

            if (entityCount <= 0 ||
                lengths.Count != entityCount)
            {
                return "";
            }

            double maxLength =
                lengths.Max();

            if (maxLength <= 1e-9)
                maxLength = 1.0;

            data.LengthRatios =
                lengths
                    .Select(
                        x =>
                            Math.Round(
                                x / maxLength,
                                3))
                    .OrderBy(
                        x =>
                            x)
                    .ToList();

            List<double> pairDistances =
                new List<double>();

            for (int i = 0;
                i < centers.Count;
                i++)
            {
                for (int j = i + 1;
                    j < centers.Count;
                    j++)
                {
                    pairDistances.Add(
                        PlanDistance(
                            centers[i],
                            centers[j]));
                }
            }

            if (pairDistances.Count > 0)
            {
                double maxPair =
                    pairDistances.Max();

                if (maxPair <= 1e-9)
                    maxPair = 1.0;

                data.PairDistanceRatios =
                    pairDistances
                        .Select(
                            x =>
                                Math.Round(
                                    x / maxPair,
                                    3))
                        .OrderBy(
                            x =>
                                x)
                        .ToList();
            }

            return
                SerializeSmartGeometryFingerprint(
                    data);
        }

        private string BuildSmartBlockGeometryFingerprint(
            Transaction tr,
            BlockReference br)
        {
            if (tr == null ||
                br == null)
            {
                return "";
            }

            DBObjectCollection exploded =
                new DBObjectCollection();

            List<Entity> entities =
                new List<Entity>();

            try
            {
                br.Explode(
                    exploded);

                foreach (DBObject obj
                    in exploded)
                {
                    if (obj is Entity ent)
                    {
                        entities.Add(
                            ent);
                    }
                }

                return
                    BuildSmartGeometryFingerprintFromEntities(
                        entities);
            }
            catch
            {
                return "";
            }
            finally
            {
                foreach (DBObject obj
                    in exploded)
                {
                    try
                    {
                        obj.Dispose();
                    }
                    catch
                    {
                    }
                }
            }
        }

        private string BuildSmartGeometryFingerprintFromEntities(
            IEnumerable<Entity> entities)
        {
            SmartGeometryFingerprintData data =
                new SmartGeometryFingerprintData();

            List<double> lengths =
                new List<double>();

            List<Point3d> centers =
                new List<Point3d>();

            foreach (Entity ent
                in entities ??
                Enumerable.Empty<Entity>())
            {
                if (ent == null)
                    continue;

                if (!(ent is Curve curve))
                    continue;

                if (ent is Line)
                    data.LineCount++;
                else if (ent is Arc)
                    data.ArcCount++;
                else if (ent is Circle)
                    data.CircleCount++;
                else if (ent is Polyline)
                    data.PolylineCount++;
                else
                    continue;

                double length =
                    0.0;

                try
                {
                    length =
                        LayChieuDaiCurveThongKe(
                            curve);
                }
                catch
                {
                }

                if (length <= 1e-6)
                {
                    try
                    {
                        Extents3d ex =
                            ent.GeometricExtents;

                        length =
                            ex.MinPoint.DistanceTo(
                                ex.MaxPoint);
                    }
                    catch
                    {
                        length =
                            1.0;
                    }
                }

                lengths.Add(
                    Math.Max(
                        length,
                        1e-6));

                try
                {
                    Extents3d ex =
                        ent.GeometricExtents;

                    centers.Add(
                        new Point3d(
                            (ex.MinPoint.X +
                             ex.MaxPoint.X) * 0.5,
                            (ex.MinPoint.Y +
                             ex.MaxPoint.Y) * 0.5,
                            0.0));
                }
                catch
                {
                }
            }

            int entityCount =
                data.LineCount +
                data.ArcCount +
                data.CircleCount +
                data.PolylineCount;

            if (entityCount <= 0 ||
                lengths.Count !=
                    entityCount)
            {
                return "";
            }

            double maxLength =
                lengths.Max();

            if (maxLength <= 1e-9)
                maxLength = 1.0;

            data.LengthRatios =
                lengths
                    .Select(
                        x =>
                            Math.Round(
                                x / maxLength,
                                3))
                    .OrderBy(
                        x =>
                            x)
                    .ToList();

            List<double> pairDistances =
                new List<double>();

            for (int i = 0;
                i < centers.Count;
                i++)
            {
                for (int j = i + 1;
                    j < centers.Count;
                    j++)
                {
                    pairDistances.Add(
                        PlanDistance(
                            centers[i],
                            centers[j]));
                }
            }

            if (pairDistances.Count > 0)
            {
                double maxPair =
                    pairDistances.Max();

                if (maxPair <= 1e-9)
                    maxPair = 1.0;

                data.PairDistanceRatios =
                    pairDistances
                        .Select(
                            x =>
                                Math.Round(
                                    x / maxPair,
                                    3))
                        .OrderBy(
                            x =>
                                x)
                        .ToList();
            }

            return
                SerializeSmartGeometryFingerprint(
                    data);
        }

        private static string SerializeSmartGeometryFingerprint(
            SmartGeometryFingerprintData data)
        {
            if (data == null)
                return "";

            string lengths =
                string.Join(
                    ",",
                    data.LengthRatios.Select(
                        x =>
                            x.ToString(
                                "0.000",
                                CultureInfo.InvariantCulture)));

            string distances =
                string.Join(
                    ",",
                    data.PairDistanceRatios.Select(
                        x =>
                            x.ToString(
                                "0.000",
                                CultureInfo.InvariantCulture)));

            return
                "L=" +
                data.LineCount +
                ";A=" +
                data.ArcCount +
                ";C=" +
                data.CircleCount +
                ";P=" +
                data.PolylineCount +
                ";R=" +
                lengths +
                ";D=" +
                distances;
        }

        private static bool TryParseSmartGeometryFingerprint(
            string value,
            out SmartGeometryFingerprintData data)
        {
            data =
                new SmartGeometryFingerprintData();

            if (string.IsNullOrWhiteSpace(
                    value))
            {
                return false;
            }

            try
            {
                string[] parts =
                    value.Split(';');

                foreach (string part in parts)
                {
                    if (part.StartsWith(
                            "L=",
                            StringComparison.Ordinal))
                    {
                        int.TryParse(
                            part.Substring(2),
                            out int n);
                        data.LineCount = n;
                    }
                    else if (part.StartsWith(
                                 "A=",
                                 StringComparison.Ordinal))
                    {
                        int.TryParse(
                            part.Substring(2),
                            out int n);
                        data.ArcCount = n;
                    }
                    else if (part.StartsWith(
                                 "C=",
                                 StringComparison.Ordinal))
                    {
                        int.TryParse(
                            part.Substring(2),
                            out int n);
                        data.CircleCount = n;
                    }
                    else if (part.StartsWith(
                                 "P=",
                                 StringComparison.Ordinal))
                    {
                        int.TryParse(
                            part.Substring(2),
                            out int n);
                        data.PolylineCount = n;
                    }
                    else if (part.StartsWith(
                                 "R=",
                                 StringComparison.Ordinal))
                    {
                        data.LengthRatios =
                            ParseSmartRatioList(
                                part.Substring(2));
                    }
                    else if (part.StartsWith(
                                 "D=",
                                 StringComparison.Ordinal))
                    {
                        data.PairDistanceRatios =
                            ParseSmartRatioList(
                                part.Substring(2));
                    }
                }

                int count =
                    data.LineCount +
                    data.ArcCount +
                    data.CircleCount +
                    data.PolylineCount;

                return
                    count > 0 &&
                    data.LengthRatios.Count ==
                    count;
            }
            catch
            {
                return false;
            }
        }

        private static List<double> ParseSmartRatioList(
            string value)
        {
            List<double> result =
                new List<double>();

            if (string.IsNullOrWhiteSpace(
                    value))
            {
                return result;
            }

            foreach (string token
                in value.Split(','))
            {
                if (double.TryParse(
                        token,
                        NumberStyles.Float,
                        CultureInfo.InvariantCulture,
                        out double number))
                {
                    result.Add(
                        number);
                }
            }

            return result;
        }

        private static double CompareSmartGeometryFingerprints(
            string learned,
            string candidate)
        {
            if (!TryParseSmartGeometryFingerprint(
                    learned,
                    out SmartGeometryFingerprintData a) ||
                !TryParseSmartGeometryFingerprint(
                    candidate,
                    out SmartGeometryFingerprintData b))
            {
                return double.MaxValue;
            }

            if (a.LineCount != b.LineCount ||
                a.ArcCount != b.ArcCount ||
                a.CircleCount != b.CircleCount ||
                a.PolylineCount != b.PolylineCount ||
                a.LengthRatios.Count !=
                    b.LengthRatios.Count ||
                a.PairDistanceRatios.Count !=
                    b.PairDistanceRatios.Count)
            {
                return double.MaxValue;
            }

            double lengthScore =
                0.0;

            for (int i = 0;
                i < a.LengthRatios.Count;
                i++)
            {
                lengthScore +=
                    Math.Abs(
                        a.LengthRatios[i] -
                        b.LengthRatios[i]);
            }

            if (a.LengthRatios.Count > 0)
            {
                lengthScore /=
                    a.LengthRatios.Count;
            }

            double distanceScore =
                0.0;

            for (int i = 0;
                i < a.PairDistanceRatios.Count;
                i++)
            {
                distanceScore +=
                    Math.Abs(
                        a.PairDistanceRatios[i] -
                        b.PairDistanceRatios[i]);
            }

            if (a.PairDistanceRatios.Count > 0)
            {
                distanceScore /=
                    a.PairDistanceRatios.Count;
            }

            return
                lengthScore * 0.55 +
                distanceScore * 0.45;
        }

        private static string GetSmartGeometryFingerprintSummary(
            string fingerprint)
        {
            if (!TryParseSmartGeometryFingerprint(
                    fingerprint,
                    out SmartGeometryFingerprintData data))
            {
                return "Fingerprint không hợp lệ";
            }

            return
                "Line=" +
                data.LineCount +
                ", Arc=" +
                data.ArcCount +
                ", Circle=" +
                data.CircleCount +
                ", Polyline=" +
                data.PolylineCount;
        }

        private bool TryMatchSmartBlockByGeometry(
            Transaction tr,
            BlockReference br,
            List<SmartSymbolRule> geometryRules,
            out SmartSymbolRule bestRule,
            out double bestScore)
        {
            bestRule =
                null;

            bestScore =
                double.MaxValue;

            if (tr == null ||
                br == null ||
                geometryRules == null ||
                geometryRules.Count == 0)
            {
                return false;
            }

            string candidateFingerprint =
                BuildSmartBlockGeometryFingerprint(
                    tr,
                    br);

            if (string.IsNullOrWhiteSpace(
                    candidateFingerprint))
            {
                return false;
            }

            var ranked =
                geometryRules
                    .Where(
                        r =>
                            r != null &&
                            !string.IsNullOrWhiteSpace(
                                r.GeometryFingerprint) &&
                            !string.IsNullOrWhiteSpace(
                                r.DisplayName))
                    .Select(
                        r =>
                            new
                            {
                                Rule =
                                    r,
                                Score =
                                    CompareSmartGeometryFingerprints(
                                        r.GeometryFingerprint,
                                        candidateFingerprint)
                            })
                    .Where(
                        x =>
                            x.Score <
                                double.MaxValue &&
                            !double.IsNaN(
                                x.Score) &&
                            !double.IsInfinity(
                                x.Score))
                    .GroupBy(
                        x =>
                            x.Rule.DisplayName,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(
                        g =>
                            g.OrderBy(
                                 x =>
                                     x.Score)
                             .First())
                    .OrderBy(
                        x =>
                            x.Score)
                    .ToList();

            if (ranked.Count == 0)
                return false;

            bestRule =
                ranked[0].Rule;

            bestScore =
                ranked[0].Score;

            if (bestScore >
                0.060)
            {
                bestRule =
                    null;

                return false;
            }

            if (ranked.Count > 1 &&
                ranked[1].Score -
                    bestScore <
                0.018)
            {
                bestRule =
                    null;

                return false;
            }

            return true;
        }


        private List<SmartGeometryMatch> FindSmartGeometryMatches(
            Database db,
            List<ObjectId> primitiveIds,
            List<SmartSymbolRule> geometryRules,
            List<SmartSymbolRule> allRules)
        {
            List<SmartGeometryMatch> result =
                new List<SmartGeometryMatch>();

            bool hasVectorRules =
                geometryRules != null &&
                geometryRules.Count > 0;

            bool hasOnnxRules =
                allRules != null &&
                allRules.Count > 0 &&
                GetOnnxSymbolClassifier() != null;

            if (db == null ||
                primitiveIds == null ||
                primitiveIds.Count == 0 ||
                (!hasVectorRules &&
                 !hasOnnxRules))
            {
                return result;
            }

            List<SmartGeometryPrimitive> primitives =
                new List<SmartGeometryPrimitive>();

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (ObjectId id in primitiveIds)
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased ||
                        !(ent is Curve))
                    {
                        continue;
                    }

                    try
                    {
                        Extents3d ex =
                            ent.GeometricExtents;

                        double dx =
                            Math.Abs(
                                ex.MaxPoint.X -
                                ex.MinPoint.X);

                        double dy =
                            Math.Abs(
                                ex.MaxPoint.Y -
                                ex.MinPoint.Y);

                        // Bỏ các nét kiến trúc rất dài.
                        if (Math.Max(
                                dx,
                                dy) >
                            1800.0)
                        {
                            continue;
                        }

                        primitives.Add(
                            new SmartGeometryPrimitive
                            {
                                Id =
                                    id,
                                Extents =
                                    ex,
                                Center =
                                    new Point3d(
                                        (ex.MinPoint.X +
                                         ex.MaxPoint.X) * 0.5,
                                        (ex.MinPoint.Y +
                                         ex.MaxPoint.Y) * 0.5,
                                        0.0)
                            });
                    }
                    catch
                    {
                    }
                }

                tr.Commit();
            }

            if (primitives.Count == 0)
                return result;

            // Gom cluster theo khoảng cách bounding box.
            // Ký hiệu van thường nhỏ; gap 80 mm đủ để gom các nét không chạm nhau.
            const double clusterGap =
                80.0;

            List<List<SmartGeometryPrimitive>> clusters =
                new List<List<SmartGeometryPrimitive>>();

            HashSet<ObjectId> used =
                new HashSet<ObjectId>();

            foreach (SmartGeometryPrimitive seed
                in primitives)
            {
                if (used.Contains(
                        seed.Id))
                {
                    continue;
                }

                List<SmartGeometryPrimitive> cluster =
                    new List<SmartGeometryPrimitive>();

                Queue<SmartGeometryPrimitive> queue =
                    new Queue<SmartGeometryPrimitive>();

                queue.Enqueue(
                    seed);

                used.Add(
                    seed.Id);

                while (queue.Count > 0)
                {
                    SmartGeometryPrimitive current =
                        queue.Dequeue();

                    cluster.Add(
                        current);

                    // Chặn cluster quá lớn: thường đó là chi tiết kiến trúc,
                    // không phải ký hiệu van/thiết bị.
                    if (cluster.Count > 30)
                        break;

                    foreach (SmartGeometryPrimitive other
                        in primitives)
                    {
                        if (used.Contains(
                                other.Id))
                        {
                            continue;
                        }

                        if (AreSmartGeometryExtentsNear(
                                current.Extents,
                                other.Extents,
                                clusterGap))
                        {
                            used.Add(
                                other.Id);

                            queue.Enqueue(
                                other);
                        }
                    }
                }

                if (cluster.Count > 0 &&
                    cluster.Count <= 30)
                {
                    clusters.Add(
                        cluster);
                }
            }

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (List<SmartGeometryPrimitive> cluster
                    in clusters)
                {
                    List<ObjectId> ids =
                        cluster
                            .Select(
                                x =>
                                    x.Id)
                            .ToList();

                    string fingerprint =
                        BuildSmartGeometryFingerprint(
                            tr,
                            ids);

                    if (string.IsNullOrWhiteSpace(
                            fingerprint))
                    {
                        continue;
                    }

                    SmartSymbolRule bestRule =
                        null;

                    double bestScore =
                        double.MaxValue;

                    foreach (SmartSymbolRule rule
                        in geometryRules ??
                           new List<SmartSymbolRule>())
                    {
                        if (rule == null ||
                            string.IsNullOrWhiteSpace(
                                rule.GeometryFingerprint))
                        {
                            continue;
                        }

                        double score =
                            CompareSmartGeometryFingerprints(
                                rule.GeometryFingerprint,
                                fingerprint);

                        if (score < bestScore)
                        {
                            bestScore =
                                score;
                            bestRule =
                                rule;
                        }
                    }

                    string source =
                        "GEOMETRY";

                    MepSymbolClassifier.Prediction onnxPrediction =
                        null;

                    // Vector chưa đủ chắc -> thử ONNX trên chính cluster EXPLODE.
                    if (bestRule == null ||
                        bestScore >
                            0.10)
                    {
                        if (!TryMatchSmartGeometryClusterByOnnx(
                                tr,
                                ids,
                                allRules,
                                out bestRule,
                                out onnxPrediction))
                        {
                            continue;
                        }

                        bestScore =
                            1.0 -
                            Math.Max(
                                0.0,
                                Math.Min(
                                    1.0,
                                    onnxPrediction?.Confidence ?? 0.0));

                        source =
                            "ONNX";
                    }

                    double x =
                        cluster.Average(
                            p =>
                                p.Center.X);

                    double y =
                        cluster.Average(
                            p =>
                                p.Center.Y);

                    result.Add(
                        new SmartGeometryMatch
                        {
                            Rule =
                                bestRule,
                            Center =
                                new Point3d(
                                    x,
                                    y,
                                    0.0),
                            Score =
                                bestScore,
                            Source =
                                source,
                            OnnxPrediction =
                                onnxPrediction
                        });
                }

                tr.Commit();
            }

            return result;
        }

        private static bool AreSmartGeometryExtentsNear(
            Extents3d a,
            Extents3d b,
            double gap)
        {
            return
                a.MinPoint.X <=
                    b.MaxPoint.X + gap &&
                a.MaxPoint.X >=
                    b.MinPoint.X - gap &&
                a.MinPoint.Y <=
                    b.MaxPoint.Y + gap &&
                a.MaxPoint.Y >=
                    b.MinPoint.Y - gap;
        }

        private void ScanSmartValveDeviceStatistics(
            Document doc,
            List<SmartSymbolRule> rules)
        {
            if (doc == null)
                return;

            if (rules == null ||
                rules.Count == 0)
            {
                MessageBox.Show(
                    "Danh sách ký hiệu của Legend đang trống.",
                    "NHẬN DIỆN THÔNG MINH");
                return;
            }

            Editor ed =
                doc.Editor;

            Database db =
                doc.Database;

            PromptSelectionOptions pso =
                new PromptSelectionOptions();

            pso.MessageForAdding =
                "\nQuét vùng mặt bằng cần nhận diện VAN / THIẾT BỊ + KIỂM TRA SÓT: ";

            _smartValveStage =
                "SCAN_SELECT_AREA";

            PromptSelectionResult psr =
                ed.GetSelection(
                    pso);

            if (psr.Status !=
                    PromptStatus.OK ||
                psr.Value == null ||
                psr.Value.Count == 0)
            {
                return;
            }

            // STEP22A:
            // Build graph ngay trên đúng vùng user vừa quét.
            // Các bước nhận diện phía dưới sẽ dùng graph này để suy DN/context.
            _smartValveStage =
                "GRAPH_BUILD";

            BuildMepGraphFromSelection(
                doc,
                psr.Value.GetObjectIds(),
                false);

            rules =
                rules
                    .Where(
                        r =>
                            r != null &&
                            !string.IsNullOrWhiteSpace(
                                r.BlockKey) &&
                            !string.IsNullOrWhiteSpace(
                                r.DisplayName))
                    .ToList();

            if (rules.Count == 0)
            {
                MessageBox.Show(
                    "Không có ký hiệu hợp lệ để quét.",
                    "NHẬN DIỆN THÔNG MINH");
                return;
            }

            // Chỉ các tên có thật trong Legend hiện tại mới dùng cho cảnh báo LEGEND 0.
            // Memory Local được phép hỗ trợ nhận diện nhưng không tạo cảnh báo giả.
            List<string> currentLegendNames =
                rules
                    .Select(
                        r =>
                            r.DisplayName)
                    .Where(
                        n =>
                            !string.IsNullOrWhiteSpace(
                                n))
                    .Distinct(
                        StringComparer.OrdinalIgnoreCase)
                    .ToList();

            // STEP 18: Legend hiện tại thắng trước; sau đó bổ sung Positive Memory.
            rules =
                EnrichSmartRulesWithAiLearning(
                    rules);

            List<SmartSymbolRule> blockRules =
                rules
                    .Where(
                        r =>
                            r != null &&
                            string.Equals(
                                r.MatchMode,
                                "BLOCK",
                                StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(
                                r.BlockKey))
                    .ToList();

            List<SmartSymbolRule> pointRules =
                rules
                    .Where(
                        r =>
                            string.Equals(
                                r.MatchMode,
                                "POINT",
                                StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(
                                r.BlockKey))
                    .ToList();

            List<SmartSymbolRule> geometryRules =
                rules
                    .Where(
                        r =>
                            string.Equals(
                                r.MatchMode,
                                "GEOMETRY",
                                StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(
                                r.GeometryFingerprint))
                    .ToList();

            List<SmartSymbolRule> rasterRules =
                rules
                    .Where(
                        r =>
                            r != null &&
                            !string.IsNullOrWhiteSpace(
                                r.RasterSignature))
                    .ToList();

            // Chỉ dùng exact BlockKey khi key đó ứng với đúng MỘT nhãn.
            // Nếu cùng Dynamic Block family có nhiều state/nhãn, để Geometry/Vision phân xử.
            Dictionary<string, SmartSymbolRule> ruleMap =
                blockRules
                    .GroupBy(
                        r =>
                            r.BlockKey,
                        StringComparer.OrdinalIgnoreCase)
                    .Where(
                        g =>
                            g.Select(
                                 r =>
                                     r.DisplayName)
                             .Where(
                                 n =>
                                     !string.IsNullOrWhiteSpace(
                                         n))
                             .Distinct(
                                 StringComparer.OrdinalIgnoreCase)
                             .Count() == 1)
                    .Select(
                        g =>
                            g.First())
                    .ToDictionary(
                        r =>
                            r.BlockKey,
                        r =>
                            r,
                        StringComparer.OrdinalIgnoreCase);

            Dictionary<string, SmartSymbolRule> pointRuleMap =
                pointRules
                    .GroupBy(
                        r =>
                            r.BlockKey,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(
                        g =>
                            g.Last())
                    .ToDictionary(
                        r =>
                            r.BlockKey,
                        r =>
                            r,
                        StringComparer.OrdinalIgnoreCase);

            List<SmartPipeCandidate> pipeCandidates =
                new List<SmartPipeCandidate>();

            List<ObjectId> matchedBlocks =
                new List<ObjectId>();

            // Exact BlockKey match vẫn ưu tiên.
            // Nếu tên block khác nhưng hình giống Legend, lưu rule override ở đây.
            Dictionary<ObjectId, SmartSymbolRule> matchedBlockRuleOverrides =
                new Dictionary<ObjectId, SmartSymbolRule>();

            HashSet<ObjectId> matchedBlockByOnnx =
                new HashSet<ObjectId>();

            Dictionary<ObjectId, MepSymbolClassifier.Prediction> matchedBlockOnnxPredictions =
                new Dictionary<ObjectId, MepSymbolClassifier.Prediction>();

            HashSet<ObjectId> matchedBlockByRaster =
                new HashSet<ObjectId>();

            Dictionary<ObjectId, string> matchedBlockRasterSignatures =
                new Dictionary<ObjectId, string>();

            Dictionary<ObjectId, double> matchedBlockRasterScores =
                new Dictionary<ObjectId, double>();

            List<ObjectId> unknownBlocks =
                new List<ObjectId>();

            List<ObjectId> matchedPoints =
                new List<ObjectId>();

            List<ObjectId> unknownPoints =
                new List<ObjectId>();

            List<ObjectId> geometryPrimitiveIds =
                new List<ObjectId>();

            _smartValveStage =
                "SCAN_COLLECT_OBJECTS";

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (SelectedObject selected
                    in psr.Value)
                {
                    if (selected == null ||
                        selected.ObjectId.IsNull)
                    {
                        continue;
                    }

                    Entity ent =
                        tr.GetObject(
                            selected.ObjectId,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased)
                    {
                        continue;
                    }

                    string entLayer =
                        (ent.Layer ?? "")
                            .Trim();

                    if (IsSmartAuditLayer(
                            entLayer))
                    {
                        continue;
                    }

                    if (ent is Curve curve)
                    {
                        string layer =
                            entLayer;

                        if (LaLayerBienOngShop(
                                layer) ||
                            LaLayerPhuKienHoacTamShop(
                                layer))
                        {
                            continue;
                        }

                        // STEP 17:
                        // Nếu BƯỚC 1 AI đã dựng TDL_AI_PIPE_DN150..., coi chính lớp đó
                        // là "mô hình ống" có độ tin cậy cao cho VAN / THIẾT BỊ.
                        string aiPipeSize =
                            ExtractAiPipeSizeFromLayer(
                                layer);

                        bool isAiPipe =
                            !string.IsNullOrWhiteSpace(
                                aiPipeSize);

                        bool pipeLayer =
                            isAiPipe ||
                            LaLayerOng(
                                layer) ||
                            LaLayerTamOngShop(
                                layer);

                        if (pipeLayer)
                        {
                            string size =
                                aiPipeSize;

                            if (string.IsNullOrWhiteSpace(
                                    size))
                            {
                                TryExtractSmartPipeSize(
                                    layer,
                                    out size);
                            }

                            if (!string.IsNullOrWhiteSpace(
                                    size))
                            {
                                pipeCandidates.Add(
                                    new SmartPipeCandidate
                                    {
                                        Id =
                                            curve.ObjectId,
                                        Size =
                                            size,
                                        Layer =
                                            layer,
                                        IsAiGenerated =
                                            isAiPipe,
                                        Confidence =
                                            isAiPipe
                                                ? 0.99
                                                : 0.88
                                    });
                            }

                            continue;
                        }

                        // Giữ lại hình học nhỏ ngoài ống để:
                        // 1) match mẫu EXPLODE đã học
                        // 2) chạy vòng kiểm tra chéo tìm ký hiệu chưa học.
                        if (ent is Line ||
                            ent is Arc ||
                            ent is Circle ||
                            ent is Polyline)
                        {
                            geometryPrimitiveIds.Add(
                                curve.ObjectId);
                        }

                        continue;
                    }

                    if (ent is DBPoint dbPoint)
                    {
                        string pointKey =
                            GetSmartPointSignature(
                                dbPoint);

                        if (!string.IsNullOrWhiteSpace(
                                pointKey) &&
                            pointRuleMap.ContainsKey(
                                pointKey))
                        {
                            matchedPoints.Add(
                                dbPoint.ObjectId);
                        }
                        else
                        {
                            unknownPoints.Add(
                                dbPoint.ObjectId);
                        }

                        continue;
                    }

                    if (ent is BlockReference br)
                    {
                        if (TryReadVerticalRiserData(
                                br,
                                out VerticalRiserData _))
                        {
                            continue;
                        }

                        string key =
                            GetSmartBlockIdentityKey(
                                tr,
                                br);

                        if (ruleMap.ContainsKey(
                                key))
                        {
                            matchedBlocks.Add(
                                br.ObjectId);
                        }
                        else
                        {
                            // STEP18F:
                            // Tên block có thể khác giữa Legend và mặt bằng.
                            // So thêm geometry fingerprint của chính BLOCK.
                            if (TryMatchSmartBlockByGeometry(
                                    tr,
                                    br,
                                    geometryRules,
                                    out SmartSymbolRule geometryRule,
                                    out double geometryScore))
                            {
                                matchedBlocks.Add(
                                    br.ObjectId);

                                matchedBlockRuleOverrides[
                                    br.ObjectId] =
                                    geometryRule;

                                continue;
                            }

                            // STEP21B - ONNX CLASSIFIER:
                            // Sau Exact Block + Vector Fingerprint, dùng model đã train
                            // để phân loại hình ký hiệu. Model không có/lỗi => tự bỏ qua.
                            if (TryMatchSmartBlockByOnnx(
                                    tr,
                                    br,
                                    rules,
                                    out SmartSymbolRule onnxRule,
                                    out MepSymbolClassifier.Prediction onnxPrediction))
                            {
                                matchedBlocks.Add(
                                    br.ObjectId);

                                matchedBlockRuleOverrides[
                                    br.ObjectId] =
                                    onnxRule;

                                matchedBlockByOnnx.Add(
                                    br.ObjectId);

                                matchedBlockOnnxPredictions[
                                    br.ObjectId] =
                                    onnxPrediction;

                                continue;
                            }

                            // STEP19 - HYBRID VISION LITE FALLBACK:
                            // nếu ONNX chưa có hoặc chưa đủ chắc, mới dùng silhouette cũ.
                            if (TryMatchSmartBlockByRaster(
                                    tr,
                                    br,
                                    rasterRules,
                                    out SmartSymbolRule rasterRule,
                                    out double rasterScore,
                                    out string rasterSignature))
                            {
                                matchedBlocks.Add(
                                    br.ObjectId);

                                matchedBlockRuleOverrides[
                                    br.ObjectId] =
                                    rasterRule;

                                matchedBlockByRaster.Add(
                                    br.ObjectId);

                                matchedBlockRasterSignatures[
                                    br.ObjectId] =
                                    rasterSignature;

                                matchedBlockRasterScores[
                                    br.ObjectId] =
                                    rasterScore;

                                continue;
                            }

                            // STEP 18:
                            // Nếu người dùng từng BỎ QUA signature này,
                            // loại ngay trước Candidate Detector.
                            if (IsAiLearningNegativeBlock(
                                    key))
                            {
                                continue;
                            }

                            unknownBlocks.Add(
                                br.ObjectId);
                        }
                    }
                }

                tr.Commit();
            }

            // STEP 17:
            // Không phụ thuộc việc người dùng có quét trúng nét overlay AI hay không.
            // Lấy toàn bộ TDL_AI_PIPE_DN... trong CurrentSpace làm mô hình tham chiếu.
            AppendGlobalAiPipeCandidates(
                db,
                pipeCandidates);

            // Shared scan result containers/counters.
            // Must be declared BEFORE POINT / BLOCK / GEOMETRY matching.
            Dictionary<string, int> counts =
                new Dictionary<string, int>(
                    StringComparer.OrdinalIgnoreCase);

            List<SmartAuditRow> auditRows =
                new List<SmartAuditRow>();

            HashSet<string> detectedLegendNames =
                new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);

            int sizeMatched =
                0;

            int sizeUncertain =
                0;

            int noPipeNearby =
                0;

            _smartValveStage =
                "SCAN_MATCH_POINTS";

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (ObjectId pointId
                    in matchedPoints)
                {
                    DBPoint point =
                        tr.GetObject(
                            pointId,
                            OpenMode.ForRead,
                            false) as DBPoint;

                    if (point == null ||
                        point.IsErased)
                    {
                        continue;
                    }

                    string pointKey =
                        GetSmartPointSignature(
                            point);

                    if (!pointRuleMap.TryGetValue(
                            pointKey,
                            out SmartSymbolRule rule))
                    {
                        continue;
                    }

                    string size =
                        "-";

                    string auditStatus =
                        "OK";

                    string auditNote =
                        "Đã nhận diện POINT / DBPoint theo Legend.";

                    if (string.Equals(
                            rule.SizeRule,
                            "THEO_ONG",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        string inferredSize;
                        bool uncertain;

                        bool found =
                            TryInferSmartBlockPipeSize(
                                tr,
                                point.Position,
                                pipeCandidates,
                                out inferredSize,
                                out uncertain);

                        if (found &&
                            !uncertain)
                        {
                            size =
                                inferredSize;

                            sizeMatched++;
                        }
                        else if (found &&
                                 uncertain)
                        {
                            size =
                                "CẦN KIỂM TRA";

                            auditStatus =
                                "DN_CHECK";

                            auditNote =
                                "POINT nhận đúng loại nhưng có nhiều DN gần vị trí này.";

                            sizeUncertain++;
                        }
                        else
                        {
                            size =
                                "KHÔNG RÕ DN";

                            auditStatus =
                                "NO_DN";

                            auditNote =
                                "POINT nhận đúng loại nhưng chưa tìm thấy tuyến ống đủ gần.";

                            noPipeNearby++;
                        }
                    }

                    string countKey =
                        rule.DisplayName +
                        "\u001F" +
                        size;

                    if (!counts.ContainsKey(
                            countKey))
                    {
                        counts[countKey] =
                            0;
                    }

                    counts[countKey]++;

                    detectedLegendNames.Add(
                        rule.DisplayName);

                    auditRows.Add(
                        new SmartAuditRow
                        {
                            Status =
                                auditStatus,
                            Name =
                                rule.DisplayName,
                            Size =
                                size,
                            Source =
                                "POINT",
                            Note =
                                auditNote,
                            Point =
                                new Point3d(
                                    point.Position.X,
                                    point.Position.Y,
                                    0.0),
                            FollowDn =
                                string.Equals(
                                    rule.SizeRule,
                                    "THEO_ONG",
                                    StringComparison.OrdinalIgnoreCase),
                            MatchMode =
                                "POINT",
                            BlockKey =
                                rule.BlockKey,
                            GeometryFingerprint =
                                "",
                            SourceId =
                                pointId
                        });
                }

                tr.Commit();
            }

            _smartValveStage =
                "SCAN_MATCH_EXPLODED_GEOMETRY";

            List<SmartGeometryMatch> geometryMatches =
                FindSmartGeometryMatches(
                    db,
                    geometryPrimitiveIds,
                    geometryRules,
                    rules);

            _smartValveStage =
                "SCAN_INFER_DN";

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (ObjectId blockId
                    in matchedBlocks)
                {
                    BlockReference br =
                        tr.GetObject(
                            blockId,
                            OpenMode.ForRead,
                            false) as BlockReference;

                    if (br == null ||
                        br.IsErased)
                    {
                        continue;
                    }

                    string blockKey =
                        GetSmartBlockIdentityKey(
                            tr,
                            br);

                    SmartSymbolRule rule =
                        null;

                    bool overrideMatch =
                        matchedBlockRuleOverrides.TryGetValue(
                            blockId,
                            out rule);

                    bool onnxFallbackMatch =
                        overrideMatch &&
                        matchedBlockByOnnx.Contains(
                            blockId);

                    bool rasterFallbackMatch =
                        overrideMatch &&
                        !onnxFallbackMatch &&
                        matchedBlockByRaster.Contains(
                            blockId);

                    bool geometryFallbackMatch =
                        overrideMatch &&
                        !onnxFallbackMatch &&
                        !rasterFallbackMatch;

                    if (!overrideMatch &&
                        !ruleMap.TryGetValue(
                            blockKey,
                            out rule))
                    {
                        continue;
                    }

                    string size =
                        "-";

                    string auditStatus =
                        "OK";

                    string auditNote =
                        rasterFallbackMatch
                            ? "Đã nhận diện BLOCK bằng Hybrid Vision."
                            : "Đã nhận diện BLOCK.";

                    if (string.Equals(
                            rule.SizeRule,
                            "THEO_ONG",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        string inferredSize;
                        bool uncertain;

                        bool found =
                            TryInferSmartBlockPipeSize(
                                tr,
                                br,
                                pipeCandidates,
                                out inferredSize,
                                out uncertain);

                        if (found &&
                            !uncertain)
                        {
                            size =
                                inferredSize;

                            auditNote =
                                "Đã nhận diện BLOCK + suy DN bằng Pipe-Device Fusion (ưu tiên mô hình AI và hình học block).";

                            sizeMatched++;
                        }
                        else if (found &&
                                 uncertain)
                        {
                            size =
                                "CẦN KIỂM TRA";

                            auditStatus =
                                "DN_CHECK";

                            auditNote =
                                "Nhận được loại nhưng có nhiều DN gần vị trí này.";

                            sizeUncertain++;
                        }
                        else
                        {
                            size =
                                "KHÔNG RÕ DN";

                            auditStatus =
                                "NO_DN";

                            auditNote =
                                "Nhận được loại nhưng chưa tìm thấy tuyến ống đủ gần.";

                            noPipeNearby++;
                        }
                    }

                    string countKey =
                        rule.DisplayName +
                        "\u001F" +
                        size;

                    if (!counts.ContainsKey(
                            countKey))
                    {
                        counts[countKey] =
                            0;
                    }

                    counts[countKey]++;

                    detectedLegendNames.Add(
                        rule.DisplayName);

                    auditRows.Add(
                        new SmartAuditRow
                        {
                            Status =
                                auditStatus,
                            Name =
                                rule.DisplayName,
                            Size =
                                size,
                            Source =
                                onnxFallbackMatch
                                    ? "BLOCK - ONNX"
                                    : rasterFallbackMatch
                                        ? "BLOCK - VISION"
                                        : geometryFallbackMatch
                                            ? "BLOCK - HÌNH HỌC"
                                            : "BLOCK",
                            Note =
                                onnxFallbackMatch &&
                                matchedBlockOnnxPredictions.ContainsKey(blockId)
                                    ? "ONNX: " +
                                      matchedBlockOnnxPredictions[blockId].Label +
                                      " | confidence=" +
                                      matchedBlockOnnxPredictions[blockId].Confidence.ToString(
                                          "P1",
                                          CultureInfo.InvariantCulture) +
                                      " | margin=" +
                                      matchedBlockOnnxPredictions[blockId].Margin.ToString(
                                          "P1",
                                          CultureInfo.InvariantCulture) +
                                      (string.IsNullOrWhiteSpace(
                                           matchedBlockOnnxPredictions[blockId].SecondLabel)
                                          ? ""
                                          : " | #2=" +
                                            matchedBlockOnnxPredictions[blockId].SecondLabel +
                                            " " +
                                            matchedBlockOnnxPredictions[blockId].SecondConfidence.ToString(
                                                "P1",
                                                CultureInfo.InvariantCulture)) +
                                      ". " + auditNote
                                    : rasterFallbackMatch
                                        ? "Tên/vector/ONNX chưa chốt trực tiếp nhưng silhouette Vision Lite khớp Legend. Vision score=" +
                                          (matchedBlockRasterScores.ContainsKey(blockId)
                                              ? matchedBlockRasterScores[blockId].ToString(
                                                  "0.000",
                                                  CultureInfo.InvariantCulture)
                                              : "-") +
                                          ". " + auditNote
                                        : geometryFallbackMatch
                                            ? "Tên block khác Legend nhưng geometry fingerprint khớp. " +
                                              auditNote
                                            : auditNote,
                            Point =
                                new Point3d(
                                    br.Position.X,
                                    br.Position.Y,
                                    0.0),
                            FollowDn =
                                string.Equals(
                                    rule.SizeRule,
                                    "THEO_ONG",
                                    StringComparison.OrdinalIgnoreCase),
                            MatchMode =
                                onnxFallbackMatch
                                    ? "BLOCK"
                                    : rasterFallbackMatch
                                        ? (string.IsNullOrWhiteSpace(rule.MatchMode)
                                            ? "BLOCK"
                                            : rule.MatchMode)
                                        : geometryFallbackMatch
                                            ? "GEOMETRY"
                                            : "BLOCK",
                            BlockKey =
                                overrideMatch
                                    ? blockKey
                                    : rule.BlockKey,
                            GeometryFingerprint =
                                BuildSmartBlockGeometryFingerprint(
                                    tr,
                                    br),
                            RasterSignature =
                                onnxFallbackMatch
                                    ? BuildSmartBlockRasterSignature(
                                        tr,
                                        br)
                                    : rasterFallbackMatch &&
                                      matchedBlockRasterSignatures.ContainsKey(blockId)
                                        ? matchedBlockRasterSignatures[blockId]
                                        : (rule.RasterSignature ?? ""),
                            SourceId =
                                blockId
                        });
                }

                foreach (SmartGeometryMatch match
                    in geometryMatches)
                {
                    if (match == null ||
                        match.Rule == null)
                    {
                        continue;
                    }

                    SmartSymbolRule rule =
                        match.Rule;

                    string size =
                        "-";

                    string auditStatus =
                        "OK";

                    bool geometryOnnxMatch =
                        string.Equals(
                            match.Source,
                            "ONNX",
                            StringComparison.OrdinalIgnoreCase);

                    string auditNote =
                        geometryOnnxMatch &&
                        match.OnnxPrediction != null
                            ? "HÌNH EXPLODE được ONNX phân loại: " +
                              match.OnnxPrediction.Label +
                              " | confidence=" +
                              match.OnnxPrediction.Confidence.ToString(
                                  "P1",
                                  CultureInfo.InvariantCulture) +
                              " | margin=" +
                              match.OnnxPrediction.Margin.ToString(
                                  "P1",
                                  CultureInfo.InvariantCulture) +
                              "."
                            : "Đã nhận diện HÌNH EXPLODE bằng vector fingerprint.";

                    if (string.Equals(
                            rule.SizeRule,
                            "THEO_ONG",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        string inferredSize;
                        bool uncertain;

                        bool found =
                            TryInferSmartBlockPipeSize(
                                tr,
                                match.Center,
                                pipeCandidates,
                                out inferredSize,
                                out uncertain);

                        if (found &&
                            !uncertain)
                        {
                            size =
                                inferredSize;

                            sizeMatched++;
                        }
                        else if (found &&
                                 uncertain)
                        {
                            size =
                                "CẦN KIỂM TRA";

                            auditStatus =
                                "DN_CHECK";

                            auditNote =
                                "Nhận được loại nhưng có nhiều DN gần vị trí này.";

                            sizeUncertain++;
                        }
                        else
                        {
                            size =
                                "KHÔNG RÕ DN";

                            auditStatus =
                                "NO_DN";

                            auditNote =
                                "Nhận được loại nhưng chưa tìm thấy tuyến ống đủ gần.";

                            noPipeNearby++;
                        }
                    }

                    string countKey =
                        rule.DisplayName +
                        "\u001F" +
                        size;

                    if (!counts.ContainsKey(
                            countKey))
                    {
                        counts[countKey] =
                            0;
                    }

                    counts[countKey]++;

                    detectedLegendNames.Add(
                        rule.DisplayName);

                    auditRows.Add(
                        new SmartAuditRow
                        {
                            Status =
                                auditStatus,
                            Name =
                                rule.DisplayName,
                            Size =
                                size,
                            Source =
                                geometryOnnxMatch
                                    ? "HÌNH EXPLODE - ONNX"
                                    : "HÌNH EXPLODE",
                            Note =
                                auditNote,
                            Point =
                                new Point3d(
                                    match.Center.X,
                                    match.Center.Y,
                                    0.0),
                            FollowDn =
                                string.Equals(
                                    rule.SizeRule,
                                    "THEO_ONG",
                                    StringComparison.OrdinalIgnoreCase),
                            MatchMode =
                                "GEOMETRY",
                            BlockKey =
                                rule.BlockKey,
                            GeometryFingerprint =
                                rule.GeometryFingerprint ?? ""
                        });
                }

                tr.Commit();
            }

            _smartValveStage =
                "AUDIT_FIND_UNKNOWN_BLOCKS";

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (ObjectId blockId
                    in unknownBlocks)
                {
                    BlockReference br =
                        tr.GetObject(
                            blockId,
                            OpenMode.ForRead,
                            false) as BlockReference;

                    if (br == null ||
                        br.IsErased)
                    {
                        continue;
                    }

                    if (!IsSmartPotentialUnknownBlock(
                            tr,
                            br,
                            pipeCandidates))
                    {
                        continue;
                    }

                    Point3d center =
                        new Point3d(
                            br.Position.X,
                            br.Position.Y,
                            0.0);

                    if (IsSmartPointNearRecognized(
                            center,
                            auditRows,
                            140.0))
                    {
                        continue;
                    }

                    string inferredSize =
                        "";

                    bool uncertain =
                        false;

                    bool foundPipe =
                        TryInferSmartBlockPipeSize(
                            tr,
                            br,
                            pipeCandidates,
                            out inferredSize,
                            out uncertain);

                    string displaySize =
                        foundPipe
                            ? (uncertain
                                ? "CẦN KIỂM TRA"
                                : inferredSize)
                            : "KHÔNG RÕ DN";

                    string blockName =
                        GetShopStatBlockName(
                            tr,
                            br);

                    string unknownBlockKey =
                        GetSmartBlockIdentityKey(
                            tr,
                            br);

                    if (string.IsNullOrWhiteSpace(
                            unknownBlockKey))
                    {
                        unknownBlockKey =
                            NormalizeSmartSymbolKey(
                                blockName);
                    }

                    auditRows.Add(
                        new SmartAuditRow
                        {
                            Status =
                                "MISSING",
                            Name =
                                "CHƯA NHẬN DIỆN",
                            Size =
                                displaySize,
                            Source =
                                "BLOCK CHƯA HỌC",
                            Note =
                                "Block gần tuyến ống nhưng không khớp Legend: " +
                                (string.IsNullOrWhiteSpace(
                                     blockName)
                                    ? "(không tên)"
                                    : blockName),
                            Point =
                                center,
                            FollowDn =
                                true,
                            MatchMode =
                                "BLOCK",
                            BlockKey =
                                unknownBlockKey,
                            GeometryFingerprint =
                                BuildSmartBlockGeometryFingerprint(
                                    tr,
                                    br),
                            RasterSignature =
                                BuildSmartBlockRasterSignature(
                                    tr,
                                    br),
                            SourceId =
                                blockId
                        });
                }

                tr.Commit();
            }

            _smartValveStage =
                "AUDIT_FIND_UNKNOWN_POINTS";

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (ObjectId pointId
                    in unknownPoints)
                {
                    DBPoint point =
                        tr.GetObject(
                            pointId,
                            OpenMode.ForRead,
                            false) as DBPoint;

                    if (point == null ||
                        point.IsErased)
                    {
                        continue;
                    }

                    Point3d center =
                        new Point3d(
                            point.Position.X,
                            point.Position.Y,
                            0.0);

                    if (IsSmartPointNearRecognized(
                            center,
                            auditRows,
                            100.0))
                    {
                        continue;
                    }

                    string inferredSize =
                        "";

                    bool uncertain =
                        false;

                    bool foundPipe =
                        TryInferSmartBlockPipeSize(
                            tr,
                            point.Position,
                            pipeCandidates,
                            out inferredSize,
                            out uncertain);

                    // POINT không gần network ống thì không đưa vào bảng sót.
                    if (!foundPipe)
                        continue;

                    string pointKey =
                        GetSmartPointSignature(
                            point);

                    auditRows.Add(
                        new SmartAuditRow
                        {
                            Status =
                                "MISSING",
                            Name =
                                "CHƯA NHẬN DIỆN",
                            Size =
                                uncertain
                                    ? "CẦN KIỂM TRA"
                                    : inferredSize,
                            Source =
                                "POINT CHƯA HỌC",
                            Note =
                                "AutoCAD POINT/DBPoint gần tuyến ống nhưng chưa có trong Legend/AI Memory.",
                            Point =
                                center,
                            FollowDn =
                                true,
                            MatchMode =
                                "POINT",
                            BlockKey =
                                pointKey,
                            GeometryFingerprint =
                                "",
                            SourceId =
                                pointId
                        });
                }

                tr.Commit();
            }

            _smartValveStage =
                "AUDIT_FIND_UNKNOWN_GEOMETRY";

            List<SmartAuditGeometryCluster> geometryClusters =
                FindSmartAuditGeometryClusters(
                    db,
                    geometryPrimitiveIds);

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (SmartAuditGeometryCluster cluster
                    in geometryClusters)
                {
                    if (cluster == null)
                        continue;

                    if (IsSmartPointNearRecognized(
                            cluster.Center,
                            auditRows,
                            140.0))
                    {
                        continue;
                    }

                    string inferredSize =
                        "";

                    bool uncertain =
                        false;

                    bool foundPipe =
                        TryInferSmartBlockPipeSize(
                            tr,
                            cluster.Center,
                            pipeCandidates,
                            out inferredSize,
                            out uncertain);

                    // Vòng kiểm tra chéo chỉ coi là ứng viên "sót"
                    // khi cụm hình thực sự nằm gần một tuyến ống.
                    if (!foundPipe)
                        continue;

                    string displaySize =
                        uncertain
                            ? "CẦN KIỂM TRA"
                            : inferredSize;

                    string unknownFingerprint =
                        BuildSmartGeometryFingerprint(
                            tr,
                            cluster.ObjectIds);

                    string unknownGeometryKey =
                        string.IsNullOrWhiteSpace(
                            unknownFingerprint)
                            ? ""
                            : "GEO_" +
                              Convert.ToBase64String(
                                  Encoding.UTF8.GetBytes(
                                      unknownFingerprint));

                    // STEP 18:
                    // Negative geometry memory dùng fingerprint rotation/scale independent.
                    if (IsAiLearningNegativeGeometry(
                            unknownFingerprint))
                    {
                        continue;
                    }

                    auditRows.Add(
                        new SmartAuditRow
                        {
                            Status =
                                "MISSING",
                            Name =
                                "CHƯA NHẬN DIỆN",
                            Size =
                                displaySize,
                            Source =
                                "HÌNH CHƯA HỌC",
                            Note =
                                "Cụm " +
                                cluster.EntityCount +
                                " nét nhỏ nằm trên/gần tuyến ống nhưng không khớp mẫu Legend.",
                            Point =
                                cluster.Center,
                            FollowDn =
                                true,
                            MatchMode =
                                "GEOMETRY",
                            BlockKey =
                                unknownGeometryKey,
                            GeometryFingerprint =
                                unknownFingerprint ?? ""
                        });
                }

                tr.Commit();
            }

            // Loại trùng ứng viên đỏ nếu hai thuật toán cùng chỉ vào một vị trí.
            auditRows =
                DeduplicateSmartAuditRows(
                    auditRows);

            List<string> legendZero =
                currentLegendNames
                    .Where(
                        name =>
                            !detectedLegendNames.Contains(
                                name))
                    .Distinct(
                        StringComparer.OrdinalIgnoreCase)
                    .OrderBy(
                        name =>
                            name)
                    .ToList();

            _smartValveStage =
                "AUDIT_DRAW_MARKERS";

            DrawSmartAuditMarkers(
                doc,
                auditRows);

            _smartValveStage =
                "AUDIT_REVIEW_INTERACTIVE";

            AttachPreviewToAuditRows(
                doc,
                auditRows,
                _lastSmartLegendRows);

            bool auditAccepted =
                ShowSmartAuditReportDialog(
                    doc,
                    auditRows,
                    legendZero);

            if (!auditAccepted)
            {
                return;
            }

            _smartValveStage =
                "AUDIT_APPLY_CORRECTIONS";

            ApplySmartAuditCorrections(
                auditRows);

            UpdateSmartRulesFromAuditRows(
                rules,
                auditRows);

            // STEP 18:
            // Chỉ học mạnh khi người dùng thực sự sửa hoặc xác nhận mẫu mới.
            LearnAiFromAuditCorrections(
                auditRows);

            // Sau khi sửa tên / xác nhận các dòng đỏ,
            // tính lại Legend 0 và thống kê từ chính danh sách đã kiểm tra.
            detectedLegendNames =
                new HashSet<string>(
                    auditRows
                        .Where(
                            r =>
                                r != null &&
                                !string.Equals(
                                    r.Status,
                                    "MISSING",
                                    StringComparison.OrdinalIgnoreCase) &&
                                !string.IsNullOrWhiteSpace(
                                    r.Name))
                        .Select(
                            r =>
                                r.Name),
                    StringComparer.OrdinalIgnoreCase);

            legendZero =
                currentLegendNames
                    .Where(
                        name =>
                            !detectedLegendNames.Contains(
                                name))
                    .Distinct(
                        StringComparer.OrdinalIgnoreCase)
                    .OrderBy(
                        name =>
                            name)
                    .ToList();

            auditRows =
                DeduplicateSmartAuditRows(
                    auditRows);

            DrawSmartAuditMarkers(
                doc,
                auditRows);

            SaveLastSmartAuditSession(
                auditRows,
                legendZero,
                rules);

            List<SmartValveStatRow> rows =
                BuildSmartStatsFromAuditRows(
                    auditRows);

            if (rows.Count > 0)
            {
                _smartValveStage =
                    "SCAN_OUTPUT_TABLE";

                XuatBangThongKeVanThongMinh(
                    rows);
            }

            int recognizedCount =
                auditRows.Count(
                    r =>
                        r != null &&
                        !string.Equals(
                            r.Status,
                            "MISSING",
                            StringComparison.OrdinalIgnoreCase));

            int missingCount =
                auditRows.Count(
                    r =>
                        r != null &&
                        string.Equals(
                            r.Status,
                            "MISSING",
                            StringComparison.OrdinalIgnoreCase));

            int certainCount =
                auditRows.Count(
                    r =>
                        r != null &&
                        string.Equals(
                            r.Status,
                            "OK",
                            StringComparison.OrdinalIgnoreCase));

            int candidateCount =
                recognizedCount +
                missingCount;

            double coverage =
                candidateCount > 0
                    ? recognizedCount * 100.0 /
                      candidateCount
                    : 100.0;

            double certainCoverage =
                candidateCount > 0
                    ? certainCount * 100.0 /
                      candidateCount
                    : 100.0;

            MessageBox.Show(
                "KIỂM TRA CHÉO hoàn tất.\n\n" +
                "• Tổng ứng viên sau khi rà soát: " +
                candidateCount +
                "\n• Đã nhận diện: " +
                recognizedCount +
                "\n• Nhận diện chắc chắn: " +
                certainCount +
                "\n• Còn nghi bị sót: " +
                missingCount +
                "\n• Legend có nhưng mặt bằng chưa thấy: " +
                legendZero.Count +
                "\n\n" +
                "Độ phủ nhận diện: " +
                coverage.ToString(
                    "0.0",
                    CultureInfo.InvariantCulture) +
                "%\n" +
                "Độ phủ chắc chắn: " +
                certainCoverage.ToString(
                    "0.0",
                    CultureInfo.InvariantCulture) +
                "%\n\n" +
                "Các tên bạn sửa trong bảng kiểm tra đã được học lại cho lần quét sau.",
                "KIỂM TRA SÓT VAN / THIẾT BỊ");
        }


        private static bool IsSmartAuditLayer(
            string layer)
        {
            if (string.IsNullOrWhiteSpace(
                    layer))
            {
                return false;
            }

            return
                layer.Equals(
                    SmartAuditOkLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layer.Equals(
                    SmartAuditCheckLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layer.Equals(
                    SmartAuditMissingLayer,
                    StringComparison.OrdinalIgnoreCase);
        }

        private bool IsSmartPotentialUnknownBlock(
            Transaction tr,
            BlockReference br,
            List<SmartPipeCandidate> pipes)
        {
            if (tr == null ||
                br == null ||
                pipes == null ||
                pipes.Count == 0)
            {
                return false;
            }

            double maxSize =
                0.0;

            try
            {
                Extents3d ex =
                    br.GeometricExtents;

                double dx =
                    Math.Abs(
                        ex.MaxPoint.X -
                        ex.MinPoint.X);

                double dy =
                    Math.Abs(
                        ex.MaxPoint.Y -
                        ex.MinPoint.Y);

                maxSize =
                    Math.Max(
                        dx,
                        dy);

                // Chặn các block kiến trúc / title / viewport quá lớn.
                if (maxSize < 8.0 ||
                    maxSize > 1600.0)
                {
                    return false;
                }
            }
            catch
            {
                maxSize = 300.0;
            }

            string size;
            bool uncertain;

            bool nearPipe =
                TryInferSmartBlockPipeSize(
                    tr,
                    br,
                    pipes,
                    out size,
                    out uncertain);

            return nearPipe;
        }

        private List<SmartAuditGeometryCluster> FindSmartAuditGeometryClusters(
            Database db,
            List<ObjectId> primitiveIds)
        {
            List<SmartAuditGeometryCluster> result =
                new List<SmartAuditGeometryCluster>();

            if (db == null ||
                primitiveIds == null ||
                primitiveIds.Count == 0)
            {
                return result;
            }

            List<SmartGeometryPrimitive> primitives =
                new List<SmartGeometryPrimitive>();

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (ObjectId id
                    in primitiveIds)
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased ||
                        !(ent is Curve))
                    {
                        continue;
                    }

                    try
                    {
                        Extents3d ex =
                            ent.GeometricExtents;

                        double dx =
                            Math.Abs(
                                ex.MaxPoint.X -
                                ex.MinPoint.X);

                        double dy =
                            Math.Abs(
                                ex.MaxPoint.Y -
                                ex.MinPoint.Y);

                        double max =
                            Math.Max(
                                dx,
                                dy);

                        // Chỉ giữ nét nhỏ có khả năng là ký hiệu.
                        if (max > 1400.0)
                            continue;

                        primitives.Add(
                            new SmartGeometryPrimitive
                            {
                                Id =
                                    id,
                                Extents =
                                    ex,
                                Center =
                                    new Point3d(
                                        (ex.MinPoint.X +
                                         ex.MaxPoint.X) * 0.5,
                                        (ex.MinPoint.Y +
                                         ex.MaxPoint.Y) * 0.5,
                                        0.0)
                            });
                    }
                    catch
                    {
                    }
                }

                tr.Commit();
            }

            if (primitives.Count == 0)
                return result;

            const double clusterGap =
                70.0;

            HashSet<ObjectId> used =
                new HashSet<ObjectId>();

            foreach (SmartGeometryPrimitive seed
                in primitives)
            {
                if (used.Contains(
                        seed.Id))
                {
                    continue;
                }

                Queue<SmartGeometryPrimitive> queue =
                    new Queue<SmartGeometryPrimitive>();

                List<SmartGeometryPrimitive> cluster =
                    new List<SmartGeometryPrimitive>();

                queue.Enqueue(
                    seed);

                used.Add(
                    seed.Id);

                while (queue.Count > 0)
                {
                    SmartGeometryPrimitive current =
                        queue.Dequeue();

                    cluster.Add(
                        current);

                    if (cluster.Count > 24)
                        break;

                    foreach (SmartGeometryPrimitive other
                        in primitives)
                    {
                        if (used.Contains(
                                other.Id))
                        {
                            continue;
                        }

                        if (AreSmartGeometryExtentsNear(
                                current.Extents,
                                other.Extents,
                                clusterGap))
                        {
                            used.Add(
                                other.Id);

                            queue.Enqueue(
                                other);
                        }
                    }
                }

                if (cluster.Count <= 0 ||
                    cluster.Count > 24)
                {
                    continue;
                }

                double minX =
                    cluster.Min(
                        p =>
                            p.Extents.MinPoint.X);

                double minY =
                    cluster.Min(
                        p =>
                            p.Extents.MinPoint.Y);

                double maxX =
                    cluster.Max(
                        p =>
                            p.Extents.MaxPoint.X);

                double maxY =
                    cluster.Max(
                        p =>
                            p.Extents.MaxPoint.Y);

                double width =
                    maxX -
                    minX;

                double height =
                    maxY -
                    minY;

                double maxDim =
                    Math.Max(
                        width,
                        height);

                if (maxDim < 8.0 ||
                    maxDim > 1400.0)
                {
                    continue;
                }

                result.Add(
                    new SmartAuditGeometryCluster
                    {
                        Center =
                            new Point3d(
                                (minX + maxX) * 0.5,
                                (minY + maxY) * 0.5,
                                0.0),
                        Width =
                            width,
                        Height =
                            height,
                        EntityCount =
                            cluster.Count,
                        ObjectIds =
                            cluster
                                .Select(
                                    p =>
                                        p.Id)
                                .ToList()
                    });
            }

            return result;
        }

        private static bool IsSmartPointNearRecognized(
            Point3d point,
            List<SmartAuditRow> rows,
            double tolerance)
        {
            if (rows == null)
                return false;

            foreach (SmartAuditRow row
                in rows)
            {
                if (row == null ||
                    string.Equals(
                        row.Status,
                        "MISSING",
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (PlanDistance(
                        point,
                        row.Point) <=
                    tolerance)
                {
                    return true;
                }
            }

            return false;
        }

        private List<SmartAuditRow> DeduplicateSmartAuditRows(
            List<SmartAuditRow> rows)
        {
            List<SmartAuditRow> result =
                new List<SmartAuditRow>();

            if (rows == null)
                return result;

            foreach (SmartAuditRow row
                in rows)
            {
                if (row == null)
                    continue;

                SmartAuditRow duplicate =
                    result.FirstOrDefault(
                        r =>
                            string.Equals(
                                r.Status,
                                row.Status,
                                StringComparison.OrdinalIgnoreCase) &&
                            PlanDistance(
                                r.Point,
                                row.Point) <=
                            100.0);

                if (duplicate == null)
                {
                    result.Add(
                        row);
                }
                else
                {
                    // Nếu trùng vị trí, ưu tiên thông tin BLOCK rõ hơn hình học.
                    if (row.Source.StartsWith(
                            "BLOCK",
                            StringComparison.OrdinalIgnoreCase) &&
                        !duplicate.Source.StartsWith(
                            "BLOCK",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        duplicate.Name =
                            row.Name;

                        duplicate.Size =
                            row.Size;

                        duplicate.Source =
                            row.Source;

                        duplicate.Note =
                            row.Note;
                    }
                }
            }

            return result;
        }

        private void DrawSmartAuditMarkers(
            Document doc,
            List<SmartAuditRow> rows)
        {
            if (doc == null)
                return;

            Database db =
                doc.Database;

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                EnsureLayerExists(
                    tr,
                    db,
                    SmartAuditOkLayer,
                    false);

                EnsureLayerExists(
                    tr,
                    db,
                    SmartAuditCheckLayer,
                    false);

                EnsureLayerExists(
                    tr,
                    db,
                    SmartAuditMissingLayer,
                    false);

                SetReview3DLayerColor(
                    tr,
                    db,
                    SmartAuditOkLayer,
                    3);

                SetReview3DLayerColor(
                    tr,
                    db,
                    SmartAuditCheckLayer,
                    30);

                SetReview3DLayerColor(
                    tr,
                    db,
                    SmartAuditMissingLayer,
                    1);

                BlockTableRecord space =
                    (BlockTableRecord)tr.GetObject(
                        db.CurrentSpaceId,
                        OpenMode.ForWrite);

                List<ObjectId> oldMarkers =
                    new List<ObjectId>();

                foreach (ObjectId id
                    in space)
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent != null &&
                        !ent.IsErased &&
                        IsSmartAuditLayer(
                            ent.Layer))
                    {
                        oldMarkers.Add(
                            id);
                    }
                }

                foreach (ObjectId id
                    in oldMarkers)
                {
                    Entity ent =
                        tr.GetObject(
                            id,
                            OpenMode.ForWrite,
                            false) as Entity;

                    if (ent != null &&
                        !ent.IsErased)
                    {
                        ent.Erase();
                    }
                }

                foreach (SmartAuditRow row
                    in rows ?? new List<SmartAuditRow>())
                {
                    if (row == null)
                        continue;

                    string layer =
                        SmartAuditOkLayer;

                    double radius =
                        120.0;

                    string shortText =
                        "";

                    if (string.Equals(
                            row.Status,
                            "MISSING",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        layer =
                            SmartAuditMissingLayer;

                        radius =
                            260.0;

                        shortText =
                            "CHƯA NHẬN DIỆN";
                    }
                    else if (string.Equals(
                                 row.Status,
                                 "DN_CHECK",
                                 StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(
                                 row.Status,
                                 "NO_DN",
                                 StringComparison.OrdinalIgnoreCase))
                    {
                        layer =
                            SmartAuditCheckLayer;

                        radius =
                            210.0;

                        shortText =
                            row.Size;
                    }

                    Circle marker =
                        new Circle(
                            new Point3d(
                                row.Point.X,
                                row.Point.Y,
                                0.0),
                            Vector3d.ZAxis,
                            radius);

                    marker.SetDatabaseDefaults(
                        db);

                    marker.Layer =
                        layer;

                    marker.ColorIndex =
                        256;

                    space.AppendEntity(
                        marker);

                    tr.AddNewlyCreatedDBObject(
                        marker,
                        true);

                    if (!string.IsNullOrWhiteSpace(
                            shortText))
                    {
                        DBText label =
                            new DBText();

                        label.SetDatabaseDefaults(
                            db);

                        label.TextStyleId =
                            db.Textstyle;

                        label.TextString =
                            shortText;

                        label.Height =
                            110.0;

                        label.Layer =
                            layer;

                        label.ColorIndex =
                            256;

                        label.Position =
                            new Point3d(
                                row.Point.X +
                                radius * 1.2,
                                row.Point.Y +
                                radius * 0.7,
                                0.0);

                        space.AppendEntity(
                            label);

                        tr.AddNewlyCreatedDBObject(
                            label,
                            true);
                    }
                }

                tr.Commit();
            }

            try
            {
                doc.Editor.Regen();
            }
            catch
            {
            }
        }

        private void AttachPreviewToAuditRows(
            Document doc,
            List<SmartAuditRow> rows,
            List<SmartLegendAutoRow> legendRows)
        {
            if (doc == null ||
                rows == null ||
                rows.Count == 0)
            {
                return;
            }

            Database db =
                doc.Database;

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                foreach (SmartAuditRow row
                    in rows)
                {
                    if (row == null ||
                        row.Preview != null)
                    {
                        continue;
                    }

                    SmartLegendAutoRow legendRow =
                        FindMatchingLegendRowForAudit(
                            row,
                            legendRows);

                    if (legendRow != null &&
                        legendRow.Preview != null)
                    {
                        try
                        {
                            row.Preview =
                                new System.Drawing.Bitmap(
                                    legendRow.Preview);
                        }
                        catch
                        {
                        }

                        if (row.Preview != null)
                            continue;
                    }

                    try
                    {
                        if (!row.SourceId.IsNull)
                        {
                            row.Preview =
                                CreateSmartLegendPreviewBitmap(
                                    tr,
                                    new List<ObjectId> { row.SourceId },
                                    130,
                                    60);

                            if (row.Preview != null)
                                continue;
                        }

                        if (string.Equals(
                                row.MatchMode,
                                "GEOMETRY",
                                StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(
                                row.GeometryFingerprint))
                        {
                            List<ObjectId> ids =
                                FindGeometryObjectIdsByFingerprintNearPoint(
                                    tr,
                                    db,
                                    row.GeometryFingerprint,
                                    row.Point);

                            if (ids.Count > 0)
                            {
                                row.Preview =
                                    CreateSmartLegendPreviewBitmap(
                                        tr,
                                        ids,
                                        130,
                                        60);
                            }
                        }
                    }
                    catch
                    {
                    }
                }

                tr.Commit();
            }
        }

        private SmartLegendAutoRow FindMatchingLegendRowForAudit(
            SmartAuditRow row,
            List<SmartLegendAutoRow> legendRows)
        {
            if (row == null ||
                legendRows == null)
            {
                return null;
            }

            if (string.Equals(
                    row.MatchMode,
                    "GEOMETRY",
                    StringComparison.OrdinalIgnoreCase))
            {
                return
                    legendRows.FirstOrDefault(
                        r =>
                            r != null &&
                            string.Equals(
                                r.MatchMode,
                                "GEOMETRY",
                                StringComparison.OrdinalIgnoreCase) &&
                            string.Equals(
                                r.GeometryFingerprint,
                                row.GeometryFingerprint,
                                StringComparison.Ordinal));
            }

            return
                legendRows.FirstOrDefault(
                    r =>
                        r != null &&
                        !string.Equals(
                            r.MatchMode,
                            "GEOMETRY",
                            StringComparison.OrdinalIgnoreCase) &&
                        string.Equals(
                            r.BlockKey,
                            row.BlockKey,
                            StringComparison.OrdinalIgnoreCase));
        }

        private List<ObjectId> FindGeometryObjectIdsByFingerprintNearPoint(
            Transaction tr,
            Database db,
            string fingerprint,
            Point3d targetPoint)
        {
            List<ObjectId> result =
                new List<ObjectId>();

            if (tr == null ||
                db == null ||
                string.IsNullOrWhiteSpace(
                    fingerprint))
            {
                return result;
            }

            BlockTableRecord space =
                tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForRead) as BlockTableRecord;

            if (space == null)
                return result;

            List<ObjectId> primitiveIds =
                new List<ObjectId>();

            foreach (ObjectId id
                in space)
            {
                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent == null ||
                    ent.IsErased)
                {
                    continue;
                }

                if (ent is Line ||
                    ent is Arc ||
                    ent is Circle ||
                    ent is Polyline)
                {
                    try
                    {
                        Extents3d ex =
                            ent.GeometricExtents;

                        Point3d center =
                            new Point3d(
                                (ex.MinPoint.X + ex.MaxPoint.X) * 0.5,
                                (ex.MinPoint.Y + ex.MaxPoint.Y) * 0.5,
                                0.0);

                        if (PlanDistance(
                                center,
                                targetPoint) <=
                            450.0)
                        {
                            primitiveIds.Add(
                                id);
                        }
                    }
                    catch
                    {
                    }
                }
            }

            if (primitiveIds.Count == 0)
                return result;

            List<SmartAuditGeometryCluster> clusters =
                FindSmartAuditGeometryClusters(
                    db,
                    primitiveIds);

            SmartAuditGeometryCluster best =
                clusters
                    .Where(
                        c =>
                            c != null &&
                            c.ObjectIds != null &&
                            c.ObjectIds.Count > 0)
                    .OrderBy(
                        c =>
                            PlanDistance(
                                c.Center,
                                targetPoint))
                    .FirstOrDefault();

            if (best == null)
                return result;

            string bestFingerprint =
                BuildSmartGeometryFingerprint(
                    tr,
                    best.ObjectIds);

            if (!string.Equals(
                    bestFingerprint,
                    fingerprint,
                    StringComparison.Ordinal))
            {
                return result;
            }

            return
                best.ObjectIds
                    .ToList();
        }

        private bool ShowSmartAuditReportDialog(
            Document doc,
            List<SmartAuditRow> rows,
            List<string> legendZero)
        {
            if (doc == null)
                return false;

            rows =
                rows ??
                new List<SmartAuditRow>();

            legendZero =
                legendZero ??
                new List<string>();

            while (true)
            {
                SmartAuditRow zoomRow =
                    null;

                using (System.Windows.Forms.Form form =
                    new System.Windows.Forms.Form())
                using (System.Windows.Forms.Label summary =
                    new System.Windows.Forms.Label())
                using (System.Windows.Forms.DataGridView grid =
                    new System.Windows.Forms.DataGridView())
                using (System.Windows.Forms.Button applyButton =
                    new System.Windows.Forms.Button())
                using (System.Windows.Forms.Button cancelButton =
                    new System.Windows.Forms.Button())
                {
                    int recognized =
                        rows.Count(
                            r =>
                                r != null &&
                                !string.Equals(
                                    r.Status,
                                    "MISSING",
                                    StringComparison.OrdinalIgnoreCase));

                    int missing =
                        rows.Count(
                            r =>
                                r != null &&
                                string.Equals(
                                    r.Status,
                                    "MISSING",
                                    StringComparison.OrdinalIgnoreCase));

                    int certain =
                        rows.Count(
                            r =>
                                r != null &&
                                string.Equals(
                                    r.Status,
                                    "OK",
                                    StringComparison.OrdinalIgnoreCase));

                    int needCheck =
                        rows.Count(
                            r =>
                                r != null &&
                                (string.Equals(
                                     r.Status,
                                     "DN_CHECK",
                                     StringComparison.OrdinalIgnoreCase) ||
                                 string.Equals(
                                     r.Status,
                                     "NO_DN",
                                     StringComparison.OrdinalIgnoreCase)));

                    int total =
                        recognized +
                        missing;

                    double coverage =
                        total > 0
                            ? recognized * 100.0 /
                              total
                            : 100.0;

                    form.Text =
                        "KIỂM TRA SÓT VAN / THIẾT BỊ";

                    form.StartPosition =
                        System.Windows.Forms.FormStartPosition.CenterScreen;

                    form.Width =
                        1460;

                    form.Height =
                        760;

                    form.BackColor =
                        System.Drawing.Color.White;

                    form.MinimizeBox =
                        false;

                    summary.Left =
