                                grid.Rows[e.RowIndex].Tag as SmartAuditRow;

                            if (row == null)
                                return;

                            string columnName =
                                grid.Columns[e.ColumnIndex].Name;

                            if (string.Equals(
                                    columnName,
                                    "ZOOM",
                                    StringComparison.OrdinalIgnoreCase))
                            {
                                syncGridToRows();

                                zoomRow =
                                    row;

                                form.DialogResult =
                                    System.Windows.Forms.DialogResult.Retry;

                                form.Close();

                                return;
                            }

                            if (string.Equals(
                                    columnName,
                                    "EDIT",
                                    StringComparison.OrdinalIgnoreCase))
                            {
                                syncGridToRows();

                                bool changed =
                                    ShowSmartAuditEditDialog(
                                        row);

                                if (changed)
                                {
                                    row.UserEdited =
                                        true;

                                    grid.Rows[e.RowIndex]
                                        .Cells["NAME"].Value =
                                        row.Name;

                                    grid.Rows[e.RowIndex]
                                        .Cells["FOLLOW_DN"].Value =
                                        row.FollowDn;

                                    grid.Rows[e.RowIndex]
                                        .Cells["SIZE"].Value =
                                        row.Size;

                                    grid.Rows[e.RowIndex]
                                        .Cells["STATUS"].Value =
                                        GetSmartAuditStatusText(
                                            row.Status);

                                    grid.Rows[e.RowIndex]
                                        .Cells["NOTE"].Value =
                                        row.Note;

                                    if (string.Equals(
                                            row.Status,
                                            "MISSING",
                                            StringComparison.OrdinalIgnoreCase))
                                    {
                                        grid.Rows[e.RowIndex]
                                            .DefaultCellStyle.BackColor =
                                            System.Drawing.Color.MistyRose;
                                    }
                                    else if (!string.Equals(
                                                 row.Status,
                                                 "OK",
                                                 StringComparison.OrdinalIgnoreCase))
                                    {
                                        grid.Rows[e.RowIndex]
                                            .DefaultCellStyle.BackColor =
                                            System.Drawing.Color.LemonChiffon;
                                    }
                                    else
                                    {
                                        grid.Rows[e.RowIndex]
                                            .DefaultCellStyle.BackColor =
                                            System.Drawing.Color.Honeydew;
                                    }
                                }

                                return;
                            }

                            if (string.Equals(
                                    columnName,
                                    "IGNORE",
                                    StringComparison.OrdinalIgnoreCase))
                            {
                                syncGridToRows();

                                // STEP 18:
                                // Dòng đỏ CHƯA HỌC bị BỎ QUA => học NEGATIVE ngay.
                                LearnAiNegativeFromAuditRow(
                                    row);

                                rows.Remove(
                                    row);

                                grid.Rows.RemoveAt(
                                    e.RowIndex);

                                int number =
                                    1;

                                foreach (System.Windows.Forms.DataGridViewRow r
                                    in grid.Rows)
                                {
                                    if (r.Tag is SmartAuditRow)
                                    {
                                        r.Cells["STT"].Value =
                                            number++;
                                    }
                                }

                                return;
                            }
                        };

                    grid.CellDoubleClick +=
                        (s, e) =>
                        {
                            if (e.RowIndex < 0)
                                return;

                            SmartAuditRow row =
                                grid.Rows[e.RowIndex].Tag as SmartAuditRow;

                            if (row == null)
