                    {
                        nameBox.Focus();
                        nameBox.SelectAll();
                    };

                if (form.ShowDialog() !=
                    System.Windows.Forms.DialogResult.OK)
                {
                    return false;
                }

                string newName =
                    NormalizeSmartDisplayName(
                        nameBox.Text);

                if (string.IsNullOrWhiteSpace(
                        newName))
                {
                    System.Windows.Forms.MessageBox.Show(
                        "Bạn chưa nhập TÊN VAN / THIẾT BỊ.",
                        "SỬA NHẬN DIỆN",
                        System.Windows.Forms.MessageBoxButtons.OK,
                        System.Windows.Forms.MessageBoxIcon.Warning);

                    return false;
                }

                row.Name =
                    newName;

                row.FollowDn =
                    followDnBox.Checked;

                if (!row.FollowDn)
                {
                    row.Size =
                        "-";

                    row.Status =
                        "OK";
                }
                else
                {
                    string enteredSize =
                        (sizeBox.Text ?? "")
                            .Trim()
                            .ToUpperInvariant();

                    if (string.IsNullOrWhiteSpace(
                            enteredSize))
                    {
                        enteredSize =
                            "KHÔNG RÕ DN";
                    }

                    if (Regex.IsMatch(
                            enteredSize,
                            @"^\d{1,4}$"))
                    {
                        enteredSize =
                            "DN" +
                            enteredSize;
                    }

                    row.Size =
                        enteredSize;

                    if (string.Equals(
                            row.Size,
                            "CẦN KIỂM TRA",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        row.Status =
                            "DN_CHECK";
                    }
                    else if (string.Equals(
                                 row.Size,
                                 "KHÔNG RÕ DN",
                                 StringComparison.OrdinalIgnoreCase))
                    {
                        row.Status =
                            "NO_DN";
                    }
                    else
                    {
                        row.Status =
                            "OK";
                    }
                }

                row.UserEdited =
                    true;

                row.Note =
                    "Người dùng đã ZOOM kiểm tra và sửa thông tin thủ công.";

                return true;
            }
        }

        private void ApplySmartAuditCorrections(
            List<SmartAuditRow> rows)
        {
            if (rows == null)
                return;

            foreach (SmartAuditRow row
                in rows)
            {
                if (row == null)
                    continue;

                row.Name =
                    NormalizeSmartDisplayName(
                        row.Name);

                bool hasConfirmedName =
                    !string.IsNullOrWhiteSpace(
                        row.Name) &&
                    !string.Equals(
                        row.Name,
                        "CHƯA NHẬN DIỆN",
                        StringComparison.OrdinalIgnoreCase);

                if (!hasConfirmedName)
                {
                    row.Status =
                        "MISSING";

                    continue;
                }

                if (!row.FollowDn)
                {
                    row.Size =
                        "-";

                    row.Status =
                        "OK";
                }
                else if (string.Equals(
                             row.Size,
                             "CẦN KIỂM TRA",
                             StringComparison.OrdinalIgnoreCase))
                {
                    row.Status =
                        "DN_CHECK";
                }
                else if (string.Equals(
                             row.Size,
                             "KHÔNG RÕ DN",
                             StringComparison.OrdinalIgnoreCase) ||
                         string.IsNullOrWhiteSpace(
                             row.Size))
                {
                    row.Status =
                        "NO_DN";
                }
                else
                {
                    row.Status =
                        "OK";
                }

                if (row.Source.IndexOf(
                        "CHƯA HỌC",
                        StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    row.Source =
                        string.Equals(
                            row.MatchMode,
                            "GEOMETRY",
                            StringComparison.OrdinalIgnoreCase)
                            ? "HÌNH BỔ SUNG"
                            : "BLOCK BỔ SUNG";

                    row.Note =
                        "Người dùng đã kiểm tra vị trí và xác nhận tên.";
                }
            }

            // Nếu cùng một block/fingerprint xuất hiện nhiều lần,
            // sửa tên một lần sẽ áp cho toàn bộ các instance cùng ký hiệu.
            List<IGrouping<string, SmartAuditRow>> groups =
                rows
                    .Where(
                        r =>
                            r != null &&
                            !string.IsNullOrWhiteSpace(
                                GetSmartAuditRuleSignature(
                                    r)))
                    .GroupBy(
                        r =>
                            GetSmartAuditRuleSignature(
                                r),
                        StringComparer.OrdinalIgnoreCase)
                    .ToList();

            foreach (IGrouping<string, SmartAuditRow> group
                in groups)
            {
                SmartAuditRow confirmed =
                    group.FirstOrDefault(
                        r =>
                            !string.IsNullOrWhiteSpace(
                                r.Name) &&
                            !string.Equals(
                                r.Name,
                                "CHƯA NHẬN DIỆN",
                                StringComparison.OrdinalIgnoreCase));

                if (confirmed == null)
                    continue;

                foreach (SmartAuditRow item
                    in group)
                {
                    if (item == null)
                        continue;

                    if (string.Equals(
                            item.Name,
                            "CHƯA NHẬN DIỆN",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        item.Name =
                            confirmed.Name;

                        item.FollowDn =
                            confirmed.FollowDn;

                        if (!item.FollowDn)
                        {
                            item.Size =
                                "-";

                            item.Status =
                                "OK";
                        }
                        else if (string.Equals(
                                     item.Size,
                                     "CẦN KIỂM TRA",
                                     StringComparison.OrdinalIgnoreCase))
                        {
                            item.Status =
                                "DN_CHECK";
                        }
                        else if (string.Equals(
                                     item.Size,
                                     "KHÔNG RÕ DN",
                                     StringComparison.OrdinalIgnoreCase))
                        {
                            item.Status =
                                "NO_DN";
                        }
                        else
                        {
                            item.Status =
                                "OK";
                        }

                        item.Note =
                            "Tự cập nhật theo ký hiệu cùng mẫu đã được người dùng xác nhận.";
                    }
                }
            }
        }

        private static string GetSmartAuditRuleSignature(
            SmartAuditRow row)
        {
            if (row == null)
                return "";

            if (string.Equals(
                    row.MatchMode,
                    "GEOMETRY",
                    StringComparison.OrdinalIgnoreCase))
            {
                return
                    string.IsNullOrWhiteSpace(
                        row.GeometryFingerprint)
                        ? ""
                        : "GEO|" +
                          row.GeometryFingerprint;
            }

            return
                string.IsNullOrWhiteSpace(
                    row.BlockKey)
                    ? ""
                    : "BLOCK|" +
                      row.BlockKey;
        }

        private void UpdateSmartRulesFromAuditRows(
            List<SmartSymbolRule> currentRules,
            List<SmartAuditRow> auditRows)
        {
            if (currentRules == null ||
                auditRows == null)
            {
                return;
            }

            List<SmartSymbolRule> library =
                LoadSmartSymbolRules();

            foreach (SmartAuditRow row
                in auditRows)
            {
                if (row == null ||
                    string.Equals(
                        row.Status,
                        "MISSING",
                        StringComparison.OrdinalIgnoreCase) ||
                    string.IsNullOrWhiteSpace(
                        row.Name) ||
                    string.Equals(
                        row.Name,
                        "CHƯA NHẬN DIỆN",
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                string signature =
                    GetSmartAuditRuleSignature(
                        row);

                if (string.IsNullOrWhiteSpace(
                        signature))
                {
                    continue;
                }

                SmartSymbolRule updateRule =
                    new SmartSymbolRule
                    {
                        BlockKey =
                            row.BlockKey,
                        DisplayName =
                            row.Name,
                        SizeRule =
                            row.FollowDn
                                ? "THEO_ONG"
                                : "KHONG_SIZE",
                        MatchMode =
                            string.IsNullOrWhiteSpace(
                                row.MatchMode)
                                ? "BLOCK"
                                : row.MatchMode,
                        GeometryFingerprint =
                            row.GeometryFingerprint ?? "",
                        RasterSignature =
                            row.RasterSignature ?? ""
                    };

                UpsertSmartRuleList(
                    currentRules,
                    updateRule);

                UpsertSmartRuleList(
                    library,
                    updateRule);
            }

            SaveSmartSymbolRules(
                library);
        }

        private static void UpsertSmartRuleList(
            List<SmartSymbolRule> rules,
            SmartSymbolRule updateRule)
        {
            if (rules == null ||
                updateRule == null)
            {
                return;
            }

            SmartSymbolRule existing =
                null;

            if (string.Equals(
                    updateRule.MatchMode,
                    "GEOMETRY",
                    StringComparison.OrdinalIgnoreCase))
            {
                existing =
                    rules.FirstOrDefault(
                        r =>
                            r != null &&
                            string.Equals(
                                r.MatchMode,
                                "GEOMETRY",
                                StringComparison.OrdinalIgnoreCase) &&
                            string.Equals(
                                r.GeometryFingerprint,
                                updateRule.GeometryFingerprint,
                                StringComparison.Ordinal));
            }
            else
            {
                existing =
                    rules.FirstOrDefault(
                        r =>
                            r != null &&
                            !string.Equals(
                                r.MatchMode,
                                "GEOMETRY",
                                StringComparison.OrdinalIgnoreCase) &&
                            string.Equals(
                                r.BlockKey,
                                updateRule.BlockKey,
                                StringComparison.OrdinalIgnoreCase));
            }

            if (existing == null)
            {
                rules.Add(
                    updateRule);

                return;
            }

            existing.BlockKey =
                updateRule.BlockKey;

            existing.DisplayName =
                updateRule.DisplayName;

            existing.SizeRule =
                updateRule.SizeRule;

            existing.MatchMode =
                updateRule.MatchMode;

            existing.GeometryFingerprint =
                updateRule.GeometryFingerprint;

            existing.RasterSignature =
                updateRule.RasterSignature;
        }

        private List<SmartValveStatRow> BuildSmartStatsFromAuditRows(
            List<SmartAuditRow> rows)
        {
            if (rows == null)
            {
                return
                    new List<SmartValveStatRow>();
            }

            return
                rows
                    .Where(
                        r =>
                            r != null &&
                            !string.Equals(
                                r.Status,
                                "MISSING",
                                StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(
                                r.Name) &&
                            !string.Equals(
                                r.Name,
                                "CHƯA NHẬN DIỆN",
                                StringComparison.OrdinalIgnoreCase))
                    .GroupBy(
                        r =>
                            (r.Name ?? "") +
                            "\u001F" +
                            (r.FollowDn
                                ? (r.Size ?? "-")
                                : "-"),
                        StringComparer.OrdinalIgnoreCase)
                    .Select(
                        g =>
                        {
                            string[] parts =
                                g.Key.Split(
                                    '\u001F');

                            return
                                new SmartValveStatRow
                                {
                                    Loai =
                                        parts.Length > 0
                                            ? parts[0]
                                            : "",
                                    Size =
                                        parts.Length > 1
                                            ? parts[1]
                                            : "-",
                                    SoLuong =
                                        g.Count()
                                };
                        })
                    .OrderBy(
                        r =>
                            r.Loai)
                    .ThenByDescending(
                        r =>
                            SmartSizeSortValue(
                                r.Size))
                    .ToList();
        }



        private static int GetSmartAuditStatusOrder(
            string status)
        {
            if (string.Equals(
                    status,
                    "MISSING",
                    StringComparison.OrdinalIgnoreCase))
            {
                return 0;
            }

            if (string.Equals(
                    status,
                    "DN_CHECK",
                    StringComparison.OrdinalIgnoreCase) ||
                string.Equals(
                    status,
                    "NO_DN",
                    StringComparison.OrdinalIgnoreCase))
            {
                return 1;
            }

            return 2;
        }

        private static string GetSmartAuditStatusText(
            string status)
        {
            if (string.Equals(
                    status,
                    "MISSING",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "⚠ CHƯA NHẬN DIỆN";
            }

            if (string.Equals(
                    status,
                    "DN_CHECK",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "⚠ DN CHƯA CHẮC";
            }

            if (string.Equals(
                    status,
                    "NO_DN",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "⚠ KHÔNG RÕ DN";
            }

            return "✓ OK";
        }

        private void AppendGlobalAiPipeCandidates(
            Database db,
            List<SmartPipeCandidate> candidates)
        {
            if (db == null ||
                candidates == null)
            {
                return;
            }

            HashSet<ObjectId> existingIds =
                new HashSet<ObjectId>(
                    candidates
                        .Where(
                            c =>
                                c != null &&
                                !c.Id.IsNull)
                        .Select(
                            c =>
                                c.Id));

            try
            {
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    BlockTableRecord space =
                        tr.GetObject(
                            db.CurrentSpaceId,
                            OpenMode.ForRead,
                            false) as BlockTableRecord;

                    if (space == null)
                        return;

                    foreach (ObjectId id
                        in space)
                    {
                        if (existingIds.Contains(
                                id))
                        {
                            continue;
                        }

                        Curve curve =
                            tr.GetObject(
                                id,
                                OpenMode.ForRead,
                                false) as Curve;

                        if (curve == null ||
                            curve.IsErased)
                        {
                            continue;
                        }

                        string layer =
                            (curve.Layer ?? "")
                                .Trim();

                        string size =
                            ExtractAiPipeSizeFromLayer(
                                layer);

                        if (string.IsNullOrWhiteSpace(
                                size))
                        {
                            continue;
                        }

                        candidates.Add(
                            new SmartPipeCandidate
                            {
                                Id =
                                    id,
                                Size =
                                    size,
                                Layer =
                                    layer,
                                IsAiGenerated =
                                    true,
                                Confidence =
                                    0.99
                            });

                        existingIds.Add(
                            id);
                    }

                    tr.Commit();
                }
            }
            catch
            {
                // AI overlay là nguồn tăng cường.
                // Nếu CurrentSpace không đọc được thì vẫn giữ candidate từ vùng quét.
            }
        }

        private bool TryInferSmartBlockPipeSize(
            Transaction tr,
            BlockReference blockReference,
            List<SmartPipeCandidate> candidates,
            out string size,
            out bool uncertain)
        {
            size =
                "";

            uncertain =
                false;

            if (blockReference == null)
                return false;

            Extents3d? deviceExtents =
                null;

            try
            {
                deviceExtents =
                    blockReference.GeometricExtents;
            }
            catch
            {
            }

            return
                TryInferSmartPipeSizeFusion(
                    tr,
                    blockReference.Position,
                    deviceExtents,
                    candidates,
                    out size,
                    out uncertain);
        }

        private bool TryInferSmartBlockPipeSize(
            Transaction tr,
            Point3d blockPosition,
            List<SmartPipeCandidate> candidates,
            out string size,
            out bool uncertain)
        {
            return
                TryInferSmartPipeSizeFusion(
                    tr,
                    blockPosition,
                    null,
                    candidates,
                    out size,
                    out uncertain);
        }

        private bool TryInferSmartPipeSizeFusion(
            Transaction tr,
            Point3d insertionPoint,
            Extents3d? deviceExtents,
            List<SmartPipeCandidate> candidates,
            out string size,
            out bool uncertain)
        {
            size =
                "";

            uncertain =
                false;

            if (tr == null ||
                candidates == null ||
                candidates.Count == 0)
            {
                return false;
            }

            List<Point3d> referencePoints =
                GetSmartDeviceReferencePoints(
                    insertionPoint,
                    deviceExtents);

            double deviceDiagonal =
                0.0;

            if (deviceExtents.HasValue)
            {
                Extents3d ex =
                    deviceExtents.Value;

                deviceDiagonal =
                    PlanDistance(
                        ex.MinPoint,
                        ex.MaxPoint);
            }

            // Với block có base point đặt lệch, khoảng cách theo insertion point có thể sai.
            // Ngưỡng được nới theo kích thước symbol nhưng vẫn có trần để không hút nhầm ống xa.
            double maxSearchDistance =
                Math.Min(
                    1400.0,
                    Math.Max(
                        650.0,
                        deviceDiagonal * 1.25 +
                        250.0));

            // STEP22A/22B - GRAPH + GNN CONTEXT:
            // lấy thêm phiếu từ topology graph. Graph không thay thế phép đo hình học;
            // nó chỉ tăng context và xử lý các trường hợp nhiều đoạn/nhánh giống nhau.
            MepGraphDnInference graphInference =
                GetGraphDnInference(
                    insertionPoint,
                    deviceExtents);

            MepGraphGnnClassifier.Prediction gnnPrediction =
                GetGnnDnPrediction(
                    insertionPoint,
                    deviceExtents);

            bool gnnStrong =
                gnnPrediction != null &&
                gnnPrediction.Success &&
                gnnPrediction.Confidence >=
                    0.84 &&
                gnnPrediction.Margin >=
                    0.08;

            Dictionary<string, SmartPipeSizeVote> votes =
                new Dictionary<string, SmartPipeSizeVote>(
                    StringComparer.OrdinalIgnoreCase);

            foreach (SmartPipeCandidate candidate
                in candidates)
            {
                if (candidate == null ||
                    candidate.Id.IsNull ||
                    string.IsNullOrWhiteSpace(
                        candidate.Size))
                {
                    continue;
                }

                Curve curve =
                    tr.GetObject(
                        candidate.Id,
                        OpenMode.ForRead,
                        false) as Curve;

                if (curve == null ||
                    curve.IsErased)
                {
                    continue;
                }

                double minDistance =
                    double.MaxValue;

                foreach (Point3d p
                    in referencePoints)
                {
                    double distance =
                        GetSmartDistancePointToCurve(
                            curve,
                            p);

                    if (distance <
                        minDistance)
                    {
                        minDistance =
                            distance;
                    }
                }

                bool crossesDevice =
                    false;

                if (deviceExtents.HasValue)
                {
                    crossesDevice =
                        IsSmartCurveInsideExpandedDeviceBox(
                            curve,
                            deviceExtents.Value,
                            130.0);
                }

                if (!crossesDevice &&
                    (double.IsNaN(
                         minDistance) ||
                     double.IsInfinity(
                         minDistance) ||
                     minDistance >
                         maxSearchDistance))
                {
                    continue;
                }

                double confidence =
                    Math.Max(
                        0.50,
                        Math.Min(
                            1.00,
                            candidate.Confidence));

                double score =
                    minDistance /
                    confidence;

                // Mô hình ống AI là nguồn đã hợp nhất Geometry + Text + Topology.
                if (candidate.IsAiGenerated)
                {
                    score -=
                        180.0;
                }

                // Nếu tim ống thực sự xuyên qua vùng hình học của symbol,
                // đây là bằng chứng mạnh hơn khoảng cách đến block insertion point.
                if (crossesDevice)
                {
                    score -=
                        360.0;
                }

                score =
                    Math.Max(
                        0.0,
                        score);

                if (!votes.TryGetValue(
                        candidate.Size,
                        out SmartPipeSizeVote vote))
                {
                    vote =
                        new SmartPipeSizeVote
                        {
                            Size =
                                candidate.Size
                        };

                    votes[candidate.Size] =
                        vote;
                }

                vote.SupportCount++;

                if (candidate.IsAiGenerated)
                {
                    vote.AiSupportCount++;
                }

                if (crossesDevice)
                {
                    vote.CrossesDeviceBox =
                        true;
                }

                if (score <
                    vote.BestScore)
                {
                    vote.BestScore =
                        score;
                }
            }

            if (votes.Count == 0)
            {
                if (graphInference != null &&
                    graphInference.Found)
                {
                    size =
                        graphInference.Dn;

                    uncertain =
                        graphInference.Ambiguous ||
                        graphInference.Confidence <
                            0.72;

                    if (gnnStrong)
                    {
                        bool agrees =
                            string.Equals(
                                gnnPrediction.Dn,
                                graphInference.Dn,
                                StringComparison.OrdinalIgnoreCase);

                        if (agrees)
                        {
                            if (gnnPrediction.Confidence >=
                                    0.90 &&
                                gnnPrediction.Margin >=
                                    0.12)
                            {
                                uncertain =
                                    false;
                            }
                        }
                        else if (graphInference.Ambiguous &&
                                 gnnPrediction.Confidence >=
                                    0.90 &&
                                 gnnPrediction.Margin >=
                                    0.12)
                        {
                            size =
                                gnnPrediction.Dn;

                            uncertain =
                                false;
                        }
                        else
                        {
                            uncertain =
                                true;
                        }
                    }

                    return true;
                }

                if (gnnStrong &&
                    gnnPrediction.Confidence >=
                        0.88)
                {
                    size =
                        gnnPrediction.Dn;

                    uncertain =
                        gnnPrediction.Margin <
                            0.12;

                    return true;
                }

                return false;
            }

            List<SmartPipeSizeVote> ordered =
                votes.Values
                    .OrderBy(
                        v =>
                            v.EffectiveScore)
                    .ThenByDescending(
                        v =>
                            v.AiSupportCount)
                    .ThenByDescending(
                        v =>
                            v.SupportCount)
                    .ToList();

            SmartPipeSizeVote best =
                ordered[0];

            // Không có bằng chứng đủ gần -> không gán.
            if (best.EffectiveScore >
                900.0)
            {
                return false;
            }

            size =
                best.Size;

            // Graph đồng ý với geometry vote => tăng độ chắc chắn.
            // Graph khác với geometry vote mạnh => không ép, chỉ đánh dấu cần kiểm tra.
            if (graphInference != null &&
                graphInference.Found &&
                graphInference.Confidence >=
                    0.82)
            {
                bool graphAgrees =
                    string.Equals(
                        graphInference.Dn,
                        best.Size,
                        StringComparison.OrdinalIgnoreCase);

                if (!graphAgrees &&
                    graphInference.Confidence >=
                        0.90)
                {
                    bool bestPhysicalStrong =
                        best.CrossesDeviceBox ||
                        best.AiSupportCount > 0 ||
                        best.SupportCount >= 2;

                    if (!bestPhysicalStrong)
                    {
                        size =
                            graphInference.Dn;

                        uncertain =
                            graphInference.Ambiguous;

                        return true;
                    }

                    uncertain =
                        true;
                }
            }

            if (ordered.Count == 1)
            {
                if (graphInference != null &&
                    graphInference.Found &&
                    !string.Equals(
                        graphInference.Dn,
                        size,
                        StringComparison.OrdinalIgnoreCase) &&
                    graphInference.Confidence >=
                        0.90)
                {
                    uncertain =
                        true;
                }

                return true;
            }

            SmartPipeSizeVote second =
                ordered[1];

            // AI overlay xuyên qua symbol hoặc có >=2 support cùng DN:
            // chỉ coi DN khác là xung đột nếu nó cũng có bằng chứng thực sự mạnh.
            bool bestIsStrong =
                best.CrossesDeviceBox ||
                best.AiSupportCount > 0 ||
                best.SupportCount >= 2;

            bool secondIsStrong =
                second.CrossesDeviceBox ||
                second.AiSupportCount > 0 ||
                second.SupportCount >= 2;

            if (gnnStrong)
            {
                bool gnnAgreesBest =
                    string.Equals(
                        gnnPrediction.Dn,
                        best.Size,
                        StringComparison.OrdinalIgnoreCase);

                bool graphAgreesGnn =
                    graphInference != null &&
                    graphInference.Found &&
                    string.Equals(
                        graphInference.Dn,
                        gnnPrediction.Dn,
                        StringComparison.OrdinalIgnoreCase);

                if (!gnnAgreesBest &&
                    gnnPrediction.Confidence >=
                        0.92 &&
                    gnnPrediction.Margin >=
                        0.15)
                {
                    if (!bestIsStrong &&
                        (graphAgreesGnn ||
                         graphInference == null ||
                         !graphInference.Found ||
                         graphInference.Ambiguous))
                    {
                        size =
                            gnnPrediction.Dn;

                        uncertain =
                            false;

                        return true;
                    }

                    // Geometry mạnh mà GNN phản đối => bắt user kiểm tra,
                    // tuyệt đối không cho GNN ghi đè mù quáng.
                    if (bestIsStrong)
                    {
                        uncertain =
                            true;
                    }
                }
            }

            double scoreGap =
                second.EffectiveScore -
                best.EffectiveScore;

            if (secondIsStrong &&
                scoreGap < 90.0)
            {
                if (graphInference != null &&
                    graphInference.Found &&
                    !graphInference.Ambiguous &&
                    graphInference.Confidence >=
                        0.90 &&
                    string.Equals(
                        graphInference.Dn,
                        best.Size,
                        StringComparison.OrdinalIgnoreCase))
                {
                    uncertain =
                        false;

                    return true;
                }

                if (gnnStrong &&
                    gnnPrediction.Confidence >=
                        0.90 &&
                    gnnPrediction.Margin >=
                        0.12)
                {
                    bool gnnAgreesBest =
                        string.Equals(
                            gnnPrediction.Dn,
                            best.Size,
                            StringComparison.OrdinalIgnoreCase);

                    bool graphCompatible =
                        graphInference == null ||
                        !graphInference.Found ||
                        graphInference.Ambiguous ||
                        string.Equals(
                            graphInference.Dn,
                            gnnPrediction.Dn,
                            StringComparison.OrdinalIgnoreCase);

                    if (gnnAgreesBest &&
                        graphCompatible)
                    {
                        uncertain =
                            false;

                        return true;
                    }
                }

                uncertain =
                    true;

                return true;
            }

            // Nếu cả hai chỉ là "gần" chứ không xuyên symbol,
            // cần khoảng cách tách biệt rõ hơn mới chốt.
            if (!bestIsStrong &&
                scoreGap < 150.0)
            {
                if (graphInference != null &&
                    graphInference.Found &&
                    !graphInference.Ambiguous &&
                    graphInference.Confidence >=
                        0.88)
                {
                    size =
                        graphInference.Dn;

                    uncertain =
                        false;

                    return true;
                }

                if (gnnStrong &&
                    gnnPrediction.Confidence >=
                        0.88 &&
                    gnnPrediction.Margin >=
                        0.10)
                {
                    bool graphCompatible =
                        graphInference == null ||
                        !graphInference.Found ||
                        graphInference.Ambiguous ||
                        string.Equals(
                            graphInference.Dn,
                            gnnPrediction.Dn,
                            StringComparison.OrdinalIgnoreCase);

                    if (graphCompatible)
                    {
                        size =
                            gnnPrediction.Dn;

                        uncertain =
                            false;

                        return true;
                    }
                }

                uncertain =
                    true;

                return true;
            }

            return true;
        }

        private List<Point3d> GetSmartDeviceReferencePoints(
            Point3d insertionPoint,
            Extents3d? deviceExtents)
        {
            List<Point3d> points =
                new List<Point3d>
                {
                    new Point3d(
                        insertionPoint.X,
                        insertionPoint.Y,
                        0.0)
                };

            if (!deviceExtents.HasValue)
                return points;

            Extents3d ex =
                deviceExtents.Value;

            double minX =
                ex.MinPoint.X;

            double minY =
                ex.MinPoint.Y;

            double maxX =
                ex.MaxPoint.X;

            double maxY =
                ex.MaxPoint.Y;

            double cx =
                (minX + maxX) * 0.5;

            double cy =
                (minY + maxY) * 0.5;

            points.Add(
                new Point3d(
                    cx,
                    cy,
                    0.0));

            points.Add(
                new Point3d(
                    minX,
                    cy,
                    0.0));

            points.Add(
                new Point3d(
                    maxX,
                    cy,
                    0.0));

            points.Add(
                new Point3d(
                    cx,
                    minY,
                    0.0));

            points.Add(
                new Point3d(
                    cx,
                    maxY,
                    0.0));

            return points;
        }

        private bool IsSmartCurveInsideExpandedDeviceBox(
            Curve curve,
            Extents3d extents,
            double margin)
        {
            if (curve == null)
                return false;

            double minX =
                extents.MinPoint.X -
                margin;

            double minY =
                extents.MinPoint.Y -
                margin;

            double maxX =
                extents.MaxPoint.X +
                margin;

            double maxY =
                extents.MaxPoint.Y +
                margin;

            Point3d center =
                new Point3d(
                    (extents.MinPoint.X +
                     extents.MaxPoint.X) * 0.5,
                    (extents.MinPoint.Y +
                     extents.MaxPoint.Y) * 0.5,
                    curve.StartPoint.Z);

            try
            {
                Point3d closest =
                    curve.GetClosestPointTo(
                        center,
                        false);

                if (closest.X >= minX &&
                    closest.X <= maxX &&
                    closest.Y >= minY &&
                    closest.Y <= maxY)
                {
                    return true;
                }
            }
            catch
            {
            }

            try
            {
                Point3d start =
                    curve.StartPoint;

                if (start.X >= minX &&
                    start.X <= maxX &&
                    start.Y >= minY &&
                    start.Y <= maxY)
                {
                    return true;
                }

                Point3d end =
                    curve.EndPoint;

                if (end.X >= minX &&
                    end.X <= maxX &&
                    end.Y >= minY &&
                    end.Y <= maxY)
                {
                    return true;
                }
            }
            catch
            {
            }

            return false;
        }


        private double GetSmartDistancePointToCurve(
            Curve curve,
            Point3d point)
        {
            if (curve == null)
                return double.MaxValue;

            try
            {
                Point3d closest =
                    curve.GetClosestPointTo(
                        point,
                        false);

                return
                    Math.Sqrt(
                        Math.Pow(
                            closest.X -
                            point.X,
                            2.0) +
                        Math.Pow(
                            closest.Y -
                            point.Y,
                            2.0));
            }
            catch
            {
                try
                {
                    return
                        Math.Min(
                            PlanDistance(
                                point,
                                curve.StartPoint),
                            PlanDistance(
                                point,
                                curve.EndPoint));
                }
                catch
                {
                    return double.MaxValue;
                }
            }
        }

        private bool TryExtractSmartPipeSize(
            string layer,
            out string size)
        {
            size =
                "";

            if (string.IsNullOrWhiteSpace(
                    layer))
            {
                return false;
            }

            // Chức năng SMART chỉ đọc size trực tiếp từ tên layer.
            // Không gọi TryParseAutomaticPipeSize(ctx=null) nữa để tách hoàn toàn
            // khỏi trạng thái UI/vật liệu đang chọn.
            Match directDn =
                Regex.Match(
                    layer,
                    @"(?<![A-Z0-9])DN\s*(\d+(?:\.\d+)?)",
                    RegexOptions.IgnoreCase);

            if (directDn.Success)
            {
                size =
                    "DN" +
                    directDn.Groups[1].Value;

                return true;
            }

            Match outside =
                Regex.Match(
                    layer,
                    @"(?<![A-Z0-9])(?:D|Ø|Φ)\s*(\d+(?:\.\d+)?)",
                    RegexOptions.IgnoreCase);

            if (outside.Success &&
                double.TryParse(
                    outside.Groups[1].Value,
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out double outsideValue))
            {
                if (TryConvertOutsideDiameterToNominal(
                        outsideValue,
                        out double nominal))
                {
                    size =
                        "DN" +
                        FormatSizeNumber(
                            nominal);
                }
                else
                {
                    size =
                        "D" +
                        FormatSizeNumber(
                            outsideValue);
                }

                return true;
            }

            return false;
        }


        private static double SmartSizeSortValue(
            string size)
        {
            if (string.IsNullOrWhiteSpace(
                    size))
            {
                return -1.0;
            }

            Match m =
                Regex.Match(
                    size,
                    @"(\d+(?:\.\d+)?)");

            if (!m.Success)
                return -1.0;

            if (double.TryParse(
                    m.Groups[1].Value,
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out double value))
            {
                return value;
            }

            return -1.0;
        }

        private static string GetSmartLegendText(
            Entity ent)
        {
            if (ent is DBText dbText)
            {
                return
                    dbText.TextString ?? "";
            }

            if (ent is MText mText)
            {
                return
                    mText.Text ?? "";
            }

            return "";
        }

        private static string NormalizeSmartDisplayName(
            string value)
        {
            if (string.IsNullOrWhiteSpace(
                    value))
            {
                return "";
            }

            string result =
                value.Trim();

            // Nhiều bản vẽ MEP cũ dùng font TCVN3/ABC (.VnTime, .VnArial...).
            // Khi đọc TextString từ AutoCAD, chuỗi bên trong vẫn là mã TCVN3.
            // Nếu đưa thẳng vào Table dùng font Unicode thì sẽ ra kiểu:
            //   c«ng t¸c dßng ch¶y kÌm gi¸m s¸t
            // Thực tế phải là:
            //   công tác dòng chảy kèm giám sát
            if (LooksLikeTcvn3SmartText(
                    result))
            {
                result =
                    ConvertTcvn3SmartTextToUnicode(
                        result);
            }

            result =
                Regex.Replace(
                    result,
                    @"\s+",
                    " ");

            return result;
        }

        private static bool LooksLikeTcvn3SmartText(
            string value)
        {
            if (string.IsNullOrEmpty(
                    value))
            {
                return false;
            }

            // Chỉ dùng các ký tự "đặc trưng mạnh" để nhận diện,
            // tránh chuyển nhầm chuỗi Unicode tiếng Việt bình thường.
            const string strongLegacyChars =
                "µ¸¶·¹¨»¾¼½Æ©ÇÊÈÉË®ÌÐÎÏÑªÒÕÓÔÖ×ÝØÜÞß«¬­¡¢§£¤¥¦";

            foreach (char ch in value)
            {
                if (strongLegacyChars.IndexOf(
                        ch) >= 0)
                {
                    return true;
                }
            }

            return false;
        }

        private static string ConvertTcvn3SmartTextToUnicode(
            string value)
        {
            if (string.IsNullOrEmpty(
                    value))
            {
                return value ?? "";
            }

            // Bảng mã TCVN3/ABC thông dụng.
            const string legacyLower =
                "µ¸¶·¹¨»¾¼½Æ©ÇÊÈÉË®ÌÐÎÏÑªÒÕÓÔÖ×ÝØÜÞßãáâä«åèæçé¬êíëìîïóñòô­õøö÷ù";

            const string unicodeLower =
                "àáảãạăằắẳẵặâầấẩẫậđèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữự";

            StringBuilder sb =
                new StringBuilder(
                    value.Length);

            foreach (char ch in value)
            {
                int index =
                    legacyLower.IndexOf(
                        ch);

                if (index >= 0 &&
                    index <
                    unicodeLower.Length)
                {
                    sb.Append(
                        unicodeLower[index]);

                    continue;
                }

                // Các chữ cái hoa cơ sở của TCVN3.
                switch (ch)
                {
                    case '¡':
                        sb.Append('Ă');
                        break;

                    case '¢':
                        sb.Append('Â');
                        break;

                    case '§':
                        sb.Append('Đ');
                        break;

                    case '£':
                        sb.Append('Ê');
                        break;

                    case '¤':
                        sb.Append('Ô');
                        break;

                    case '¥':
                        sb.Append('Ơ');
                        break;

                    case '¦':
                        sb.Append('Ư');
                        break;

                    default:
                        sb.Append(ch);
                        break;
                }
            }

            return
                sb.ToString();
        }


        private static string NormalizeSmartSymbolKey(
            string value)
        {
            if (string.IsNullOrWhiteSpace(
                    value))
            {
                return "";
            }

            return
                NormalizeShopKey(
                    value);
        }

        private List<SmartSymbolRule> LoadSmartSymbolRules()
        {
            List<SmartSymbolRule> result =
                new List<SmartSymbolRule>();

            try
            {
                string path =
                    SmartSymbolLibraryPath;

                if (!File.Exists(path))
                    return result;

                foreach (string line
                    in File.ReadAllLines(
                        path,
                        Encoding.UTF8))
                {
                    if (string.IsNullOrWhiteSpace(
                            line))
                    {
                        continue;
                    }

                    string[] parts =
                        line.Split('|');

                    if (parts.Length < 3)
                        continue;

                    string blockKey =
                        DecodeSmartField(
                            parts[0]);

                    string displayName =
                        NormalizeSmartDisplayName(
                            DecodeSmartField(
                                parts[1]));

                    string sizeRule =
                        DecodeSmartField(
                            parts[2]);

                    string matchMode =
                        parts.Length >= 4
                            ? DecodeSmartField(
                                parts[3])
                            : "BLOCK";

                    string geometryFingerprint =
                        parts.Length >= 5
                            ? DecodeSmartField(
                                parts[4])
                            : "";

                    string rasterSignature =
                        parts.Length >= 6
                            ? DecodeSmartField(
                                parts[5])
                            : "";

                    if (string.IsNullOrWhiteSpace(
                            blockKey) ||
                        string.IsNullOrWhiteSpace(
                            displayName))
                    {
                        continue;
                    }

                    result.Add(
                        new SmartSymbolRule
                        {
                            BlockKey =
                                blockKey,
                            DisplayName =
                                displayName,
                            SizeRule =
                                string.IsNullOrWhiteSpace(
                                    sizeRule)
                                    ? "THEO_ONG"
                                    : sizeRule,
                            MatchMode =
                                string.IsNullOrWhiteSpace(
                                    matchMode)
                                    ? "BLOCK"
                                    : matchMode,
                            GeometryFingerprint =
                                geometryFingerprint ?? "",
                            RasterSignature =
                                rasterSignature ?? ""
                        });
                }
            }
            catch
            {
            }

            return result;
        }

        private void SaveSmartSymbolRules(
            List<SmartSymbolRule> rules)
        {
            if (rules == null)
                return;

            try
            {
                string path =
                    SmartSymbolLibraryPath;

                List<string> lines =
                    rules
                        .Where(
                            x =>
                                x != null &&
                                !string.IsNullOrWhiteSpace(
                                    x.BlockKey) &&
                                !string.IsNullOrWhiteSpace(
                                    x.DisplayName))
                        .GroupBy(
                            x =>
                                x.BlockKey,
                            StringComparer.OrdinalIgnoreCase)
                        .Select(
                            g =>
                                g.Last())
                        .OrderBy(
                            x =>
                                x.DisplayName)
                        .Select(
                            x =>
                                EncodeSmartField(
                                    x.BlockKey) +
                                "|" +
                                EncodeSmartField(
                                    x.DisplayName) +
                                "|" +
                                EncodeSmartField(
                                    x.SizeRule) +
                                "|" +
                                EncodeSmartField(
                                    x.MatchMode) +
                                "|" +
                                EncodeSmartField(
                                    x.GeometryFingerprint) +
                                "|" +
                                EncodeSmartField(
                                    x.RasterSignature))
                        .ToList();

                File.WriteAllLines(
                    path,
                    lines,
                    Encoding.UTF8);
            }
            catch (System.Exception ex)
            {
                MessageBox.Show(
                    "Không lưu được thư viện ký hiệu:\n" +
                    ex.Message,
                    "NHẬN DIỆN THÔNG MINH");
            }
        }

        private static string EncodeSmartField(
            string value)
        {
            byte[] bytes =
                Encoding.UTF8.GetBytes(
                    value ?? "");

            return
                Convert.ToBase64String(
                    bytes);
        }

        private static string DecodeSmartField(
            string value)
        {
            try
            {
                byte[] bytes =
                    Convert.FromBase64String(
                        value ?? "");

                return
                    Encoding.UTF8.GetString(
                        bytes);
            }
            catch
            {
                return "";
            }
        }

        private void XuatBangThongKeVanThongMinh(
            List<SmartValveStatRow> rows)
        {
            if (rows == null ||
                rows.Count == 0)
            {
                return;
            }

            Document doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            Database db =
                doc.Database;

            Editor ed =
                doc.Editor;

            Point3d tablePosition =
                Point3d.Origin;

            bool replaceExisting =
                false;

            // Nếu bảng gần nhất còn tồn tại trong DWG,
            // lấy đúng Position và thay bảng ở cùng chỗ.
            if (!_lastSmartStatsTableId.IsNull &&
                _lastSmartStatsTableId.IsValid)
            {
                try
                {
                    using (doc.LockDocument())
                    using (Transaction tr =
                        db.TransactionManager.StartTransaction())
                    {
                        Table oldTable =
                            tr.GetObject(
                                _lastSmartStatsTableId,
                                OpenMode.ForRead,
                                false) as Table;

                        if (oldTable != null &&
                            !oldTable.IsErased)
                        {
                            tablePosition =
                                oldTable.Position;

                            replaceExisting =
                                true;
                        }

                        tr.Commit();
                    }
                }
                catch
                {
                    replaceExisting =
                        false;
                }
            }

            if (!replaceExisting)
            {
                _smartValveStage =
                    "SCAN_OUTPUT_PICK_POINT";

                PromptPointResult ppr =
                    ed.GetPoint(
                        "\nKích chọn vị trí đặt BẢNG VAN / THIẾT BỊ THÔNG MINH: ");

                if (ppr.Status !=
                    PromptStatus.OK)
                {
                    return;
                }

                tablePosition =
                    ppr.Value;
            }

            _smartValveStage =
                "SCAN_OUTPUT_WRITE_TABLE";

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                BlockTableRecord btr =
                    (BlockTableRecord)tr.GetObject(
                        db.CurrentSpaceId,
                        OpenMode.ForWrite);

                if (replaceExisting &&
                    !_lastSmartStatsTableId.IsNull &&
                    _lastSmartStatsTableId.IsValid)
                {
                    try
                    {
                        Table oldTable =
                            tr.GetObject(
                                _lastSmartStatsTableId,
                                OpenMode.ForWrite,
                                false) as Table;

                        if (oldTable != null &&
                            !oldTable.IsErased)
                        {
                            oldTable.Erase();
                        }
                    }
                    catch
                    {
                    }
                }

                Table table =
                    new Table
                    {
                        TableStyle =
                            db.Tablestyle
                    };

                table.SetDatabaseDefaults(
                    db);

                table.Color =
                    Autodesk.AutoCAD.Colors.Color
                        .FromColorIndex(
                            ColorMethod.ByAci,
                            2);

                int rowCount =
                    rows.Count + 2;

                table.SetSize(
                    rowCount,
                    4);

                table.Position =
                    tablePosition;

                double sf =
                    12.0;

                double textH =
                    140.0 * sf;

                for (int r = 0;
                    r < table.Rows.Count;
                    r++)
                {
                    table.Rows[r].Height =
                        (r == 0
                            ? 420.0
                            : 320.0) * sf;

                    for (int c = 0;
                        c < 4;
                        c++)
                    {
                        table.Cells[r, c]
                            .TextStyleId =
                            db.Textstyle;

                        table.Cells[r, c]
                            .TextHeight =
                            textH;
                    }
                }

                table.Columns[0].Width =
                    900.0 * sf;

                table.Columns[1].Width =
                    4400.0 * sf;

                table.Columns[2].Width =
                    2200.0 * sf;

                table.Columns[3].Width =
                    1800.0 * sf;

                try
                {
                    table.MergeCells(
                        CellRange.Create(
                            table,
                            0,
                            0,
                            0,
                            3));
                }
                catch
                {
                }

                table.Cells[0, 0].TextString =
                    "BẢNG THỐNG KÊ VAN / THIẾT BỊ THÔNG MINH";

                table.Cells[0, 0].Alignment =
                    CellAlignment.MiddleCenter;

                table.Cells[1, 0].TextString =
                    "STT";

                table.Cells[1, 1].TextString =
                    "LOẠI VAN / THIẾT BỊ";

                table.Cells[1, 2].TextString =
                    "SIZE";

                table.Cells[1, 3].TextString =
                    "SL (cái)";

                for (int c = 0;
                    c < 4;
                    c++)
                {
                    table.Cells[1, c].Alignment =
                        CellAlignment.MiddleCenter;
                }

                for (int i = 0;
                    i < rows.Count;
                    i++)
                {
                    SmartValveStatRow row =
                        rows[i];

                    int r =
                        i + 2;

                    table.Cells[r, 0].TextString =
                        (i + 1).ToString();

                    table.Cells[r, 0].Alignment =
                        CellAlignment.MiddleCenter;

                    table.Cells[r, 1].TextString =
                        "   " +
                        (row.Loai ?? "");

                    table.Cells[r, 1].Alignment =
                        CellAlignment.MiddleLeft;

                    table.Cells[r, 2].TextString =
                        row.Size ?? "-";

                    table.Cells[r, 2].Alignment =
                        CellAlignment.MiddleCenter;

                    table.Cells[r, 3].TextString =
                        row.SoLuong.ToString();

                    table.Cells[r, 3].Alignment =
                        CellAlignment.MiddleCenter;
                }

                ObjectId newTableId =
                    btr.AppendEntity(
                        table);

                tr.AddNewlyCreatedDBObject(
                    table,
                    true);

                table.GenerateLayout();

                tr.Commit();

                _lastSmartStatsTableId =
                    newTableId;
            }

            _smartValveStage =
                "SCAN_OUTPUT_DONE";
        }


        private void ThongKeThietBiVanCu(
            Document doc)
        {
            if (doc == null)
                return;

            Editor ed =
                doc.Editor;

            Database db =
                doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            using (doc.LockDocument())
            {
                TypedValue[] tvs =
                    new TypedValue[]
                    {
                        new TypedValue(
                            (int)DxfCode.Start,
                            "TEXT,MTEXT")
                    };

                SelectionFilter filter =
                    new SelectionFilter(
                        tvs);

                PromptSelectionOptions pso =
                    new PromptSelectionOptions();

                pso.MessageForAdding =
                    "\nQuét chọn khu vực thiết bị / van cần thống kê: ";

                PromptSelectionResult psr =
                    ed.GetSelection(
                        pso,
                        filter);

                if (psr.Status !=
                    PromptStatus.OK)
                {
                    return;
                }

                Dictionary<string, double> dictSoLuong =
                    new Dictionary<string, double>(
                        StringComparer.OrdinalIgnoreCase);

                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    foreach (SelectedObject so
                        in psr.Value)
                    {
                        Entity ent =
                            tr.GetObject(
                                so.ObjectId,
                                OpenMode.ForRead)
                                as Entity;

                        if (ent == null)
                            continue;

                        string layer =
                            ent.Layer ?? "";

                        if (!LaLayerCuaTool(
                                layer))
                        {
                            continue;
                        }

                        if (LaLayerOng(
                                layer))
                        {
                            continue;
                        }

                        if (!dictSoLuong.ContainsKey(
                                layer))
                        {
                            dictSoLuong[layer] =
                                0;
                        }

                        dictSoLuong[layer] +=
                            1;
                    }

                    tr.Commit();
                }

                if (dictSoLuong.Count ==
                    0)
                {
                    MessageBox.Show(
                        "Không tìm thấy text thiết bị / van nào trong vùng chọn.",
                        "Thông báo");
                    return;
                }

                List<ThongKeOng> danhSachThongKe =
                    new List<ThongKeOng>();

                foreach (var item
                    in dictSoLuong)
                {
                    string heThong =
                        item.Key;

                    if (heThong.Contains(
                            "_"))
                    {
                        heThong =
                            heThong.Split(
                                '_')[0];
                    }

                    double kichThuoc =
                        0;

                    Match match =
                        Regex.Match(
                            item.Key,
                            @"\d+(\.\d+)?");

                    if (match.Success)
                    {
                        double.TryParse(
                            match.Value,
                            NumberStyles.Any,
                            CultureInfo.InvariantCulture,
                            out kichThuoc);
                    }

                    danhSachThongKe.Add(
                        new ThongKeOng
                        {
                            TenLayer =
                                item.Key,
                            SoLuong =
                                item.Value,
                            HeThongSort =
                                heThong,
                            KichThuocSort =
                                kichThuoc
                        });
                }

                List<ThongKeOng> danhSachDaSapXep =
                    danhSachThongKe
                        .OrderBy(
                            x =>
                                x.HeThongSort)
                        .ThenBy(
                            x =>
                                x.TenLayer)
                        .ThenByDescending(
                            x =>
                                x.KichThuocSort)
                        .ToList();

                for (int i = 0;
                    i < danhSachDaSapXep.Count;
                    i++)
                {
                    danhSachDaSapXep[i].STT =
                        i + 1;
                }

                XuatBangRaCad(
                    danhSachDaSapXep,
                    "BẢNG THỐNG KÊ THIẾT BỊ + VAN",
                    "SỐ LƯỢNG (cái)");
            }
        }


        private const string TempFindLayerName = "_TIM_DOI_TUONG_TEMP";

        private class EntityColorBackup
        {
            public ObjectId Id;
            public Autodesk.AutoCAD.Colors.Color Color;
        }


        private class ShopFittingFindKey
        {
            public string Loai { get; set; }
            public string KichThuoc { get; set; }
            public string KieuNoi { get; set; }

            public string DisplayText
            {
                get
                {
                    return
                        (Loai ?? "") + " | " +
                        (KichThuoc ?? "") + " | " +
                        (KieuNoi ?? "");
                }
            }
        }

        private void BtnTimDoiTuongThongKe_Click(
            object sender,
            RoutedEventArgs e)
        {
            TimDoiTuongThongKe(false);
        }

        private void BtnTimDoiTuongKhoanhTron_Click(
            object sender,
            RoutedEventArgs e)
        {
            TimDoiTuongThongKe(true);
        }

        private void TimDoiTuongThongKe(bool khoanhTron)
        {
            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var db = doc.Database;
            var ed = doc.Editor;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            List<ObjectId> tempLineIds =
                new List<ObjectId>();

            List<EntityColorBackup> colorBackups =
                new List<EntityColorBackup>();

            try
            {
                while (true)
                {
                    ed.WriteMessage(
                        khoanhTron
                            ? "\n[TÌM ĐỐI TƯỢNG KHOANH TRÒN] " +
                              "Click vào một dòng bảng thống kê (ESC thoát): "
                            : "\n[TÌM ĐỐI TƯỢNG ĐƯỜNG THẲNG] " +
                              "Click vào một dòng bảng thống kê (ESC thoát): ");

                    PromptPointOptions ppo =
                        new PromptPointOptions(
                            "\nClick vào dòng cần tìm trên bảng thống kê: ")
                        {
                            AllowNone = true
                        };

                    PromptPointResult ppr =
                        ed.GetPoint(ppo);

                    if (ppr.Status == PromptStatus.None ||
                        ppr.Status == PromptStatus.Cancel)
                    {
                        ed.WriteMessage(
                            khoanhTron
                                ? "\n[TÌM ĐỐI TƯỢNG KHOANH TRÒN] Đã thoát."
                                : "\n[TÌM ĐỐI TƯỢNG ĐƯỜNG THẲNG] Đã thoát.");
                        break;
                    }

                    if (ppr.Status != PromptStatus.OK)
                        continue;

                    // Xóa dấu lần trước + phục hồi màu.
                    KhoiPhucMauVaXoaDuong(
                        doc,
                        db,
                        tempLineIds,
                        colorBackups);

                    tempLineIds.Clear();
                    colorBackups.Clear();

                    Point3d pick =
                        ppr.Value;

                    Point3d fromPt =
                        pick;

                    string layerName = "";

                    ShopFittingFindKey fittingKey =
                        null;

                    // ----------------------------------------------------
                    // Bước 1:
                    // Ưu tiên nhận dòng từ BẢNG THỐNG KÊ PHỤ KIỆN SHOP.
                    // Nếu không phải bảng này thì quay về cách cũ theo Layer.
                    // ----------------------------------------------------
                    using (doc.LockDocument())
                    using (Transaction tr =
                        db.TransactionManager.StartTransaction())
                    {
                        if (!TryReadShopFittingRowAtPoint(
                                tr,
                                db,
                                ed,
                                pick,
                                out fittingKey,
                                out fromPt))
                        {
                            // FIX40N:
                            // Bảng ỐNG / THIẾT BỊ + VAN được đọc bằng bộ riêng.
                            // Không phụ thuộc hoàn toàn vào Table.HitTest vì
                            // AutoCAD có lúc trả sai row khi bảng scale lớn.
                            if (!TryReadStandardStatLayerRowAtPoint(
                                    tr,
                                    db,
                                    ed,
                                    pick,
                                    out layerName,
                                    out fromPt))
                            {
                                layerName =
                                    TimTenLayerTaiDiem(
                                        tr,
                                        db,
                                        ed,
                                        pick,
                                        out fromPt);
                            }
                        }

                        tr.Commit();
                    }

                    layerName =
                        (layerName ?? "")
                            .Trim();

                    bool timTheoPhuKien =
                        fittingKey != null;

                    if (!timTheoPhuKien)
                    {
                        if (string.IsNullOrWhiteSpace(layerName) ||
                            layerName.Equals(
                                "TÊN LAYER",
                                StringComparison.OrdinalIgnoreCase) ||
                            layerName.Equals(
                                "STT",
                                StringComparison.OrdinalIgnoreCase) ||
                            layerName.StartsWith(
                                "BẢNG THỐNG KÊ",
                                StringComparison.OrdinalIgnoreCase) ||
                            layerName.StartsWith(
                                "SỐ LƯỢNG",
                                StringComparison.OrdinalIgnoreCase) ||
                            layerName.Equals(
                                "M2",
                                StringComparison.OrdinalIgnoreCase) ||
                            layerName.Equals(
                                "TỔNG",
                                StringComparison.OrdinalIgnoreCase))
                        {
                            MessageBox.Show(
                                "Không đọc được dòng thống kê tại vị trí click.\n\n" +
                                "• Bảng Ống / Thiết bị + Van: click vào dòng có Tên Layer.\n" +
                                "• Bảng Phụ kiện SHOP: click vào bất kỳ ô nào trên dòng phụ kiện.",
                                "Cảnh báo");
                            continue;
                        }
                    }

                    List<Point3d> targets =
                        new List<Point3d>();

                    HashSet<ObjectId> targetIds =
                        new HashSet<ObjectId>();

                    HashSet<ObjectId> circleIds =
                        new HashSet<ObjectId>();

                    // ----------------------------------------------------
                    // Bước 2:
                    // Tìm target.
                    // - Bảng phụ kiện: match Loại + Kích thước + Kiểu nối.
                    // - Bảng cũ: match Layer như trước.
                    // ----------------------------------------------------
                    using (doc.LockDocument())
                    using (Transaction tr =
                        db.TransactionManager.StartTransaction())
                    {
                        BlockTableRecord btr =
                            (BlockTableRecord)tr.GetObject(
                                db.CurrentSpaceId,
                                OpenMode.ForRead);

                        if (timTheoPhuKien)
                        {
                            foreach (ObjectId id in btr)
                            {
                                BlockReference br =
                                    tr.GetObject(
                                        id,
                                        OpenMode.ForRead,
                                        false) as BlockReference;

                                if (br == null ||
                                    br.IsErased)
                                {
                                    continue;
                                }

                                if (!TryGetShopFittingStatIdentity(
                                        tr,
                                        br,
                                        br.Layer ?? "",
                                        out string loai,
                                        out string kichThuoc,
                                        out string kieuNoi,
                                        out int _,
                                        out double __))
                                {
                                    continue;
                                }

                                if (!ShopFittingFindTextEquals(
                                        loai,
                                        fittingKey.Loai) ||
                                    !ShopFittingFindTextEquals(
                                        kichThuoc,
                                        fittingKey.KichThuoc) ||
                                    !ShopFittingFindTextEquals(
                                        kieuNoi,
                                        fittingKey.KieuNoi))
                                {
                                    continue;
                                }

                                Point3d pt =
                                    LayDiemDaiDien(br);

                                targets.Add(pt);
                                targetIds.Add(id);

                                if (khoanhTron)
                                    circleIds.Add(id);
                            }
                        }
                        else
                        {
                            // FIX40N:
                            // Ống SHOP là LINE, không phải Polyline.
                            // Thu tất cả Curve để hỗ trợ:
                            // LINE / LWPOLYLINE / ARC.
                            List<Curve> curves =
                                new List<Curve>();

                            List<Curve> shopCenterCurves =
                                new List<Curve>();

                            List<Entity> texts =
                                new List<Entity>();

                            List<BlockReference> verticalRisers =
                                new List<BlockReference>();

                            bool isShopStatLayer =
                                layerName.StartsWith(
                                    "FF_SHOP_",
                                    StringComparison.OrdinalIgnoreCase);

                            foreach (ObjectId id in btr)
                            {
                                Entity o =
                                    tr.GetObject(
                                        id,
                                        OpenMode.ForRead)
                                        as Entity;

                                if (o == null ||
                                    o.IsErased)
                                {
                                    continue;
                                }

                                if (!LayerThongKeOngMatchesEntity(
                                        layerName,
                                        o.Layer))
                                {
                                    continue;
                                }

                                if (o is Table)
                                    continue;

                                // Highlight TẤT CẢ entity cùng tuyến:
                                // FF_SHOP_DNxx = 2 nét biên
                                // FF_SHOP_TAM_DNxx = tim.
                                targetIds.Add(
                                    o.ObjectId);

                                if (o is Curve cv)
                                {
                                    curves.Add(cv);

                                    if (LaLayerTamOngShop(
                                            o.Layer))
                                    {
                                        shopCenterCurves.Add(
                                            cv);
                                    }
                                }
                                else if (o is DBText ||
                                         o is MText)
                                {
                                    texts.Add(o);
                                }
                                else if (o is BlockReference riserBlock &&
                                         TryReadVerticalRiserData(
                                             riserBlock,
                                             out VerticalRiserData _))
                                {
                                    verticalRisers.Add(
                                        riserBlock);
                                }
                            }

                            // Với SHOP: chỉ dùng TIM làm vị trí mũi tên/vòng tròn
                            // để không sinh 3 dấu trên 2 biên + 1 tim.
                            List<Curve> representativeCurves =
                                isShopStatLayer &&
                                shopCenterCurves.Count > 0
                                    ? shopCenterCurves
                                    : curves;

                            if (representativeCurves.Count > 0)
                            {
                                foreach (Curve cv
                                    in representativeCurves)
                                {
                                    targets.Add(
                                        LayDiemGiuaCurveThongKe(
                                            cv));

                                    if (khoanhTron)
                                    {
                                        circleIds.Add(
                                            cv.ObjectId);
                                    }
                                }
                            }
                            else
                            {
                                foreach (Entity t in texts)
                                {
                                    targets.Add(
                                        LayDiemDaiDien(t));

                                    if (khoanhTron)
                                    {
                                        circleIds.Add(
                                            t.ObjectId);
                                    }
                                }
                            }

                            // Trục đứng dùng BlockReference + XData, không phải Curve.
                            // Luôn thêm tâm block làm đích tìm kiếm, kể cả khi cùng
                            // layer đang có các đoạn ống ngang.
                            foreach (BlockReference riser in verticalRisers)
                            {
                                targets.Add(
                                    riser.Position);

                                if (khoanhTron)
                                {
                                    circleIds.Add(
                                        riser.ObjectId);
                                }
                            }
                        }

                        tr.Commit();
                    }

                    string targetText =
                        timTheoPhuKien
                            ? fittingKey.DisplayText
                            : layerName;

                    if (targets.Count == 0)
                    {
                        MessageBox.Show(
                            timTheoPhuKien
                                ? "Không tìm thấy phụ kiện SHOP tương ứng:\n" +
                                  targetText
                                : "Không tìm thấy đối tượng nào trên layer:\n" +
                                  layerName,
                            "Thông báo");

                        continue;
                    }

                    // ----------------------------------------------------
                    // Bước 3:
                    // Đổi target = vàng, còn lại = xám.
                    // Bảng thống kê giữ nguyên màu.
                    // ----------------------------------------------------
                    using (doc.LockDocument())
                    using (Transaction tr =
                        db.TransactionManager.StartTransaction())
                    {
                        EnsureTempFindLayer(
                            tr,
                            db);

                        BlockTableRecord btr =
                            (BlockTableRecord)tr.GetObject(
                                db.CurrentSpaceId,
                                OpenMode.ForWrite);

                        Autodesk.AutoCAD.Colors.Color colYellow =
                            Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                                ColorMethod.ByAci,
                                2);

                        Autodesk.AutoCAD.Colors.Color colGray =
                            Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                                ColorMethod.ByAci,
                                8);

                        HashSet<ObjectId> blockChildBackupIds =
                            new HashSet<ObjectId>();

                        foreach (ObjectId id in btr)
                        {
                            Entity o =
                                tr.GetObject(
                                    id,
                                    OpenMode.ForRead)
                                    as Entity;

                            if (o == null ||
                                o.IsErased)
                            {
                                continue;
                            }

                            // Không đổi màu các bảng thống kê.
                            if (o is Table)
                                continue;

                            if (string.Equals(
                                    o.Layer,
                                    TempFindLayerName,
                                    StringComparison.OrdinalIgnoreCase))
                            {
                                continue;
                            }

                            if (IsEntityOnLockedLayer(
                                    tr,
                                    db,
                                    o))
                            {
                                continue;
                            }

                            try
                            {
                                o.UpgradeOpen();

                                colorBackups.Add(
                                    new EntityColorBackup
                                    {
                                        Id = id,
                                        Color = o.Color
                                    });

                                bool isTarget =
                                    targetIds.Contains(id);

                                o.Color =
                                    isTarget
                                        ? colYellow
                                        : colGray;

                                if (o is BlockReference br)
                                {
                                    DoiMauEntityTrongBlockTamThoi(
                                        tr,
                                        db,
                                        br,
                                        isTarget
                                            ? colYellow
                                            : colGray,
                                        colorBackups,
                                        blockChildBackupIds,
                                        new HashSet<ObjectId>());
                                }
                            }
                            catch
                            {
                            }
                        }

                        if (khoanhTron)
                        {
                            foreach (ObjectId id in circleIds)
                            {
                                try
                                {
                                    Entity ent =
                                        tr.GetObject(
                                            id,
                                            OpenMode.ForRead)
                                            as Entity;

                                    Circle circle;

                                    if (ent is Curve shopCurve &&
                                        (LaLayerTamOngShop(
                                             ent.Layer) ||
                                         LaLayerBienOngShop(
                                             ent.Layer)))
                                    {
                                        // FIX40N:
                                        // Khoanh ống SHOP tại GIỮA đoạn ống,
                                        // không lấy toàn extents của LINE dài.
                                        Point3d center =
                                            LayDiemGiuaCurveThongKe(
                                                shopCurve);

                                        double dn =
                                            0.0;

                                        Match dnMatch =
                                            Regex.Match(
                                                ent.Layer ?? "",
                                                @"DN\s*(\d+(?:[.,]\d+)?)",
                                                RegexOptions.IgnoreCase);

                                        if (dnMatch.Success)
                                        {
                                            double.TryParse(
                                                dnMatch.Groups[1].Value
                                                    .Replace(',', '.'),
                                                NumberStyles.Any,
                                                CultureInfo.InvariantCulture,
                                                out dn);
                                        }

                                        double od =
                                            dn > 0.0 &&
                                            TryGetFireSteelOutsideDiameter(
                                                dn,
                                                out double outside)
                                                ? outside
                                                : dn;

                                        double radius =
                                            Math.Max(
                                                600.0,
                                                Math.Max(
                                                    od * 3.0,
                                                    300.0));

                                        circle =
                                            new Circle(
                                                center,
                                                Vector3d.ZAxis,
                                                radius);
                                    }
                                    else
                                    {
                                        circle =
                                            TaoVongTronBaoDoiTuong(
                                                ent);
                                    }

                                    if (circle == null)
                                        continue;

                                    circle.SetDatabaseDefaults(db);
                                    circle.Layer =
                                        TempFindLayerName;

                                    circle.Color =
                                        Autodesk.AutoCAD.Colors.Color
                                            .FromColorIndex(
                                                ColorMethod.ByAci,
                                                1);

                                    btr.AppendEntity(circle);

                                    tr.AddNewlyCreatedDBObject(
                                        circle,
                                        true);

                                    tempLineIds.Add(
                                        circle.ObjectId);
                                }
                                catch
                                {
                                }
                            }
                        }
                        else
                        {
                            foreach (Point3d toPt in targets)
                            {
                                Line line =
                                    new Line(
                                        fromPt,
                                        toPt);

                                line.SetDatabaseDefaults(db);
                                line.Layer =
                                    TempFindLayerName;

                                line.Color =
                                    Autodesk.AutoCAD.Colors.Color
                                        .FromColorIndex(
                                            ColorMethod.ByAci,
                                            1);

                                btr.AppendEntity(line);

                                tr.AddNewlyCreatedDBObject(
                                    line,
                                    true);

                                tempLineIds.Add(
                                    line.ObjectId);
                            }
                        }

                        tr.Commit();
                    }

                    ed.Regen();

                    ed.WriteMessage(
                        (khoanhTron
                            ? $"\n[TÌM ĐỐI TƯỢNG KHOANH TRÒN] " +
                              $"{targetText} → {targets.Count} đối tượng " +
                              "(vàng + vòng tròn). "
                            : $"\n[TÌM ĐỐI TƯỢNG ĐƯỜNG THẲNG] " +
                              $"{targetText} → {targets.Count} đối tượng " +
                              "(vàng). ") +
                        "Click dòng khác để tìm tiếp, ESC để phục hồi màu & thoát.");
                }
            }
            catch (System.Exception ex)
            {
                try
                {
                    KhoiPhucMauVaXoaDuong(
                        doc,
                        db,
                        tempLineIds,
                        colorBackups);
                }
                catch
                {
                }

                MessageBox.Show(
                    "Lỗi tìm đối tượng:\n" +
                    ex.Message,
                    "Lỗi");
            }
            finally
            {
                KhoiPhucMauVaXoaDuong(
                    doc,
                    db,
                    tempLineIds,
                    colorBackups);

                try
                {
                    ed.Regen();
                }
                catch
                {
                }
            }
        }

        private static bool ShopFittingFindTextEquals(
            string a,
            string b)
        {
            return string.Equals(
                (a ?? "").Trim(),
                (b ?? "").Trim(),
                StringComparison.OrdinalIgnoreCase);
        }

        private static bool LayerThongKeOngMatchesEntity(
            string tableLayer,
            string entityLayer)
        {
            string tableName =
                (tableLayer ?? "")
                    .Trim();

            string entityName =
                (entityLayer ?? "")
                    .Trim();

            if (string.Equals(
                    tableName,
                    entityName,
                    StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            string[] systems =
                new[]
                {
                    "FF",
                    "CTN"
                };

            foreach (string system
                in systems)
            {
                string edgePrefix =
                    system +
                    "_SHOP_";

                string centerPrefix =
                    system +
                    "_SHOP_TAM_";

                if (tableName.StartsWith(
                        centerPrefix,
                        StringComparison.OrdinalIgnoreCase))
                {
                    string tail =
                        tableName.Substring(
                            centerPrefix.Length);

                    string edge =
                        edgePrefix +
                        tail;

                    if (string.Equals(
                            edge,
                            entityName,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        return true;
                    }
                }
                else if (tableName.StartsWith(
                             edgePrefix,
                             StringComparison.OrdinalIgnoreCase))
                {
                    string tail =
                        tableName.Substring(
                            edgePrefix.Length);

                    string center =
                        centerPrefix +
                        tail;

                    if (string.Equals(
                            center,
                            entityName,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        return true;
                    }
                }
            }

            return false;
        }


        private static void KhoiPhucMauVaXoaDuong(
            Document doc,
            Database db,
            List<ObjectId> tempLineIds,
            List<EntityColorBackup> colorBackups)
        {
            try
            {
                using (doc.LockDocument())
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    if (colorBackups != null)
                    {
                        foreach (var bak in colorBackups)
                        {
                            if (bak.Id.IsNull || bak.Id.IsErased)
                                continue;
                            try
                            {
                                Entity o =
                                    tr.GetObject(bak.Id, OpenMode.ForWrite)
                                        as Entity;
                                if (o != null && bak.Color != null)
                                    o.Color = bak.Color;
                            }
                            catch { }
                        }
                    }

                    if (tempLineIds != null)
                    {
                        foreach (ObjectId id in tempLineIds)
                        {
                            if (id.IsNull || id.IsErased)
                                continue;
                            try
                            {
                                Entity ent =
                                    tr.GetObject(id, OpenMode.ForWrite)
                                        as Entity;
                                if (ent != null)
                                    ent.Erase();
                            }
                            catch { }
                        }
                    }

                    tr.Commit();
                }
            }
            catch { }
        }

        private bool TryReadStandardStatLayerRowAtPoint(
            Transaction tr,
            Database db,
            Editor ed,
            Point3d pick,
            out string layerName,
            out Point3d fromPt)
        {
            layerName = "";
            fromPt = pick;

            BlockTableRecord btr =
                (BlockTableRecord)tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForRead);

            Table bestTable =
                null;

            Extents3d bestExt =
                new Extents3d();

            double bestDistance =
                double.MaxValue;

            foreach (ObjectId id in btr)
            {
                Table tb =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Table;

                if (tb == null ||
                    tb.Columns.Count < 2 ||
                    tb.Rows.Count < 3)
                {
                    continue;
                }

                string title = "";

                try
                {
                    title =
                        (tb.Cells[0, 0].TextString ?? "")
                            .Trim();
                }
                catch
                {
                    continue;
                }

                bool isPipeTable =
                    title.StartsWith(
                        "BẢNG THỐNG KÊ KHỐI LƯỢNG ỐNG",
                        StringComparison.OrdinalIgnoreCase);

                bool isDeviceTable =
                    title.StartsWith(
                        "BẢNG THỐNG KÊ THIẾT BỊ + VAN",
                        StringComparison.OrdinalIgnoreCase);

                if (!isPipeTable &&
                    !isDeviceTable)
                {
                    continue;
                }

                try
                {
                    Extents3d ext =
                        tb.GeometricExtents;

                    double width =
                        Math.Abs(
                            ext.MaxPoint.X -
                            ext.MinPoint.X);

                    double height =
                        Math.Abs(
                            ext.MaxPoint.Y -
                            ext.MinPoint.Y);

                    double pad =
                        Math.Max(
                            50.0,
                            Math.Max(
                                width,
                                height) *
                            0.015);

                    if (pick.X <
                            ext.MinPoint.X - pad ||
                        pick.X >
                            ext.MaxPoint.X + pad ||
                        pick.Y <
                            ext.MinPoint.Y - pad ||
                        pick.Y >
                            ext.MaxPoint.Y + pad)
                    {
                        continue;
                    }

                    Point3d mid =
                        new Point3d(
                            (ext.MinPoint.X +
                             ext.MaxPoint.X) / 2.0,
                            (ext.MinPoint.Y +
                             ext.MaxPoint.Y) / 2.0,
                            ext.MinPoint.Z);

                    double distance =
                        PlanDistance(
                            pick,
                            mid);

                    if (distance <
                        bestDistance)
                    {
                        bestDistance =
                            distance;

                        bestTable =
                            tb;

                        bestExt =
                            ext;
                    }
                }
                catch
                {
                }
            }

            if (bestTable == null)
                return false;

            int row = -1;

            // --------------------------------------------------------
            // A) HitTest trước.
            // --------------------------------------------------------
            try
            {
                Vector3d viewDirection =
                    Vector3d.ZAxis;

                try
                {
                    using (ViewTableRecord view =
                        ed.GetCurrentView())
                    {
                        viewDirection =
                            view.ViewDirection;

                        if (viewDirection.Length <
                            1e-9)
                        {
                            viewDirection =
                                Vector3d.ZAxis;
                        }
                    }
                }
                catch
                {
                }

                TableHitTestInfo hit =
                    bestTable.HitTest(
                        pick,
                        viewDirection);

                if (hit.Type !=
                    TableHitTestType.Cell)
                {
                    hit =
                        bestTable.HitTest(
                            pick,
                            Vector3d.ZAxis);
                }

                if (hit.Type ==
                    TableHitTestType.Cell)
                {
                    row =
                        hit.Row;
                }
            }
            catch
            {
            }

            // --------------------------------------------------------
            // B) Nếu HitTest trả header/sai row:
            // tính row trực tiếp từ EXTENTS TOP + chiều cao từng hàng.
            //
            // Đây là phần sửa chính cho bảng scale lớn như ảnh user gửi.
            // --------------------------------------------------------
            bool rowLooksValid =
                row >= 2 &&
                row <
                    bestTable.Rows.Count;

            if (!rowLooksValid)
            {
                row =
                    FindStandardStatDataRowByY(
                        bestTable,
                        bestExt,
                        pick.Y);
            }

            // Nếu HitTest có row >=2 nhưng text col1 lại rỗng/header,
            // thử lại bằng tọa độ Y.
            string value = "";

            if (row >= 2 &&
                row <
                    bestTable.Rows.Count)
            {
                try
                {
                    value =
                        (bestTable.Cells[row, 1].TextString ?? "")
                            .Trim();
                }
                catch
                {
                    value = "";
                }
            }

            if (string.IsNullOrWhiteSpace(
                    value) ||
                value.Equals(
                    "TÊN LAYER",
                    StringComparison.OrdinalIgnoreCase) ||
                value.Equals(
                    "TỔNG",
                    StringComparison.OrdinalIgnoreCase))
            {
                int fallbackRow =
                    FindStandardStatDataRowByY(
                        bestTable,
                        bestExt,
                        pick.Y);

                if (fallbackRow >= 2 &&
                    fallbackRow <
                        bestTable.Rows.Count)
                {
                    row =
                        fallbackRow;

                    try
                    {
                        value =
                            (bestTable.Cells[row, 1].TextString ?? "")
                                .Trim();
                    }
                    catch
                    {
                        value = "";
                    }
                }
            }

            value =
                (value ?? "")
                    .Trim();

            if (string.IsNullOrWhiteSpace(
                    value) ||
                value.Equals(
                    "TÊN LAYER",
                    StringComparison.OrdinalIgnoreCase) ||
                value.Equals(
                    "STT",
                    StringComparison.OrdinalIgnoreCase) ||
                value.Equals(
                    "TỔNG",
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            layerName =
                value;

            fromPt =
                pick;

            try
            {
                ed.WriteMessage(
                    $"\n[TÌM FIX40N] Đọc bảng: row={row}, layer={layerName}");
            }
            catch
            {
            }

            return true;
        }

        private static int FindStandardStatDataRowByY(
            Table table,
            Extents3d ext,
            double pickY)
        {
            if (table == null ||
                table.Rows.Count < 3)
            {
                return -1;
            }

            try
            {
                // Với bảng không xoay (các bảng do tool tạo),
                // ext.MaxPoint.Y là đỉnh bảng ổn định hơn Table.Position.Y.
                double yTop =
                    ext.MaxPoint.Y;

                double accumulated =
                    0.0;

                for (int r = 0;
                    r <
                    table.Rows.Count;
                    r++)
                {
                    double rowHeight =
                        table.Rows[r].Height;

                    double top =
                        yTop -
                        accumulated;

                    double bottom =
                        top -
                        rowHeight;

                    if (pickY <=
                            top &&
                        pickY >=
                            bottom)
                    {
                        return r;
                    }

                    accumulated +=
                        rowHeight;
                }

                // Fallback gần nhất theo tâm hàng.
                double bestDist =
                    double.MaxValue;

                int bestRow =
                    -1;

                accumulated =
                    0.0;

                for (int r = 2;
                    r <
                    table.Rows.Count;
                    r++)
                {
                    double rowHeight =
                        table.Rows[r].Height;

                    double centerY =
                        yTop -
                        accumulated -
                        rowHeight / 2.0;

                    double dist =
                        Math.Abs(
                            pickY -
                            centerY);

                    if (dist <
                        bestDist)
                    {
                        bestDist =
                            dist;

                        bestRow =
                            r;
                    }

                    accumulated +=
                        rowHeight;
                }

                return bestRow;
            }
            catch
            {
                return -1;
            }
        }


        private bool TryReadShopFittingRowAtPoint(
            Transaction tr,
            Database db,
            Editor ed,
            Point3d pick,
            out ShopFittingFindKey key,
            out Point3d fromPt)
        {
            key = null;
            fromPt = pick;

            BlockTableRecord btr =
                (BlockTableRecord)tr.GetObject(
                    db.CurrentSpaceId,
                    OpenMode.ForRead);

            Table bestTable = null;
            double bestDist = double.MaxValue;

            foreach (ObjectId id in btr)
            {
                Table tb =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead)
                        as Table;

                if (tb == null ||
                    tb.Columns.Count < 5 ||
                    tb.Rows.Count < 3)
                {
                    continue;
                }

                string title = "";

                try
                {
                    title =
                        (tb.Cells[0, 0].TextString ?? "")
                            .Trim();
                }
                catch
                {
                    continue;
                }

                if (!title.StartsWith(
                        "BẢNG THỐNG KÊ PHỤ KIỆN SHOP",
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                try
                {
                    Extents3d ext =
                        tb.GeometricExtents;

                    double pad =
                        Math.Max(
                            ext.MaxPoint.X - ext.MinPoint.X,
                            ext.MaxPoint.Y - ext.MinPoint.Y) *
                        0.03;

                    if (pick.X < ext.MinPoint.X - pad ||
                        pick.X > ext.MaxPoint.X + pad ||
                        pick.Y < ext.MinPoint.Y - pad ||
                        pick.Y > ext.MaxPoint.Y + pad)
                    {
                        continue;
                    }

                    Point3d mid =
                        new Point3d(
                            (ext.MinPoint.X + ext.MaxPoint.X) / 2.0,
                            (ext.MinPoint.Y + ext.MaxPoint.Y) / 2.0,
                            0.0);

                    double d =
                        pick.DistanceTo(mid);

                    if (d < bestDist)
                    {
                        bestDist = d;
                        bestTable = tb;
                    }
                }
                catch
                {
                }
            }

            if (bestTable == null)
                return false;

            int row = -1;

            try
            {
                Vector3d viewDir =
                    Vector3d.ZAxis;

                try
                {
                    using (ViewTableRecord view =
                        ed.GetCurrentView())
                    {
                        viewDir =
                            view.ViewDirection;

                        if (viewDir.Length < 1e-9)
                            viewDir = Vector3d.ZAxis;
                    }
                }
                catch
                {
                }

                TableHitTestInfo hit =
                    bestTable.HitTest(
                        pick,
                        viewDir);

                if (hit.Type != TableHitTestType.Cell)
                {
                    hit =
                        bestTable.HitTest(
                            pick,
                            Vector3d.ZAxis);
                }

                if (hit.Type == TableHitTestType.Cell)
                    row = hit.Row;
            }
            catch
            {
            }

            // Fallback nếu HitTest không nhận:
            // tính hàng theo chiều cao các row từ Position của Table.
            if (row < 0)
            {
                try
                {
                    double yTop =
                        bestTable.Position.Y;

                    double y =
                        pick.Y;

                    double accumulated = 0.0;

                    for (int r = 0;
                        r < bestTable.Rows.Count;
                        r++)
                    {
                        double h =
                            bestTable.Rows[r].Height;

                        double top =
                            yTop - accumulated;

                        double bottom =
                            top - h;

                        if (y <= top &&
                            y >= bottom)
                        {
                            row = r;
                            break;
                        }

                        accumulated += h;
                    }
                }
                catch
                {
                }
            }

            // Hàng 0 = tiêu đề, hàng 1 = header,
            // hàng cuối = TỔNG.
            if (row < 2 ||
                row >= bestTable.Rows.Count)
            {
                return false;
            }

            string loai = "";
            string kichThuoc = "";
            string kieuNoi = "";

            try
            {
                loai =
                    (bestTable.Cells[row, 1].TextString ?? "")
                        .Trim();

                kichThuoc =
                    (bestTable.Cells[row, 2].TextString ?? "")
                        .Trim();

                kieuNoi =
                    (bestTable.Cells[row, 3].TextString ?? "")
                        .Trim();
            }
            catch
            {
                return false;
            }

            if (string.IsNullOrWhiteSpace(loai) ||
                loai.Equals(
                    "LOẠI PHỤ KIỆN",
                    StringComparison.OrdinalIgnoreCase) ||
                loai.Equals(
                    "TỔNG",
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            key =
                new ShopFittingFindKey
                {
                    Loai = loai,
                    KichThuoc = kichThuoc,
                    KieuNoi = kieuNoi
                };

            fromPt =
                pick;

            return true;
        }


        /// <summary>
        /// Tìm bảng gần điểm click và lấy text cột Tên Layer.
        /// </summary>
        private static string TimTenLayerTaiDiem(
            Transaction tr,
            Database db,
            Editor ed,
            Point3d pick,
            out Point3d fromPt)
        {
            fromPt = pick;

            BlockTableRecord btr =
                (BlockTableRecord)tr.GetObject(
                    db.CurrentSpaceId, OpenMode.ForRead);

            Table bestTable = null;
            double bestTableDist = double.MaxValue;

            foreach (ObjectId id in btr)
            {
                Table tb = tr.GetObject(id, OpenMode.ForRead) as Table;
                if (tb == null)
                    continue;

                try
                {
                    Extents3d ext = tb.GeometricExtents;
                    // Mở rộng một chút vùng bao
                    double pad = Math.Max(
                        ext.MaxPoint.X - ext.MinPoint.X,
                        ext.MaxPoint.Y - ext.MinPoint.Y) * 0.05;

                    if (pick.X < ext.MinPoint.X - pad ||
                        pick.X > ext.MaxPoint.X + pad ||
                        pick.Y < ext.MinPoint.Y - pad ||
                        pick.Y > ext.MaxPoint.Y + pad)
                        continue;

                    Point3d mid = new Point3d(
                        (ext.MinPoint.X + ext.MaxPoint.X) / 2.0,
                        (ext.MinPoint.Y + ext.MaxPoint.Y) / 2.0,
                        0);
                    double d = pick.DistanceTo(mid);
                    if (d < bestTableDist)
                    {
                        bestTableDist = d;
                        bestTable = tb;
                    }
                }
                catch { }
            }

            if (bestTable == null)
                return "";

            // 1) HitTest
            string name = LayTenLayerTuBang(
                bestTable, pick, ed, out fromPt);
            if (!string.IsNullOrWhiteSpace(name))
                return name;

            // 2) Fallback khoảng cách ô
            return LayTenLayerBangBangKhoangCach(
                bestTable, pick, out fromPt);
        }

        private static Point3d LayDiemGiuaCurveThongKe(
            Curve curve)
        {
            if (curve == null)
                return Point3d.Origin;

            try
            {
                if (curve is Line line)
                {
                    return MidPoint(
                        line.StartPoint,
                        line.EndPoint);
                }

                if (curve is Polyline pl)
                {
                    double length =
                        pl.Length;

                    if (length > 1e-9)
                    {
                        return pl.GetPointAtDist(
                            length / 2.0);
                    }

                    return pl.NumberOfVertices > 0
                        ? pl.GetPoint3dAt(0)
                        : Point3d.Origin;
                }

                if (curve is Arc arc)
                {
                    double midAngle =
                        arc.StartAngle +
                        (arc.EndAngle -
                         arc.StartAngle) / 2.0;

                    return arc.Center +
                        new Vector3d(
                            Math.Cos(midAngle) *
                            arc.Radius,
                            Math.Sin(midAngle) *
                            arc.Radius,
                            0.0);
                }

                double startParam =
                    curve.StartParam;

                double endParam =
                    curve.EndParam;

                return curve.GetPointAtParameter(
                    (startParam +
                     endParam) / 2.0);
            }
            catch
            {
                try
                {
                    return MidPoint(
                        curve.StartPoint,
                        curve.EndPoint);
                }
                catch
                {
                    return Point3d.Origin;
                }
            }
        }


        private static Point3d LayDiemGiuaPolyline(Polyline pl)
        {
            try
            {
                if (pl == null || pl.NumberOfVertices < 1)
                    return Point3d.Origin;

                double len = pl.Length;
                if (len > 1e-9)
                    return pl.GetPointAtDist(len / 2.0);

                return pl.GetPoint3dAt(0);
            }
            catch
            {
                try { return pl.GetPoint3dAt(0); }
                catch { return Point3d.Origin; }
            }
        }

        private static Point3d LayDiemDaiDien(Entity o)
        {
            try
            {
                if (o is Polyline pl && pl.NumberOfVertices > 0)
                    return pl.GetPoint3dAt(0);

                if (o is Curve cv)
                    return cv.StartPoint;

                if (o is DBText t)
                    return t.Position;

                if (o is MText mt)
                    return mt.Location;

                if (o is BlockReference br)
                    return br.Position;

                Extents3d ext = o.GeometricExtents;
                return new Point3d(
                    (ext.MinPoint.X + ext.MaxPoint.X) / 2.0,
                    (ext.MinPoint.Y + ext.MaxPoint.Y) / 2.0,
                    (ext.MinPoint.Z + ext.MaxPoint.Z) / 2.0);
            }
            catch
            {
                return Point3d.Origin;
            }
        }

        private static void DoiMauEntityTrongBlockTamThoi(
            Transaction tr,
            Database db,
            BlockReference blockRef,
            Autodesk.AutoCAD.Colors.Color color,
            List<EntityColorBackup> colorBackups,
            HashSet<ObjectId> backedUpIds,
            HashSet<ObjectId> visitedBlockRecords)
        {
            if (blockRef == null ||
                blockRef.BlockTableRecord.IsNull ||
                visitedBlockRecords.Contains(blockRef.BlockTableRecord))
                return;

            try
            {
                foreach (ObjectId attId in blockRef.AttributeCollection)
                {
                    AttributeReference att =
                        tr.GetObject(attId, OpenMode.ForRead)
                            as AttributeReference;

                    if (att == null || att.IsErased)
                        continue;

                    if (IsEntityOnLockedLayer(tr, db, att))
                        continue;

                    try
                    {
                        att.UpgradeOpen();

                        if (!backedUpIds.Contains(att.ObjectId))
                        {
                            colorBackups.Add(new EntityColorBackup
                            {
                                Id = att.ObjectId,
                                Color = att.Color
                            });
                            backedUpIds.Add(att.ObjectId);
                        }

                        att.Color = color;
                    }
                    catch { }
                }
            }
            catch { }

            visitedBlockRecords.Add(blockRef.BlockTableRecord);

            try
            {
                BlockTableRecord blockDef =
                    tr.GetObject(
                        blockRef.BlockTableRecord,
                        OpenMode.ForRead) as BlockTableRecord;

                if (blockDef == null)
                    return;

                foreach (ObjectId childId in blockDef)
                {
                    Entity child =
                        tr.GetObject(childId, OpenMode.ForRead)
                            as Entity;
                    if (child == null || child.IsErased)
                        continue;

                    if (IsEntityOnLockedLayer(tr, db, child))
                        continue;

                    try
                    {
                        child.UpgradeOpen();

                        if (!backedUpIds.Contains(child.ObjectId))
                        {
                            colorBackups.Add(new EntityColorBackup
                            {
                                Id = child.ObjectId,
                                Color = child.Color
                            });
                            backedUpIds.Add(child.ObjectId);
                        }

                        child.Color = color;

                        if (child is BlockReference nestedBlock)
                        {
                            DoiMauEntityTrongBlockTamThoi(
                                tr,
                                db,
                                nestedBlock,
                                color,
                                colorBackups,
                                backedUpIds,
                                visitedBlockRecords);
                        }
                    }
                    catch { }
                }
            }
            catch { }
            finally
            {
                visitedBlockRecords.Remove(blockRef.BlockTableRecord);
            }
        }

        private static Circle TaoVongTronBaoDoiTuong(Entity ent)
        {
            if (ent == null)
                return null;

            try
            {
                Extents3d ext = ent.GeometricExtents;

                Point3d center =
                    new Point3d(
                        (ext.MinPoint.X + ext.MaxPoint.X) / 2.0,
                        (ext.MinPoint.Y + ext.MaxPoint.Y) / 2.0,
                        (ext.MinPoint.Z + ext.MaxPoint.Z) / 2.0);

                double width =
                    Math.Abs(ext.MaxPoint.X - ext.MinPoint.X);
                double height =
                    Math.Abs(ext.MaxPoint.Y - ext.MinPoint.Y);
                double maxSize = Math.Max(width, height);

                if (maxSize < 1e-6)
                    maxSize = 600.0;

                double radius =
                    Math.Max(maxSize * 1.44, 600.0);

                return new Circle(
                    center,
                    Vector3d.ZAxis,
                    radius);
            }
            catch
            {
                Point3d center = LayDiemDaiDien(ent);
                return new Circle(
                    center,
                    Vector3d.ZAxis,
                    600.0);
            }
        }

        private static string LayTenLayerTuBang(
            Table table,
            Point3d pick,
            Editor ed,
            out Point3d cellCenter)
        {
            cellCenter = pick;

            try
            {
                Vector3d viewDir = Vector3d.ZAxis;
                try
                {
                    using (ViewTableRecord view = ed.GetCurrentView())
                    {
                        viewDir = view.ViewDirection;
                        if (viewDir.Length < 1e-9)
                            viewDir = Vector3d.ZAxis;
                    }
                }
                catch { }

                TableHitTestInfo hit = table.HitTest(pick, viewDir);

                if (hit.Type != TableHitTestType.Cell)
                    hit = table.HitTest(pick, Vector3d.ZAxis);

                if (hit.Type != TableHitTestType.Cell)
                    hit = table.HitTest(pick, new Vector3d(0, 0, 1));

                // Fallback: duyệt từng ô, chọn ô gần điểm pick nhất (cột tên layer = 1)
                if (hit.Type != TableHitTestType.Cell)
                {
                    return LayTenLayerBangBangKhoangCach(
                        table, pick, out cellCenter);
                }

                int row = hit.Row;
                int col = hit.Column;

                string text = (table.Cells[row, col].TextString ?? "").Trim();

                if (col != 1 && table.Columns.Count > 1 && row >= 2)
                {
                    string col1 = (table.Cells[row, 1].TextString ?? "").Trim();
                    if (!string.IsNullOrWhiteSpace(col1))
                        text = col1;
                }

                cellCenter = pick;
                return text;
            }
            catch
            {
                return LayTenLayerBangBangKhoangCach(
                    table, pick, out cellCenter);
            }
        }

        private static string LayTenLayerBangBangKhoangCach(
            Table table,
            Point3d pick,
            out Point3d cellCenter)
        {
            cellCenter = pick;
            string best = "";
            double bestDist = double.MaxValue;

            try
            {
                int rows = table.Rows.Count;
                int cols = table.Columns.Count;
                if (cols < 2)
                    return "";

                // Chỉ xét cột 1 (Tên Layer), bỏ hàng 0-1 (tiêu đề)
                for (int r = 2; r < rows; r++)
                {
                    try
                    {
                        Cell cell = table.Cells[r, 1];
                        string text = (cell.TextString ?? "").Trim();
                        if (string.IsNullOrWhiteSpace(text))
                            continue;

                        // Ước lượng tâm ô theo vị trí bảng + cộng dồn width/height
                        double x = table.Position.X;
                        double y = table.Position.Y;

                        for (int c = 0; c < 1; c++)
                            x += table.Columns[c].Width;
                        x += table.Columns[1].Width / 2.0;

                        for (int rr = 0; rr < r; rr++)
                            y -= table.Rows[rr].Height;
                        y -= table.Rows[r].Height / 2.0;

                        Point3d center = new Point3d(x, y, table.Position.Z);
                        double d = pick.DistanceTo(center);

                        if (d < bestDist)
                        {
                            bestDist = d;
                            best = text;
                            cellCenter = center;
                        }
                    }
                    catch { }
                }
            }
            catch { }

            return best;
        }

        private static void EnsureTempFindLayer(
            Transaction tr,
            Database db)
        {
            LayerTable lt =
                (LayerTable)tr.GetObject(
                    db.LayerTableId, OpenMode.ForRead);

            if (lt.Has(TempFindLayerName))
            {
                LayerTableRecord existing =
                    (LayerTableRecord)tr.GetObject(
                        lt[TempFindLayerName],
                        OpenMode.ForWrite);

                existing.IsLocked = false;
                existing.IsOff = false;
                existing.IsFrozen = false;
                return;
            }

            lt.UpgradeOpen();
            LayerTableRecord ltr = new LayerTableRecord();
            ltr.Name = TempFindLayerName;
            ltr.Color = Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                ColorMethod.ByAci, 1);
            ltr.IsOff = false;
            ltr.IsLocked = false;
            ltr.IsFrozen = false;
            lt.Add(ltr);
            tr.AddNewlyCreatedDBObject(ltr, true);
        }

        private static bool IsEntityOnLockedLayer(
            Transaction tr,
            Database db,
            Entity ent)
        {
            if (ent == null)
                return false;

            try
            {
                LayerTable lt =
                    (LayerTable)tr.GetObject(
                        db.LayerTableId,
                        OpenMode.ForRead);

                if (!lt.Has(ent.Layer))
                    return false;

                LayerTableRecord ltr =
                    (LayerTableRecord)tr.GetObject(
                        lt[ent.Layer],
                        OpenMode.ForRead);

                return ltr != null && ltr.IsLocked;
            }
            catch
            {
                return false;
            }
        }

        private static void XoaDuongChiTam(
            Document doc,
            Database db,
            List<ObjectId> ids)
        {
            if (ids == null || ids.Count == 0)
                return;

            try
            {
                using (doc.LockDocument())
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    foreach (ObjectId id in ids)
                    {
                        if (id.IsNull || id.IsErased)
                            continue;

                        try
                        {
                            Entity ent =
                                tr.GetObject(id, OpenMode.ForWrite)
                                    as Entity;
                            if (ent != null)
                                ent.Erase();
                        }
                        catch { }
                    }

                    tr.Commit();
                }
            }
            catch { }
        }

        private static double TinhM2OngGioTuLayer(
            string layerName,
            double chieuDaiMet)
        {
            if (string.IsNullOrWhiteSpace(layerName) ||
                chieuDaiMet <= 0.0)
                return 0.0;

            Match match =
                Regex.Match(
                    layerName,
                    @"(\d+(?:\.\d+)?)\s*[xX×]\s*(\d+(?:\.\d+)?)");

            if (!match.Success)
                return 0.0;

            double canhA;
            double canhB;

            if (!double.TryParse(
                    match.Groups[1].Value,
                    NumberStyles.Any,
                    CultureInfo.InvariantCulture,
                    out canhA) ||
                !double.TryParse(
                    match.Groups[2].Value,
                    NumberStyles.Any,
                    CultureInfo.InvariantCulture,
                    out canhB))
                return 0.0;

            double chuViMet =
                ((canhA / 1000.0) * 2.0) +
                ((canhB / 1000.0) * 2.0);

            return chieuDaiMet * chuViMet;
        }

        private static string FormatSoThongKe(double value)
        {
            return Math.Round(value, 2)
                .ToString("0.##", CultureInfo.InvariantCulture);
        }

        private void XuatBangRaCad(
            List<ThongKeOng> data,
            string tieuDe = "BẢNG THỐNG KÊ KHỐI LƯỢNG ỐNG",
            string cotSoLuong = "SỐ LƯỢNG (m)",
            bool themCotM2OngGio = false,
            bool themCotTrucDung = false)
        {
            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var db = doc.Database;
            var ed = doc.Editor;

            PromptPointOptions ppo =
                new PromptPointOptions(
                    "\nKích chọn vị trí đặt Bảng thống kê: ");

            PromptPointResult ppr =
                ed.GetPoint(ppo);

            if (ppr.Status != PromptStatus.OK)
                return;

            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                BlockTableRecord btr =
                    (BlockTableRecord)tr.GetObject(
                        db.CurrentSpaceId,
                        OpenMode.ForWrite);

                Table tb =
                    new Table
                    {
                        TableStyle = db.Tablestyle
                    };

                tb.Color =
                    Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                        ColorMethod.ByAci,
                        2);

                // Bảng ống mới:
                // STT | LAYER | ỐNG NGANG | TRỤC ĐỨNG | TỔNG | M2
                // Các bảng thiết bị/van vẫn giữ bố cục cũ.
                int soCot =
                    themCotTrucDung
                        ? (themCotM2OngGio ? 6 : 5)
                        : (themCotM2OngGio ? 4 : 3);

                bool hasTotalRow =
                    themCotM2OngGio ||
                    themCotTrucDung;

                int soDong = data.Count + 2 +
                    (hasTotalRow ? 1 : 0);

                tb.SetSize(soDong, soCot);
                tb.Position = ppr.Value;

                // Cỡ bảng lớn, tỷ lệ cột cân với chiều cao chữ
                double sf = 12.0;
                double textH = 140.0 * sf;   // ~1680

                for (int r = 0;
                    r < tb.Rows.Count;
                    r++)
                {
                    // Hàng tiêu đề cao hơn một chút
                    tb.Rows[r].Height = (r == 0 ? 420.0 : 320.0) * sf;

                    for (int c = 0;
                        c < tb.Columns.Count;
                        c++)
                    {
                        tb.Cells[r, c].TextStyleId = db.Textstyle;
                        tb.Cells[r, c].TextHeight = textH;
                    }
                }

                // Độ rộng cột thay đổi theo chế độ bảng.
                tb.Columns[0].Width = 900.0 * sf;     // STT
                tb.Columns[1].Width =
                    (themCotTrucDung
                        ? 4300.0
                        : (themCotM2OngGio ? 4500.0 : 4800.0)) * sf;

                if (themCotTrucDung)
                {
                    tb.Columns[2].Width = 2100.0 * sf; // ngang
                    tb.Columns[3].Width = 2100.0 * sf; // đứng
                    tb.Columns[4].Width = 2000.0 * sf; // tổng

                    if (themCotM2OngGio)
                        tb.Columns[5].Width = 1800.0 * sf;
                }
                else
                {
                    tb.Columns[2].Width = 2200.0 * sf;

                    if (themCotM2OngGio)
                        tb.Columns[3].Width = 1800.0 * sf;
                }

                // Gộp hàng tiêu đề theo số cột thực tế
                try
                {
                    tb.MergeCells(
                        CellRange.Create(tb, 0, 0, 0, soCot - 1));
                }
                catch
                {
                    // một số version TableStyle không merge được — bỏ qua
                }

                tb.Cells[0, 0].TextString = tieuDe;
                tb.Cells[0, 0].Alignment =
                    CellAlignment.MiddleCenter;

                tb.Cells[1, 0].TextString = "STT";
                tb.Cells[1, 1].TextString = "TÊN LAYER";

                if (themCotTrucDung)
                {
                    tb.Cells[1, 2].TextString = "ỐNG NGANG (m)";
                    tb.Cells[1, 3].TextString = "TRỤC ĐỨNG (m)";
                    tb.Cells[1, 4].TextString = "TỔNG (m)";

                    if (themCotM2OngGio)
                        tb.Cells[1, 5].TextString = "M2";
                }
                else
                {
                    tb.Cells[1, 2].TextString = cotSoLuong;

                    if (themCotM2OngGio)
                        tb.Cells[1, 3].TextString = "M2";
                }

                for (int i = 0; i < soCot; i++)
                {
                    tb.Cells[1, i].Alignment =
                        CellAlignment.MiddleCenter;
                }

                int row = 2;

                foreach (var item in data)
                {
                    tb.Cells[row, 0].TextString =
                        item.STT.ToString();

                    tb.Cells[row, 0].Alignment =
                        CellAlignment.MiddleCenter;

                    tb.Cells[row, 1].TextString =
                        "   " + item.TenLayer;

                    tb.Cells[row, 1].Alignment =
                        CellAlignment.MiddleLeft;

                    if (themCotTrucDung)
                    {
                        tb.Cells[row, 2].TextString =
                            FormatSoThongKe(
                                item.ChieuDaiNgang);

                        tb.Cells[row, 3].TextString =
                            FormatSoThongKe(
                                item.ChieuDaiDung);

                        tb.Cells[row, 4].TextString =
                            FormatSoThongKe(
                                item.SoLuong);

                        tb.Cells[row, 2].Alignment =
                            CellAlignment.MiddleCenter;

                        tb.Cells[row, 3].Alignment =
                            CellAlignment.MiddleCenter;

                        tb.Cells[row, 4].Alignment =
                            CellAlignment.MiddleCenter;

                        if (themCotM2OngGio)
                        {
                            tb.Cells[row, 5].TextString =
                                FormatSoThongKe(item.M2);

                            tb.Cells[row, 5].Alignment =
                                CellAlignment.MiddleCenter;
                        }
                    }
                    else
                    {
                        tb.Cells[row, 2].TextString =
                            FormatSoThongKe(item.SoLuong);

                        tb.Cells[row, 2].Alignment =
                            CellAlignment.MiddleCenter;

                        if (themCotM2OngGio)
                        {
                            tb.Cells[row, 3].TextString =
                                FormatSoThongKe(item.M2);

                            tb.Cells[row, 3].Alignment =
                                CellAlignment.MiddleCenter;
                        }
                    }

                    row++;
                }

                if (hasTotalRow)
                {
                    try
                    {
                        tb.MergeCells(
                            CellRange.Create(tb, row, 0, row, 1));
                    }
                    catch
                    {
                    }

                    tb.Cells[row, 0].TextString = "TỔNG";
                    tb.Cells[row, 0].Alignment =
                        CellAlignment.MiddleCenter;

                    if (themCotTrucDung)
                    {
                        tb.Cells[row, 2].TextString =
                            FormatSoThongKe(
                                data.Sum(x => x.ChieuDaiNgang));

                        tb.Cells[row, 3].TextString =
                            FormatSoThongKe(
                                data.Sum(x => x.ChieuDaiDung));

                        tb.Cells[row, 4].TextString =
                            FormatSoThongKe(
                                data.Sum(x => x.SoLuong));

                        tb.Cells[row, 2].Alignment =
                            CellAlignment.MiddleCenter;

                        tb.Cells[row, 3].Alignment =
                            CellAlignment.MiddleCenter;

                        tb.Cells[row, 4].Alignment =
                            CellAlignment.MiddleCenter;

                        if (themCotM2OngGio)
                        {
                            tb.Cells[row, 5].TextString =
                                FormatSoThongKe(
                                    data.Sum(x => x.M2));

                            tb.Cells[row, 5].Alignment =
                                CellAlignment.MiddleCenter;
                        }
                    }
                    else
                    {
                        tb.Cells[row, 2].TextString =
                            FormatSoThongKe(
                                data.Sum(x => x.SoLuong));

                        tb.Cells[row, 2].Alignment =
                            CellAlignment.MiddleCenter;

                        if (themCotM2OngGio)
                        {
                            tb.Cells[row, 3].TextString =
                                FormatSoThongKe(
                                    data.Sum(x => x.M2));

                            tb.Cells[row, 3].Alignment =
                                CellAlignment.MiddleCenter;
                        }
                    }
                }

                tb.GenerateLayout();
                btr.AppendEntity(tb);
                tr.AddNewlyCreatedDBObject(tb, true);
                tr.Commit();
            }
        }

        private void BtnTimDoiTuong_Click(
            object sender,
            RoutedEventArgs e)
        {
            var doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            var ed = doc.Editor;
            var db = doc.Database;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            using (doc.LockDocument())
            {
                List<ObjectId> tempLines =
                    new List<ObjectId>();

                try
                {
                    PromptPointOptions ppo =
                        new PromptPointOptions(
                            "\nKích chọn trực tiếp vào dòng " +
                            "tên layer cần tìm trong Bảng: ");

                    PromptPointResult ppr =
                        ed.GetPoint(ppo);

                    if (ppr.Status != PromptStatus.OK)
                        return;

                    Point3d hitPt = ppr.Value;

                    using (Transaction tr =
                        db.TransactionManager.StartTransaction())
                    {
                        BlockTableRecord btr =
                            (BlockTableRecord)tr.GetObject(
                                db.CurrentSpaceId,
                                OpenMode.ForWrite);

                        Table targetTable = null;
                        double minBoxDist = double.MaxValue;

                        foreach (ObjectId id in btr)
                        {
                            if (id.ObjectClass.IsDerivedFrom(
                                RXClass.GetClass(
                                    typeof(Table))))
                            {
                                Table tb =
                                    tr.GetObject(
                                        id,
                                        OpenMode.ForRead)
                                        as Table;

                                if (tb != null)
                                {
                                    double dist =
                                        Math.Abs(
                                            hitPt.X -
                                            tb.Position.X) +
                                        Math.Abs(
                                            hitPt.Y -
                                            tb.Position.Y);

                                    if (dist < minBoxDist)
                                    {
                                        minBoxDist = dist;
                                        targetTable = tb;
                                    }
                                }
                            }
                        }

                        if (targetTable == null)
                        {
                            MessageBox.Show(
                                "Không tìm thấy Bảng thống kê!",
                                "Thông báo");

                            return;
                        }

                        int targetRow = -1;
                        double curY =
                            targetTable.Position.Y;

                        for (int r = 0;
                            r < targetTable.Rows.Count;
                            r++)
                        {
                            double h =
                                targetTable.Rows[r].Height;

                            if (hitPt.Y <= curY &&
                                hitPt.Y >= curY - h)
                            {
                                targetRow = r;
                                break;
                            }

                            curY -= h;
                        }

                        if (targetRow < 2)
                        {
                            MessageBox.Show(
                                "Hãy kích vào dòng dữ liệu " +
                                "bên trong bảng!",
                                "Nhắc nhở");

                            return;
                        }

                        string targetLayer =
                            targetTable
                                .Cells[targetRow, 1]
                                .TextString
                                .Trim();

                        TypedValue[] tvs =
                            new TypedValue[]
                            {
                                new TypedValue(
                                    (int)DxfCode.Start,
                                    "LWPOLYLINE"),
                                new TypedValue(
                                    (int)DxfCode.LayerName,
                                    targetLayer)
                            };

                        PromptSelectionResult psr =
                            ed.SelectAll(
                                new SelectionFilter(tvs));

                        if (psr.Status != PromptStatus.OK ||
                            psr.Value.Count == 0)
                        {
                            MessageBox.Show(
                                $"Không tìm thấy đoạn ống nào " +
                                $"thuộc Layer: {targetLayer}",
                                "Thông báo");

                            return;
                        }

                        foreach (
                            SelectedObject so in psr.Value)
                        {
                            Polyline pline =
                                tr.GetObject(
                                    so.ObjectId,
                                    OpenMode.ForRead)
                                    as Polyline;

                            if (pline != null &&
                                pline.Length > 0)
                            {
                                Line pointerLine =
                                    new Line(
                                        hitPt,
                                        pline.GetPointAtDist(
                                            pline.Length /
                                            2.0))
                                    {
                                        ColorIndex = 1
                                    };

                                tempLines.Add(
                                    btr.AppendEntity(
                                        pointerLine));

                                tr.AddNewlyCreatedDBObject(
                                    pointerLine,
                                    true);
                            }
                        }

                        tr.Commit();
                    }

                    ed.GetPoint(
                        new PromptPointOptions(
                            "\n[Đang chỉ vạch] Bấm ENTER " +
                            "hoặc kích chuột để xóa và kết thúc: ")
                        {
                            AllowNone = true
                        });
                }
                catch
                {
                }
                finally
                {
                    if (tempLines.Count > 0)
                    {
                        try
                        {
                            using (Transaction tr =
                                db.TransactionManager
                                    .StartTransaction())
                            {
                                foreach (
                                    ObjectId id in tempLines)
                                {
                                    if (!id.IsErased &&
                                        id.IsValid)
                                    {
                                        Entity ent =
                                            tr.GetObject(
                                                id,
                                                OpenMode.ForWrite)
                                                as Entity;

                                        ent?.Erase();
                                    }
                                }

                                tr.Commit();
                            }

                            ed.Regen();
                        }
                        catch
                        {
                        }
                    }
                }
            }
        }

        private void Db_ObjectAppended(
            object sender,
            ObjectEventArgs e)
        {
            if (!_isWaitingForPline ||
                _plineWatcherDocument == null ||
                e == null)
            {
                return;
            }

            Database eventDatabase =
                sender as Database;

            if (eventDatabase != null &&
                eventDatabase !=
                _plineWatcherDocument.Database)
            {
                return;
            }

            Polyline pline =
                e.DBObject as Polyline;

            if (pline == null)
                return;

            if (!string.Equals(
                pline.Layer,
                _currentLayerNameForText,
                StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            _lastPlineId = pline.Id;
            _pendingPlineIds.Add(pline.Id);
        }

        private void StartPlineTextWatcher(Document doc)
        {
            if (doc == null)
                return;

            if (_isWaitingForPline &&
                _plineWatcherDocument == doc)
            {
                return;
            }

            if (_isWaitingForPline &&
                _plineWatcherDocument != null)
            {
                CleanupEvents(
                    _plineWatcherDocument);
            }

            _plineWatcherDocument = doc;

            doc.Database.ObjectAppended +=
                Db_ObjectAppended;

            doc.CommandEnded +=
                Doc_CommandEnded;

            doc.CommandCancelled +=
                Doc_CommandCancelled;

            _isWaitingForPline = true;
        }

        private bool IsPlineCommand(CommandEventArgs e)
        {
            string commandName =
                (e?.GlobalCommandName ?? "")
                    .Trim()
                    .TrimStart('.', '_');

            return string.Equals(
                commandName,
                "PLINE",
                StringComparison.OrdinalIgnoreCase);
        }

        private void Doc_CommandEnded(
            object sender,
            CommandEventArgs e)
        {
            if (_isWaitingForPline &&
                IsPlineCommand(e))
            {
                AddTextToPendingPolylines(
                    sender as Document ??
                    _plineWatcherDocument,
                    true);

                _lastPlineId = ObjectId.Null;
                _pendingPlineIds.Clear();
            }
        }

        private void Doc_CommandCancelled(
            object sender,
            CommandEventArgs e)
        {
            if (_isWaitingForPline &&
                IsPlineCommand(e))
            {
                AddTextToPendingPolylines(
                    sender as Document ??
                    _plineWatcherDocument,
                    false);

                _lastPlineId = ObjectId.Null;
                _pendingPlineIds.Clear();
            }
        }

        private void AddTextToPendingPolylines(
            Document doc,
            bool allowFallback)
        {
            if (doc == null)
                return;

            if (_pendingPlineIds.Count == 0 &&
                _lastPlineId != ObjectId.Null)
            {
                _pendingPlineIds.Add(
                    _lastPlineId);
            }

            List<ObjectId> candidates =
                _pendingPlineIds
                    .Where(
                        id =>
                            id != ObjectId.Null &&
                            id.IsValid &&
                            !id.IsErased)
                    .ToList();

            if (allowFallback &&
                candidates.Count == 0)
            {
                ObjectId newestPlineId =
                    FindNewestUnprocessedPolyline(doc);

                if (newestPlineId != ObjectId.Null)
                    candidates.Add(newestPlineId);
            }

            foreach (ObjectId id in candidates)
            {
                if (_processedPlineIds.Contains(id))
                    continue;

                if (AddTextToPolyline(
                    doc,
                    id,
                    _currentLayerNameForText,
                    _currentPlineWidth))
                {
                    _processedPlineIds.Add(id);
                }
            }
        }

        private ObjectId FindNewestUnprocessedPolyline(
            Document doc)
        {
            ObjectId newestId = ObjectId.Null;
            long newestHandle = long.MinValue;

            try
            {
                using (doc.LockDocument())
                using (Transaction tr =
                    doc.Database.TransactionManager
                        .StartTransaction())
                {
                    BlockTableRecord space =
                        (BlockTableRecord)tr.GetObject(
                            doc.Database.CurrentSpaceId,
                            OpenMode.ForRead);

                    foreach (ObjectId id in space)
                    {
                        if (_processedPlineIds.Contains(id))
                            continue;

                        Polyline pline =
                            tr.GetObject(
                                id,
                                OpenMode.ForRead,
                                false)
                                as Polyline;

                        if (pline == null ||
                            pline.NumberOfVertices < 2)
                        {
                            continue;
                        }

                        if (!string.Equals(
                            pline.Layer,
                            _currentLayerNameForText,
                            StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }

                        long handleValue =
                            id.Handle.Value;

                        if (handleValue > newestHandle)
                        {
                            newestHandle = handleValue;
                            newestId = id;
                        }
                    }

                    tr.Commit();
                }
            }
            catch
            {
                return ObjectId.Null;
            }

            return newestId;
        }

        private void CleanupEvents(Document doc)
        {
            _isWaitingForPline = false;
            _lastPlineId = ObjectId.Null;
            _pendingPlineIds.Clear();

            if (doc != null)
            {
                doc.Database.ObjectAppended -=
                    Db_ObjectAppended;

                doc.CommandEnded -=
                    Doc_CommandEnded;

                doc.CommandCancelled -=
                    Doc_CommandCancelled;
            }

            if (_plineWatcherDocument == doc)
                _plineWatcherDocument = null;
        }

        private bool AddTextToPolyline(
            Document doc,
            ObjectId plineId,
            string layerName,
            double width)
        {
            if (doc == null ||
                plineId == ObjectId.Null ||
                !plineId.IsValid ||
                plineId.IsErased)
            {
                return false;
            }

            var db = doc.Database;

            try
            {
                using (doc.LockDocument())
                using (Transaction tr =
                    db.TransactionManager.StartTransaction())
                {
                    Polyline pline =
                        tr.GetObject(
                            plineId,
                            OpenMode.ForRead)
                            as Polyline;

                    if (pline == null)
                        return false;

                    BlockTableRecord owner =
                        (BlockTableRecord)tr.GetObject(
                            pline.OwnerId,
                            OpenMode.ForWrite);

                    double textHeight =
                        Math.Max(
                            width *
                            LabelTextHeightToWidthRatio,
                            MinimumLabelTextHeight);

                    int segmentCount =
                        pline.Closed
                            ? pline.NumberOfVertices
                            : pline.NumberOfVertices - 1;

                    for (int i = 0;
                        i < segmentCount;
                        i++)
                    {
                        if (pline.GetSegmentType(i) !=
                            SegmentType.Line)
                        {
                            continue;
                        }

                        LineSegment3d segment =
                            pline.GetLineSegmentAt(i);

                        double segmentLength =
                            segment.StartPoint.DistanceTo(
                                segment.EndPoint);

                        // Dưới 3m: vẫn hiện chữ, chỉ DN (+ CN/EI nếu có)
                        // Từ 3m trở lên: hiện full layer như cũ
                        string displayText =
                            segmentLength <
                            ManualMinimumLabelSegmentLength
                                ? GetShortSizeLabel(layerName)
                                : layerName;

                        if (string.IsNullOrWhiteSpace(displayText))
                            continue;

                        Point3d midPt =
                            segment.MidPoint;

                        Vector3d dir =
                            segment.Direction;

                        double angle =
                            dir.AngleOnPlane(
                                new Plane());

                        if (angle > Math.PI / 2 &&
                            angle <=
                            3 * Math.PI / 2)
                        {
                            angle -= Math.PI;
                            dir = dir.Negate();
                        }

                        Point3d textPt =
                            midPt +
                            dir.RotateBy(
                                Math.PI / 2,
                                Vector3d.ZAxis) *
                            ((width / 2.0) +
                             (textHeight * 0.2));

                        DBText txt = new DBText();
                        txt.SetDatabaseDefaults(db);
                        txt.TextString = displayText;
                        txt.Height = textHeight;
                        txt.Layer = layerName;
                        txt.ColorIndex = 256;
                        txt.Justify =
                            AttachmentPoint.BottomCenter;

                        txt.AlignmentPoint = textPt;
                        txt.Rotation = angle;

                        owner.AppendEntity(txt);

                        tr.AddNewlyCreatedDBObject(
                            txt,
                            true);
                    }

                    tr.Commit();
                    return true;
                }
            }
            catch (System.Exception ex)
            {
                doc.Editor.WriteMessage(
                    $"\nKhông thể tạo chữ theo nét vẽ: " +
                    $"{ex.Message}");

                return false;
            }
        }

        private void UserControl_Unloaded(
            object sender,
            RoutedEventArgs e)
        {
            if (_isWaitingForPline)
                CleanupEvents(_plineWatcherDocument);

            StopReview3DEscapeWatcher();

            DisposeOnnxSymbolClassifier();
            DisposeMepGraphGnnClassifier();
        }

        /// <summary>
        /// Tự động thu nhỏ / phóng to toàn bộ giao diện theo chiều rộng palette.
        /// Trên laptop hẹp sẽ scale nhỏ lại (tối thiểu 0.72), trên máy to vẫn gần 1.0.
        /// </summary>
        private void UserControl_SizeChanged(object sender, SizeChangedEventArgs e)
        {
            if (UiScale == null) return;

            // Chiều rộng thiết kế gốc của palette
            const double baseWidth = 360.0;

            // Giới hạn scale để không quá nhỏ hoặc quá to
            double scale = Math.Max(0.72, Math.Min(1.05, ActualWidth / baseWidth));

            UiScale.ScaleX = scale;
            UiScale.ScaleY = scale;
        }

        // ==================== ĐẶT THIẾT BỊ MẪU ====================

        private void BtnDatThietBiMau_Click(object sender, RoutedEventArgs e)
        {
            var doc = Autodesk.AutoCAD.ApplicationServices.Core.Application
                .DocumentManager.MdiActiveDocument;
            if (doc == null) return;

            var db = doc.Database;
            var ed = doc.Editor;

            Autodesk.AutoCAD.Internal.Utils.SetFocusToDwgView();

            // 1. Chọn text mẫu
            ed.WriteMessage("\n[ĐẶT THIẾT BỊ MẪU] Chọn TEXT mẫu đã đặt: ");
            var peoText = new PromptEntityOptions("\nChọn Text mẫu: ");
            peoText.SetRejectMessage("\nChỉ chọn TEXT hoặc MTEXT.");
            peoText.AddAllowedClass(typeof(DBText), false);
            peoText.AddAllowedClass(typeof(MText), false);
            var perText = ed.GetEntity(peoText);
            if (perText.Status != PromptStatus.OK) return;

            // 2. Chọn block mẫu
            ed.WriteMessage("\nChọn BLOCK mẫu tương ứng: ");
            var peoBlock = new PromptEntityOptions("\nChọn Block mẫu: ");
            peoBlock.SetRejectMessage("\nChỉ chọn Block Reference.");
            peoBlock.AddAllowedClass(typeof(BlockReference), false);
            var perBlock = ed.GetEntity(peoBlock);
            if (perBlock.Status != PromptStatus.OK) return;

            string sampleTextString = "";
            string sampleLayer = "0";
            double sampleHeight = MinimumLabelTextHeight;
            double sampleRotation = 0;
            Point3d sampleTextPos = Point3d.Origin;
            AttachmentPoint sampleJustify = AttachmentPoint.MiddleCenter;
            bool isMText = false;

            string sampleBlockName = "";
            Point3d sampleBlockPos = Point3d.Origin;
            double sampleBlockRotation = 0;
            Scale3d sampleBlockScale = new Scale3d(1);

            using (doc.LockDocument())
            using (Transaction tr = db.TransactionManager.StartTransaction())
            {
                Entity textEnt = tr.GetObject(perText.ObjectId, OpenMode.ForRead) as Entity;
                BlockReference blk = tr.GetObject(perBlock.ObjectId, OpenMode.ForRead) as BlockReference;

                if (textEnt == null || blk == null)
                {
                    MessageBox.Show("Không đọc được text hoặc block mẫu.", "Lỗi");
                    return;
                }

                sampleBlockName = blk.Name;
                sampleBlockPos = blk.Position;
                sampleBlockRotation = blk.Rotation;
                sampleBlockScale = blk.ScaleFactors;

                if (textEnt is DBText dbText)
                {
                    sampleTextString = dbText.TextString;
                    sampleLayer = dbText.Layer;
                    sampleHeight = dbText.Height;
                    sampleRotation = dbText.Rotation;
                    sampleTextPos = dbText.AlignmentPoint;
                    if (sampleTextPos.IsEqualTo(Point3d.Origin) ||
                        dbText.Justify == AttachmentPoint.BaseLeft)
                        sampleTextPos = dbText.Position;
                    sampleJustify = dbText.Justify;
                }
                else if (textEnt is MText mText)
                {
                    isMText = true;
                    sampleTextString = mText.Contents;
                    sampleLayer = mText.Layer;
                    sampleHeight = mText.TextHeight;
                    sampleRotation = mText.Rotation;
                    sampleTextPos = mText.Location;
                }

                tr.Commit();
            }

            if (string.IsNullOrWhiteSpace(sampleTextString) ||
                string.IsNullOrWhiteSpace(sampleBlockName))
            {
                MessageBox.Show("Text hoặc Block mẫu không hợp lệ.", "Cảnh báo");
                return;
            }

            // Vector offset từ block → text (trong hệ tọa độ thế giới)
            Vector3d offsetWorld = sampleTextPos - sampleBlockPos;

            // 3. Quét chọn vùng
            ed.WriteMessage(
                $"\n[ĐẶT THIẾT BỊ MẪU] Block mẫu: {sampleBlockName} | Text: {sampleTextString}");
            ed.WriteMessage("\nQuét chọn vùng chứa các block cần đặt text (Enter kết thúc): ");

            var pso = new PromptSelectionOptions
            {
                MessageForAdding = "\nChọn các đối tượng trong vùng (hoặc quét cửa sổ): ",
                AllowDuplicates = false
            };

            // Chỉ lấy BlockReference
            var filter = new SelectionFilter(new[]
            {
                new TypedValue((int)DxfCode.Start, "INSERT")
            });

            var psr = ed.GetSelection(pso, filter);
            if (psr.Status != PromptStatus.OK || psr.Value.Count == 0)
            {
                ed.WriteMessage("\nKhông có block nào được chọn.");
                return;
            }

            int placed = 0;
            int skippedSame = 0;

            using (doc.LockDocument())
            using (Transaction tr = db.TransactionManager.StartTransaction())
            {
                BlockTableRecord btr = (BlockTableRecord)tr.GetObject(
                    db.CurrentSpaceId, OpenMode.ForWrite);

                EnsureLayerExists(tr, db, sampleLayer, false);

                foreach (SelectedObject so in psr.Value)
                {
                    if (so == null || so.ObjectId == perBlock.ObjectId)
                    {
                        skippedSame++;
                        continue; // bỏ qua block mẫu
                    }

                    BlockReference other = tr.GetObject(so.ObjectId, OpenMode.ForRead) as BlockReference;
                    if (other == null) continue;

                    // Chỉ lấy block cùng tên
                    if (!string.Equals(other.Name, sampleBlockName, StringComparison.OrdinalIgnoreCase))
                        continue;

                    // Tính vị trí text mới = vị trí block mới + offset (có xét scale & rotation nếu cần)
                    // Đơn giản: giữ offset theo hệ thế giới (đủ dùng hầu hết trường hợp)
                    Point3d newTextPos = other.Position + offsetWorld;

                    // Nếu block bị xoay / scale khác mẫu thì có thể biến đổi offset
                    // (nâng cao – hiện tại giữ offset cố định cho ổn định)

                    if (isMText)
                    {
                        MText mt = new MText();
                        mt.SetDatabaseDefaults(db);
                        mt.Contents = sampleTextString;
                        mt.TextHeight = sampleHeight;
                        mt.Layer = sampleLayer;
                        mt.ColorIndex = 256;
                        mt.Location = newTextPos;
                        mt.Rotation = sampleRotation;
                        btr.AppendEntity(mt);
                        tr.AddNewlyCreatedDBObject(mt, true);
                    }
                    else
                    {
                        DBText txt = new DBText();
                        txt.SetDatabaseDefaults(db);
                        txt.TextStyleId = db.Textstyle;
                        txt.TextString = sampleTextString;
                        txt.Height = sampleHeight;
                        txt.WidthFactor = 1.0;
                        txt.Layer = sampleLayer;
                        txt.ColorIndex = 256;
                        txt.Justify = sampleJustify;
                        txt.Rotation = sampleRotation;

                        if (sampleJustify == AttachmentPoint.BaseLeft ||
                            sampleJustify == AttachmentPoint.BaseCenter ||
                            sampleJustify == AttachmentPoint.BaseRight ||
                            sampleJustify == AttachmentPoint.BaseAlign ||
                            sampleJustify == AttachmentPoint.BaseFit)
                        {
                            txt.Position = newTextPos;
                        }
                        else
                        {
                            txt.AlignmentPoint = newTextPos;
                            try { txt.AdjustAlignment(db); } catch { }
                        }

                        btr.AppendEntity(txt);
                        tr.AddNewlyCreatedDBObject(txt, true);
                    }

                    placed++;
                }

                tr.Commit();
            }

            ed.Regen();
            ed.WriteMessage(
                $"\n[ĐẶT THIẾT BỊ MẪU] Đã đặt {placed} text trên các block '{sampleBlockName}'." +
                (skippedSame > 0 ? $" (bỏ qua {skippedSame} block mẫu)" : ""));
        }

