        private string OnnxAiModelFolder
        {
            get
            {
                try
                {
                    string baseFolder =
                        Environment.GetFolderPath(
                            Environment.SpecialFolder.ApplicationData);

                    if (string.IsNullOrWhiteSpace(
                            baseFolder))
                    {
                        baseFolder =
                            Path.GetTempPath();
                    }

                    string folder =
                        Path.Combine(
                            baseFolder,
                            "TDL_MEP",
                            "AI",
                            "models");

                    if (!Directory.Exists(
                            folder))
                    {
                        Directory.CreateDirectory(
                            folder);
                    }

                    return folder;
                }
                catch
                {
                    return
                        Path.Combine(
                            Path.GetTempPath(),
                            "TDL_MEP_AI_models");
                }
            }
        }

        private string OnnxDefaultModelPath =>
            Path.Combine(
                OnnxAiModelFolder,
                "mep_symbol_classifier.onnx");

        private string OnnxDefaultLabelsPath =>
            Path.Combine(
                OnnxAiModelFolder,
                "mep_symbol_labels.txt");

        private bool ResolveOnnxModelFiles(
            out string modelPath,
            out string labelsPath)
        {
            modelPath = "";
            labelsPath = "";

            try
            {
                if (File.Exists(
                        OnnxDefaultModelPath) &&
                    File.Exists(
                        OnnxDefaultLabelsPath))
                {
                    modelPath =
                        OnnxDefaultModelPath;

                    labelsPath =
                        OnnxDefaultLabelsPath;

                    return true;
                }
            }
            catch
            {
            }

            // Fallback: cho phép deploy model ngay cạnh DLL plugin.
            try
            {
                string pluginFolder =
                    Path.GetDirectoryName(
                        Assembly.GetExecutingAssembly()
                            .Location) ??
                    "";

                string[] modelCandidates =
                {
                    Path.Combine(
                        pluginFolder,
                        "AI",
                        "models",
                        "mep_symbol_classifier.onnx"),
                    Path.Combine(
                        pluginFolder,
                        "mep_symbol_classifier.onnx")
                };

                foreach (string candidate
                    in modelCandidates)
                {
                    if (!File.Exists(
                            candidate))
                    {
                        continue;
                    }

                    string folder =
                        Path.GetDirectoryName(
                            candidate) ??
                        pluginFolder;

                    string[] labelCandidates =
                    {
                        Path.Combine(
                            folder,
                            "mep_symbol_labels.txt"),
                        Path.ChangeExtension(
                            candidate,
                            ".txt"),
                        Path.Combine(
                            folder,
                            "labels.txt")
                    };

                    string labels =
                        labelCandidates.FirstOrDefault(
                            File.Exists);

                    if (string.IsNullOrWhiteSpace(
                            labels))
                    {
                        continue;
                    }

                    modelPath =
                        candidate;

                    labelsPath =
                        labels;

                    return true;
                }
            }
            catch
            {
            }

            return false;
        }

        private MepSymbolClassifier GetOnnxSymbolClassifier(
            bool forceReload = false)
        {
            if (!ResolveOnnxModelFiles(
                    out string modelPath,
                    out string labelsPath))
            {
                DisposeOnnxSymbolClassifier();
                _onnxLastLoadError = "";
                return null;
            }

            DateTime writeUtc =
                DateTime.MinValue;

            try
            {
                writeUtc =
                    File.GetLastWriteTimeUtc(
                        modelPath);
            }
            catch
            {
            }

            if (!forceReload &&
                _onnxSymbolClassifier != null &&
                string.Equals(
                    _onnxLoadedModelPath,
                    modelPath,
                    StringComparison.OrdinalIgnoreCase) &&
                _onnxLoadedModelWriteUtc ==
                    writeUtc)
            {
                return
                    _onnxSymbolClassifier;
            }

            DisposeOnnxSymbolClassifier();

            try
            {
                _onnxSymbolClassifier =
                    new MepSymbolClassifier(
                        modelPath,
                        labelsPath);

                _onnxLoadedModelPath =
                    modelPath;

                _onnxLoadedModelWriteUtc =
                    writeUtc;

                _onnxLastLoadError =
                    "";

                return
                    _onnxSymbolClassifier;
            }
            catch (System.Exception ex)
            {
                _onnxLastLoadError =
                    ex.GetType().Name +
                    ": " +
                    ex.Message;

                DisposeOnnxSymbolClassifier();

                return null;
            }
        }

        private void DisposeOnnxSymbolClassifier()
        {
            try
            {
                _onnxSymbolClassifier?.Dispose();
            }
            catch
            {
            }

            _onnxSymbolClassifier =
                null;

            _onnxLoadedModelPath =
                "";

            _onnxLoadedModelWriteUtc =
                DateTime.MinValue;
        }

