        private void BtnOnnxLoadModel_Click(
            object sender,
            RoutedEventArgs e)
        {
            try
            {
                Microsoft.Win32.OpenFileDialog modelDialog =
                    new Microsoft.Win32.OpenFileDialog
                    {
                        Title =
                            "Chọn model phân loại ký hiệu MEP (.onnx)",
                        Filter =
                            "ONNX model (*.onnx)|*.onnx|All files (*.*)|*.*",
                        CheckFileExists =
                            true,
                        Multiselect =
                            false
                    };

                bool? selected =
                    modelDialog.ShowDialog();

                if (selected != true)
                    return;

                string selectedModel =
                    modelDialog.FileName;

                string modelFolder =
                    Path.GetDirectoryName(
                        selectedModel) ??
                    "";

                string[] candidateLabels =
                {
                    Path.Combine(
                        modelFolder,
                        "mep_symbol_labels.txt"),
                    Path.ChangeExtension(
                        selectedModel,
                        ".txt"),
                    Path.Combine(
                        modelFolder,
                        "labels.txt")
                };

                string selectedLabels =
                    candidateLabels.FirstOrDefault(
                        File.Exists) ??
                    "";

                if (string.IsNullOrWhiteSpace(
                        selectedLabels))
                {
                    Microsoft.Win32.OpenFileDialog labelsDialog =
                        new Microsoft.Win32.OpenFileDialog
                        {
                            Title =
                                "Chọn file labels của model (mỗi dòng = 1 class)",
                            Filter =
                                "Text labels (*.txt)|*.txt|All files (*.*)|*.*",
                            CheckFileExists =
                                true,
                            Multiselect =
                                false
                        };

                    bool? labelsSelected =
                        labelsDialog.ShowDialog();

                    if (labelsSelected != true)
                    {
                        MessageBox.Show(
                            "Chưa chọn labels nên chưa thể nạp model ONNX.",
                            "ONNX AI");
                        return;
                    }

                    selectedLabels =
                        labelsDialog.FileName;
                }

                Directory.CreateDirectory(
                    OnnxAiModelFolder);

                CopyFileIfDifferent(
                    selectedModel,
                    OnnxDefaultModelPath);

                CopyFileIfDifferent(
                    selectedLabels,
                    OnnxDefaultLabelsPath);

                MepSymbolClassifier classifier =
                    GetOnnxSymbolClassifier(
                        true);

                UpdateOnnxStatusUi();

                if (classifier == null)
                {
                    MessageBox.Show(
                        "Đã copy model nhưng ONNX Runtime chưa load được.\n\n" +
                        (_onnxLastLoadError ?? "Unknown") +
                        "\n\nPlugin vẫn chạy bằng CAD Native/Vector/Vision cũ.",
                        "ONNX AI");
                    return;
                }

                MessageBox.Show(
                    "Đã nạp model ONNX thành công.\n\n" +
                    "Classes: " + classifier.ClassCount + "\n" +
                    "Input: " + classifier.InputWidth + "×" + classifier.InputHeight + " " + classifier.InputLayout + "\n\n" +
                    "ONNX sẽ được dùng sau Exact Block + Vector, trước Vision Lite.",
                    "ONNX AI");
            }
            catch (System.Exception ex)
            {
                MessageBox.Show(
                    "Không nạp được model ONNX:\n" +
                    ex.Message,
                    "ONNX AI");
            }
        }

        private void CopyFileIfDifferent(
            string source,
            string destination)
        {
            if (string.IsNullOrWhiteSpace(
                    source) ||
                string.IsNullOrWhiteSpace(
                    destination))
            {
                return;
            }

            string sourceFull =
                Path.GetFullPath(
                    source);

            string destinationFull =
                Path.GetFullPath(
                    destination);

            if (string.Equals(
                    sourceFull,
                    destinationFull,
                    StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            string folder =
                Path.GetDirectoryName(
                    destinationFull) ??
                "";

            if (!string.IsNullOrWhiteSpace(
                    folder))
            {
                Directory.CreateDirectory(
                    folder);
            }

            File.Copy(
                sourceFull,
                destinationFull,
                true);
        }

        private bool TryResolveOnnxPredictionToRule(
            MepSymbolClassifier.Prediction prediction,
            List<SmartSymbolRule> rules,
            out SmartSymbolRule bestRule)
        {
            bestRule =
                null;

            if (prediction == null ||
                !prediction.Success ||
                rules == null ||
                rules.Count == 0)
            {
                return false;
            }

            if (prediction.Confidence <
                    OnnxDeviceMinConfidence ||
                prediction.Margin <
                    OnnxDeviceMinMargin)
            {
                return false;
            }

            string predictedName =
                GetOnnxDisplayLabel(
                    prediction.Label);

            string predictedKey =
                NormalizeOnnxDisplayKey(
                    predictedName);

            if (string.IsNullOrWhiteSpace(
                    predictedKey))
            {
                return false;
            }

            List<SmartSymbolRule> labelMatches =
                rules
                    .Where(
                        r =>
                            r != null &&
                            !string.IsNullOrWhiteSpace(
                                r.DisplayName) &&
                            string.Equals(
                                NormalizeOnnxDisplayKey(
                                    r.DisplayName),
                                predictedKey,
                                StringComparison.OrdinalIgnoreCase))
                    .OrderBy(
                        r =>
                            string.Equals(
                                r.MatchMode,
                                "BLOCK",
                                StringComparison.OrdinalIgnoreCase)
                                ? 0
                                : string.Equals(
                                      r.MatchMode,
                                      "GEOMETRY",
                                      StringComparison.OrdinalIgnoreCase)
                                    ? 1
                                    : 2)
                    .ToList();

            if (labelMatches.Count == 0)
            {
                return false;
            }

            bestRule =
                labelMatches[0];

            return true;
        }

        private bool TryMatchSmartGeometryClusterByOnnx(
            Transaction tr,
            List<ObjectId> ids,
            List<SmartSymbolRule> rules,
            out SmartSymbolRule bestRule,
            out MepSymbolClassifier.Prediction prediction)
        {
            bestRule =
                null;

            prediction =
                null;

            if (tr == null ||
                ids == null ||
                ids.Count == 0 ||
                rules == null ||
                rules.Count == 0)
            {
                return false;
            }

            MepSymbolClassifier classifier =
                GetOnnxSymbolClassifier();

            if (classifier == null)
                return false;

            using (System.Drawing.Bitmap bitmap =
                CreateSmartLegendPreviewBitmap(
                    tr,
                    ids,
                    128,
                    128))
            {
                prediction =
                    classifier.Predict(
                        bitmap);
            }

            return
                TryResolveOnnxPredictionToRule(
                    prediction,
                    rules,
                    out bestRule);
        }

        private bool TryMatchSmartBlockByOnnx(
            Transaction tr,
            BlockReference br,
            List<SmartSymbolRule> rules,
            out SmartSymbolRule bestRule,
            out MepSymbolClassifier.Prediction prediction)
        {
            bestRule =
                null;

            prediction =
                null;

            if (tr == null ||
                br == null ||
                rules == null ||
                rules.Count == 0)
            {
                return false;
            }

            MepSymbolClassifier classifier =
                GetOnnxSymbolClassifier();

            if (classifier == null)
                return false;

            using (System.Drawing.Bitmap bitmap =
                CreateSmartLegendPreviewBitmap(
                    tr,
                    new List<ObjectId>
                    {
                        br.ObjectId
                    },
                    128,
                    128))
            {
                prediction =
                    classifier.Predict(
                        bitmap);
            }

            return
                TryResolveOnnxPredictionToRule(
                    prediction,
                    rules,
                    out bestRule);
        }


        private string GetOnnxDisplayLabel(
            string rawLabel)
        {
            string value =
                (rawLabel ?? "")
                    .Trim();

            // Cho phép labels file dạng:
            // FLOW_SWITCH|CÔNG TẮC DÒNG CHẢY KÈM GIÁM SÁT
            int separator =
                value.IndexOf('|');

            if (separator >= 0 &&
                separator <
                    value.Length - 1)
            {
                value =
                    value.Substring(
                            separator + 1)
                        .Trim();
            }

            return value;
        }

        private string NormalizeOnnxDisplayKey(
            string value)
        {
            string normalized =
                NormalizeSmartDisplayName(
                    value ?? "");

            normalized =
                BoDauTiengViet(
                    normalized)
                    .ToUpperInvariant();

            normalized =
                Regex.Replace(
                    normalized,
                    @"[^A-Z0-9]+",
                    " ");

            normalized =
                Regex.Replace(
                    normalized,
                    @"\s+",
                    " ")
                    .Trim();

            return normalized;
        }

