        private void RunAiAutomaticPipeTakeoff()
        {
            Document doc =
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .DocumentManager
                    .MdiActiveDocument;

            if (doc == null)
                return;

            Editor ed = doc.Editor;

            try
            {
                Autodesk.AutoCAD.ApplicationServices.Core.Application
                    .MainWindow
                    .Focus();
            }
            catch
            {
            }

            MessageBoxResult confirm =
                MessageBox.Show(
                    "AI sẽ dựng lớp nhận diện ĐƯỜNG ỐNG riêng trên bản vẽ.\n\n" +
                    "• Không xóa/sửa nét gốc.\n" +
                    "• Đường nhận diện: TDL_AI_PIPE_DN...\n" +
                    "• Đoạn chưa chắc chắn: TDL_AI_PIPE_CHECK.\n" +
                    "• Chạy lại sẽ xóa output AI PIPE cũ rồi dựng lại.\n" +
                    "• Tự loại REVCLOUD/đám mây và các curve không giống đường ống.\n" +
                    "• Nhận diện VAN / THIẾT BỊ đã tách thành nút riêng trong tab AI.\n\n" +
                    "Tiếp tục nhận diện ĐƯỜNG ỐNG?",
                    "AI BÓC TÁCH MEP",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Information);

            if (confirm != MessageBoxResult.Yes)
                return;

            PromptSelectionOptions pso =
                new PromptSelectionOptions();

            pso.MessageForAdding =
                "\n[AI BÓC TÁCH] Quét vùng có đường ống + TEXT DN/D/Ø: ";

            TypedValue[] tvs =
                new TypedValue[]
                {
                    new TypedValue((int)DxfCode.Operator, "<OR"),
                    new TypedValue((int)DxfCode.Start, "LINE"),
                    new TypedValue((int)DxfCode.Start, "LWPOLYLINE"),
                    new TypedValue((int)DxfCode.Start, "POLYLINE"),
                    new TypedValue((int)DxfCode.Start, "ARC"),
                    new TypedValue((int)DxfCode.Start, "CIRCLE"),
                    new TypedValue((int)DxfCode.Start, "INSERT"),
                    new TypedValue((int)DxfCode.Start, "POINT"),
                    new TypedValue((int)DxfCode.Start, "TEXT"),
                    new TypedValue((int)DxfCode.Start, "MTEXT"),
                    new TypedValue((int)DxfCode.Operator, "OR>")
                };

            PromptSelectionResult psr =
                ed.GetSelection(
                    pso,
                    new SelectionFilter(tvs));

            if (psr.Status != PromptStatus.OK ||
                psr.Value == null ||
                psr.Value.Count == 0)
            {
                return;
            }

            AiPipeTakeoffRunResult run =
                AnalyzeAndDrawAiPipeTakeoff(
                    doc,
                    psr.Value);

            // STEP22A:
            // Sau khi AI PIPE tạo overlay DN, build graph lại để graph lấy luôn
            // nguồn TDL_AI_PIPE_DN... có confidence cao.
            BuildMepGraphFromSelection(
                doc,
                psr.Value.GetObjectIds(),
                false);

            if (run == null ||
                run.OutputSegmentCount <= 0)
            {
                MessageBox.Show(
                    "Chưa có tuyến nào đủ bằng chứng để AI chốt.\n\n" +
                    "Cần có ít nhất một TEXT size dạng DN100 / D60 / Ø60 song song với tuyến ống.",
                    "AI BÓC TÁCH MEP");
                return;
            }

            bool placeTable =
                ShowAiPipeTakeoffSummaryDialog(
                    run);

            if (placeTable &&
                run.Stats.Count > 0)
            {
                OutputAiPipeTakeoffTable(
                    doc,
                    run.Stats);
            }

            ed.WriteMessage(
                "\n[AI PIPE] Hoàn tất nhận diện đường ống. " +
                "Muốn nhận diện thiết bị, bấm nút AI NHẬN DIỆN VAN / THIẾT BỊ riêng.");
        }

        private AiPipeTakeoffRunResult AnalyzeAndDrawAiPipeTakeoff(
            Document doc,
            SelectionSet selection)
        {
            AiPipeTakeoffRunResult result =
                new AiPipeTakeoffRunResult();

            if (doc == null ||
                selection == null)
            {
                return result;
            }

            Database db = doc.Database;
            Editor ed = doc.Editor;

            using (doc.LockDocument())
            using (Transaction tr =
                db.TransactionManager.StartTransaction())
            {
                BlockTableRecord space =
                    (BlockTableRecord)tr.GetObject(
                        db.CurrentSpaceId,
                        OpenMode.ForWrite);

                DeleteOldAiPipeOutput(
                    tr,
                    space);

                List<Curve> originalCurves =
                    new List<Curve>();

                List<Entity> intersectEntities =
                    new List<Entity>();

                List<TextData> sizeTexts =
                    new List<TextData>();

                Dictionary<Curve, string> layerHints =
                    new Dictionary<Curve, string>();

                // Block nhỏ dùng làm landmark để nhận ra các nhánh copy giống nhau.
                List<AiPipeContextAnchor> contextAnchors =
                    new List<AiPipeContextAnchor>();

                foreach (SelectedObject so
                    in selection)
                {
                    if (so == null ||
                        so.ObjectId.IsNull)
                    {
                        continue;
                    }

                    Entity ent =
                        tr.GetObject(
                            so.ObjectId,
                            OpenMode.ForRead,
                            false) as Entity;

                    if (ent == null ||
                        ent.IsErased)
                    {
                        continue;
                    }

                    if (IsAiPipeOutputLayer(
                            ent.Layer))
                    {
                        continue;
                    }

                    // STEP18H:
                    // POINT cũng có thể là ký hiệu đầu phun / device marker.
                    if (ent is DBPoint markerPoint)
                    {
                        contextAnchors.Add(
                            new AiPipeContextAnchor
                            {
                                Point =
                                    markerPoint.Position,
                                BlockKey =
                                    GetSmartPointSignature(
                                        markerPoint),
                                MaxSpan =
                                    80.0
                            });

                        continue;
                    }

                    // STEP18F:
                    // Engine VẼ THEO MẪU cũ dùng Circle/Block làm marker.
                    // Các đầu phun trong hình user là CIRCLE, nên nếu bỏ Circle
                    // thì targetMarkers=0 và template không bao giờ match.
                    if (ent is Circle markerCircle)
                    {
                        contextAnchors.Add(
                            new AiPipeContextAnchor
                            {
                                Point =
                                    markerCircle.Center,
                                BlockKey =
                                    "CIRCLE",
                                MaxSpan =
                                    markerCircle.Radius *
                                    2.0
                            });

                        continue;
                    }

                    if (ent is Line ||
                        ent is Polyline ||
                        ent is Polyline2d ||
                        ent is Polyline3d ||
                        ent is Arc)
                    {
                        Curve curve = ent as Curve;

                        if (curve == null ||
                            GetAiPipeCurveLength(curve) <= 5.0)
                        {
                            continue;
                        }

                        bool hasLayerHint =
                            TryParseAiPipeSizeText(
                                ent.Layer,
                                out string hintedSize);

                        AiPipeCurveRejectReason rejectReason;

                        if (!IsAiLikelyPipeCurve(
                                ent,
                                curve,
                                hasLayerHint,
                                out rejectReason))
                        {
                            if (rejectReason ==
                                AiPipeCurveRejectReason.RevisionCloud)
                            {
                                result.RejectedCloudCount++;
                            }
                            else
                            {
                                result.RejectedNonPipeCount++;
                            }

                            continue;
                        }

                        originalCurves.Add(curve);
                        intersectEntities.Add(ent);

                        if (hasLayerHint)
                        {
                            layerHints[curve] =
                                hintedSize;
                        }

                        continue;
                    }

                    if (ent is BlockReference contextBlock)
                    {
                        try
                        {
                            string blockName =
                                GetShopStatBlockName(
                                    tr,
                                    contextBlock);

                            string blockKey =
                                NormalizeSmartSymbolKey(
                                    blockName);

                            Extents3d ex =
                                contextBlock.GeometricExtents;

                            double dx =
                                Math.Abs(
                                    ex.MaxPoint.X -
                                    ex.MinPoint.X);

                            double dy =
                                Math.Abs(
                                    ex.MaxPoint.Y -
                                    ex.MinPoint.Y);

                            double span =
                                Math.Max(
                                    dx,
                                    dy);

                            if (span >= 5.0 &&
                                span <= 2500.0)
                            {
                                List<Point3d> circularCenters =
                                    GetCircularCentersFromBlock(
                                        tr,
                                        contextBlock);

                                if (circularCenters.Count > 0)
                                {
                                    foreach (Point3d circleCenter
                                        in circularCenters)
                                    {
                                        contextAnchors.Add(
                                            new AiPipeContextAnchor
                                            {
                                                Point =
                                                    circleCenter,
                                                BlockKey =
                                                    string.IsNullOrWhiteSpace(
                                                        blockKey)
                                                        ? "BLOCK_CIRCLE"
                                                        : blockKey,
                                                MaxSpan =
                                                    span
                                            });
                                    }
                                }
                                else
                                {
                                    Point3d center =
                                        new Point3d(
                                            (ex.MinPoint.X +
                                             ex.MaxPoint.X) * 0.5,
                                            (ex.MinPoint.Y +
                                             ex.MaxPoint.Y) * 0.5,
                                            0.0);

                                    contextAnchors.Add(
                                        new AiPipeContextAnchor
                                        {
                                            Point =
                                                center,
                                            BlockKey =
                                                blockKey,
                                            MaxSpan =
                                                span
                                        });
                                }
                            }
                        }
                        catch
                        {
                        }

                        continue;
                    }

                    if (ent is DBText txt)
                    {
                        string raw =
                            (txt.TextString ?? "")
                                .Replace("\r", "")
                                .Replace("\n", "")
                                .Trim();

                        if (!TryParseAiPipeSizeText(
                                raw,
                                out string size))
                        {
                            continue;
                        }

                        Point3d pt =
                            (txt.Justify != AttachmentPoint.BaseLeft &&
                             (Math.Abs(txt.AlignmentPoint.X) > 1e-9 ||
                              Math.Abs(txt.AlignmentPoint.Y) > 1e-9))
                                ? txt.AlignmentPoint
                                : txt.Position;

                        sizeTexts.Add(
                            new TextData
                            {
                                Position = pt,
                                Rotation = txt.Rotation,
                                TextString = size,
                                LayerName = GetAiPipeLayerName(size),
                                Width = FixedDnPipeDisplayWidth
                            });

                        continue;
                    }

                    if (ent is MText mtxt)
                    {
                        string raw =
                            (mtxt.Text ?? "")
                                .Replace("\r", "")
                                .Replace("\n", "")
                                .Trim();

                        if (!TryParseAiPipeSizeText(
                                raw,
                                out string size))
                        {
                            continue;
                        }

                        sizeTexts.Add(
                            new TextData
                            {
                                Position = mtxt.Location,
                                Rotation = mtxt.Rotation,
                                TextString = size,
                                LayerName = GetAiPipeLayerName(size),
                                Width = FixedDnPipeDisplayWidth
                            });
                    }
                }

                result.RawCurveCount = originalCurves.Count;
                result.SizeTextCount = sizeTexts.Count;

                if (originalCurves.Count == 0 ||
                    sizeTexts.Count == 0)
                {
                    tr.Commit();
                    return result;
                }

                Dictionary<Curve, List<TextProjectionData>> textMap =
                    MapAiPipeTextsToCurves(
                        originalCurves,
                        sizeTexts,
                        layerHints,
                        out int ambiguousTextCount);

                result.AmbiguousTextCount =
                    ambiguousTextCount;

                List<SegmentData> segments =
                    SplitAiPipeCurves(
                        originalCurves,
                        intersectEntities,
                        textMap);

                HashSet<SegmentData> explicitText =
                    new HashSet<SegmentData>();

                HashSet<SegmentData> explicitLayer =
                    new HashSet<SegmentData>();

                AssignAiPipeTextSeeds(
                    segments,
                    textMap,
                    explicitText);

                AssignAiPipeLayerSeeds(
                    segments,
                    layerHints,
                    explicitText,
                    explicitLayer);

                if (!segments.Any(
                        s =>
                            s != null &&
                            s.HasExplicitSize &&
                            !string.IsNullOrWhiteSpace(s.Layer)))
                {
                    tr.Commit();
                    return result;
                }

                // STEP18F - THỨ TỰ QUAN TRỌNG:
                // 1) Chỉ fill trong CÙNG parent nếu parent có đúng 1 DN.
                //    Đây là suy luận an toàn, không truyền qua giao T.
                int sameParentInherited =
                    PropagateAiPipeSizesWithinSameParentOnly(
                        segments);

                result.InheritedSegmentCount +=
                    sameParentInherited;

                // 2) STEP18H - BRANCH OBJECT ENGINE:
                //    Dùng đúng engine TryMatchTemplateBranch + marker-bound span cũ.
                //    Source pattern lấy trực tiếp từ các DN explicit, không đòi source
                //    đã được fill sẵn 55-82% chiều dài.
                result.BranchObjectInheritedCount =
                    PropagateAiPipePatternByBranchObjectEngine(
                        segments,
                        contextAnchors,
                        out int branchObjectMatches);

                result.BranchObjectMatchedCount =
                    branchObjectMatches;

                result.InheritedSegmentCount +=
                    result.BranchObjectInheritedCount;

                // 3) Engine STEP18E cũ giữ làm fallback cho target còn trống.
                result.AutoTemplateBranchInheritedCount =
                    PropagateAiPipePatternByExistingTemplateEngine(
                        segments,
                        contextAnchors);

                result.InheritedSegmentCount +=
                    result.AutoTemplateBranchInheritedCount;

                // 4) Sau khi copy nhánh mẫu xong mới lan truyền topology cho phần còn lại.
                result.InheritedSegmentCount +=
                    PropagateFirePipeSizesByTopology(
                        segments);

                // STEP18D giữ làm fallback cho các trường hợp đơn giản.
                result.RepeatedBranchInheritedCount =
                    PropagateAiPipeSizesByRepeatedBranchTemplate(
                        segments,
                        contextAnchors);

                result.InheritedSegmentCount +=
                    result.RepeatedBranchInheritedCount;

                List<AiPipeSegmentResult> recognized =
                    BuildAiPipeResults(
                        segments,
                        explicitText,
                        explicitLayer);

                List<SegmentData> checks =
                    FindAiPipeCheckSegments(
                        segments);

                result.CheckSegmentCount = checks.Count;

                EnsureAiPipeLayer(
                    tr,
                    db,
                    AiPipeCheckLayer,
                    30);

                EnsureAiPipeLayer(
                    tr,
                    db,
                    AiPipeInfoLayer,
                    2);

                foreach (AiPipeSegmentResult item
                    in recognized)
                {
                    if (item?.Segment?.Curve == null)
                        continue;

                    string layerName =
                        GetAiPipeLayerName(
                            item.Size);

                    EnsureAiPipeLayer(
                        tr,
                        db,
                        layerName,
                        GetExpectedAciColor(
                            layerName));

                    Entity overlay =
                        CreateAiPipeOverlay(
                            item.Segment.Curve,
                            layerName,
                            FixedDnPipeDisplayWidth);

                    if (overlay == null)
                        continue;

                    space.AppendEntity(overlay);
                    tr.AddNewlyCreatedDBObject(overlay, true);
                    result.OutputSegmentCount++;

                    if ((explicitText != null &&
                         explicitText.Contains(
                             item.Segment)) ||
                        (item.Confidence >= 0.94 &&
                         item.Length >= 12000.0))
                    {
                        DBText label =
                            CreateAiPipeLabel(
                                db,
                                item.Segment.Curve,
                                item.Size,
                                layerName);

                        if (label != null)
                        {
                            space.AppendEntity(label);
                            tr.AddNewlyCreatedDBObject(label, true);

                            try
                            {
                                label.AdjustAlignment(db);
                            }
                            catch
                            {
                            }
                        }
                    }
                }

                foreach (SegmentData segment
                    in checks)
                {
                    if (segment?.Curve == null)
                        continue;

                    Entity check =
                        CreateAiPipeOverlay(
                            segment.Curve,
                            AiPipeCheckLayer,
                            0.0);

                    if (check == null)
                        continue;

                    space.AppendEntity(check);
                    tr.AddNewlyCreatedDBObject(check, true);
                }

                result.ExplicitSegmentCount =
                    recognized.Count(
                        r =>
                            r.Segment != null &&
                            r.Segment.HasExplicitSize);

                result.TotalLengthMeters =
                    recognized.Sum(r => r.Length) /
                    1000.0;

                result.AverageConfidence =
                    recognized.Count > 0
                        ? recognized.Average(r => r.Confidence)
                        : 0.0;

                result.Stats =
                    recognized
                        .GroupBy(
                            r => r.Size,
                            StringComparer.OrdinalIgnoreCase)
                        .Select(
                            g => new AiPipeTakeoffStatRow
                            {
                                Size = g.Key,
                                LengthMeters =
                                    g.Sum(r => r.Length) / 1000.0,
                                SegmentCount = g.Count(),
                                ExplicitCount =
                                    g.Count(
                                        r =>
                                            r.Segment != null &&
                                            r.Segment.HasExplicitSize),
                                InheritedCount =
                                    g.Count(
                                        r =>
                                            r.Segment != null &&
                                            !r.Segment.HasExplicitSize),
                                AverageConfidence =
                                    g.Average(r => r.Confidence)
                            })
                        .OrderByDescending(
                            r => SmartSizeSortValue(r.Size))
                        .ToList();

                tr.Commit();
            }

            try
            {
                ed.Regen();
                ed.WriteMessage(
                    "\n[AI BÓC TÁCH] Đã dựng " +
                    result.OutputSegmentCount +
                    " đoạn; CHECK=" +
                    result.CheckSegmentCount +
                    "; confidence=" +
                    (result.AverageConfidence * 100.0)
                        .ToString("0.0", CultureInfo.InvariantCulture) +
                    "%.");
            }
            catch
            {
            }

            return result;
        }

        private enum AiPipeCurveRejectReason
        {
            None = 0,
            RevisionCloud = 1,
            AnnotationLayer = 2,
            NonPipeGeometry = 3
        }

        private bool IsAiLikelyPipeCurve(
            Entity ent,
            Curve curve,
            bool hasLayerSizeHint,
            out AiPipeCurveRejectReason reason)
        {
            reason =
                AiPipeCurveRejectReason.None;

            if (ent == null ||
                curve == null)
            {
                reason =
                    AiPipeCurveRejectReason.NonPipeGeometry;

                return false;
            }

            string layer =
                (ent.Layer ?? "")
                    .Trim()
                    .ToUpperInvariant();

            // Layer annotation/markup là bằng chứng loại rất mạnh.
            string[] rejectLayerTokens =
                new string[]
                {
                    "REVCLOUD",
                    "REV-CLOUD",
                    "REV_CLOUD",
                    "REVISION",
                    "CLOUD",
                    "MARKUP",
                    "MARK-UP",
                    "HATCH",
                    "WIPEOUT",
                    "DEFPOINTS"
                };

            if (rejectLayerTokens.Any(
                    token =>
                        layer.Contains(token)))
            {
                reason =
                    layer.Contains("CLOUD") ||
                    layer.Contains("REV")
                        ? AiPipeCurveRejectReason.RevisionCloud
                        : AiPipeCurveRejectReason.AnnotationLayer;

                return false;
            }

            if (ent is Polyline pl)
            {
                if (IsAiRevisionCloudPolyline(
                        pl))
                {
                    reason =
                        AiPipeCurveRejectReason.RevisionCloud;

                    return false;
                }

                // Polyline rất phức tạp nhưng không có bất kỳ bằng chứng layer-size:
                // ưu tiên precision, không coi là ống ngay.
                if (!hasLayerSizeHint &&
                    pl.NumberOfVertices >= 80)
                {
                    reason =
                        AiPipeCurveRejectReason.NonPipeGeometry;

                    return false;
                }
            }

            // Arc đơn lẻ dễ là ký hiệu/markup. Nếu nằm trên layer có size thì giữ.
            // Nếu không có layer-size, chỉ giữ cung có hình học hợp lý như co ống.
            if (ent is Arc arc &&
                !hasLayerSizeHint)
            {
                double included =
                    Math.Abs(
                        arc.EndAngle -
                        arc.StartAngle);

                while (included >
                    Math.PI * 2.0)
                {
                    included -=
                        Math.PI * 2.0;
                }

                if (arc.Radius < 15.0 ||
                    arc.Radius > 5000.0 ||
                    included <
                        Math.PI / 36.0)
                {
                    reason =
                        AiPipeCurveRejectReason.NonPipeGeometry;

                    return false;
                }
            }

            return true;
        }

        private bool IsAiRevisionCloudPolyline(
            Polyline pl)
        {
            if (pl == null ||
                pl.NumberOfVertices < 5)
            {
                return false;
            }

            int segmentCount =
                pl.Closed
                    ? pl.NumberOfVertices
                    : pl.NumberOfVertices - 1;

            if (segmentCount <= 0)
                return false;

            int bulgeCount = 0;
            int strongBulgeCount = 0;
            List<double> chordLengths =
                new List<double>();

            for (int i = 0;
                i < segmentCount;
                i++)
            {
                try
                {
                    double bulge =
                        Math.Abs(
                            pl.GetBulgeAt(i));

                    if (bulge > 0.01)
                        bulgeCount++;

                    if (bulge > 0.12)
                        strongBulgeCount++;

                    int next =
                        (i + 1) %
                        pl.NumberOfVertices;

                    Point2d a =
                        pl.GetPoint2dAt(i);

                    Point2d b =
                        pl.GetPoint2dAt(next);

                    chordLengths.Add(
                        a.GetDistanceTo(b));
                }
                catch
                {
                }
            }

            double bulgeRatio =
                segmentCount > 0
                    ? (double)bulgeCount /
                      segmentCount
                    : 0.0;

            double strongRatio =
                segmentCount > 0
                    ? (double)strongBulgeCount /
                      segmentCount
                    : 0.0;

            // AutoCAD REVCLOUD điển hình: polyline gồm rất nhiều cung lặp.
            if (segmentCount >= 6 &&
                strongBulgeCount >= 4 &&
                strongRatio >= 0.45)
            {
                return true;
            }

            if (pl.Closed &&
                segmentCount >= 6 &&
                bulgeCount >= 4 &&
                bulgeRatio >= 0.50)
            {
                return true;
            }

            // Dấu hiệu scallop lặp đều: nhiều segment cong có chord gần bằng nhau.
            if (segmentCount >= 10 &&
                bulgeRatio >= 0.35 &&
                chordLengths.Count >= 6)
            {
                double mean =
                    chordLengths.Average();

                if (mean > 1e-6)
                {
                    double variance =
                        chordLengths.Average(
                            x =>
                                Math.Pow(
                                    x - mean,
                                    2.0));

                    double cv =
                        Math.Sqrt(variance) /
                        mean;

                    if (cv <= 0.45)
                        return true;
                }
            }

            return false;
        }

        private Dictionary<Curve, List<TextProjectionData>>
            MapAiPipeTextsToCurves(
                List<Curve> originalCurves,
                List<TextData> texts,
                Dictionary<Curve, string> layerHints,
                out int ambiguousTextCount)
        {
            ambiguousTextCount = 0;

            Dictionary<Curve, List<TextProjectionData>> result =
                new Dictionary<Curve, List<TextProjectionData>>();

            foreach (Curve curve
                in originalCurves ??
                new List<Curve>())
            {
                result[curve] =
                    new List<TextProjectionData>();
            }

            foreach (TextData text
                in texts ??
                new List<TextData>())
            {
                List<Tuple<Curve, Point3d, double>> candidates =
                    new List<Tuple<Curve, Point3d, double>>();

                foreach (Curve curve
                    in originalCurves ??
                    new List<Curve>())
                {
                    if (curve == null)
                        continue;

                    if (!TryGetClosestPointInPlan(
                            curve,
                            text.Position,
                            out Point3d closest,
                            out double distance))
                    {
                        continue;
                    }

                    if (distance > 2600.0)
                        continue;

                    if (!IsTextParallelToCurve(
                            curve,
                            closest,
                            text.Rotation))
                    {
                        continue;
                    }

                    double anglePenalty =
                        TinhGocLech(
                            curve,
                            closest,
                            text.Rotation) *
                        5500.0;

                    double score =
                        distance +
                        anglePenalty;

                    // Layer có đúng size là bằng chứng cộng thêm.
                    if (layerHints != null &&
                        layerHints.TryGetValue(
                            curve,
                            out string hintedSize))
                    {
                        string normalizedText =
                            NormalizeAiPipeSize(
                                text.TextString);

                        if (string.Equals(
                                NormalizeAiPipeSize(
                                    hintedSize),
                                normalizedText,
                                StringComparison.OrdinalIgnoreCase))
                        {
                            score -= 350.0;
                        }
                        else
                        {
                            score += 900.0;
                        }
                    }

                    score +=
                        GetAiPipeLayerSemanticPenalty(
                            curve.Layer);

                    candidates.Add(
                        Tuple.Create(
                            curve,
                            closest,
                            score));
                }

                List<Tuple<Curve, Point3d, double>> ordered =
                    candidates
                        .OrderBy(
                            item =>
                                item.Item3)
                        .ToList();

                if (ordered.Count == 0)
                    continue;

                Tuple<Curve, Point3d, double> best =
                    ordered[0];

                if (best.Item3 >
                    AiPipeExplicitTextMaxScore)
                {
                    continue;
                }

                if (ordered.Count >= 2)
                {
                    double secondScore =
                        ordered[1].Item3;

                    double margin =
                        secondScore -
                        best.Item3;

                    // Hai tuyến song song/gần nhau mà chữ không đủ phân biệt:
                    // bỏ qua thay vì gán đại.
                    if (margin < 160.0 &&
                        secondScore < 1500.0)
                    {
                        ambiguousTextCount++;
                        continue;
                    }
                }

                try
                {
                    double along =
                        best.Item1.GetDistAtPoint(
                            best.Item2);

                    result[best.Item1].Add(
                        new TextProjectionData
                        {
                            Text = text,
                            DistanceAlongCurve = along,
                            MatchScore = best.Item3
                        });
                }
                catch
                {
                }
            }

            foreach (Curve curve
                in result.Keys.ToList())
            {
                result[curve] =
                    result[curve]
                        .OrderBy(
                            x =>
                                x.DistanceAlongCurve)
                        .ThenBy(
                            x =>
                                x.MatchScore)
                        .ToList();
            }

            return result;
        }

        private double GetAiPipeLayerSemanticPenalty(
            string layerName)
        {
            string layer =
                (layerName ?? "")
                    .ToUpperInvariant();

            if (string.IsNullOrWhiteSpace(layer))
                return 0.0;

            string[] positive =
                new string[]
                {
                    "PIPE",
                    "PCCC",
                    "FIRE",
                    "SPR",
                    "WATER",
                    "FF",
                    "CTN",
                    "PPR",
                    "PVC",
                    "HDPE",
                    "ONG",
                    "ỐNG"
                };

            if (positive.Any(
                    token =>
                        layer.Contains(token)))
            {
                return -120.0;
            }

            string[] negative =
                new string[]
                {
                    "WALL",
                    "GRID",
                    "DIM",
                    "TEXT",
                    "DOOR",
                    "WINDOW",
                    "HATCH",
                    "REV",
                    "CLOUD",
                    "MARKUP",
                    "ARCH",
                    "A-"
                };

            if (negative.Any(
                    token =>
                        layer.Contains(token)))
            {
                return 900.0;
            }

            return 0.0;
        }

        private List<SegmentData> SplitAiPipeCurves(
            List<Curve> curves,
            List<Entity> intersectEntities,
            Dictionary<Curve, List<TextProjectionData>> textMap)
        {
            List<SegmentData> result =
                new List<SegmentData>();

            if (curves == null)
                return result;

            Plane xyPlane =
                new Plane(
                    Point3d.Origin,
                    Vector3d.ZAxis);

            foreach (Curve mainCurve
                in curves)
            {
                if (mainCurve == null)
                    continue;

                Point3dCollection splitPoints =
                    new Point3dCollection();

                foreach (Entity other
                    in intersectEntities ?? new List<Entity>())
                {
                    if (ReferenceEquals(mainCurve, other))
                        continue;

                    try
                    {
                        Point3dCollection pts =
                            new Point3dCollection();

                        mainCurve.IntersectWith(
                            other,
                            Intersect.OnBothOperands,
                            xyPlane,
                            pts,
                            IntPtr.Zero,
                            IntPtr.Zero);

                        foreach (Point3d p in pts)
                        {
                            splitPoints.Add(
                                mainCurve.GetClosestPointTo(
                                    p,
                                    false));
                        }
                    }
                    catch
                    {
                    }

                    try
                    {
                        if (other is Curve otherCurve)
                        {
                            Point3d[] endpoints =
                                new Point3d[]
                                {
                                    otherCurve.StartPoint,
                                    otherCurve.EndPoint
                                };

                            foreach (Point3d p in endpoints)
                            {
                                Point3d flat =
                                    new Point3d(
                                        p.X,
                                        p.Y,
                                        mainCurve.StartPoint.Z);

                                Point3d closest =
                                    mainCurve.GetClosestPointTo(
                                        flat,
                                        false);

                                if (PlanDistance(
                                        closest,
                                        flat) <= 80.0)
                                {
                                    splitPoints.Add(closest);
                                }
                            }
                        }
                    }
                    catch
                    {
                    }
                }

                if (mainCurve is Polyline pl)
                {
                    for (int i = 0;
                        i < pl.NumberOfVertices;
                        i++)
                    {
                        splitPoints.Add(
                            pl.GetPoint3dAt(i));
                    }
                }

                double total =
                    GetAiPipeCurveLength(
                        mainCurve);

                if (total <= 1.0)
                    continue;

                List<double> distances =
                    new List<double>();

                foreach (Point3d p
                    in splitPoints)
                {
                    try
                    {
                        Point3d closest =
                            mainCurve.GetClosestPointTo(
                                p,
                                false);

                        double d =
                            mainCurve.GetDistAtPoint(
                                closest);

                        if (d > 1.0 &&
                            d < total - 1.0 &&
                            !distances.Any(
                                x => Math.Abs(x - d) < 1.0))
                        {
                            distances.Add(d);
                        }
                    }
                    catch
                    {
                    }
                }

                List<double> transitionDistances =
                    GetTextSizeTransitionDistances(
                        mainCurve,
                        textMap,
                        distances);

                foreach (double d
                    in transitionDistances)
                {
                    if (d > 1.0 &&
                        d < total - 1.0 &&
                        !distances.Any(
                            x => Math.Abs(x - d) < 1.0))
                    {
                        distances.Add(d);
                    }
                }

                distances.Sort();

                Point3dCollection finalPts =
                    new Point3dCollection();

                foreach (double d
                    in distances)
                {
                    try
                    {
                        finalPts.Add(
                            mainCurve.GetPointAtDist(d));
                    }
                    catch
                    {
                    }
                }

                if (finalPts.Count > 0)
                {
                    try
                    {
                        DBObjectCollection splits =
                            mainCurve.GetSplitCurves(finalPts);

                        foreach (DBObject obj
                            in splits)
                        {
                            if (obj is Curve c)
                            {
                                result.Add(
                                    new SegmentData
                                    {
                                        Curve = c,
                                        OriginalParent = mainCurve
                                    });
                            }
                            else
                            {
                                obj.Dispose();
                            }
                        }

                        continue;
                    }
                    catch
                    {
                    }
                }

                Curve clone =
                    mainCurve.Clone() as Curve;

                if (clone != null)
                {
                    result.Add(
                        new SegmentData
                        {
                            Curve = clone,
                            OriginalParent = mainCurve
                        });
                }
            }

            return result;
        }

        private void AssignAiPipeTextSeeds(
            List<SegmentData> segments,
            Dictionary<Curve, List<TextProjectionData>> textMap,
            HashSet<SegmentData> explicitText)
        {
            if (segments == null ||
                textMap == null)
            {
                return;
            }

            foreach (KeyValuePair<Curve, List<TextProjectionData>> pair
                in textMap)
            {
                foreach (TextProjectionData projection
                    in pair.Value ?? new List<TextProjectionData>())
                {
                    if (projection?.Text == null ||
                        projection.MatchScore > AiPipeExplicitTextMaxScore)
                    {
                        continue;
                    }

                    SegmentData best = null;
                    double bestScore = double.MaxValue;

                    foreach (SegmentData segment
                        in segments.Where(
                            s =>
                                ReferenceEquals(
                                    s.OriginalParent,
                                    pair.Key)))
                    {
                        if (segment?.Curve == null)
                            continue;

                        if (!TryGetClosestPointInPlan(
                                segment.Curve,
                                projection.Text.Position,
                                out Point3d closest,
                                out double distance))
                        {
                            continue;
                        }

                        if (!IsTextParallelToCurve(
                                segment.Curve,
                                closest,
                                projection.Text.Rotation))
                        {
                            continue;
                        }

                        double score =
                            distance +
                            TinhGocLech(
                                segment.Curve,
                                closest,
                                projection.Text.Rotation) *
                            5000.0;

                        if (score < bestScore)
                        {
                            best = segment;
                            bestScore = score;
                        }
                    }

                    if (best == null ||
                        bestScore > AiPipeExplicitTextMaxScore ||
                        bestScore >= best.BestScore)
                    {
                        continue;
                    }

                    string size =
                        NormalizeAiPipeSize(
                            projection.Text.TextString);

                    best.Layer =
                        GetAiPipeLayerName(size);

                    best.LabelText = size;
                    best.Width = FixedDnPipeDisplayWidth;
                    best.BestScore = bestScore;
                    best.HasExplicitSize = true;

                    explicitText?.Add(best);
                }
            }
        }

        private void AssignAiPipeLayerSeeds(
            List<SegmentData> segments,
            Dictionary<Curve, string> hints,
            HashSet<SegmentData> explicitText,
            HashSet<SegmentData> explicitLayer)
        {
            if (segments == null ||
                hints == null)
            {
                return;
            }

            foreach (SegmentData segment
                in segments)
            {
                if (segment?.OriginalParent == null ||
                    !hints.TryGetValue(
                        segment.OriginalParent,
                        out string hintedSize))
                {
                    continue;
                }

                if (explicitText != null &&
                    explicitText.Contains(segment))
                {
                    continue;
                }

                if (!string.IsNullOrWhiteSpace(segment.Layer))
                    continue;

                segment.Layer =
                    GetAiPipeLayerName(hintedSize);

                segment.LabelText = hintedSize;
                segment.Width = FixedDnPipeDisplayWidth;
                segment.HasExplicitSize = true;
                segment.BestScore = 250.0;

                explicitLayer?.Add(segment);
            }
        }

        private class AiBranchSizeZone
        {
            public double StartFraction { get; set; }
            public double EndFraction { get; set; }
            public string Layer { get; set; } = "";
            public string LabelText { get; set; } = "";
        }

        private class AiBranchObjectCandidate
        {
            public Curve SourceParent { get; set; }
            public Curve TargetParent { get; set; }
            public Curve SourceMatchCurve { get; set; }
            public Curve TargetMatchCurve { get; set; }
            public Matrix3d Transform { get; set; } =
                Matrix3d.Identity;
            public double Score { get; set; } =
                double.MaxValue;
            public int MarkerCount { get; set; }
            public bool Reversed { get; set; }
            public string PatternSignature { get; set; } = "";
            public List<AiBranchSizeZone> Zones { get; set; } =
                new List<AiBranchSizeZone>();
        }

        private class AiAutoTemplateBranchCandidate
        {
            public Curve SourceParent { get; set; }
            public Curve TargetParent { get; set; }
            public Matrix3d Transform { get; set; } =
                Matrix3d.Identity;
            public double Score { get; set; } =
                double.MaxValue;
            public int SourceMarkerCount { get; set; }
            public int TargetMarkerCount { get; set; }
            public string PatternSignature { get; set; } = "";
        }

        private int PropagateAiPipePatternByBranchObjectEngine(
            List<SegmentData> segments,
            List<AiPipeContextAnchor> anchors,
            out int matchedBranchCount)
        {
            matchedBranchCount =
                0;

            if (segments == null ||
                segments.Count == 0 ||
                anchors == null ||
                anchors.Count == 0)
            {
                return 0;
            }

            Dictionary<Curve, List<SegmentData>> byParent =
                segments
                    .Where(
                        s =>
                            s?.OriginalParent != null)
                    .GroupBy(
                        s =>
                            s.OriginalParent)
                    .ToDictionary(
                        g =>
                            g.Key,
                        g =>
                            g.ToList());

            if (byParent.Count < 2)
                return 0;

            List<Curve> allParents =
                byParent.Keys
                    .Where(
                        c =>
                            c != null)
                    .ToList();

            List<Curve> sourceParents =
                allParents
                    .Where(
                        p =>
                            byParent[p].Any(
                                s =>
                                    s != null &&
                                    s.HasExplicitSize &&
                                    !string.IsNullOrWhiteSpace(
                                        s.Layer)))
                    .ToList();

            List<Curve> targetParents =
                allParents
                    .Where(
                        p =>
                            byParent[p].All(
                                s =>
                                    s != null &&
                                    !s.HasExplicitSize))
                    .ToList();

            if (sourceParents.Count == 0 ||
                targetParents.Count == 0)
            {
                return 0;
            }

            int inheritedCount =
                0;

            foreach (Curve targetParent
                in targetParents.ToList())
            {
                List<Point3d> targetMarkers =
                    GetAiBranchObjectMarkersNearCurve(
                        targetParent,
                        anchors);

                if (targetMarkers.Count < 2)
                    continue;

                Curve targetBound =
                    BuildTemplateMarkerBoundReferenceCurve(
                        targetParent,
                        targetMarkers);

                if (targetBound == null)
                    continue;

                List<AiBranchObjectCandidate> matches =
                    new List<AiBranchObjectCandidate>();

                try
                {
                    foreach (Curve sourceParent
                        in sourceParents)
                    {
                        if (sourceParent == null ||
                            ReferenceEquals(
                                sourceParent,
                                targetParent))
                        {
                            continue;
                        }

                        List<Point3d> sourceMarkers =
                            GetAiBranchObjectMarkersNearCurve(
                                sourceParent,
                                anchors);

                        if (sourceMarkers.Count < 2)
                            continue;

                        // Marker count là feature cực mạnh cho nhánh sprinkler lặp.
                        int markerDifference =
                            Math.Abs(
                                sourceMarkers.Count -
                                targetMarkers.Count);

                        if (markerDifference >
                            Math.Max(
                                1,
                                (int)Math.Ceiling(
                                    sourceMarkers.Count *
                                    0.20)))
                        {
                            continue;
                        }

                        Curve sourceBound =
                            BuildTemplateMarkerBoundReferenceCurve(
                                sourceParent,
                                sourceMarkers);

                        if (sourceBound == null)
                            continue;

                        List<AiBranchSizeZone> zones =
                            BuildAiBranchSizeZonesFromExplicitSeeds(
                                sourceParent,
                                sourceBound,
                                byParent[sourceParent]);

                        if (zones.Count == 0)
                        {
                            sourceBound.Dispose();
                            continue;
                        }

                        List<Point3d> sourceMarkersBound =
                            GetAiBranchObjectMarkersNearCurve(
                                sourceBound,
                                anchors);

                        List<Point3d> targetMarkersBound =
                            GetAiBranchObjectMarkersNearCurve(
                                targetBound,
                                anchors);

                        bool matched =
                            TryMatchTemplateBranch(
                                sourceBound,
                                targetBound,
                                -1,
                                -1,
                                sourceMarkersBound,
                                targetMarkersBound,
                                out Matrix3d transform,
                                out double score);

                        if (!matched)
                        {
                            sourceBound.Dispose();
                            continue;
                        }

                        Point3d mappedSourceStart =
                            sourceBound.StartPoint
                                .TransformBy(
                                    transform);

                        bool reversed =
                            GetTemplatePlanDistance(
                                mappedSourceStart,
                                targetBound.EndPoint) <
                            GetTemplatePlanDistance(
                                mappedSourceStart,
                                targetBound.StartPoint);

                        string signature =
                            BuildAiBranchZoneSignature(
                                zones);

                        matches.Add(
                            new AiBranchObjectCandidate
                            {
                                SourceParent =
                                    sourceParent,
                                TargetParent =
                                    targetParent,
                                SourceMatchCurve =
                                    sourceBound,
                                TargetMatchCurve =
                                    targetBound.Clone()
                                        as Curve,
                                Transform =
                                    transform,
                                Score =
                                    score,
                                MarkerCount =
                                    Math.Min(
                                        sourceMarkersBound.Count,
                                        targetMarkersBound.Count),
                                Reversed =
                                    reversed,
                                PatternSignature =
                                    signature,
                                Zones =
                                    zones
                            });
                    }

                    if (matches.Count == 0)
                        continue;

                    List<AiBranchObjectCandidate> ranked =
                        matches
                            .OrderBy(
                                m =>
                                    m.Score)
                            .ThenByDescending(
                                m =>
                                    m.MarkerCount)
                            .ToList();

                    AiBranchObjectCandidate best =
                        ranked[0];

                    // Hai mẫu hình học giống nhau nhưng schedule DN khác nhau:
                    // không đoán nếu điểm số gần nhau.
                    if (ranked.Count > 1)
                    {
                        AiBranchObjectCandidate second =
                            ranked[1];

                        double scoreTolerance =
                            Math.Max(
                                30.0,
                                GetTemplateCurveLength(
                                    best.SourceMatchCurve) *
                                0.008);

                        if (!string.Equals(
                                best.PatternSignature,
                                second.PatternSignature,
                                StringComparison.OrdinalIgnoreCase) &&
                            Math.Abs(
                                second.Score -
                                best.Score) <=
                            scoreTolerance)
                        {
                            continue;
                        }
                    }

                    int added =
                        ApplyAiBranchZonesToTargetParent(
                            segments,
                            targetParent,
                            best.TargetMatchCurve,
                            best.Zones,
                            best.Reversed,
                            best.Score,
                            best.MarkerCount);

                    if (added > 0)
                    {
                        inheritedCount +=
                            added;

                        matchedBranchCount++;
                    }
                }
                finally
                {
                    targetBound.Dispose();

                    foreach (AiBranchObjectCandidate candidate
                        in matches)
                    {
                        try
                        {
                            candidate.SourceMatchCurve?.Dispose();
                        }
                        catch
                        {
                        }

                        try
                        {
                            candidate.TargetMatchCurve?.Dispose();
                        }
                        catch
                        {
                        }
                    }
                }
            }

            return inheritedCount;
        }

        private List<Point3d> GetAiBranchObjectMarkersNearCurve(
            Curve curve,
            List<AiPipeContextAnchor> anchors)
        {
            List<Point3d> result =
                new List<Point3d>();

            if (curve == null ||
                anchors == null)
            {
                return result;
            }

            double curveLength =
                GetAiPipeCurveLength(
                    curve);

            // Tighter than STEP18D: branch markers normally sit ON the pipe centerline.
            double baseTolerance =
                Math.Max(
                    70.0,
                    Math.Min(
                        220.0,
                        curveLength *
                        0.018));

            foreach (AiPipeContextAnchor anchor
                in anchors)
            {
                if (anchor == null)
                    continue;

                double tolerance =
                    Math.Max(
                        baseTolerance,
                        Math.Min(
                            260.0,
                            anchor.MaxSpan *
                            0.45 +
                            50.0));

                if (!TryGetClosestPointInPlan(
                        curve,
                        anchor.Point,
                        out Point3d closest,
                        out double distance))
                {
                    continue;
                }

                if (distance >
                    tolerance)
                {
                    continue;
                }

                AddUniquePoint(
                    result,
                    anchor.Point,
                    5.0);
            }

            // Stable order along curve.
            return
                result
                    .OrderBy(
                        p =>
                            GetAiStationOnParent(
                                curve,
                                p))
                    .ToList();
        }

        private List<AiBranchSizeZone> BuildAiBranchSizeZonesFromExplicitSeeds(
            Curve sourceParent,
            Curve sourceBound,
            List<SegmentData> sourceSegments)
        {
            List<AiBranchSizeZone> zones =
                new List<AiBranchSizeZone>();

            if (sourceParent == null ||
                sourceBound == null ||
                sourceSegments == null)
            {
                return zones;
            }

            double low =
                Math.Min(
                    GetAiStationOnParent(
                        sourceParent,
                        sourceBound.StartPoint),
                    GetAiStationOnParent(
                        sourceParent,
                        sourceBound.EndPoint));

            double high =
                Math.Max(
                    GetAiStationOnParent(
                        sourceParent,
                        sourceBound.StartPoint),
                    GetAiStationOnParent(
                        sourceParent,
                        sourceBound.EndPoint));

            double span =
                high -
                low;

            if (span <= 50.0)
                return zones;

            var seeds =
                sourceSegments
                    .Where(
                        s =>
                            s?.Curve != null &&
                            s.HasExplicitSize &&
                            !string.IsNullOrWhiteSpace(
                                s.Layer))
                    .Select(
                        s =>
                        {
                            double station =
                                GetAiStationOnParent(
                                    sourceParent,
                                    GetAiCurveMidPoint(
                                        s.Curve));

                            string layer =
                                s.Layer;

                            string label =
                                !string.IsNullOrWhiteSpace(
                                    s.LabelText)
                                    ? s.LabelText
                                    : ExtractAiPipeSizeFromLayer(
                                        layer);

                            return
                                new
                                {
                                    Segment =
                                        s,
                                    Station =
                                        station,
                                    Fraction =
                                        (station -
                                         low) /
                                        span,
                                    Layer =
                                        layer,
                                    Label =
                                        label
                                };
                        })
                    .Where(
                        x =>
                            x.Fraction >=
                                -0.05 &&
                            x.Fraction <=
                                1.05)
                    .OrderBy(
                        x =>
                            x.Fraction)
                    .ToList();

            if (seeds.Count == 0)
                return zones;

            // Clamp and merge seeds that are practically at the same station.
            var compact =
                new List<Tuple<double, string, string>>();

            foreach (var seed
                in seeds)
            {
                double f =
                    Math.Max(
                        0.0,
                        Math.Min(
                            1.0,
                            seed.Fraction));

                if (compact.Count > 0 &&
                    Math.Abs(
                        compact[
                            compact.Count - 1]
                            .Item1 -
                        f) <
                    0.015)
                {
                    compact[
                        compact.Count - 1] =
                        Tuple.Create(
                            f,
                            seed.Layer,
                            seed.Label);

                    continue;
                }

                compact.Add(
                    Tuple.Create(
                        f,
                        seed.Layer,
                        seed.Label));
            }

            if (compact.Count == 0)
                return zones;

            List<double> boundaries =
                new List<double>
                {
                    0.0
                };

            for (int i = 0;
                i < compact.Count - 1;
                i++)
            {
                boundaries.Add(
                    (compact[i].Item1 +
                     compact[i + 1].Item1) *
                    0.5);
            }

            boundaries.Add(
                1.0);

            for (int i = 0;
                i < compact.Count;
                i++)
            {
                AiBranchSizeZone zone =
                    new AiBranchSizeZone
                    {
                        StartFraction =
                            boundaries[i],
                        EndFraction =
                            boundaries[i + 1],
                        Layer =
                            compact[i].Item2,
                        LabelText =
                            compact[i].Item3
                    };

                // Merge adjacent equal DN.
                if (zones.Count > 0 &&
                    string.Equals(
                        zones[
                            zones.Count - 1]
                            .Layer,
                        zone.Layer,
                        StringComparison.OrdinalIgnoreCase))
                {
                    zones[
                        zones.Count - 1]
                        .EndFraction =
                        zone.EndFraction;
                }
                else
                {
                    zones.Add(
                        zone);
                }
            }

            return zones;
        }

        private string BuildAiBranchZoneSignature(
            List<AiBranchSizeZone> zones)
        {
            if (zones == null ||
                zones.Count == 0)
            {
                return "";
            }

            return
                string.Join(
                    "|",
                    zones.Select(
                        z =>
                            ExtractAiPipeSizeFromLayer(
                                z.Layer) +
                            ":" +
                            z.StartFraction.ToString(
                                "0.00",
                                CultureInfo.InvariantCulture) +
                            "-" +
                            z.EndFraction.ToString(
                                "0.00",
                                CultureInfo.InvariantCulture)));
        }

        private int ApplyAiBranchZonesToTargetParent(
            List<SegmentData> allSegments,
            Curve targetParent,
            Curve targetBound,
            List<AiBranchSizeZone> sourceZones,
            bool reversed,
            double matchScore,
            int markerCount)
        {
            if (allSegments == null ||
                targetParent == null ||
                targetBound == null ||
                sourceZones == null ||
                sourceZones.Count == 0)
            {
                return 0;
            }

            double parentLength =
                GetAiPipeCurveLength(
                    targetParent);

            if (parentLength <= 50.0)
                return 0;

            double low =
                Math.Min(
                    GetAiStationOnParent(
                        targetParent,
                        targetBound.StartPoint),
                    GetAiStationOnParent(
                        targetParent,
                        targetBound.EndPoint));

            double high =
                Math.Max(
                    GetAiStationOnParent(
                        targetParent,
                        targetBound.StartPoint),
                    GetAiStationOnParent(
                        targetParent,
                        targetBound.EndPoint));

            double span =
                high -
                low;

            if (span <= 50.0)
                return 0;

            List<double> splitDistances =
                new List<double>();

            // Preserve all old split boundaries (T/intersections etc.).
            foreach (SegmentData oldSegment
                in allSegments.Where(
                    s =>
                        s?.Curve != null &&
                        ReferenceEquals(
                            s.OriginalParent,
                            targetParent)))
            {
                Point3d[] points =
                    new Point3d[]
                    {
                        oldSegment.Curve.StartPoint,
                        oldSegment.Curve.EndPoint
                    };

                foreach (Point3d p
                    in points)
                {
                    double d =
                        GetAiStationOnParent(
                            targetParent,
                            p);

                    AddAiSplitDistance(
                        splitDistances,
                        d,
                        parentLength);
                }
            }

            AddAiSplitDistance(
                splitDistances,
                low,
                parentLength);

            AddAiSplitDistance(
                splitDistances,
                high,
                parentLength);

            foreach (AiBranchSizeZone zone
                in sourceZones)
            {
                double[] sourceFractions =
                    new double[]
                    {
                        zone.StartFraction,
                        zone.EndFraction
                    };

                foreach (double sourceFraction
                    in sourceFractions)
                {
                    double targetFraction =
                        reversed
                            ? 1.0 -
                              sourceFraction
                            : sourceFraction;

                    double d =
                        low +
                        span *
                        targetFraction;

                    AddAiSplitDistance(
                        splitDistances,
                        d,
                        parentLength);
                }
            }

            splitDistances =
                splitDistances
                    .Where(
                        d =>
                            d > 1.0 &&
                            d <
                                parentLength - 1.0)
                    .Distinct()
                    .OrderBy(
                        d =>
                            d)
                    .ToList();

            Point3dCollection pointsToSplit =
                new Point3dCollection();

            foreach (double d
                in splitDistances)
            {
                try
                {
                    pointsToSplit.Add(
                        targetParent.GetPointAtDist(
                            d));
                }
                catch
                {
                }
            }

            List<Curve> pieces =
                new List<Curve>();

            if (pointsToSplit.Count > 0)
            {
                try
                {
                    DBObjectCollection splitObjects =
                        targetParent.GetSplitCurves(
                            pointsToSplit);

                    foreach (DBObject obj
                        in splitObjects)
                    {
                        if (obj is Curve c)
                        {
                            pieces.Add(
                                c);
                        }
                        else
                        {
                            obj.Dispose();
                        }
                    }
                }
                catch
                {
                }
            }

            if (pieces.Count == 0)
            {
                Curve clone =
                    targetParent.Clone()
                        as Curve;

                if (clone != null)
                {
                    pieces.Add(
                        clone);
                }
            }

            if (pieces.Count == 0)
                return 0;

            List<SegmentData> replacements =
                new List<SegmentData>();

            int assigned =
                0;

            foreach (Curve piece
                in pieces)
            {
                Point3d mid =
                    GetAiCurveMidPoint(
                        piece);

                double station =
                    GetAiStationOnParent(
                        targetParent,
                        mid);

                SegmentData replacement =
                    new SegmentData
                    {
                        Curve =
                            piece,
                        OriginalParent =
                            targetParent,
                        Width =
                            FixedDnPipeDisplayWidth
                    };

                if (station >=
                        low - 1.0 &&
                    station <=
                        high + 1.0)
                {
                    double targetFraction =
                        (station -
                         low) /
                        span;

                    targetFraction =
                        Math.Max(
                            0.0,
                            Math.Min(
                                1.0,
                                targetFraction));

                    double sourceFraction =
                        reversed
                            ? 1.0 -
                              targetFraction
                            : targetFraction;

                    AiBranchSizeZone zone =
                        sourceZones
                            .FirstOrDefault(
                                z =>
                                    sourceFraction >=
                                        z.StartFraction -
                                        1e-6 &&
                                    sourceFraction <=
                                        z.EndFraction +
                                        1e-6);

                    if (zone == null)
                    {
                        zone =
                            sourceZones
                                .OrderBy(
                                    z =>
                                        Math.Abs(
                                            sourceFraction -
                                            (z.StartFraction +
                                             z.EndFraction) *
                                            0.5))
                                .FirstOrDefault();
                    }

                    if (zone != null)
                    {
                        replacement.Layer =
                            zone.Layer;

                        replacement.LabelText =
                            zone.LabelText;

                        replacement.HasExplicitSize =
                            false;

                        replacement.AiInferenceSource =
                            "BRANCH_OBJECT_TEMPLATE";

                        double confidence =
                            markerCount >= 4
                                ? 0.985
                                : markerCount == 3
                                    ? 0.975
                                    : 0.955;

                        // A very large matching error lowers confidence slightly,
                        // but does not destroy a 4-marker exact repeated branch.
                        double penalty =
                            Math.Min(
                                0.025,
                                matchScore /
                                Math.Max(
                                    5000.0,
                                    span) *
                                0.015);

                        replacement.AiInferenceConfidence =
                            Math.Max(
                                0.92,
                                confidence -
                                penalty);

                        assigned++;
                    }
                }

                replacements.Add(
                    replacement);
            }

            if (assigned <= 0)
            {
                foreach (Curve piece
                    in pieces)
                {
                    try
                    {
                        piece.Dispose();
                    }
                    catch
                    {
                    }
                }

                return 0;
            }

            List<SegmentData> old =
                allSegments
                    .Where(
                        s =>
                            s != null &&
                            ReferenceEquals(
                                s.OriginalParent,
                                targetParent))
                    .ToList();

            foreach (SegmentData oldSegment
                in old)
            {
                allSegments.Remove(
                    oldSegment);

                try
                {
                    oldSegment.Curve?.Dispose();
                }
                catch
                {
                }
            }

            allSegments.AddRange(
                replacements);

            return assigned;
        }

        private void AddAiSplitDistance(
            List<double> distances,
            double value,
            double maxLength)
        {
            if (distances == null ||
                double.IsNaN(
                    value) ||
                double.IsInfinity(
                    value))
            {
                return;
            }

            value =
                Math.Max(
                    0.0,
                    Math.Min(
                        maxLength,
                        value));

            if (!distances.Any(
                    d =>
                        Math.Abs(
                            d -
                            value) <
                        1.0))
            {
                distances.Add(
                    value);
            }
        }

        private int PropagateAiPipePatternByExistingTemplateEngine(
            List<SegmentData> segments,
            List<AiPipeContextAnchor> anchors)
        {
            if (segments == null ||
                segments.Count == 0)
            {
                return 0;
            }

            // Parent curve là LINE/POLYLINE gốc trước khi Split theo text DN.
            List<Curve> parentCurves =
                segments
                    .Where(
                        s =>
                            s?.OriginalParent != null)
                    .Select(
                        s =>
                            s.OriginalParent)
                    .Distinct()
                    .ToList();

            if (parentCurves.Count < 2)
                return 0;

            Dictionary<Curve, List<SegmentData>> segmentsByParent =
                segments
                    .Where(
                        s =>
                            s?.OriginalParent != null)
                    .GroupBy(
                        s =>
                            s.OriginalParent)
                    .ToDictionary(
                        g =>
                            g.Key,
                        g =>
                            g.ToList());

            // SOURCE:
            // phải có DN nhận diện phủ gần hết tuyến.
            List<Curve> sourceParents =
                parentCurves
                    .Where(
                        parent =>
                            IsAiTemplateSourceParent(
                                parent,
                                segmentsByParent[parent]))
                    .ToList();

            // TARGET:
            // toàn tuyến chưa có DN. Đây chính là nhánh dưới trong hình user.
            List<Curve> targetParents =
                parentCurves
                    .Where(
                        parent =>
                            IsAiTemplateUnknownTargetParent(
                                segmentsByParent[parent]))
                    .ToList();

            if (sourceParents.Count == 0 ||
                targetParents.Count == 0)
            {
                return 0;
            }

            List<Point3d> allAnchorPoints =
                (anchors ??
                 new List<AiPipeContextAnchor>())
                    .Where(
                        a =>
                            a != null)
                    .Select(
                        a =>
                            a.Point)
                    .ToList();

            int inheritedCount =
                0;

            foreach (Curve targetParent
                in targetParents.ToList())
            {
                if (targetParent == null)
                    continue;

                List<Point3d> targetMarkers =
                    GetAiTemplateMarkersNearCurveStrict(
                        targetParent,
                        anchors);

                // Với nhánh chỉ là một line thẳng, marker chính là bằng chứng
                // phân biệt "nhánh sprinkler copy" với line kiến trúc.
                if (targetMarkers.Count < 2)
                    continue;

                int targetRootIndex =
                    FindTemplateBranchRootIndex(
                        targetParent,
                        parentCurves);

                List<AiAutoTemplateBranchCandidate> matches =
                    new List<AiAutoTemplateBranchCandidate>();

                foreach (Curve sourceParent
                    in sourceParents)
                {
                    if (sourceParent == null ||
                        ReferenceEquals(
                            sourceParent,
                            targetParent))
                    {
                        continue;
                    }

                    if (sourceParent.ObjectId != ObjectId.Null &&
                        targetParent.ObjectId != ObjectId.Null &&
                        sourceParent.ObjectId ==
                            targetParent.ObjectId)
                    {
                        continue;
                    }

                    List<Point3d> sourceMarkers =
                        GetAiTemplateMarkersNearCurveStrict(
                            sourceParent,
                            anchors);

                    if (sourceMarkers.Count < 2)
                        continue;

                    // Marker count phải gần giống. Ví dụ 4 đầu phun ↔ 4 đầu phun.
                    if (Math.Abs(
                            sourceMarkers.Count -
                            targetMarkers.Count) >
                        Math.Max(
                            1,
                            (int)Math.Ceiling(
                                sourceMarkers.Count *
                                0.25)))
                    {
                        continue;
                    }

                    int sourceRootIndex =
                        FindTemplateBranchRootIndex(
                            sourceParent,
                            parentCurves);

                    bool matched =
                        TryMatchTemplateBranch(
                            sourceParent,
                            targetParent,
                            sourceRootIndex,
                            targetRootIndex,
                            sourceMarkers,
                            targetMarkers,
                            out Matrix3d transform,
                            out double score);

                    if (!matched)
                        continue;

                    string pattern =
                        GetAiPipeParentPatternSignature(
                            sourceParent,
                            segmentsByParent[sourceParent]);

                    if (string.IsNullOrWhiteSpace(
                            pattern))
                    {
                        continue;
                    }

                    matches.Add(
                        new AiAutoTemplateBranchCandidate
                        {
                            SourceParent =
                                sourceParent,
                            TargetParent =
                                targetParent,
                            Transform =
                                transform,
                            Score =
                                score,
                            SourceMarkerCount =
                                sourceMarkers.Count,
                            TargetMarkerCount =
                                targetMarkers.Count,
                            PatternSignature =
                                pattern
                        });
                }

                if (matches.Count == 0)
                    continue;

                List<AiAutoTemplateBranchCandidate> ranked =
                    matches
                        .OrderBy(
                            m =>
                                m.Score)
                        .ThenByDescending(
                            m =>
                                Math.Min(
                                    m.SourceMarkerCount,
                                    m.TargetMarkerCount))
                        .ToList();

                AiAutoTemplateBranchCandidate best =
                    ranked[0];

                // Nếu nhánh mẫu thứ 2 gần như ngang điểm nhưng lại có pattern DN khác,
                // không đoán. Ví dụ hai loại nhánh cùng hình nhưng schedule khác nhau.
                if (ranked.Count > 1)
                {
                    AiAutoTemplateBranchCandidate second =
                        ranked[1];

                    double ambiguityTolerance =
                        Math.Max(
                            40.0,
                            GetTemplateCurveLength(
                                best.SourceParent) *
                            0.006);

                    if (!string.Equals(
                            best.PatternSignature,
                            second.PatternSignature,
                            StringComparison.OrdinalIgnoreCase) &&
                        Math.Abs(
                            second.Score -
                            best.Score) <=
                        ambiguityTolerance)
                    {
                        continue;
                    }
                }

                int inheritedForTarget =
                    ApplyAiPipePatternToMatchedTarget(
                        segments,
                        best.SourceParent,
                        best.TargetParent,
                        best.Transform,
                        segmentsByParent[
                            best.SourceParent],
                        best.Score,
                        best.SourceMarkerCount,
                        best.TargetMarkerCount);

                inheritedCount +=
                    inheritedForTarget;

                if (inheritedForTarget > 0)
                {
                    // Dictionary cũ không còn đúng sau khi target bị split.
                    // Không dùng target này thêm lần nữa trong vòng hiện tại.
                    continue;
                }
            }

            return inheritedCount;
        }

        private bool IsAiTemplateSourceParent(
            Curve parent,
            List<SegmentData> parentSegments)
        {
            if (parent == null ||
                parentSegments == null ||
                parentSegments.Count == 0)
            {
                return false;
            }

            double totalParentLength =
                GetAiPipeCurveLength(
                    parent);

            if (totalParentLength <= 100.0)
                return false;

            double knownLength =
                parentSegments
                    .Where(
                        s =>
                            s?.Curve != null &&
                            !string.IsNullOrWhiteSpace(
                                s.Layer))
                    .Sum(
                        s =>
                            GetAiPipeCurveLength(
                                s.Curve));

            int explicitSeedCount =
                parentSegments.Count(
                    s =>
                        s != null &&
                        s.HasExplicitSize &&
                        !string.IsNullOrWhiteSpace(
                            s.Layer));

            double coverage =
                knownLength /
                Math.Max(
                    totalParentLength,
                    1.0);

            // STEP18F:
            // - 1 seed: phải phủ rất cao (sau same-parent fill thường = 100%).
            // - >=2 seed trên nhánh nhiều DN: cho phép coverage thấp hơn,
            //   vì GetTextSizeTransitionDistances đã chia zone theo các text.
            if (explicitSeedCount >= 2)
            {
                return
                    coverage >=
                        0.55;
            }

            return
                explicitSeedCount >= 1 &&
                coverage >=
                    0.82;
        }

        private bool IsAiTemplateUnknownTargetParent(
            List<SegmentData> parentSegments)
        {
            if (parentSegments == null ||
                parentSegments.Count == 0)
            {
                return false;
            }

            // STEP18F:
            // Target = nhánh KHÔNG CÓ TEXT/LAYER SIZE TRỰC TIẾP.
            // Không dùng Layer blank làm điều kiện vì các bước suy luận khác
            // có thể đã tạm gán Layer dù user không hề ghi DN.
            return
                parentSegments.All(
                    s =>
                        s != null &&
                        !s.HasExplicitSize);
        }

        private List<Point3d> GetAiTemplateMarkersNearCurveStrict(
            Curve curve,
            List<AiPipeContextAnchor> anchors)
        {
            List<Point3d> result =
                new List<Point3d>();

            if (curve == null ||
                anchors == null ||
                anchors.Count == 0)
            {
                return result;
            }

            double curveLength =
                GetAiPipeCurveLength(
                    curve);

            double corridor =
                Math.Max(
                    180.0,
                    Math.Min(
                        520.0,
                        curveLength * 0.035));

            foreach (AiPipeContextAnchor anchor
                in anchors)
            {
                if (anchor == null)
                    continue;

                double allowed =
                    Math.Max(
                        corridor,
                        Math.Min(
                            520.0,
                            anchor.MaxSpan * 0.80 +
                            80.0));

                if (!TryGetClosestPointInPlan(
                        curve,
                        anchor.Point,
                        out Point3d ignored,
                        out double distance))
                {
                    continue;
                }

                if (distance >
                    allowed)
                {
                    continue;
                }

                AddUniquePoint(
                    result,
                    anchor.Point,
                    5.0);
            }

            return
                result;
        }

        private string GetAiPipeParentPatternSignature(
            Curve parent,
            List<SegmentData> parentSegments)
        {
            if (parent == null ||
                parentSegments == null)
            {
                return "";
            }

            List<SegmentData> ordered =
                parentSegments
                    .Where(
                        s =>
                            s?.Curve != null &&
                            !string.IsNullOrWhiteSpace(
                                s.Layer))
                    .OrderBy(
                        s =>
                            GetAiStationOnParent(
                                parent,
                                GetAiCurveMidPoint(
                                    s.Curve)))
                    .ToList();

            if (ordered.Count == 0)
                return "";

            List<string> pieces =
                new List<string>();

            foreach (SegmentData segment
                in ordered)
            {
                string size =
                    ExtractAiPipeSizeFromLayer(
                        segment.Layer);

                if (string.IsNullOrWhiteSpace(
                        size))
                {
                    size =
                        segment.LabelText ??
                        "";
                }

                double midStation =
                    GetAiStationOnParent(
                        parent,
                        GetAiCurveMidPoint(
                            segment.Curve));

                double parentLength =
                    Math.Max(
                        1.0,
                        GetAiPipeCurveLength(
                            parent));

                double fraction =
                    midStation /
                    parentLength;

                pieces.Add(
                    size +
                    "@" +
                    Math.Round(
                        fraction,
                        2)
                        .ToString(
                            "0.00",
                            CultureInfo.InvariantCulture));
            }

            return
                string.Join(
                    "|",
                    pieces);
        }

        private double GetAiStationOnParent(
            Curve parent,
            Point3d point)
        {
            if (parent == null)
                return 0.0;

            try
            {
                Point3d closest =
                    parent.GetClosestPointTo(
                        point,
                        false);

                return
                    parent.GetDistAtPoint(
                        closest);
            }
            catch
            {
                return 0.0;
            }
        }

        private int ApplyAiPipePatternToMatchedTarget(
            List<SegmentData> allSegments,
            Curve sourceParent,
            Curve targetParent,
            Matrix3d transform,
            List<SegmentData> sourceSegments,
            double matchScore,
            int sourceMarkerCount,
            int targetMarkerCount)
        {
            if (allSegments == null ||
                sourceParent == null ||
                targetParent == null ||
                sourceSegments == null)
            {
                return 0;
            }

            List<SegmentData> knownSourceSegments =
                sourceSegments
                    .Where(
                        s =>
                            s?.Curve != null &&
                            !string.IsNullOrWhiteSpace(
                                s.Layer))
                    .ToList();

            if (knownSourceSegments.Count == 0)
                return 0;

            double targetLength =
                GetAiPipeCurveLength(
                    targetParent);

            if (targetLength <= 100.0)
                return 0;

            List<double> splitDistances =
                new List<double>();

            // Copy boundary của PATTERN từ source sang target bằng transform
            // của engine mẫu cũ. Đây là chỗ STEP18D pairwise không làm được.
            foreach (SegmentData sourceSegment
                in knownSourceSegments)
            {
                Point3d[] endpoints =
                    new Point3d[]
                    {
                        sourceSegment.Curve.StartPoint,
                        sourceSegment.Curve.EndPoint
                    };

                foreach (Point3d sourcePoint
                    in endpoints)
                {
                    try
                    {
                        Point3d expectedTarget =
                            sourcePoint.TransformBy(
                                transform);

                        Point3d targetClosest =
                            targetParent.GetClosestPointTo(
                                expectedTarget,
                                false);

                        double planError =
                            PlanDistance(
                                expectedTarget,
                                targetClosest);

                        double boundaryTolerance =
                            Math.Max(
                                100.0,
                                targetLength *
                                0.01);

                        if (planError >
                            boundaryTolerance)
                        {
                            continue;
                        }

                        double d =
                            targetParent.GetDistAtPoint(
                                targetClosest);

                        if (d > 2.0 &&
                            d <
                                targetLength - 2.0 &&
                            !splitDistances.Any(
                                x =>
                                    Math.Abs(
                                        x - d) <
                                    2.0))
                        {
                            splitDistances.Add(
                                d);
                        }
                    }
                    catch
                    {
                    }
                }
            }

            splitDistances.Sort();

            List<Curve> targetPieces =
                new List<Curve>();

            if (splitDistances.Count > 0)
            {
                Point3dCollection points =
                    new Point3dCollection();

                foreach (double d
                    in splitDistances)
                {
                    try
                    {
                        points.Add(
                            targetParent.GetPointAtDist(
                                d));
                    }
                    catch
                    {
                    }
                }

                if (points.Count > 0)
                {
                    try
                    {
                        DBObjectCollection splitObjects =
                            targetParent.GetSplitCurves(
                                points);

                        foreach (DBObject obj
                            in splitObjects)
                        {
                            if (obj is Curve c)
                            {
                                targetPieces.Add(
                                    c);
                            }
                            else
                            {
                                obj.Dispose();
                            }
                        }
                    }
                    catch
                    {
                    }
                }
            }

            if (targetPieces.Count == 0)
            {
                Curve clone =
                    targetParent.Clone()
                        as Curve;

                if (clone != null)
                {
                    targetPieces.Add(
                        clone);
                }
            }

            if (targetPieces.Count == 0)
                return 0;

            // Source segment midpoint sau transform là "tọa độ kỳ vọng"
            // của từng zone DN trên target.
            List<Tuple<SegmentData, Point3d>> expectedSourceZones =
                knownSourceSegments
                    .Select(
                        s =>
                            Tuple.Create(
                                s,
                                GetAiCurveMidPoint(
                                    s.Curve)
                                    .TransformBy(
                                        transform)))
                    .ToList();

            List<SegmentData> newTargetSegments =
                new List<SegmentData>();

            foreach (Curve targetPiece
                in targetPieces)
            {
                Point3d targetMid =
                    GetAiCurveMidPoint(
                        targetPiece);

                var bestSourceZone =
                    expectedSourceZones
                        .OrderBy(
                            z =>
                                PlanDistance(
                                    z.Item2,
                                    targetMid))
                        .FirstOrDefault();

                if (bestSourceZone == null ||
                    bestSourceZone.Item1 == null)
                {
                    targetPiece.Dispose();
                    continue;
                }

                SegmentData sourceZone =
                    bestSourceZone.Item1;

                double confidence =
                    0.93;

                // 3+ marker giống nhau => đây gần như đúng use-case của
                // chức năng VẼ THEO MẪU, nâng confidence.
                int commonMarkers =
                    Math.Min(
                        sourceMarkerCount,
                        targetMarkerCount);

                if (commonMarkers >= 4)
                {
                    confidence =
                        0.98;
                }
                else if (commonMarkers >= 3)
                {
                    confidence =
                        0.97;
                }
                else if (commonMarkers >= 2)
                {
                    confidence =
                        0.95;
                }

                double scorePenalty =
                    Math.Min(
                        0.03,
                        matchScore /
                        Math.Max(
                            5000.0,
                            GetTemplateCurveLength(
                                sourceParent)) *
                        0.02);

                confidence =
                    Math.Max(
                        0.90,
                        confidence -
                        scorePenalty);

                newTargetSegments.Add(
                    new SegmentData
                    {
                        Curve =
                            targetPiece,
                        OriginalParent =
                            targetParent,
                        Layer =
                            sourceZone.Layer,
                        LabelText =
                            sourceZone.LabelText,
                        Width =
                            FixedDnPipeDisplayWidth,
                        HasExplicitSize =
                            false,
                        AiInferenceSource =
                            "AUTO_TEMPLATE_BRANCH",
                        AiInferenceConfidence =
                            confidence
                    });
            }

            if (newTargetSegments.Count == 0)
                return 0;

            // Chỉ replace target cũ khi toàn bộ pieces đã được map DN.
            List<SegmentData> oldTargetSegments =
                allSegments
                    .Where(
                        s =>
                            s != null &&
                            ReferenceEquals(
                                s.OriginalParent,
                                targetParent))
                    .ToList();

            foreach (SegmentData oldSegment
                in oldTargetSegments)
            {
                allSegments.Remove(
                    oldSegment);

                try
                {
                    oldSegment.Curve?.Dispose();
                }
                catch
                {
                }
            }

            allSegments.AddRange(
                newTargetSegments);

            return
                newTargetSegments.Count;
        }

        private int PropagateAiPipeSizesByRepeatedBranchTemplate(
            List<SegmentData> segments,
            List<AiPipeContextAnchor> anchors)
        {
            if (segments == null ||
                segments.Count == 0)
            {
                return 0;
            }

            List<SegmentData> sourceSegments =
                segments
                    .Where(
                        s =>
                            s?.Curve != null &&
                            !string.IsNullOrWhiteSpace(
                                s.Layer))
                    .ToList();

            List<SegmentData> targetSegments =
                segments
                    .Where(
                        s =>
                            s?.Curve != null &&
                            string.IsNullOrWhiteSpace(
                                s.Layer))
                    .ToList();

            if (sourceSegments.Count == 0 ||
                targetSegments.Count == 0)
            {
                return 0;
            }

            List<AiRepeatedBranchProposal> proposals =
                new List<AiRepeatedBranchProposal>();

            foreach (SegmentData source
                in sourceSegments)
            {
                double sourceLength =
                    GetAiPipeCurveLength(
                        source.Curve);

                if (sourceLength <= 50.0)
                    continue;

                Point3d sourceMid =
                    GetAiCurveMidPoint(
                        source.Curve);

                double sourceAngle =
                    GetAiCurveAxisAngle(
                        source.Curve);

                foreach (SegmentData target
                    in targetSegments)
                {
                    double targetLength =
                        GetAiPipeCurveLength(
                            target.Curve);

                    if (targetLength <= 50.0)
                        continue;

                    double lengthTolerance =
                        Math.Max(
                            80.0,
                            Math.Max(
                                sourceLength,
                                targetLength) *
                            0.025);

                    double lengthDiff =
                        Math.Abs(
                            sourceLength -
                            targetLength);

                    if (lengthDiff >
                        lengthTolerance)
                    {
                        continue;
                    }

                    double targetAngle =
                        GetAiCurveAxisAngle(
                            target.Curve);

                    double angleDiff =
                        GetAiParallelAngleDifference(
                            sourceAngle,
                            targetAngle);

                    if (angleDiff >
                        3.0 * Math.PI / 180.0)
                    {
                        continue;
                    }

                    Point3d targetMid =
                        GetAiCurveMidPoint(
                            target.Curve);

                    double dx =
                        targetMid.X -
                        sourceMid.X;

                    double dy =
                        targetMid.Y -
                        sourceMid.Y;

                    if (Math.Sqrt(
                            dx * dx +
                            dy * dy) <
                        200.0)
                    {
                        continue;
                    }

                    int anchorMatches =
                        CountAiTranslatedAnchorMatches(
                            source.Curve,
                            target.Curve,
                            dx,
                            dy,
                            anchors);

                    double lengthScore =
                        1.0 -
                        Math.Min(
                            1.0,
                            lengthDiff /
                            Math.Max(
                                lengthTolerance,
                                1.0));

                    double angleScore =
                        1.0 -
                        Math.Min(
                            1.0,
                            angleDiff /
                            (3.0 *
                             Math.PI /
                             180.0));

                    double sameLayerBonus =
                        0.0;

                    try
                    {
                        string sourceOriginalLayer =
                            source.OriginalParent?.Layer ??
                            "";

                        string targetOriginalLayer =
                            target.OriginalParent?.Layer ??
                            "";

                        if (!string.IsNullOrWhiteSpace(
                                sourceOriginalLayer) &&
                            string.Equals(
                                sourceOriginalLayer,
                                targetOriginalLayer,
                                StringComparison.OrdinalIgnoreCase))
                        {
                            sameLayerBonus =
                                0.08;
                        }
                    }
                    catch
                    {
                    }

                    double pairScore =
                        0.53 * lengthScore +
                        0.27 * angleScore +
                        sameLayerBonus +
                        Math.Min(
                            0.22,
                            anchorMatches * 0.075);

                    proposals.Add(
                        new AiRepeatedBranchProposal
                        {
                            Source =
                                source,
                            Target =
                                target,
                            Dx =
                                dx,
                            Dy =
                                dy,
                            PairScore =
                                pairScore,
                            AnchorMatches =
                                anchorMatches,
                            TranslationKey =
                                GetAiTranslationKey(
                                    dx,
                                    dy,
                                    40.0)
                        });
                }
            }

            if (proposals.Count == 0)
                return 0;

            Dictionary<SegmentData, List<AiRepeatedBranchProposal>> votesByTarget =
                new Dictionary<
                    SegmentData,
                    List<AiRepeatedBranchProposal>>();

            foreach (IGrouping<string, AiRepeatedBranchProposal> group
                in proposals.GroupBy(
                    p =>
                        p.TranslationKey,
                    StringComparer.OrdinalIgnoreCase))
            {
                List<AiRepeatedBranchProposal> list =
                    group.ToList();

                int uniqueSourceCount =
                    list
                        .Select(
                            p =>
                                p.Source)
                        .Distinct()
                        .Count();

                int uniqueTargetCount =
                    list
                        .Select(
                            p =>
                                p.Target)
                        .Distinct()
                        .Count();

                int bestAnchorMatches =
                    list.Max(
                        p =>
                            p.AnchorMatches);

                int totalAnchorMatches =
                    list.Sum(
                        p =>
                            p.AnchorMatches);

                double averagePairScore =
                    list.Average(
                        p =>
                            p.PairScore);

                bool geometryStrong =
                    uniqueSourceCount >= 2 &&
                    uniqueTargetCount >= 2 &&
                    averagePairScore >= 0.72;

                bool landmarkStrong =
                    bestAnchorMatches >= 2 &&
                    averagePairScore >= 0.72;

                bool mixedStrong =
                    uniqueTargetCount >= 2 &&
                    totalAnchorMatches >= 1 &&
                    averagePairScore >= 0.70;

                if (!geometryStrong &&
                    !landmarkStrong &&
                    !mixedStrong)
                {
                    continue;
                }

                foreach (AiRepeatedBranchProposal proposal
                    in list)
                {
                    if (proposal?.Target == null ||
                        proposal.Source == null ||
                        string.IsNullOrWhiteSpace(
                            proposal.Source.Layer))
                    {
                        continue;
                    }

                    if (!votesByTarget.TryGetValue(
                            proposal.Target,
                            out List<AiRepeatedBranchProposal> targetVotes))
                    {
                        targetVotes =
                            new List<AiRepeatedBranchProposal>();

                        votesByTarget[
                            proposal.Target] =
                            targetVotes;
                    }

                    targetVotes.Add(
                        proposal);
                }
            }

            int inherited =
                0;

            foreach (
                KeyValuePair<
                    SegmentData,
                    List<AiRepeatedBranchProposal>>
                    pair
                in votesByTarget)
            {
                SegmentData target =
                    pair.Key;

                if (target == null ||
                    !string.IsNullOrWhiteSpace(
                        target.Layer))
                {
                    continue;
                }

                var ranked =
                    pair.Value
                        .Where(
                            p =>
                                p?.Source != null &&
                                !string.IsNullOrWhiteSpace(
                                    p.Source.Layer))
                        .GroupBy(
                            p =>
                                p.Source.Layer,
                            StringComparer.OrdinalIgnoreCase)
                        .Select(
                            g =>
                                new
                                {
                                    Layer =
                                        g.Key,
                                    Count =
                                        g.Count(),
                                    Best =
                                        g.Max(
                                            p =>
                                                p.PairScore +
                                                p.AnchorMatches * 0.04),
                                    Anchor =
                                        g.Max(
                                            p =>
                                                p.AnchorMatches),
                                    Source =
                                        g.OrderByDescending(
                                            p =>
                                                p.PairScore +
                                                p.AnchorMatches * 0.04)
                                         .First()
                                         .Source
                                })
                        .OrderByDescending(
                            x =>
                                x.Count)
                        .ThenByDescending(
                            x =>
                                x.Anchor)
                        .ThenByDescending(
                            x =>
                                x.Best)
                        .ToList();

                if (ranked.Count == 0)
                    continue;

                var best =
                    ranked[0];

                if (ranked.Count > 1)
                {
                    var second =
                        ranked[1];

                    if (best.Count ==
                            second.Count &&
                        Math.Abs(
                            best.Best -
                            second.Best) <
                        0.10)
                    {
                        continue;
                    }
                }

                target.Layer =
                    best.Layer;

                target.Width =
                    FixedDnPipeDisplayWidth;

                target.LabelText =
                    best.Source?.LabelText ??
                    ExtractAiPipeSizeFromLayer(
                        best.Layer);

                target.AiInferenceSource =
                    "REPEATED_BRANCH_TEMPLATE";

                target.AiInferenceConfidence =
                    Math.Min(
                        0.95,
                        0.88 +
                        Math.Min(
                            0.07,
                            best.Count * 0.02 +
                            best.Anchor * 0.015));

                inherited++;
            }

            return inherited;
        }

        private string GetAiTranslationKey(
            double dx,
            double dy,
            double quantum)
        {
            if (quantum <= 1.0)
                quantum = 40.0;

            long qx =
                (long)Math.Round(
                    dx /
                    quantum);

            long qy =
                (long)Math.Round(
                    dy /
                    quantum);

            return
                qx.ToString(
                    CultureInfo.InvariantCulture) +
                "|" +
                qy.ToString(
                    CultureInfo.InvariantCulture);
        }

        private Point3d GetAiCurveMidPoint(
            Curve curve)
        {
            if (curve == null)
                return Point3d.Origin;

            try
            {
                double length =
                    GetAiPipeCurveLength(
                        curve);

                if (length > 1.0)
                {
                    Point3d p =
                        curve.GetPointAtDist(
                            length * 0.5);

                    return
                        new Point3d(
                            p.X,
                            p.Y,
                            0.0);
                }
            }
            catch
            {
            }

            try
            {
                return
                    new Point3d(
                        (curve.StartPoint.X +
                         curve.EndPoint.X) * 0.5,
                        (curve.StartPoint.Y +
                         curve.EndPoint.Y) * 0.5,
                        0.0);
            }
            catch
            {
                return Point3d.Origin;
            }
        }

        private double GetAiCurveAxisAngle(
            Curve curve)
        {
            if (curve == null)
                return 0.0;

            try
            {
                Point3d a =
                    curve.StartPoint;

                Point3d b =
                    curve.EndPoint;

                Vector3d v =
                    new Vector3d(
                        b.X - a.X,
                        b.Y - a.Y,
                        0.0);

                if (v.Length >
                    1e-6)
                {
                    double angle =
                        Math.Atan2(
                            v.Y,
                            v.X);

                    while (angle <
                        0.0)
                    {
                        angle +=
                            Math.PI;
                    }

                    while (angle >=
                        Math.PI)
                    {
                        angle -=
                            Math.PI;
                    }

                    return angle;
                }
            }
            catch
            {
            }

            return 0.0;
        }

        private double GetAiParallelAngleDifference(
            double a,
            double b)
        {
            double diff =
                Math.Abs(
                    a -
                    b);

            diff =
                diff %
                Math.PI;

            if (diff >
                Math.PI / 2.0)
            {
                diff =
                    Math.PI -
                    diff;
            }

            return
                Math.Abs(
                    diff);
        }

        private int CountAiTranslatedAnchorMatches(
            Curve source,
            Curve target,
            double dx,
            double dy,
            List<AiPipeContextAnchor> anchors)
        {
            if (source == null ||
                target == null ||
                anchors == null ||
                anchors.Count == 0)
            {
                return 0;
            }

            double sourceLength =
                GetAiPipeCurveLength(
                    source);

            double targetLength =
                GetAiPipeCurveLength(
                    target);

            double corridor =
                Math.Max(
                    280.0,
                    Math.Min(
                        700.0,
                        Math.Max(
                            sourceLength,
                            targetLength) *
                        0.05));

            List<AiPipeContextAnchor> sourceAnchors =
                anchors
                    .Where(
                        a =>
                            a != null &&
                            GetSmartDistancePointToCurve(
                                source,
                                a.Point) <=
                            Math.Max(
                                corridor,
                                a.MaxSpan * 0.75 +
                                100.0))
                    .ToList();

            List<AiPipeContextAnchor> targetAnchors =
                anchors
                    .Where(
                        a =>
                            a != null &&
                            GetSmartDistancePointToCurve(
                                target,
                                a.Point) <=
                            Math.Max(
                                corridor,
                                a.MaxSpan * 0.75 +
                                100.0))
                    .ToList();

            if (sourceAnchors.Count == 0 ||
                targetAnchors.Count == 0)
            {
                return 0;
            }

            int matches =
                0;

            HashSet<AiPipeContextAnchor> usedTargets =
                new HashSet<AiPipeContextAnchor>();

            foreach (AiPipeContextAnchor sourceAnchor
                in sourceAnchors)
            {
                Point3d translated =
                    new Point3d(
                        sourceAnchor.Point.X +
                        dx,
                        sourceAnchor.Point.Y +
                        dy,
                        0.0);

                AiPipeContextAnchor best =
                    targetAnchors
                        .Where(
                            t =>
                                !usedTargets.Contains(
                                    t) &&
                                (string.IsNullOrWhiteSpace(
                                     sourceAnchor.BlockKey) ||
                                 string.IsNullOrWhiteSpace(
                                     t.BlockKey) ||
                                 string.Equals(
                                     sourceAnchor.BlockKey,
                                     t.BlockKey,
                                     StringComparison.OrdinalIgnoreCase)))
                        .OrderBy(
                            t =>
                                PlanDistance(
                                    translated,
                                    t.Point))
                        .FirstOrDefault();

                if (best == null)
                    continue;

                double tolerance =
                    Math.Max(
                        150.0,
                        Math.Min(
                            350.0,
                            Math.Max(
                                sourceAnchor.MaxSpan,
                                best.MaxSpan) *
                            0.65 +
                            80.0));

                if (PlanDistance(
                        translated,
                        best.Point) <=
                    tolerance)
                {
                    matches++;
                    usedTargets.Add(
                        best);
                }
            }

            return matches;
        }

        private List<AiPipeSegmentResult> BuildAiPipeResults(
            List<SegmentData> segments,
            HashSet<SegmentData> explicitText,
            HashSet<SegmentData> explicitLayer)
        {
            List<AiPipeSegmentResult> result =
                new List<AiPipeSegmentResult>();

            if (segments == null)
                return result;

            Dictionary<Curve, HashSet<string>> explicitByParent =
                segments
                    .Where(
                        s =>
                            s != null &&
                            s.HasExplicitSize &&
                            s.OriginalParent != null &&
                            !string.IsNullOrWhiteSpace(s.Layer))
                    .GroupBy(s => s.OriginalParent)
                    .ToDictionary(
                        g => g.Key,
                        g => new HashSet<string>(
                            g.Select(s => s.Layer),
                            StringComparer.OrdinalIgnoreCase));

            foreach (SegmentData segment
                in segments)
            {
                if (segment?.Curve == null ||
                    string.IsNullOrWhiteSpace(segment.Layer))
                {
                    continue;
                }

                string size =
                    ExtractAiPipeSizeFromLayer(
                        segment.Layer);

                if (string.IsNullOrWhiteSpace(size))
                    continue;

                double confidence;
                string evidence;

                if (explicitText != null &&
                    explicitText.Contains(segment))
                {
                    confidence = 0.99;
                    evidence = "TEXT song song";
                }
                else if (explicitLayer != null &&
                         explicitLayer.Contains(segment))
                {
                    confidence = 0.95;
                    evidence = "Layer gốc";
                }
                else if (string.Equals(
                             segment.AiInferenceSource,
                             "BRANCH_OBJECT_TEMPLATE",
                             StringComparison.OrdinalIgnoreCase))
                {
                    confidence =
                        segment.AiInferenceConfidence > 0.0
                            ? segment.AiInferenceConfidence
                            : 0.97;

                    evidence =
                        "Branch Object / mẫu có sẵn";
                }
                else if (string.Equals(
                             segment.AiInferenceSource,
                             "AUTO_TEMPLATE_BRANCH",
                             StringComparison.OrdinalIgnoreCase))
                {
                    confidence =
                        segment.AiInferenceConfidence > 0.0
                            ? segment.AiInferenceConfidence
                            : 0.96;

                    evidence =
                        "Auto Template / engine mẫu cũ";
                }
                else if (string.Equals(
                             segment.AiInferenceSource,
                             "REPEATED_BRANCH_TEMPLATE",
                             StringComparison.OrdinalIgnoreCase))
                {
                    confidence =
                        segment.AiInferenceConfidence > 0.0
                            ? segment.AiInferenceConfidence
                            : 0.93;

                    evidence =
                        "Nhánh giống nhau / Template fallback";
                }
                else
                {
                    bool sameParent =
                        segment.OriginalParent != null &&
                        explicitByParent.TryGetValue(
                            segment.OriginalParent,
                            out HashSet<string> parentSizes) &&
                        parentSizes.Count == 1;

                    if (sameParent)
                    {
                        confidence =
                            segment.AiInferenceConfidence > 0.0
                                ? segment.AiInferenceConfidence
                                : 0.94;

                        evidence =
                            "Cùng LINE/POLYLINE";
                    }
                    else
                    {
                        confidence =
                            segment.AiInferenceConfidence > 0.0
                                ? segment.AiInferenceConfidence
                                : 0.84;

                        evidence =
                            "Topology thẳng hàng";
                    }
                }

                double length =
                    GetAiPipeCurveLength(
                        segment.Curve);

                if (length <= 1.0)
                    continue;

                result.Add(
                    new AiPipeSegmentResult
                    {
                        Segment = segment,
                        Size = size,
                        Length = length,
                        Confidence = confidence,
                        Evidence = evidence
                    });
            }

            return result;
        }

        private List<SegmentData> FindAiPipeCheckSegments(
            List<SegmentData> segments)
        {
            List<SegmentData> result =
                new List<SegmentData>();

            if (segments == null ||
                segments.Count == 0)
            {
                return result;
            }

            List<AutomaticPipeNetworkNode> nodes =
                BuildAutomaticPipeNetworkNodes(
                    segments);

            HashSet<SegmentData> added =
                new HashSet<SegmentData>();

            foreach (AutomaticPipeNetworkNode node
                in nodes)
            {
                bool hasKnown =
                    node.Ends.Any(
                        e =>
                            e?.Segment != null &&
                            !string.IsNullOrWhiteSpace(
                                e.Segment.Layer));

                if (!hasKnown)
                    continue;

                foreach (SegmentData unknown
                    in node.Ends
                        .Select(e => e.Segment)
                        .Where(
                            s =>
                                s != null &&
                                string.IsNullOrWhiteSpace(s.Layer))
                        .Distinct())
                {
                    if (added.Contains(unknown) ||
                        unknown.Curve == null ||
                        GetAiPipeCurveLength(
                            unknown.Curve) <= 5.0)
                    {
                        continue;
                    }

                    added.Add(unknown);
                    result.Add(unknown);
                }
            }

            return result;
        }

        private bool TryParseAiPipeSizeText(
            string raw,
            out string size)
        {
            size = "";

            if (string.IsNullOrWhiteSpace(raw))
                return false;

            string normalized =
                NormalizeSmartDisplayName(raw)
                    .ToUpperInvariant()
                    .Replace("Ø", "D")
                    .Replace("Φ", "D")
                    .Replace(" ", "");

            if (normalized.Contains("FFL") ||
                normalized.Contains("LEVEL") ||
                normalized.Contains("EL+"))
            {
                return false;
            }

            Match dn =
                Regex.Match(
                    normalized,
                    @"DN(?<N>\d{1,4}(?:[.,]\d+)?)",
                    RegexOptions.IgnoreCase);

            if (dn.Success &&
                double.TryParse(
                    dn.Groups["N"].Value.Replace(',', '.'),
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out double dnValue) &&
                dnValue >= 10.0 &&
                dnValue <= 1200.0)
            {
                size =
                    "DN" +
                    FormatSizeNumber(dnValue);

                return true;
            }

            Match outside =
                Regex.Match(
                    normalized,
                    @"(?:^|[^A-Z0-9])D(?<N>\d{1,4}(?:[.,]\d+)?)(?:$|[^0-9])",
                    RegexOptions.IgnoreCase);

            if (outside.Success &&
                double.TryParse(
                    outside.Groups["N"].Value.Replace(',', '.'),
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out double outsideValue) &&
                outsideValue >= 10.0 &&
                outsideValue <= 1300.0 &&
                TryConvertOutsideDiameterToNominal(
                    outsideValue,
                    out double nominal))
            {
                size =
                    "DN" +
                    FormatSizeNumber(nominal);

                return true;
            }

            return false;
        }

        private static string NormalizeAiPipeSize(
            string raw)
        {
            if (string.IsNullOrWhiteSpace(raw))
                return "";

            Match m =
                Regex.Match(
                    raw,
                    @"DN\s*(?<N>\d{1,4}(?:[.,]\d+)?)",
                    RegexOptions.IgnoreCase);

            return m.Success
                ? "DN" +
                  m.Groups["N"].Value.Replace(',', '.')
                : raw.Trim().ToUpperInvariant();
        }

        private static string GetAiPipeLayerName(
            string size)
        {
            return
                AiPipeLayerPrefix +
                NormalizeAiPipeSize(size)
                    .Replace(" ", "")
                    .Replace(".", "_");
        }

        private static string ExtractAiPipeSizeFromLayer(
            string layer)
        {
            if (string.IsNullOrWhiteSpace(layer) ||
                !layer.StartsWith(
                    AiPipeLayerPrefix,
                    StringComparison.OrdinalIgnoreCase))
            {
                return "";
            }

            string suffix =
                layer.Substring(
                    AiPipeLayerPrefix.Length)
                    .Replace("_", ".");

            Match m =
                Regex.Match(
                    suffix,
                    @"DN\d{1,4}(?:\.\d+)?",
                    RegexOptions.IgnoreCase);

            return m.Success
                ? m.Value.ToUpperInvariant()
                : "";
        }

        private static bool IsAiPipeOutputLayer(
            string layer)
        {
            if (string.IsNullOrWhiteSpace(layer))
                return false;

            return
                layer.StartsWith(
                    AiPipeLayerPrefix,
                    StringComparison.OrdinalIgnoreCase) ||
                layer.Equals(
                    AiPipeCheckLayer,
                    StringComparison.OrdinalIgnoreCase) ||
                layer.Equals(
                    AiPipeInfoLayer,
                    StringComparison.OrdinalIgnoreCase);
        }

        private void DeleteOldAiPipeOutput(
            Transaction tr,
            BlockTableRecord space)
        {
            if (tr == null ||
                space == null)
            {
                return;
            }

            List<ObjectId> ids =
                new List<ObjectId>();

            foreach (ObjectId id in space)
            {
                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForRead,
                        false) as Entity;

                if (ent != null &&
                    !ent.IsErased &&
                    IsAiPipeOutputLayer(ent.Layer))
                {
                    ids.Add(id);
                }
            }

            foreach (ObjectId id in ids)
            {
                Entity ent =
                    tr.GetObject(
                        id,
                        OpenMode.ForWrite,
                        false) as Entity;

                if (ent != null &&
                    !ent.IsErased)
                {
                    ent.Erase();
                }
            }
        }

        private void EnsureAiPipeLayer(
            Transaction tr,
            Database db,
            string layerName,
            short aci)
        {
            LayerTable lt =
                (LayerTable)tr.GetObject(
                    db.LayerTableId,
                    OpenMode.ForRead);

            LayerTableRecord ltr = null;

            if (!lt.Has(layerName))
            {
                lt.UpgradeOpen();

                ltr =
                    new LayerTableRecord
                    {
                        Name = layerName
                    };

                lt.Add(ltr);
                tr.AddNewlyCreatedDBObject(ltr, true);
            }
            else
            {
                ltr =
                    tr.GetObject(
                        lt[layerName],
                        OpenMode.ForWrite,
                        false) as LayerTableRecord;
            }

            if (ltr != null)
            {
                ltr.Color =
                    Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                        ColorMethod.ByAci,
                        aci);
            }
        }

        private Entity CreateAiPipeOverlay(
            Curve source,
            string layerName,
            double width)
        {
            if (source == null)
                return null;

            try
            {
                Entity clone =
                    source.Clone() as Entity;

                if (clone == null)
                    return null;

                clone.Layer = layerName;
                clone.Color =
                    Autodesk.AutoCAD.Colors.Color.FromColorIndex(
                        ColorMethod.ByLayer,
                        256);

                clone.LineWeight =
                    Autodesk.AutoCAD.DatabaseServices.LineWeight.ByLayer;

                if (clone is Polyline pl)
                {
                    pl.ConstantWidth = width;
                }

                return clone;
            }
            catch
            {
                return null;
            }
        }

        private DBText CreateAiPipeLabel(
            Database db,
            Curve curve,
            string size,
            string layerName)
        {
            try
            {
                double length =
                    GetAiPipeCurveLength(curve);

                if (length <= 1.0)
                    return null;

                Point3d middle =
                    curve.GetPointAtDist(
                        length * 0.5);

                double parameter =
                    curve.GetParameterAtPoint(
                        curve.GetClosestPointTo(
                            middle,
                            false));

                Vector3d direction =
                    curve.GetFirstDerivative(
                        parameter);

                direction =
                    new Vector3d(
                        direction.X,
                        direction.Y,
                        0.0);

                if (direction.Length <= 1e-6)
                    return null;

                direction = direction.GetNormal();

                double rotation =
                    direction.AngleOnPlane(
                        new Plane());

                if (rotation > Math.PI / 2.0 &&
                    rotation <= 3.0 * Math.PI / 2.0)
                {
                    rotation -= Math.PI;
                    direction = direction.Negate();
                }

                Vector3d normal =
                    direction.RotateBy(
                        Math.PI / 2.0,
                        Vector3d.ZAxis);

                DBText text =
                    new DBText();

                text.SetDatabaseDefaults(db);
                text.TextStyleId = db.Textstyle;
                text.TextString = size;
                text.Height = 95.0;
                text.Layer = layerName;
                text.ColorIndex = 256;
                text.Justify =
                    AttachmentPoint.BottomCenter;
                text.AlignmentPoint =
                    middle + normal * 90.0;
                text.Rotation = rotation;

                return text;
            }
            catch
            {
                return null;
            }
        }

        private double GetAiPipeCurveLength(
            Curve curve)
        {
            if (curve == null)
                return 0.0;

            try
            {
                return
                    curve.GetDistanceAtParameter(
                        curve.EndParam);
            }
            catch
            {
                try
                {
                    return
                        curve.StartPoint.DistanceTo(
                            curve.EndPoint);
                }
                catch
                {
                    return 0.0;
                }
            }
        }

